// Hyperrealistic Coloured Pencil on Toned Blue-Grey Paper:
// Top-down view of Curly Lacinato and Red Kale at Dawn after the First Frost

const PALETTE = {
  paperBase: "#2b3540",
  paperDark: "#1c242d",
  paperLight: "#394654",

  soilDeep: "#090a0f",
  soilDark: "#12131a",
  soilMid: "#1e2029",
  soilWarm: "#29252e",
  soilRime: "#8ea6b8",

  shadowAbyss: "#04060a",
  shadowSlate: "#070c12",
  shadowPlum: "#0b0610",

  lacinatoDeep: "#0b191c",
  lacinatoDark: "#13292d",
  lacinatoMid: "#1e3e42",
  lacinatoSlate: "#2d5559",
  lacinatoHigh: "#447175",
  lacinatoBurnish: "#679296",
  lacinatoRibDark: "#244246",
  lacinatoRibMid: "#4d7378",
  lacinatoRibLight: "#82a8ad",

  plumAbyss: "#110817",
  plumDeep: "#1d0e26",
  plumDark: "#2e173b",
  plumMid: "#462457",
  plumBright: "#633575",
  plumHigh: "#824f94",
  plumBurnish: "#a37bb3",
  plumVeinDark: "#4a163f",
  plumVeinMid: "#782864",
  plumVeinLight: "#a6498c",
  plumVeinGlow: "#cc78b2",

  rimeBlue: "#7c9cb0",
  rimePale: "#aac6d6",
  frostCyan: "#d2eaf5",
  frostWhite: "#f0f9fd",
  pureWhite: "#ffffff"
};

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);

  randomSeed(849201);
  noiseSeed(849201);

  // Custom needle-sharp coloured pencil for brittle frost crystals
  brush.add("ice_needle", {
    type: "default",
    weight: 0.32,
    scatter: 0.04,
    sharpness: 0.96,
    grain: 4,
    opacity: 245,
    spacing: 0.12,
    pressure: [1.1, 0.7, 0.05],
    noise: 0.15
  });

  // Custom waxy burnishing coloured pencil for dense pigment layers
  brush.add("burnish", {
    type: "default",
    weight: 1.35,
    scatter: 0.18,
    sharpness: 0.45,
    grain: 14,
    opacity: 155,
    spacing: 0.18,
    pressure: [0.4, 1.2, 0.4],
    noise: 0.35
  });

  // Fine sharpening pencil for detail lines and vein edges
  brush.add("verithin", {
    type: "default",
    weight: 0.48,
    scatter: 0.08,
    sharpness: 0.88,
    grain: 9,
    opacity: 210,
    spacing: 0.15,
    pressure: [0.3, 1.0, 0.2],
    noise: 0.25
  });
}

function draw() {
  translate(-width / 2, -height / 2);

  // 1. Toned Blue-Grey Paper Ground & Cold Dawn Atmosphere
  drawTonedPaperGround();

  // 2. Surrounding Frozen Soil Bed & Rime-Dusted Clods
  drawFrozenSoilBed();

  // 3. Build Interlocking Botanical Schedule (Back-to-Front Tiers)
  renderKaleGardenBed();

  // 4. Final Brittle Ice Glints, Bridged Frost Filaments & Cold Rime Dust
  drawFinalFrostGlints();

  noLoop();
}

// =============================================================================
// SAFE P5.BRUSH HELPERS
// =============================================================================

function setPen(name, col, weight = 1) {
  brush.set(name, col, weight);
}

function safeLine(name, col, weight, x1, y1, x2, y2) {
  if (dist(x1, y1, x2, y2) < 0.5) return;
  brush.set(name, col, weight);
  brush.line(x1, y1, x2, y2);
}

function safeSpline(name, col, weight, pts, curv = 0.5) {
  if (!pts || pts.length < 3) return;
  let clean = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    let prev = clean[clean.length - 1];
    if (dist(prev[0], prev[1], pts[i][0], pts[i][1]) > 1.5) {
      clean.push(pts[i]);
    }
  }
  if (clean.length < 3) {
    if (clean.length === 2) {
      safeLine(name, col, weight, clean[0][0], clean[0][1], clean[1][0], clean[1][1]);
    }
    return;
  }
  brush.set(name, col, weight);
  brush.spline(clean, curv);
}

function drawWashShape(pts, col, opacity = 220, curv = 0.35) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.wash(col, opacity);
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noWash();
}

function drawHatchShape(pts, brushName, col, weight, distVal, angleVal, opts, curv = 0.35) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.hatchStyle(brushName, col, weight);
  brush.hatch(distVal, angleVal, opts);
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noHatch();
}

// =============================================================================
// 1. TONED BLUE-GREY PAPER GROUND
// =============================================================================

function drawTonedPaperGround() {
  background(PALETTE.paperBase);

  // Subtle cold dawn paper tone modulation
  brush.noStroke();
  brush.fillBleed(0.25, "out");
  brush.fillTexture(0.65, 0.3);

  const paperZones = [
    { x: 200, y: 200, r: 380, col: PALETTE.paperDark, a: 85 },
    { x: 1020, y: 240, r: 420, col: PALETTE.paperDark, a: 95 },
    { x: 180, y: 980, r: 400, col: PALETTE.paperDark, a: 90 },
    { x: 1040, y: 1020, r: 360, col: PALETTE.paperDark, a: 85 },
    { x: 600, y: 580, r: 520, col: PALETTE.paperLight, a: 45 }
  ];

  for (let z of paperZones) {
    brush.fill(z.col, z.a);
    brush.circle(z.x, z.y, z.r, 0.35);
  }
  brush.noFill();

  // Fine cotton-rag paper tooth across the entire sheet
  brush.noStroke();
  brush.hatchStyle("cpencil", "#232c36", 0.55);
  brush.hatch(9, 32, { rand: 0.12 });
  brush.rect(0, 0, width, height, "corner");
  brush.noHatch();

  brush.hatchStyle("cpencil", "#354250", 0.45);
  brush.hatch(11, -58, { rand: 0.14 });
  brush.rect(0, 0, width, height, "corner");
  brush.noHatch();
}

// =============================================================================
// 2. FROZEN GARDEN SOIL BED & RIME
// =============================================================================

function drawFrozenSoilBed() {
  // Deep earth recessions in the spaces around the rosettes
  const soilPockets = [
    { x: 960, y: 260, rx: 320, ry: 270, rot: -20 },
    { x: 210, y: 830, rx: 280, ry: 310, rot: 15 },
    { x: 650, y: 110, rx: 290, ry: 170, rot: 8 },
    { x: 560, y: 1090, rx: 310, ry: 170, rot: -10 },
    { x: 110, y: 150, rx: 220, ry: 200, rot: 35 },
    { x: 1090, y: 1080, rx: 230, ry: 210, rot: -30 },
    { x: 600, y: 600, rx: 340, ry: 340, rot: 45 }
  ];

  for (let p of soilPockets) {
    let pts = [];
    for (let a = 0; a < 360; a += 24) {
      let n = noise(p.x * 0.01 + cos(a), p.y * 0.01 + sin(a));
      let radX = p.rx * (0.7 + 0.45 * n);
      let radY = p.ry * (0.7 + 0.45 * n);
      let px = p.x + cos(a + p.rot) * radX;
      let py = p.y + sin(a + p.rot) * radY;
      pts.push([px, py]);
    }
    drawWashShape(pts, PALETTE.soilDark, 175, 0.45);
    drawHatchShape(pts, "charcoal", PALETTE.soilDeep, 0.85, 7, p.rot + 20, { rand: 0.25 }, 0.45);
  }

  // Render frozen soil clods, organic humus crumbs, and rime-dusted stones
  const numClods = 290;
  for (let i = 0; i < numClods; i++) {
    let cx = random(-20, width + 20);
    let cy = random(-20, height + 20);

    // Favor soil zones (away from the tightest rosette centers, though some under-layer is fine)
    let d1 = dist(cx, cy, 420, 430);
    let d2 = dist(cx, cy, 820, 770);
    if (d1 < 190 || d2 < 190) continue;

    let clodR = random(5, 28) * (random() < 0.2 ? 1.5 : 1.0);
    let pts = [];
    let sides = floor(random(6, 10));
    let baseAng = random(360);

    for (let s = 0; s < sides; s++) {
      let a = baseAng + (s * 360) / sides;
      let r = clodR * random(0.68, 1.18);
      pts.push([cx + cos(a) * r, cy + sin(a) * r]);
    }

    // Shadow under clod
    let shPts = pts.map(pt => [pt[0] + 4, pt[1] + 5]);
    drawWashShape(shPts, PALETTE.shadowAbyss, 195, 0.25);

    // Clod body
    let clodCol = random() < 0.5 ? PALETTE.soilDark : (random() < 0.5 ? PALETTE.soilMid : PALETTE.soilWarm);
    drawWashShape(pts, clodCol, 215, 0.25);

    // Coloured pencil shading on clod
    for (let k = 0; k < 4; k++) {
      let a = random(180, 340);
      let r1 = clodR * random(0.2, 0.7);
      let x1 = cx + cos(a) * r1;
      let y1 = cy + sin(a) * r1;
      safeLine("cpencil", PALETTE.paperLight, 0.65, x1, y1, x1 + random(-6, 6), y1 + random(-4, 4));
    }

    // Pale rime frost crusting the top ridges of the soil clod
    let rimeCount = floor( map(clodR, 5, 42, 3, 14) );
    for (let r = 0; r < rimeCount; r++) {
      let a = random(-155, -15);
      let rad = clodR * random(0.35, 0.98);
      let rx = cx + cos(a) * rad;
      let ry = cy + sin(a) * rad;
      let len = random(2.5, 6.5);
      let spikeAng = a + random(-35, 35);
      let col = random() < 0.38 ? PALETTE.frostWhite : (random() < 0.6 ? PALETTE.rimePale : PALETTE.rimeBlue);
      safeLine("ice_needle", col, random(0.55, 1.05), rx, ry, rx + cos(spikeAng) * len, ry + sin(spikeAng) * len);
    }
  }

  // Delicate frost rime crystal stars & needles across bare soil patches
  for (let i = 0; i < 420; i++) {
    let sx = random(width);
    let sy = random(height);
    let d1 = dist(sx, sy, 420, 430);
    let d2 = dist(sx, sy, 820, 770);
    if (d1 < 230 || d2 < 230) continue;

    if (random() < 0.22) {
      // Miniature six-rayed ground hoarfrost star on soil
      let starR = random(3.5, 8.5);
      let baseA = random(60);
      for (let ray = 0; ray < 3; ray++) {
        let a = baseA + ray * 60 + random(-6, 6);
        safeLine(
          "ice_needle",
          random() < 0.5 ? PALETTE.rimePale : PALETTE.frostCyan,
          0.6,
          sx - cos(a) * starR,
          sy - sin(a) * starR,
          sx + cos(a) * starR,
          sy + sin(a) * starR
        );
      }
    } else {
      // Single pale rime needle
      let a = random(360);
      let l = random(2, 5.5);
      safeLine("verithin", PALETTE.rimeBlue, 0.5, sx, sy, sx + cos(a) * l, sy + sin(a) * l);
    }
  }

  // A few frost-rimmed winter pine needles / dry stems resting on the soil
  const twigs = [
    { x1: 860, y1: 160, x2: 1030, y2: 240, bend: 18 },
    { x1: 940, y1: 330, x2: 1120, y2: 280, bend: -14 },
    { x1: 120, y1: 760, x2: 280, y2: 870, bend: 22 },
    { x1: 190, y1: 930, x2: 330, y2: 830, bend: -15 }
  ];
  for (let tw of twigs) {
    let mx = (tw.x1 + tw.x2) * 0.5 + tw.bend;
    let my = (tw.y1 + tw.y2) * 0.5 - tw.bend;
    safeSpline("2B", PALETTE.shadowAbyss, 1.8, [[tw.x1 + 3, tw.y1 + 4], [mx + 3, my + 4], [tw.x2 + 3, tw.y2 + 4]], 0.4);
    safeSpline("cpencil", "#3b353d", 1.3, [[tw.x1, tw.y1], [mx, my], [tw.x2, tw.y2]], 0.4);
    // Frost needles along twig
    for (let t = 0.08; t <= 0.92; t += 0.06) {
      let px = bezierPoint(tw.x1, mx, mx, tw.x2, t);
      let py = bezierPoint(tw.y1, my, my, tw.y2, t);
      let fa = atan2(tw.y2 - tw.y1, tw.x2 - tw.x1) + (random() < 0.5 ? -65 : 65) + random(-15, 15);
      let fl = random(3.5, 8);
      safeLine("ice_needle", PALETTE.frostWhite, 0.75, px, py, px + cos(fa) * fl, py + sin(fa) * fl);
    }
  }
}

// =============================================================================
// 3. INTERLOCKING KALE BED ARCHITECTURE
// =============================================================================

function renderKaleGardenBed() {
  const cLac = { x: 415, y: 425 }; // Primary Lacinato Kale Rosette Center
  const cRed = { x: 815, y: 775 }; // Primary Red Curly Kale Rosette Center

  let leaves = [];

  // --- A. Peripheral Framing Leaves (Neighboring plants entering from corners) ---
  leaves.push({
    type: "lacinato", tier: 0,
    bx: 1180, by: 70, angle: 148, len: 390, wid: 125, bend: -16, frost: 0.9
  });
  leaves.push({
    type: "lacinato", tier: 0,
    bx: 1210, by: 220, angle: 168, len: 350, wid: 115, bend: 14, frost: 0.85
  });
  leaves.push({
    type: "red", tier: 0,
    bx: 40, by: 1150, angle: -42, len: 360, wid: 195, bend: 12, frost: 0.9
  });
  leaves.push({
    type: "red", tier: 0,
    bx: -20, by: 980, angle: -18, len: 320, wid: 175, bend: -15, frost: 0.85
  });

  // --- B. Outer Tier Leaves (Tier 1 - Large mature leaves spreading wide) ---
  const lacTier1 = [
    { angle: 195, len: 430, wid: 138, bend: -18 },
    { angle: 132, len: 410, wid: 132, bend: 15 },
    { angle: 255, len: 420, wid: 142, bend: 14 },
    { angle: 68,  len: 400, wid: 130, bend: -16 },
    { angle: 315, len: 435, wid: 136, bend: -12 },
    { angle: 12,  len: 445, wid: 140, bend: 18 } // Reaches toward Red Kale
  ];
  for (let l of lacTier1) {
    leaves.push({
      type: "lacinato", tier: 1,
      bx: cLac.x + cos(l.angle) * 18,
      by: cLac.y + sin(l.angle) * 18,
      angle: l.angle, len: l.len, wid: l.wid, bend: l.bend, frost: 0.95
    });
  }

  const redTier1 = [
    { angle: 20,  len: 390, wid: 215, bend: 14 },
    { angle: 82,  len: 380, wid: 210, bend: -16 },
    { angle: 142, len: 400, wid: 220, bend: 15 },
    { angle: 262, len: 390, wid: 205, bend: -12 },
    { angle: 322, len: 385, wid: 210, bend: 16 },
    { angle: 204, len: 425, wid: 225, bend: -14 } // Reaches toward Lacinato Kale
  ];
  for (let l of redTier1) {
    leaves.push({
      type: "red", tier: 1,
      bx: cRed.x + cos(l.angle) * 20,
      by: cRed.y + sin(l.angle) * 20,
      angle: l.angle, len: l.len, wid: l.wid, bend: l.bend, frost: 0.95
    });
  }

  // --- C. Middle Tier Leaves (Tier 2 - Richly arched, deeply textured) ---
  const lacTier2 = [
    { angle: 42,  len: 340, wid: 118, bend: -14 },
    { angle: 102, len: 325, wid: 112, bend: 16 },
    { angle: 164, len: 335, wid: 116, bend: -15 },
    { angle: 226, len: 330, wid: 115, bend: 12 },
    { angle: 288, len: 345, wid: 120, bend: -14 },
    { angle: 348, len: 350, wid: 118, bend: 15 }
  ];
  for (let l of lacTier2) {
    leaves.push({
      type: "lacinato", tier: 2,
      bx: cLac.x + cos(l.angle) * 10,
      by: cLac.y + sin(l.angle) * 10,
      angle: l.angle, len: l.len, wid: l.wid, bend: l.bend, frost: 1.08
    });
  }

  const redTier2 = [
    { angle: 52,  len: 305, wid: 185, bend: -12 },
    { angle: 115, len: 295, wid: 178, bend: 14 },
    { angle: 176, len: 320, wid: 192, bend: -16 },
    { angle: 235, len: 310, wid: 186, bend: 15 },
    { angle: 295, len: 300, wid: 180, bend: -14 },
    { angle: 352, len: 295, wid: 176, bend: 12 }
  ];
  for (let l of redTier2) {
    leaves.push({
      type: "red", tier: 2,
      bx: cRed.x + cos(l.angle) * 12,
      by: cRed.y + sin(l.angle) * 12,
      angle: l.angle, len: l.len, wid: l.wid, bend: l.bend, frost: 1.08
    });
  }

  // --- D. Inner Upper Tier Leaves (Tier 3 - Steep, heavily frosted young leaves) ---
  const lacTier3 = [
    { angle: 18,  len: 215, wid: 86, bend: -12 },
    { angle: 92,  len: 200, wid: 82, bend: 14 },
    { angle: 165, len: 210, wid: 84, bend: -10 },
    { angle: 238, len: 195, wid: 80, bend: 12 },
    { angle: 310, len: 205, wid: 84, bend: -14 }
  ];
  for (let l of lacTier3) {
    leaves.push({
      type: "lacinato", tier: 3,
      bx: cLac.x + cos(l.angle) * 5,
      by: cLac.y + sin(l.angle) * 5,
      angle: l.angle, len: l.len, wid: l.wid, bend: l.bend, frost: 1.22
    });
  }

  const redTier3 = [
    { angle: 30,  len: 195, wid: 135, bend: 12 },
    { angle: 102, len: 185, wid: 128, bend: -14 },
    { angle: 174, len: 205, wid: 140, bend: 12 },
    { angle: 246, len: 190, wid: 132, bend: -12 },
    { angle: 318, len: 185, wid: 130, bend: 14 }
  ];
  for (let l of redTier3) {
    leaves.push({
      type: "red", tier: 3,
      bx: cRed.x + cos(l.angle) * 6,
      by: cRed.y + sin(l.angle) * 6,
      angle: l.angle, len: l.len, wid: l.wid, bend: l.bend, frost: 1.22
    });
  }

  // Sort by tier and interleave Lacinato and Red Kale so overlaps look organic
  leaves.sort((a, b) => a.tier - b.tier);

  for (let leaf of leaves) {
    if (leaf.type === "lacinato") {
      drawLacinatoLeaf(leaf);
    } else {
      drawRedKaleLeaf(leaf);
    }
  }

  // --- E. Tightly Curled Rosette Crowns (Heart buds) ---
  drawLacinatoCrown(cLac.x, cLac.y);
  drawRedKaleCrown(cRed.x, cRed.y);
}

// =============================================================================
// 4. LACINATO (TUSCAN / DINOSAUR) KALE LEAF RENDERER
// =============================================================================

function drawLacinatoLeaf(cfg) {
  const { bx, by, angle, len, wid, bend, tier, frost } = cfg;
  const steps = 26;
  const seed = bx * 0.13 + by * 0.29 + angle;

  let spine = [];
  let leftMargin = [];
  let rightMargin = [];

  // 1. Compute Spine & Rolled Crinkled Margins
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let curAng = angle + bend * sin(t * 180) + (noise(seed + t * 2.5) - 0.5) * 14;
    let px = bx;
    let py = by;
    if (i > 0) {
      let prev = spine[i - 1];
      let stepLen = (len / steps) * (1.0 - 0.12 * t);
      px = prev.x + cos(curAng) * stepLen;
      py = prev.y + sin(curAng) * stepLen;
    }

    // Strap-like oblanceolate width profile of Lacinato kale
    let profile;
    if (t < 0.12) {
      let u = t / 0.12;
      profile = 0.11 + 0.24 * (u * u);
    } else if (t < 0.78) {
      let u = (t - 0.12) / 0.66;
      profile = 0.35 + 0.65 * sin(u * 155);
    } else {
      let u = (t - 0.78) / 0.22;
      profile = 0.62 * cos(u * 90);
    }

    let halfW = (wid * 0.5) * max(0.04, profile);
    let nx = -sin(curAng);
    let ny = cos(curAng);

    // Undulating marginal crinkles
    let waveL = (noise(seed + 10 + t * 9) - 0.5) * 18 * sin(t * 180);
    let waveR = (noise(seed + 30 + t * 9) - 0.5) * 18 * sin(t * 180);
    let puckerL = sin(t * 720 + seed * 20) * 4.5 * sin(t * 180);
    let puckerR = cos(t * 720 + seed * 25) * 4.5 * sin(t * 180);

    let wL = max(3, halfW + waveL + puckerL);
    let wR = max(3, halfW + waveR + puckerR);

    let lx = px + nx * wL;
    let ly = py + ny * wL;
    let rx = px - nx * wR;
    let ry = py - ny * wR;

    spine.push({ x: px, y: py, ang: curAng, nx, ny, wL, wR, t });
    leftMargin.push([lx, ly]);
    rightMargin.push([rx, ry]);
  }

  let contour = [...leftMargin, ...rightMargin.slice().reverse()];

  // 2. Deep, Frost-Free Overlap Cast Shadow
  let shOff = 15 + tier * 3.5;
  let shAng = angle + 25;
  let shadowPts1 = contour.map(p => [
    p[0] + cos(shAng) * shOff + 5,
    p[1] + sin(shAng) * shOff + 7
  ]);
  let shadowPts2 = contour.map(p => [
    p[0] + cos(shAng) * (shOff * 0.55) + 2,
    p[1] + sin(shAng) * (shOff * 0.55) + 3
  ]);

  drawWashShape(shadowPts1, PALETTE.shadowSlate, 185, 0.35);
  drawWashShape(shadowPts2, PALETTE.shadowAbyss, 235, 0.35);

  // Feathered frost-free dark coloured pencil shading along the shadow edge
  for (let i = 2; i < leftMargin.length - 2; i++) {
    let lp = leftMargin[i];
    let rp = rightMargin[i];
    safeLine("2B", PALETTE.shadowAbyss, 1.35, lp[0] + 4, lp[1] + 5, lp[0] + cos(shAng) * shOff, lp[1] + sin(shAng) * shOff);
    safeLine("2B", PALETTE.shadowAbyss, 1.35, rp[0] + 4, rp[1] + 5, rp[0] + cos(shAng) * shOff, rp[1] + sin(shAng) * shOff);
  }

  // 3. Base Slate-Green Leaf Blade & Coloured Pencil Undertone
  drawWashShape(contour, PALETTE.lacinatoDeep, 248, 0.35);

  let innerContour = [];
  for (let i = 2; i <= steps - 1; i++) {
    let s = spine[i];
    innerContour.push([s.x + s.nx * (s.wL * 0.86), s.y + s.ny * (s.wL * 0.86)]);
  }
  for (let i = steps - 1; i >= 2; i--) {
    let s = spine[i];
    innerContour.push([s.x - s.nx * (s.wR * 0.86), s.y - s.ny * (s.wR * 0.86)]);
  }
  drawWashShape(innerContour, PALETTE.lacinatoDark, 210, 0.35);
  drawHatchShape(innerContour, "cpencil", PALETTE.lacinatoMid, 0.85, 6.5, angle + 45, { rand: 0.16 }, 0.35);

  // 4. Lateral Veins & Savoyed Bullate Blisters (Signature Lacinato Texture)
  let veinStations = [];
  for (let i = 3; i <= steps - 2; i += 2) {
    veinStations.push(i);
  }

  // Render bullate blisters between lateral veins on both sides
  for (let side of [-1, 1]) {
    for (let vIdx = 0; vIdx < veinStations.length - 1; vIdx++) {
      let idxA = veinStations[vIdx];
      let idxB = veinStations[vIdx + 1];
      let sA = spine[idxA];
      let sB = spine[idxB];

      let maxW_A = side === 1 ? sA.wL : sA.wR;
      let maxW_B = side === 1 ? sB.wL : sB.wR;
      let avgW = (maxW_A + maxW_B) * 0.5;

      let numBlisters = constrain(floor(avgW / 14), 2, 5);

      for (let b = 0; b < numBlisters; b++) {
        let u0 = (b + 0.12) / numBlisters;
        let u1 = (b + 0.92) / numBlisters;
        let uMid = (u0 + u1) * 0.5;

        // Lateral veins sweep forward toward the tip as they move outward
        let fwdA = min(steps, idxA + floor(uMid * 2.6));
        let fwdB = min(steps, idxB + floor(uMid * 2.6));
        let sp1 = spine[fwdA];
        let sp2 = spine[fwdB];

        let w1 = (side === 1 ? sp1.wL : sp1.wR) * uMid * 0.92;
        let w2 = (side === 1 ? sp2.wL : sp2.wR) * uMid * 0.92;

        let cx = (sp1.x + sp2.x) * 0.5 + ((sp1.nx + sp2.nx) * 0.5) * side * ((w1 + w2) * 0.5);
        let cy = (sp1.y + sp2.y) * 0.5 + ((sp1.ny + sp2.ny) * 0.5) * side * ((w1 + w2) * 0.5);

        let blisterR = constrain((avgW / numBlisters) * 0.52 * random(0.85, 1.15), 5.5, 18);
        let blisterAng = sp1.ang + side * 48 + random(-10, 10);

        drawLacinatoBlister(cx, cy, blisterR, blisterAng, uMid, frost);
      }
    }
  }

  // 5. Lateral Veins & Feathery Hoarfrost Fronds on Lateral Ribs
  for (let side of [-1, 1]) {
    for (let vIdx = 0; vIdx < veinStations.length; vIdx++) {
      let idx = veinStations[vIdx];
      let s0 = spine[idx];
      let sFwd = spine[min(steps, idx + 2)];
      let sTip = spine[min(steps, idx + 3)];

      let maxW0 = side === 1 ? s0.wL : s0.wR;
      let maxWFwd = side === 1 ? sFwd.wL : sFwd.wR;
      let maxWTip = side === 1 ? sTip.wL : sTip.wR;
      if (maxW0 < 12) continue;

      let p0 = [s0.x + s0.nx * side * 2.5, s0.y + s0.ny * side * 2.5];
      let p1 = [
        sFwd.x + sFwd.nx * side * (maxWFwd * 0.52) + random(-3, 3),
        sFwd.y + sFwd.ny * side * (maxWFwd * 0.52) + random(-3, 3)
      ];
      let p2 = [
        sTip.x + sTip.nx * side * (maxWTip * 0.86),
        sTip.y + sTip.ny * side * (maxWTip * 0.86)
      ];

      // Dark sunken trough beside lateral vein
      safeSpline("verithin", PALETTE.shadowAbyss, 0.95, [
        [p0[0] + 1.5, p0[1] + 1.5],
        [p1[0] + 1.5, p1[1] + 1.5],
        [p2[0] + 1.5, p2[1] + 1.5]
      ], 0.45);

      // Lateral vein body
      safeSpline("cpencil", PALETTE.lacinatoRibMid, 1.1, [p0, p1, p2], 0.45);
      safeSpline("verithin", PALETTE.lacinatoRibLight, 0.75, [p0, p1, p2], 0.45);

      // Forked sub-vein near leaf edge
      if (maxWFwd > 22 && idx < steps - 3) {
        let sFork = spine[min(steps, idx + 1)];
        let pf = [
          sFork.x + sFork.nx * side * (maxWFwd * 0.82),
          sFork.y + sFork.ny * side * (maxWFwd * 0.82)
        ];
        safeLine("verithin", PALETTE.lacinatoRibMid, 0.65, p1[0], p1[1], pf[0], pf[1]);
      }

      // Feathery hoarfrost fronds growing along lateral vein
      let veinAng = atan2(p1[1] - p0[1], p1[0] - p0[0]);
      let numFronds = floor(random(3, 6) * frost);
      for (let f = 0; f < numFronds; f++) {
        let u = map(f, 0, numFronds, 0.15, 0.82);
        let fx = lerp(p0[0], p2[0], u);
        let fy = lerp(p0[1], p2[1], u);
        let fSide = (f % 2 === 0 ? 1 : -1);
        let frondAng = veinAng + fSide * random(42, 68);
        let frondLen = random(6, 13) * frost * (1.0 - 0.35 * u);
        drawHoarfrostFrond(fx, fy, frondAng, frondLen, 0.85);
      }
    }
  }

  // 6. Central Midrib & Prominent Feathery Hoarfrost Fronds
  for (let i = 0; i < steps - 1; i++) {
    let s1 = spine[i];
    let s2 = spine[i + 1];
    let ribW = map(s1.t, 0, 1, wid * 0.085, 1.2);

    // Sunken shadow grooves flanking the midrib
    safeLine("verithin", PALETTE.shadowAbyss, 1.1,
      s1.x + s1.nx * (ribW + 1.5), s1.y + s1.ny * (ribW + 1.5),
      s2.x + s2.nx * (ribW + 1.2), s2.y + s2.ny * (ribW + 1.2)
    );
    safeLine("verithin", PALETTE.shadowAbyss, 1.1,
      s1.x - s1.nx * (ribW + 1.5), s1.y - s1.ny * (ribW + 1.5),
      s2.x - s2.nx * (ribW + 1.2), s2.y - s2.ny * (ribW + 1.2)
    );

    // Burnished glaucous midrib body
    let weightRib = map(s1.t, 0, 1, 2.6, 0.55);
    safeLine("burnish", PALETTE.lacinatoRibDark, weightRib * 1.15, s1.x, s1.y, s2.x, s2.y);
    safeLine("cpencil", PALETTE.lacinatoRibMid, weightRib * 0.85, s1.x, s1.y, s2.x, s2.y);
    safeLine("verithin", PALETTE.lacinatoRibLight, weightRib * 0.55, s1.x, s1.y, s2.x, s2.y);

    // Feathery hoarfrost fronds growing along both sides of the central midrib
    if (i >= 1 && i < steps - 1) {
      let frondsPerStep = s1.t < 0.75 ? 2 : 1;
      for (let f = 0; f < frondsPerStep; f++) {
        let u = (f + random(0.15, 0.85)) / frondsPerStep;
        let mx = lerp(s1.x, s2.x, u);
        let my = lerp(s1.y, s2.y, u);

        for (let side of [-1, 1]) {
          if (random() > 0.82 * frost) continue;
          let rx = mx + s1.nx * side * (ribW * 0.85);
          let ry = my + s1.ny * side * (ribW * 0.85);
          let frondAng = s1.ang + side * random(42, 68);
          let frondLen = random(9, 20) * frost * (1.05 - 0.55 * s1.t);
          drawHoarfrostFrond(rx, ry, frondAng, frondLen, 1.05);
        }
      }
    }
  }

  // 7. Rolled Crinkled Leaf Margin Outlined by Needle-Fine White Pencil Crystals
  drawCrinkledFrostedMargin(leftMargin, spine, 1, PALETTE.lacinatoDeep, PALETTE.lacinatoHigh, frost);
  drawCrinkledFrostedMargin(rightMargin, spine, -1, PALETTE.lacinatoDeep, PALETTE.lacinatoHigh, frost);
}

function drawLacinatoBlister(cx, cy, r, ang, uDist, frost) {
  let rx = r * 1.22;
  let ry = r * 0.82;

  // 1. Dark crevice ring around the blister dome
  let ringPts = [];
  for (let a = 0; a <= 360; a += 45) {
    let radX = rx * random(0.92, 1.08);
    let radY = ry * random(0.92, 1.08);
    let px = cx + cos(a) * radX * cos(ang) - sin(a) * radY * sin(ang);
    let py = cy + cos(a) * radX * sin(ang) + sin(a) * radY * cos(ang);
    ringPts.push([px, py]);
  }
  safeSpline("verithin", PALETTE.shadowAbyss, 1.05, ringPts, 0.5);

  // 2. Burnished coloured pencil dome strokes (dark slate to frosty sage-slate)
  const layers = [
    { scale: 0.82, col: PALETTE.lacinatoMid, brush: "burnish", w: 1.05 },
    { scale: 0.58, col: PALETTE.lacinatoSlate, brush: "burnish", w: 0.9 },
    { scale: 0.36, col: PALETTE.lacinatoHigh, brush: "cpencil", w: 0.78 }
  ];

  for (let lyr of layers) {
    let arcPts = [];
    for (let a = -150; a <= 30; a += 45) {
      let px = cx + (cos(a) * rx * lyr.scale) * cos(ang) - (sin(a) * ry * lyr.scale - ry * 0.1) * sin(ang);
      let py = cy + (cos(a) * rx * lyr.scale) * sin(ang) + (sin(a) * ry * lyr.scale - ry * 0.1) * cos(ang);
      arcPts.push([px, py]);
    }
    safeSpline(lyr.brush, lyr.col, lyr.w, arcPts, 0.5);
  }

  // Burnished highlight sheen at crest of blister
  if (r > 7.5) {
    safeLine(
      "cpencil",
      PALETTE.lacinatoBurnish,
      0.75,
      cx - cos(ang) * (rx * 0.25),
      cy - sin(ang) * (rx * 0.25) - 1.5,
      cx + cos(ang) * (rx * 0.25),
      cy + sin(ang) * (rx * 0.25) - 1.5
    );
  }

  // 3. Needle-fine white pencil crystals outlining the crinkled blister ridge
  let crystalCount = floor(map(r, 5.5, 18, 5, 14) * frost * (0.65 + 0.5 * uDist));
  let startA = random(-170, -110);
  let spanA = random(140, 230);

  let crestPts = [];
  for (let c = 0; c < crystalCount; c++) {
    let a = startA + (c / max(1, crystalCount - 1)) * spanA + random(-8, 8);
    let radX = rx * random(0.68, 0.96);
    let radY = ry * random(0.68, 0.96);
    let bx = cx + cos(a) * radX * cos(ang) - sin(a) * radY * sin(ang);
    let by = cy + cos(a) * radX * sin(ang) + sin(a) * radY * cos(ang);
    crestPts.push([bx, by]);

    let outAng = atan2(by - cy, bx - cx) + random(-22, 22);
    let spikeLen = random(2.5, 6.8) * frost;
    let col = random() < 0.55 ? PALETTE.pureWhite : PALETTE.frostCyan;
    safeLine("ice_needle", col, random(0.6, 1.05), bx, by, bx + cos(outAng) * spikeLen, by + sin(outAng) * spikeLen);
  }

  if (crestPts.length >= 3) {
    safeSpline("ice_needle", PALETTE.frostWhite, 0.72, crestPts, 0.35);
  }
}

// =============================================================================
// 5. RED CURLY KALE LEAF RENDERER (PLUM-VIOLET & 3D FRILLED RUFFLES)
// =============================================================================

function drawRedKaleLeaf(cfg) {
  const { bx, by, angle, len, wid, bend, tier, frost } = cfg;
  const steps = 24;
  const seed = bx * 0.19 + by * 0.31 + angle;

  let spine = [];
  let leftMargin = [];
  let rightMargin = [];
  let lobesLeft = [];
  let lobesRight = [];

  // 1. Compute Spine & Deeply Lobed Ruffled Fan Geometry
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let curAng = angle + bend * sin(t * 180) + (noise(seed + t * 2.2) - 0.5) * 16;
    let px = bx;
    let py = by;
    if (i > 0) {
      let prev = spine[i - 1];
      let stepLen = (len / steps) * (1.0 - 0.1 * t);
      px = prev.x + cos(curAng) * stepLen;
      py = prev.y + sin(curAng) * stepLen;
    }

    // Broad obovate / fan-shaped Red Kale profile with deep pinnate lobes
    let baseProfile;
    if (t < 0.15) {
      baseProfile = 0.08 + 0.25 * (t / 0.15);
    } else if (t < 0.82) {
      let u = (t - 0.15) / 0.67;
      baseProfile = 0.33 + 0.67 * pow(sin(u * 135), 0.75);
    } else {
      let u = (t - 0.82) / 0.18;
      baseProfile = 0.78 * cos(u * 85);
    }

    // Deep lobe modulation (5-6 distinct ruffled lobes along each side)
    let lobeModL = 0.72 + 0.36 * sin(t * 1800 + seed * 10);
    let lobeModR = 0.72 + 0.36 * sin(t * 1800 + seed * 10 + 45);
    if (t < 0.18) {
      lobeModL = 1.0;
      lobeModR = 1.0;
    }

    let halfW = wid * 0.5 * max(0.05, baseProfile);
    let wL = max(4, halfW * lobeModL);
    let wR = max(4, halfW * lobeModR);

    let nx = -sin(curAng);
    let ny = cos(curAng);

    let lx = px + nx * wL;
    let ly = py + ny * wL;
    let rx = px - nx * wR;
    let ry = py - ny * wR;

    spine.push({ x: px, y: py, ang: curAng, nx, ny, wL, wR, t });
    leftMargin.push([lx, ly]);
    rightMargin.push([rx, ry]);

    if (i >= 4 && i <= steps - 1) {
      lobesLeft.push({ x: lx, y: ly, sx: px, sy: py, nx, ny, w: wL, t, ang: curAng + 68 });
      lobesRight.push({ x: rx, y: ry, sx: px, sy: py, nx: -nx, ny: -ny, w: wR, t, ang: curAng - 68 });
    }
  }

  // Add apical crown ruffle lobes around the tip
  let sTip = spine[steps - 1];
  let apicalLobes = [];
  for (let a = -55; a <= 55; a += 22) {
    let tipAng = sTip.ang + a;
    let rad = wid * 0.28 * (1.0 - 0.004 * abs(a));
    apicalLobes.push({
      x: sTip.x + cos(tipAng) * rad,
      y: sTip.y + sin(tipAng) * rad,
      sx: sTip.x,
      sy: sTip.y,
      nx: cos(tipAng),
      ny: sin(tipAng),
      w: rad,
      t: 0.95,
      ang: tipAng
    });
  }

  let contour = [
    ...leftMargin.slice(0, steps - 1),
    ...apicalLobes.map(l => [l.x, l.y]),
    ...rightMargin.slice(0, steps - 1).reverse()
  ];

  // 2. Deep Frost-Free Overlap Cast Shadow
  let shOff = 17 + tier * 3.8;
  let shAng = angle + 22;
  let shadowPts1 = contour.map(p => [
    p[0] + cos(shAng) * shOff + 5,
    p[1] + sin(shAng) * shOff + 7
  ]);
  let shadowPts2 = contour.map(p => [
    p[0] + cos(shAng) * (shOff * 0.55) + 2,
    p[1] + sin(shAng) * (shOff * 0.55) + 3
  ]);

  drawWashShape(shadowPts1, PALETTE.shadowPlum, 195, 0.4);
  drawWashShape(shadowPts2, PALETTE.shadowAbyss, 240, 0.4);

  // Feathered frost-free shadow strokes under the ruffled lobes
  for (let i = 3; i < contour.length; i += 2) {
    let cp = contour[i];
    safeLine("2B", PALETTE.shadowAbyss, 1.4, cp[0] + 3, cp[1] + 4, cp[0] + cos(shAng) * shOff, cp[1] + sin(shAng) * shOff);
  }

  // 3. Base Plum-Violet Leaf Blade & Coloured Pencil Burnishing
  drawWashShape(contour, PALETTE.plumAbyss, 248, 0.4);

  let innerPts = [];
  for (let i = 2; i < steps - 1; i++) {
    let s = spine[i];
    innerPts.push([s.x + s.nx * (s.wL * 0.82), s.y + s.ny * (s.wL * 0.82)]);
  }
  for (let i = steps - 2; i >= 2; i--) {
    let s = spine[i];
    innerPts.push([s.x - s.nx * (s.wR * 0.82), s.y - s.ny * (s.wR * 0.82)]);
  }
  drawWashShape(innerPts, PALETTE.plumDeep, 225, 0.4);
  drawHatchShape(innerPts, "cpencil", PALETTE.plumDark, 0.9, 6, angle - 38, { rand: 0.18 }, 0.4);

  // 4. Internal Ripple Folds & Burnished Plum Ridges across the Blade
  for (let side of [-1, 1]) {
    for (let i = 4; i <= steps - 2; i += 2) {
      let s0 = spine[i];
      let s1 = spine[min(steps, i + 2)];
      let maxW = side === 1 ? s0.wL : s0.wR;
      if (maxW < 18) continue;

      let foldCount = 3;
      for (let f = 0; f < foldCount; f++) {
        let u0 = 0.15 + f * 0.22;
        let u1 = u0 + 0.25;
        let pA = [s0.x + s0.nx * side * (maxW * u0), s0.y + s0.ny * side * (maxW * u0)];
        let pB = [
          (s0.x + s1.x) * 0.5 + s0.nx * side * (maxW * ((u0 + u1) * 0.5)) + cos(s0.ang) * 8,
          (s0.y + s1.y) * 0.5 + s0.ny * side * (maxW * ((u0 + u1) * 0.5)) + sin(s0.ang) * 8
        ];
        let pC = [s1.x + s1.nx * side * (maxW * u1), s1.y + s1.ny * side * (maxW * u1)];

        // Frost-free dark damson fold trough
        safeSpline("2B", PALETTE.shadowAbyss, 1.3, [
          [pA[0] + 2, pA[1] + 2],
          [pB[0] + 2, pB[1] + 2],
          [pC[0] + 2, pC[1] + 2]
        ], 0.45);

        // Burnished plum-violet ridge
        safeSpline("burnish", PALETTE.plumMid, 1.25, [pA, pB, pC], 0.45);
        safeSpline("cpencil", PALETTE.plumBright, 0.95, [pA, pB, pC], 0.45);
        safeSpline("verithin", PALETTE.plumHigh, 0.7, [pA, pB, pC], 0.45);

        // Fine white frost needles catching on internal crinkle ridge
        let numTicks = floor(random(4, 8) * frost);
        for (let k = 0; k < numTicks; k++) {
          let ku = k / max(1, numTicks - 1);
          let tx = bezierPoint(pA[0], pB[0], pB[0], pC[0], ku);
          let ty = bezierPoint(pA[1], pB[1], pB[1], pC[1], ku);
          let ta = s0.ang + side * 40 + random(-25, 25);
          let tl = random(2.5, 6.2) * frost;
          safeLine("ice_needle", random() < 0.5 ? PALETTE.pureWhite : PALETTE.frostCyan, 0.75, tx, ty, tx + cos(ta) * tl, ty + sin(ta) * tl);
        }
      }
    }
  }

  // 5. Branching Plum-Magenta Veins & Feathery Hoarfrost Fronds
  for (let side of [-1, 1]) {
    for (let i = 4; i <= steps - 2; i += 3) {
      let s0 = spine[i];
      let sMid = spine[min(steps, i + 2)];
      let sEnd = spine[min(steps, i + 3)];
      let maxW = side === 1 ? sMid.wL : sMid.wR;
      if (maxW < 16) continue;

      let v0 = [s0.x + s0.nx * side * 2, s0.y + s0.ny * side * 2];
      let v1 = [sMid.x + sMid.nx * side * (maxW * 0.48), sMid.y + sMid.ny * side * (maxW * 0.48)];
      let v2 = [sEnd.x + sEnd.nx * side * (maxW * 0.78), sEnd.y + sEnd.ny * side * (maxW * 0.78)];

      // Sunken shadow next to plum vein
      safeSpline("verithin", PALETTE.shadowAbyss, 1.0, [
        [v0[0] + 1.5, v0[1] + 1.5],
        [v1[0] + 1.5, v1[1] + 1.5],
        [v2[0] + 1.5, v2[1] + 1.5]
      ], 0.45);

      // Vivid magenta-plum lateral vein
      safeSpline("burnish", PALETTE.plumVeinDark, 1.25, [v0, v1, v2], 0.45);
      safeSpline("cpencil", PALETTE.plumVeinMid, 0.95, [v0, v1, v2], 0.45);
      safeSpline("verithin", PALETTE.plumVeinLight, 0.7, [v0, v1, v2], 0.45);

      // Secondary branching veinlets into the ruffles
      for (let br of [-1, 1]) {
        let bAng = atan2(v2[1] - v1[1], v2[0] - v1[0]) + br * 34;
        let bLen = maxW * 0.28;
        let bx2 = v1[0] + cos(bAng) * bLen;
        let by2 = v1[1] + sin(bAng) * bLen;
        safeLine("verithin", PALETTE.plumVeinLight, 0.65, v1[0], v1[1], bx2, by2);
      }

      // Feathery hoarfrost fronds growing along the lateral plum veins
      let vAng = atan2(v1[1] - v0[1], v1[0] - v0[0]);
      let frondCount = floor(random(3, 6) * frost);
      for (let f = 0; f < frondCount; f++) {
        let u = map(f, 0, frondCount, 0.15, 0.85);
        let fx = lerp(v0[0], v2[0], u);
        let fy = lerp(v0[1], v2[1], u);
        let fSide = f % 2 === 0 ? 1 : -1;
        let frondAng = vAng + fSide * random(42, 66);
        let frondLen = random(6.5, 14) * frost * (1.0 - 0.3 * u);
        drawHoarfrostFrond(fx, fy, frondAng, frondLen, 0.9);
      }
    }
  }

  // 6. Central Plum-Violet Midrib & Feathery Hoarfrost Fronds
  for (let i = 0; i < steps - 1; i++) {
    let s1 = spine[i];
    let s2 = spine[i + 1];
    let ribW = map(s1.t, 0, 1, wid * 0.065, 1.2);

    safeLine("verithin", PALETTE.shadowAbyss, 1.15,
      s1.x + s1.nx * (ribW + 1.5), s1.y + s1.ny * (ribW + 1.5),
      s2.x + s2.nx * (ribW + 1.2), s2.y + s2.ny * (ribW + 1.2)
    );
    safeLine("verithin", PALETTE.shadowAbyss, 1.15,
      s1.x - s1.nx * (ribW + 1.5), s1.y - s1.ny * (ribW + 1.5),
      s2.x - s2.nx * (ribW + 1.2), s2.y - s2.ny * (ribW + 1.2)
    );

    let wRib = map(s1.t, 0, 1, 2.7, 0.55);
    safeLine("burnish", PALETTE.plumVeinDark, wRib * 1.15, s1.x, s1.y, s2.x, s2.y);
    safeLine("cpencil", PALETTE.plumVeinMid, wRib * 0.9, s1.x, s1.y, s2.x, s2.y);
    safeLine("verithin", PALETTE.plumVeinGlow, wRib * 0.55, s1.x, s1.y, s2.x, s2.y);

    // Feathery hoarfrost fronds along both sides of the central plum rib
    if (i >= 1 && i < steps - 1) {
      let frondsHere = s1.t < 0.78 ? 2 : 1;
      for (let f = 0; f < frondsHere; f++) {
        let u = (f + random(0.2, 0.8)) / frondsHere;
        let mx = lerp(s1.x, s2.x, u);
        let my = lerp(s1.y, s2.y, u);
        for (let side of [-1, 1]) {
          if (random() > 0.85 * frost) continue;
          let rx = mx + s1.nx * side * (ribW * 0.85);
          let ry = my + s1.ny * side * (ribW * 0.85);
          let frondAng = s1.ang + side * random(40, 68);
          let frondLen = random(9.5, 21) * frost * (1.05 - 0.5 * s1.t);
          drawHoarfrostFrond(rx, ry, frondAng, frondLen, 1.08);
        }
      }
    }
  }

  // 7. Extravagantly Curled 3D Frilled Margins Outlined by Needle-Fine White Crystals
  let allLobes = [...lobesLeft, ...apicalLobes, ...lobesRight.reverse()];
  for (let i = 0; i < allLobes.length; i++) {
    let lb = allLobes[i];
    let curlRadius = constrain(lb.w * 0.24 * random(0.85, 1.2), 10, 26);
    drawRedKale3DRuffleCluster(lb.x, lb.y, lb.ang, curlRadius, frost);
  }
}

function drawRedKale3DRuffleCluster(cx, cy, outAng, rad, frost) {
  // Each marginal lobe consists of 2-3 tightly folded 3D ribbon curls
  const subCurls = 3;
  for (let s = 0; s < subCurls; s++) {
    let offsetAng = outAng + (s - 1) * 42 + random(-10, 10);
    let subDist = rad * (s === 1 ? 0.55 : 0.38);
    let rx = cx + cos(offsetAng) * subDist;
    let ry = cy + sin(offsetAng) * subDist;
    let rSize = rad * (s === 1 ? 0.72 : 0.58);

    // 1. Deep, frost-free dark shadow pocket tucked inside the folded curl
    let pocketPts = [];
    for (let a = 0; a < 360; a += 45) {
      let pr = rSize * 0.65 * random(0.82, 1.15);
      pocketPts.push([rx + cos(a) * pr, ry + sin(a) * pr]);
    }
    drawWashShape(pocketPts, PALETTE.shadowAbyss, 240, 0.45);

    // 2. Burnished plum-violet turning lip of the 3D ruffle
    let lipSpan = random(190, 250);
    let lipStart = offsetAng - lipSpan * 0.5;
    let lipOuter = [];
    let lipMid = [];
    let lipInner = [];

    let segs = 7;
    for (let k = 0; k <= segs; k++) {
      let u = k / segs;
      let a = lipStart + u * lipSpan;
      let wave = sin(u * 360 * 1.5) * (rSize * 0.16);
      let rOut = rSize + wave;
      let rM = rSize * 0.78 + wave * 0.7;
      let rIn = rSize * 0.56 + wave * 0.4;

      lipOuter.push([rx + cos(a) * rOut, ry + sin(a) * rOut]);
      lipMid.push([rx + cos(a) * rM, ry + sin(a) * rM]);
      lipInner.push([rx + cos(a) * rIn, ry + sin(a) * rIn]);
    }

    // Coloured pencil burnishing on the turning curl lip
    safeSpline("burnish", PALETTE.plumDark, 1.35, lipInner, 0.5);
    safeSpline("burnish", PALETTE.plumBright, 1.25, lipMid, 0.5);
    safeSpline("cpencil", PALETTE.plumHigh, 0.95, lipMid, 0.5);
    safeSpline("verithin", PALETTE.plumBurnish, 0.75, lipOuter, 0.5);

    // 3. Needle-fine white pencil crystals outlining the crinkled outer crest
    safeSpline("ice_needle", PALETTE.frostCyan, 0.95, lipOuter, 0.45);
    safeSpline("ice_needle", PALETTE.pureWhite, 0.8, lipOuter, 0.45);

    let numNeedles = floor(map(rSize, 6, 20, 9, 20) * frost);
    for (let n = 0; n < numNeedles; n++) {
      let u = n / max(1, numNeedles - 1);
      let a = lipStart + u * lipSpan + random(-6, 6);
      let wave = sin(u * 360 * 1.5) * (rSize * 0.16);
      let rOut = rSize + wave;
      let nx = rx + cos(a) * rOut;
      let ny = ry + sin(a) * rOut;

      let spikeAng = a + random(-24, 24);
      let spikeLen = random(3.0, 8.8) * frost * (0.7 + 0.5 * sin(u * 180));
      let col = random() < 0.62 ? PALETTE.pureWhite : PALETTE.frostCyan;

      safeLine("ice_needle", col, random(0.65, 1.15), nx, ny, nx + cos(spikeAng) * spikeLen, ny + sin(spikeAng) * spikeLen);

      // Secondary forked crystal barb on larger needles
      if (spikeLen > 5.8 && random() < 0.45) {
        let bx = nx + cos(spikeAng) * (spikeLen * 0.55);
        let by = ny + sin(spikeAng) * (spikeLen * 0.55);
        let barbAng = spikeAng + (random() < 0.5 ? -38 : 38);
        let barbLen = spikeLen * 0.48;
        safeLine("ice_needle", PALETTE.pureWhite, 0.65, bx, by, bx + cos(barbAng) * barbLen, by + sin(barbAng) * barbLen);
      }
    }
  }
}

// =============================================================================
// 6. FEATHERY HOARFROST FRONDS & CRINKLED FROSTED MARGINS
// =============================================================================

function drawHoarfrostFrond(x, y, ang, len, weightMult = 1.0) {
  if (len < 3.5) return;

  // Curved dendritic main crystal spine
  let bend = random(-18, 18);
  let p0 = [x, y];
  let p1 = [
    x + cos(ang + bend * 0.5) * (len * 0.52),
    y + sin(ang + bend * 0.5) * (len * 0.52)
  ];
  let p2 = [
    x + cos(ang + bend) * len,
    y + sin(ang + bend) * len
  ];

  safeSpline("ice_needle", PALETTE.frostCyan, 0.85 * weightMult, [p0, p1, p2], 0.4);
  safeSpline("ice_needle", PALETTE.pureWhite, 0.7 * weightMult, [p0, p1, p2], 0.4);

  // Feathery secondary crystal plumes branching off both sides of the frond spine
  let pairs = constrain(floor(len / 3.2), 2, 6);
  for (let i = 1; i <= pairs; i++) {
    let u = i / (pairs + 0.5);
    let bx = bezierPoint(p0[0], p1[0], p1[0], p2[0], u);
    let by = bezierPoint(p0[1], p1[1], p1[1], p2[1], u);
    let curA = ang + bend * u;

    for (let side of [-1, 1]) {
      let barbAng = curA + side * random(34, 52);
      let barbLen = len * (0.48 * (1.0 - 0.65 * u)) * random(0.8, 1.2);
      if (barbLen < 1.8) continue;

      let ex = bx + cos(barbAng) * barbLen;
      let ey = by + sin(barbAng) * barbLen;
      let col = random() < 0.6 ? PALETTE.pureWhite : PALETTE.frostCyan;
      safeLine("ice_needle", col, 0.62 * weightMult, bx, by, ex, ey);
    }
  }
}

function drawCrinkledFrostedMargin(marginPts, spine, side, darkCol, highCol, frost) {
  // Build high-frequency crinkled scalloped edge along the Lacinato margin
  let crinkledPts = [];

  for (let i = 1; i < marginPts.length - 1; i++) {
    let pA = marginPts[i];
    let pB = marginPts[i + 1];
    let s = spine[i];
    let outAng = atan2(s.ny * side, s.nx * side);

    let subSteps = 4;
    for (let k = 0; k < subSteps; k++) {
      let u = k / subSteps;
      let bx = lerp(pA[0], pB[0], u);
      let by = lerp(pA[1], pB[1], u);

      // Tightly puckered marginal crinkle wave
      let crinkle = sin((i * subSteps + k) * 65) * 3.8 + (noise(i * 0.7 + k * 0.3) - 0.5) * 4.5;
      let cx = bx + cos(outAng) * crinkle;
      let cy = by + sin(outAng) * crinkle;
      crinkledPts.push({ x: cx, y: cy, outAng, t: s.t });
    }
  }

  // 1. Dark tucked shadow just inside the rolled margin
  let innerLip = crinkledPts.map(p => [
    p.x - cos(p.outAng) * 3.5,
    p.y - sin(p.outAng) * 3.5
  ]);
  safeSpline("verithin", PALETTE.shadowAbyss, 1.05, innerLip, 0.4);

  // 2. Burnished slate-blue lip highlight
  let midLip = crinkledPts.map(p => [
    p.x - cos(p.outAng) * 1.5,
    p.y - sin(p.outAng) * 1.5
  ]);
  safeSpline("cpencil", highCol, 0.85, midLip, 0.4);

  // 3. Crystalline white pencil outline & needle spikes along every crinkle
  let outerOutline = crinkledPts.map(p => [p.x, p.y]);
  safeSpline("ice_needle", PALETTE.frostCyan, 0.9, outerOutline, 0.35);
  safeSpline("ice_needle", PALETTE.pureWhite, 0.75, outerOutline, 0.35);

  for (let i = 0; i < crinkledPts.length; i++) {
    let p = crinkledPts[i];
    let spikesHere = random() < 0.65 ? 2 : 1;
    for (let s = 0; s < spikesHere; s++) {
      let spikeAng = p.outAng + random(-32, 32);
      let spikeLen = random(2.8, 8.2) * frost * (0.65 + 0.35 * sin(i * 55));
      let col = random() < 0.62 ? PALETTE.pureWhite : PALETTE.frostCyan;
      safeLine(
        "ice_needle",
        col,
        random(0.65, 1.15),
        p.x,
        p.y,
        p.x + cos(spikeAng) * spikeLen,
        p.y + sin(spikeAng) * spikeLen
      );
    }
  }
}

// =============================================================================
// 7. ROSETTE CROWNS (TIGHTLY CURLED HEART BUDS)
// =============================================================================

function drawLacinatoCrown(cx, cy) {
  // Deep frost-free central shadow well
  let wellPts = [];
  for (let a = 0; a < 360; a += 30) {
    let r = random(42, 58);
    wellPts.push([cx + cos(a) * r, cy + sin(a) * r]);
  }
  drawWashShape(wellPts, PALETTE.shadowAbyss, 245, 0.45);

  // 6 tightly curled young Lacinato heart leaves spiraling inward
  const buds = [
    { ang: 15,  len: 95, wid: 44, bend: 24 },
    { ang: 88,  len: 85, wid: 40, bend: -22 },
    { ang: 162, len: 80, wid: 38, bend: 25 },
    { ang: 235, len: 70, wid: 34, bend: -20 },
    { ang: 308, len: 62, wid: 32, bend: 22 },
    { ang: 52,  len: 46, wid: 26, bend: -28 }
  ];

  for (let b of buds) {
    drawLacinatoLeaf({
      bx: cx + cos(b.ang + 180) * 6,
      by: cy + sin(b.ang + 180) * 6,
      angle: b.ang,
      len: b.len,
      wid: b.wid,
      bend: b.bend,
      tier: 4,
      frost: 1.35
    });
  }

  // Intense cluster of white ice crystals right in the emerging bud apex
  for (let i = 0; i < 45; i++) {
    let a = random(360);
    let d = random(2, 24);
    let px = cx + cos(a) * d;
    let py = cy + sin(a) * d;
    let sa = a + random(-35, 35);
    let sl = random(4, 11);
    safeLine("ice_needle", PALETTE.pureWhite, random(0.75, 1.2), px, py, px + cos(sa) * sl, py + sin(sa) * sl);
  }
}

function drawRedKaleCrown(cx, cy) {
  // Deep frost-free central shadow well
  let wellPts = [];
  for (let a = 0; a < 360; a += 30) {
    let r = random(46, 64);
    wellPts.push([cx + cos(a) * r, cy + sin(a) * r]);
  }
  drawWashShape(wellPts, PALETTE.shadowAbyss, 245, 0.45);

  // Tightly packed 3D ruffled violet bud leaves in the center
  const rings = [
    { count: 6, dist: 36, size: 22 },
    { count: 5, dist: 20, size: 17 },
    { count: 4, dist: 8,  size: 13 }
  ];

  for (let r of rings) {
    let baseA = random(360);
    for (let i = 0; i < r.count; i++) {
      let a = baseA + (i * 360) / r.count + random(-12, 12);
      let bx = cx + cos(a) * r.dist;
      let by = cy + sin(a) * r.dist;

      // Tiny plum vein feeding the central bud ruffle
      safeLine("cpencil", PALETTE.plumVeinGlow, 0.9, cx, cy, bx, by);
      drawHoarfrostFrond(
        lerp(cx, bx, 0.5),
        lerp(cy, by, 0.5),
        a + (i % 2 === 0 ? 52 : -52),
        random(7, 13),
        1.0
      );

      drawRedKale3DRuffleCluster(bx, by, a, r.size, 1.38);
    }
  }
}

// =============================================================================
// 8. FINAL BRITTLE ICE GLINTS & COLD RIME FINISH
// =============================================================================

function drawFinalFrostGlints() {
  // Fine crystalline rime dust across the leaf surfaces (avoiding deep overlap shadows)
  const centres = [
    { x: 415, y: 425, r: 390 },
    { x: 815, y: 775, r: 390 }
  ];

  for (let c of centres) {
    for (let i = 0; i < 240; i++) {
      let a = random(360);
      let d = sqrt(random()) * c.r;
      let gx = c.x + cos(a) * d;
      let gy = c.y + sin(a) * d;

      let glintAng = random(360);
      let glintLen = random(1.8, 5.2);
      let col = random() < 0.65 ? PALETTE.pureWhite : PALETTE.frostCyan;
      safeLine("ice_needle", col, random(0.55, 0.95), gx, gy, gx + cos(glintAng) * glintLen, gy + sin(glintAng) * glintLen);

      // Occasional intersecting crystal cross-glint for brittle ice sparkle
      if (random() < 0.18) {
        let crossA = glintAng + 60 + random(-10, 10);
        safeLine(
          "ice_needle",
          PALETTE.pureWhite,
          0.75,
          gx - cos(crossA) * (glintLen * 0.6),
          gy - sin(crossA) * (glintLen * 0.6),
          gx + cos(crossA) * (glintLen * 0.6),
          gy + sin(crossA) * (glintLen * 0.6)
        );
      }
    }
  }
}

