// =============================================================================
// GEOMETRY & DRAWING HELPERS
// =============================================================================

function polyShape(pts, curvature = 0) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

function lerpHex(c1, c2, t) {
  let col1 = color(c1);
  let col2 = color(c2);
  return lerpColor(col1, col2, constrain(t, 0, 1));
}

function windowTopY(x) {
  // Strong asymmetric diagonal upper window frame
  return map(x, 0, 1200, 328, 74);
}

function windowBotY(x) {
  // Asymmetric diagonal lower window sill
  return map(x, 0, 1200, 1138, 1012);
}

// =============================================================================
// 1. WASHI PAPER TEXTURE
// =============================================================================

function drawWashiPaperTexture() {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set("baren", "#DFD9CA", 0.9);
  for (let y = 15; y < 1200; y += 26) {
    brush.line(0, y + random(-3, 3), 1200, y + random(-3, 3));
  }
}

// =============================================================================
// 2. BOKASHI SKY & TINY SNOW-CAPPED FUJI
// =============================================================================

function drawBokashiWindowSky() {
  const bands = 34;
  const horizonY = 956;

  // Graded bokashi horizontal bands clipped below the diagonal upper window frame
  brush.noStroke();
  brush.noHatch();

  for (let i = 0; i < bands; i++) {
    let t0 = i / bands;
    let t1 = (i + 1.35) / bands;
    let y0 = lerp(65, horizonY, t0);
    let y1 = lerp(65, horizonY, t1);

    // Non-linear ukiyo-e bokashi curve: deep Prussian at top, long transition to pale bone
    let col;
    if (t0 < 0.16) {
      col = lerpHex(PAL.prussianDark, PAL.prussianDeep, t0 / 0.16);
    } else if (t0 < 0.34) {
      col = lerpHex(PAL.prussianDeep, PAL.prussianMid, (t0 - 0.16) / 0.18);
    } else if (t0 < 0.52) {
      col = lerpHex(PAL.prussianMid, PAL.prussianMist, (t0 - 0.34) / 0.18);
    } else if (t0 < 0.70) {
      col = lerpHex(PAL.prussianMist, PAL.prussianHaze, (t0 - 0.52) / 0.18);
    } else if (t0 < 0.86) {
      col = lerpHex(PAL.prussianHaze, PAL.horizonBone, (t0 - 0.70) / 0.16);
    } else {
      col = lerpHex(PAL.horizonBone, PAL.paper, (t0 - 0.86) / 0.14);
    }

    let xLeft0 = y0 < 328 ? map(y0, 328, 74, 0, 1200) : 0;
    let xLeft1 = y1 < 328 ? map(y1, 328, 74, 0, 1200) : 0;
    xLeft0 = constrain(xLeft0, 0, 1200);
    xLeft1 = constrain(xLeft1, 0, 1200);

    brush.wash(col, 215);
    polyShape([
      [xLeft0, max(y0, windowTopY(xLeft0))],
      [1200, max(y0, windowTopY(1200))],
      [1200, y1],
      [xLeft1, max(y1, windowTopY(xLeft1))]
    ]);
  }
  brush.noWash();

  // Soft watercolor bokashi atmospheric pass in upper sky
  const bleedBands = [
    { y0: 75, y1: 240, c: PAL.prussianDark, op: 65 },
    { y0: 180, y1: 390, c: PAL.prussianDeep, op: 55 },
    { y0: 320, y1: 540, c: PAL.prussianSoft, op: 45 },
    { y0: 480, y1: 710, c: PAL.prussianPale, op: 38 }
  ];
  for (let b of bleedBands) {
    brush.fill(b.c, b.op);
    brush.fillBleed(0.22, "out");
    brush.fillTexture(0.3, 0.12);
    let xl0 = constrain(map(b.y0, 328, 74, 0, 1200), 0, 1200);
    let xl1 = constrain(map(b.y1, 328, 74, 0, 1200), 0, 1200);
    polyShape([
      [xl0, max(b.y0, windowTopY(xl0))],
      [1200, max(b.y0, windowTopY(1200))],
      [1200, b.y1],
      [xl1, max(b.y1, windowTopY(xl1))]
    ]);
  }
  brush.noFill();

  // Horizontal woodblock grain lines in the Prussian blue sky
  for (let y = 82; y < 860; y += 9) {
    let t = map(y, 80, 860, 0, 1);
    let xl = constrain(map(y, 328, 74, 0, 1200), 0, 1200);
    let c = lerpHex(PAL.prussianDark, PAL.horizonBlue, t);
    brush.set("2H", c, map(t, 0, 1, 0.45, 0.22));
    brush.line(xl + 4, y, 1200, y + random(-1.2, 1.2));
  }

  // Subtle diagonal interior glass reflection (faint double-bar ceiling light reflection)
  brush.noStroke();
  brush.wash("#E8F0F2", 26);
  polyShape([
    [640, 210], [1080, 118], [1095, 134], [655, 226]
  ]);
  brush.wash("#E8F0F2", 18);
  polyShape([
    [662, 238], [1102, 146], [1110, 155], [670, 247]
  ]);
  brush.noWash();
}

function drawDistantHorizonAndFuji() {
  const hY = 956;
