  brush.wash("#B8C8D0", 190);
  polyShape([
    [0, hY], [1200, hY], [1200, 1020], [0, 1140]
  ]);

  // 2. Mt. Fuji silhouette (concave volcanic slopes + subtle Hoei crater bump on right)
  const fujiPoly = [
