function drawRailwayCatenaryWires() {
  // Subtle asymmetric diagonal overhead railway wires outside the window
  brush.set("rotring", "#2A4558", 0.38);
  // Upper messenger wire (gentle catenary sag)
  let wirePts = [];
  for (let x = 380; x <= 1200; x += 40) {
    let t = (x - 380) / 820;
    let sag = sin(t * 180) * 18;
    wirePts.push([x, lerp(835, 780, t) + sag]);
  }
  brush.spline(wirePts, 0.4);

  // Lower contact wire (straight diagonal)
  brush.set("rotring", "#2A4558", 0.42);
  brush.line(380, 862, 1200, 804);

  // Vertical dropper wires connecting messenger to contact wire
  brush.set("rotring", "#39566B", 0.28);
  for (let x = 440; x < 1180; x += 95) {
    let t = (x - 380) / 820;
    let yTop = lerp(835, 780, t) + sin(t * 180) * 18;
    let yBot = lerp(862, 804, t);
    brush.line(x, yTop, x, yBot);
  }

  // Distant angled railway stanchion truss at far right
  brush.set("rotring", "#223B4D", 0.65);
  brush.line(1118, 765, 1118, 975);
  brush.line(1132, 765, 1132, 975);
