function drawPlasticRingFull() {
  // Classic circular commuter tsurikawa ring
  // Center (396, 470), Outer Radius = 190, Inner Radius = 146, Mid Radius = 168, Tube r = 22
  const cx = 396;
  const cy = 470;
  const rMid = 168;
  const rTube = 22;

  // Build ring sector quads around 360 degrees for smooth cylindrical shading
  const steps = 72;
  const ringZones = [
    { off0: -22, off1: -14, col: PAL.ringShadow, op: 248 }, // Inner rim shadow
    { off0: -14, off1: -5,  col: PAL.ringMid,    op: 250 }, // Inner slope
    { off0: -5,  off1: 7,   col: PAL.ringBase,   op: 252 }, // Central lit crest
    { off0: 7,   off1: 15,  col: PAL.ringMid,    op: 250 }, // Outer slope
    { off0: 15,  off1: 22,  col: PAL.ringShadow, op: 248 }  // Outer rim edge
  ];

  brush.noStroke();
  for (let z of ringZones) {
    brush.wash(z.col, z.op);
    for (let i = 0; i < steps; i++) {
      let a0 = (i / steps) * 360;
      let a1 = ((i + 1) / steps) * 360;
      let r0 = rMid + z.off0;
      let r1 = rMid + z.off1;
      polyShape([
        [cx + cos(a0) * r0, cy + sin(a0) * r0],
        [cx + cos(a1) * r0, cy + sin(a1) * r0],
        [cx + cos(a1) * r1, cy + sin(a1) * r1],
        [cx + cos(a0) * r1, cy + sin(a0) * r1]
      ]);
    }
  }

  // Cool sky reflection along the lower-right outer bevel facing the window
  brush.wash(PAL.ringSkyRefl, 175);
  for (let i = 0; i < steps; i++) {
    let a0 = (i / steps) * 360;
    if (a0 > -35 && a0 < 145) {
      let a1 = a0 + 360 / steps;
      let r0 = rMid + 11;
      let r1 = rMid + 20;
      polyShape([
        [cx + cos(a0) * r0, cy + sin(a0) * r0],
        [cx + cos(a1) * r0, cy + sin(a1) * r0],
        [cx + cos(a1) * r1, cy + sin(a1) * r1],
        [cx + cos(a0) * r1, cy + sin(a0) * r1]
      ]);
    }
  }

  // Deep core shadow along underside of top arc and inner bottom arc
  brush.wash(PAL.ringDeep, 165);
  for (let i = 0; i < steps; i++) {
    let a0 = (i / steps) * 360;
    if (a0 > 20 && a0 < 165) {
      let a1 = a0 + 360 / steps;
      let r0 = rMid - 21;
      let r1 = rMid - 12;
      polyShape([
        [cx + cos(a0) * r0, cy + sin(a0) * r0],
        [cx + cos(a1) * r0, cy + sin(a1) * r0],
        [cx + cos(a1) * r1, cy + sin(a1) * r1],
        [cx + cos(a0) * r1, cy + sin(a0) * r1]
      ]);
    }
  }
  brush.noWash();

  // Fine concentric cylindrical shading lines & worn plastic sheen
  for (let off = -19; off <= 19; off += 2.5) {
    let norm = off / 22;
    let col = abs(norm) < 0.25 ? PAL.ringSpec : (norm < 0 ? PAL.ringDeep : PAL.ringShadow);
    let w = abs(norm) < 0.25 ? 0.65 : 0.32;
    brush.set("2H", col, w);
    brush.arc(cx, cy, rMid + off, 0, 360);
  }

  // High-gloss specular sheen ribbons along the curved torus surface
  brush.set("cpencil", PAL.ringSpec, 1.35);
  brush.arc(cx, cy, rMid + 4, 22, 152);
  brush.arc(cx, cy, rMid + 6, 32, 138);
  brush.arc(cx, cy, rMid - 3, 205, 265);
  brush.set("rotring", "#FFFFFF", 0.75);
  brush.arc(cx, cy, rMid + 5, 38, 128);
  brush.arc(cx, cy, rMid - 9, 48, 115);

  // Subtle injection-mold parting seam line along inner circumference
  brush.set("rotring", "#68645C", 0.35);
  brush.arc(cx, cy, rMid - 18, 15, 170);

  // Worn micro-scratches & commuter fingernail/ring scuffs across the plastic sheen
  for (let i = 0; i < 95; i++) {
    let ang = random(18, 265);
    if (ang > 165 && ang < 205) continue; // thumb area
    let rad = rMid + random(-16, 16);
    let px = cx + cos(ang) * rad;
    let py = cy + sin(ang) * rad;
    let sAng = ang + 90 + random(-38, 38);
    let sLen = random(4, 15);
    brush.set("micro", i % 2 === 0 ? "#FFFFFF" : "#78736A", random(0.3, 0.65));
    brush.line(
      px - cos(sAng) * sLen * 0.5,
      py - sin(sAng) * sLen * 0.5,
      px + cos(sAng) * sLen * 0.5,
      py + sin(sAng) * sLen * 0.5
    );
  }

  // Crisp woodblock keylines for outer and inner ring boundaries
  brush.set("rotring", PAL.ink, 1.05);
  brush.arc(cx, cy, rMid + rTube, 0, 360);
  brush.arc(cx, cy, rMid - rTube, 0, 360);
}

