// Hyperreal Still Life: Three Blocks of Silken Tofu on a Damp Cedar Board
// Rendered with p5.js v2 + p5.brush in WEBGL

const SEED = 4289;

// Camera & 3D Projection state
const CAM = {
  pos: [-430, -500, 355],
  target: [8, -8, 26],
  focal: 1490,
  cx: 600,
  cy: 590,
  forward: [0, 0, 0],
  right: [0, 0, 0],
  up: [0, 0, 0]
};

// Diffused paper window light direction (pointing toward Upper-Left shoji screen)
const LIGHT = (() => {
  let lx = -0.71, ly = 0.34, lz = 0.616;
  let len = Math.hypot(lx, ly, lz);
  return [lx / len, ly / len, lz / len];
})();

// Cedar board dimensions (top surface at Z = 0)
const BOARD = {
  xMin: -255, xMax: 275,
  yMin: -195, yMax: 205,
  zBottom: -46
};

// Three blocks of silken tofu (back-to-front painter's order from camera)
const BLOCKS = [
  {
    id: 0,
    cx: 74, cy: 46,
    hx: 65, hy: 52, h: 90,
    theta: -0.115, // radians (~ -6.6 deg)
    bevel: 3.2,
    chipCorner: false
  },
  {
    id: 1,
    cx: -68, cy: 24,
    hx: 62, hy: 49, h: 80,
    theta: 0.145, // radians (~ +8.3 deg)
    bevel: 3.0,
    chipCorner: false
  },
  {
    id: 2,
    cx: 10, cy: -70,
    hx: 59, hy: 47, h: 70,
    theta: -0.22, // radians (~ -12.6 deg)
    bevel: 2.9,
    chipCorner: true // subtle organic depression on one corner
  }
];

function initCamera() {
  let fx = CAM.target[0] - CAM.pos[0];
  let fy = CAM.target[1] - CAM.pos[1];
  let fz = CAM.target[2] - CAM.pos[2];
  let fl = Math.hypot(fx, fy, fz);
  CAM.forward = [fx / fl, fy / fl, fz / fl];

  // World up is [0, 0, 1]; right = normalize(cross(forward, worldUp))
  let rx = CAM.forward[1];
  let ry = -CAM.forward[0];
  let rl = Math.hypot(rx, ry);
  CAM.right = [rx / rl, ry / rl, 0];

  // camUp = cross(right, forward)
  CAM.up = [
    CAM.right[1] * CAM.forward[2] - CAM.right[2] * CAM.forward[1],
    CAM.right[2] * CAM.forward[0] - CAM.right[0] * CAM.forward[2],
    CAM.right[0] * CAM.forward[1] - CAM.right[1] * CAM.forward[0]
  ];
}

function project(x, y, z) {
  let dx = x - CAM.pos[0];
  let dy = y - CAM.pos[1];
  let dz = z - CAM.pos[2];
  let depth = dx * CAM.forward[0] + dy * CAM.forward[1] + dz * CAM.forward[2];
  let px = dx * CAM.right[0] + dy * CAM.right[1] + dz * CAM.right[2];
  let py = dx * CAM.up[0] + dy * CAM.up[1] + dz * CAM.up[2];
  let s = CAM.focal / Math.max(depth, 10);
  return [CAM.cx + px * s, CAM.cy - py * s, depth];
}

// Transform world (x, y, z) into a block's local coordinates
function toBlockLocal(x, y, z, b) {
  let dx = x - b.cx;
  let dy = y - b.cy;
  let c = Math.cos(-b.theta);
  let s = Math.sin(-b.theta);
  return [dx * c - dy * s, dx * s + dy * c, z];
}

// Transform block local (lx, ly, lz) to world coordinates with subtle gravity slump
function toBlockWorld(lx, ly, lz, b) {
  let t = constrain(lz / b.h, 0, 1);
  // Silken tofu bulges almost imperceptibly near the lower third under its own weight
  let slump = 1.0 + 0.016 * Math.sin(Math.PI * Math.pow(1 - t, 0.85));
  let sx = lx * slump;
  let sy = ly * slump;

  // Top surface pillowing and subtle organic ripple
  let topDome = 0;
  if (lz > b.h * 0.7) {
    let nx = lx / b.hx;
    let ny = ly / b.hy;
    let edgeDist = 1 - Math.max(nx * nx, ny * ny);
    topDome = 1.35 * Math.max(0, edgeDist) * (t - 0.7) / 0.3;
    topDome += 0.45 * (noise(lx * 0.03 + b.id * 7, ly * 0.03 + 13) - 0.5) * t;
  }

  // Optional tiny spoon/paddle depression near front corner of block 2
  let indent = 0;
  if (b.chipCorner && lx < -b.hx * 0.55 && ly < -b.hy * 0.45 && lz > b.h * 0.65) {
    let dCorner = Math.hypot((lx + b.hx) / 16, (ly + b.hy) / 16, (lz - b.h) / 14);
    if (dCorner < 1.2) {
      indent = -2.2 * Math.pow(1 - dCorner / 1.2, 2);
    }
  }

  let c = Math.cos(b.theta);
  let s = Math.sin(b.theta);
  return [
    b.cx + sx * c - sy * s,
    b.cy + sx * s + sy * c,
    lz + topDome + indent
  ];
}

// Signed Distance Function to a single rounded tofu block
function blockSDF(x, y, z, b) {
  let [lx, ly, lz] = toBlockLocal(x, y, z, b);
  let r = b.bevel;
  let qx = Math.abs(lx) - (b.hx - r);
  let qy = Math.abs(ly) - (b.hy - r);
  let qz = Math.abs(lz - b.h * 0.5) - (b.h * 0.5 - r);
  let outDist = Math.hypot(Math.max(qx, 0), Math.max(qy, 0), Math.max(qz, 0));
  let inDist = Math.min(Math.max(qx, qy, qz), 0);
  return outDist + inDist - r;
}

// Minimum 2D footprint distance to any tofu block on the board plane
function minFootprintSDF(x, y) {
  let minD = 1e9;
  for (let i = 0; i < BLOCKS.length; i++) {
    let b = BLOCKS[i];
    let [lx, ly] = toBlockLocal(x, y, 0, b);
    let r = 4.0;
    let qx = Math.abs(lx) - (b.hx - r);
    let qy = Math.abs(ly) - (b.hy - r);
    let d = Math.hypot(Math.max(qx, 0), Math.max(qy, 0)) + Math.min(Math.max(qx, qy), 0) - r;
    if (d < minD) minD = d;
  }
  return minD;
}

// Faint shoji paper lattice projection (returns 0 in open pane, up to 1 on soft kumiko grid shadow)
function shojiLattice(x, y, z) {
  // Project along LIGHT onto virtual shoji window plane
  let u = x * LIGHT[1] - y * LIGHT[0] + 18;
  let horizProj = x * LIGHT[0] + y * LIGHT[1];
  let v = z - horizProj * (LIGHT[2] / Math.hypot(LIGHT[0], LIGHT[1])) + 24;

  // Classic Japanese shoji proportions (wide horizontal panes)
  let du = 92;
  let dv = 58;
  let su = Math.sin((Math.PI * u) / du);
  let sv = Math.sin((Math.PI * v) / dv);

  // Soft Gaussian-like diffusion because light passes through translucent washi paper
  let barU = Math.exp(-(su * su) / 0.055);
  let barV = Math.exp(-(sv * sv) / 0.065);

  // Subtle heavier mullions every 3 panes
  let mu = Math.sin((Math.PI * u) / (du * 3));
  let mullion = 0.35 * Math.exp(-(mu * mu) / 0.03);

  return constrain(Math.max(barU, barV * 0.88) + mullion, 0, 1);
}

// Soft ray-marched shadow from the three tofu blocks (0 = lit, 1 = shadowed)
function computeSoftShadow(x, y, z, ignoreBlockId = -1) {
  let shadow = 0;
  let steps = [10, 24, 42, 66, 98, 138];
  for (let s = 0; s < steps.length; s++) {
    let t = steps[s];
    let px = x + LIGHT[0] * t;
    let py = y + LIGHT[1] * t;
    let pz = z + LIGHT[2] * t;
    let minD = 1e9;
    for (let i = 0; i < BLOCKS.length; i++) {
      if (i === ignoreBlockId) continue;
      let d = blockSDF(px, py, pz, BLOCKS[i]);
      if (d < minD) minD = d;
    }
    // Diffused paper light has a very wide, soft penumbra
    let occ = constrain(0.5 - minD / (0.42 * t + 6), 0, 1);
    if (occ > shadow) shadow = occ;
  }
  return shadow;
}

// Ambient occlusion from neighboring blocks and board surface
function computeAO(x, y, z, selfId = -1) {
  let ao = 0;
  // Board contact AO
  if (z >= 0 && z < 34) {
    ao += 0.42 * Math.pow(1 - z / 34, 2.2);
  }
  // Inter-block proximity AO
  for (let i = 0; i < BLOCKS.length; i++) {
    if (i === selfId) continue;
    let d = blockSDF(x, y, z, BLOCKS[i]);
    if (d < 42) {
      ao += 0.38 * Math.pow(constrain(1 - d / 42, 0, 1), 1.8);
    }
  }
  return constrain(ao, 0, 0.85);
}

// Color interpolation & formatting helpers
function mixRGB(c1, c2, t) {
  let u = constrain(t, 0, 1);
  return [
    c1[0] + (c2[0] - c1[0]) * u,
    c1[1] + (c2[1] - c1[1]) * u,
    c1[2] + (c2[2] - c1[2]) * u
  ];
}

function rgbHex(rgb) {
  let r = constrain(Math.round(rgb[0]), 0, 255).toString(16).padStart(2, "0");
  let g = constrain(Math.round(rgb[1]), 0, 255).toString(16).padStart(2, "0");
  let b = constrain(Math.round(rgb[2]), 0, 255).toString(16).padStart(2, "0");
  return `#${r}${g}${b}`;
}

