function draw() {
  translate(-width / 2, -height / 2);

  // High-key rice-paper / warm ivory ground
  background("#f5f2ec");

  // 1. Enveloping twilight-ivory background & faint shoji light in the air
  drawAtmosphereAndBackground();

  // 2. Damp cedar board (watercolor salmon-pink blush + fine perspective wood grain + ghost reflections)
  drawCedarBoard();

  // 3. Thin pooled water / whey halo weeping around the tofu bases
  drawWaterPuddleAndMeniscusOnBoard();

  // 4. Three hyperreal blocks of silken tofu (back-to-front order)
  for (let i = 0; i < BLOCKS.length; i++) {
    drawTofuBlock(BLOCKS[i]);
  }

  // 5. Final unifying veil of diffused lattice light & delicate graphite grain
  drawUnifyingVeil();

  noLoop();
}

// ============================================================================
// 1. ATMOSPHERE & BACKGROUND
// ============================================================================
function drawAtmosphereAndBackground() {
  brush.noStroke();

  // Soft watercolor washes in dusky twilight grey-lavender & warm rice-white
  const bgWashes = [
    { color: "#e4e0e3", alpha: 42, y1: -40, y2: 460 },
    { color: "#ebe7e7", alpha: 38, y1: 120, y2: 560 },
    { color: "#dfdbe0", alpha: 32, y1: -40, y2: 280 },
    { color: "#f6f3ed", alpha: 48, y1: 240, y2: 720 }
  ];

  for (let w of bgWashes) {
    brush.fill(w.color, w.alpha);
    brush.fillBleed(0.22, "out");
    brush.fillTexture(0.28, 0.08);
    brush.beginShape(0.2);
    brush.vertex(-60, w.y1);
    brush.vertex(1260, w.y1 - 30);
    brush.vertex(1260, w.y2 + 40);
    brush.vertex(-60, w.y2);
    brush.endShape(true);
  }
  brush.noFill();

  // Smudged twilight gradation across the upper background wall
  for (let y = 10; y < 520; y += 10) {
    let t = y / 520;
    let baseCol = mixRGB([221, 217, 222], [244, 241, 236], Math.pow(t, 0.75));
    let pts = [];
    for (let x = -20; x <= 1220; x += 60) {
      // Faint memory of the shoji lattice on the back wall
      let u = (x - 600) * 0.52 + (y - 300) * 0.25;
      let v = (y - 260) * 0.65 - (x - 600) * 0.14;
      let lat = Math.max(
        Math.exp(-Math.pow(Math.sin((Math.PI * u) / 96), 2) / 0.08),
        Math.exp(-Math.pow(Math.sin((Math.PI * v) / 62), 2) / 0.08)
      );
      let c = mixRGB(baseCol, [214, 209, 215], lat * 0.22);
      pts.push([x, y + (noise(x * 0.005, y * 0.005) - 0.5) * 8, c]);
    }
    for (let i = 0; i < pts.length - 1; i++) {
      brush.set("smudge_wide", rgbHex(pts[i][2]), 1.3);
      brush.line(pts[i][0], pts[i][1], pts[i + 1][0], pts[i + 1][1]);
    }
  }
}

// ============================================================================
// 2. DAMP CEDAR BOARD (MANAITA)
// ============================================================================
function getCedarGrain(x, y) {
  // Subtle curved planks and earlywood/latewood rings along the X axis
  let warp = 18 * (noise(x * 0.0035 + 10, y * 0.008 + 20) - 0.5);
  let yc = y + warp + 28 * Math.sin(x * 0.0042 + 0.8);
  let ringPhase = Math.abs(yc - 15) * 0.21 + 3.2 * noise(x * 0.006, y * 0.015);
  let cathedral = Math.pow(0.5 + 0.5 * Math.sin(ringPhase), 2.4);
  let fineFiber = noise(x * 0.025, y * 0.35);
  return constrain(cathedral * 0.68 + fineFiber * 0.32, 0, 1);
}

// Computes the ghost reflection of the three bright tofu blocks on the wet cedar surface
function getBoardWetReflection(x, y) {
  let refl = 0;
  for (let i = 0; i < BLOCKS.length; i++) {
    let b = BLOCKS[i];
    // Trace from (x, y, 0) roughly upward and slightly back toward the block
    let [lx, ly] = toBlockLocal(x + 12, y + 14, 0, b);
    let dx = Math.max(Math.abs(lx) - b.hx, 0);
    let dy = Math.max(Math.abs(ly) - b.hy, 0);
    let dist2D = Math.hypot(dx, dy);
    // Reflection stretches toward the viewer (-X, -Y)
    let frontDir = (x - b.cx) * (-0.62) + (y - b.cy) * (-0.78);
    if (frontDir > -20 && dist2D < 95) {
      let falloff = Math.exp(-dist2D / 36) * constrain(1 - Math.max(0, frontDir - 15) / 85, 0, 1);
      refl = Math.max(refl, falloff);
    }
  }
  return refl;
}

function drawCedarBoard() {
  // Project main board corners
  let pTL = project(BOARD.xMin, BOARD.yMax, 0);
  let pTR = project(BOARD.xMax, BOARD.yMax, 0);
  let pBR = project(BOARD.xMax, BOARD.yMin, 0);
  let pBL = project(BOARD.xMin, BOARD.yMin, 0);

  let pTL_b = project(BOARD.xMin, BOARD.yMax, BOARD.zBottom);
  let pBL_b = project(BOARD.xMin, BOARD.yMin, BOARD.zBottom);
  let pBR_b = project(BOARD.xMax, BOARD.yMin, BOARD.zBottom);

  // A. Solid base washes for the three visible faces of the cedar board
  brush.noStroke();

  // Top face base wash (warm ivory-salmon)
  brush.wash("#f1e4dd", 235);
  brush.beginShape(0);
  brush.vertex(pTL[0], pTL[1]);
  brush.vertex(pTR[0], pTR[1]);
  brush.vertex(pBR[0], pBR[1]);
  brush.vertex(pBL[0], pBL[1]);
  brush.endShape(true);

  // Front-Left end-grain face (X = BOARD.xMin)
  brush.wash("#DFC9C0", 240);
  brush.beginShape(0);
  brush.vertex(pTL[0], pTL[1]);
  brush.vertex(pBL[0], pBL[1]);
  brush.vertex(pBL_b[0], pBL_b[1]);
  brush.vertex(pTL_b[0], pTL_b[1]);
  brush.endShape(true);

  // Front-Right long edge face (Y = BOARD.yMin, in twilight shadow)
  brush.wash("#d6c6c4", 240);
  brush.beginShape(0);
  brush.vertex(pBL[0], pBL[1]);
  brush.vertex(pBR[0], pBR[1]);
  brush.vertex(pBR_b[0], pBR_b[1]);
  brush.vertex(pBL_b[0], pBL_b[1]);
  brush.endShape(true);
  brush.noWash();

  // B. Pale watercolor glazes giving the cedar its blush of salmon-pink
  const cedarStrips = [
    { y0: -190, y1: -110, col: "#ebd3c8", alpha: 52 },
    { y0: -125, y1: -35,  col: "#e5c6b9", alpha: 58 },
    { y0: -50,  y1: 45,   col: "#e8cec2", alpha: 55 },
    { y0: 30,   y1: 125,  col: "#e3c2b5", alpha: 50 },
    { y0: 110,  y1: 202,  col: "#edd9d0", alpha: 46 },
    // Damp deeper blush halo right under the three blocks
    { y0: -115, y1: 105,  col: "#dcb8ab", alpha: 44, x0: -150, x1: 165 }
  ];

  for (let st of cedarStrips) {
    let x0 = st.x0 !== undefined ? st.x0 : BOARD.xMin + 4;
    let x1 = st.x1 !== undefined ? st.x1 : BOARD.xMax - 4;
    let c1 = project(x0, st.y0, 0);
    let c2 = project(x1, st.y0, 0);
    let c3 = project(x1, st.y1, 0);
    let c4 = project(x0, st.y1, 0);

    brush.fill(st.col, st.alpha);
    brush.fillBleed(0.16, "out");
    brush.fillTexture(0.32, 0.12);
    brush.beginShape(0.15);
    brush.vertex(c1[0], c1[1]);
    brush.vertex(c2[0], c2[1]);
    brush.vertex(c3[0], c3[1]);
    brush.vertex(c4[0], c4[1]);
    brush.endShape(true);
  }

  // Cool twilight sky reflection glaze on the damp outer margins of the board
  const skyGlazes = [
    { x0: -250, x1: -90, y0: 60, y1: 200, col: "#e2dfe4", alpha: 42 },
    { x0: 80, x1: 270, y0: -190, y1: -40, col: "#ddd8de", alpha: 45 }
  ];
  for (let sg of skyGlazes) {
    let c1 = project(sg.x0, sg.y0, 0);
    let c2 = project(sg.x1, sg.y0, 0);
    let c3 = project(sg.x1, sg.y1, 0);
    let c4 = project(sg.x0, sg.y1, 0);
    brush.fill(sg.col, sg.alpha);
    brush.fillBleed(0.2, "out");
    brush.beginShape(0.1);
    brush.vertex(c1[0], c1[1]);
    brush.vertex(c2[0], c2[1]);
    brush.vertex(c3[0], c3[1]);
    brush.vertex(c4[0], c4[1]);
    brush.endShape(true);
  }
  brush.noFill();

  // C. Detailed 3D surface shading, wood grain, shoji lattice & damp reflections on Top Face
  const lightWood = [245, 234, 227];     // high-key ivory-cedar
  const salmonGrain = [227, 198, 187];   // pale salmon-pink latewood
  const dampWood = [218, 188, 178];      // moisture-darkened cedar around tofu
  const shadowTwilight = [204, 194, 197];// dusky twilight cast shadow on cedar
  const latticeTint = [224, 214, 213];   // faint lattice bar tint

  // Broad smudged tonal pass across the board first
  for (let y = BOARD.yMax - 4; y >= BOARD.yMin + 4; y -= 7) {
    for (let x = BOARD.xMin + 6; x <= BOARD.xMax - 18; x += 18) {
      let xm = x + 9;
      let grain = getCedarGrain(xm, y);
      let dFoot = minFootprintSDF(xm, y);
      let wetness = constrain(1 - dFoot / 95, 0, 1);
      let shadow = computeSoftShadow(xm, y, 0.5);
      let ao = computeAO(xm, y, 0.2);
      let lat = shojiLattice(xm, y, 0) * (1 - shadow * 0.75);
      let refl = getBoardWetReflection(xm, y);

      let col = mixRGB(lightWood, salmonGrain, grain * 0.75);
      col = mixRGB(col, dampWood, wetness * 0.45);
      col = mixRGB(col, latticeTint, lat * 0.36);
      col = mixRGB(col, shadowTwilight, constrain(shadow * 0.68 + ao * 0.65, 0, 0.88));
      // Ghostly reflection of the white tofu blocks on the damp wood
      col = mixRGB(col, [250, 248, 244], refl * 0.48 * (1 - shadow * 0.4));

      let p1 = project(x, y, 0);
      let p2 = project(x + 19, y, 0);
      brush.set("smudge_fine", rgbHex(col), 1.35);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }

  // Crisp, delicate cedar grain fibers and growth-ring cathedrals
  for (let y = BOARD.yMax - 2; y >= BOARD.yMin + 2; y -= 2.4) {
    let x = BOARD.xMin + 4;
    while (x < BOARD.xMax - 8) {
      let step = random(14, 30);
      let xNext = Math.min(x + step, BOARD.xMax - 4);
      let xm = (x + xNext) * 0.5;

      let grain = getCedarGrain(xm, y);
      let dFoot = minFootprintSDF(xm, y);

      // Skip drawing inside the solid footprints of the blocks to save budget
      if (dFoot < -6) {
        x = xNext;
        continue;
      }

      let wetness = constrain(1 - dFoot / 85, 0, 1);
      let shadow = computeSoftShadow(xm, y, 0.5);
      let ao = computeAO(xm, y, 0.2);
      let lat = shojiLattice(xm, y, 0) * (1 - shadow * 0.75);
      let refl = getBoardWetReflection(xm, y);

      let col = mixRGB(lightWood, salmonGrain, Math.pow(grain, 0.85));
      col = mixRGB(col, dampWood, wetness * 0.5);
      col = mixRGB(col, latticeTint, lat * 0.38);
      col = mixRGB(col, shadowTwilight, constrain(shadow * 0.72 + ao * 0.7, 0, 0.92));
      col = mixRGB(col, [252, 250, 246], refl * 0.55);

      let yWobble = 0.6 * Math.sin(xm * 0.02 + y * 0.05);
      let p1 = project(x, y, 0);
      let p2 = project(xNext, y + yWobble, 0);

      let brushName = grain > 0.55 ? "cedar_fiber" : "soft_graphite";
      let w = map(grain, 0, 1, 0.65, 1.15);
      brush.set(brushName, rgbHex(col), w);
      brush.line(p1[0], p1[1], p2[0], p2[1]);

      x = xNext;
    }
  }

  // D. Front-Left End-Grain Face (X = BOARD.xMin)
  for (let z = 0; z >= BOARD.zBottom; z -= 2.2) {
    for (let y = BOARD.yMax; y > BOARD.yMin; y -= 14) {
      let yNext = Math.max(y - 14, BOARD.yMin);
      let ym = (y + yNext) * 0.5;
      // Curved end-grain growth rings dipping toward center
      let ringDist = Math.hypot((ym - 15) * 0.22, (z + 62) * 0.55);
      let ring = 0.5 + 0.5 * Math.sin(ringDist);
      let lat = shojiLattice(BOARD.xMin, ym, z);
      let dampBottom = constrain(1 - (z - BOARD.zBottom) / 14, 0, 1);

      let col = mixRGB([230, 212, 204], [208, 184, 175], ring * 0.7 + dampBottom * 0.3);
      col = mixRGB(col, [198, 186, 188], lat * 0.28);

      let p1 = project(BOARD.xMin, y, z);
      let p2 = project(BOARD.xMin, yNext, z);
      brush.set("cedar_fiber", rgbHex(col), 1.05);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }
  // Vertical saw/plane micro-texture on the end-grain
  for (let y = BOARD.yMax - 4; y > BOARD.yMin + 4; y -= 5.5) {
    let pTop = project(BOARD.xMin, y, 0);
    let pBot = project(BOARD.xMin, y, BOARD.zBottom);
    let shade = noise(y * 0.08) > 0.5 ? "#c9b2a9" : "#dec7be";
    brush.set("2H", shade, 0.45);
    brush.line(pTop[0], pTop[1], pBot[0], pBot[1]);
  }

  // E. Front-Right Long Face (Y = BOARD.yMin, turned away into twilight shadow)
  for (let z = 0; z >= BOARD.zBottom; z -= 2.2) {
    for (let x = BOARD.xMin; x < BOARD.xMax; x += 18) {
      let xNext = Math.min(x + 18, BOARD.xMax);
      let xm = (x + xNext) * 0.5;
      let grain = 0.5 + 0.5 * Math.sin((z + 8 * Math.sin(xm * 0.008)) * 0.38);
      let shadow = computeSoftShadow(xm, BOARD.yMin, z);
      let lat = shojiLattice(xm, BOARD.yMin, z) * (1 - shadow * 0.7);

      let col = mixRGB([218, 204, 202], [198, 183, 183], grain * 0.65);
      col = mixRGB(col, [186, 176, 180], shadow * 0.45 + lat * 0.22);

      let p1 = project(x, BOARD.yMin, z);
      let p2 = project(xNext, BOARD.yMin, z);
      brush.set("cedar_fiber", rgbHex(col), 1.1);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }

  // Damp chamfer highlight along the front-top edges of the cedar board
  for (let x = BOARD.xMin; x < BOARD.xMax; x += 12) {
    let p1 = project(x, BOARD.yMin, 0);
    let p2 = project(x + 12, BOARD.yMin, 0);
    let sh = computeSoftShadow(x + 6, BOARD.yMin, 0.5);
    let col = mixRGB([249, 245, 240], [222, 214, 214], sh * 0.75);
    brush.set("soft_graphite", rgbHex(col), 1.1);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
  for (let y = BOARD.yMin; y < BOARD.yMax; y += 12) {
    let p1 = project(BOARD.xMin, y, 0);
    let p2 = project(BOARD.xMin, y + 12, 0);
    brush.set("soft_graphite", "#f7f3ed", 1.15);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Subtle shadow beneath the bottom of the board on the table surface
  for (let d = 1; d <= 14; d += 2.2) {
    let cL = project(BOARD.xMin - d * 0.4, BOARD.yMax, BOARD.zBottom);
    let cM = project(BOARD.xMin - d * 0.3, BOARD.yMin - d * 0.5, BOARD.zBottom);
    let cR = project(BOARD.xMax, BOARD.yMin - d * 0.6, BOARD.zBottom);
    let col = mixRGB([176, 166, 171], [238, 234, 230], d / 14);
    brush.set("smudge_fine", rgbHex(col), 1.2);
    brush.line(cL[0], cL[1], cM[0], cM[1]);
    brush.line(cM[0], cM[1], cR[0], cR[1]);
  }
}

// ============================================================================
// 3. WATER PUDDLE / WHEY FILM ON THE DAMP CEDAR
// ============================================================================
function drawWaterPuddleAndMeniscusOnBoard() {
  // Trace organic water film edge around the cluster of blocks
  for (let y = BOARD.yMin + 15; y <= BOARD.yMax - 15; y += 2.5) {
    for (let x = BOARD.xMin + 20; x <= BOARD.xMax - 20; x += 2.5) {
      let dFoot = minFootprintSDF(x, y);
      if (dFoot < 2 || dFoot > 62) continue;

      let ang = Math.atan2(y, x - 10);
      let puddleLimit = 28 + 18 * noise(x * 0.018 + 5, y * 0.018 + 9) + 6 * Math.sin(ang * 3);
      let rimDist = Math.abs(dFoot - puddleLimit);

      if (rimDist < 1.8) {
        let p = project(x, y, 0.1);
        let pNext = project(x + 2.2, y - 1.4, 0.1);
        let sh = computeSoftShadow(x, y, 0.5);

        // Outer refraction line of the thin water film
        let refractCol = mixRGB([212, 192, 185], [198, 186, 188], sh);
        brush.set("2H", rgbHex(refractCol), 0.5);
        brush.line(p[0], p[1], pNext[0], pNext[1]);

        // Intermittent specular glint on the curved water rim facing the window
        if (sh < 0.35 && noise(x * 0.12, y * 0.12) > 0.52) {
          brush.set("silk_gloss", "#fdfcf9", 0.75);
          brush.line(p[0], p[1] - 0.8, pNext[0], pNext[1] - 0.8);
        }
      }
    }
  }
}

// ============================================================================
// 4. HYPERREAL SILKEN TOFU BLOCKS
// ============================================================================
// Evaluates the exact high-key surface color of a tofu block at local (lx, ly, lz)
function shadeTofuPoint(lx, ly, lz, nx, ny, nz, b) {
  let [wx, wy, wz] = toBlockWorld(lx, ly, lz, b);

  // Rotate normal by block's theta
  let c = Math.cos(b.theta);
  let s = Math.sin(b.theta);
  let wnx = nx * c - ny * s;
  let wny = nx * s + ny * c;
  let wnz = nz;

  // Diffuse lighting from the paper window
  let ndotl = wnx * LIGHT[0] + wny * LIGHT[1] + wnz * LIGHT[2];
  let wrapDiff = constrain((ndotl + 0.45) / 1.45, 0, 1);

  // Cast shadow from other blocks & ambient occlusion
  let castSh = computeSoftShadow(wx + wnx * 1.5, wy + wny * 1.5, wz + wnz * 1.5, b.id);
  let ao = computeAO(wx, wy, wz, b.id);

  // Faint shoji lattice falling across the tofu
  let lat = shojiLattice(wx, wy, wz) * (1 - castSh * 0.8) * constrain(ndotl + 0.35, 0, 1);

  // Subsurface scattering (silken tofu glows warm ivory near top & lit edges)
  let topProximity = constrain(1 - (b.h - lz) / 26, 0, 1);
  let edgeProximity = constrain(
    1 - Math.min(b.hx - Math.abs(lx), b.hy - Math.abs(ly)) / 22,
    0,
    1
  );
  let sss = constrain(topProximity * 0.6 + edgeProximity * 0.45, 0, 1) * (1 - castSh * 0.65);

  // Warm salmon-pink bounce light reflected upward from the damp cedar board onto vertical walls
  let boardBounce = (1 - Math.abs(wnz)) * constrain(1 - lz / 38, 0, 1) * 0.45;

  // High-key palette definitions
  const litIvory = [251, 249, 243];      // rice-white / warm ivory
  const sssCream = [254, 252, 245];      // translucent curd glow
  const midWarmGrey = [237, 233, 228];   // faintest warm grey
  const twilightShadow = [216, 211, 213];// dusky twilight cool-warm shadow
  const cedarBounceCol = [235, 221, 216];// blush bounce from board
  const latticeGrey = [235, 230, 227];   // shoji grid bar tint
  const deepCrevice = [184, 176, 180];   // contact AO (still high-key)

  // Combine lighting terms
  let effLight = wrapDiff * (1 - castSh * 0.52);
  let col;
  if (effLight > 0.5) {
    col = mixRGB(midWarmGrey, litIvory, (effLight - 0.5) * 2.0);
  } else {
    col = mixRGB(twilightShadow, midWarmGrey, effLight * 2.0);
  }

  // Add subsurface glow
  col = mixRGB(col, sssCream, sss * 0.52);
  // Add warm cedar bounce on lower walls
  col = mixRGB(col, cedarBounceCol, boardBounce);
  // Apply faint shoji lattice
  col = mixRGB(col, latticeGrey, lat * 0.34);
  // Apply subtle organic curd mottling
  let curdNoise = noise(lx * 0.08 + b.id * 11, ly * 0.08, lz * 0.08);
  col = mixRGB(col, [246, 243, 238], (curdNoise - 0.5) * 0.14);
  // Apply ambient occlusion near base & between blocks
  col = mixRGB(col, deepCrevice, ao * 0.68);

  return col;
}

function drawTofuBlock(b) {
  let hx = b.hx;
  let hy = b.hy;
  let h = b.h;
  let bev = b.bevel;

  // --------------------------------------------------------------------------
  // A. Base Contact Shadow & Dark Refraction Crevice on the Cedar Board
  // --------------------------------------------------------------------------
  // Front-Left bottom edge (lx = -hx, ly in [-hy, hy])
  for (let ly = -hy; ly < hy; ly += 3.5) {
    let w1 = toBlockWorld(-hx - 0.8, ly, 0, b);
    let w2 = toBlockWorld(-hx - 0.8, Math.min(ly + 4, hy), 0, b);
    let p1 = project(w1[0], w1[1], 0);
    let p2 = project(w2[0], w2[1], 0);
    brush.set("soft_graphite", "#9e9397", 1.35);
    brush.line(p1[0], p1[1] + 1.2, p2[0], p2[1] + 1.2);
  }
  // Front-Right bottom edge (ly = -hy, lx in [-hx, hx])
  for (let lx = -hx; lx < hx; lx += 3.5) {
    let w1 = toBlockWorld(lx, -hy - 0.8, 0, b);
    let w2 = toBlockWorld(Math.min(lx + 4, hx), -hy - 0.8, 0, b);
    let p1 = project(w1[0], w1[1], 0);
    let p2 = project(w2[0], w2[1], 0);
    brush.set("soft_graphite", "#968b90", 1.45);
    brush.line(p1[0], p1[1] + 1.4, p2[0], p2[1] + 1.4);
  }

  // --------------------------------------------------------------------------
  // B. Opaque Base Washes for the Three Visible Faces (Prevents Board Bleed)
  // --------------------------------------------------------------------------
  brush.noStroke();

  // 1. Front-Left Face (lx = -hx)
  brush.wash("#efeae2", 248);
  brush.beginShape(0);
  for (let ly = -hy; ly <= hy; ly += 12) {
    let p = project(...toBlockWorld(-hx, ly, 0, b));
    brush.vertex(p[0], p[1]);
  }
  for (let ly = hy; ly >= -hy; ly -= 12) {
    let p = project(...toBlockWorld(-hx, ly, h, b));
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);

  // 2. Front-Right Face (ly = -hy, in soft twilight shadow)
  brush.wash("#ded9d8", 248);
  brush.beginShape(0);
  for (let lx = -hx; lx <= hx; lx += 12) {
    let p = project(...toBlockWorld(lx, -hy, 0, b));
    brush.vertex(p[0], p[1]);
  }
  for (let lx = hx; lx >= -hx; lx -= 12) {
    let p = project(...toBlockWorld(lx, -hy, h, b));
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);

  // 3. Top Face (lz = h, brightest rice-white)
  brush.wash("#f9f7f1", 250);
  brush.beginShape(0);
  let topCorners = [
    [-hx, -hy], [hx, -hy], [hx, hy], [-hx, hy]
  ];
  for (let k = 0; k < 4; k++) {
    let c0 = topCorners[k];
    let c1 = topCorners[(k + 1) % 4];
    for (let u = 0; u < 1; u += 0.2) {
      let lx = lerp(c0[0], c1[0], u);
      let ly = lerp(c0[1], c1[1], u);
      let p = project(...toBlockWorld(lx, ly, h, b));
      brush.vertex(p[0], p[1]);
    }
  }
  brush.endShape(true);
  brush.noWash();

  // --------------------------------------------------------------------------
  // C. Smudged Graphite & Tonal Gradation on Front-Left Face (lx = -hx)
  // --------------------------------------------------------------------------
  // Wide smudge pass for seamless gradation
  for (let lz = 2; lz <= h - bev; lz += 5.5) {
    for (let ly = -hy + bev; ly < hy - bev; ly += 14) {
      let lyNext = Math.min(ly + 15, hy - bev);
      let col = shadeTofuPoint(-hx, (ly + lyNext) * 0.5, lz, -1, 0, 0, b);
      let p1 = project(...toBlockWorld(-hx, ly, lz, b));
      let p2 = project(...toBlockWorld(-hx, lyNext, lz, b));
      brush.set("smudge_fine", rgbHex(col), 1.3);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }
  // Fine soft-graphite pass capturing subtle knife-cut horizontal & vertical grain
  for (let lz = 1.2; lz <= h - bev * 0.6; lz += 1.65) {
    for (let ly = -hy + bev * 0.6; ly < hy - bev * 0.6; ly += 10) {
      let lyNext = Math.min(ly + 10.5, hy - bev * 0.6);
      let col = shadeTofuPoint(-hx, (ly + lyNext) * 0.5, lz, -1, 0, 0, b);
      let p1 = project(...toBlockWorld(-hx, ly, lz, b));
      let p2 = project(...toBlockWorld(-hx, lyNext, lz, b));
      brush.set("soft_graphite", rgbHex(col), 0.95);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }

  // --------------------------------------------------------------------------
  // D. Smudged Graphite & Tonal Gradation on Front-Right Face (ly = -hy)
  // --------------------------------------------------------------------------
  for (let lz = 2; lz <= h - bev; lz += 5.5) {
    for (let lx = -hx + bev; lx < hx - bev; lx += 14) {
      let lxNext = Math.min(lx + 15, hx - bev);
      let col = shadeTofuPoint((lx + lxNext) * 0.5, -hy, lz, 0, -1, 0, b);
      let p1 = project(...toBlockWorld(lx, -hy, lz, b));
      let p2 = project(...toBlockWorld(lxNext, -hy, lz, b));
      brush.set("smudge_fine", rgbHex(col), 1.3);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }
  for (let lz = 1.2; lz <= h - bev * 0.6; lz += 1.65) {
    for (let lx = -hx + bev * 0.6; lx < hx - bev * 0.6; lx += 10) {
      let lxNext = Math.min(lx + 10.5, hx - bev * 0.6);
      let col = shadeTofuPoint((lx + lxNext) * 0.5, -hy, lz, 0, -1, 0, b);
      let p1 = project(...toBlockWorld(lx, -hy, lz, b));
      let p2 = project(...toBlockWorld(lxNext, -hy, lz, b));
      brush.set("soft_graphite", rgbHex(col), 0.95);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }

  // --------------------------------------------------------------------------
  // E. Top Face (lz = h): Luminous Rice-White Skin, Lattice & Coagulation Ripples
  // --------------------------------------------------------------------------
  for (let ly = -hy + bev * 0.5; ly <= hy - bev * 0.5; ly += 5.0) {
    for (let lx = -hx + bev * 0.5; lx < hx - bev * 0.5; lx += 14) {
      let lxNext = Math.min(lx + 15, hx - bev * 0.5);
      let lxm = (lx + lxNext) * 0.5;
      let col = shadeTofuPoint(lxm, ly, h, 0, 0, 1, b);
      let p1 = project(...toBlockWorld(lx, ly, h, b));
      let p2 = project(...toBlockWorld(lxNext, ly, h, b));
      brush.set("smudge_fine", rgbHex(col), 1.35);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }

  for (let ly = -hy + bev * 0.4; ly <= hy - bev * 0.4; ly += 1.55) {
    for (let lx = -hx + bev * 0.4; lx < hx - bev * 0.4; lx += 10) {
      let lxNext = Math.min(lx + 10.5, hx - bev * 0.4);
      let lxm = (lx + lxNext) * 0.5;

      // Delicate surface ripple on the silken coagulation skin
      let skinWave = Math.sin(lxm * 0.14 + ly * 0.09 + noise(lxm * 0.04, ly * 0.04) * 3.5);
      let nx = 0.06 * skinWave;
      let ny = 0.05 * Math.cos(lxm * 0.08 - ly * 0.12);
      let col = shadeTofuPoint(lxm, ly, h, nx, ny, 0.99, b);

      let p1 = project(...toBlockWorld(lx, ly, h, b));
      let p2 = project(...toBlockWorld(lxNext, ly, h, b));
      brush.set("soft_graphite", rgbHex(col), 0.92);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }

  // --------------------------------------------------------------------------
  // F. Rounded Bevels & Trembling Glossy Skin Highlights
  // --------------------------------------------------------------------------
  // 1. Vertical Front Corner Bevel (lx = -hx, ly = -hy)
  for (let a = 0; a <= 1; a += 0.25) {
    let ang = Math.PI + a * (Math.PI * 0.5); // from -X to -Y
    let nx = Math.cos(ang);
    let ny = Math.sin(ang);
    let bx = -hx + bev * (1 + nx);
    let by = -hy + bev * (1 + ny);
    for (let lz = 2; lz < h - bev; lz += 6) {
      let col = shadeTofuPoint(bx, by, lz + 3, nx, ny, 0, b);
      // Slight glossy catch-light along the wet vertical corner ridge
      if (Math.abs(a - 0.35) < 0.2) {
        col = mixRGB(col, [252, 250, 246], 0.38);
      }
      let p1 = project(...toBlockWorld(bx, by, lz, b));
      let p2 = project(...toBlockWorld(bx, by, Math.min(lz + 6.5, h - bev), b));
      brush.set("soft_graphite", rgbHex(col), 1.0);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }

  // 2. Top-Front-Left Bevel (lx = -hx, lz = h): Direct window light specular ridge!
  for (let ly = -hy + 2; ly < hy - 2; ly += 3.2) {
    let lyNext = Math.min(ly + 3.5, hy - 2);
    let lym = (ly + lyNext) * 0.5;
    let wobble = 0.45 * (noise(lym * 0.15 + b.id * 9) - 0.5);
    let p1 = project(...toBlockWorld(-hx + 1.1, ly, h - 0.6 + wobble, b));
    let p2 = project(...toBlockWorld(-hx + 1.1, lyNext, h - 0.6 + wobble, b));

    let [wx, wy, wz] = toBlockWorld(-hx, lym, h, b);
    let lat = shojiLattice(wx, wy, wz);
    let sh = computeSoftShadow(wx, wy, wz, b.id);

    // Trembling glossy highlight on the wet rounded skin
    if (sh < 0.45 && noise(lym * 0.12, b.id * 5) > 0.18) {
      let glossCol = mixRGB([255, 255, 255], [245, 242, 238], lat * 0.45);
      let weight = map(noise(lym * 0.22 + b.id), 0, 1, 0.7, 1.45);
      brush.set("silk_gloss", rgbHex(glossCol), weight);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }

  // 3. Top-Front-Right Bevel (ly = -hy, lz = h): Soft translucent rim highlight
  for (let lx = -hx + 2; lx < hx - 2; lx += 3.2) {
    let lxNext = Math.min(lx + 3.5, hx - 2);
    let lxm = (lx + lxNext) * 0.5;
    let wobble = 0.45 * (noise(lxm * 0.15 + b.id * 17) - 0.5);
    let p1 = project(...toBlockWorld(lx, -hy + 1.1, h - 0.6 + wobble, b));
    let p2 = project(...toBlockWorld(lxNext, -hy + 1.1, h - 0.6 + wobble, b));

    let [wx, wy, wz] = toBlockWorld(lxm, -hy, h, b);
    let sh = computeSoftShadow(wx, wy, wz, b.id);
    if (sh < 0.5 && noise(lxm * 0.14 + 3, b.id) > 0.22) {
      let col = mixRGB([254, 253, 250], [238, 234, 232], sh * 0.6);
      brush.set("silk_gloss", rgbHex(col), 0.95);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }

  // 4. Back-Left & Back-Right Top Rim Whisper Highlights
  for (let lx = -hx + 4; lx < hx - 4; lx += 5) {
    let p1 = project(...toBlockWorld(lx, hy - 0.8, h - 0.4, b));
    let p2 = project(...toBlockWorld(lx + 5, hy - 0.8, h - 0.4, b));
    brush.set("soft_graphite", "#fcfbf7", 0.85);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
  for (let ly = -hy + 4; ly < hy - 4; ly += 5) {
    let p1 = project(...toBlockWorld(hx - 0.8, ly, h - 0.4, b));
    let p2 = project(...toBlockWorld(hx - 0.8, ly + 5, h - 0.4, b));
    brush.set("soft_graphite", "#f2eee8", 0.8);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // --------------------------------------------------------------------------
  // G. Tiny Pores, Micro-Bubbles & Imperfections on the Cut Tofu Faces
  // --------------------------------------------------------------------------
  drawTofuPoresAndDetails(b);

  // --------------------------------------------------------------------------
  // H. Wet Capillary Meniscus along the Bottom Base of the Tofu Block
  // --------------------------------------------------------------------------
  // Front-Left base meniscus
  for (let ly = -hy + 2; ly < hy - 2; ly += 2.8) {
    let [wx, wy, wz] = toBlockWorld(-hx - 0.4, ly, 1.4, b);
    let sh = computeSoftShadow(wx, wy, wz, b.id);
    let p1 = project(wx, wy, wz);
    let p2 = project(...toBlockWorld(-hx - 0.4, ly + 2.4, 1.4, b));

    // Translucent water fillet
    let filletCol = mixRGB([212, 204, 203], [192, 184, 186], sh);
    brush.set("2H", rgbHex(filletCol), 0.55);
    brush.line(p1[0], p1[1], p2[0], p2[1]);

    // Tiny wet specular bead on the meniscus
    if (sh < 0.4 && noise(ly * 0.25 + b.id * 11) > 0.42) {
      brush.set("silk_gloss", "#ffffff", 0.85);
      brush.line(p1[0], p1[1] - 0.9, p2[0], p2[1] - 0.9);
    }
  }

  // Front-Right base meniscus
  for (let lx = -hx + 2; lx < hx - 2; lx += 2.8) {
    let [wx, wy, wz] = toBlockWorld(lx, -hy - 0.4, 1.4, b);
    let sh = computeSoftShadow(wx, wy, wz, b.id);
    let p1 = project(wx, wy, wz);
    let p2 = project(...toBlockWorld(lx + 2.4, -hy - 0.4, 1.4, b));

    let filletCol = mixRGB([200, 192, 194], [182, 174, 178], sh);
    brush.set("2H", rgbHex(filletCol), 0.55);
    brush.line(p1[0], p1[1], p2[0], p2[1]);

    if (sh < 0.5 && noise(lx * 0.28 + b.id * 19) > 0.52) {
      brush.set("silk_gloss", "#faf8f5", 0.7);
      brush.line(p1[0], p1[1] - 0.8, p2[0], p2[1] - 0.8);
    }
  }
}

function drawTofuPoresAndDetails(b) {
  let hx = b.hx;
  let hy = b.hy;
  let h = b.h;

  // 1. Pores on Front-Left Face (lx = -hx)
  let numPoresFL = 135;
  for (let i = 0; i < numPoresFL; i++) {
    let ly = random(-hy + 4, hy - 4);
    let lz = random(3, h - 4);
    // Cluster pores organically using Perlin noise
    let density = noise(ly * 0.06 + b.id * 20, lz * 0.06);
    if (density < 0.42 && random() < 0.75) continue;

    let [wx, wy, wz] = toBlockWorld(-hx, ly, lz, b);
    let p = project(wx, wy, wz);
    let poreSize = random(0.7, 2.2) * (density > 0.62 ? 1.35 : 0.85);

    let baseCol = shadeTofuPoint(-hx, ly, lz, -1, 0, 0, b);
    let dimpleShadow = mixRGB(baseCol, [186, 179, 181], 0.42);
    let dimpleHighlight = mixRGB(baseCol, [255, 255, 255], 0.78);

    // Upper-left shadow crescent of the tiny pore
    brush.set("2H", rgbHex(dimpleShadow), 0.42);
    brush.line(p[0] - poreSize * 0.5, p[1] - poreSize * 0.3, p[0] + poreSize * 0.5, p[1] - poreSize * 0.1);

    // Lower-right moist rim glint of the pore
    brush.set("silk_gloss", rgbHex(dimpleHighlight), 0.48);
    brush.line(p[0] - poreSize * 0.3, p[1] + poreSize * 0.5, p[0] + poreSize * 0.6, p[1] + poreSize * 0.3);
  }

  // 2. Pores on Front-Right Face (ly = -hy, shadowed side)
  let numPoresFR = 125;
  for (let i = 0; i < numPoresFR; i++) {
    let lx = random(-hx + 4, hx - 4);
    let lz = random(3, h - 4);
    let density = noise(lx * 0.06 + b.id * 33, lz * 0.06 + 10);
    if (density < 0.43 && random() < 0.75) continue;

    let [wx, wy, wz] = toBlockWorld(lx, -hy, lz, b);
    let p = project(wx, wy, wz);
    let poreSize = random(0.7, 2.1) * (density > 0.6 ? 1.3 : 0.85);

    let baseCol = shadeTofuPoint(lx, -hy, lz, 0, -1, 0, b);
    let dimpleShadow = mixRGB(baseCol, [172, 165, 169], 0.45);
    let dimpleHighlight = mixRGB(baseCol, [248, 245, 242], 0.62);

    brush.set("2H", rgbHex(dimpleShadow), 0.44);
    brush.line(p[0] - poreSize * 0.5, p[1] - poreSize * 0.3, p[0] + poreSize * 0.5, p[1] - poreSize * 0.1);

    brush.set("soft_graphite", rgbHex(dimpleHighlight), 0.5);
    brush.line(p[0] - poreSize * 0.2, p[1] + poreSize * 0.5, p[0] + poreSize * 0.6, p[1] + poreSize * 0.3);
  }

  // 3. Tiny Pinpoint Pores & Glossy Dew Glints on Top Face (lz = h)
  let numPoresTop = 85;
  for (let i = 0; i < numPoresTop; i++) {
    let lx = random(-hx + 6, hx - 6);
    let ly = random(-hy + 6, hy - 6);
    if (noise(lx * 0.07, ly * 0.07 + b.id * 15) < 0.46) continue;

    let [wx, wy, wz] = toBlockWorld(lx, ly, h, b);
    let p = project(wx, wy, wz);
    let s = random(0.6, 1.6);

    brush.set("2H", "#dfd9d3", 0.38);
    brush.line(p[0] - s * 0.5, p[1] - s * 0.2, p[0] + s * 0.4, p[1]);

    brush.set("silk_gloss", "#ffffff", 0.52);
    brush.line(p[0] - s * 0.2, p[1] + s * 0.4, p[0] + s * 0.6, p[1] + s * 0.2);
  }

  // 4. Delicate vertical wire/knife striation marks on the cut walls
  for (let k = 0; k < 14; k++) {
    let ly = random(-hy + 8, hy - 8);
    let zStart = random(6, h * 0.45);
    let zEnd = zStart + random(16, 38);
    let p1 = project(...toBlockWorld(-hx, ly, zStart, b));
    let p2 = project(...toBlockWorld(-hx, ly, Math.min(zEnd, h - 5), b));
    let col = shadeTofuPoint(-hx, ly, (zStart + zEnd) * 0.5, -1, 0, 0, b);
    let striaCol = mixRGB(col, [215, 209, 207], 0.22);
    brush.set("2H", rgbHex(striaCol), 0.35);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // 5. If this block has the subtle chipped/indented front corner, render its wet curd facets
  if (b.chipCorner) {
    for (let u = 0; u <= 1; u += 0.2) {
      let lx = lerp(-hx, -hx * 0.68, u);
      let ly = lerp(-hy * 0.65, -hy, u);
      let p1 = project(...toBlockWorld(lx, ly, h - 1.5, b));
      let p2 = project(...toBlockWorld(lx + 3.5, ly + 2.5, h - 3.2, b));
      brush.set("2H", "#d4cdd0", 0.42);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
      brush.set("silk_gloss", "#ffffff", 0.65);
      brush.line(p1[0] + 0.6, p1[1] + 0.8, p2[0] + 0.6, p2[1] + 0.8);
    }
  }
}

