// Scalloped outer radius of the giant tomato slice
function outerRadius(deg) {
  let base = 1438;
  let lobe = 0;
  for (let c of CHAMBERS) {
    let mid = (c.a0 + c.a1) * 0.5;
    let halfSpan = (c.a1 - c.a0) * 0.5;
    let d = abs(deg - mid);
    if (d < halfSpan + 4) {
      let norm = constrain(1 - d / (halfSpan + 4), 0, 1);
      lobe += 28 * sin(norm * 90);
    }
  }
  for (let s of SEPTA) {
    let d = abs(deg - s.mid);
    if (d < 6) {
      lobe -= 16 * cos((d / 6) * 90);
    }
  }
  let n = (noise(deg * 0.08 + 100) - 0.5) * 18;
  return base + lobe + n;
}

// Core outer boundary (star-like columella that flares into septa and placental lobes)
function coreRadius(deg) {
  let base = 345;
  let flare = 0;
  for (let s of SEPTA) {
    let d = abs(deg - s.mid);
    if (d < 8) {
      flare += 48 * pow(cos((d / 8) * 90), 1.6);
    }
  }
  for (let c of CHAMBERS) {
    let mid = (c.a0 + c.a1) * 0.5;
    let d = abs(deg - mid);
    if (d < 6.5) {
      flare += 32 * cos((d / 6.5) * 90);
    }
  }
  let n = (noise(deg * 0.12 + 30) - 0.5) * 20;
  return base + flare + n;
}

// Polar to Cartesian helper around tomato center (CX, CY)
function tPt(r, deg) {
  let radTwist = sin(r * 0.18 + deg * 2.0) * 0.35;
  let a = deg + radTwist;
  return [CX + r * cos(a), CY + r * sin(a)];
}

// Safe shape wrapper using beginShape/vertex/endShape
function drawPoly(pts, curvature = 0.12, closed = true) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closed);
}

// Safe spline wrapper avoiding duplicate consecutive points
function safeSpline(pts, curvature = 0.5) {
  if (!pts || pts.length < 2) return;
  let clean = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    let prev = clean[clean.length - 1];
    let dx = pts[i][0] - prev[0];
    let dy = pts[i][1] - prev[1];
    if (dx * dx + dy * dy > 1.0) {
      clean.push(pts[i]);
    }
  }
  if (clean.length >= 2) {
    brush.spline(clean, curvature);
  }
}

// Build a curved polar patch polygon between r0..r1 and a0..a1
function buildArcPatch(r0, r1, a0, a1, stepsA = 10, stepsR = 4, jitter = 0) {
  let pts = [];
  for (let i = 0; i <= stepsA; i++) {
    let t = i / stepsA;
    let a = lerp(a0, a1, t);
    let jr = jitter ? (noise(a * 0.2, r0 * 0.02) - 0.5) * jitter : 0;
    pts.push(tPt(r0 + jr, a));
  }
  for (let i = 1; i < stepsR; i++) {
    let t = i / stepsR;
    let r = lerp(r0, r1, t);
    let ja = jitter ? (noise(r * 0.02, a1 * 0.2) - 0.5) * (jitter * 0.04) : 0;
    pts.push(tPt(r, a1 + ja));
  }
  for (let i = stepsA; i >= 0; i--) {
    let t = i / stepsA;
    let a = lerp(a0, a1, t);
    let jr = jitter ? (noise(a * 0.2 + 50, r1 * 0.02) - 0.5) * jitter : 0;
    pts.push(tPt(r1 + jr, a));
  }
  for (let i = stepsR - 1; i >= 1; i--) {
    let t = i / stepsR;
    let r = lerp(r0, r1, t);
    let ja = jitter ? (noise(r * 0.02 + 50, a0 * 0.2) - 0.5) * (jitter * 0.04) : 0;
    pts.push(tPt(r, a0 + ja));
  }
  return pts;
}

// Render a bold 1960s flat marker swath with slight edge pooling and directional grain
function renderMarkerSwath(pts, fillCol, alpha, strokeCol, hatchAngle, hatchSpacing = 13) {
  brush.noStroke();
  brush.noFill();
  brush.wash(fillCol, alpha);
  brush.hatchStyle("chiselMarker", strokeCol, 0.9);
  brush.hatch(hatchSpacing, hatchAngle, { rand: 0.015, continuous: true });
  drawPoly(pts, 0.08, true);
  brush.noHatch();
  brush.noWash();

  // Confident marker edge pass along the swath boundary
  brush.set("chiselMarker", strokeCol, 0.75);
  let edgeSlice = pts.slice(0, floor(pts.length * 0.52));
  safeSpline(edgeSlice, 0.25);
}

// Compute organic chamber boundary polygon
function getChamberPoints(ch, radialOffset = 0, angularInset = 0) {
  let a0 = ch.a0 + angularInset;
  let a1 = ch.a1 - angularInset;
  let midA = (a0 + a1) * 0.5;
  let span = a1 - a0;

  let pts = [];
  let N = 28;

  // Outer wall (with bilobed inward scallop at the middle of the chamber)
  for (let i = 0; i <= N; i++) {
    let t = i / N;
    let a = lerp(a0, a1, t);
    // Rounded corners near a0 and a1
    let edgeRound = sin(t * 180);
    // Bilobed dip in the middle of the outer wall
    let midDip = exp(-pow((t - 0.5) / 0.16, 2)) * 68;
    let rOut = 1158 + radialOffset - (1 - pow(edgeRound, 0.45)) * 185 - midDip;
    rOut += (noise(a * 0.25, ch.id * 10) - 0.5) * 18;
    pts.push(tPt(rOut, a));
  }

  // Right wall going inward along septum
  let M = 14;
  for (let i = 1; i < M; i++) {
    let t = i / M;
    let r = lerp(970 + radialOffset, 395 - radialOffset, t);
    // Bulge slightly wider in the middle radius
    let belly = sin(t * 180) * 1.4;
    let a = a1 + belly - t * 1.2 + (noise(r * 0.02, ch.id * 20) - 0.5) * 0.7;
    pts.push(tPt(r, a));
  }

  // Inner wall (wrapping around the core / placental base)
  let K = 16;
  for (let i = K; i >= 0; i--) {
    let t = i / K;
    let a = lerp(a0 + 1.2, a1 - 1.2, t);
    let rIn = coreRadius(a) + 22 - radialOffset + sin(t * 180) * 28;
    pts.push(tPt(rIn, a));
  }

  // Left wall going outward along septum
  for (let i = M - 1; i >= 1; i--) {
    let t = i / M;
    let r = lerp(970 + radialOffset, 395 - radialOffset, t);
    let belly = sin(t * 180) * 1.4;
    let a = a0 - belly + t * 1.2 + (noise(r * 0.02 + 9, ch.id * 20) - 0.5) * 0.7;
    pts.push(tPt(r, a));
  }

  return pts;
}

// Compute placental lobe polygon extending from core into the center of a chamber
function getPlacentaPoints(ch, scaleWidth = 1.0, rMaxOffset = 0) {
  let midA = (ch.a0 + ch.a1) * 0.5;
  let halfW = (ch.a1 - ch.a0) * 0.22 * scaleWidth;
  let rBase = 335;
  let rTip = 790 + rMaxOffset;

  let pts = [];
  let steps = 26;
  for (let i = 0; i <= steps; i++) {
    let u = (i / steps) * 2 - 1; // -1 to +1 around the lobe
    let profile = pow(cos(u * 90), 0.75);
    let r = lerp(rBase, rTip, profile);
    // Mushroom/kidney flare near the tip of the placenta
    let flare = 1.0 + 0.38 * sin(constrain((r - 450) / 320, 0, 1) * 180);
    let a = midA + u * halfW * flare + sin(r * 0.04 + ch.id) * 0.6;
    pts.push(tPt(r, a));
  }
  return pts;
}

function draw() {
  translate(-width / 2, -height / 2);

  // =========================================================================
  // 1. DUSKY CREAM BACKGROUND & 1960s LINEN WEAVE (TOP-RIGHT CORNER)
  // =========================================================================
  background("#F2E9D8");

  // Warm twilight parchment modulation in the top-right corner
  brush.noStroke();
  let cornerWashPts = [
    [600, -20], [1220, -20], [1220, 620], [920, 380], [600, -20]
  ];
  brush.wash("#EAE0CE", 150);
  drawPoly(cornerWashPts, 0.1, true);

  let rimShadowPts = [];
  for (let a = -64; a <= -24; a += 2) {
    rimShadowPts.push(tPt(outerRadius(a) - 5, a));
  }
  for (let a = -24; a >= -64; a -= 2) {
    rimShadowPts.push(tPt(outerRadius(a) + 38, a));
  }
  brush.wash("#DECAC8", 125);
  drawPoly(rimShadowPts, 0.15, true);
  brush.noWash();

  // Tactile woven textile threads in the cream top-right corner
  for (let i = 0; i < 68; i++) {
    let offset = map(i, 0, 67, 620, 1200);
    let x1 = offset;
    let y1 = 0;
    let x2 = 1200;
    let y2 = 1200 - offset;
    if (x2 > x1 + 8) {
      brush.set("2H", i % 2 === 0 ? "#E0D4BE" : "#D8C9B4", 0.55);
      brush.line(x1, y1, x2, y2);
    }
  }
  for (let i = 0; i < 42; i++) {
    let d = map(i, 0, 41, 1435, 1770);
    let a0 = -62;
    let a1 = -28;
    let p1 = tPt(d, a0);
    let p2 = tPt(d, (a0 + a1) * 0.5);
    let p3 = tPt(d, a1);
    brush.set("2H", i % 3 === 0 ? "#D6C5B3" : "#E5DAC6", 0.5);
    safeSpline([p1, p2, p3], 0.4);
  }

  // =========================================================================
  // 2. SOLID UNDERPAINTING SILHOUETTE OF THE GIANT TOMATO SLICE
  // =========================================================================
  let sliceOutline = [[CX, CY]];
  for (let a = -98; a <= 8; a += 1.5) {
    sliceOutline.push(tPt(outerRadius(a), a));
  }
  brush.noStroke();
  brush.wash("#B31B34", 248);
  drawPoly(sliceOutline, 0.08, true);
  brush.noWash();

  // =========================================================================
  // 3. CONFIDENT FLAT MARKER FIELDS OF FLESH (CARMINE & CADMIUM RED SWATHS)
  // =========================================================================
  // Palette of dusky twilight carmines, rich crimsons, and vivid cadmium reds
  const markerPalette = [
    { fill: "#9E162F", stroke: "#7D1024", alpha: 195 }, // Deep twilight carmine
    { fill: "#C42038", stroke: "#9E162F", alpha: 190 }, // Rich carmine red
    { fill: "#E33B2C", stroke: "#C2271D", alpha: 185 }, // Vivid cadmium red
    { fill: "#EE5238", stroke: "#D13824", alpha: 175 }, // Bright cadmium scarlet
    { fill: "#7A1128", stroke: "#590A1C", alpha: 195 }, // Dusky plum-carmine
    { fill: "#D42C38", stroke: "#A81B2B", alpha: 185 }, // Warm crimson-cadmium
    { fill: "#F26849", stroke: "#D9482B", alpha: 165 }  // Luminous vermilion-cadmium
  ];

  // 3A. Broad overlapping circumferential marker swaths across the outer pericarp (r = 1090..1425)
  const pericarpRings = [
    { r0: 1085, r1: 1215, segs: 8, overlapA: 2.8, palOffset: 0 },
    { r0: 1185, r1: 1320, segs: 9, overlapA: 3.2, palOffset: 2 },
    { r0: 1295, r1: 1412, segs: 10, overlapA: 2.5, palOffset: 4 }
  ];

  for (let ring of pericarpRings) {
    let totalA = 104; // -96 to +8
    let stepA = totalA / ring.segs;
    for (let s = 0; s < ring.segs; s++) {
      let aStart = -96 + s * stepA - ring.overlapA;
      let aEnd = aStart + stepA + ring.overlapA * 2;
      let rIn = ring.r0 + (noise(s * 3.1, ring.r0) - 0.5) * 28;
      let rOut = min(ring.r1 + (noise(s * 7.3, ring.r1) - 0.5) * 26, outerRadius((aStart + aEnd) * 0.5) - 18);

      let swatch = markerPalette[(s + ring.palOffset) % markerPalette.length];
      let pts = buildArcPatch(rIn, rOut, aStart, aEnd, 8, 3, 10);
      let midAngle = (aStart + aEnd) * 0.5 + 90;
      renderMarkerSwath(pts, swatch.fill, swatch.alpha, swatch.stroke, midAngle, 14);
    }
  }

  // 3B. Broad radial & diagonal marker swaths down the septa walls (r = 340..1220)
  for (let idx = 0; idx < SEPTA.length; idx++) {
    let sep = SEPTA[idx];
    let radialBands = [
      { r0: 330, r1: 650,  w0: 4.8, w1: 5.8, pIdx: (idx * 2) % markerPalette.length },
      { r0: 590, r1: 930,  w0: 5.6, w1: 7.2, pIdx: (idx * 2 + 2) % markerPalette.length },
      { r0: 870, r1: 1210, w0: 7.0, w1: 11.5, pIdx: (idx * 2 + 3) % markerPalette.length }
    ];

    for (let b of radialBands) {
      // Left and right overlapping swaths along each septum
      for (let side of [-1, 1]) {
        let a0 = sep.mid + (side === -1 ? -b.w0 : -1.2);
        let a1 = sep.mid + (side === -1 ? 1.2 : b.w0);
        let a0Out = sep.mid + (side === -1 ? -b.w1 : -1.6);
        let a1Out = sep.mid + (side === -1 ? 1.6 : b.w1);

        let pts = [
          tPt(b.r0, a0),
          tPt(b.r0, (a0 + a1) * 0.5),
          tPt(b.r0, a1),
          tPt((b.r0 + b.r1) * 0.5, lerp(a1, a1Out, 0.5)),
          tPt(b.r1, a1Out),
          tPt(b.r1, (a0Out + a1Out) * 0.5),
          tPt(b.r1, a0Out),
          tPt((b.r0 + b.r1) * 0.5, lerp(a0, a0Out, 0.5))
        ];

        let sw = markerPalette[(b.pIdx + (side === 1 ? 1 : 0)) % markerPalette.length];
        renderMarkerSwath(pts, sw.fill, sw.alpha, sw.stroke, sep.mid + side * 8, 12);
      }
    }

    // Bold expressive wide marker strokes sweeping straight up the septum spine
    brush.set("broadMarker", "#E33B2C", 1.05);
    safeSpline([
      tPt(370, sep.mid - 1.2),
      tPt(680, sep.mid + 0.6),
      tPt(1020, sep.mid - 0.8),
      tPt(1260, sep.mid + 1.0)
    ], 0.4);

    brush.set("broadMarker", "#9E162F", 0.9);
    safeSpline([
      tPt(410, sep.mid + 1.8),
      tPt(740, sep.mid - 1.0),
      tPt(1120, sep.mid + 2.2)
    ], 0.4);
  }

  // 3C. Secondary pericarp marker lobes dipping into the middle of each chamber's outer wall
  for (let c of CHAMBERS) {
    let midA = (c.a0 + c.a1) * 0.5;
    let lobePts = [
      tPt(1185, midA - 6.5),
      tPt(1185, midA),
      tPt(1185, midA + 6.5),
      tPt(1110, midA + 4.2),
      tPt(1055, midA + 1.5),
      tPt(1045, midA),
      tPt(1055, midA - 1.5),
      tPt(1110, midA - 4.2)
    ];
    renderMarkerSwath(lobePts, "#E64030", 195, "#B51D33", midA + 90, 11);

    let innerHighlightSwath = buildArcPatch(1155, 1245, c.a0 + 2, c.a1 - 2, 8, 2, 6);
    renderMarkerSwath(innerHighlightSwath, "#F05A3E", 165, "#D13228", midA + 85, 13);
  }

  // 3D. Expressive overlapping marker strokes across the pericarp for authentic hand-laid print feel
  for (let i = 0; i < 28; i++) {
    let r = random(1135, 1395);
    let a0 = random(-92, -6);
    let span = random(9, 20);
    let a1 = min(a0 + span, 5);
    let col = i % 3 === 0 ? "#F26444" : (i % 3 === 1 ? "#8F142C" : "#D92B38");
    brush.set("broadMarker", col, random(0.75, 1.25));
    safeSpline([
      tPt(r, a0),
      tPt(r + random(-14, 14), (a0 + a1) * 0.5),
      tPt(r + random(-10, 10), a1)
    ], 0.35);
  }

  // 3E. Outer Skin / Cuticle Rim (Rich twilight burgundy skin + bright cadmium subcuticle)
  for (let s = 0; s < 12; s++) {
    let a0 = -96 + s * 8.6 - 1.0;
    let a1 = a0 + 10.6;
    let mid = (a0 + a1) * 0.5;
    let rOuter = outerRadius(mid);

    // Subcuticle bright cadmium-vermilion band
    let subPts = buildArcPatch(rOuter - 46, rOuter - 18, a0, a1, 6, 2, 4);
    renderMarkerSwath(subPts, s % 2 === 0 ? "#F25C38" : "#E33B2C", 205, "#C72820", mid + 90, 10);

    // Outer skin dark twilight plum-carmine band
    let skinPts = [];
    for (let k = 0; k <= 8; k++) {
      let a = lerp(a0, a1, k / 8);
      skinPts.push(tPt(outerRadius(a) - 20, a));
    }
    for (let k = 8; k >= 0; k--) {
      let a = lerp(a0, a1, k / 8);
      skinPts.push(tPt(outerRadius(a) + 2, a));
    }
    renderMarkerSwath(skinPts, s % 2 === 0 ? "#590B20" : "#731029", 225, "#3D0615", mid + 90, 8);
  }

  // Crisp outer cuticle pen & pencil definition along the top-right cream boundary
  let outerEdgeLine = [];
  for (let a = -68; a <= -22; a += 1.0) {
    outerEdgeLine.push(tPt(outerRadius(a), a));
  }
  brush.set("rotring", "#380514", 0.95);
  safeSpline(outerEdgeLine, 0.35);

  let cuticleGlossLine = [];
  for (let a = -65; a <= -25; a += 1.2) {
    cuticleGlossLine.push(tPt(outerRadius(a) - 5, a));
  }
  brush.set("cpencil", "#F78B6D", 0.85);
  safeSpline(cuticleGlossLine, 0.35);

  // Subtle cross-cut vascular specks in the outer pericarp flesh (where realism meets print)
  for (let i = 0; i < 65; i++) {
    let a = random(-92, 2);
    let r = random(1195, outerRadius(a) - 48);
    let p = tPt(r, a);
    brush.set("cpencil", "#F7C8C2", random(0.55, 0.95));
    brush.line(p[0] - 3, p[1] - 2, p[0] + 4, p[1] + 2);
    brush.set("rotring", "#7A1128", 0.45);
    brush.line(p[0] + 2, p[1] + 2, p[0] + 6, p[1] + 4);
  }

  // =========================================================================
  // 4. SEED CHAMBERS (LOCULES): DEEP GLASSY GEL & PLACENTAL LOBES
  // =========================================================================
  for (let ch of CHAMBERS) {
    // 4A. Outer bevel rim of the chamber (flesh curving down into the cavity)
    let rimPts = getChamberPoints(ch, 10, -0.4);
    brush.noStroke();
    brush.wash("#7D1128", 215);
    drawPoly(rimPts, 0.12, true);
    brush.noWash();

    // 4B. Deep twilight plum-garnet base of the locular cavity
    let cavPts = getChamberPoints(ch, 0, 0);
    brush.noStroke();
    brush.wash("#330514", 242);
    drawPoly(cavPts, 0.12, true);
    brush.noWash();

    // 4C. Watercolor glassy gel washes inside the chamber (batched for rich bleed)
    let innerGelPts = getChamberPoints(ch, -22, 0.7);
    brush.noStroke();
    brush.fill("#5E0C24", 155);
    brush.fillBleed(0.24, "in");
    brush.fillTexture(0.55, 0.4);
    drawPoly(innerGelPts, 0.15, true);

    // Translucent amber-ruby subsurface light pools in the left and right lobes of the chamber
    let midA = (ch.a0 + ch.a1) * 0.5;
    for (let side of [-1, 1]) {
      let aStart = side === -1 ? ch.a0 + 1.2 : midA + 1.5;
      let aEnd = side === -1 ? midA - 1.5 : ch.a1 - 1.2;
      let poolPts = buildArcPatch(470, 1040, aStart, aEnd, 6, 3, 18);
      brush.fill("#A82230", 130);
      brush.fillBleed(0.2, "in");
      brush.fillTexture(0.5, 0.35);
      drawPoly(poolPts, 0.15, true);

      let warmPool = buildArcPatch(530, 960, aStart + 1.0, aEnd - 1.0, 5, 2, 14);
      brush.fill("#CC4B2B", 110);
      brush.fillBleed(0.18, "in");
      drawPoly(warmPool, 0.18, true);
    }
    brush.noFill();

    // 4D. Fine pencil & pen cross-contour shading along the recessed chamber wall bevel
    for (let k = 0; k < 56; k++) {
      let idx = floor(map(k, 0, 55, 0, cavPts.length - 1));
      let pOuter = rimPts[idx];
      let pInner = cavPts[idx];
      if (pOuter && pInner) {
        brush.set("rotring", "#24030E", 0.5);
        brush.line(pOuter[0], pOuter[1], pInner[0], pInner[1]);
      }
    }
    brush.set("HB", "#1F020B", 0.85);
    safeSpline(cavPts.concat([cavPts[0]]), 0.25);

    // 4E. Placental Lobe (fleshy core projection inside the seed chamber)
    let placShadow = getPlacentaPoints(ch, 1.14, 22);
    brush.noStroke();
    brush.wash("#21020C", 210);
    drawPoly(placShadow, 0.15, true);

    let placBase = getPlacentaPoints(ch, 1.0, 0);
    brush.wash("#B52038", 235);
    drawPoly(placBase, 0.15, true);

    let placMid = getPlacentaPoints(ch, 0.76, -38);
    brush.wash("#D94E60", 210);
    drawPoly(placMid, 0.15, true);

    let placCore = getPlacentaPoints(ch, 0.48, -85);
    brush.wash("#F0A8B6", 215);
    drawPoly(placCore, 0.15, true);

    let placSpine = getPlacentaPoints(ch, 0.24, -135);
    brush.wash("#FAE0E6", 225);
    drawPoly(placSpine, 0.15, true);
    brush.noWash();

    // Fine vascular striations inside the placental lobe
    for (let f = -5; f <= 5; f++) {
      let norm = f / 5;
      let aOffset = norm * (ch.a1 - ch.a0) * 0.14;
      let fPts = [
        tPt(340, midA + aOffset * 0.4),
        tPt(480, midA + aOffset * 0.8),
        tPt(620, midA + aOffset * 1.25),
        tPt(735 - abs(f) * 18, midA + aOffset * 1.55)
      ];
      brush.set("silkyFiber", abs(f) <= 2 ? "#FFF7F9" : "#F2B6C2", 0.75);
      safeSpline(fPts, 0.45);
    }
  }

  // =========================================================================
  // 5. THE WHITE FIBROUS CORE (COLUMELLA & VASCULAR BUNDLES)
  // =========================================================================
  // Layered blush-to-ivory washes in the bottom-left core (CX = -40, CY = 1240)
  const coreLayers = [
    { rScale: 1.12, col: "#C9384D", alpha: 210 },
    { rScale: 1.00, col: "#DF6D80", alpha: 220 },
    { rScale: 0.88, col: "#EDA5B3", alpha: 225 },
    { rScale: 0.76, col: "#F6CFD7", alpha: 235 },
    { rScale: 0.62, col: "#FBE9ED", alpha: 240 },
    { rScale: 0.46, col: "#FFF8FA", alpha: 245 }
  ];

  brush.noStroke();
  for (let layer of coreLayers) {
    let pts = [[CX, CY]];
    for (let a = -98; a <= 10; a += 2) {
      pts.push(tPt(coreRadius(a) * layer.rScale, a));
    }
    brush.wash(layer.col, layer.alpha);
    drawPoly(pts, 0.12, true);
  }

  // Slightly recessed spongy central pith right at the heart of the slice (r = 0..125)
  let pithPts = [[CX, CY]];
  for (let a = -98; a <= 10; a += 4) {
    pithPts.push(tPt(118 + (noise(a * 0.15) - 0.5) * 24, a));
  }
  brush.wash("#DEC0CA", 215);
  drawPoly(pithPts, 0.15, true);
  brush.noWash();

  // Vascular fiber bundles streaming from the core up the center of each radial septum
  for (let sep of SEPTA) {
    for (let s = -4; s <= 4; s++) {
      let da = s * 0.45;
      let maxR = map(abs(s), 0, 4, 1060, 680);
      let pts = [];
      for (let r = 180; r <= maxR; r += 75) {
        let wave = sin(r * 0.045 + s * 25) * (0.35 + (r / 1000) * 0.8);
        pts.push(tPt(r, sep.mid + da + wave));
      }
      let col = abs(s) <= 1 ? "#FFF6F8" : (abs(s) <= 2 ? "#F5C6D0" : "#E58A9B");
      brush.set("silkyFiber", col, map(abs(s), 0, 4, 0.9, 0.5));
      safeSpline(pts, 0.45);
    }
  }

  // Dense radiating & branching fibrous pencil/pen texture across the white core
  for (let i = 0; i < 210; i++) {
    let a = random(-94, 4);
    let r0 = random(45, 220);
    let r1 = r0 + random(75, 195);
    let rm = (r0 + r1) * 0.5;
    let drift = random(-2.8, 2.8);

    let p0 = tPt(r0, a);
    let p1 = tPt(rm, a + drift * 0.5);
    let p2 = tPt(r1, a + drift);

    if (i % 4 === 0) {
      brush.set("rotring", "#8C5D6E", 0.38);
    } else if (i % 2 === 0) {
      brush.set("silkyFiber", "#FFFFFF", 0.85);
    } else {
      brush.set("2H", "#D49AA9", 0.55);
    }
    safeSpline([p0, p1, p2], 0.4);
  }

  // Cellular micro-pits and spongy pith detail in the core
  for (let i = 0; i < 85; i++) {
    let a = random(-92, 2);
    let r = random(28, 265);
    let p = tPt(r, a);
    let rad = random(2.5, 6.5);
    brush.set("2H", r < 125 ? "#7D5262" : "#B87D8E", 0.45);
    brush.arc(p[0], p[1], rad, random(0, 180), random(200, 350));
    brush.set("rotring", "#FFFFFF", 0.45);
    brush.line(p[0] - rad * 0.5, p[1] - rad * 0.5, p[0] + rad * 0.5, p[1] - rad * 0.2);
  }

  // =========================================================================
  // 6. HYPERREAL PALE SEEDS, MUCILAGINOUS SACS & FUNICULI IN THE CHAMBERS
  // =========================================================================
  for (let ch of CHAMBERS) {
    let midA = (ch.a0 + ch.a1) * 0.5;
    let halfSpan = (ch.a1 - ch.a0) * 0.5;

    // Generate seed positions flanking both sides of the placental lobe
    let submergedSeeds = [];
    let surfaceSeeds = [];

    let rows = ch.partial ? [0] : [-1, 1];
    for (let side of rows) {
      let sideDir = ch.partial ? 1 : side;
      let count = ch.partial ? 5 : 6;

      for (let k = 0; k < count; k++) {
        let t = k / (count - 1);
        let r = lerp(455, 985, t) + random(-18, 18);
        let aDist = lerp(halfSpan * 0.46, halfSpan * 0.62, sin(t * 180)) + random(-1.1, 1.1);
        let a = midA + sideDir * aDist;

        // Pointed tip of seed aims back toward the placental attachment point
        let attachR = constrain(r - random(55, 110), 390, 740);
        let attachA = midA + sideDir * (halfSpan * 0.18);
        let pSeed = tPt(r, a);
        let pAttach = tPt(attachR, attachA);
        let angleToPlacenta = atan2(pAttach[1] - pSeed[1], pAttach[0] - pSeed[0]);

        surfaceSeeds.push({
          x: pSeed[0],
          y: pSeed[1],
          r: r,
          a: a,
          ang: angleToPlacenta + random(-14, 14),
          len: random(42, 54),
          wid: random(22, 28),
          attach: pAttach
        });

        // Also place a deeper submerged seed nearby in the dark gel
        if (k < count - 1) {
          let rSub = r + random(28, 62);
          let aSub = midA + sideDir * (aDist + random(-2.2, 2.6));
          let pSub = tPt(rSub, aSub);
          submergedSeeds.push({
            x: pSub[0],
            y: pSub[1],
            ang: angleToPlacenta + random(-28, 28),
            len: random(36, 46),
            wid: random(19, 24)
          });
        }
      }
    }

    // 6A. Draw Submerged Seeds (muted amber-rose, veiled beneath ruby gel)
    for (let sd of submergedSeeds) {
      if (sd.x < -30 || sd.x > 1230 || sd.y < -30 || sd.y > 1230) continue;
      let bodyPts = buildSeedPolygon(sd.x, sd.y, sd.len, sd.wid, sd.ang);
      brush.noStroke();
      brush.wash("#AD443B", 165);
      drawPoly(bodyPts, 0.2, true);

      let corePts = buildSeedPolygon(sd.x, sd.y, sd.len * 0.6, sd.wid * 0.55, sd.ang);
      brush.wash("#7D2228", 180);
      drawPoly(corePts, 0.2, true);

      // Dark ruby gel veil over the submerged seed
      let veilPts = buildSeedPolygon(sd.x + 4, sd.y - 3, sd.len * 1.25, sd.wid * 1.25, sd.ang);
      brush.wash("#4F0A1E", 115);
      drawPoly(veilPts, 0.25, true);
      brush.noWash();
    }

    // 6B. Draw Surface Seeds (mucilaginous gel sac, silky hairs, funiculus, straw-ivory body)
    for (let sd of surfaceSeeds) {
      if (sd.x < -40 || sd.x > 1240 || sd.y < -40 || sd.y > 1240) continue;

      // 1) Translucent golden-amber mucilaginous gel sac surrounding the seed
      let sacPts = buildSeedPolygon(sd.x, sd.y, sd.len * 1.55, sd.wid * 1.65, sd.ang);
      brush.noStroke();
      brush.wash("#B86B2E", 85);
      drawPoly(sacPts, 0.25, true);

      let innerSacPts = buildSeedPolygon(sd.x, sd.y, sd.len * 1.28, sd.wid * 1.35, sd.ang);
      brush.wash("#D99B42", 75);
      drawPoly(innerSacPts, 0.25, true);
      brush.noWash();

      // 2) Funiculus (umbilical cord attaching seed tip to the placental lobe)
      let tipX = sd.x + cos(sd.ang) * (sd.len * 0.52);
      let tipY = sd.y + sin(sd.ang) * (sd.len * 0.52);
      let midFunX = (tipX + sd.attach[0]) * 0.5 + random(-12, 12);
      let midFunY = (tipY + sd.attach[1]) * 0.5 + random(-12, 12);
      brush.set("silkyFiber", "#F7D4C8", 0.85);
      safeSpline([[tipX, tipY], [midFunX, midFunY], sd.attach], 0.45);
      brush.set("rotring", "#FFF7F2", 0.4);
      safeSpline([[tipX, tipY], [midFunX + 2, midFunY - 2], sd.attach], 0.45);

      // 3) Fine silky seed hairs (pubescence) radiating into the gel sac
      let hairCount = 26;
      for (let h = 0; h < hairCount; h++) {
        let theta = map(h, 0, hairCount, 0, 360);
        let localX = cos(theta) * (sd.len * 0.46);
        let localY = sin(theta) * (sd.wid * 0.46);
        let outX = cos(theta) * (sd.len * 0.68);
        let outY = sin(theta) * (sd.wid * 0.72);

        let ca = cos(sd.ang);
        let sa = sin(sd.ang);
        let hx0 = sd.x + localX * ca - localY * sa;
        let hy0 = sd.y + localX * sa + localY * ca;
        let hx1 = sd.x + outX * ca - outY * sa;
        let hy1 = sd.y + outX * sa + outY * ca;

        brush.set("2H", h % 2 === 0 ? "#F5E4B5" : "#E0C078", 0.38);
        brush.line(hx0, hy0, hx1, hy1);
      }

      // 4) Seed drop shadow in the gel pocket
      let shadowPts = buildSeedPolygon(sd.x + 4, sd.y + 5, sd.len * 1.04, sd.wid * 1.06, sd.ang);
      brush.noStroke();
      brush.wash("#290410", 185);
      drawPoly(shadowPts, 0.2, true);

      // 5) Outer pale straw-cream seed body (wing/margin)
      let seedOuter = buildSeedPolygon(sd.x, sd.y, sd.len, sd.wid, sd.ang);
      brush.wash("#FBF1D2", 242);
      drawPoly(seedOuter, 0.18, true);

      // 6) Warm golden-ochre inner seed depression
      let seedMid = buildSeedPolygon(sd.x - cos(sd.ang) * 2, sd.y - sin(sd.ang) * 2, sd.len * 0.72, sd.wid * 0.66, sd.ang);
      brush.wash("#DEAC54", 225);
      drawPoly(seedMid, 0.18, true);

      // 7) Dusky amber-brown embryo core
      let seedInner = buildSeedPolygon(sd.x - cos(sd.ang) * 3, sd.y - sin(sd.ang) * 3, sd.len * 0.45, sd.wid * 0.38, sd.ang);
      brush.wash("#996028", 210);
      drawPoly(seedInner, 0.18, true);
      brush.noWash();

      // 8) Crisp hyperreal pencil & pen detailing on the seed
      brush.set("rotring", "#6B3D18", 0.45);
      safeSpline(seedOuter.concat([seedOuter[0]]), 0.25);

      brush.set("2H", "#7D491E", 0.4);
      safeSpline(seedMid, 0.25);

      // Bright ivory ridge highlight along the upper edge of the seed rim
      let ridgeSlice = seedOuter.slice(1, floor(seedOuter.length * 0.48));
      brush.set("wetPen", "#FFFDF7", 0.65);
      safeSpline(ridgeSlice, 0.3);

      // Partial translucent ruby gel meniscus lapping over the lower edge of the seed
      let lapPts = buildSeedPolygon(
        sd.x - sin(sd.ang) * (sd.wid * 0.28),
        sd.y + cos(sd.ang) * (sd.wid * 0.28),
        sd.len * 0.85,
        sd.wid * 0.55,
        sd.ang
      );
      brush.noStroke();
      brush.wash("#6E0F25", 95);
      drawPoly(lapPts, 0.2, true);
      brush.noWash();

      // Wet crescent specular highlight on the glossy gel dome covering the seed
      let hlAngle = sd.ang - 35;
      let hlX = sd.x + cos(hlAngle) * (sd.len * 0.22);
      let hlY = sd.y + sin(hlAngle) * (sd.wid * 0.32);
      let hlX2 = sd.x - cos(sd.ang) * (sd.len * 0.25);
      let hlY2 = sd.y - sin(sd.ang) * (sd.wid * 0.25);
      brush.set("wetPen", "#FFFFFF", 0.8);
      safeSpline([
        [hlX - 6, hlY - 3],
        [hlX, hlY],
        [hlX2, hlY2]
      ], 0.4);
    }
  }

  // =========================================================================
  // 7. WET SPECULAR HIGHLIGHTS IN FINE PENCIL & PEN (GLASSY MENISCUS)
  // =========================================================================
  // 7A. Major curved meniscus highlight ribbons inside each seed chamber
  for (let ch of CHAMBERS) {
    let a0 = ch.a0 + 1.4;
    let a1 = ch.a1 - 1.4;
    let midA = (a0 + a1) * 0.5;

    // Outer chamber arch meniscus (where gel meets outer pericarp wall)
    drawWetHighlightRibbon([
      tPt(1095, a0 + 1.2),
      tPt(1122, lerp(a0, midA, 0.45)),
      tPt(1078, midA - 1.8),
      tPt(1055, midA),
      tPt(1080, midA + 1.8),
      tPt(1120, lerp(midA, a1, 0.55)),
      tPt(1092, a1 - 1.2)
    ], 11);

    // Left septum wall meniscus ribbon
    drawWetHighlightRibbon([
      tPt(445, a0 + 0.6),
      tPt(610, a0 - 0.3),
      tPt(785, a0 - 0.5),
      tPt(955, a0 + 0.4)
    ], 9);

    // Right septum wall meniscus ribbon
    drawWetHighlightRibbon([
      tPt(460, a1 - 0.6),
      tPt(640, a1 + 0.4),
      tPt(810, a1 + 0.3),
      tPt(965, a1 - 0.5)
    ], 8.5);

    // Glossy wet rim arching around the tip of the placental lobe
    let halfP = (ch.a1 - ch.a0) * 0.19;
    drawWetHighlightRibbon([
      tPt(615, midA - halfP),
      tPt(735, midA - halfP * 0.65),
      tPt(785, midA),
      tPt(730, midA + halfP * 0.65),
      tPt(605, midA + halfP)
    ], 8);

    // Secondary interior gel ripples & wet light beads inside the dark cavity
    for (let side of [-1, 1]) {
      let aLane = midA + side * (ch.a1 - ch.a0) * 0.29;
      drawWetHighlightRibbon([
        tPt(520, aLane - side * 1.2),
        tPt(675, aLane + side * 0.8),
        tPt(840, aLane - side * 0.6)
      ], 6);
    }
  }

  // 7B. Glistening wet beads & fine pencil/pen specular glints on the core & septa edges
  for (let i = 0; i < 95; i++) {
    let a = random(-92, 2);
    let r = random(180, 1180);
    let p = tPt(r, a);
    if (p[0] < 5 || p[0] > 1195 || p[1] < 5 || p[1] > 1195) continue;

    let beadLen = random(4, 14);
    let ang = a + 90 + random(-25, 25);
    let dx = cos(ang) * beadLen;
    let dy = sin(ang) * beadLen;

    // Crisp dark refractive shadow right beside the wet highlight
    brush.set("rotring", "#330412", 0.55);
    brush.line(p[0] + 1.5, p[1] + 2, p[0] + dx + 1.5, p[1] + dy + 2);

    // Pure white wet glint
    brush.set("wetPen", "#FFFFFF", random(0.55, 1.0));
    brush.line(p[0], p[1], p[0] + dx, p[1] + dy);
  }

  noLoop();
}

// Helper to build a natural teardrop-shaped tomato seed polygon
function buildSeedPolygon(cx, cy, len, wid, angleDeg) {
  let pts = [];
  let steps = 20;
  let ca = cos(angleDeg);
  let sa = sin(angleDeg);

  for (let i = 0; i < steps; i++) {
    let t = map(i, 0, steps, 0, 360);
    // Teardrop profile: pointed at x = +len/2 (theta = 0), rounded at x = -len/2 (theta = 180)
    let xLocal = cos(t) * (len * 0.5);
    let taper = 0.78 - 0.28 * cos(t);
    let yLocal = sin(t) * (wid * 0.5) * taper;

    let rx = cx + xLocal * ca - yLocal * sa;
    let ry = cy + xLocal * sa + yLocal * ca;
    pts.push([rx, ry]);
  }
  return pts;
}

// Helper to render a hyperreal wet meniscus highlight ribbon in fine pencil and pen
function drawWetHighlightRibbon(spinePts, maxWidth = 9) {
  if (!spinePts || spinePts.length < 2) return;

  let leftPts = [];
  let rightPts = [];
  let N = spinePts.length;

  for (let i = 0; i < N; i++) {
    let t = i / (N - 1);
    let p = spinePts[i];
    let pPrev = spinePts[max(0, i - 1)];
    let pNext = spinePts[min(N - 1, i + 1)];

    let tx = pNext[0] - pPrev[0];
    let ty = pNext[1] - pPrev[1];
    let mag = sqrt(tx * tx + ty * ty) || 1;
    let nx = -ty / mag;
    let ny = tx / mag;

    // Organic pinching and swelling along the wet meniscus
    let w = maxWidth * sin(t * 180) * (0.65 + 0.45 * sin(t * 540));
    leftPts.push([p[0] + nx * w * 0.5, p[1] + ny * w * 0.5]);
    rightPts.unshift([p[0] - nx * w * 0.5, p[1] - ny * w * 0.5]);
  }

  let poly = leftPts.concat(rightPts);

  // 1) Dark refractive edge shadow immediately adjacent to the wet reflection
  brush.set("rotring", "#1F020B", 0.75);
  safeSpline(rightPts, 0.35);

  // 2) Soft twilight icy-blush glow halo around the highlight
  brush.set("cpencil", "#F5D5E0", 1.15);
  safeSpline(leftPts, 0.35);

  // 3) Bright white specular body
  brush.noStroke();
  brush.wash("#FFFFFF", 242);
  drawPoly(poly, 0.15, true);
  brush.noWash();

  // 4) Fine 2H pencil hatch modulation across the highlight + razor-sharp white pen spine
  for (let i = 1; i < leftPts.length - 1; i++) {
    let pA = leftPts[i];
    let pB = rightPts[rightPts.length - 1 - i];
    if (pA && pB) {
      brush.set("2H", "#D8E4F2", 0.42);
      brush.line(pA[0], pA[1], pB[0], pB[1]);
    }
  }

  brush.set("wetPen", "#FFFFFF", 0.95);
  safeSpline(spinePts, 0.4);
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(8472);
  noiseSeed(8472);

  // Ultra-soft atmospheric spray for glassy sky and cloud gradients (no linear strokes)
  brush.add("air_spray", {
    type: "spray",
    weight: 22,
    scatter: 9.5,
    opacity: 11,
    spacing: 0.75,
    pressure: [0.5, 1.0, 0.5]
  });

  // Finer mist spray for cloud saucer edges and wet slate underpainting
  brush.add("mist_spray", {
    type: "spray",
    weight: 10,
    scatter: 4.2,
    opacity: 16,
    spacing: 0.55,
    pressure: [0.4, 1.0, 0.4]
  });

  // Sharp coloured pencil for hyperreal slate striations, water sheen burnishing, and lichen
  brush.add("fine_cpencil", {
    type: "default",
    weight: 0.38,
    scatter: 0.14,
    sharpness: 0.68,
    grain: 26,
    opacity: 92,
    spacing: 0.14,
    pressure: [0.35, 1.15, 0.35]
  });

  // Crystalline pinpoint brush for mica glints and specular water pinpricks
  brush.add("mica_glint", {
    type: "default",
    weight: 0.28,
    scatter: 0.03,
    sharpness: 0.94,
    grain: 4,
    opacity: 215,
    spacing: 0.1,
    pressure: [0.8, 1.2, 0.8]
  });
}

function draw() {
  translate(-width / 2, -height / 2);
  brush.noField();
  brush.noClip();

  background("#172331");

  // 1. ENORMOUS GLASSY SKY (Soft wash + fine spray gradient, zero visible strokes)
  drawGlassySky();

  // 2. DISTANT LOWER STANDING-WAVE LENTICULAR WISPS
  drawDistantLenticulars();

  // 3. TOWERING STACK OF LENTICULAR CLOUDS (Smooth-edged saucers in pale peach, lavender-grey, cold white)
  drawMainLenticularStack();

  // 4. LOW HORIZON & DISTANT COLD SLATE RIDGES VEILED IN MIST
  drawDistantHorizon();

  // 5. FOREGROUND ROCKY SLATE RIDGE
  drawForegroundRidge();

  // 6. HYPERREAL CAIRN OF WET-DARK SLATE PEBBLES (Coloured pencil over spray, water sheen, lichen, mica)
  drawSlateCairn();

  noLoop();
}

