// UTILITIES & GEOMETRY HELPERS
// ============================================================================

function washPoly(pts, col, alpha) {
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.wash(col, alpha);
  brush.beginShape(0);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noWash();
}

function washRectBand(x, y, w, h, col, alpha) {
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.wash(col, alpha);
  brush.rect(x, y, w, h, "corner");
  brush.noWash();
}

function lerpHex(c1, c2, t) {
  return lerpColor(color(c1), color(c2), constrain(t, 0, 1));
}

function skyColorAtY(y) {
  let stops = [
    { y: 0, c: "#162230" },
    { y: 150, c: "#213244" },
    { y: 310, c: "#32475c" },
    { y: 470, c: "#486075" },
    { y: 620, c: "#647a8e" },
    { y: 750, c: "#8697a7" },
    { y: 850, c: "#abb4c0" },
    { y: 915, c: "#c9c8cf" },
    { y: 965, c: "#dfd2ce" }
  ];
  if (y <= stops[0].y) return color(stops[0].c);
  for (let i = 0; i < stops.length - 1; i++) {
    if (y <= stops[i + 1].y) {
      let t = (y - stops[i].y) / (stops[i + 1].y - stops[i].y);
      return lerpHex(stops[i].c, stops[i + 1].c, t);
    }
  }
  return color(stops[stops.length - 1].c);
}

// Generates a smooth aerodynamic saucer/lens polygon for lenticular clouds
function makeSaucerPoints(cx, cy, rx, ryTop, ryBot, opts = {}) {
  let steps = opts.steps || 56;
  let pinch = opts.pinch || 0.72;
  let tilt = opts.tilt || 0;
  let waveAmp = opts.waveAmp || 0;
  let waveFreq = opts.waveFreq || 1.5;
  let wavePhase = opts.wavePhase || 0;
  let asymX = opts.asymX || 0;

  let cosT = cos(tilt);
  let sinT = sin(tilt);
  let pts = [];

  for (let i = 0; i < steps; i++) {
    let ang = (i / steps) * 360;
    let ux = cos(ang);
    let uy = sin(ang);

    // Taper tips into smooth saucer edges
    let env = pow(max(0.0001, 1 - ux * ux), pinch - 0.5);
    let localX = ux * rx + (1 - ux * ux) * asymX;
    let ry = uy < 0 ? ryTop : ryBot;
    let wave = sin(ux * 180 * waveFreq + wavePhase) * waveAmp * (1 - ux * ux);
    let localY = uy * ry * env + wave;

    let px = cx + localX * cosT - localY * sinT;
    let py = cy + localX * sinT + localY * cosT;
    pts.push([px, py]);
  }
  return pts;
}

// Generates an organic water-worn lens-shaped slate pebble contour
function makePebblePoints(cx, cy, rx, ryTop, ryBot, tilt, seedOffset, steps = 52) {
  let cosT = cos(tilt);
  let sinT = sin(tilt);
  let pts = [];

  for (let i = 0; i < steps; i++) {
    let ang = (i / steps) * 360;
    let ux = cos(ang);
    let uy = sin(ang);

    // Subtle lens-like taper at left/right rims + natural river/shore slate harmonics
    let lensEnv = pow(max(0.001, 1 - ux * ux), 0.08);
    let harm1 = sin(ang * 2 + seedOffset * 37) * 0.022;
    let harm2 = cos(ang * 3 - seedOffset * 53) * 0.014;
    let radMod = 1 + harm1 + harm2;

    let lx = ux * rx * radMod;
    let ry = uy < 0 ? ryTop : ryBot;
    // Slightly flatten bottom contact belly and dome the top
    let flatBelly = uy > 0 ? 1 - 0.1 * pow(uy, 2) : 1;
    let ly = uy * ry * lensEnv * radMod * flatBelly;

    let px = cx + lx * cosT - ly * sinT;
    let py = cy + lx * sinT + ly * cosT;
    pts.push([px, py]);
  }
  return pts;
}

// Point-in-polygon check for clipping fine pencil strokes or specks inside a stone
function pointInPoly(x, y, pts) {
  let inside = false;
  for (let i = 0, j = pts.length - 1; i < pts.length; j = i++) {
    let xi = pts[i][0], yi = pts[i][1];
    let xj = pts[j][0], yj = pts[j][1];
    let intersect = ((yi > y) !== (yj > y)) &&
      (x < (xj - xi) * (y - yi) / ((yj - yi) + 0.00001) + xi);
    if (intersect) inside = !inside;
  }
  return inside;
}

// ============================================================================
// 1. GLASSY ENORMOUS SKY
// ============================================================================

function drawGlassySky() {
  let maxSkyY = 975;
  let numBands = 115;
  let stepY = maxSkyY / numBands;

  // Seamless overlapping wash bands
  for (let i = 0; i <= numBands; i++) {
    let y = i * stepY - 12;
    let col = skyColorAtY(y + stepY * 0.5);
    washRectBand(-20, y, width + 40, stepY * 2.4, col, 72);
  }

  // Subtle central zenith-to-horizon luminosity column behind the cloud/cairn axis
  for (let i = 0; i < 14; i++) {
    let t = i / 13;
    let cy = lerp(240, 880, t);
    let rx = lerp(560, 480, t);
    let ry = lerp(190, 95, t);
    let glowCol = lerpColor(skyColorAtY(cy), color("#e8dcd8"), 0.16);
    let glowPts = makeSaucerPoints(600, cy, rx, ry, ry, { pinch: 0.52, steps: 40 });
    washPoly(glowPts, glowCol, 14);
  }

  // Fine airbrush spray passes across the sky for velvety, stroke-free atmospheric grain
  for (let i = 0; i < 220; i++) {
    let y = random(-10, 955);
    let baseCol = skyColorAtY(y);
    let shift = random(-0.08, 0.08);
    let sprayCol = shift > 0
      ? lerpColor(baseCol, color("#f0e6e2"), shift)
      : lerpColor(baseCol, color("#121d2b"), -shift);
    brush.set("air_spray", sprayCol, random(0.9, 1.5));
    let x1 = random(-40, width * 0.45);
    let x2 = x1 + random(260, 680);
    brush.line(x1, y, x2, y + random(-4, 4));
  }
}

// ============================================================================
// 2 & 3. LENTICULAR CLOUD SAUCERS (SMOOTH-EDGED, GLASSY, LAYERED)
// ============================================================================

function drawSingleLenticularSaucer(cfg) {
  let {
    cx, cy, rx, ryTop, ryBot,
    tilt = 0, pinch = 0.74,
    waveAmp = 1.5, waveFreq = 1.5, wavePhase = 0,
    asymX = 0, wafers = 2,
    peachStrength = 1.0, shadowDepth = 1.0
  } = cfg;

  let baseOpts = {
    steps: 60,
    pinch: pinch,
    tilt: tilt,
    waveAmp: waveAmp,
    waveFreq: waveFreq,
    wavePhase: wavePhase,
    asymX: asymX
  };

  // A. Soft outer atmospheric edge blend (glassy transition into sky)
  let skyBg = skyColorAtY(cy);
  for (let k = 3; k >= 1; k--) {
    let scaleExpand = 1 + k * 0.022;
    let haloCol = lerpColor(skyBg, color("#c9ccd6"), 0.35 - k * 0.08);
    let pts = makeSaucerPoints(
      cx, cy,
      rx * scaleExpand,
      ryTop * (1 + k * 0.05),
      ryBot * (1 + k * 0.05),
      baseOpts
    );
    washPoly(pts, haloCol, 18);
  }

  // B. Main saucer body — cool silvery lavender-grey base
  let bodyPts = makeSaucerPoints(cx, cy, rx, ryTop, ryBot, baseOpts);
  washPoly(bodyPts, "#a8aebd", 52);

  // C. Upper cold-white dome & razor-smooth lit crest (light from upper-left)
  let whiteLayers = 9;
  for (let i = 0; i < whiteLayers; i++) {
    let t = i / (whiteLayers - 1);
    let wCx = cx - rx * 0.035 * t;
    let wCy = cy - ryTop * 0.18 * t;
    let wRx = rx * lerp(0.99, 0.78, t * 0.65);
    let wRyTop = ryTop * lerp(0.98, 0.56, t);
    let wRyBot = ryBot * lerp(0.35, -0.15, t);
    let wCol = lerpHex("#d0d7e3", "#ffffff", pow(t, 0.75));
    let pts = makeSaucerPoints(wCx, wCy, max(12, wRx), max(2, wRyTop), max(1, wRyBot), {
      ...baseOpts,
      pinch: pinch + 0.04 * t
    });
    washPoly(pts, wCol, lerp(28, 48, t));
  }

  // D. Pale peach internal cushion & rim glow (layered between cold white crest and lavender belly)
  let peachLayers = 8;
  for (let i = 0; i < peachLayers; i++) {
    let t = i / (peachLayers - 1);
    let pCx = cx - rx * 0.04 * (1 - t * 0.5);
    let pCy = cy + lerp(-ryTop * 0.12, ryBot * 0.18, t);
    let pRx = rx * lerp(0.98, 0.82, t);
    let pRyTop = ryTop * lerp(0.62, 0.22, t);
    let pRyBot = ryBot * lerp(0.55, 0.25, t);
    let pCol = lerpHex("#f3dfd6", "#d8b4ac", t);
    let pts = makeSaucerPoints(pCx, pCy, max(10, pRx), max(1.5, pRyTop), max(1.5, pRyBot), {
      ...baseOpts,
      pinch: pinch + 0.02
    });
    washPoly(pts, pCol, 24 * peachStrength);
  }

  // E. Lavender-grey underbelly & sculptural core shadow
  let bellyLayers = 10;
  for (let i = 0; i < bellyLayers; i++) {
    let t = i / (bellyLayers - 1);
    let bCx = cx + rx * 0.02 * t;
    let bCy = cy + lerp(ryTop * 0.05, ryBot * 0.38, t);
    let bRx = rx * lerp(0.96, 0.68, pow(t, 1.2));
    let bRyTop = ryTop * lerp(0.28, 0.04, t);
    let bRyBot = ryBot * lerp(0.92, 0.42, t);

    let c1 = "#939bab";
    let c2 = "#6f788c";
    let c3 = "#505a6e";
    let bCol = t < 0.5 ? lerpHex(c1, c2, t * 2) : lerpHex(c2, c3, (t - 0.5) * 2);

    let pts = makeSaucerPoints(bCx, bCy, max(10, bRx), max(1, bRyTop), max(1.5, bRyBot), {
      ...baseOpts,
      pinch: pinch + 0.05
    });
    washPoly(pts, bCol, lerp(22, 36, t) * shadowDepth);
  }

  // F. Internal laminar wafer rims (characteristic stacked-plate rings inside the lenticular lens)
  for (let w = 0; w < wafers; w++) {
    let wt = (w + 1) / (wafers + 1);
    let ringY = cy + lerp(-ryTop * 0.28, ryBot * 0.16, wt);
    let ringRx = rx * lerp(0.94, 0.86, wt);
    let ringTop = max(1.5, ryTop * 0.16);
    let ringBot = max(1.5, ryBot * 0.14);

    // Bright upper wafer lip (cold white to pale peach)
    let lipCol = w % 2 === 0 ? "#f7faff" : "#eed7ce";
    let lipPts = makeSaucerPoints(cx - 4, ringY - 1.8, ringRx, ringTop, ringBot * 0.5, {
      ...baseOpts,
      pinch: pinch + 0.06
    });
    washPoly(lipPts, lipCol, 34);

    // Cool lavender-grey recess immediately beneath wafer lip
    let recPts = makeSaucerPoints(cx + 3, ringY + 2.2, ringRx * 0.96, ringTop * 0.5, ringBot, {
      ...baseOpts,
      pinch: pinch + 0.06
    });
    washPoly(recPts, "#626c80", 28 * shadowDepth);
  }

  // G. Crisp top highlight crescent (cold white razor rim)
  let rimPts = makeSaucerPoints(
    cx - rx * 0.02,
    cy - ryTop * 0.26,
    rx * 0.88,
    max(2, ryTop * 0.68),
    max(1, ryTop * 0.12),
    { ...baseOpts, pinch: pinch + 0.08 }
  );
  washPoly(rimPts, "#ffffff", 42);

  // H. Glassy spray airbrushing over the saucer (blends layers into a stroke-free spray sheen)
  let sprayCount = floor(map(rx, 80, 550, 14, 52, true));
  for (let i = 0; i < sprayCount; i++) {
    let fracX = random(-0.78, 0.78);
    let span = random(0.15, 0.38);
    let x1 = cx + fracX * rx;
    let x2 = cx + constrain(fracX + span, -0.88, 0.88) * rx;
    let envM = pow(max(0.05, 1 - fracX * fracX), pinch);
    let zone = random();
    let yOff, sCol;
    if (zone < 0.35) {
      // Upper cold white / pale peach zone
      yOff = -random(0.15, 0.75) * ryTop * envM;
      sCol = random() < 0.6 ? "#f5f9fd" : "#edd6cd";
    } else if (zone < 0.68) {
      // Mid pale peach / pearlescent lavender zone
      yOff = random(-0.2, 0.3) * ryBot * envM;
      sCol = random() < 0.55 ? "#e5c8be" : "#c6cad6";
    } else {
      // Lower lavender-grey shadow zone
      yOff = random(0.2, 0.75) * ryBot * envM;
      sCol = random() < 0.5 ? "#7a8396" : "#5c667a";
    }
    brush.set("mist_spray", sCol, random(0.65, 1.25));
    brush.line(x1, cy + yOff, x2, cy + yOff + random(-1.5, 1.5));
  }
}

