function drawDistantHorizon() {
  // Soft horizon haze glow just above y = 925
  for (let i = 0; i < 8; i++) {
    let y = 890 + i * 9;
    washRectBand(-20, y, width + 40, 22, "#dfd4d0", 16);
  }

  // Far mountain chain (y ~ 912 to 965)
  let farRidge = [[-20, 980]];
  for (let x = -20; x <= width + 20; x += 18) {
    let n1 = noise(x * 0.0025, 10.4) * 34;
    let n2 = noise(x * 0.009, 22.1) * 11;
    // Dip slightly in the middle so the cairn has maximum breathing room against the sky/mist
    let valleyDip = exp(-pow((x - 600) / 340, 2)) * 16;
    let y = 912 + n1 + n2 + valleyDip;
    farRidge.push([x, y]);
  }
  farRidge.push([width + 20, 980]);
  washPoly(farRidge, "#677687", 175);
  washPoly(farRidge, "#586778", 95);

  // Subtle snow/ice-light facets on the far ridge
  for (let i = 2; i < farRidge.length - 3; i += 2) {
    let p1 = farRidge[i];
    let p2 = farRidge[i + 1];
    if (p2[1] > p1[1] - 1) {
      let facet = [
        p1,
        p2,
        [p2[0] - 12, p2[1] + 18],
        [p1[0] - 18, p1[1] + 14]
      ];
      washPoly(facet, "#8fa0b0", 55);
    }
  }

  // Mid-distance cold slate ridge (y ~ 930 to 990)
  let midRidge = [[-20, 1010]];
  for (let x = -20; x <= width + 20; x += 16) {
    let n1 = noise(x * 0.0032, 41.7) * 28;
    let n2 = noise(x * 0.012, 55.3) * 9;
    let valleyDip = exp(-pow((x - 600) / 280, 2)) * 12;
    let y = 928 + n1 + n2 + valleyDip;
    midRidge.push([x, y]);
  }
  midRidge.push([width + 20, 1010]);
  washPoly(midRidge, "#3f4f60", 190);
  washPoly(midRidge, "#334252", 110);

  // Glassy valley mist bands between distant ridges and foreground ridge
  for (let i = 0; i < 12; i++) {
    let my = map(i, 0, 11, 924, 962);
    let mCol = lerpHex("#d5ced0", "#8e9eae", i / 11);
    washRectBand(-20, my, width + 40, 10, mCol, 22);
    brush.set("air_spray", mCol, 1.1);
    brush.line(-20, my + 3, width + 20, my + 3);
