}

// ============================================================================
// 5. FOREGROUND ROCKY SLATE RIDGE
// ============================================================================

function ridgeCrestY(x) {
  // Rises gently to a natural slate pedestal around x = 600, y = 946
  let centerRise = -34 * exp(-pow((x - 600) / 370, 2));
  let flatPedestal = 6 * exp(-pow((x - 600) / 130, 2));
  let n1 = (noise(x * 0.004, 77.2) - 0.5) * 26;
  let n2 = (noise(x * 0.018, 91.8) - 0.5) * 8;
  // Flatten the immediate cairn seat (x in 460..740) so the base pebble sits solidly
  let seatSmooth = constrain( abs(x - 600) / 145, 0, 1);
  return 982 + centerRise + flatPedestal + (n1 + n2) * (0.25 + 0.75 * seatSmooth);
}

function drawForegroundRidge() {
  // Base dark wet slate mass
  let ridgePoly = [[-20, 1220]];
  for (let x = -20; x <= width + 20; x += 12) {
    ridgePoly.push([x, ridgeCrestY(x)]);
  }
  ridgePoly.push([width + 20, 1220]);

  washPoly(ridgePoly, "#141c24", 245);
  washPoly(ridgePoly, "#0f151c", 180);

  // Construct angular fractured slate slabs across the foreground slope
  let cols = 18;
  let rows = 6;
  let stepX = (width + 80) / cols;

  let grid = [];
  for (let r = 0; r <= rows; r++) {
    let rowPts = [];
    let tRow = pow(r / rows, 1.15);
    for (let c = 0; c <= cols; c++) {
      let bx = -40 + c * stepX;
      let crest = ridgeCrestY(bx);
      let by = lerp(crest, 1225, tRow);
      // Angular metamorphic slate step offsets (slanted slightly left-to-right)
      let jx = (r > 0 && r < rows) ? (noise(c * 0.7, r * 1.3, 12) - 0.5) * 34 : 0;
      let jy = (r > 0 && r < rows) ? (noise(c * 1.1, r * 0.9, 34) - 0.5) * 18 : 0;
      rowPts.push([bx + jx, by + jy]);
    }
    grid.push(rowPts);
  }

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      let pTL = grid[r][c];
      let pTR = grid[r][c + 1];
      let pBR = grid[r + 1][c + 1];
      let pBL = grid[r + 1][c];

      // Split slab into an upper sky-facing cleavage plane and a steeper dark step face
      let midL = [lerp(pTL[0], pBL[0], 0.52), lerp(pTL[1], pBL[1], 0.45)];
      let midR = [lerp(pTR[0], pBR[0], 0.58), lerp(pTR[1], pBR[1], 0.52)];

      let topFace = [pTL, pTR, midR, midL];
      let steepFace = [midL, midR, pBR, pBL];

      // Wet sky sheen on top-facing slate cleavage
      let distCenter = abs((pTL[0] + pTR[0]) * 0.5 - 600) / 600;
      let sheenTone = lerpHex("#52667a", "#2b3948", constrain(distCenter * 0.8 + random(-0.15, 0.15), 0, 1));
      washPoly(topFace, sheenTone, random(90, 155));

      // Secondary wet highlight strip near the top edge of the slab
      let rimFace = [
        pTL,
        pTR,
        [lerp(pTR[0], midR[0], 0.35), lerp(pTR[1], midR[1], 0.35)],
        [lerp(pTL[0], midL[0], 0.35), lerp(pTL[1], midL[1], 0.35)]
      ];
      washPoly(rimFace, "#7e93a6", random(45, 85));

      // Steep shadow fracture face
      let darkTone = random() < 0.5 ? "#0b1016" : "#121a22";
      washPoly(steepFace, darkTone, random(160, 220));

      // Coloured pencil cleavage striations across the slab
      let numLines = floor(random(10, 18));
      for (let k = 0; k < numLines; k++) {
        let f = k / numLines;
        let lx1 = lerp(pTL[0], pBL[0], f);
        let ly1 = lerp(pTL[1], pBL[1], f);
        let lx2 = lerp(pTR[0], pBR[0], f);
        let ly2 = lerp(pTR[1], pBR[1], f);

        let pCol = f < 0.45
          ? (random() < 0.5 ? "#889cae" : "#5a6e80")
          : (random() < 0.6 ? "#090d12" : "#222e3c");
        brush.set("fine_cpencil", pCol, random(0.6, 1.1));
        brush.line(lx1, ly1, lx2, ly2);
      }

      // Crisp dark fissure between slabs
      brush.set("cpencil", "#06080c", random(0.8, 1.3));
      brush.line(midL[0], midL[1], midR[0], midR[1]);
    }
  }

  // Spray atmospheric moisture and shadow depth across the lower ridge
  for (let i = 0; i < 65; i++) {
    let sx = random(-20, width + 20);
    let sy = random(ridgeCrestY(sx) + 5, 1195);
    let sCol = random() < 0.4 ? "#5a6f82" : "#0b1017";
    brush.set("mist_spray", sCol, random(0.8, 1.5));
    brush.line(sx - random(30, 80), sy, sx + random(30, 80), sy + random(-5, 5));
  }

  // Scatter crustose lichen and wet mica glints on foreground ridge slabs
  for (let i = 0; i < 28; i++) {
    let lx = random(60, 1140);
    let ly = random(ridgeCrestY(lx) + 12, 1160);
    drawLichenColony(lx, ly, random(6, 16), null);
  }

  for (let i = 0; i < 160; i++) {
    let gx = random(30, 1170);
    let gy = random(ridgeCrestY(gx) + 2, 1180);
    let gCol = random() < 0.65 ? "#dce9f5" : "#f2e2dc";
    brush.set("mica_glint", gCol, random(0.6, 1.2));
    let len = random(1.2, 3.5);
    brush.line(gx, gy, gx + len, gy + random(-0.6, 0.6));
  }
}

// ============================================================================
// 6. HYPERREAL CAIRN OF SMOOTH, WET-DARK SLATE PEBBLES
// ============================================================================

function drawSlateCairn() {
  // 9 stacked lens-like slate pebbles, sitting on the ridge pedestal at (600, 954)
  let stones = [
    { cx: 600, cy: 934, rx: 136, ryTop: 28, ryBot: 23, tilt: -1.1, seed: 1, lichenSide: 1 },
    { cx: 597, cy: 889, rx: 118, ryTop: 25, ryBot: 21, tilt: 1.5,  seed: 2, lichenSide: -1 },
    { cx: 603, cy: 847, rx: 102, ryTop: 22, ryBot: 19, tilt: -1.7, seed: 3, lichenSide: 1 },
    { cx: 598, cy: 809, rx: 88,  ryTop: 20, ryBot: 17, tilt: 1.2,  seed: 4, lichenSide: 0 },
    { cx: 602, cy: 775, rx: 75,  ryTop: 18, ryBot: 15, tilt: -0.9, seed: 5, lichenSide: -1 },
    { cx: 599, cy: 745, rx: 64,  ryTop: 16, ryBot: 13, tilt: 1.9,  seed: 6, lichenSide: 1 },
    { cx: 601, cy: 719, rx: 52,  ryTop: 14, ryBot: 11, tilt: -1.4, seed: 7, lichenSide: 0 },
    { cx: 599, cy: 696, rx: 41,  ryTop: 12, ryBot: 9.5, tilt: 0.8, seed: 8, lichenSide: -1 },
    { cx: 600, cy: 676, rx: 29,  ryTop: 9.5, ryBot: 8, tilt: -0.5, seed: 9, lichenSide: 1 }
  ];

  // Anchor shadow & wet dark reflection of Stone 0 onto the rocky ridge pedestal
  let basePedestalShadow = makePebblePoints(604, 955, 148, 10, 16, -0.5, 99, 44);
  washPoly(basePedestalShadow, "#06080c", 210);
  let baseWetRefl = makePebblePoints(602, 962, 128, 8, 22, -0.5, 98, 44);
  washPoly(baseWetRefl, "#0b1017", 150);

  // Draw each stone from bottom to top
  for (let i = 0; i < stones.length; i++) {
    let s = stones[i];

    // If i > 0, cast a dark wet reflection and tight occlusion crevice onto the top of stone i-1
    if (i > 0) {
      let below = stones[i - 1];
      let contactY = s.cy + s.ryBot * 0.88;
      let contactRx = s.rx * 0.84;

      // Wet dark reflection pool on the glossy upper dome of the lower stone
      let reflPts = makePebblePoints(
        s.cx + 2,
        contactY + 4,
        contactRx * 0.95,
        below.ryTop * 0.22,
        below.ryTop * 0.55,
        below.tilt,
        i * 31
      );
      washPoly(reflPts, "#0b1017", 155);

      // Razor-tight ambient occlusion shadow right at the contact seam
      let occPts = makePebblePoints(
        s.cx,
        contactY,
        contactRx * 0.78,
        3.5,
        5.5,
        s.tilt * 0.5,
        i * 19
      );
      washPoly(occPts, "#040609", 235);
    }

    drawSingleSlatePebble(s, i);

    // Re-reinforce the ultra-dark contact line under the pebble belly so it sits with heavy gravity
    let seamPts = [];
    let steps = 28;
    let cosT = cos(s.tilt);
    let sinT = sin(s.tilt);
    for (let k = 0; k <= steps; k++) {
      let ang = map(k, 0, steps, 32, 148);
      let ux = cos(ang) * 0.78;
      let uy = sin(ang);
      let lx = ux * s.rx;
      let ly = uy * s.ryBot * (1 - 0.1 * pow(uy, 2));
      let px = s.cx + lx * cosT - ly * sinT;
      let py = s.cy + lx * sinT + ly * cosT;
      seamPts.push([px, py]);
    }
    brush.set("fine_cpencil", "#040609", 1.15);
    brush.spline(seamPts, 0.3);
  }
}

function drawSingleSlatePebble(s, index) {
  let { cx, cy, rx, ryTop, ryBot, tilt, seed, lichenSide } = s;
  let cosT = cos(tilt);
  let sinT = sin(tilt);

  // Helper to transform local stone coordinates (lx, ly) into canvas coordinates
  function toWorld(lx, ly) {
    return [cx + lx * cosT - ly * sinT, cy + lx * sinT + ly * cosT];
  }

  let mainPts = makePebblePoints(cx, cy, rx, ryTop, ryBot, tilt, seed, 56);

  // --------------------------------------------------------------------------
  // STAGE 1: WET-DARK SLATE BASE & VOLUMETRIC CORE (Wash + Spray)
  // --------------------------------------------------------------------------
  washPoly(mainPts, "#131b24", 248);
  washPoly(mainPts, "#18222d", 180);

  // Deep obsidian-slate shadow belly on the lower and right-hand underside
  for (let k = 0; k < 7; k++) {
    let t = k / 6;
    let [scx, scy] = toWorld(rx * lerp(0.02, 0.1, t), ryBot * lerp(0.12, 0.44, t));
    let sPts = makePebblePoints(
      scx, scy,
      rx * lerp(0.96, 0.74, t),
      ryTop * lerp(0.45, 0.05, t),
      ryBot * lerp(0.88, 0.46, t),
      tilt, seed + 10
    );
    let shCol = lerpHex("#151e28", "#070a0f", t);
    washPoly(sPts, shCol, 55);
  }

  // Cool indigo-slate and lavender-slate midtone body
  for (let k = 0; k < 5; k++) {
    let t = k / 4;
    let [mcx, mcy] = toWorld(-rx * 0.04 * t, -ryTop * lerp(0.02, 0.22, t));
    let mPts = makePebblePoints(
      mcx, mcy,
      rx * lerp(0.95, 0.78, t),
      ryTop * lerp(0.86, 0.58, t),
      ryBot * lerp(0.52, 0.18, t),
      tilt, seed + 20
    );
    let midCol = lerpHex("#222f3d", "#3d4d5f", t);
    washPoly(mPts, midCol, 42);
  }

  // Secondary sky-bounce reflection along the extreme lower-left and far-right curved rim
  let rimBouncePts = makePebblePoints(
    cx - rx * 0.08, cy + ryBot * 0.15,
    rx * 0.94, ryTop * 0.2, ryBot * 0.78,
    tilt, seed + 30
  );
  washPoly(rimBouncePts, "#38495a", 24);

  // Spray underpainting over the stone interior
  let sprayPasses = floor(map(rx, 28, 136, 12, 34));
  for (let i = 0; i < sprayPasses; i++) {
    let u = random(-0.72, 0.72);
    let v = random(-0.65, 0.65);
    if (u * u + v * v > 0.78) continue;
    let [px1, py1] = toWorld(u * rx - rx * 0.15, v * (v < 0 ? ryTop : ryBot));
    let [px2, py2] = toWorld(u * rx + rx * 0.15, v * (v < 0 ? ryTop : ryBot));
    let spCol = v < -0.15 ? "#5c7084" : (v < 0.2 ? "#2b3948" : "#0b0f15");
    brush.set("mist_spray", spCol, random(0.45, 0.85));
    brush.line(px1, py1, px2, py2);
  }

  // --------------------------------------------------------------------------
  // STAGE 2: GLASSY WATER SHEEN ON WET STONE (Reflecting the Lenticular Sky)
  // --------------------------------------------------------------------------
  // Because the slate is wet, water creates a high-contrast specular reflection
  // across the upper-left and top dome, mirroring the cold white, pale peach,
  // and lavender-grey of the lenticular clouds above.
  let sheenLayers = 11;
  for (let k = 0; k < sheenLayers; k++) {
    let t = k / (sheenLayers - 1);
    let [shX, shY] = toWorld(
      -rx * lerp(0.05, 0.16, t),
      -ryTop * lerp(0.18, 0.56, t)
    );
    let shRx = rx * lerp(0.86, 0.42, pow(t, 0.9));
    let shRyTop = ryTop * lerp(0.68, 0.22, t);
    let shRyBot = ryTop * lerp(0.32, 0.04, t);

    let shCol;
    if (t < 0.35) {
      shCol = lerpHex("#495c70", "#7b8ea1", t / 0.35);
    } else if (t < 0.68) {
      // Lavender-grey & pale peach cloud reflection in the wet film
      shCol = lerpHex("#8e99ab", "#d8c6c2", (t - 0.35) / 0.33);
    } else {
      // Cold white sky specular reflection
      shCol = lerpHex("#d8e3ec", "#f7fbff", (t - 0.68) / 0.32);
    }

    let shPts = makePebblePoints(
      shX, shY,
      max(6, shRx), max(1.8, shRyTop), max(1.0, shRyBot),
      tilt - 1.2 * t, seed + 40 + k, 40
    );
    washPoly(shPts, shCol, lerp(28, 52, t));
  }

  // Wet refractive dark boundary ring just below the specular water sheen
  // (Wet stone is noticeably darker right next to the specular sky reflection)
  let wetRingPts = [];
  for (let i = 0; i <= 24; i++) {
    let u = map(i, 0, 24, -0.82, 0.78);
    let archY = -ryTop * 0.12 * (1 - u * u) + ryBot * 0.08 * u;
    wetRingPts.push(toWorld(u * rx, archY));
  }
  brush.set("cpencil", "#0e151d", 0.9);
  brush.spline(wetRingPts, 0.35);

  // --------------------------------------------------------------------------
  // STAGE 3: COLOURED PENCIL OVER SPRAY (Cross-contour & Slate Bedding Lines)
  // --------------------------------------------------------------------------
  // A. Sedimentary / metamorphic slate cleavage striations wrapping across the 3D lens
  let numStrata = floor(map(ryTop + ryBot, 16, 52, 26, 68));
  for (let i = 0; i < numStrata; i++) {
    let v = map(i, 0, numStrata - 1, -0.92, 0.92) + random(-0.02, 0.02);
    let maxU = sqrt(max(0.01, 1 - v * v * 0.96));

    // Break into 1 or 2 natural pencil strokes along the stratum
    let segs = random() < 0.6 ? 2 : 1;
    for (let sIdx = 0; sIdx < segs; sIdx++) {
      let uStart = segs === 1 ? -maxU * random(0.65, 0.94) : (sIdx === 0 ? -maxU * 0.92 : -maxU * 0.15);
      let uEnd = segs === 1 ? maxU * random(0.65, 0.94) : (sIdx === 0 ? maxU * 0.2 : maxU * 0.92);
      if (uEnd - uStart < 0.2) continue;

      let curvePts = [];
      let nSteps = 9;
      for (let m = 0; m <= nSteps; m++) {
        let u = lerp(uStart, uEnd, m / nSteps);
        // 3D lens cross-contour curvature: bows up in upper half, bows down in lower half
        let domeBow = (1 - (u * u) / (maxU * maxU + 0.001)) * 0.16 * v;
        let vCurved = v + domeBow;
        let ly = vCurved < 0 ? vCurved * ryTop : vCurved * ryBot;
        let lx = u * rx;
        curvePts.push(toWorld(lx, ly));
      }

      // Pick coloured pencil pigment according to lighting zone on the wet stone
      let pCol, pWeight;
      let biasLeft = (uStart + uEnd) * 0.5;
      if (v < -0.52 && biasLeft < 0.25) {
        // Core water sheen burnishing: cold white, icy blue, pale peach
        let r = random();
        pCol = r < 0.48 ? "#eef6fc" : (r < 0.78 ? "#c5d6e6" : "#e6cfc7");
        pWeight = random(0.65, 1.15);
      } else if (v < -0.22) {
        // Upper sheen transition: lavender-grey, steel-blue, silver-slate
        let r = random();
        pCol = r < 0.45 ? "#8fa2b4" : (r < 0.78 ? "#62778b" : "#b8bfd1");
        pWeight = random(0.55, 0.95);
      } else if (v < 0.18) {
        // Wet dark slate mid-zone: deep prussian-slate, graphite-blue, dark violet-slate
        let r = random();
        pCol = r < 0.45 ? "#17212c" : (r < 0.78 ? "#2d3d4e" : "#444b5e");
        pWeight = random(0.6, 1.0);
      } else if (v < 0.68) {
        // Deep shadow belly: charcoal-obsidian, wet black-slate
        pCol = random() < 0.65 ? "#080c11" : "#121a24";
        pWeight = random(0.65, 1.1);
      } else {
        // Extreme bottom rim: subtle dark slate with faint sky-bounce on left/right tips
        pCol = abs(biasLeft) > 0.35 ? "#394a5b" : "#06090e";
        pWeight = random(0.55, 0.9);
      }

      let bName = random() < 0.68 ? "fine_cpencil" : "cpencil";
      brush.set(bName, pCol, pWeight);
      brush.spline(curvePts, 0.3);
    }
  }

  // B. Fine oblique cross-hatching pencil strokes to model the rounded lens curvature at the flanks
  let flankStrokes = floor(map(rx, 28, 136, 14, 36));
  for (let i = 0; i < flankStrokes; i++) {
    let side = random() < 0.5 ? -1 : 1;
    let u0 = side * random(0.35, 0.86);
    let v0 = random(-0.45, 0.45);
    if (u0 * u0 + v0 * v0 > 0.85) continue;

    let u1 = u0 + side * random(0.08, 0.18);
    let v1 = v0 + random(0.15, 0.32);
    let p1 = toWorld(u0 * rx, v0 * (v0 < 0 ? ryTop : ryBot));
    let p2 = toWorld(u1 * rx, v1 * (v1 < 0 ? ryTop : ryBot));

    let fCol = side < 0
      ? (v0 < 0 ? "#7a8fa3" : "#243240")
      : (v0 < 0 ? "#3c4d5e" : "#0b1017");
    brush.set("fine_cpencil", fCol, random(0.45, 0.8));
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // C. Occasional hairline quartz or slate cleavage micro-vein on larger pebbles
  if (rx > 50 && index % 2 === 0) {
    let veinPts = [];
    let uV = random(-0.35, 0.25);
    for (let k = 0; k <= 6; k++) {
      let t = k / 6;
      let u = uV + (t - 0.5) * 0.45 + sin(t * 180) * 0.03;
      let v = lerp(-0.65, 0.55, t);
      let ly = v < 0 ? v * ryTop : v * ryBot;
      veinPts.push(toWorld(u * rx, ly));
    }
    brush.set("fine_cpencil", "#9eb0c0", 0.55);
    brush.spline(veinPts, 0.25);
    // Thin dark shadow edge alongside the vein
    let veinShadowPts = veinPts.map(p => [p[0] + 1.2, p[1] + 0.8]);
    brush.set("fine_cpencil", "#0c1219", 0.5);
    brush.spline(veinShadowPts, 0.25);
  }

  // D. Crisp wet water-film rim highlight along the top-left lens contour
  let topRimPts = [];
  for (let i = 0; i <= 18; i++) {
    let ang = map(i, 0, 18, 202, 318);
    let ux = cos(ang);
    let uy = sin(ang);
    let lensEnv = pow(max(0.001, 1 - ux * ux), 0.08);
    let lx = ux * rx * 0.96;
    let ly = uy * ryTop * lensEnv * 0.93;
    topRimPts.push(toWorld(lx, ly));
  }
  brush.set("fine_cpencil", "#e8f2fa", map(rx, 28, 136, 0.65, 1.15));
  brush.spline(topRimPts, 0.35);

  // Brightest core specular water streak inside the upper-left dome
  let coreSheenPts = [];
  for (let i = 0; i <= 12; i++) {
    let ang = map(i, 0, 12, 224, 288);
    let ux = cos(ang);
    let uy = sin(ang);
    let lx = ux * rx * 0.78;
    let ly = uy * ryTop * 0.76;
    coreSheenPts.push(toWorld(lx, ly));
  }
  brush.set("mica_glint", "#ffffff", map(rx, 28, 136, 0.7, 1.25));
  brush.spline(coreSheenPts, 0.35);

  // Subtle contour definition around the shadow underside of the pebble
  let botRimPts = [];
  for (let i = 0; i <= 20; i++) {
    let ang = map(i, 0, 20, 15, 165);
    let ux = cos(ang);
    let uy = sin(ang);
    let lx = ux * rx * 0.98;
    let ly = uy * ryBot * (1 - 0.1 * pow(uy, 2)) * 0.98;
    botRimPts.push(toWorld(lx, ly));
  }
  brush.set("fine_cpencil", "#06090e", 0.95);
  brush.spline(botRimPts, 0.35);

  // --------------------------------------------------------------------------
  // STAGE 4: LICHEN SPECKS (Crustose saxicolous colonies on stone flanks)
  // --------------------------------------------------------------------------
  if (lichenSide !== 0) {
    let numColonies = floor(map(rx, 28, 136, 1, 4));
    for (let c = 0; c < numColonies; c++) {
      let lu = lichenSide * random(0.28, 0.68);
      let lv = random(-0.22, 0.38);
      let [lx, ly] = toWorld(lu * rx, lv * (lv < 0 ? ryTop : ryBot));
      let colonyRad = map(rx, 28, 136, 4.5, 13) * random(0.75, 1.2);
      drawLichenColony(lx, ly, colonyRad, mainPts);
    }
  }
  // Tiny isolated lichen specks across the stone
  let tinySpecks = floor(map(rx, 28, 136, 6, 20));
  for (let i = 0; i < tinySpecks; i++) {
    let u = random(-0.78, 0.78);
    let v = random(-0.5, 0.55);
    if (u * u + v * v > 0.72) continue;
    let [sx, sy] = toWorld(u * rx, v * (v < 0 ? ryTop : ryBot));
    let lCols = ["#8fa495", "#aebfa8", "#a89560", "#c2b078", "#cbd4cf"];
    let lCol = random(lCols);
    brush.set("fine_cpencil", lCol, random(0.55, 0.95));
    brush.line(sx, sy, sx + random(0.8, 2.0), sy + random(-0.7, 0.7));
  }

  // --------------------------------------------------------------------------
  // STAGE 5: MICA GLINTS & WATER FILM MICRO-BEADS
  // --------------------------------------------------------------------------
  let numGlints = floor(map(rx, 28, 136, 16, 56));
  for (let i = 0; i < numGlints; i++) {
    // Concentrate glints along the wet sheen boundary and upper cleavage steps
    let u = random(-0.82, 0.78);
    let v = random() < 0.72 ? random(-0.82, -0.05) : random(-0.05, 0.45);
    if (u * u + v * v > 0.82) continue;

    let [gx, gy] = toWorld(u * rx, v * (v < 0 ? ryTop : ryBot));
    if (!pointInPoly(gx, gy, mainPts)) continue;

    let glintCols = ["#ffffff", "#e6f3ff", "#f7e6df", "#d4e6f7"];
    let gCol = random(glintCols);
    let gW = random(0.55, 1.35);

    // Tiny dark micro-shadow immediately under the mineral flake for hyperreal pop
    brush.set("fine_cpencil", "#090e14", gW * 0.7);
    brush.line(gx, gy + 0.9, gx + 1.6, gy + 1.1);

    // Bright crystalline mica glint
    brush.set("mica_glint", gCol, gW);
    let gLen = random(0.9, 2.6);
    let gAng = tilt + random(-12, 12);
    brush.line(gx, gy, gx + cos(gAng) * gLen, gy + sin(gAng) * gLen);
  }
}

// Renders a hyper-detailed crustose lichen patch (pale thallus rim, olive/sage/ochre areoles, dark apothecia)
function drawLichenColony(cx, cy, radius, clipPoly) {
  let palettes = [
    // Seafoam & sage crustose lichen
    { rim: "#cfd9d2", body: "#8ea395", inner: "#6c8273", spore: "#1e2621" },
    // Pale mustard-ochre & ash lichen (Xanthoria / Rhizocarpon style)
    { rim: "#d8d2be", body: "#b59f66", inner: "#8f7a47", spore: "#242016" },
    // Cold silver-grey & pale olive lichen
    { rim: "#d5dce0", body: "#9aa69e", inner: "#738078", spore: "#1a201e" }
  ];
  let pal = random(palettes);

  let specks = floor(map(radius, 4, 16, 10, 34));
  for (let i = 0; i < specks; i++) {
    let ang = random(360);
    let dist = pow(random(), 0.65) * radius;
    let px = cx + cos(ang) * dist * 1.25;
    let py = cy + sin(ang) * dist * 0.72;

    if (clipPoly && !pointInPoly(px, py, clipPoly)) continue;

    let t = dist / radius;
    let col = t > 0.72 ? pal.rim : (t > 0.35 ? pal.body : pal.inner);

    // Tiny shadow under crust edge
    if (t > 0.65 && random() < 0.5) {
      brush.set("fine_cpencil", "#0b1016", 0.55);
      brush.line(px, py + 0.9, px + 1.4, py + 1.0);
    }

    brush.set("fine_cpencil", col, random(0.6, 1.05));
    let len = random(0.9, 2.2);
    brush.line(px, py, px + len, py + random(-0.6, 0.6));

    // Tiny dark fruiting body (apothecium) in the center of the colony
    if (t < 0.45 && random() < 0.35) {
      brush.set("fine_cpencil", pal.spore, 0.65);
      brush.line(px, py, px + 0.9, py + 0.2);
    }
  }
}

// Hyperrealistic Watercolour & Pencil Study:
// Block-Printed Indigo & Madder Cotton Draped Over Pale Sand Dunes

const PALETTE = {
  paper: "#f4ece0",
  paperSun: "#f8f2e7",
  paperWarm: "#eadcc7",
