// Precomputed 3D surface & lighting grid for fast, exact interpolation
const GRID_U = 120;
const GRID_V = 96;
let surfGrid = [];

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(4271);
  noiseSeed(4271);

  // Custom brushes for crisp resist lines, crackle veins, and stipple sand
  brush.add("resistPen", {
    type: "default",
    weight: 0.9,
    scatter: 0.04,
    sharpness: 0.85,
    grain: 0.25,
    opacity: 210,
    spacing: 0.18,
    pressure: [0.85, 1.0, 0.85],
    noise: 0.25
  });

  brush.add("crackle", {
    type: "default",
    weight: 0.45,
    scatter: 0.08,
    sharpness: 0.9,
    grain: 0.4,
    opacity: 150,
    spacing: 0.2,
    pressure: [0.3, 1.1, 0.2],
    noise: 0.7
  });

  brush.add("paperGouache", {
    type: "marker",
    weight: 1.4,
    scatter: 0.02,
    opacity: 235,
    spacing: 0.15,
    pressure: [0.9, 1.0, 0.9],
    markerTip: false,
    noise: 0.15
  });

  brush.add("sandStipple", {
    type: "custom",
    weight: 1.1,
    scatter: 0.35,
    opacity: 220,
    spacing: 0.9,
    pressure: [0.8, 1.2, 0.7],
    tip: (_m) => {
      _m.rotate(25);
      _m.rect(-0.6, -0.4, 1.2, 0.8);
    },
    rotate: "random",
    markerTip: false,
    noise: 0.5
  });

  buildSurfaceGrid();
}

// Asymmetric heavy cotton fold wave: sharper crests, wide sagging catenary troughs
function foldWave(phi) {
  return (Math.cos(phi) + 0.34 * Math.cos(2 * phi) + 0.09 * Math.cos(3 * phi)) / 1.43;
}

function foldWaveDeriv(phi) {
  return (-Math.sin(phi) - 0.68 * Math.sin(2 * phi) - 0.27 * Math.sin(3 * phi)) / 1.43;
}

// Raw 3D cloth & dune surface evaluation at fabric coordinates (u, v) in [0, 1]
function evalClothRaw(u, v) {
  // Subtle camera perspective: top edge (v=0) is slightly further up the dune slope
  let persp = 0.89 + 0.17 * v;

  // Base planar projection of thrown cloth
  let baseU_x = 118 + u * 1125;
  let baseU_y = 595 - (u - 0.5) * 95 + Math.sin(u * Math.PI * 1.25 - 0.3) * 32;

  let halfWidth = 478 * persp * (0.95 + 0.06 * Math.sin(u * 4.5 + 0.4));
  let x0 = baseU_x + (v - 0.5) * 105 - (1 - u) * Math.sin(v * Math.PI) * 18;
  let y0 = baseU_y + (v - 0.5) * 2.0 * halfWidth;

  // 1. Underlying broad sand-dune topography
  let duneZ =
    48 * Math.cos(2 * Math.PI * (0.72 * u - 0.42 * v - 0.12)) +
    28 * Math.sin(Math.PI * v * 1.1 + 0.3) -
    22 * Math.cos(Math.PI * (u * 1.4 + v * 0.8));

  // 2. Primary heavy diagonal folds of the wet cotton cloth
  let bend = 0.22 * Math.sin(Math.PI * u * 1.1) * Math.cos(Math.PI * v * 0.9);
  let phi1 = 2 * Math.PI * (3.55 * u - 1.42 * v + bend - 0.08);
  let env1 = 0.78 + 0.28 * Math.sin(Math.PI * (0.85 * u + 0.15)) * (0.85 + 0.2 * Math.cos(Math.PI * v));
  let w1 = foldWave(phi1) * env1;
  let dw1 = foldWaveDeriv(phi1) * env1;
  let z1 = 56 * w1;

  // 3. Secondary counter-folds & sagging catenary hollows
  let phi2 = 2 * Math.PI * (1.75 * u + 2.15 * v - 0.16 * Math.cos(2 * Math.PI * u) + 0.15);
  let env2 = 0.55 + 0.45 * Math.cos(Math.PI * (u - v * 0.7));
  let w2 = foldWave(phi2) * env2;
  let dw2 = foldWaveDeriv(phi2) * env2;
  let z2 = 29 * w2;

  // 4. Pinched tension creases that pull across the hollows
  let cDist1 = (u - 0.34) * 0.82 + (v - 0.48) * 0.57;
  let crease1 = 24 * Math.exp(-(cDist1 * cDist1) / (2 * 0.032 * 0.032)) * Math.exp(-Math.pow((v - 0.48) / 0.36, 2));
  let dCrease1 = crease1 * (-cDist1 / (0.032 * 0.032));

  let cDist2 = (u - 0.71) * 0.76 - (v - 0.52) * 0.65;
  let crease2 = 22 * Math.exp(-(cDist2 * cDist2) / (2 * 0.036 * 0.036)) * Math.exp(-Math.pow((v - 0.52) / 0.38, 2));
  let dCrease2 = crease2 * (-cDist2 / (0.036 * 0.036));

  // 5. Selvedge border ripples where damp cloth hem rests on sand
  let edgeProx = Math.exp(-v / 0.09) + Math.exp(-(1 - v) / 0.09) + 0.7 * Math.exp(-u / 0.08);
  let phi3 = 2 * Math.PI * (8.5 * u + 3.2 * v);
  let z3 = 11 * Math.sin(phi3) * edgeProx;

  // Organic fine cotton ripple noise
  let nVal = (noise(u * 6.5 + 10, v * 6.5 + 20) - 0.5) * 14;

  // Total 3D height Z above reference plane
  let z = duneZ * 0.45 + z1 + z2 + crease1 + crease2 + z3 + nVal;
  let foldHeight = z1 + z2 + crease1 + crease2 + z3; // height relative to dune

  // Lateral fabric bunching (conservation of cloth arc length across folds)
  let bunchX = -17.5 * dw1 * 0.91 - 8.5 * dw2 * 0.62 - 0.22 * dCrease1 - 0.20 * dCrease2;
  let bunchY = 17.5 * dw1 * 0.41 - 8.5 * dw2 * 0.78 - 0.16 * dCrease1 + 0.18 * dCrease2;

  // Project 3D height Z into 2D oblique view
  let x = x0 + bunchX - 0.24 * z;
  let y = y0 + bunchY - 0.74 * z;

  return { x, y, z, foldHeight, duneZ, x0, y0, w1, w2 };
}

function buildSurfaceGrid() {
  surfGrid = new Array(GRID_U + 1);
  for (let i = 0; i <= GRID_U; i++) {
    surfGrid[i] = new Array(GRID_V + 1);
    let u = i / GRID_U;
    for (let j = 0; j <= GRID_V; j++) {
      let v = j / GRID_V;
      surfGrid[i][j] = evalClothRaw(u, v);
    }
  }

  // Compute 3D normals, foreshortening, and hard-sun illumination with ray-marched cast shadows
  // Hard sun comes from upper-left-front
  let sunX = -0.62, sunY = -0.44, sunZ = 0.65;
  let sunLen = Math.hypot(sunX, sunY, sunZ);
  sunX /= sunLen; sunY /= sunLen; sunZ /= sunLen;

  for (let i = 0; i <= GRID_U; i++) {
    for (let j = 0; j <= GRID_V; j++) {
      let i0 = Math.max(0, i - 1), i1 = Math.min(GRID_U, i + 1);
      let j0 = Math.max(0, j - 1), j1 = Math.min(GRID_V, j + 1);

      let pU0 = surfGrid[i0][j], pU1 = surfGrid[i1][j];
      let pV0 = surfGrid[i][j0], pV1 = surfGrid[i][j1];

      let dux = pU1.x0 - pU0.x0, duy = pU1.y0 - pU0.y0, duz = (pU1.z - pU0.z) * 1.45;
      let dvx = pV1.x0 - pV0.x0, dvy = pV1.y0 - pV0.y0, dvz = (pV1.z - pV0.z) * 1.45;

      // Cross product Tu x Tv (oriented upward toward viewer +Z)
      let nx = duy * dvz - duz * dvy;
      let ny = duz * dvx - dux * dvz;
      let nz = dux * dvy - duy * dvx;
      if (nz < 0) { nx = -nx; ny = -ny; nz = -nz; }
      let nLen = Math.hypot(nx, ny, nz) || 1;
      nx /= nLen; ny /= nLen; nz /= nLen;

      // Direct Lambertian dot product
      let ndotl = nx * sunX + ny * sunY + nz * sunZ;

      // Ray-march toward sun in (u, v) grid to detect cast shadows from fold crests
      let castShadow = 0;
      let curZ = surfGrid[i][j].z;
      for (let step = 1; step <= 14; step++) {
        let su = i - step * 0.72;
        let sv = j - step * 0.36;
        if (su < 0 || sv < 0 || su > GRID_U || sv > GRID_V) break;
        let si = Math.round(su), sj = Math.round(sv);
        let sampleZ = surfGrid[si][sj].z;
        let rayZ = curZ + step * 5.8;
        if (sampleZ > rayZ) {
          castShadow = Math.min(1.0, (sampleZ - rayZ) / 14.0);
          break;
        }
      }

      // Hard sun response: crisp transition at terminator + deep cool trough ambient occlusion
      let direct = constrain((ndotl - 0.08) / 0.55, 0, 1);
      // Sharpen terminator for hard desert sun
      direct = direct * direct * (3 - 2 * direct);
      direct *= (1.0 - 0.88 * castShadow);

      let troughAO = constrain((surfGrid[i][j].foldHeight + 45) / 95, 0, 1);
      let light = constrain(0.12 + 0.72 * direct + 0.16 * troughAO, 0, 1);

      // 2D Jacobian foreshortening factor (how compressed the surface is on screen)
      let sxU = pU1.x - pU0.x, syU = pU1.y - pU0.y;
      let sxV = pV1.x - pV0.x, syV = pV1.y - pV0.y;
      let area2D = Math.abs(sxU * syV - syU * sxV);
      let baseArea = Math.abs(dux * dvy - duy * dvx) || 1;
      let compression = constrain(area2D / baseArea, 0.18, 1.35);

      surfGrid[i][j].light = light;
      surfGrid[i][j].direct = direct;
      surfGrid[i][j].castShadow = castShadow;
      surfGrid[i][j].troughAO = troughAO;
      surfGrid[i][j].compression = compression;
      surfGrid[i][j].nx = nx;
      surfGrid[i][j].ny = ny;
    }
  }
}

// Bilinear lookup of surface point and lighting at any (u, v)
function getClothPoint(u, v) {
  let cu = constrain(u, 0, 1) * GRID_U;
  let cv = constrain(v, 0, 1) * GRID_V;
  let i0 = Math.floor(cu), j0 = Math.floor(cv);
  let i1 = Math.min(GRID_U, i0 + 1), j1 = Math.min(GRID_V, j0 + 1);
  let fu = cu - i0, fv = cv - j0;

  let p00 = surfGrid[i0][j0], p10 = surfGrid[i1][j0];
  let p01 = surfGrid[i0][j1], p11 = surfGrid[i1][j1];

  let w00 = (1 - fu) * (1 - fv);
  let w10 = fu * (1 - fv);
  let w01 = (1 - fu) * fv;
  let w11 = fu * fv;

  return {
    x: p00.x * w00 + p10.x * w10 + p01.x * w01 + p11.x * w11,
    y: p00.y * w00 + p10.y * w10 + p01.y * w01 + p11.y * w11,
    z: p00.z * w00 + p10.z * w10 + p01.z * w01 + p11.z * w11,
    foldHeight: p00.foldHeight * w00 + p10.foldHeight * w10 + p01.foldHeight * w01 + p11.foldHeight * w11,
    light: p00.light * w00 + p10.light * w10 + p01.light * w01 + p11.light * w11,
    direct: p00.direct * w00 + p10.direct * w10 + p01.direct * w01 + p11.direct * w11,
    compression: p00.compression * w00 + p10.compression * w10 + p01.compression * w01 + p11.compression * w11
  };
}

function draw() {
  translate(-width / 2, -height / 2);

  // 1. Warm rag paper ground
  background(PALETTE.paper);

  // 2. Exposed pale sand dunes & wind ripples + cast shadow of cloth onto sand
  drawSandDunesAndCastShadows();

  // 3. Base warm tannin/cotton undertone on the cloth
  drawClothBaseUndertone();

  // 4. Batched watercolour layers: Deep Indigo, Madder-Red, and Muted Earth compartments
  drawBatchedWatercolourPattern();

  // 5. Crisp reserved white & black geometric lattice + rows of tiny bare-paper stars
  drawGeometricLatticeAndStars();

  // 6. Faint resist crackle bleed along the reserved white lines and stars
  drawResistCrackleBleed();

  // 7. Hard sun & deep, cool trough shadows (watercolour shadow glazes + drapery hatching + crest weave)
  drawHardSunAndTroughShadows();

  // 8. Cotton selvedge hems, left-end warp fringes, and encroaching sand drift
  drawSelvedgesAndFringes();

  // 9. Scattered sand grains in fine pencil stipple across the cloth and troughs
  drawScatteredSandGrains();

  noLoop();
}

// ============================================================================
// STAGE 2: PALE SAND DUNES, WIND RIPPLES & CLOTH CAST SHADOWS
// ============================================================================
function drawSandDunesAndCastShadows() {
  brush.noStroke();

  // Upper sand dune washes (above v=0 edge and left of u=0 edge)
  brush.fill(PALETTE.sandLight, 115);
  brush.fillBleed(0.25, "out");
  brush.fillTexture(0.45, 0.25);
  drawPolygonFill([
    [-20, -20], [1220, -20], [1220, 210], [600, 180], [220, 270], [210, 1150], [-20, 1150]
  ]);

  // Lower sand dune washes (below v=1 edge)
  brush.fill(PALETTE.sandMid, 130);
  drawPolygonFill([
    [-20, 960], [600, 980], [1220, 960], [1220, 1220], [-20, 1220]
  ]);

  // Warm ochre dune swells
  brush.fill(PALETTE.sandOchre, 95);
  brush.fillBleed(0.3, "out");
  drawPolygonFill([
    [-20, -20], [780, -20], [540, 155], [140, 210], [-20, 420]
  ]);
  drawPolygonFill([
    [320, 1045], [880, 1020], [1220, 995], [1220, 1220], [240, 1220]
  ]);

  // Cool earth shadow on lee slope of upper-right and lower-left dune swells
  brush.fill(PALETTE.sandShadow, 80);
  drawPolygonFill([
    [720, -20], [1220, -20], [1220, 165], [810, 140]
  ]);
  drawPolygonFill([
    [-20, 680], [165, 650], [210, 1220], [-20, 1220]
  ]);

  // Wind-sculpted sand ripples on the exposed dunes
  brush.noFill();
  for (let r = 0; r < 28; r++) {
    let yBase = -10 + r * 9.5;
    if (yBase < 210) {
      let ptsSun = [], ptsShade = [];
      for (let x = -10; x <= 1210; x += 45) {
        let wave = Math.sin(x * 0.012 + r * 0.55) * 14 + (noise(x * 0.008, r * 0.3) - 0.5) * 12;
        ptsSun.push([x, yBase + wave, 0.7]);
        ptsShade.push([x, yBase + wave + 2.8, 0.8]);
      }
      brush.set("2H", PALETTE.sandEarth, 0.85);
      brush.spline(ptsShade, 0.5);
      brush.set("cpencil", PALETTE.paperSun, 0.75);
      brush.spline(ptsSun, 0.5);
    }
  }

  for (let r = 0; r < 24; r++) {
    let yBase = 1000 + r * 9.5;
    let ptsSun = [], ptsShade = [];
    for (let x = -10; x <= 1210; x += 45) {
      let wave = Math.sin(x * 0.011 - r * 0.45 + 1.2) * 15 + (noise(x * 0.008, r * 0.3 + 50) - 0.5) * 12;
      ptsSun.push([x, yBase + wave, 0.7]);
      ptsShade.push([x, yBase + wave + 3.0, 0.85]);
    }
    brush.set("2H", PALETTE.sandShadow, 0.9);
    brush.spline(ptsShade, 0.5);
    brush.set("cpencil", PALETTE.sandLight, 0.8);
    brush.spline(ptsSun, 0.5);
  }

  // Sharp, deep cool cast shadow thrown by the cloth's bottom selvedge (v=1) onto the sand under hard sun
  brush.noStroke();
  brush.fill(PALETTE.sandDeepShadow, 155);
  brush.fillBleed(0.08, "out");
  brush.fillTexture(0.5, 0.4);
  let botShadowPts = [];
  for (let i = 0; i <= 40; i++) {
    let u = i / 40;
    let p = getClothPoint(u, 1.0);
    botShadowPts.push([p.x, p.y - 2]);
  }
  for (let i = 40; i >= 0; i--) {
    let u = i / 40;
    let p = getClothPoint(u, 1.0);
    let lift = Math.max(8, (p.foldHeight + 45) * 0.48);
    botShadowPts.push([p.x + lift * 0.55, p.y + lift * 0.85]);
  }
  drawPolygonFill(botShadowPts);

  // Cast shadow along the left fringed edge (u=0) and top selvedge lifts (v=0)
  let leftShadowPts = [];
  for (let j = 0; j <= 30; j++) {
    let v = j / 30;
    let p = getClothPoint(0.0, v);
    leftShadowPts.push([p.x + 2, p.y]);
  }
  for (let j = 30; j >= 0; j--) {
    let v = j / 30;
    let p = getClothPoint(0.0, v);
    let lift = Math.max(6, (p.foldHeight + 40) * 0.35);
    leftShadowPts.push([p.x - 10 + lift * 0.3, p.y + lift * 0.7]);
  }
  drawPolygonFill(leftShadowPts);
}

// ============================================================================
// STAGE 3: CLOTH BASE UNDERTONE
// ============================================================================
function drawClothBaseUndertone() {
  // Subtle warm natural cotton / myrobalan undertone so the cloth reads as a unified body
  brush.noStroke();
  brush.fill(PALETTE.paperWarm, 75);
  brush.fillBleed(0.06, "in");
  brush.fillTexture(0.35, 0.2);

  let clothOutline = [];
  for (let i = 0; i <= 36; i++) {
    let p = getClothPoint(i / 36, 0);
    clothOutline.push([p.x, p.y]);
  }
  for (let j = 1; j <= 28; j++) {
    let p = getClothPoint(1, j / 28);
    clothOutline.push([p.x, p.y]);
  }
  for (let i = 35; i >= 0; i--) {
    let p = getClothPoint(i / 36, 1);
    clothOutline.push([p.x, p.y]);
  }
  for (let j = 27; j >= 1; j--) {
    let p = getClothPoint(0, j / 28);
    clothOutline.push([p.x, p.y]);
  }
  drawPolygonFill(clothOutline);
}

// ============================================================================
// STAGE 4: BATCHED WATERCOLOUR LAYERS (INDIGO, MADDER-RED & EARTH COMPARTMENTS)
// ============================================================================
function sampleUVPoly(uvList, subdiv = 2) {
  let pts = [];
  let sumLight = 0, sumZ = 0, count = 0;
  for (let k = 0; k < uvList.length; k++) {
    let a = uvList[k];
    let b = uvList[(k + 1) % uvList.length];
    let steps = Math.max(1, subdiv);
    for (let s = 0; s < steps; s++) {
      let t = s / steps;
      let u = a[0] + (b[0] - a[0]) * t;
      let v = a[1] + (b[1] - a[1]) * t;
      let p = getClothPoint(u, v);
      pts.push([p.x, p.y]);
      sumLight += p.light;
      sumZ += p.foldHeight;
      count++;
    }
  }
  return { pts, avgLight: sumLight / count, avgZ: sumZ / count };
}

function drawPolygonFill(pts) {
  if (pts.length < 3) return;
  brush.beginShape(0.08);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

function drawBatchedWatercolourPattern() {
  // Collect all watercolor polygons into color batches for optimal p5.brush caching & authentic layering
  let batches = {
    indigoLight: [],
    indigoMid: [],
    indigoDeep: [],
    indigoSecondDip: [],
    madderLight: [],
    madderMid: [],
    madderDeep: [],
    madderSecondDip: [],
    earthAccent: []
  };

  function addCompartment(uvPoly, family, subdiv = 2, secondDipScale = 0) {
    let polyData = sampleUVPoly(uvPoly, subdiv);
    let L = polyData.avgLight;
    if (family === "indigo") {
      if (L > 0.66) batches.indigoLight.push(polyData.pts);
      else if (L > 0.38) batches.indigoMid.push(polyData.pts);
      else batches.indigoDeep.push(polyData.pts);

      // Saturated second layer in folds & deeper compartments
      if (secondDipScale > 0 || L < 0.58) {
        let sc = secondDipScale > 0 ? secondDipScale : 0.72;
        let cx = 0, cy = 0;
        for (let p of uvPoly) { cx += p[0]; cy += p[1]; }
        cx /= uvPoly.length; cy /= uvPoly.length;
        let innerUV = uvPoly.map(p => [cx + (p[0] - cx) * sc, cy + (p[1] - cy) * sc]);
        batches.indigoSecondDip.push(sampleUVPoly(innerUV, 1).pts);
      }
    } else if (family === "madder") {
      if (L > 0.66) batches.madderLight.push(polyData.pts);
      else if (L > 0.38) batches.madderMid.push(polyData.pts);
      else batches.madderDeep.push(polyData.pts);

      if (secondDipScale > 0 || L < 0.58) {
        let sc = secondDipScale > 0 ? secondDipScale : 0.72;
        let cx = 0, cy = 0;
        for (let p of uvPoly) { cx += p[0]; cy += p[1]; }
        cx /= uvPoly.length; cy /= uvPoly.length;
        let innerUV = uvPoly.map(p => [cx + (p[0] - cx) * sc, cy + (p[1] - cy) * sc]);
        batches.madderSecondDip.push(sampleUVPoly(innerUV, 1).pts);
      }
    } else if (family === "earth") {
      batches.earthAccent.push(polyData.pts);
    }
  }

  // 1. Left End Cross-Border (Pallu): u in [0.015, 0.132]
  let vSegs = 7;
  for (let j = 0; j < vSegs; j++) {
    let v0 = 0.035 + (j / vSegs) * 0.93;
    let v1 = 0.035 + ((j + 1) / vSegs) * 0.93;
    addCompartment([[0.018, v0], [0.052, v0], [0.052, v1], [0.018, v1]], "indigo", 3);
    addCompartment([[0.058, v0], [0.092, v0], [0.092, v1], [0.058, v1]], "madder", 3);
    addCompartment([[0.098, v0], [0.129, v0], [0.129, v1], [0.098, v1]], "indigo", 3);
  }

  // 2. Top & Bottom Selvedge & Star Guard Borders: v in [0, 0.148] and [0.852, 1.0]
  let uBorderSegs = 10;
  for (let i = 0; i < uBorderSegs; i++) {
    let u0 = 0.136 + (i / uBorderSegs) * 0.862;
    let u1 = 0.136 + ((i + 1) / uBorderSegs) * 0.862;

    // Top border bands
    addCompartment([[u0, 0.004], [u1, 0.004], [u1, 0.030], [u0, 0.030]], "indigo", 3);
    addCompartment([[u0, 0.036], [u1, 0.036], [u1, 0.082], [u0, 0.082]], "madder", 3, 0.78);
    addCompartment([[u0, 0.088], [u1, 0.088], [u1, 0.142], [u0, 0.142]], "indigo", 3, 0.78);

    // Bottom border bands
    addCompartment([[u0, 0.858], [u1, 0.858], [u1, 0.912], [u0, 0.912]], "indigo", 3, 0.78);
    addCompartment([[u0, 0.918], [u1, 0.918], [u1, 0.964], [u0, 0.964]], "madder", 3, 0.78);
    addCompartment([[u0, 0.970], [u1, 0.970], [u1, 0.996], [u0, 0.996]], "indigo", 3);
  }

  // 3. Main Central Geometric Block-Printed Lattice: 10 x 7 modules
  let Nu = 10, Nv = 7;
  let uStart = 0.138, uEnd = 0.996;
  let vStart = 0.150, vEnd = 0.850;
  let du = (uEnd - uStart) / Nu;
  let dv = (vEnd - vStart) / Nv;

  for (let i = 0; i < Nu; i++) {
    for (let j = 0; j < Nv; j++) {
      let uc = uStart + (i + 0.5) * du;
      let vc = vStart + (j + 0.5) * dv;
      let hu = du * 0.5;
      let hv = dv * 0.5;

      // Helper to map local cell coordinates (s, t) in [-1, 1]^2 to (u, v)
      const toUV = (s, t) => [uc + s * hu, vc + t * hv];

      let isEven = (i + j) % 2 === 0;
      let mainFam = isEven ? "indigo" : "madder";
      let innerFam = isEven ? "madder" : "indigo";
      let cornerFam = isEven ? "madder" : "indigo";

      // Central Octagon Medallion (inset from lattice straps by 0.14 to leave bare paper reserve!)
      let octOuter = [
        toUV(-0.28, -0.74), toUV(0.28, -0.74),
        toUV(0.74, -0.28),  toUV(0.74, 0.28),
        toUV(0.28, 0.74),   toUV(-0.28, 0.74),
        toUV(-0.74, 0.28),  toUV(-0.74, -0.28)
      ];
      addCompartment(octOuter, mainFam, 1, 0.82);

      // Inner Diamond / Star Rosette inside the Octagon (also inset for reserved white ring)
      let diaInner = [
        toUV(0.0, -0.44), toUV(0.44, 0.0),
        toUV(0.0, 0.44),  toUV(-0.44, 0.0)
      ];
      addCompartment(diaInner, innerFam, 1, 0);

      // 4 Corner Triangles inside module (forming secondary interlocking diamonds across lattice straps)
      let cTopLeft = [toUV(-0.82, -0.82), toUV(-0.38, -0.82), toUV(-0.82, -0.38)];
      let cTopRight = [toUV(0.82, -0.82), toUV(0.82, -0.38), toUV(0.38, -0.82)];
      let cBotRight = [toUV(0.82, 0.82), toUV(0.38, 0.82), toUV(0.82, 0.38)];
      let cBotLeft = [toUV(-0.82, 0.82), toUV(-0.82, 0.38), toUV(-0.38, 0.82)];

      addCompartment(cTopLeft, cornerFam, 1, 0);
      addCompartment(cTopRight, cornerFam, 1, 0);
      addCompartment(cBotRight, cornerFam, 1, 0);
      addCompartment(cBotLeft, cornerFam, 1, 0);

      // Muted earth-tone accent lozenges in alternate cells
      if ((i * 3 + j) % 3 === 0) {
        let earthDot = [
          toUV(0.0, -0.22), toUV(0.22, 0.0),
          toUV(0.0, 0.22),  toUV(-0.22, 0.0)
        ];
        addCompartment(earthDot, "earth", 1, 0);
      }
    }
  }

  // Execute batched watercolor fills!
  brush.noStroke();

  const renderBatch = (polyList, col, alpha, bleed, tex, border) => {
    if (!polyList.length) return;
    brush.fill(col, alpha);
    brush.fillBleed(bleed, "out");
    brush.fillTexture(tex, border);
    for (let pts of polyList) {
      drawPolygonFill(pts);
    }
  };

  // Layer 1: Sunlit & Midtone washes
  renderBatch(batches.earthAccent, PALETTE.earthGold, 155, 0.14, 0.45, 0.35);
  renderBatch(batches.madderLight, PALETTE.madderSun, 175, 0.16, 0.50, 0.40);
  renderBatch(batches.madderMid, PALETTE.madderMid, 195, 0.18, 0.55, 0.45);
  renderBatch(batches.madderDeep, PALETTE.madderDeep, 215, 0.18, 0.55, 0.45);

  renderBatch(batches.indigoLight, PALETTE.indigoSun, 180, 0.16, 0.52, 0.42);
  renderBatch(batches.indigoMid, PALETTE.indigoMid, 200, 0.18, 0.58, 0.48);
  renderBatch(batches.indigoDeep, PALETTE.indigoDeep, 220, 0.20, 0.60, 0.50);

  // Layer 2: Saturated glaze layers (pooled pigment in folds & block interiors)
  renderBatch(batches.madderSecondDip, PALETTE.madderAbyss, 115, 0.12, 0.45, 0.35);
  renderBatch(batches.indigoSecondDip, PALETTE.indigoAbyss, 125, 0.12, 0.48, 0.38);
}

// ============================================================================
// STAGE 5: CRISP RESERVED WHITE & BLACK LATTICE + ROWS OF TINY BARE-PAPER STARS
// ============================================================================
function getPaperReserveColor(light) {
  if (light > 0.72) return PALETTE.paperSun;
  if (light > 0.52) return PALETTE.paper;
  if (light > 0.34) return "#c7bfb4";
  if (light > 0.22) return PALETTE.paperShadowCool;
  return PALETTE.paperShadowDeep;
}

function getBlackInkColor(light) {
  if (light > 0.65) return PALETTE.blackSun;
  if (light > 0.35) return PALETTE.blackInk;
  return PALETTE.blackShadow;
}

// Draws a crisp reserved bare-paper star at (u, v) warped accurately onto the 3D fold surface
function drawBarePaperStar(uc, vc, ru, rv, numPoints = 8) {
  let centerP = getClothPoint(uc, vc);
  let paperCol = getPaperReserveColor(centerP.light);
  let inkCol = getBlackInkColor(centerP.light);

  let starPts = [];
  let totalVerts = numPoints * 2;
  for (let k = 0; k < totalVerts; k++) {
    let ang = (k * Math.PI * 2) / totalVerts;
    let rad = k % 2 === 0 ? 1.0 : 0.38;
    let u = uc + Math.cos(ang) * ru * rad;
    let v = vc + Math.sin(ang) * rv * rad;
    let p = getClothPoint(u, v);
    starPts.push([p.x, p.y]);
  }

  // 1. Wash bare-paper reserve inside star so any bled watercolour is crisply held back
  brush.noStroke();
  brush.wash(paperCol, 240);
  drawPolygonFill(starPts);
  brush.noWash();

  // 2. Crisp iron-black block-print resist outline around star
  let compWeight = constrain(Math.sqrt(centerP.compression), 0.45, 1.0);
  brush.set("resistPen", inkCol, 0.55 * compWeight);
  for (let k = 0; k < starPts.length; k++) {
    let a = starPts[k];
    let b = starPts[(k + 1) % starPts.length];
    brush.line(a[0], a[1], b[0], b[1]);
  }

  // 3. Tiny central mordant dot inside larger 8-pointed stars
  if (numPoints >= 8 && centerP.compression > 0.32) {
    brush.set("resistPen", inkCol, 0.7 * compWeight);
    brush.line(centerP.x - 0.8, centerP.y - 0.8, centerP.x + 0.8, centerP.y + 0.8);
  }
}

// Draws a warped UV line segment with crisp bare-paper reserve flanked by iron-black key lines
function drawResistStrapUV(u0, v0, u1, v1, duPerp, dvPerp, steps = 16, withCenterBlack = false) {
  let leftPts = [], centerPts = [], rightPts = [];
  for (let s = 0; s <= steps; s++) {
    let t = s / steps;
    let u = u0 + (u1 - u0) * t;
    let v = v0 + (v1 - v0) * t;

    let pC = getClothPoint(u, v);
    let pL = getClothPoint(u - duPerp, v - dvPerp);
    let pR = getClothPoint(u + duPerp, v + dvPerp);

    let wMod = constrain(Math.sqrt(pC.compression), 0.45, 1.05);
    centerPts.push({ x: pC.x, y: pC.y, light: pC.light, w: wMod });
    leftPts.push([pL.x, pL.y, 0.85 * wMod]);
    rightPts.push([pR.x, pR.y, 0.85 * wMod]);
  }

  // Crisp reserved white core along the strap (chunked by lighting zone)
  for (let s = 0; s < steps; s++) {
    let a = centerPts[s], b = centerPts[s + 1];
    let col = getPaperReserveColor((a.light + b.light) * 0.5);
    brush.set("paperGouache", col, 1.35 * ((a.w + b.w) * 0.5));
    brush.line(a.x, a.y, b.x, b.y);
  }

  // Flanking iron-black block-printed outlines
  brush.set("resistPen", PALETTE.blackInk, 0.68);
  brush.spline(leftPts, 0.35);
  brush.spline(rightPts, 0.35);

  if (withCenterBlack) {
    let midLine = centerPts.map(p => [p.x, p.y, 0.55 * p.w]);
    brush.set("resistPen", PALETTE.blackInk, 0.42);
    brush.spline(midLine, 0.35);
  }
}

function drawGeometricLatticeAndStars() {
  let Nu = 10, Nv = 7;
  let uStart = 0.138, uEnd = 0.996;
  let vStart = 0.150, vEnd = 0.850;
  let du = (uEnd - uStart) / Nu;
  let dv = (vEnd - vStart) / Nv;

  // 1. Longitudinal Border Guard Straps (v = 0.033, 0.085, 0.146 and v = 0.854, 0.915, 0.967)
  const borderVs = [0.033, 0.085, 0.146, 0.854, 0.915, 0.967];
  for (let bv of borderVs) {
    drawResistStrapUV(0.135, bv, 0.998, bv, 0, 0.0038, 42, true);
  }

  // 2. Left Cross-Border (Pallu) Guard Straps (u = 0.016, 0.055, 0.095, 0.134)
  const palluUs = [0.016, 0.055, 0.095, 0.134];
  for (let pu of palluUs) {
    drawResistStrapUV(pu, 0.008, pu, 0.992, 0.0032, 0, 36, true);
  }

  // 3. Orthogonal Lattice Straps across the Main Central Field
  for (let i = 0; i <= Nu; i++) {
    let u = uStart + i * du;
    drawResistStrapUV(u, vStart, u, vEnd, 0.0032, 0, 32, true);
  }
  for (let j = 0; j <= Nv; j++) {
    let v = vStart + j * dv;
    drawResistStrapUV(uStart, v, uEnd, v, 0, 0.0038, 40, true);
  }

  // 4. Diagonal Lattice Straps & Inner Medallion Frames inside each of the 10 x 7 modules
  for (let i = 0; i < Nu; i++) {
    for (let j = 0; j < Nv; j++) {
      let uc = uStart + (i + 0.5) * du;
      let vc = vStart + (j + 0.5) * dv;
      let hu = du * 0.5;
      let hv = dv * 0.5;
      const toUV = (s, t) => [uc + s * hu, vc + t * hv];

      // 4 diagonal straps separating the corner triangles from the central octagon
      let diagPairs = [
        [toUV(-0.88, -0.32), toUV(-0.32, -0.88)],
        [toUV(0.32, -0.88),  toUV(0.88, -0.32)],
        [toUV(0.88, 0.32),   toUV(0.32, 0.88)],
        [toUV(-0.32, 0.88),  toUV(-0.88, 0.32)]
      ];
      for (let pair of diagPairs) {
        drawResistStrapUV(
          pair[0][0], pair[0][1],
          pair[1][0], pair[1][1],
          0.0024, 0.0028, 5, false
        );
      }

      // Crisp inner diamond resist ring inside each octagon
      let ringUV = [
        toUV(0.0, -0.48), toUV(0.48, 0.0),
        toUV(0.0, 0.48),  toUV(-0.48, 0.0)
      ];
      for (let k = 0; k < 4; k++) {
        let a = ringUV[k], b = ringUV[(k + 1) % 4];
        drawResistStrapUV(a[0], a[1], b[0], b[1], 0.0018, 0.0022, 4, false);
      }

      // Geometric 8-pointed star petals radiating from center of octagon
      let pCenter = getClothPoint(uc, vc);
      let inkCol = getBlackInkColor(pCenter.light);
      let papCol = getPaperReserveColor(pCenter.light);
      let wMod = constrain(Math.sqrt(pCenter.compression), 0.45, 1.0);

      for (let m = 0; m < 8; m++) {
        let ang = (m * Math.PI) / 4;
        let uTip = uc + Math.cos(ang) * hu * 0.64;
        let vTip = vc + Math.sin(ang) * hv * 0.64;
        let uBase = uc + Math.cos(ang) * hu * 0.22;
        let vBase = vc + Math.sin(ang) * hv * 0.22;
        let p1 = getClothPoint(uBase, vBase);
        let p2 = getClothPoint(uTip, vTip);

        brush.set("paperGouache", papCol, 0.72 * wMod);
        brush.line(p1.x, p1.y, p2.x, p2.y);
        brush.set("resistPen", inkCol, 0.48 * wMod);
        brush.line(p1.x, p1.y, p2.x, p2.y);
      }

      // Center bare-paper star held back at the heart of every medallion
      drawBarePaperStar(uc, vc, hu * 0.20, hv * 0.20, 8);
    }
  }

  // 5. ROWS OF TINY STARS HELD BACK AS BARE PAPER
  // Row A & B: Outer Madder Star Guard Bands (top v=0.059 and bottom v=0.941)
  let numBorderStars = 34;
  for (let k = 0; k < numBorderStars; k++) {
    let u = 0.148 + (k + 0.5) * ((0.992 - 0.148) / numBorderStars);
    drawBarePaperStar(u, 0.059, 0.0095, 0.0155, 8);
    drawBarePaperStar(u, 0.941, 0.0095, 0.0155, 8);

    // Tiny paired resist dots between stars in the row
    if (k < numBorderStars - 1) {
      let uMid = u + 0.5 * ((0.992 - 0.148) / numBorderStars);
      drawBarePaperStar(uMid, 0.059, 0.0038, 0.0058, 4);
      drawBarePaperStar(uMid, 0.941, 0.0038, 0.0058, 4);
    }
  }

  // Row C & D: Inner Indigo Border Chevron & Star Track (v=0.115 and v=0.885)
  let numInnerStars = 28;
  for (let k = 0; k < numInnerStars; k++) {
    let u0 = 0.145 + k * ((0.992 - 0.145) / numInnerStars);
    let u1 = 0.145 + (k + 1) * ((0.992 - 0.145) / numInnerStars);
    let uMid = (u0 + u1) * 0.5;

    // Zig-zag reserved white & black chevron in the inner border
    drawResistStrapUV(u0, 0.093, uMid, 0.137, 0.0016, 0.002, 3, false);
    drawResistStrapUV(uMid, 0.137, u1, 0.093, 0.0016, 0.002, 3, false);

    drawResistStrapUV(u0, 0.907, uMid, 0.863, 0.0016, 0.002, 3, false);
    drawResistStrapUV(uMid, 0.863, u1, 0.907, 0.0016, 0.002, 3, false);

    // Tiny bare-paper stars nestled in the chevron peaks
    drawBarePaperStar(uMid, 0.106, 0.0065, 0.0105, 8);
    drawBarePaperStar(uMid, 0.894, 0.0065, 0.0105, 8);
  }

  // Row E, F, G: Left End Cross-Border (Pallu) vertical rows of tiny bare-paper stars
  let numPalluStars = 24;
  for (let k = 0; k < numPalluStars; k++) {
    let v = 0.038 + (k + 0.5) * (0.924 / numPalluStars);
    drawBarePaperStar(0.035, v, 0.0095, 0.0135, 8);
    drawBarePaperStar(0.075, v, 0.0085, 0.0120, 4);
    drawBarePaperStar(0.114, v, 0.0095, 0.0135, 8);
  }

  // Row H: Lattice Intersection Stars across the entire 11 x 8 grid nodes
  for (let i = 0; i <= Nu; i++) {
    for (let j = 0; j <= Nv; j++) {
      let u = uStart + i * du;
      let v = vStart + j * dv;
      drawBarePaperStar(u, v, 0.0082, 0.0115, 8);
    }
  }
}

// ============================================================================
// STAGE 6: FAINT CRACKLE BLEED AT RESIST EDGES
// ============================================================================
function drawResistCrackleBleed() {
  // Fine hairline tendrils of indigo and madder seeping across the reserved white lines and star edges
  let Nu = 10, Nv = 7;
  let uStart = 0.138, uEnd = 0.996;
  let vStart = 0.150, vEnd = 0.850;
  let du = (uEnd - uStart) / Nu;
  let dv = (vEnd - vStart) / Nv;

  for (let k = 0; k < 520; k++) {
    let u, v, dirU, dirV;
    if (k < 340) {
      // Along main lattice straps
      if (random() < 0.5) {
        let i = floor(random(Nu + 1));
        u = uStart + i * du + random(-0.0025, 0.0025);
        v = random(vStart, vEnd);
        dirU = random(-0.006, 0.006);
        dirV = random(-0.003, 0.003);
      } else {
        let j = floor(random(Nv + 1));
        u = random(uStart, uEnd);
        v = vStart + j * dv + random(-0.003, 0.003);
        dirU = random(-0.003, 0.003);
        dirV = random(-0.007, 0.007);
      }
    } else {
      // Along border star rows & medallion rings
      u = random(0.03, 0.98);
      v = random() < 0.5 ? random(0.03, 0.15) : random(0.85, 0.97);
      dirU = random(-0.005, 0.005);
      dirV = random(-0.006, 0.006);
    }

    let p0 = getClothPoint(u, v);
    let p1 = getClothPoint(u + dirU * 0.5, v + dirV * 0.5);
    let p2 = getClothPoint(u + dirU, v + dirV);

    let isIndigo = random() < 0.58;
    let col = isIndigo ? PALETTE.indigoMid : PALETTE.madderDeep;
    brush.set("crackle", col, random(0.35, 0.65));
    brush.spline([[p0.x, p0.y, 0.4], [p1.x + random(-1.2, 1.2), p1.y + random(-1.2, 1.2), 0.9], [p2.x, p2.y, 0.2]], 0.5);
  }
}

// ============================================================================
// STAGE 7: HARD SUN & DEEP COOL TROUGH SHADOWS
// ============================================================================
function drawHardSunAndTroughShadows() {
  // 1. Watercolour shadow glazes in the deep sagging troughs & steep shadow flanks
  // Scan the UV grid for contiguous shadow basins (light < 0.44) and build smooth polygon strips
  brush.noStroke();

  let uSteps = 44;
  let vSteps = 32;

  let midShadowPolys = [];
  let deepShadowPolys = [];

  for (let j = 0; j < vSteps; j++) {
    let v0 = j / vSteps;
    let v1 = (j + 1) / vSteps;
    let inMid = false, startU_mid = 0;
    let inDeep = false, startU_deep = 0;

    for (let i = 0; i <= uSteps; i++) {
      let u = i / uSteps;
      let p = getClothPoint(u, (v0 + v1) * 0.5);

      // Mid-cool shadow terminator (light < 0.46)
      if (p.light < 0.46 && i < uSteps) {
        if (!inMid) { inMid = true; startU_mid = u; }
      } else if (inMid) {
        inMid = false;
        if (u - startU_mid > 0.025) {
          let uvRect = [[startU_mid, v0], [u, v0], [u, v1], [startU_mid, v1]];
          midShadowPolys.push(sampleUVPoly(uvRect, 2).pts);
        }
      }

      // Deep core trough shadow (light < 0.30)
      if (p.light < 0.30 && i < uSteps) {
        if (!inDeep) { inDeep = true; startU_deep = u; }
      } else if (inDeep) {
        inDeep = false;
        if (u - startU_deep > 0.02) {
          let uvRect = [[startU_deep, v0], [u, v0], [u, v1], [startU_deep, v1]];
          deepShadowPolys.push(sampleUVPoly(uvRect, 2).pts);
        }
      }
    }
  }

  // Lay cool transparent indigo-slate watercolour glazes over the troughs
  brush.fill(PALETTE.shadowGlaze1, 68);
  brush.fillBleed(0.22, "out");
  brush.fillTexture(0.45, 0.25);
  for (let pts of midShadowPolys) {
    drawPolygonFill(pts);
  }

  brush.fill(PALETTE.shadowGlaze2, 76);
  brush.fillBleed(0.18, "out");
  brush.fillTexture(0.52, 0.32);
  for (let pts of deepShadowPolys) {
    drawPolygonFill(pts);
  }

  // 2. Fine contour pencil shading inside the troughs & steep fold flanks
  // AND sun-struck cotton warp/weft thread highlights along the bright fold crests!
  for (let j = 0; j <= 88; j++) {
    let v = j / 88;
    for (let i = 0; i < 80; i++) {
      let u0 = i / 80;
      let u1 = (i + 1) / 80;
      let p0 = getClothPoint(u0, v);
      let p1 = getClothPoint(u1, v);

      if (p0.light < 0.36) {
        // Cool deep charcoal/2B drapery shading in the shadow troughs following warp contour
        let shadeAlpha = map(p0.light, 0.12, 0.36, 0.85, 0.25, true);
        if (random() < 0.65) {
          brush.set("2B", PALETTE.indigoAbyss, shadeAlpha * 0.75);
          brush.line(p0.x, p0.y, p1.x, p1.y);
        }
      } else if (p0.light > 0.78 && random() < 0.55) {
        // Sun-bleached cotton thread sheen on the high crests catching hard sun
        let sunW = map(p0.light, 0.78, 0.98, 0.35, 0.85, true);
        brush.set("2H", PALETTE.paperSun, sunW);
        brush.line(p0.x, p0.y, p1.x, p1.y);
      }
    }
  }

  // Cross-weft threads on sun crests and deep pinch creases
  for (let i = 0; i <= 95; i++) {
    let u = i / 95;
    for (let j = 0; j < 70; j++) {
      let v0 = j / 70;
      let v1 = (j + 1) / 70;
      let p0 = getClothPoint(u, v0);
      let p1 = getClothPoint(u, v1);

      if (p0.light < 0.28 && random() < 0.55) {
        brush.set("HB", PALETTE.blackShadow, 0.55);
        brush.line(p0.x, p0.y, p1.x, p1.y);
      } else if (p0.light > 0.82 && random() < 0.45) {
        brush.set("2H", PALETTE.sandLight, 0.5);
        brush.line(p0.x, p0.y, p1.x, p1.y);
      }
    }
  }
}

// ============================================================================
// STAGE 8: SELVEDGE HEMS, WARP FRINGES & ENCROACHING SAND DRIFT
// ============================================================================
function drawSelvedgesAndFringes() {
  // 1. Rolled cotton selvedge cord along v=0 (top) and v=1 (bottom)
  for (let edgeV of [0.0, 1.0]) {
    let ptsCord = [];
    for (let i = 0; i <= 60; i++) {
      let u = i / 60;
      let p = getClothPoint(u, edgeV);
      ptsCord.push([p.x, p.y, 0.9]);
    }
    brush.set("2B", PALETTE.blackInk, 1.1);
    brush.spline(ptsCord, 0.4);

    // Highlight along sun-facing selvedge cord
    for (let i = 0; i < 60; i++) {
      let u0 = i / 60, u1 = (i + 1) / 60;
      let p0 = getClothPoint(u0, edgeV);
      let p1 = getClothPoint(u1, edgeV);
      if (p0.light > 0.5) {
        brush.set("cpencil", PALETTE.paperWarm, 0.85);
        brush.line(p0.x, p0.y - 1.5, p1.x, p1.y - 1.5);
      }
    }
  }

  // 2. Raw twisted cotton warp fringes along the left end (u=0) resting on the pale sand dune
  let numFringes = 68;
  for (let k = 0; k <= numFringes; k++) {
    let v = 0.01 + (k / numFringes) * 0.98;
    let p0 = getClothPoint(0.0, v);
    let len = random(16, 34);
    let angle = 172 + sin(v * 320) * 14 + random(-8, 8);
    let mx = p0.x + cos(angle) * len * 0.55;
    let my = p0.y + sin(angle) * len * 0.55 + 3;
    let ex = p0.x + cos(angle) * len;
    let ey = p0.y + sin(angle) * len + 7;

    // Fringe cast shadow on sand
    brush.set("2H", PALETTE.sandDeepShadow, 0.65);
    brush.spline([[p0.x, p0.y + 3, 0.8], [mx + 2, my + 4, 0.7], [ex + 3, ey + 4, 0.3]], 0.5);

    // Twisted un-dyed cotton fringe cord (slightly stained with indigo near border)
    let fringeCol = p0.light > 0.48 ? PALETTE.paperSun : PALETTE.sandShadow;
    brush.set("cpencil", fringeCol, 0.95);
    brush.spline([[p0.x, p0.y, 1.0], [mx, my, 0.9], [ex, ey, 0.5]], 0.5);
  }

  // 3. Small wind-blown drift of pale sand spilling over the lower-right and upper-left dip of the cloth
  brush.noStroke();
  brush.fill(PALETTE.sandMid, 165);
  brush.fillBleed(0.25, "out");
  brush.fillTexture(0.5, 0.3);

  let drift1 = [];
  for (let i = 0; i <= 16; i++) {
    let u = 0.28 + (i / 16) * 0.24;
    let depth = Math.sin((i / 16) * Math.PI) * 0.065;
    let p = getClothPoint(u, depth);
    drift1.push([p.x, p.y]);
  }
  for (let i = 16; i >= 0; i--) {
    let u = 0.28 + (i / 16) * 0.24;
    let p = getClothPoint(u, 0.0);
    drift1.push([p.x, p.y - 12]);
  }
  drawPolygonFill(drift1);
}

// ============================================================================
// STAGE 9: SCATTERED SAND GRAINS IN FINE PENCIL STIPPLE
// ============================================================================
function drawScatteredSandGrains() {
  // 1. Fine spray dust pass along sand-drift zones & deep fold troughs
  for (let k = 0; k < 45; k++) {
    let u = random(0.02, 0.96);
    let v = random() < 0.65 ? (random() < 0.5 ? random(0.0, 0.28) : random(0.72, 1.0)) : random(0.2, 0.8);
    let p0 = getClothPoint(u, v);
    let p1 = getClothPoint(u + random(-0.04, 0.04), v + random(-0.03, 0.03));
    let col = p0.light > 0.5 ? PALETTE.sandLight : PALETTE.sandShadow;
    brush.set("spray", col, random(0.45, 0.85));
    brush.line(p0.x, p0.y, p1.x, p1.y);
  }

  // 2. Hyperrealistic individual sand grains in fine pencil stipple
  // Sand grains naturally roll down steep slopes and pool in the sagging hollows (low foldHeight)
  // and cluster near the dune borders!
  let totalGrains = 2600;
  for (let g = 0; g < totalGrains; g++) {
    let u = random(0.01, 0.99);
    let v = random(0.01, 0.99);

    let p = getClothPoint(u, v);

    // Probability weighting: higher near sand borders and inside sagging troughs
    let borderDist = Math.min(v, 1 - v, u * 1.2);
    let borderWeight = Math.exp(-borderDist / 0.18);
    let troughWeight = constrain((15 - p.foldHeight) / 55, 0, 1);
    let patchNoise = noise(u * 9.0 + 30, v * 9.0 + 70);

    let prob = 0.12 + 0.55 * borderWeight + 0.45 * troughWeight * patchNoise;
    if (random() > prob) continue;

    let gx = p.x + random(-2.5, 2.5);
    let gy = p.y + random(-2.5, 2.5);
    let grainLen = random(1.1, 2.6);
    let ang = random(360);
    let dx = cos(ang) * grainLen;
    let dy = sin(ang) * grainLen;

    if (p.light > 0.48) {
      // Sunlit sand grain: tiny dark shadow speck on lower-right + bright ochre/quartz highlight speck
      brush.set("2B", PALETTE.blackInk, random(0.45, 0.75));
      brush.line(gx + 0.9, gy + 1.0, gx + 0.9 + dx * 0.7, gy + 1.0 + dy * 0.7);

      let grainCol = random() < 0.55 ? PALETTE.sandLight : (random() < 0.6 ? PALETTE.sandMid : PALETTE.sandOchre);
      brush.set("cpencil", grainCol, random(0.65, 1.15));
      brush.line(gx, gy, gx + dx, gy + dy);
    } else {
      // Shadowed sand grain in cool trough: muted earth/taupe stipple
      let shadeGrainCol = random() < 0.5 ? PALETTE.sandShadow : PALETTE.sandEarth;
      brush.set("2H", shadeGrainCol, random(0.55, 0.95));
      brush.line(gx, gy, gx + dx * 0.85, gy + dy * 0.85);
    }
  }

  // 3. Extra stipple sand texture on the exposed pale sand dunes around the cloth
  for (let s = 0; s < 900; s++) {
    let sx = random(10, 1190);
    let sy = random() < 0.52 ? random(10, 195) : random(1010, 1190);
    let len = random(1.2, 2.5);
    let col = random() < 0.45 ? PALETTE.sandEarth : (random() < 0.5 ? PALETTE.sandShadow : PALETTE.paperSun);
    brush.set("2H", col, random(0.45, 0.85));
    brush.line(sx, sy, sx + len, sy + 0.4);
  }
}

// Hyperreal Sandstone Stepwell & Dented Brass Lota
// Rendered with p5.js v2 + p5.brush in WEBGL

let VX = 450;
let VY = 695;
let CAM_X = -38;
let CAM_Y = 38;
let FOCAL = 1020;
let ROT_ANGLE = 0.085; // ~4.9 degrees subtle vertigo tilt
let COS_R, SIN_R;

// Directional sunlight vector (from South-West / upper-left-front down into the shaft)
let SUN_DIR;

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(4219);
  noiseSeed(4219);

  COS_R = Math.cos(ROT_ANGLE);
  SIN_R = Math.sin(ROT_ANGLE);

  // Normalized sunlight vector pointing in direction light travels (+x, -y, +z)
  let lx = 0.53, ly = -0.44, lz = 0.724;
  let lLen = Math.hypot(lx, ly, lz);
  SUN_DIR = { x: lx / lLen, y: ly / lLen, z: lz / lLen };

  // Custom ultra-fine burin / hard graphite tip for hyperreal chisel marks and metallic reflections
  brush.add("needle2H", {
    type: "default",
    weight: 0.22,
    scatter: 0.04,
    sharpness: 0.92,
    grain: 6,
    opacity: 195,
    spacing: 0.12,
    pressure: [0.6, 1.0, 0.5],
    noise: 0.25
  });

  brush.add("chiselEdge", {
    type: "default",
    weight: 0.38,
    scatter: 0.08,
    sharpness: 0.85,
    grain: 9,
    opacity: 210,
    spacing: 0.15,
    pressure: [0.85, 1.15, 0.7],
    noise: 0.4
  });
}

function draw() {
  translate(-width / 2, -height / 2);

  // Warm bone-ivory paper ground (high-contrast lit stone base)
  background("#f2ece0");
  brush.noField();

  // 1. Subtle paper grain & peripheral tonal framing
  renderPaperPreparation();

  // 2. Build all 3D geometry of the stepwell tiers, landings, corners, and pool
  let faces = buildStepwellGeometry();

  // 3. Render the dark emerald pool at the bottom of the shaft first
  renderDarkGreenPool();

  // 4. Sort visible 3D stone faces back-to-front (deepest abyss up to foreground rim)
  faces.sort((a, b) => b.sortKey - a.sortKey);

  // 5. Batch watercolor glazes (sepia & raw sienna ONLY where stone catches light,
  //    and deep charcoal/umber washes in the abyssal tiers)
  renderWatercolorGlazesAndWashes(faces);

  // 6. Render dense, controlled hard-graphite cross-hatching, worn treads, and chisel scars
  renderGraphiteArchitecture(faces);

  // 7. Render the focal point: the single dented, polished brass lota on the sunlit landing
  renderBrassLotaOnLanding();

  noLoop();
}

// ============================================================================
// 3D PROJECTION & LIGHTING ENGINE
// ============================================================================

function toWorld(u, v, z, wallIdx) {
  let rx, ry;
  if (wallIdx === 0) { rx = u; ry = v; }           // North
  else if (wallIdx === 1) { rx = -v; ry = u; }     // East
  else if (wallIdx === 2) { rx = -u; ry = -v; }    // South
  else { rx = v; ry = -u; }                        // West

  let wx = rx * COS_R - ry * SIN_R;
  let wy = rx * SIN_R + ry * COS_R;
  return { x: wx, y: wy, z: z };
}

function rotateNormal(nu, nv, nz, wallIdx) {
  let rx, ry;
  if (wallIdx === 0) { rx = nu; ry = nv; }
  else if (wallIdx === 1) { rx = -nv; ry = nu; }
  else if (wallIdx === 2) { rx = -nu; ry = -nv; }
  else { rx = nv; ry = -nu; }

  let wx = rx * COS_R - ry * SIN_R;
  let wy = rx * SIN_R + ry * COS_R;
  return { x: wx, y: wy, z: nz };
}

function project3D(p) {
  let invZ = FOCAL / p.z;
  return [
    VX + (p.x - CAM_X) * invZ,
    VY + (p.y - CAM_Y) * invZ
  ];
}

function quadOnScreen(pts2D) {
  let minX = 1e9, maxX = -1e9, minY = 1e9, maxY = -1e9;
  for (let i = 0; i < pts2D.length; i++) {
    let x = pts2D[i][0], y = pts2D[i][1];
    if (x < minX) minX = x;
    if (x > maxX) maxX = x;
    if (y < minY) minY = y;
    if (y > maxY) maxY = y;
  }
  return !(maxX < -60 || minX > 1260 || maxY < -60 || minY > 1260);
}

// Computes exact 3D illumination, cast shadows from stepwell rim & pyramids, and abyssal falloff
function computeFaceLighting(centroid, normal, meta) {
  // Dot product with incoming sun ray (-SUN_DIR points toward sun)
  let ndotl = -(normal.x * SUN_DIR.x + normal.y * SUN_DIR.y + normal.z * SUN_DIR.z);
  let directFace = Math.max(0, ndotl);

  // Macro cast shadow thrown by the South and West upper rims of the stepwell shaft
  // Trace ray from centroid back toward sun: P(t) = centroid - t * SUN_DIR
  // At z_rim = 760, opening half-size R_rim = 610
  let dzRim = centroid.z - 760;
  let shadowFactor = 1.0;
  if (dzRim > 0) {
    let t = dzRim / SUN_DIR.z;
    let xAtRim = centroid.x - t * SUN_DIR.x;
    let yAtRim = centroid.y - t * SUN_DIR.y;
    // Rotate back to un-tilted stepwell axes to check against South (+y) and West (-x) walls
    let ux = xAtRim * COS_R + yAtRim * SIN_R;
    let uy = -xAtRim * SIN_R + yAtRim * COS_R;
    // Soft penumbra across the macro shadow boundary
    let distWest = ux - (-545);
    let distSouth = 525 - uy;
    let minClearance = Math.min(distWest, distSouth);
    if (minClearance < 0) {
      shadowFactor = Math.max(0.0, 1.0 + minClearance / 95.0);
    }
  }

  // Local step / pyramid self-shadowing
  if (meta.inLocalShadow) {
    shadowFactor *= 0.25;
  }

  // Depth attenuation: toward the bottom the drawing falls into near-black graphite mass
  // z ranges from ~750 at top rim to ~2480 at the pool
  let depthNorm = constrain((centroid.z - 820) / (2420 - 820), 0, 1);
  let abyssalAttenuation = Math.pow(1.0 - depthNorm, 1.55);

  let effectiveSun = directFace * shadowFactor * abyssalAttenuation;

  // Ambient sky light from the open shaft above (stronger on horizontal treads facing -z)
  let skyView = (normal.z < -0.5) ? 0.36 : 0.16;
  let ambient = skyView * Math.pow(1.0 - depthNorm * 0.92, 1.4);

  let totalLight = constrain(effectiveSun * 0.88 + ambient, 0.02, 1.0);
  let isSunlitGlaze = (effectiveSun > 0.34 && depthNorm < 0.62);

  return {
    light: totalLight,
    sun: effectiveSun,
    depth: depthNorm,
    isSunlitGlaze: isSunlitGlaze
  };
}

// ============================================================================
// STEPWELL 3D GEOMETRY GENERATOR
// ============================================================================

function buildStepwellGeometry() {
  let faces = [];

  // Define the stacked architectural tiers from outer top rim down to the pool
  const tiers = [
    // Tier 0: Outer monumental zigzag flights (fills canvas edges & corners completely, no sky)
    { id: 0, rOut: 820, rIn: 525, zTop: 740, zBot: 1045, steps: 9, bays: 6 },
    // Tier 1: Upper-mid zigzag flights (below the Brass Lota landing)
    { id: 1, rOut: 418, rIn: 274, zTop: 1068, zBot: 1450, steps: 9, bays: 6 },
    // Tier 2: Mid-deep zigzag flights (sinking into shadow)
    { id: 2, rOut: 234, rIn: 152, zTop: 1474, zBot: 1910, steps: 8, bays: 4 },
    // Tier 3: Abyssal zigzag flights (near-black graphite mass)
    { id: 3, rOut: 132, rIn: 84,  zTop: 1936, zBot: 2350, steps: 7, bays: 3 }
  ];

  // Define the horizontal landings between tiers
  const landings = [
    // Landing 0: Outer rim terrace
    { id: 0, rOut: 1080, rIn: 820, z: 740, drop: 18, blocksPerWall: 10 },
    // Landing 1: Primary foreground terrace (holds the Brass Lota on the NE sunlit slabs!)
    { id: 1, rOut: 525,  rIn: 418, z: 1045, drop: 23, blocksPerWall: 12 },
    // Landing 2: Mid-level gallery terrace
    { id: 2, rOut: 274,  rIn: 234, z: 1450, drop: 24, blocksPerWall: 10 },
    // Landing 3: Deep shadowy ledge
    { id: 3, rOut: 152,  rIn: 132, z: 1910, drop: 26, blocksPerWall: 8 },
    // Landing 4: Pool ghat rim + submerged steps
    { id: 4, rOut: 84,   rIn: 68,  z: 2350, drop: 48, blocksPerWall: 6 }
  ];

  function addQuad(u0, v0, z0, u1, v1, z1, u2, v2, z2, u3, v3, z3, nu, nv, nz, wallIdx, meta) {
    let p0 = toWorld(u0, v0, z0, wallIdx);
    let p1 = toWorld(u1, v1, z1, wallIdx);
    let p2 = toWorld(u2, v2, z2, wallIdx);
    let p3 = toWorld(u3, v3, z3, wallIdx);

    let cx = (p0.x + p1.x + p2.x + p3.x) * 0.25;
    let cy = (p0.y + p1.y + p2.y + p3.y) * 0.25;
    let cz = (p0.z + p1.z + p2.z + p3.z) * 0.25;

    let n = rotateNormal(nu, nv, nz, wallIdx);

    // Backface culling against camera at (CAM_X, CAM_Y, 0)
    let vx = cx - CAM_X;
    let vy = cy - CAM_Y;
    let vz = cz;
    let dotCam = n.x * vx + n.y * vy + n.z * vz;
    if (dotCam >= -0.5) return; // Turned away from camera

    let pts2D = [project3D(p0), project3D(p1), project3D(p2), project3D(p3)];
    if (!quadOnScreen(pts2D)) return;

    let centroid = { x: cx, y: cy, z: cz };
    let lighting = computeFaceLighting(centroid, n, meta);

    // Painter's algorithm sort key: distance squared from camera + slight bias for vertical vs horizontal
    let distSq = vx * vx + vy * vy + vz * vz * 1.15;
    if (meta.type === "tread" || meta.type === "landing") distSq -= 120;

    faces.push({
      p3D: [p0, p1, p2, p3],
      pts2D: pts2D,
      centroid: centroid,
      normal: n,
      wallIdx: wallIdx,
      meta: meta,
      lighting: lighting,
      sortKey: distSq
    });
  }

  // Generate all Landings
  for (let ld of landings) {
    for (let w = 0; w < 4; w++) {
      let N = ld.blocksPerWall;
      let span = 2 * ld.rIn;
      let du = span / N;

      // Main wall landing slabs (subdivided into outer and inner stone courses)
      let rMid = (ld.rOut + ld.rIn) * 0.5;
      for (let i = 0; i < N; i++) {
        let uA = -ld.rIn + i * du;
        let uB = uA + du;
        // Outer slab course
        addQuad(
          uA, -ld.rOut, ld.z,
          uB, -ld.rOut, ld.z,
          uB, -rMid, ld.z,
          uA, -rMid, ld.z,
          0, 0, -1, w,
          { type: "landing", tierId: ld.id, worn: false, inLocalShadow: false }
        );
        // Inner cornice slab course
        addQuad(
          uA, -rMid, ld.z,
          uB, -rMid, ld.z,
          uB, -ld.rIn, ld.z,
          uA, -ld.rIn, ld.z,
          0, 0, -1, w,
          { type: "landing", tierId: ld.id, worn: true, inLocalShadow: false }
        );
        // Vertical cornice drop riser at inner edge
        addQuad(
          uA, -ld.rIn, ld.z,
          uB, -ld.rIn, ld.z,
          uB, -ld.rIn, ld.z + ld.drop,
          uA, -ld.rIn, ld.z + ld.drop,
          0, 1, 0, w,
          { type: "riser", tierId: ld.id, worn: false, inLocalShadow: false }
        );
      }

      // Corner square landing slabs: u in [rIn, rOut], v in [-rOut, -rIn]
      let cw = (ld.rOut - ld.rIn) * 0.5;
      for (let cu = 0; cu < 2; cu++) {
        for (let cv = 0; cv < 2; cv++) {
          let u0 = ld.rIn + cu * cw;
          let u1 = u0 + cw;
          let v0 = -ld.rOut + cv * cw;
          let v1 = v0 + cw;
          addQuad(
            u0, v0, ld.z,
            u1, v0, ld.z,
            u1, v1, ld.z,
            u0, v1, ld.z,
            0, 0, -1, w,
            { type: "landing", tierId: ld.id, worn: false, inLocalShadow: false }
          );
        }
      }
    }
  }

  // Generate all Zigzag Stepped Tiers
  for (let t of tiers) {
    let dv = (t.rOut - t.rIn) / t.steps;
    let dz = (t.zBot - t.zTop) / t.steps;
    let bayW = (2 * t.rIn) / t.bays;
    let du = bayW / (2 * t.steps);

    for (let w = 0; w < 4; w++) {
      // 1. Zigzag Pyramid Bays along main wall span [-rIn, rIn]
      for (let b = 0; b < t.bays; b++) {
        let uc = -t.rIn + (b + 0.5) * bayW;

        for (let i = 0; i < t.steps; i++) {
          let v0 = -t.rOut + i * dv;
          let v1 = v0 + dv;
          let vIn = -t.rIn;
          let z0 = t.zTop + i * dz;
          let z1 = z0 + dz;

          // (A) Inward recessed steps (Left and Right of the projecting pyramid)
          if (i < t.steps - 1) {
            let uLeft0 = uc - bayW * 0.5;
            let uLeft1 = uc - (i + 1) * du;
            let uRight0 = uc + (i + 1) * du;
            let uRight1 = uc + bayW * 0.5;

            // Left inward tread (partially shadowed by adjacent pyramid wall)
            addQuad(
              uLeft0, v0, z0,
              uLeft1, v0, z0,
              uLeft1, v1, z0,
              uLeft0, v1, z0,
              0, 0, -1, w,
              { type: "tread", tierId: t.id, stepIdx: i, worn: true, inLocalShadow: (w === 0 || w === 3) }
            );
            // Right inward tread
            addQuad(
              uRight0, v0, z0,
              uRight1, v0, z0,
              uRight1, v1, z0,
              uRight0, v1, z0,
              0, 0, -1, w,
              { type: "tread", tierId: t.id, stepIdx: i, worn: true, inLocalShadow: (w === 1 || w === 2) }
            );

            // Left inward riser
            addQuad(
              uLeft0, v1, z0,
              uLeft1, v1, z0,
              uLeft1, v1, z1,
              uLeft0, v1, z1,
              0, 1, 0, w,
              { type: "riser", tierId: t.id, stepIdx: i, worn: false, inLocalShadow: true }
            );
            // Right inward riser
            addQuad(
              uRight0, v1, z0,
              uRight1, v1, z0,
              uRight1, v1, z1,
              uRight0, v1, z1,
              0, 1, 0, w,
              { type: "riser", tierId: t.id, stepIdx: i, worn: false, inLocalShadow: false }
            );
          }

          // (B) Lateral Zigzag Pyramid Treads
          if (i === 0) {
            // Top apex capstone of pyramid
            addQuad(
              uc - du, v0, z0,
              uc + du, v0, z0,
              uc + du, vIn, z0,
              uc - du, vIn, z0,
              0, 0, -1, w,
              { type: "tread", tierId: t.id, stepIdx: i, worn: true, inLocalShadow: false }
            );
          } else {
            // Left lateral step tread descending along -u
            addQuad(
              uc - (i + 1) * du, v0, z0,
              uc - i * du,       v0, z0,
              uc - i * du,       vIn, z0,
              uc - (i + 1) * du, vIn, z0,
              0, 0, -1, w,
              { type: "tread", tierId: t.id, stepIdx: i, worn: true, inLocalShadow: false }
            );
            // Right lateral step tread descending along +u
            addQuad(
              uc + i * du,       v0, z0,
              uc + (i + 1) * du, v0, z0,
              uc + (i + 1) * du, vIn, z0,
              uc + i * du,       vIn, z0,
              0, 0, -1, w,
              { type: "tread", tierId: t.id, stepIdx: i, worn: true, inLocalShadow: false }
            );
          }

          // (C) Lateral Zigzag Pyramid Risers (facing sideways -u and +u!)
          if (v1 < vIn - 0.1) {
            // Left-facing lateral riser (normal -1, 0, 0)
            addQuad(
              uc - (i + 1) * du, v1, z0,
              uc - (i + 1) * du, vIn, z0,
              uc - (i + 1) * du, vIn, z1,
              uc - (i + 1) * du, v1, z1,
              -1, 0, 0, w,
              { type: "latRiser", tierId: t.id, stepIdx: i, worn: false, inLocalShadow: false }
            );
            // Right-facing lateral riser (normal +1, 0, 0)
            addQuad(
              uc + (i + 1) * du, vIn, z0,
              uc + (i + 1) * du, v1, z0,
              uc + (i + 1) * du, v1, z1,
              uc + (i + 1) * du, vIn, z1,
              1, 0, 0, w,
              { type: "latRiser", tierId: t.id, stepIdx: i, worn: false, inLocalShadow: false }
            );
          }

          // (D) Stepped-Triangle Front Masonry Wall of Pyramid at v = vIn (normal 0, +1, 0)
          addQuad(
            uc - (i + 1) * du, vIn, z0,
            uc + (i + 1) * du, vIn, z0,
            uc + (i + 1) * du, vIn, z1,
            uc - (i + 1) * du, vIn, z1,
            0, 1, 0, w,
            { type: "frontWall", tierId: t.id, stepIdx: i, worn: false, inLocalShadow: false }
          );
        }
      }

      // 2. Mitered Corner Steps: u in [rIn, rOut], v in [-rOut, -rIn]
      for (let i = 0; i < t.steps; i++) {
        let v0 = -t.rOut + i * dv;
        let v1 = v0 + dv;
        let u0 = t.rOut - i * dv;
        let u1 = u0 - dv;
        let z0 = t.zTop + i * dz;
        let z1 = z0 + dz;

        // Horizontal L-leg 1 (continuing North wall step into corner)
        addQuad(
          t.rIn, v0, z0,
          u0,    v0, z0,
          u0,    v1, z0,
          t.rIn, v1, z0,
          0, 0, -1, w,
          { type: "tread", tierId: t.id, stepIdx: i, worn: false, inLocalShadow: (w === 2 || w === 3) }
        );
        // Riser for L-leg 1
        addQuad(
          t.rIn, v1, z0,
          u1,    v1, z0,
          u1,    v1, z1,
          t.rIn, v1, z1,
          0, 1, 0, w,
          { type: "riser", tierId: t.id, stepIdx: i, worn: false, inLocalShadow: false }
        );

        // Horizontal L-leg 2 (continuing East wall step into corner)
        addQuad(
          u1, v1,     z0,
          u0, v1,     z0,
          u0, -t.rIn, z0,
          u1, -t.rIn, z0,
          0, 0, -1, w,
          { type: "tread", tierId: t.id, stepIdx: i, worn: false, inLocalShadow: (w === 2 || w === 3) }
        );
        // Riser for L-leg 2
        addQuad(
          u1, v1,     z0,
          u1, -t.rIn, z0,
          u1, -t.rIn, z1,
          u1, v1,     z1,
          -1, 0, 0, w,
          { type: "latRiser", tierId: t.id, stepIdx: i, worn: false, inLocalShadow: false }
        );
      }
    }
  }

  return faces;
}

// ============================================================================
// PAPER PREPARATION & DARK GREEN POOL
// ============================================================================

function renderPaperPreparation() {
  // Very subtle raw-umber / graphite paper grain in the shadowed lower-left half
  brush.noStroke();
  brush.wash("#e7decb", 55);
  brush.rect(0, 0, 1200, 1200, "corner");

  // Fine paper tooth lines across the sheet
  brush.set("2H", "#dfd5c0", 0.35);
  for (let i = 0; i < 90; i++) {
    let y = random(0, 1200);
    brush.line(0, y, 1200, y + random(-8, 8));
  }
}

function renderDarkGreenPool() {
  // The pool sits at Z = 2398, R = 68 (with submerged steps at R = 80, 74, 68)
  function getPoolQuad(r, z) {
    let pts = [];
    const corners = [[-r, -r], [r, -r], [r, r], [-r, r]];
    for (let c of corners) {
      let p3 = toWorld(c[0], c[1], z, 0);
      pts.push(project3D(p3));
    }
    return pts;
  }

  let outerPool = getPoolQuad(86, 2360);
  let midPool   = getPoolQuad(75, 2405);
  let innerPool = getPoolQuad(65, 2450);
  let corePool  = getPoolQuad(48, 2500);

  brush.noStroke();

  // Deep emerald-viridian-black watercolor washes for the subterranean water
  const poolLayers = [
    { pts: outerPool, col: "#162d24", op: 215, bleed: 0.08 },
    { pts: midPool,   col: "#0f261e", op: 230, bleed: 0.12 },
    { pts: innerPool, col: "#091b14", op: 240, bleed: 0.10 },
    { pts: corePool,  col: "#05110c", op: 250, bleed: 0.06 }
  ];

  for (let pl of poolLayers) {
    brush.fill(pl.col, pl.op);
    brush.fillBleed(pl.bleed, "in");
    brush.fillTexture(0.55, 0.35);
    brush.beginShape(0);
    for (let pt of pl.pts) brush.vertex(pt[0], pt[1]);
    brush.endShape(true);
  }
  brush.noFill();

  // Submerged mossy stone steps dimly visible through the dark green water
  for (let s = 0; s < 3; s++) {
    let r = 82 - s * 6.5;
    let z = 2375 + s * 22;
    let q = getPoolQuad(r, z);
    brush.set("2B", s === 0 ? "#244235" : "#173025", 0.55);
    for (let k = 0; k < 4; k++) {
      let a = q[k], b = q[(k + 1) % 4];
      brush.line(a[0], a[1], b[0], b[1]);
    }
  }

  // Dense graphite cross-hatching over the dark water abyss
  let minX = Math.min(outerPool[0][0], outerPool[3][0]);
  let maxX = Math.max(outerPool[1][0], outerPool[2][0]);
  let minY = Math.min(outerPool[0][1], outerPool[1][1]);
  let maxY = Math.max(outerPool[2][1], outerPool[3][1]);

  brush.set("needle2H", "#06120d", 0.7);
  for (let y = minY + 3; y < maxY - 3; y += 2.2) {
    brush.line(minX + 3, y, maxX - 3, y + random(-1.5, 1.5));
  }
  for (let x = minX + 3; x < maxX - 3; x += 2.6) {
    brush.line(x, minY + 3, x + random(-1.5, 1.5), maxY - 3);
  }

  // Faint geometric sky reflection & delicate surface tension ripples in the dark emerald water
  let cx = (innerPool[0][0] + innerPool[2][0]) * 0.5;
  let cy = (innerPool[0][1] + innerPool[2][1]) * 0.5;

  brush.set("needle2H", "#395e4e", 0.45);
  for (let r = 10; r <= 34; r += 8) {
    let pts = [];
    for (let a = 0; a <= 360; a += 30) {
      let rad = a * Math.PI / 180;
      pts.push([cx + Math.cos(rad) * r + 4, cy + Math.sin(rad) * r * 0.92 - 3]);
    }
    brush.spline(pts, 0.5);
  }

  // Ghostly pale-green glint of reflected upper steps on the water surface
  brush.set("needle2H", "#6c917e", 0.35);
  for (let i = 0; i < 9; i++) {
    let yy = cy - 18 + i * 3.2;
    let halfW = 14 - Math.abs(i - 4) * 2.2;
    brush.line(cx + 6 - halfW, yy, cx + 6 + halfW, yy);
  }
}

// ============================================================================
// WATERCOLOR GLAZES (SEPIA & RAW SIENNA ON SUNLIT STONE) & ABYSSAL MASS
// ============================================================================

function renderWatercolorGlazesAndWashes(faces) {
  brush.noStroke();

  // 1. Consolidate and apply thin Sepia & Raw-Sienna watercolor glazes ONLY where stone catches light
  // We sample sunlit faces and group by warm glaze tone
  let rawSiennaFaces = [];
  let sepiaGlazeFaces = [];

  for (let f of faces) {
    let L = f.lighting;
    let pts = f.pts2D;

    // Base tonal wash for every stone face (fast solid brush.wash)
    let washCol, washOp;
    if (L.depth > 0.68) {
      // Deep abyssal tiers: heavy charcoal-black wash
      washCol = L.light > 0.25 ? "#2b2a28" : "#151617";
      washOp = map(L.depth, 0.68, 1.0, 155, 235);
    } else if (L.isSunlitGlaze) {
      // Sunlit stone catches warm golden raw-sienna or sepia undertone
      washCol = L.sun > 0.52 ? "#e8cfa6" : "#d8b482";
      washOp = map(L.sun, 0.34, 0.9, 55, 115);
      if (f.meta.type === "landing" || (f.meta.stepIdx % 2 === 0 && f.meta.tierId <= 1)) {
        if (L.sun > 0.50) rawSiennaFaces.push(f);
        else sepiaGlazeFaces.push(f);
      }
    } else {
      // Cool/neutral hard-graphite shadow planes (zero warm glaze)
      if (L.light > 0.42) {
        washCol = "#cbc4b6";
        washOp = 85;
      } else if (L.light > 0.22) {
        washCol = "#8a857c";
        washOp = 135;
      } else {
        washCol = "#43423f";
        washOp = 180;
      }
    }

    brush.wash(washCol, washOp);
    brush.beginShape(0);
    for (let p of pts) brush.vertex(p[0], p[1]);
    brush.endShape(true);
  }
  brush.noWash();

  // 2. Apply true bleeding Watercolor Glazes (brush.fill) on strategic sunlit stone regions
  // Batch 1: Thin Raw-Sienna glaze (#c68236) where upper treads & landings catch direct sun
  brush.fill("#c68236", 52);
  brush.fillBleed(0.06, "out");
  brush.fillTexture(0.48, 0.32);
  let countSienna = 0;
  for (let i = 0; i < rawSiennaFaces.length; i += 2) {
    if (countSienna > 32) break;
    let pts = rawSiennaFaces[i].pts2D;
    brush.beginShape(0);
    for (let p of pts) brush.vertex(p[0], p[1]);
    brush.endShape(true);
    countSienna++;
  }

  // Batch 2: Thin Sepia glaze (#7d4e29) on raking sunlit masonry and warm step edges
  brush.fill("#7d4e29", 46);
  brush.fillBleed(0.05, "in");
  brush.fillTexture(0.52, 0.38);
  let countSepia = 0;
  for (let i = 0; i < sepiaGlazeFaces.length; i += 2) {
    if (countSepia > 28) break;
    let pts = sepiaGlazeFaces[i].pts2D;
    brush.beginShape(0);
    for (let p of pts) brush.vertex(p[0], p[1]);
    brush.endShape(true);
    countSepia++;
  }
  brush.noFill();

  // 3. Dry-media near-black graphite mass (brush.mass) in the deep abyssal bands (Tier 3 & deep Tier 2)
  // Consolidate the four deep inner wall bands of Tier 3 into 4 large trapezoidal polygons
  const abyssWalls = [0, 1, 2, 3];
  for (let w of abyssWalls) {
    let p0 = project3D(toWorld(-150, -150, 1890, w));
    let p1 = project3D(toWorld( 150, -150, 1890, w));
    let p2 = project3D(toWorld(  72,  -72, 2380, w));
    let p3 = project3D(toWorld( -72,  -72, 2380, w));

    brush.mass("charcoal", "#161718", {
      precision: 0.75,
      strength: 0.85,
      gradient: 0.35,
      outline: false
    });
    brush.beginShape(0);
    brush.vertex(p0[0], p0[1]);
    brush.vertex(p1[0], p1[1]);
    brush.vertex(p2[0], p2[1]);
    brush.vertex(p3[0], p3[1]);
    brush.endShape(true);
  }
  brush.noMass();
}

// ============================================================================
// HARD GRAPHITE CROSS-HATCHING, CHISEL SCARS & WORN TREADS
// ============================================================================

function lerp2D(a, b, t) {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t];
}

function dist2D(a, b) {
  return Math.hypot(b[0] - a[0], b[1] - a[1]);
}

function renderGraphiteArchitecture(faces) {
  for (let idx = 0; idx < faces.length; idx++) {
    let f = faces[idx];
    let pts = f.pts2D; // [p0, p1, p2, p3]
    let L = f.lighting;
    let meta = f.meta;

    let wPx = (dist2D(pts[0], pts[1]) + dist2D(pts[3], pts[2])) * 0.5;
    let hPx = (dist2D(pts[0], pts[3]) + dist2D(pts[1], pts[2])) * 0.5;
    let areaApprox = wPx * hPx;
    if (areaApprox < 6) continue;

    // Choose hard graphite grade and darkness based on illumination and depth
    let darkTone = L.depth > 0.62 ? "#111213" : (L.light < 0.30 ? "#21201e" : (L.isSunlitGlaze ? "#574330" : "#3a3835"));
    let midTone  = L.isSunlitGlaze ? "#6e543b" : "#4f4c47";

    // 1. Controlled Perspective Cross-Hatching across the quad
    // Determine spacing in pixels and number of cross-hatch directions (1 to 4 passes)
    let darkness = 1.0 - L.light * (1.0 - L.depth * 0.75);

    // Pass 1: Longitudinal hatching (along u-axis of stone block: p0->p1 and p3->p2)
    if (darkness > 0.16) {
      let sp1 = map(darkness, 0.16, 1.0, 5.2, 1.8);
      let steps1 = Math.min(26, Math.max(2, Math.floor(hPx / sp1)));
      brush.set("needle2H", midTone, map(darkness, 0.16, 1.0, 0.45, 0.85));
      for (let i = 1; i < steps1; i++) {
        let t = i / steps1;
        let a = lerp2D(pts[0], pts[3], t);
        let b = lerp2D(pts[1], pts[2], t);
        brush.line(a[0], a[1], b[0], b[1]);
      }
    }

    // Pass 2: Transverse cross-hatching (along v-axis of stone block: p0->p3 and p1->p2)
    if (darkness > 0.34) {
      let sp2 = map(darkness, 0.34, 1.0, 5.5, 2.0);
      let steps2 = Math.min(30, Math.max(2, Math.floor(wPx / sp2)));
      brush.set("needle2H", darkTone, map(darkness, 0.34, 1.0, 0.55, 0.95));
      for (let i = 1; i < steps2; i++) {
        let t = i / steps2;
        let a = lerp2D(pts[0], pts[1], t);
        let b = lerp2D(pts[3], pts[2], t);
        brush.line(a[0], a[1], b[0], b[1]);
      }
    }

    // Pass 3: Diagonal 45-degree cross-hatching for deep shadows and risers
    if (darkness > 0.52 && areaApprox > 28) {
      let sp3 = map(darkness, 0.52, 1.0, 5.0, 2.1);
      let diagSteps = Math.min(28, Math.max(3, Math.floor((wPx + hPx) / sp3)));
      brush.set("2H", darkTone, map(darkness, 0.52, 1.0, 0.42, 0.78));
      for (let i = 1; i < diagSteps; i++) {
        let s = (i / diagSteps) * 2.0;
        let a = s <= 1.0 ? lerp2D(pts[0], pts[1], s) : lerp2D(pts[1], pts[2], s - 1.0);
        let b = s <= 1.0 ? lerp2D(pts[0], pts[3], s) : lerp2D(pts[3], pts[2], s - 1.0);
        brush.line(a[0], a[1], b[0], b[1]);
      }
    }

    // Pass 4: Opposite diagonal near-black graphite saturation in the deep tiers
    if (darkness > 0.72 && areaApprox > 35) {
      let diagSteps2 = Math.min(24, Math.max(3, Math.floor((wPx + hPx) / 2.6)));
      brush.set("2B", "#121314", 0.52);
      for (let i = 1; i < diagSteps2; i++) {
        let s = (i / diagSteps2) * 2.0;
        let a = s <= 1.0 ? lerp2D(pts[1], pts[0], s) : lerp2D(pts[0], pts[3], s - 1.0);
        let b = s <= 1.0 ? lerp2D(pts[1], pts[2], s) : lerp2D(pts[2], pts[3], s - 1.0);
        brush.line(a[0], a[1], b[0], b[1]);
      }
    }

    // 2. Ashlar Stone Block Subdivisions & Chisel Scars on larger close-up faces
    if (areaApprox > 190 && L.depth < 0.65) {
      // Masonry vertical joint lines on risers, front walls, and treads
      if (wPx > 32) {
        let numJoints = Math.min(5, Math.floor(wPx / 28));
        brush.set("chiselEdge", darkTone, 0.65);
        for (let j = 1; j <= numJoints; j++) {
          let tj = (j + random(-0.12, 0.12)) / (numJoints + 1);
          let ja = lerp2D(pts[0], pts[1], tj);
          let jb = lerp2D(pts[3], pts[2], tj);
          brush.line(ja[0], ja[1], jb[0], jb[1]);

          // Small chipped corner spall at the mortarless joint
          if (random() < 0.55) {
            let spallPt = lerp2D(ja, jb, random(0.1, 0.9));
            brush.line(spallPt[0] - 2.5, spallPt[1] - 1.5, spallPt[0] + 2.5, spallPt[1] + 1.5);
          }
        }
      }

      // Chisel scar bursts (parallel diagonal drove-chisel marks across dressed sandstone)
      let numBursts = Math.min(5, Math.floor(areaApprox / 420) + 1);
      brush.set("needle2H", L.isSunlitGlaze ? "#66492d" : "#2f2d2a", 0.52);
      for (let b = 0; b < numBursts; b++) {
        let u = random(0.15, 0.85);
        let v = random(0.18, 0.82);
        let topPt = lerp2D(pts[0], pts[1], u);
        let botPt = lerp2D(pts[3], pts[2], u);
        let center = lerp2D(topPt, botPt, v);

        // Direction vector along block + diagonal chisel angle
        let dirX = (pts[1][0] - pts[0][0]) / (wPx + 0.01);
        let dirY = (pts[1][1] - pts[0][1]) / (wPx + 0.01);
        let nX = -dirY, nY = dirX;

        let scarCount = Math.floor(random(4, 8));
        let scarLen = constrain(Math.min(wPx, hPx) * 0.16, 2.5, 7.5);
        for (let s = 0; s < scarCount; s++) {
          let offset = (s - scarCount * 0.5) * 1.9;
          let sx = center[0] + dirX * offset;
          let sy = center[1] + dirY * offset;
          let cx1 = sx + (dirX * 0.55 + nX * 0.82) * scarLen * 0.5;
          let cy1 = sy + (dirY * 0.55 + nY * 0.82) * scarLen * 0.5;
          let cx2 = sx - (dirX * 0.55 + nX * 0.82) * scarLen * 0.5;
          let cy2 = sy - (dirY * 0.55 + nY * 0.82) * scarLen * 0.5;
          brush.line(cx1, cy1, cx2, cy2);
        }
      }
    }

    // 3. Crisp Architectural Edges & Worn Concave Treads
    // Edge p3 -> p2 is the front lip of treads/landings or bottom seam of risers
    let edgeWeight = map(L.depth, 0, 1, 0.85, 0.42);
    brush.set("chiselEdge", darkTone, edgeWeight);

    if (meta.worn && (meta.type === "tread" || meta.type === "landing") && wPx > 18 && L.depth < 0.55) {
      // Render worn tread lip with a subtle concave foot-worn dip in the middle!
      let midLip = lerp2D(pts[3], pts[2], 0.5);
      let midBack = lerp2D(pts[0], pts[1], 0.5);
      // Bow slightly toward the back/down to show centuries of footsteps wearing the sandstone edge
      let dipAmt = constrain(hPx * 0.09, 1.2, 3.8);
      let bowDirX = (pts[3][0] - midBack[0]);
      let bowDirY = (pts[3][1] - midBack[1]);
      let bLen = Math.hypot(bowDirX, bowDirY) + 0.001;
      let ctrlPt = [
        midLip[0] - (bowDirX / bLen) * dipAmt,
        midLip[1] - (bowDirY / bLen) * dipAmt
      ];
      let q1 = lerp2D(pts[3], ctrlPt, 0.55);
      let q2 = lerp2D(ctrlPt, pts[2], 0.45);
      brush.spline([pts[3], q1, ctrlPt, q2, pts[2]], 0.45);

      // Extra fine shading lines right inside the worn hollow of the step
      brush.set("needle2H", midTone, 0.55);
      for (let wLine = 1; wLine <= 3; wLine++) {
        let fDip = wLine * 0.25;
        let sA = lerp2D(pts[3], pts[2], 0.22 + fDip * 0.06);
        let sB = lerp2D(pts[3], pts[2], 0.78 - fDip * 0.06);
        let sMid = [
          ctrlPt[0] - (bowDirX / bLen) * (wLine * 1.1),
          ctrlPt[1] - (bowDirY / bLen) * (wLine * 1.1)
        ];
        brush.spline([sA, sMid, sB], 0.4);
      }

      // Bright sunlit highlight along the worn stone arris if catching sun
      if (L.sun > 0.38) {
        brush.set("cpencil", "#fbf6ea", 0.55);
        brush.spline([
          lerp2D(pts[3], q1, 0.2),
          [ctrlPt[0] - (bowDirX / bLen) * 0.6, ctrlPt[1] - (bowDirY / bLen) * 0.6],
          lerp2D(q2, pts[2], 0.8)
        ], 0.4);
      }
    } else {
      // Standard chiseled stone edge
      brush.line(pts[3][0], pts[3][1], pts[2][0], pts[2][1]);
    }

    // Draw remaining structural edges of the block
    brush.set("needle2H", darkTone, edgeWeight * 0.85);
    brush.line(pts[0][0], pts[0][1], pts[1][0], pts[1][1]);
    brush.line(pts[1][0], pts[1][1], pts[2][0], pts[2][1]);
    brush.line(pts[0][0], pts[0][1], pts[3][0], pts[3][1]);
  }
}

// ============================================================================
// HYPERREAL DENTED BRASS LOTA (POLISHED REFLECTIVE FOCAL POINT)
// ============================================================================

function renderBrassLotaOnLanding() {
  // Place the brass lota on the sunlit North-East slabs of Landing 1 (Z = 1045)
  // World position on Landing 1:
  let lotaBase3D = toWorld(285, -468, 1045, 0);
  let basePt2D = project3D(lotaBase3D);

  // Compute local perspective vertical axis on screen (pointing up along -Z toward camera)
  let lotaTop3D = { x: lotaBase3D.x, y: lotaBase3D.y, z: 1045 - 122 };
  let topPt2D = project3D(lotaTop3D);

  // Axis vector from base to top on screen
  let upX = topPt2D[0] - basePt2D[0];
  let upY = topPt2D[1] - basePt2D[1];
  let upLen = Math.hypot(upX, upY);
  let ux = upX / upLen;
  let uy = upY / upLen;
  // Perpendicular horizontal axis on the vessel
  let rx = -uy;
  let ry = ux;

  // Scale of the lota on the 1200x1200 canvas (~118px belly diameter,photographic presence)
  let R_SCALE = 58.0; // max radius in px
  let H_TILT = 0.82;  // viewing foreshortening along axis
  let ELLIPSE_ASPECT = 0.84; // foreshortening of circular cross-sections seen from above

  // Profile of traditional Indian Brass Lota: v in [0, 1]
  // v=0: resting base, v=0.45: wide spherical belly, v=0.77: pinched neck, v=0.94: flared lip, v=1.0: inner throat
  function lotaProfile(v) {
    let r, h;
    if (v < 0.08) {
      // Foot ring / rounded bottom
      let t = v / 0.08;
      r = 0.34 + 0.24 * Math.sin(t * Math.PI * 0.5);
      h = v * 0.55;
    } else if (v < 0.76) {
      // Bulbous spherical belly curving into shoulder and contracted neck
      let t = (v - 0.08) / 0.68;
      r = 0.58 + 0.42 * Math.sin(t * Math.PI * 0.88) - 0.14 * Math.pow(t, 2.4);
      h = 0.044 + t * 0.72;
    } else if (v < 0.83) {
      // Pinched neck waist
      let t = (v - 0.76) / 0.07;
      r = 0.56 - 0.04 * Math.sin(t * Math.PI);
      h = 0.764 + t * 0.075;
    } else if (v <= 0.95) {
      // Flared trumpet rim / rolled lip
      let t = (v - 0.83) / 0.12;
      r = 0.55 + 0.21 * Math.pow(t, 1.25);
      h = 0.839 + t * 0.12;
    } else {
      // Over the rolled rim into the inner neck
      let t = (v - 0.95) / 0.05;
      r = 0.76 - 0.10 * t;
      h = 0.959 - t * 0.04;
    }
    return { r: r * R_SCALE, h: h * R_SCALE * 1.25 };
  }

  // 7 realistic hand-beaten dents on the brass belly & shoulder
  const dents = [
    { th: -0.45, v: 0.48, radTh: 0.34, radV: 0.13, depth: 0.13 }, // Large prominent sunlit shoulder dent
    { th:  0.22, v: 0.38, radTh: 0.28, radV: 0.11, depth: 0.11 }, // Mid-belly dent catching horizon reflection
    { th: -0.95, v: 0.33, radTh: 0.26, radV: 0.10, depth: 0.09 }, // Left sunlit flank dent
    { th:  0.78, v: 0.55, radTh: 0.30, radV: 0.12, depth: 0.12 }, // Shadow-side shoulder dent
    { th: -0.12, v: 0.62, radTh: 0.22, radV: 0.08, depth: 0.08 }, // Upper shoulder dent below neck
    { th:  0.48, v: 0.24, radTh: 0.25, radV: 0.09, depth: 0.08 }, // Lower belly stone-knock dent
    { th: -0.68, v: 0.56, radTh: 0.20, radV: 0.08, depth: 0.07 }  // Secondary hammer facet dent
  ];

  function evalDentOffset(th, v) {
    if (v > 0.74 || v < 0.10) return { dr: 0, dth: 0, dv: 0 };
    let totalDr = 0, totalDth = 0, totalDv = 0;
    for (let d of dents) {
      let dTh = (th - d.th) / d.radTh;
      let dV  = (v - d.v) / d.radV;
      let r2 = dTh * dTh + dV * dV;
      if (r2 < 1.35) {
        // Smooth dimple with a sharp raised crease rim at r2 ~ 0.75
        let w = Math.exp(-r2 * 2.4) * (1.0 - 0.35 * r2);
        let dw_dr2 = Math.exp(-r2 * 2.4) * (-2.4 * (1.0 - 0.35 * r2) - 0.35);
        totalDr  -= d.depth * R_SCALE * w;
        totalDth -= d.depth * dw_dr2 * (2 * dTh / d.radTh);
        totalDv  -= d.depth * dw_dr2 * (2 * dV / d.radV);
      }
    }
    // Subtle hand-hammered planishing facets across the entire brass pot
    let facet = Math.sin(th * 18.0) * Math.cos(v * 26.0) * 0.012;
    return { dr: totalDr, dth: totalDth + facet, dv: totalDv + facet };
  }

  // Maps (theta, v) on the 3D lota to 2D canvas coordinates
  // theta in [-PI/2, PI/2] is the front-facing hemisphere, or full [-PI, PI] for the top rim
  function lotaPoint2D(th, v) {
    let prof = lotaProfile(v);
    let dent = evalDentOffset(th, v);
    let rad = prof.r + dent.dr;

    // Cross-section ellipse centered at height prof.h along (ux, uy)
    let cx = basePt2D[0] + ux * prof.h * H_TILT;
    let cy = basePt2D[1] + uy * prof.h * H_TILT;

    // theta = 0 faces directly toward the viewer/bottom-left (-ux, -uy)
    // theta < 0 is the sunlit South-West side; theta > 0 is the shadowed North-East side
    let xOff = Math.sin(th) * rad;
    let yOff = -Math.cos(th) * rad * ELLIPSE_ASPECT;

    return [
      cx + rx * xOff + ux * yOff,
      cy + ry * xOff + uy * yOff
    ];
  }

  // --------------------------------------------------------------------------
  // 1. Cast Shadow of the Brass Lota on the Sunlit Sandstone Landing
  // --------------------------------------------------------------------------
  // Sun shines from South-West toward North-East, casting an elliptical shadow + flared rim shadow
  let shDirX = SUN_DIR.x * COS_R - SUN_DIR.y * SIN_R;
  let shDirY = SUN_DIR.x * SIN_R + SUN_DIR.y * COS_R;
  let shLen = Math.hypot(shDirX, shDirY);
  shDirX /= shLen;
  shDirY /= shLen;

  brush.noStroke();
  // Soft warm umber outer penumbra
  brush.fill("#3d2d1e", 130);
  brush.fillBleed(0.06, "out");
  brush.fillTexture(0.45, 0.35);
  brush.beginShape(0.4);
  for (let a = 0; a < 360; a += 20) {
    let rad = a * Math.PI / 180;
    let stretch = (Math.cos(rad) > 0) ? 1.55 : 0.72;
    let sx = basePt2D[0] + shDirX * 26 + Math.cos(rad) * R_SCALE * 0.78 * stretch * shDirX - Math.sin(rad) * R_SCALE * 0.68 * shDirY;
    let sy = basePt2D[1] + shDirY * 26 + Math.cos(rad) * R_SCALE * 0.78 * stretch * shDirY + Math.sin(rad) * R_SCALE * 0.68 * shDirX;
    brush.vertex(sx, sy);
  }
  brush.endShape(true);
  brush.noFill();

  // Crisp dark graphite cross-hatched core cast shadow + contact occlusion under the base
  for (let pass = 0; pass < 3; pass++) {
    let scale = 1.0 - pass * 0.22;
    brush.set(pass === 2 ? "2B" : "needle2H", pass === 2 ? "#0e0d0c" : "#1f1b17", 0.75);
    for (let i = -24; i <= 24; i += 2.1) {
      let f = i / 24;
      let halfChord = Math.sqrt(Math.max(0, 1 - f * f)) * R_SCALE * 0.72 * scale;
      let cx = basePt2D[0] + shDirX * (22 * scale) - shDirY * (i * 1.45 * scale);
      let cy = basePt2D[1] + shDirY * (22 * scale) + shDirX * (i * 1.45 * scale);
      brush.line(
        cx - shDirX * halfChord * 0.65, cy - shDirY * halfChord * 0.65,
        cx + shDirX * halfChord * 1.35, cy + shDirY * halfChord * 1.35
      );
    }
  }

  // --------------------------------------------------------------------------
  // 2. Opaque Metallic Base Washes for the Brass Lota Body & Dark Interior
  // --------------------------------------------------------------------------
  brush.noStroke();

  // Silhouette polygon of the brass body
  let silPts = [];
  for (let v = 0.0; v <= 0.95; v += 0.05) silPts.push(lotaPoint2D(-Math.PI * 0.52, v));
  for (let th = -Math.PI * 0.52; th <= Math.PI * 0.52; th += 0.2) silPts.push(lotaPoint2D(th, 0.95));
  for (let v = 0.95; v >= 0.0; v -= 0.05) silPts.push(lotaPoint2D(Math.PI * 0.52, v));
  for (let th = Math.PI * 0.52; th >= -Math.PI * 0.52; th -= 0.2) silPts.push(lotaPoint2D(th, 0.02));

  // Solid base wash to occlude stone step lines underneath the solid brass pot
  brush.wash("#d8a448", 245);
  brush.beginShape(0.2);
  for (let p of silPts) brush.vertex(p[0], p[1]);
  brush.endShape(true);
  brush.noWash();

  // Rich watercolor brass glazes (golden ochre, raw sienna, burnt umber)
  brush.fill("#c98827", 150);
  brush.fillBleed(0.03, "in");
  brush.fillTexture(0.35, 0.25);
  brush.beginShape(0.2);
  for (let p of silPts) brush.vertex(p[0], p[1]);
  brush.endShape(true);
  brush.noFill();

  // --------------------------------------------------------------------------
  // 3. Photographic Metallic Reflection Shader across the Dented 3D Surface
  // --------------------------------------------------------------------------
  // Evaluate fine micro-strips across (th, v) to render:
  // - Bright sky reflection on upper shoulder (v ~ 0.50..0.72)
  // - Sharp dark reflected stepwell horizon bands across the equator (v ~ 0.34..0.52)
  // - Warm sunlit sandstone bounce light on the lower belly (v ~ 0.10..0.32)
  // - Sharp specular crescents & dark pockets inside each of the 7 dents!

  const N_V = 68;
  const N_TH = 64;

  for (let iv = 0; iv < N_V; iv++) {
    let v0 = iv / N_V;
    let v1 = (iv + 1) / N_V;
    let vm = (v0 + v1) * 0.5;
    if (vm > 0.95) continue;

    // Vertical surface normal pitch nz (negative = facing up toward sky, positive = facing down toward stone)
    let nz;
    if (vm < 0.44) {
      // Lower belly facing downward toward sunlit stone landing
      nz = map(vm, 0.0, 0.44, 0.85, 0.0);
    } else if (vm < 0.76) {
      // Upper shoulder facing upward toward open sky & upper stepwell rim
      nz = map(vm, 0.44, 0.76, 0.0, -0.78);
    } else if (vm < 0.84) {
      // Pinched neck waist facing outward
      nz = map(vm, 0.76, 0.84, -0.2, 0.15);
    } else {
      // Flared trumpet rim facing upward
      nz = map(vm, 0.84, 0.95, 0.1, -0.82);
    }

    for (let ith = 0; ith < N_TH; ith++) {
      let th0 = map(ith, 0, N_TH, -Math.PI * 0.52, Math.PI * 0.52);
      let th1 = map(ith + 1, 0, N_TH, -Math.PI * 0.52, Math.PI * 0.52);
      let thm = (th0 + th1) * 0.5;

      let dent = evalDentOffset(thm, vm);
      let nPitch = nz + dent.dv * 3.6;
      let nYaw   = thm + dent.dth * 2.8;

      // Sun is on the left/front (nYaw ~ -0.55, nPitch ~ -0.48)
      let dSun = Math.hypot(nYaw - (-0.52), nPitch - (-0.48));
      let dRimSpec = Math.hypot(nYaw - (-0.45), vm - 0.93);

      // Compute photorealistic brass reflection tone & stroke color
      let col, weight, bName = "needle2H";

      if (dSun < 0.19 || (vm > 0.90 && dRimSpec < 0.35)) {
        // Searing white-gold specular highlight (sun reflection or dent ridge glint)
        col = dSun < 0.10 ? "#fffef7" : "#fff3be".replace("", "");
        bName = "cpencil";
        weight = 0.85;
      } else if (nPitch < -0.22) {
        // Sky & sunlit upper-tier reflection on shoulder/lip
        let skyVal = Math.sin(nYaw * 3.0 + nPitch * 8.0);
        if (nYaw < 0.15) {
          col = skyVal > 0 ? "#f7e29c" : "#dfad46";
          weight = 0.65;
        } else {
          // Shadowed right shoulder reflecting opposite stepwell wall
          col = skyVal > 0 ? "#9c6d27" : "#5e3d14";
          weight = 0.75;
        }
      } else if (nPitch >= -0.22 && nPitch <= 0.24) {
        // Dark "Horizon Band" reflecting the stacked stepwell tiers & zigzag shadows!
        // Notice how dent.dv warps nPitch into the dark band, creating sharp dent reflections!
        let tierStripe = Math.sin((nPitch * 28.0) + Math.sin(nYaw * 6.0) * 1.4);
        if (tierStripe > 0.25) {
          col = nYaw < 0 ? "#4a2c0f" : "#211408";
          weight = 0.88;
        } else {
          col = nYaw < 0 ? "#8c591e" : "#38220d";
          weight = 0.78;
        }
      } else {
        // Lower belly reflecting the warm sunlit sandstone landing directly underneath!
        if (vm < 0.08) {
          // Dark contact occlusion at base
          col = "#170e06";
          weight = 0.92;
        } else if (nYaw < 0.25) {
          // Warm golden-amber bounce light from sunlit stone slab
          col = nPitch > 0.52 ? "#b57422" : "#e3a73d";
          weight = 0.70;
        } else {
          // Core shadow side on lower right belly
          col = "#3d240c";
          weight = 0.82;
        }
      }

      let pA = lotaPoint2D(th0, vm);
      let pB = lotaPoint2D(th1, vm);
      let pC = lotaPoint2D(thm, v0);
      let pD = lotaPoint2D(thm, v1);

      brush.set(bName, col, weight);
      brush.line(pA[0], pA[1], pB[0], pB[1]);
      // Cross-contour vertical reflection strokes for dense metallic sheen
      if ((ith + iv) % 2 === 0) {
        brush.line(pC[0], pC[1], pD[0], pD[1]);
      }
    }
  }

  // --------------------------------------------------------------------------
  // 4. Photographic Dent Crease Highlights & Tarnished Patina Accents
  // --------------------------------------------------------------------------
  for (let d of dents) {
    // Draw the sharp lower-right crescent specular ridge and upper-left dark core of each dent
    let ridgePts = [];
    let corePts = [];
    for (let a = -Math.PI * 0.85; a <= Math.PI * 0.85; a += 0.25) {
      let thR = d.th + Math.cos(a) * d.radTh * 0.72;
      let vR  = d.v  + Math.sin(a) * d.radV  * 0.72;
      if (a > -0.4 && a < 2.0) ridgePts.push(lotaPoint2D(thR, vR));
      if (a <= 0.2) corePts.push(lotaPoint2D(d.th + Math.cos(a) * d.radTh * 0.38, d.v + Math.sin(a) * d.radV * 0.38));
    }
    if (ridgePts.length >= 3) {
      brush.set("cpencil", "#fffdf2", 0.62);
      brush.spline(ridgePts, 0.5);
    }
    if (corePts.length >= 3) {
      brush.set("needle2H", "#1c1006", 0.78);
      brush.spline(corePts, 0.5);
    }
  }

  // --------------------------------------------------------------------------
  // 5. The Rolled Brass Rim & Deep Shadowed Interior Throat
  // --------------------------------------------------------------------------
  // Draw the elliptical interior opening at v = 0.96 across all 360 degrees
  let throatPts = [];
  let outerLipPts = [];
  for (let a = 0; a < 360; a += 10) {
    let th = (a - 180) * Math.PI / 180;
    let profIn = lotaProfile(0.98);
    let profOut = lotaProfile(0.945);

    let cxIn = basePt2D[0] + ux * profIn.h * H_TILT;
    let cyIn = basePt2D[1] + uy * profIn.h * H_TILT;
    let xIn = Math.sin(th) * profIn.r;
    let yIn = -Math.cos(th) * profIn.r * ELLIPSE_ASPECT;
    throatPts.push([cxIn + rx * xIn + ux * yIn, cyIn + ry * xIn + uy * yIn]);

    let cxOut = basePt2D[0] + ux * profOut.h * H_TILT;
    let cyOut = basePt2D[1] + uy * profOut.h * H_TILT;
    let xOut = Math.sin(th) * profOut.r;
    let yOut = -Math.cos(th) * profOut.r * ELLIPSE_ASPECT;
    outerLipPts.push([cxOut + rx * xOut + ux * yOut, cyOut + ry * xOut + uy * yOut]);
  }

  // Dark interior hollow of the lota
  brush.noStroke();
  brush.wash("#1b1108", 245);
  brush.beginShape(0.3);
  for (let p of throatPts) brush.vertex(p[0], p[1]);
  brush.endShape(true);
  brush.noWash();

  // Reversed internal reflection inside the brass throat (warm gold on right inside wall, pitch black on left inside wall)
  for (let i = -24; i <= 24; i++) {
    let f = i / 24; // -1 (left inside) to +1 (right inside)
    let profIn = lotaProfile(0.975);
    let cxIn = basePt2D[0] + ux * profIn.h * H_TILT;
    let cyIn = basePt2D[1] + uy * profIn.h * H_TILT;
    let halfH = Math.sqrt(Math.max(0, 1 - f * f)) * profIn.r * ELLIPSE_ASPECT;
    let xOff = f * profIn.r;

    let pTop = [cxIn + rx * xOff - ux * halfH, cyIn + ry * xOff - uy * halfH];
    let pBot = [cxIn + rx * xOff + ux * halfH, cyIn + ry * xOff + uy * halfH];

    // Inside a vessel, the side opposite the sun (f > 0.15) catches warm internal sunlight!
    let inCol = f < -0.1 ? "#0e0904" : (f < 0.35 ? "#38210b" : (f < 0.72 ? "#8f5b1d" : "#cfa244"));
    brush.set("needle2H", inCol, 0.85);
    brush.line(pTop[0], pTop[1], pBot[0], pBot[1]);
  }

  // Gleaming rolled brass lip between outerLipPts and throatPts
  for (let i = 0; i < outerLipPts.length; i++) {
    let pOut = outerLipPts[i];
    let pIn  = throatPts[i];
    let nextOut = outerLipPts[(i + 1) % outerLipPts.length];

    // Brightest specular highlight on the front-left and back-right curves of the rolled torus rim
    let isGlint = (i >= 5 && i <= 15) || (i >= 23 && i <= 31);
    brush.set(isGlint ? "cpencil" : "needle2H", isGlint ? "#fffef6" : "#b88028", isGlint ? 0.9 : 0.7);
    brush.line(pOut[0], pOut[1], nextOut[0], nextOut[1]);
    brush.line(pOut[0], pOut[1], pIn[0], pIn[1]);
  }

  // Final razor-sharp graphite contour around the lota silhouette & neck engraving rings
  brush.set("needle2H", "#241608", 0.65);
  for (let ringV of [0.76, 0.79, 0.82]) {
    let ringPts = [];
    for (let th = -Math.PI * 0.5; th <= Math.PI * 0.5; th += 0.15) {
      ringPts.push(lotaPoint2D(th, ringV));
    }
    brush.spline(ringPts, 0.5);
  }

  // Crisp left and right outer contour lines of the brass vessel
  let leftContour = [], rightContour = [];
  for (let v = 0.02; v <= 0.95; v += 0.04) {
    leftContour.push(lotaPoint2D(-Math.PI * 0.51, v));
    rightContour.push(lotaPoint2D(Math.PI * 0.51, v));
  }
  brush.set("needle2H", "#3b250e", 0.62);
  brush.spline(leftContour, 0.45);
  brush.set("needle2H", "#140c04", 0.75);
  brush.spline(rightContour, 0.45);
}

