  // Custom brushes for hyperreal muscle fibers, creamy fat septa, wet highlights, and tissue creases
  brush.add("flesh_fiber", {
    type: "default",
    weight: 0.42,
    scatter: 0.14,
    sharpness: 0.68,
    grain: 9,
    opacity: 65,
