    noise: 0.7
  });

  // Precompute tissue wrinkle lines for physical paper-fold displacement & graphite rendering
  initWrinkles();
}

function initWrinkles() {
  const defs = [
    // Major diagonal & cross-tension folds across the pattern tissue
    { x1: 110, y1: 190, x2: 1090, y2: 430, amp: 18, freq: 2.2, shift: 2.8, sharp: 0.9 },
    { x1: 85,  y1: 580, x2: 1120, y2: 310, amp: 24, freq: 1.7, shift: -3.2, sharp: 0.85 },
    { x1: 160, y1: 880, x2: 1080, y2: 670, amp: 15, freq: 2.5, shift: 2.4, sharp: 0.9 },
    { x1: 340, y1: 75,  x2: 680,  y2: 1120, amp: 22, freq: 1.9, shift: -2.5, sharp: 0.8 },
    { x1: 790, y1: 85,  x2: 460,  y2: 1110, amp: 19, freq: 2.1, shift: 2.1, sharp: 0.75 },
    { x1: 90,  y1: 360, x2: 740,  y2: 1090, amp: 16, freq: 2.8, shift: -1.8, sharp: 0.7 },
    { x1: 490, y1: 95,  x2: 1110, y2: 860, amp: 14, freq: 2.4, shift: 1.9, sharp: 0.8 },
    // Short crinkle branches & radial pinches near the salmon weight
    { x1: 220, y1: 440, x2: 520,  y2: 260, amp: 9,  freq: 3.5, shift: 1.4, sharp: 0.95 },
    { x1: 620, y1: 740, x2: 990,  y2: 590, amp: 11, freq: 3.1, shift: -1.6, sharp: 0.9 },
    { x1: 140, y1: 710, x2: 490,  y2: 830, amp: 10, freq: 3.0, shift: 1.3, sharp: 0.85 },
    { x1: 730, y1: 290, x2: 1060, y2: 490, amp: 12, freq: 2.7, shift: -1.5, sharp: 0.85 },
    { x1: 540, y1: 850, x2: 890,  y2: 1060, amp: 10, freq: 3.2, shift: 1.5, sharp: 0.8 },
    { x1: 120, y1: 260, x2: 410,  y2: 120, amp: 8,  freq: 3.4, shift: -1.2, sharp: 0.75 }
  ];

  for (let i = 0; i < defs.length; i++) {
    let d = defs[i];
    let pts = [];
    let steps = 28;
    let dx = d.x2 - d.x1;
    let dy = d.y2 - d.y1;
    let len = sqrt(dx * dx + dy * dy);
    let nx = -dy / len;
    let ny = dx / len;
    for (let s = 0; s <= steps; s++) {
      let t = s / steps;
      let env = sin(t * 180);
      let n = (noise(i * 13.7 + t * d.freq, i * 7.1) - 0.5) * 2.0 * d.amp * env;
      let jag = (noise(i * 31.3 + t * 9.0) - 0.5) * 4.5 * env;
      pts.push({
        x: lerp(d.x1, d.x2, t) + nx * (n + jag),
        y: lerp(d.y1, d.y2, t) + ny * (n + jag)
      });
    }
    wrinkles.push({ ...d, pts, nx, ny });
  }
}

// Displaces pattern print lines slightly when crossing a tissue fold
function crinkleDisplace(x, y) {
  let ox = 0;
  let oy = 0;
  for (let w of wrinkles) {
    // Approximate signed distance to wrinkle segment
    let vx = w.x2 - w.x1;
    let vy = w.y2 - w.y1;
    let l2 = vx * vx + vy * vy;
    let t = constrain(((x - w.x1) * vx + (y - w.y1) * vy) / l2, 0, 1);
    let px = w.x1 + t * vx;
    let py = w.y1 + t * vy;
    let distSq = (x - px) * (x - px) + (y - py) * (y - py);
    if (distSq < 2200) {
      let falloff = exp(-distSq / 650);
      ox += w.nx * w.shift * falloff;
      oy += w.ny * w.shift * falloff;
    }
  }
  return [x + ox, y + oy];
}

// =========================================================================
// ANATOMICAL SALMON FILLET PARAMETRIC SURFACE
// u in [0, 1]: 0 = thick anterior head-cut (top-left), 1 = tapered tail-cut (bottom-right)
// v in [0, 1]: 0 = dorsal back-loin cut (upper-right), 1 = thin belly edge (lower-left)
// =========================================================================
function getSpinePoint(u) {
  let x = lerp(248, 952, u);
  let y = lerp(338, 842, u);
  // Subtle S-curve of a relaxed fillet on a flat surface
  let bend = sin(u * 180) * 24 - sin(u * 360) * 9;
  // Normal to diagonal (roughly toward upper-right)
  let nx = 0.582;
  let ny = -0.813;
  return {
    x: x + nx * bend,
    y: y + ny * bend,
    nx: nx,
    ny: ny,
    tx: 0.813,
    ty: 0.582
  };
}

function getFilletPoint(u, v, isPattern = false, seamInset = 0) {
  let uc = constrain(u, 0, 1);
  let vc = constrain(v, 0, 1);
  let sp = getSpinePoint(uc);

  // Dorsal half-width (v = 0, toward upper-right)
  let dorsalW = 148 * pow(1 - 0.52 * uc, 0.78) + 22 * sin(uc * 165);
  // Belly half-width (v = 1, toward lower-left) — wider curve at anterior belly flap, tapering toward tail
  let bellyW = 212 * pow(1 - 0.60 * uc, 1.05) + 34 * sin(pow(uc, 0.8) * 180) - 12 * sin(uc * 340);

  // End-cut rounding / beveling near u = 0 and u = 1
  let endCurveU = 0;
  if (!isPattern) {
    // Anterior cut bows outward slightly across the thick loin, curves back at the belly corner
    let headBow = sin(vc * 165) * 22 - pow(vc, 2.5) * 28;
    // Posterior tail cut angles backward toward the skin/belly edge
    let tailBow = (0.45 - vc) * 34 + sin(vc * 180) * 10;
    endCurveU = (1 - uc) * (1 - uc) * (1 - uc) * headBow + uc * uc * uc * tailBow;
  } else {
    // Pattern piece has cleaner geometric tailoring curves at ends
    let headBow = sin(vc * 160) * 18 - pow(vc, 2.2) * 24;
    let tailBow = (0.45 - vc) * 32 + sin(vc * 180) * 6;
    endCurveU = (1 - uc) * (1 - uc) * (1 - uc) * headBow + uc * uc * uc * tailBow;
  }

  // Organic edge micro-undulation for real fish vs clean curve for pattern
  let edgeRipple = 0;
  if (!isPattern) {
    edgeRipple = (noise(uc * 6.5, vc * 4.2 + 10) - 0.5) * 14 * (0.4 + 0.6 * abs(vc - 0.4));
  }

  // Apply seam inset if drawing inner stitching line or outer cutting line
  let dW = dorsalW - seamInset;
  let bW = bellyW - seamInset;

  let across = lerp(dW, -bW, vc) + edgeRipple;
  let along = endCurveU - seamInset * (uc < 0.5 ? -1 : 1) * 0.25;

  let px = sp.x + sp.nx * across + sp.tx * along;
  let py = sp.y + sp.ny * across + sp.ty * along;

  if (isPattern) {
    // Pattern outline drifts slightly off the fish: shifted +30px right, -24px up, rotated +3.1 deg around center
    let cx = 600, cy = 590;
    let dx = px - cx;
    let dy = py - cy;
    let ang = 3.15;
    let rx = dx * cos(ang) - dy * sin(ang);
    let ry = dx * sin(ang) + dy * cos(ang);
    px = cx + rx + 30;
    py = cy + ry - 24;
    return crinkleDisplace(px, py);
  }

  return [px, py];
}

// Computes the characteristic W / Chevron / S-curve of salmon myocommata (white fat septa)
// At a given myotome index `idx` (can be fractional) and cross-parameter `v` in [0, 1]
function getMyocommaU(idx, v) {
  // Base u position along the fillet with slight anatomical compression toward the tail
  let t = idx / NUM_MYOTOMES;
  let baseU = 0.94 * pow(t, 0.94) + 0.03;

  // Lateral line sits at vLat ≈ 0.36
  let vLat = 0.36;
  let uOffset = 0;

  if (v < vLat) {
    // Dorsal side (v from 0 to 0.36): curves from dorsal edge backward toward tail at lateral line,
    // with a tiny hook near v = 0
    let nd = (vLat - v) / vLat; // 1 at dorsal edge, 0 at lateral line
    uOffset = -0.072 * pow(nd, 1.45) + 0.014 * pow(nd, 3.2);
  } else {
    // Belly side (v from 0.36 to 1.0): sweeps forward toward head, then trails gracefully along the thin belly
    let nb = (v - vLat) / (1.0 - vLat); // 0 at lateral line, 1 at belly rim
    uOffset = -0.145 * pow(nb, 1.32) + 0.042 * pow(nb, 2.8);
  }

  // Subtle organic waviness per septum
  let wave = (noise(idx * 1.7, v * 4.5) - 0.5) * 0.011;
  return baseU + uOffset + wave;
}

function draw() {
  translate(-width / 2, -height / 2);

  // =========================================================================
  // 1. COOL CLINICAL STUDIO SURFACE (UNDERNEATH THE TISSUE)
  // =========================================================================
  background("#c9d3d8");

  brush.noStroke();
  brush.fillBleed(0.32, "out");
  brush.fillTexture(0.45, 0.25);

  // Large cool slate-blue/grey studio washes
  const bgZones = [
    { x: 60,  y: 60,  w: 1080, h: 1080, col: "#bfccd2", op: 95 },
    { x: 180, y: 140, w: 860,  h: 920,  col: "#b3c2c9", op: 75 },
    { x: 40,  y: 680, w: 620,  h: 480,  col: "#c5d1d6", op: 80 },
    { x: 620, y: 80,  w: 520,  h: 540,  col: "#d2dce0", op: 85 }
  ];
  for (let z of bgZones) {
    brush.fill(z.col, z.op);
    brush.rect(z.x, z.y, z.w, z.h);
  }
  brush.noFill();

  // Subtle clinical cutting-mat grid on the cool surface (shows faintly through tissue)
  brush.set("2H", "#9aa8b0", 0.45);
  for (let gx = 100; gx <= 1100; gx += 100) {
    brush.line(gx, 40, gx, 1160);
  }
  for (let gy = 100; gy <= 1100; gy += 100) {
    brush.line(40, gy, 1160, gy);
  }

  // =========================================================================
  // 2. TRANSLUCENT TAN PATTERN TISSUE SHEETS & OVERLAPS
  // =========================================================================
  // Lower overlapping secondary sheet of tissue (bottom-left to upper-mid)
  let sheet2Pts = [
    [35, 310], [740, 120], [920, 980], [95, 1155]
  ];
  brush.noStroke();
  brush.fillBleed(0.12, "in");
  brush.fillTexture(0.55, 0.35);
  brush.fill("#e2dac6", 115);
  drawShapeFromPts(sheet2Pts, 0.05);

  // Main large crinkled pattern tissue sheet covering almost the entire composition
  // Top-right corner is folded over itself, creating a triangular double-layer overlap
  let mainTissuePts = [
    [68, 88], [865, 54], [1135, 305], [1148, 1112], [112, 1142], [54, 620]
  ];
  brush.fill("#e6decb", 135);
  drawShapeFromPts(mainTissuePts, 0.08);

  // Second pass of cool-tan papery tone to give uneven translucent tissue density
  brush.fillBleed(0.28, "out");
  brush.fill("#dcd3be", 75);
  brush.rect(110, 110, 960, 960);

  // Double-layer overlap region where Sheet 1 and Sheet 2 overlap
  let overlapPts = [
    [60, 310], [735, 125], [895, 965], [112, 1135], [56, 620]
  ];
  brush.fillBleed(0.08, "in");
  brush.fill("#dfd5be", 68);
  drawShapeFromPts(overlapPts, 0.04);

  // Folded-over triangular flap at top-right corner (double thickness of tan tissue)
  let foldedFlapPts = [
    [865, 54], [1135, 305], [820, 345]
  ];
  brush.fill("#d9ceb4", 130);
  drawShapeFromPts(foldedFlapPts, 0.03);
  brush.noFill();

  // Crisp paper edges of the tissue sheets in fine graphite + pale edge highlight
  brush.set("2H", "#8d897e", 0.65);
  drawOutlineFromPts(sheet2Pts);
  brush.set("2H", "#7c786e", 0.75);
  drawOutlineFromPts(mainTissuePts);
  drawOutlineFromPts(foldedFlapPts);

  brush.set("cpencil", "#f7f3e8", 0.55);
  brush.line(865, 54, 820, 345);
  brush.line(820, 345, 1135, 305);

  // =========================================================================
  // 3. MOISTURE / NATURAL OIL ABSORPTION HALO AROUND THE SALMON
  // =========================================================================
  // Where raw salmon contacts tissue paper, moisture makes the tissue darker & more translucent
  brush.noStroke();
  brush.fillBleed(0.38, "out");
  brush.fillTexture(0.6, 0.25);

  for (let pass = 0; pass < 2; pass++) {
    let expand = pass === 0 ? -24 : -11;
    let col = pass === 0 ? "#c2bbb0" : "#b0a99e";
    let op = pass === 0 ? 75 : 90;
    brush.fill(col, op);
    brush.beginShape(0.35);
    for (let s = 0; s <= 24; s++) {
      let u = s / 24;
      let p = getFilletPoint(u, 0, false, expand);
      brush.vertex(p[0] + random(-4, 4), p[1] + random(-4, 4));
    }
    for (let s = 24; s >= 0; s--) {
      let u = s / 24;
      let p = getFilletPoint(u, 1, false, expand);
      brush.vertex(p[0] + random(-5, 5), p[1] + random(-5, 5));
    }
    brush.endShape(true);
  }
  brush.noFill();

  // =========================================================================
  // 4. GRAPHITE TISSUE WRINKLES, PLEATS & TRANSLUCENT CREASES
  // =========================================================================
  renderTissueWrinkles();

  // =========================================================================
  // 5. GARMENT PATTERN PRINT ON TISSUE (DASHED LINES, NOTCHES, ARROWS, TEXT)
  // =========================================================================
  renderGarmentPatternPrint();

  // =========================================================================
  // 6. FILLET CONTACT SHADOW & SUBSURFACE BOUNCE GLOW ON TISSUE
  // =========================================================================
  renderFilletShadow();

  // =========================================================================
  // 7. LAYERED WATERCOLOUR & COLOURED PENCIL SALMON FILLET
  // =========================================================================
  renderSalmonWatercolourBase();
  renderSalmonMuscleGrainAndFlakes();
  renderSalmon3DCutBevelAndSkin();
  renderSalmonMyocommataMarbling();
  renderSalmonWetSheenAndHighlights();

  // =========================================================================
  // 8. OVERLAPPING TRANSLUCENT TISSUE WHISPERS & FINAL CLINICAL DETAILS
  // =========================================================================
  renderFinalSurfaceIncidents();

  noLoop();
}

function drawShapeFromPts(pts, curv = 0.05) {
  brush.beginShape(curv);
  for (let p of pts) {
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);
}

function drawOutlineFromPts(pts) {
  for (let i = 0; i < pts.length; i++) {
    let a = pts[i];
    let b = pts[(i + 1) % pts.length];
    brush.line(a[0], a[1], b[0], b[1]);
  }
}

// =========================================================================
// TISSUE WRINKLES & SEE-THROUGH GRAPHITE RENDERING
// =========================================================================
function renderTissueWrinkles() {
  // Subtle tonal shading bands along major folds
  for (let w of wrinkles) {
    // Broad faint graphite shadow along one side of the crease
    brush.set("tissue_graphite", "#8c897f", 1.5 * w.sharp);
    let shadowPts = w.pts.map(p => [p.x + w.nx * 3.2, p.y + w.ny * 3.2, random(0.3, 0.9)]);
    brush.spline(shadowPts, 0.45);

    let shadowPts2 = w.pts.map(p => [p.x + w.nx * 6.0, p.y + w.ny * 6.0, random(0.2, 0.6)]);
    brush.set("tissue_graphite", "#9e9b91", 1.1);
    brush.spline(shadowPts2, 0.45);

    // Crisp graphite crease core line
    brush.set("2H", "#78756c", 0.55 * w.sharp);
    let corePts = w.pts.map(p => [p.x, p.y, random(0.4, 1.1)]);
    brush.spline(corePts, 0.35);

    // Bright paper ridge highlight immediately adjacent to the crease
    brush.set("cpencil", "#f8f4ea", 0.75 * w.sharp);
    let hiPts = w.pts.map(p => [p.x - w.nx * 1.8, p.y - w.ny * 1.8, random(0.5, 1.2)]);
    brush.spline(hiPts, 0.35);
  }

  // Fine micro-crinkle network in faint 2H graphite across the tissue corners and around the fillet
  for (let i = 0; i < 65; i++) {
    let cx = random(80, 1120);
    let cy = random(80, 1120);
    let ang = random(360);
    let len = random(28, 95);
    let midX = cx + cos(ang) * len * 0.5 + random(-8, 8);
    let midY = cy + sin(ang) * len * 0.5 + random(-8, 8);
    let ex = cx + cos(ang) * len;
    let ey = cy + sin(ang) * len;

    brush.set("2H", "#949086", random(0.28, 0.48));
    brush.spline([[cx, cy, 0.2], [midX, midY, 0.9], [ex, ey, 0.2]], 0.4);

    brush.set("cpencil", "#f5f1e6", random(0.3, 0.5));
    brush.line(cx + 1.5, cy - 1.5, midX + 1.5, midY - 1.5);
  }

  // Translucent pinched pleat near bottom-right and top-left where tissue bunches slightly
  const pleats = [
    [[140, 210], [390, 295], [382, 312], [135, 224]],
    [[790, 885], [1085, 790], [1092, 806], [795, 900]],
    [[195, 860], [510, 965], [504, 979], [190, 872]]
  ];
  brush.noStroke();
  brush.fillBleed(0.04, "in");
  for (let pl of pleats) {
    brush.fill("#d4cbb6", 90);
    drawShapeFromPts(pl, 0.02);
  }
  brush.noFill();
  for (let pl of pleats) {
    brush.set("HB", "#7b776e", 0.45);
    brush.line(pl[0][0], pl[0][1], pl[1][0], pl[1][1]);
    brush.set("cpencil", "#faf7ef", 0.65);
    brush.line(pl[3][0], pl[3][1], pl[2][0], pl[2][1]);
  }
}

// =========================================================================
// GARMENT PATTERN PRINT (BLACK DASHED CUT LINES, NOTCHES, ARROWS, TEXT)
// =========================================================================
function renderGarmentPatternPrint() {
  // Build dense polyline for the outer CUTTING LINE of the fillet pattern piece
  let outerCut = [];
  let innerSeam = [];

  const N_EDGE = 70;
  // Dorsal edge (u: 0 -> 1, v = 0)
  for (let i = 0; i <= N_EDGE; i++) {
    let u = i / N_EDGE;
    outerCut.push(getFilletPoint(u, 0, true, 0));
    innerSeam.push(getFilletPoint(u, 0, true, 26));
  }
  // Tail cut edge (u = 1, v: 0 -> 1)
  for (let i = 1; i <= 24; i++) {
    let v = i / 24;
    outerCut.push(getFilletPoint(1, v, true, 0));
    innerSeam.push(getFilletPoint(1, v, true, 26));
  }
  // Belly edge (u: 1 -> 0, v = 1)
  for (let i = N_EDGE - 1; i >= 0; i--) {
    let u = i / N_EDGE;
    outerCut.push(getFilletPoint(u, 1, true, 0));
    innerSeam.push(getFilletPoint(u, 1, true, 26));
  }
  // Anterior head cut edge (u = 0, v: 1 -> 0)
  for (let i = 23; i >= 1; i--) {
    let v = i / 24;
    outerCut.push(getFilletPoint(0, v, true, 0));
    innerSeam.push(getFilletPoint(0, v, true, 26));
  }

  // 1. Draw the outer Black Dashed Cutting Line (industrial pattern print ink)
  drawDashedPolyline(outerCut, 18, 9, "rotring", "#25292c", 1.15);
  // Subtle ink bleed / double-strike ghost line typical of flexographic pattern tissue print
  drawDashedPolyline(outerCut, 18, 9, "2H", "#555b60", 0.55);

  // 2. Draw the inner Seam Allowance Line (finer short-dashed stitch line, 15mm / 5/8" inset)
  drawDashedPolyline(innerSeam, 8, 6, "rotring", "#3e4448", 0.65);

  // Small tailor's awl/pivot circles at the 4 corners of the inner seam allowance
  const seamCorners = [
    getFilletPoint(0, 0, true, 26),
    getFilletPoint(1, 0, true, 26),
    getFilletPoint(1, 1, true, 26),
    getFilletPoint(0, 1, true, 26)
  ];
  for (let sc of seamCorners) {
    brush.set("rotring", "#32373b", 0.65);
    brush.circle(sc[0], sc[1], 4.5, 0.15);
    brush.line(sc[0] - 7, sc[1], sc[0] + 7, sc[1]);
    brush.line(sc[0], sc[1] - 7, sc[0], sc[1] + 7);
  }

  // 3. Triangular Garment Pattern Notches along the cutting line
  // Single, double, and triple notches along dorsal and belly edges
  const dorsalNotches = [
    { u: 0.18, count: 1 },
    { u: 0.52, count: 2 },
    { u: 0.82, count: 1 }
  ];
  for (let dn of dorsalNotches) {
    for (let k = 0; k < dn.count; k++) {
      let uk = dn.u + (k - (dn.count - 1) * 0.5) * 0.022;
      drawPatternNotch(uk, 0, -1);
    }
  }

  const bellyNotches = [
    { u: 0.24, count: 2 },
    { u: 0.62, count: 3 },
    { u: 0.88, count: 1 }
  ];
  for (let bn of bellyNotches) {
    for (let k = 0; k < bn.count; k++) {
      let uk = bn.u + (k - (bn.count - 1) * 0.5) * 0.024;
      drawPatternNotch(uk, 1, 1);
    }
  }

  // End-cut notches
  drawPatternNotchEnd(0, 0.42, -1);
  drawPatternNotchEnd(1, 0.48, 1);

  // 4. Tailoring Darts ("BELLY DART" & "LOIN PLEAT") printed on the pattern piece
  drawPatternDart(0.38, 1.0, 0.41, 0.58, 0.032);
  drawPatternDart(0.72, 0.0, 0.70, 0.34, 0.024);

  // 5. Long Grainline Arrow running diagonally through the pattern piece (protruding past both ends)
  let gStart = getFilletPoint(-0.12, 0.44, true, 0);
  let gEnd   = getFilletPoint(1.14, 0.44, true, 0);
  drawGrainArrow(gStart[0], gStart[1], gEnd[0], gEnd[1], "GRAINLINE - SALMO 04");

  // 6. Lengthen / Shorten Here double adjustment lines across the pattern
  for (let offset of [-5, 5]) {
    let pA = getFilletPoint(0.28, 0, true, 10 + offset);
    let pB = getFilletPoint(0.28 + offset * 0.0015, 1, true, 10 + offset);
    // Shift along u slightly for the parallel pair
    let uLine = 0.26 + (offset > 0 ? 0.012 : 0);
    let l1 = getFilletPoint(uLine, 0.02, true, 0);
    let l2 = getFilletPoint(uLine, 0.98, true, 0);
    brush.set("rotring", "#3a4045", 0.6);
    drawCrinkledSegment(l1[0], l1[1], l2[0], l2[1]);
  }

  // 7. Secondary Adjacent Garment Pattern Piece Lines near canvas edges (uncanny sewing sheet context)
  // Top-right adjacent sleeve/collar-like curve with dashed cut line & notches
  let adjPiece1 = [];
  for (let t = 0; t <= 1; t += 0.04) {
    let x = lerp(580, 1130, t);
    let y = 95 + sin(t * 150) * 65 + t * 140;
    adjPiece1.push(crinkleDisplace(x, y));
  }
  drawDashedPolyline(adjPiece1, 16, 8, "rotring", "#32373b", 0.95);

  // Bottom-left adjacent pattern piece boundary
  let adjPiece2 = [];
  for (let t = 0; t <= 1; t += 0.04) {
    let x = lerp(75, 640, t);
    let y = 760 + sin(t * 140) * 55 + t * 340;
    adjPiece2.push(crinkleDisplace(x, y));
  }
  drawDashedPolyline(adjPiece2, 16, 8, "rotring", "#32373b", 0.95);

  // Secondary vertical grain arrow on bottom-left pattern piece
  drawGrainArrow(155, 620, 142, 1060, "STRAIGHT GRAIN");

  // 8. Faded Part Numbers, Size Specs, and Registration Marks on the Tissue
  let angMain = 38.6; // matches fillet diagonal
