  drawVectorString("CUT 1 RAW / SEAM 15MM", 618, 366, 9.5, angMain, "#52585e", 0.55);

  // Text near anterior top-left (partially peeking out from under the loin edge)
  drawVectorString("04-A", 205, 215, 26, angMain, "#3e4449", 0.85);
  drawVectorString("ANTERIOR NECK CUT", 175, 252, 9.5, angMain, "#4e5459", 0.55);
  drawVectorString("NOTCH 1", 392, 198, 8.5, angMain - 6, "#4e5459", 0.5);
  drawVectorString("NOTCH 2", 628, 392, 8.5, angMain - 4, "#4e5459", 0.5);

  // Text near belly side (bottom-left of fillet, where pattern drifts off the fish)
  drawVectorString("BELLY DART", 315, 668, 9.5, angMain - 12, "#464c52", 0.55);
  drawVectorString("TRIM MEMBRANE", 535, 855, 9.5, angMain - 8, "#464c52", 0.55);
  drawVectorString("SIZE 42 / 680G", 775, 965, 11, angMain, "#41474c", 0.65);
  drawVectorString("TAIL TAPER 1:4", 945, 725, 9.5, angMain, "#4a5056", 0.55);

  // Labels on the adjacent pattern pieces
  drawVectorString("PART 15 - VENTRAL FLAP", 180, 945, 10.5, 28, "#4c5257", 0.6);
  drawVectorString("08", 920, 145, 30, 14, "#484e54", 0.8);
  drawVectorString("FOLD LINE", 855, 315, 9, -6, "#555b60", 0.55);

  // Technical registration marks (crosshairs + double circles) on tissue
  const regMarks = [
    [160, 460], [985, 420], [435, 995], [885, 1030], [495, 135]
  ];
  for (let rm of regMarks) {
    let p = crinkleDisplace(rm[0], rm[1]);
    brush.set("rotring", "#3d4348", 0.55);
    brush.circle(p[0], p[1], 11, 0.1);
    brush.circle(p[0], p[1], 5, 0.1);
    brush.line(p[0] - 18, p[1], p[0] + 18, p[1]);
    brush.line(p[0], p[1] - 18, p[0], p[1] + 18);
  }
}

function drawCrinkledSegment(x1, y1, x2, y2) {
  let steps = max(2, floor(dist(x1, y1, x2, y2) / 18));
  for (let i = 0; i < steps; i++) {
    let t0 = i / steps;
    let t1 = (i + 1) / steps;
    let p0 = crinkleDisplace(lerp(x1, x2, t0), lerp(y1, y2, t0));
    let p1 = crinkleDisplace(lerp(x1, x2, t1), lerp(y1, y2, t1));
    brush.line(p0[0], p0[1], p1[0], p1[1]);
  }
}

function drawDashedPolyline(pts, dashLen, gapLen, brushName, col, weight) {
  brush.set(brushName, col, weight);
  let drawing = true;
  let remain = dashLen;

  for (let i = 0; i < pts.length - 1; i++) {
    let x1 = pts[i][0], y1 = pts[i][1];
    let x2 = pts[i + 1][0], y2 = pts[i + 1][1];
    let segLen = dist(x1, y1, x2, y2);
    if (segLen < 0.1) continue;

    let dx = (x2 - x1) / segLen;
    let dy = (y2 - y1) / segLen;
    let covered = 0;

    while (covered < segLen) {
      let step = min(remain, segLen - covered);
      if (drawing) {
        let sx = x1 + dx * covered;
        let sy = y1 + dy * covered;
        let ex = x1 + dx * (covered + step);
        let ey = y1 + dy * (covered + step);
        brush.line(sx, sy, ex, ey);
      }
      covered += step;
      remain -= step;
      if (remain <= 0.01) {
        drawing = !drawing;
        remain = drawing ? dashLen : gapLen;
      }
    }
  }
}

function drawPatternNotch(u, vEdge, dirSign) {
  let pCenter = getFilletPoint(u, vEdge, true, 0);
  let pPrev   = getFilletPoint(u - 0.011, vEdge, true, 0);
  let pNext   = getFilletPoint(u + 0.011, vEdge, true, 0);
  // Outward tip and inward seam tick
  let pTipOut = getFilletPoint(u, vEdge, true, -15);
  let pTipIn  = getFilletPoint(u, vEdge, true, 16);

  brush.set("rotring", "#24282b", 0.95);
  brush.line(pPrev[0], pPrev[1], pTipOut[0], pTipOut[1]);
  brush.line(pNext[0], pNext[1], pTipOut[0], pTipOut[1]);
  brush.set("rotring", "#3d4348", 0.65);
  brush.line(pCenter[0], pCenter[1], pTipIn[0], pTipIn[1]);
}

function drawPatternNotchEnd(uEnd, v, dirSign) {
  let pPrev = getFilletPoint(uEnd, v - 0.03, true, 0);
  let pNext = getFilletPoint(uEnd, v + 0.03, true, 0);
  let pCent = getFilletPoint(uEnd, v, true, 0);
  let pTip  = getFilletPoint(uEnd, v, true, -14);

  brush.set("rotring", "#24282b", 0.95);
  brush.line(pPrev[0], pPrev[1], pTip[0], pTip[1]);
  brush.line(pNext[0], pNext[1], pTip[0], pTip[1]);
  brush.line(pCent[0], pCent[1], pTip[0], pTip[1]);
}

function drawPatternDart(uBase, vBase, uApex, vApex, halfWidthU) {
  let pL = getFilletPoint(uBase - halfWidthU, vBase, true, 0);
  let pR = getFilletPoint(uBase + halfWidthU, vBase, true, 0);
  let pC = getFilletPoint(uBase, vBase, true, 0);
  let pA = getFilletPoint(uApex, vApex, true, 0);

  brush.set("rotring", "#33383c", 0.75);
  drawCrinkledSegment(pL[0], pL[1], pA[0], pA[1]);
  drawCrinkledSegment(pR[0], pR[1], pA[0], pA[1]);
  brush.set("rotring", "#4e5459", 0.5);
  drawCrinkledSegment(pC[0], pC[1], pA[0], pA[1]);
  brush.circle(pA[0], pA[1], 3.5, 0.1);
}

function drawGrainArrow(x1, y1, x2, y2, label) {
  brush.set("rotring", "#2c3135", 0.85);
  drawCrinkledSegment(x1, y1, x2, y2);

  let ang = atan2(y2 - y1, x2 - x1);
  let headLen = 18;
  // Start arrowhead
  let s0 = crinkleDisplace(x1, y1);
  let s1 = crinkleDisplace(x1 + cos(ang + 24) * headLen, y1 + sin(ang + 24) * headLen);
  let s2 = crinkleDisplace(x1 + cos(ang - 24) * headLen, y1 + sin(ang - 24) * headLen);
  brush.line(s0[0], s0[1], s1[0], s1[1]);
  brush.line(s0[0], s0[1], s2[0], s2[1]);
  brush.line(s1[0], s1[1], s2[0], s2[1]);

  // End arrowhead
  let e0 = crinkleDisplace(x2, y2);
  let e1 = crinkleDisplace(x2 - cos(ang + 24) * headLen, y2 - sin(ang + 24) * headLen);
  let e2 = crinkleDisplace(x2 - cos(ang - 24) * headLen, y2 - sin(ang - 24) * headLen);
  brush.line(e0[0], e0[1], e1[0], e1[1]);
  brush.line(e0[0], e0[1], e2[0], e2[1]);
  brush.line(e1[0], e1[1], e2[0], e2[1]);

  if (label) {
    let mx = lerp(x1, x2, 0.16);
    let my = lerp(y1, y2, 0.16);
    let nx = -sin(ang) * 14;
    let ny = cos(ang) * 14;
    drawVectorString(label, mx + nx, my + ny, 9.5, ang, "#3d4348", 0.55);
  }
}

function drawVectorString(str, x, y, h, angleDeg, col, weight) {
  brush.set("rotring", col, weight);
  let w = h * 0.62;
  let spacing = h * 0.88;
  let ca = cos(angleDeg);
  let sa = sin(angleDeg);

  for (let i = 0; i < str.length; i++) {
    let ch = str[i].toUpperCase();
    let strokes = GLYPHS[ch];
    if (!strokes) continue;

    let ox = i * spacing;
    for (let poly of strokes) {
      for (let j = 0; j < poly.length - 1; j++) {
        let lx1 = ox + poly[j][0] * w;
        let ly1 = (poly[j][1] - 1) * h;
        let lx2 = ox + poly[j + 1][0] * w;
        let ly2 = (poly[j + 1][1] - 1) * h;

        let gx1 = x + lx1 * ca - ly1 * sa;
        let gy1 = y + lx1 * sa + ly1 * ca;
        let gx2 = x + lx2 * ca - ly2 * sa;
        let gy2 = y + lx2 * sa + ly2 * ca;

        let p1 = crinkleDisplace(gx1, gy1);
        let p2 = crinkleDisplace(gx2, gy2);
        brush.line(p1[0], p1[1], p2[0], p2[1]);
      }
    }
  }
}

// =========================================================================
// 6. FILLET CONTACT SHADOW & SUBSURFACE CORAL BOUNCE
// =========================================================================
function renderFilletShadow() {
  brush.noStroke();
  brush.fillBleed(0.24, "out");
  brush.fillTexture(0.5, 0.3);

  // Soft cool-umber contact shadow tucked right under the thick dorsal cut & anterior end
  brush.fill("#746b64", 115);
  brush.beginShape(0.3);
  for (let s = 0; s <= 28; s++) {
    let u = s / 28;
    let p = getFilletPoint(u, 0, false, -6);
    brush.vertex(p[0] + 9, p[1] - 6);
  }
  for (let s = 28; s >= 0; s--) {
    let u = s / 28;
    let p = getFilletPoint(u, 0.25, false, 0);
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);

  // Warm coral subsurface light bouncing onto the damp tissue along the belly & anterior rim
  brush.fillBleed(0.32, "out");
  brush.fill("#d88d76", 62);
  brush.beginShape(0.35);
  for (let s = 0; s <= 28; s++) {
    let u = s / 28;
    let p = getFilletPoint(u, 0.85, false, 0);
    brush.vertex(p[0], p[1]);
  }
  for (let s = 28; s >= 0; s--) {
    let u = s / 28;
    let p = getFilletPoint(u, 1.0, false, -14);
    brush.vertex(p[0] - 5, p[1] + 7);
  }
  brush.endShape(true);
  brush.noFill();

  // Tight dark occlusion crease right where the wet flesh sits on the paper
  brush.set("2B", "#4c423e", 0.9);
  for (let s = 0; s < 36; s++) {
    let u0 = s / 36;
    let u1 = (s + 1) / 36;
    let p0 = getFilletPoint(u0, 0, false, -1.5);
    let p1 = getFilletPoint(u1, 0, false, -1.5);
    brush.line(p0[0] + 2, p0[1] - 1.5, p1[0] + 2, p1[1] - 1.5);
  }
}

// =========================================================================
// 7A. SALMON WATERCOLOUR BASE WASHES (CORAL, APRICOT, COOL ROSE-SALMON)
// =========================================================================
function renderSalmonWatercolourBase() {
  // 1. Opaque-ish wash base so the underlying black pattern lines inside the thick loin are mostly veiled,
  // while leaving the thin belly flap slightly more translucent
  let fullOutline = [];
  for (let i = 0; i <= 40; i++) fullOutline.push(getFilletPoint(i / 40, 0));
  for (let i = 1; i <= 14; i++) fullOutline.push(getFilletPoint(1, i / 14));
  for (let i = 39; i >= 0; i--) fullOutline.push(getFilletPoint(i / 40, 1));
  for (let i = 13; i >= 1; i--) fullOutline.push(getFilletPoint(0, i / 14));

  brush.noStroke();
  brush.wash("#f7b199", 185);
  drawShapeFromPts(fullOutline, 0.25);
  brush.noWash();

  // Ghostly hint of the black pattern cutting line & dart showing very faintly through the thin translucent belly flap!
  brush.set("2H", "#8f6f68", 0.65);
  for (let i = 8; i < 28; i += 2) {
    let u0 = i / 36;
    let u1 = (i + 0.6) / 36;
    let p0 = getFilletPoint(u0, 1, true, 26);
    let p1 = getFilletPoint(u1, 1, true, 26);
    brush.line(p0[0], p0[1], p1[0], p1[1]);
  }

  // 2. Layered luminous watercolour fills batched by colour for rich organic pigment bleed
  brush.fillBleed(0.26, "in");
  brush.fillTexture(0.68, 0.42);

  // Pass A: Warm Apricot-Coral body wash
  brush.fill("#f07c5e", 145);
  drawFilletBand(0.0, 1.0, 0.03, 0.84);

  // Pass B: Deep Luminous Coral-Red along the thick loin core (v = 0.08 .. 0.56)
  brush.fill("#de5742", 125);
  drawFilletBand(0.02, 0.96, 0.06, 0.56);

  // Pass C: Cool Rose-Salmon undertone (crucial for cool hyperreal raw fish translucency)
  brush.fill("#e06366", 95);
  drawFilletBand(0.05, 0.92, 0.14, 0.68);

  // Pass D: Rich Carmine-Orange pockets along the anterior thick cut & dorsal ridge
  brush.fill("#c94338", 105);
  drawFilletBand(0.0, 0.68, 0.02, 0.34);

  // Pass E: Pale Peach-Apricot & Silvery-Rose along the thin belly flap (v = 0.68 .. 1.0)
  brush.fill("#f9bfa7", 130);
  drawFilletBand(0.02, 0.98, 0.68, 0.98);

  brush.fill("#e4ccd0", 95);
  drawFilletBand(0.08, 0.95, 0.85, 1.0);

  brush.noFill();
}

function drawFilletBand(uStart, uEnd, vStart, vEnd) {
  let steps = 24;
  brush.beginShape(0.3);
  for (let i = 0; i <= steps; i++) {
    let u = lerp(uStart, uEnd, i / steps);
    let v = vStart + (noise(u * 4, vStart * 7) - 0.5) * 0.04;
    let p = getFilletPoint(u, constrain(v, 0, 1));
    brush.vertex(p[0], p[1]);
  }
  for (let i = steps; i >= 0; i--) {
    let u = lerp(uStart, uEnd, i / steps);
    let v = vEnd + (noise(u * 4 + 9, vEnd * 7) - 0.5) * 0.04;
    let p = getFilletPoint(u, constrain(v, 0, 1));
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);
}

// =========================================================================
// 7B. CUT MUSCLE GRAIN, MYOTOME FLAKES & COLOURED PENCIL MODELLING
// =========================================================================
function renderSalmonMuscleGrainAndFlakes() {
  // For each myotome block between septum i and septum i+1, render the cut muscle grain
  // and the 3D Pillow/Flake shading (deep coral shadow next to the anterior septum,
  // warm apricot midtone in the center, cool rose transition toward the posterior septum)
  const coralDark   = ["#ad332f", "#c23f37", "#cf4d3d"];
  const coralMid    = ["#df5c46", "#e86b52", "#ec765c", "#e26360"];
  const apricotTone = ["#f38b6d", "#f79d80", "#f9b095", "#eeb4a4"];
  const bellyTone   = ["#fad2be", "#e8cfd2", "#d8dfe4"];

  for (let idx = 0; idx < NUM_MYOTOMES; idx++) {
    let vSteps = 44;
    for (let vs = 0; vs < vSteps; vs++) {
      let v0 = vs / vSteps;
      let v1 = (vs + 1) / vSteps;
      let vm = (v0 + v1) * 0.5;

      let uStart = getMyocommaU(idx, vm);
      let uEnd   = getMyocommaU(idx + 1, vm);

      // Skip if outside the fillet bounds [0, 1]
      if (uEnd < 0.005 || uStart > 0.995) continue;
      let uA = constrain(uStart, 0.004, 0.996);
      let uB = constrain(uEnd, 0.004, 0.996);
      if (uB - uA < 0.003) continue;

      // 1. Sub-myotome muscle grain fibers running longitudinally between the two septa
      let pA = getFilletPoint(uA, vm);
      let pB = getFilletPoint(uB, vm + (noise(idx, vs * 0.2) - 0.5) * 0.015);
      let pMid = getFilletPoint(lerp(uA, uB, 0.5), vm + (noise(idx * 3, vs * 0.3) - 0.5) * 0.012);

      // Choose colour based on cross-fillet position v and local noise
      let col;
      let r = noise(idx * 0.6, vm * 4.0);
      if (vm > 0.82) {
        col = random(bellyTone);
      } else if (vm > 0.60) {
        col = r < 0.55 ? random(apricotTone) : random(coralMid);
      } else if (vm < 0.14) {
        col = r < 0.6 ? random(coralDark) : random(coralMid);
      } else {
        col = r < 0.32 ? random(coralDark) : (r < 0.75 ? random(coralMid) : random(apricotTone));
      }

      brush.set("flesh_fiber", col, random(0.75, 1.35));
      brush.spline([
        [pA[0], pA[1], 0.3],
        [pMid[0], pMid[1], 1.0],
        [pB[0], pB[1], 0.3]
      ], 0.3);

      // 2. Deep shadow tuck immediately alongside the septum edge (gives each muscle block 3D convex pillow relief)
      if (vm < 0.82 && random() < 0.78) {
        let uTuck = lerp(uA, uB, 0.22);
        let pTuck = getFilletPoint(uTuck, vm);
        let tuckCol = vm < 0.5 ? random(coralDark) : "#d9614e";
        brush.set("cpencil", tuckCol, random(0.45, 0.85));
        brush.line(pA[0], pA[1], pTuck[0], pTuck[1]);
      }

      // 3. Luminous apricot-pink convex crown in the middle of the muscle flake
      if (vm > 0.08 && vm < 0.78 && random() < 0.65) {
        let uCrown1 = lerp(uA, uB, 0.38);
        let uCrown2 = lerp(uA, uB, 0.82);
        let pC1 = getFilletPoint(uCrown1, vm);
        let pC2 = getFilletPoint(uCrown2, vm);
        brush.set("cpencil", random(apricotTone), random(0.5, 0.9));
        brush.line(pC1[0], pC1[1], pC2[0], pC2[1]);
      }
    }
  }

  // 4. Longitudinal Lateral Line (Horizontal Septum at v ≈ 0.36)
  // A distinct anatomical feature of salmon fillets: a fibrous rose-silver line bisecting the chevrons
  for (let pass = 0; pass < 3; pass++) {
    let vOff = (pass - 1) * 0.008;
    let pts = [];
    for (let s = 0; s <= 36; s++) {
      let u = lerp(0.01, 0.99, s / 36);
      let v = 0.36 + vOff + (noise(u * 8, pass * 5) - 0.5) * 0.014;
      let p = getFilletPoint(u, v);
      pts.push([p[0], p[1], random(0.4, 1.1)]);
    }
    if (pass === 0) brush.set("cpencil", "#bd4742", 0.65);
    if (pass === 1) brush.set("myocomma_fat", "#f2dcd5", 0.55);
    if (pass === 2) brush.set("cpencil", "#e39b8e", 0.5);
    brush.spline(pts, 0.35);
  }

  // 5. Realistic Flake Separations (Clefts where muscle blocks slightly gape open)
  const clefts = [
    { idx: 6,  vMin: 0.14, vMax: 0.33 },
    { idx: 10, vMin: 0.38, vMax: 0.62 },
    { idx: 14, vMin: 0.16, vMax: 0.35 },
    { idx: 17, vMin: 0.42, vMax: 0.68 },
    { idx: 20, vMin: 0.18, vMax: 0.36 }
  ];
  for (let cl of clefts) {
    let cleftPts = [];
    let steps = 12;
    for (let s = 0; s <= steps; s++) {
      let v = lerp(cl.vMin, cl.vMax, s / steps);
      let u = getMyocommaU(cl.idx, v) + 0.004 * sin((s / steps) * 180);
      let p = getFilletPoint(constrain(u, 0.01, 0.99), v);
      cleftPts.push([p[0], p[1], sin((s / steps) * 180) * 1.4]);
    }
    // Deep moist crimson-brown crevice interior
    brush.set("2B", "#7d1f22", 1.15);
    brush.spline(cleftPts, 0.35);
    brush.set("pen", "#5c1317", 0.65);
    brush.spline(cleftPts, 0.35);
  }
}

// =========================================================================
// 7C. 3D CUT FACE BEVEL, SILVER-BLUE SKIN EDGE & BELLY MEMBRANE
// =========================================================================
function renderSalmon3DCutBevelAndSkin() {
  // 1. Thick Dorsal Cut Bevel (v = 0 .. 0.09): shows vertical cut thickness of the loin slab
  for (let s = 0; s < 90; s++) {
    let u = s / 90;
    let pTop = getFilletPoint(u, 0.075);
    let pBot = getFilletPoint(u, 0.0);
    let col = random(["#b53a34", "#cf4b3c", "#df604c", "#9e2c2a"]);
    brush.set("cpencil", col, random(0.45, 0.85));
    brush.line(pTop[0], pTop[1], pBot[0], pBot[1]);
  }

  // Anterior Cut Face (u = 0 .. 0.025): vertical cross-cut muscle bundles at the head end
  for (let s = 0; s < 48; s++) {
    let v = s / 48;
    let pIn  = getFilletPoint(0.022 * (1 - 0.5 * v), v);
    let pOut = getFilletPoint(0.0, v);
    let col = v < 0.7 ? random(["#b83c36", "#d65242", "#e8735b"]) : random(["#f29b82", "#e5bfc0"]);
    brush.set("cpencil", col, random(0.5, 0.9));
    brush.line(pIn[0], pIn[1], pOut[0], pOut[1]);
  }

  // 2. Iridescent Silver-Blue Skin & Dark Grey Dermis peeking out at the Posterior Tail Tip
  // and along the outer Dorsal/Tail corner (u = 0.76 .. 1.0, v = 0 .. 0.15)
  for (let s = 0; s < 55; s++) {
    let u = lerp(0.75, 1.0, s / 55);
    let pEdge = getFilletPoint(u, 0.0);
    let pSkin = [pEdge[0] + 5 * (s / 55), pEdge[1] - 4 * (s / 55)];
    let col = random(["#3e4a56", "#586878", "#7d8f9e", "#a9bac7"]);
    brush.set("cpencil", col, random(0.55, 1.0));
    brush.line(pEdge[0], pEdge[1], pSkin[0], pSkin[1]);
  }

  // Tail end skin sliver (u = 1.0, v = 0.0 .. 0.55)
  for (let s = 0; s < 35; s++) {
    let v = lerp(0.0, 0.55, s / 35);
    let p1 = getFilletPoint(0.985, v);
    let p2 = getFilletPoint(1.0, v);
    let col = random(["#434f5b", "#6b7c8c", "#9cb0bf", "#dbe5ec", "#8a5a5c"]);
    brush.set("cpencil", col, random(0.5, 0.95));
    brush.line(p1[0], p1[1], p2[0] + 4, p2[1] + 2);
  }

  // 3. Silvery-White & Cool Ice-Blue Peritoneum Membrane along the thin Belly Rim (v = 0.88 .. 1.0)
  for (let s = 0; s < 85; s++) {
    let u = lerp(0.04, 0.96, s / 85);
    let vA = random(0.86, 0.93);
    let pA = getFilletPoint(u, vA);
    let pB = getFilletPoint(min(0.99, u + 0.025), 0.995);
    let col = random(["#f4e5de", "#e2e8ed", "#cdd7e0", "#f9f5f2", "#f5c2b0"]);
    brush.set("flesh_fiber", col, random(0.6, 1.1));
    brush.line(pA[0], pA[1], pB[0], pB[1]);
  }
}

// =========================================================================
// 7D. SILVERY-WHITE & CREAMY MYOCOMMATA (CONNECTIVE TISSUE MARBLING)
// =========================================================================
function renderSalmonMyocommataMarbling() {
  for (let idx = 0; idx <= NUM_MYOTOMES; idx++) {
    let vSamples = 38;
    let subPts = [];
    let mainPts = [];
    let crispPts = [];

    for (let s = 0; s <= vSamples; s++) {
      let v = s / vSamples;
      let u = getMyocommaU(idx, v);
      if (u < 0.003 || u > 0.997) continue;

      let p = getFilletPoint(u, v);
      let pSub = getFilletPoint(constrain(u + 0.0045, 0.003, 0.997), v);

      // Connective tissue thickness profile:
      // Crisp at dorsal edge, slightly wider at lateral line (v≈0.36), thickest & ribbon-like across the belly (v>0.55)
      let wProfile = 0.65;
      if (v < 0.36) {
        wProfile = lerp(0.75, 0.95, v / 0.36);
      } else {
        wProfile = lerp(0.95, 1.55, pow((v - 0.36) / 0.64, 0.8));
      }
      // Taper slightly toward the tail
      wProfile *= lerp(1.15, 0.68, idx / NUM_MYOTOMES);

      subPts.push([pSub[0], pSub[1], wProfile * 0.9]);
      mainPts.push([p[0], p[1], wProfile]);
      crispPts.push([p[0] - 0.6, p[1] - 0.6, wProfile * 0.75]);
    }

    if (mainPts.length < 3) continue;

    // Layer 1: Subsurface warm peach-cream glow (fat embedded slightly under translucent flesh)
    brush.set("myocomma_fat", "#f6d5c6", 1.15);
    brush.spline(subPts, 0.35);

    // Layer 2: Primary creamy ivory-white myocomma band
    brush.set("myocomma_fat", "#fbf2e8", 0.92);
    brush.spline(mainPts, 0.35);

    // Layer 3: Cool silvery-white surface connective tissue core
    brush.set("cpencil", "#f2f7fa", 0.85);
    brush.spline(crispPts, 0.35);

    // Layer 4: Delicate feathered collagen branches radiating off the septum into the muscle blocks
    for (let k = 2; k < mainPts.length - 2; k += 2) {
      if (random() < 0.55) {
        let pt = mainPts[k];
        let vApprox = k / vSamples;
        let uCurr = getMyocommaU(idx, vApprox);
        let uBranch = constrain(uCurr + random(-0.016, 0.018), 0.005, 0.995);
        let vBranch = constrain(vApprox + random(-0.025, 0.025), 0.01, 0.99);
        let pBr = getFilletPoint(uBranch, vBranch);
        brush.set("flesh_fiber", "#f9ece4", random(0.45, 0.8));
        brush.line(pt[0], pt[1], pBr[0], pBr[1]);
      }
    }

    // Layer 5: Vertical cut continuation of the white stripe down the 3D dorsal edge bevel!
    let uDorsal = getMyocommaU(idx, 0.0);
    if (uDorsal > 0.02 && uDorsal < 0.98) {
      let pD0 = getFilletPoint(uDorsal, 0.0);
      let pD1 = getFilletPoint(constrain(uDorsal - 0.008, 0.01, 0.99), 0.065);
      brush.set("myocomma_fat", "#f7ebe2", 0.85);
      brush.line(pD0[0], pD0[1], pD1[0], pD1[1]);
    }
  }
}

// =========================================================================
// 7E. WET SHEEN, SPECULAR GLINTS & MOISTURE HIGHLIGHTS
// =========================================================================
function renderSalmonWetSheenAndHighlights() {
  // Raw fish has a glossy liquid film that catches sharp broken studio highlights along the convex ridge
  // (around v = 0.16 .. 0.48) and along the raised lips of the myocommata and muscle flakes
  for (let idx = 1; idx < NUM_MYOTOMES; idx++) {
    // 1. Specular streaks along the myocommata ridges in the main highlight zone
    for (let s = 0; s < 5; s++) {
      let v0 = random(0.12, 0.58);
      let v1 = v0 + random(0.03, 0.075);
      let u0 = getMyocommaU(idx, v0);
      let u1 = getMyocommaU(idx, v1);
      if (u0 < 0.02 || u1 > 0.98) continue;

      let p0 = getFilletPoint(u0, v0);
      let pMid = getFilletPoint((u0 + u1) * 0.5 + 0.002, (v0 + v1) * 0.5);
      let p1 = getFilletPoint(u1, v1);

      // Soft cyan-white wet halo
      brush.set("cpencil", "#e6f3fa", random(0.8, 1.3));
      brush.spline([[p0[0], p0[1], 0.3], [pMid[0], pMid[1], 1.1], [p1[0], p1[1], 0.3]], 0.35);

      // Razor-sharp pure white liquid highlight core
      brush.set("wet_sheen", "#ffffff", random(0.55, 1.05));
      brush.spline([[p0[0], p0[1], 0.2], [pMid[0], pMid[1], 1.2], [p1[0], p1[1], 0.2]], 0.35);
    }

    // 2. Longitudinal wet sheen glints across the convex belly of each muscle flake
    let numGlints = 4;
    for (let g = 0; g < numGlints; g++) {
      let v = random(0.14, 0.52);
      let uA = getMyocommaU(idx - 1, v);
      let uB = getMyocommaU(idx, v);
      let uStart = lerp(uA, uB, random(0.25, 0.45));
      let uEnd   = lerp(uA, uB, random(0.65, 0.88));
      if (uStart < 0.02 || uEnd > 0.98) continue;

      let pS = getFilletPoint(uStart, v);
      let pE = getFilletPoint(uEnd, v + random(-0.008, 0.008));

      brush.set("wet_sheen", "#ffffff", random(0.45, 0.95));
      brush.line(pS[0], pS[1], pE[0], pE[1]);

      // Tiny pinpoint specular bead at the end of the wet streak
      if (random() < 0.6) {
        brush.set("pen", "#ffffff", random(0.7, 1.2));
        brush.circle(pE[0], pE[1], random(1.0, 2.2), 0.1);
      }
    }
  }

  // 3. Continuous broken specular ridge along the top-right dorsal bevel edge (catching overhead light)
  for (let s = 2; s < 52; s++) {
    if (random() < 0.72) {
      let u0 = s / 55;
      let u1 = (s + random(0.5, 1.1)) / 55;
      let v = random(0.055, 0.095);
      let p0 = getFilletPoint(u0, v);
      let p1 = getFilletPoint(u1, v);
      brush.set("wet_sheen", "#ffffff", random(0.55, 1.1));
      brush.line(p0[0], p0[1], p1[0], p1[1]);
    }
  }
}

// =========================================================================
// 8. FINAL CLINICAL INCIDENTS (DROPLETS, GRAPHITE TICKS, LOOSE FIBERS)
// =========================================================================
function renderFinalSurfaceIncidents() {
  // A few tiny translucent moisture/oil droplets resting on the pattern tissue near the fillet
  const droplets = [
    { u: 0.22, v: 0, off: -16, r: 4.5 },
    { u: 0.25, v: 0, off: -25, r: 2.8 },
    { u: 0.64, v: 0, off: -14, r: 3.8 },
    { u: 0.48, v: 1, off: -18, r: 5.2 },
    { u: 0.51, v: 1, off: -28, r: 2.5 },
    { u: 0.78, v: 1, off: -15, r: 3.4 }
  ];

  for (let d of droplets) {
    let p = getFilletPoint(d.u, d.v, false, d.off);
    // Tiny shadow crescent under droplet
    brush.set("2H", "#8f887d", 0.5);
    brush.arc(p[0] + 1, p[1] + 1, d.r, 15, 165);
    // Faint coral-tinted refraction inside droplet
    brush.noStroke();
    brush.fill("#e8b8a6", 85);
    brush.circle(p[0], p[1], d.r, 0.15);
    brush.noFill();
    // Sharp white specular dot on top-left of droplet
    brush.set("wet_sheen", "#ffffff", 0.7);
    brush.line(p[0] - d.r * 0.4, p[1] - d.r * 0.4, p[0] - d.r * 0.1, p[1] - d.r * 0.5);
  }

  // Crisp graphite contour accents along the salmon perimeter to marry watercolor and pencil realism
  brush.set("HB", "#7a3b36", 0.42);
  for (let s = 0; s < 45; s++) {
    if (random() < 0.65) {
      let u0 = s / 45;
      let u1 = (s + 0.8) / 45;
      let p0 = getFilletPoint(u0, 0);
      let p1 = getFilletPoint(u1, 0);
      brush.line(p0[0], p0[1], p1[0], p1[1]);
    }
    if (random() < 0.55) {
      let u0 = s / 45;
      let u1 = (s + 0.8) / 45;
      let p0 = getFilletPoint(u0, 1);
      let p1 = getFilletPoint(u1, 1);
      brush.set("2H", "#9e8884", 0.38);
      brush.line(p0[0], p0[1], p1[0], p1[1]);
    }
  }
}

