// ============================================================================
// CORE UTILITIES & FLAT ROMANESQUE MARKER HELPERS
// ============================================================================

function resetBrush() {
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.noField();
}

function tracePoly(pts, curvature = 0, closed = true) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closed);
}

function flatMarkerPoly(pts, washCol, hatchCol, hatchAngle = 45, curvature = 0, inkWeight = 1.15, hatchDist = 6) {
  resetBrush();
  brush.wash(washCol, 238);
  brush.hatchStyle("marker", hatchCol || washCol, 0.75);
  brush.hatch(hatchDist, hatchAngle, { rand: 0.015 });
  tracePoly(pts, curvature, true);

  resetBrush();
  brush.set("pen", PAL.ink, inkWeight);
  tracePoly(pts, curvature, true);
  brush.set("rotring", PAL.ink, inkWeight * 0.65);
  tracePoly(pts, curvature, true);
  resetBrush();
}

function flatMarkerRect(x, y, w, h, washCol, hatchCol, hatchAngle = 90, inkWeight = 1.15) {
  let pts = [
    [x, y],
    [x + w, y],
    [x + w, y + h],
    [x, y + h]
  ];
  flatMarkerPoly(pts, washCol, hatchCol, hatchAngle, 0, inkWeight, 6);
}

function flatMarkerCircle(cx, cy, r, washCol, hatchCol, inkWeight = 1.1) {
  let pts = [];
  let steps = 28;
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    pts.push([cx + cos(a) * r, cy + sin(a) * r]);
  }
  flatMarkerPoly(pts, washCol, hatchCol, 45, 0.25, inkWeight, 5);
}

function annularSectorPts(cx, cy, rIn, rOut, aStart, aEnd, steps = 18) {
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let a = lerp(aStart, aEnd, i / steps);
    pts.push([cx + cos(a) * rOut, cy + sin(a) * rOut]);
  }
  for (let i = steps; i >= 0; i--) {
    let a = lerp(aStart, aEnd, i / steps);
    pts.push([cx + cos(a) * rIn, cy + sin(a) * rIn]);
  }
  return pts;
}

function heavyInkLine(x1, y1, x2, y2, w = 1.15) {
  brush.set("pen", PAL.ink, w);
  brush.line(x1, y1, x2, y2);
  brush.set("rotring", PAL.ink, w * 0.6);
  brush.line(x1, y1, x2, y2);
}

function heavyInkSpline(pts, curv = 0.4, w = 1.1) {
  brush.set("pen", PAL.ink, w);
  brush.spline(pts, curv);
  brush.set("rotring", PAL.ink, w * 0.6);
  brush.spline(pts, curv);
}

// ============================================================================
// 1. PARCHMENT GROUND & SCRIBE RULING
// ============================================================================

function drawParchmentGround() {
  resetBrush();
  brush.fill(PAL.parchmentDark, 42);
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.45, 0.2);
  brush.rect(40, 40, 1120, 1120, "corner");

  // Corner vellum aging
  const corners = [
    [120, 120, 260],
    [1080, 120, 240],
    [120, 1080, 260],
    [1080, 1080, 250]
  ];
  for (let c of corners) {
    brush.fill(PAL.parchmentShadow, 32);
    brush.circle(c[0], c[1], c[2], 0.3);
  }
  resetBrush();

  // Faint medieval drypoint / lead-point scribe ruling lines extending into margins
  brush.set("2H", "#b8a88e", 0.35);
  const rulingsY = [75, 110, 470, 840, 945, 1090, 1125];
  for (let y of rulingsY) {
    brush.line(35, y, 1165, y);
  }
  const rulingsX = [75, 110, 330, 870, 1090, 1125];
  for (let x of rulingsX) {
    brush.line(x, 35, x, 1165);
  }
  resetBrush();
}

// ============================================================================
// 2. FLAT ROMANESQUE ARCHITECTURE (MARKER + HEAVY BLACK PEN)
// ============================================================================

function drawOuterFrame() {
  // Outer thick black border band (75..1125) and inner frame (110..1090)
  // Top border segments
  const topSegs = 6;
  const segW = (1090 - 110) / topSegs;
  for (let i = 0; i < topSegs; i++) {
    let x0 = 110 + i * segW;
    let isEven = i % 2 === 0;
    let col = isEven ? PAL.lapis : PAL.green;
    let hCol = isEven ? PAL.lapisLight : PAL.greenLight;
    flatMarkerRect(x0, 75, segW, 35, col, hCol, 0, 1.15);

    // Flat geometric step-Cross or lozenge inside each border bar
    let mx = x0 + segW / 2;
    let my = 92.5;
    flatMarkerPoly(
      [[mx - 28, my], [mx, my - 11], [mx + 28, my], [mx, my + 11]],
      PAL.vermilion, PAL.vermilionBright, 45, 0, 0.9, 4
    );
    flatMarkerCircle(mx, my, 4.5, PAL.parchment, PAL.goldBuff, 0.7);
  }

  // Bottom thin fillet below rinceau (1090..1125)
  for (let i = 0; i < topSegs; i++) {
    let x0 = 110 + i * segW;
    let isEven = i % 2 === 1;
    let col = isEven ? PAL.lapis : PAL.green;
    let hCol = isEven ? PAL.lapisLight : PAL.greenLight;
    flatMarkerRect(x0, 1090, segW, 35, col, hCol, 0, 1.15);
    let mx = x0 + segW / 2;
    let my = 1107.5;
    flatMarkerPoly(
      [[mx - 26, my], [mx, my - 10], [mx + 26, my], [mx, my + 10]],
      PAL.vermilion, PAL.vermilionBright, 45, 0, 0.9, 4
    );
  }

  // Left and Right vertical border bars (y = 110..1090)
  const sideSegs = 7;
  const segH = (1090 - 110) / sideSegs;
  for (let i = 0; i < sideSegs; i++) {
    let y0 = 110 + i * segH;
    let isEven = i % 2 === 0;
    let colL = isEven ? PAL.green : PAL.lapis;
    let hColL = isEven ? PAL.greenLight : PAL.lapisLight;
    let colR = isEven ? PAL.lapis : PAL.green;
    let hColR = isEven ? PAL.lapisLight : PAL.greenLight;

    flatMarkerRect(75, y0, 35, segH, colL, hColL, 90, 1.15);
    flatMarkerRect(1090, y0, 35, segH, colR, hColR, 90, 1.15);

    // Vertical flat lozenge accents
    let my = y0 + segH / 2;
    for (let sx of [92.5, 1107.5]) {
      flatMarkerPoly(
        [[sx, my - 30], [sx + 11, my], [sx, my + 30], [sx - 11, my]],
        PAL.vermilion, PAL.vermilionBright, 45, 0, 0.85, 4
      );
      flatMarkerCircle(sx, my, 4.5, PAL.parchment, PAL.goldBuff, 0.7);
    }
  }

  // Four Vermilion Corner Bosses (35x35 squares with inner quatrefoil)
  const bosses = [
    [75, 75],
    [1090, 75],
    [75, 1090],
    [1090, 1090]
  ];
  for (let b of bosses) {
    flatMarkerRect(b[0], b[1], 35, 35, PAL.vermilion, PAL.vermilionBright, 45, 1.25);
    flatMarkerCircle(b[0] + 17.5, b[1] + 17.5, 9, PAL.goldBuff, PAL.parchment, 0.85);
    flatMarkerCircle(b[0] + 17.5, b[1] + 17.5, 4, PAL.lapis, PAL.lapisDeep, 0.7);
  }

  // Heavy outer boundary ink line
  resetBrush();
  brush.set("pen", PAL.ink, 1.5);
  brush.rect(71, 71, 1058, 1058, "corner");
  resetBrush();
}

function drawSpandrelsAndUpperArcade() {
  // Spandrel background (inside x = 110..1090, y = 110..480)
  flatMarkerRect(110, 110, 980, 370, PAL.parchmentDark, PAL.parchment, 0, 1.1);

  // Flat Romanesque diapering / masonry lines in the upper spandrels
  for (let row = 0; row < 7; row++) {
    let y = 110 + row * 48;
    heavyInkLine(110, y, 1090, y, 0.75);
    let offset = (row % 2) * 55;
    for (let x = 110 + offset; x < 1090; x += 110) {
      heavyInkLine(x, y, x, min(480, y + 48), 0.75);
    }
  }

  // Two large flat Romanesque Roundels in the left & right spandrels
  const roundels = [
    [225, 225],
    [975, 225]
  ];
  for (let [rx, ry] of roundels) {
    flatMarkerCircle(rx, ry, 76, PAL.vermilion, PAL.vermilionBright, 1.25);
    flatMarkerCircle(rx, ry, 58, PAL.lapis, PAL.lapisLight, 1.1);
    flatMarkerCircle(rx, ry, 40, PAL.green, PAL.greenLight, 1.05);

    // 8-petal stylized flat Romanesque rosette inside roundel
    for (let i = 0; i < 8; i++) {
      let a = i * 45;
      let px = rx + cos(a) * 23;
      let py = ry + sin(a) * 23;
      flatMarkerCircle(px, py, 10, PAL.parchment, PAL.goldBuff, 0.85);
    }
    flatMarkerCircle(rx, ry, 14, PAL.vermilion, PAL.vermilionBright, 0.95);
    flatMarkerCircle(rx, ry, 5, PAL.goldBuff, PAL.parchment, 0.75);
  }

  // Small turret / blind-arcade windows below the roundels (x = 135..265 and 935..1065, y = 325..465)
  const arcades = [142, 948];
  for (let ax of arcades) {
    flatMarkerRect(ax, 330, 100, 135, PAL.lapis, PAL.lapisDeep, 90, 1.1);
    // Double arched windows inside
    for (let k = 0; k < 2; k++) {
      let wx = ax + 14 + k * 42;
      let wy = 365;
      flatMarkerRect(wx, wy, 30, 85, PAL.vermilion, PAL.vermilionBright, 90, 0.95);
      let archPts = [];
      for (let s = 0; s <= 12; s++) {
        let ang = 180 + (s / 12) * 180;
        archPts.push([wx + 15 + cos(ang) * 15, wy + sin(ang) * 15]);
      }
      flatMarkerPoly(archPts, PAL.green, PAL.greenLight, 45, 0.1, 0.95, 5);
    }
  }
}

function drawNicheAndTympanum() {
  const cx = 600;
  const cy = 475;
  const rNiche = 275;

  // Arch-topped niche polygon from y = 475 up around semicircle and down to y = 840
  let nichePts = [];
  for (let i = 0; i <= 36; i++) {
    let a = 180 + (i / 36) * 180;
    nichePts.push([cx + cos(a) * rNiche, cy + sin(a) * rNiche]);
  }
  nichePts.push([cx + rNiche, 840]);
  nichePts.push([cx - rNiche, 840]);

  // Flat saturated Lapis Blue field for the inner sanctuary
  flatMarkerPoly(nichePts, PAL.lapisDeep, PAL.lapis, 90, 0, 1.35, 5);

  // Flat medieval diaper lattice inside the Lapis field (clipped geometrically to the niche)
  const spacing = 46;
  brush.set("rotring", PAL.ink, 0.75);
  for (let c = -14; c <= 14; c++) {
    // Diagonal lines +45 and -45 clipped to niche interior
    let steps = 45;
    for (let dir of [1, -1]) {
      let seg = [];
      for (let s = 0; s <= steps; s++) {
        let y = 200 + (s / steps) * 510;
        let x = cx + c * spacing + dir * (y - 475);
        let inRect = x >= cx - rNiche + 6 && x <= cx + rNiche - 6 && y >= 475 && y <= 705;
        let inArch = y < 475 && dist(x, y, cx, cy) <= rNiche - 6;
        if (inRect || inArch) {
          seg.push([x, y]);
        } else if (seg.length > 1) {
          brush.line(seg[0][0], seg[0][1], seg[seg.length - 1][0], seg[seg.length - 1][1]);
          seg = [];
        } else {
          seg = [];
        }
      }
      if (seg.length > 1) {
        brush.line(seg[0][0], seg[0][1], seg[seg.length - 1][0], seg[seg.length - 1][1]);
      }
    }
  }

  // Tiny flat vermilion & gold diamonds at the diaper centers
  for (let y = 235; y <= 685; y += spacing) {
    let rowIdx = round((y - 235) / spacing);
    for (let x = cx - 250; x <= cx + 250; x += spacing) {
      let px = x + (rowIdx % 2 === 0 ? 0 : spacing / 2);
      let py = y;
      let inside = (py >= 475 && abs(px - cx) < rNiche - 18) || (py < 475 && dist(px, py, cx, cy) < rNiche - 18);
      if (inside) {
        flatMarkerPoly(
          [[px, py - 6], [px + 6, py], [px, py + 6], [px - 6, py]],
          PAL.vermilion, PAL.vermilionBright, 45, 0, 0.65, 4
        );
      }
    }
  }

  // Horizontal Transom / Tympanum Divider Band at y = 462..490
  flatMarkerRect(cx - rNiche, 462, rNiche * 2, 28, PAL.vermilion, PAL.vermilionBright, 0, 1.2);
  for (let x = cx - rNiche + 22; x < cx + rNiche - 10; x += 38) {
    flatMarkerCircle(x, 476, 6.5, PAL.goldBuff, PAL.parchment, 0.75);
  }

  // Lower Sanctuary Drape / Throne Cloth (y = 695..840, x = 325..875)
  // Orphrey band at top of cloth (y = 695..725) in flat Leaf-Green
  flatMarkerRect(cx - rNiche, 695, rNiche * 2, 30, PAL.green, PAL.greenLight, 0, 1.15);
  for (let x = cx - rNiche + 25; x < cx + rNiche - 15; x += 45) {
