  // Main Altar Cloth in blazing flat Vermilion (y = 725..840)
  flatMarkerRect(cx - rNiche, 725, rNiche * 2, 115, PAL.vermilion, PAL.vermilionBright, 90, 1.25);

  // Stylized flat medieval vertical drapery folds on the vermilion cloth
  for (let x = cx - rNiche + 35; x < cx + rNiche - 20; x += 55) {
