    heavyInkLine(x + 12, 738, x + 12, 825, 0.75);
    // Flat chevron fold hem at bottom
    heavyInkLine(x - 12, 830, x, 818, 0.9);
    heavyInkLine(x, 818, x + 12, 830, 0.9);
