}

function drawRomanesqueArchivolts() {
  const cx = 600;
  const cy = 475;

  // Archivolt 1 (Innermost ring: R = 275..320) — Flat Leaf-Green & Parchment Chevron Molding
  const r1In = 275;
  const r1Out = 320;
  const nChev = 24;
  for (let i = 0; i < nChev; i++) {
    let a0 = 180 + (i / nChev) * 180;
    let a1 = 180 + ((i + 1) / nChev) * 180;
    let aMid = (a0 + a1) / 2;

    // Outer wedge
    let ptsOut = [
      [cx + cos(a0) * r1Out, cy + sin(a0) * r1Out],
      [cx + cos(a1) * r1Out, cy + sin(a1) * r1Out],
      [cx + cos(aMid) * r1In, cy + sin(aMid) * r1In]
    ];
    flatMarkerPoly(ptsOut, PAL.green, PAL.greenLight, aMid, 0, 1.05, 5);

    // Inner complementary triangle
    let ptsIn = [
      [cx + cos(a0) * r1In, cy + sin(a0) * r1In],
      [cx + cos(aMid) * r1In, cy + sin(aMid) * r1In],
      [cx + cos(a0) * r1Out, cy + sin(a0) * r1Out]
    ];
    flatMarkerPoly(ptsIn, PAL.goldBuff, PAL.parchment, a0, 0, 0.95, 5);

    let ptsIn2 = [
      [cx + cos(aMid) * r1In, cy + sin(aMid) * r1In],
      [cx + cos(a1) * r1In, cy + sin(a1) * r1In],
      [cx + cos(a1) * r1Out, cy + sin(a1) * r1Out]
    ];
    flatMarkerPoly(ptsIn2, PAL.vermilion, PAL.vermilionBright, a1, 0, 0.95, 5);
  }

  // Archivolt 2 (Main Voussoir Ring: R = 320..388) — Alternating Lapis, Vermilion, Leaf-Green wedge stones
  const r2In = 320;
  const r2Out = 388;
  const nVoussoirs = 17;
  for (let i = 0; i < nVoussoirs; i++) {
    let a0 = 180 + (i / nVoussoirs) * 180;
    let a1 = 180 + ((i + 1) / nVoussoirs) * 180;
    let aMid = (a0 + a1) / 2;

    let col, hCol, motifCol;
    if (i % 3 === 0) {
      col = PAL.vermilion;
      hCol = PAL.vermilionBright;
      motifCol = PAL.goldBuff;
    } else if (i % 3 === 1) {
      col = PAL.lapis;
      hCol = PAL.lapisLight;
      motifCol = PAL.vermilion;
    } else {
      col = PAL.green;
      hCol = PAL.greenLight;
      motifCol = PAL.goldBuff;
    }

    let vPts = annularSectorPts(cx, cy, r2In, r2Out, a0, a1, 6);
    flatMarkerPoly(vPts, col, hCol, aMid + 90, 0, 1.2, 5);

    // Flat Romanesque medallion inside each voussoir
    let rMid = (r2In + r2Out) / 2;
    let mx = cx + cos(aMid) * rMid;
    let my = cy + sin(aMid) * rMid;
    flatMarkerCircle(mx, my, 13, motifCol, motifCol, 0.9);
    flatMarkerCircle(mx, my, 5, PAL.parchment, PAL.parchment, 0.75);
  }

  // Archivolt 3 (Outer Hood Molding: R = 388..424) — Billet & Pearl Molding
  const r3In = 388;
  const r3Out = 424;
  const nBillets = 30;
  for (let i = 0; i < nBillets; i++) {
    let a0 = 180 + (i / nBillets) * 180;
    let a1 = 180 + ((i + 1) / nBillets) * 180;
    let aMid = (a0 + a1) / 2;
    let isEven = i % 2 === 0;
    let col = isEven ? PAL.lapis : PAL.vermilion;
    let hCol = isEven ? PAL.lapisLight : PAL.vermilionBright;
    let bPts = annularSectorPts(cx, cy, r3In, r3Out, a0, a1, 4);
    flatMarkerPoly(bPts, col, hCol, aMid, 0, 1.1, 5);
  }

  // Heavy black ink concentric rings reinforcing the archivolts
  for (let r of [275, 320, 388, 424]) {
    brush.set("pen", PAL.ink, 1.45);
    brush.arc(cx, cy, r, 180, 360);
    brush.set("rotring", PAL.ink, 0.9);
    brush.arc(cx, cy, r, 180, 360);
  }
  resetBrush();
}

