  }

  // Main Rinceau Ground (y = 959..1076) in deep flat Lapis Blue
  flatMarkerRect(110, 959, 980, 117, PAL.lapisDeep, PAL.lapis, 0, 1.25);

  // 7 Scrolling Vine Medallions across x = 110..1090
  const nScrolls = 7;
  const spanW = 940 / nScrolls;
