    // Spiral stem coiling into center of medallion
    let spiralPts = [];
    for (let s = 0; s <= 24; s++) {
      let f = s / 24;
      let ang = dir * (f * 390 - 90);
      let rad = lerp(42, 10, f);
      spiralPts.push([scx + cos(ang) * rad, baseCy + sin(ang) * rad]);
