    // Leaf vein lines
    heavyInkLine(scx - 20, baseCy - dir * 18, scx + 14, baseCy - dir * 28, 0.75);

    // Inner curling Acanthus Leaf in Vermilion
    let leaf2 = [
      [scx - 18, baseCy + dir * 8],
      [scx - 6, baseCy + dir * 34],
      [scx + 24, baseCy + dir * 28],
      [scx + 22, baseCy + dir * 4],
      [scx + 2, baseCy - dir * 4]
    ];
    flatMarkerPoly(leaf2, PAL.vermilion, PAL.vermilionBright, -30, 0.3, 1.0, 4);
    heavyInkLine(scx - 8, baseCy + dir * 12, scx + 14, baseCy + dir * 18, 0.75);

    // Central Trefoil / Berry Cluster at spiral heart
    let bx = scx + 2;
    let by = baseCy - dir * 2;
    flatMarkerCircle(bx - 6, by - 4, 5.5, PAL.goldBuff, PAL.parchment, 0.8);
    flatMarkerCircle(bx + 6, by - 4, 5.5, PAL.goldBuff, PAL.parchment, 0.8);
    flatMarkerCircle(bx, by + 5, 5.5, PAL.vermilion, PAL.vermilionBright, 0.8);

    // Vine clasp collar between scrolls
    if (i < nScrolls - 1) {
      let jx = 130 + (i + 1) * spanW;
      let jy = baseCy;
      flatMarkerRect(jx - 6, jy - 11, 12, 22, PAL.vermilion, PAL.vermilionBright, 0, 0.95);
    }
  }
}

