function drawWalnutCastShadows() {
  // Light comes from upper-left (-0.55, -0.65).
  // The enthroned walnut casts a deep, three-dimensional shadow across the flat vermilion cloth,
  // over the black-ink architectural border at y = 840, and onto the green/lapis sill below!
  resetBrush();

  // Soft outer penumbra wash
  const shadowLayers = [
    { cx: 555, cy: 848, rx: 225, ry: 56, op: 55 },
    { cx: 540, cy: 842, rx: 185, ry: 44, op: 75 },
    { cx: 525, cy: 836, rx: 145, ry: 32, op: 95 },
    { cx: 790, cy: 838, rx: 165, ry: 52, op: 65 },
    { cx: 778, cy: 832, rx: 130, ry: 38, op: 90 },
    // Backdrop shadow thrown onto the flat vermilion altar cloth behind the shells
    { cx: 565, cy: 705, rx: 175, ry: 145, op: 68 },
    { cx: 810, cy: 765, rx: 140, ry: 95, op: 62 }
  ];

  for (let s of shadowLayers) {
    let pts = [];
    for (let i = 0; i < 32; i++) {
      let a = (i / 32) * 360;
      pts.push([s.cx + cos(a) * s.rx, s.cy + sin(a) * s.ry]);
    }
    brush.fill(PAL.wVoid, s.op);
    brush.fillBleed(0.28, "out");
    brush.fillTexture(0.5, 0.25);
    tracePoly(pts, 0.3, true);
  }
  resetBrush();

  // Dense coloured-pencil & graphite cross-hatching in the cast shadow zones
  // (physically crossing over the flat black pen lines of the sill!)
  const hatchZones = [
    { cx: 535, cy: 842, rx: 170, ry: 38, n: 120 },
    { cx: 780, cy: 832, rx: 145, ry: 40, n: 105 },
    { cx: 635, cy: 815, rx: 95, ry: 45, n: 75 }
  ];

  for (let hz of hatchZones) {
    for (let i = 0; i < hz.n; i++) {
      let a = random(360);
      let r = sqrt(random()) * 0.98;
      let px = hz.cx + cos(a) * hz.rx * r;
      let py = hz.cy + sin(a) * hz.ry * r;
      let len = map(r, 0, 1, 38, 14);
      let ang = random(-14, 14);
      let col = r < 0.55 ? PAL.wVoid : PAL.wEspresso;
      brush.set("cpencil", col, map(r, 0, 1, 0.85, 0.4));
      brush.line(
        px - cos(ang) * len * 0.5,
        py - sin(ang) * len * 0.5,
        px + cos(ang) * len * 0.5,
        py + sin(ang) * len * 0.5
      );
    }
  }
  resetBrush();
}

// Helper for right splayed shell geometry (tilted open on the right side of the sill)
function rightShellPt(u, v) {
  // u in [-1..1] across width, v in [-1..1] from apex to base
  const cx = 768;
  const cy = 724;
  const tilt = 32;
  let rx = 124 * sin(((v + 1) * 0.5) * 180);
  // Slight pointed apex at v = -1
  if (v < 0) rx *= map(v, -1, 0, 0.72, 1.0);
  let lx = u * rx;
  let ly = v * 146;
  let x = cx + lx * cos(tilt) - ly * sin(tilt);
  let y = cy + lx * sin(tilt) + ly * cos(tilt);
  return [x, y];
}

function drawRightSplayedShell() {
  // The right shell half lies splayed open, tilted +32 deg, showing:
  // 1) Its deeply furrowed lower-right outer shell belly
  // 2) Its concave, velvety inner chamber facing up-left
  // 3) Its central dark woody septum rib & torn papery membrane
  // 4) Its thick, jagged fractured woody rim

  // --- A. OUTER SHELL BELLY (visible on the lower-right side of the tilted bowl) ---
  let bellyPts = [];
  for (let i = 0; i <= 28; i++) {
    let v = map(i, 0, 28, -0.85, 0.98);
    let [x, y] = rightShellPt(1.0, v);
    bellyPts.push([x, y]);
  }
  for (let i = 28; i >= 0; i--) {
    let v = map(i, 0, 28, -0.85, 0.98);
    let [x, y] = rightShellPt(1.0, v);
    let bulge = sin(map(v, -0.85, 0.98, 0, 180)) * 58;
    bellyPts.push([x + bulge * 0.82, y + bulge * 0.58]);
  }

  resetBrush();
  brush.wash(PAL.wUmber, 245);
  tracePoly(bellyPts, 0.25, true);
  resetBrush();

  // Cross-contour coloured pencil sculpting & deep vermiculate shell ridges on the outer belly
  for (let r = 0; r < 14; r++) {
    let f = r / 13; // 0 = near rim, 1 = outer lower belly edge
    let ribPts = [];
    for (let s = 0; s <= 24; s++) {
      let v = map(s, 0, 24, -0.82, 0.95);
      let [x, y] = rightShellPt(1.0, v);
      let bulge = sin(map(v, -0.85, 0.98, 0, 180)) * 58 * f;
      let wrinkle = (noise(r * 0.7, s * 0.35) - 0.5) * 9;
      ribPts.push([x + bulge * 0.82 + wrinkle, y + bulge * 0.58 + wrinkle]);
    }
    // Tonal shift: mid-bronze near top, dark core umber in middle, warm reflected ochre at very bottom
    let col = PAL.wRoast;
    if (f < 0.25) col = PAL.wAmber;
    else if (f < 0.65) col = PAL.wUmber;
    else if (f < 0.85) col = PAL.wEspresso;
    else col = PAL.wOchre; // Reflected light from sill!

    brush.set("cpencil", col, 0.95);
    brush.spline(ribPts, 0.4);
  }

  // Deep vermiculate pits & stippling on outer right shell belly
  for (let i = 0; i < 240; i++) {
    let v = random(-0.75, 0.9);
    let f = random(0.08, 0.92);
    let [x, y] = rightShellPt(1.0, v);
    let bulge = sin(map(v, -0.85, 0.98, 0, 180)) * 58 * f;
    let px = x + bulge * 0.82 + random(-4, 4);
    let py = y + bulge * 0.58 + random(-4, 4);

    let nVal = noise(px * 0.04, py * 0.04);
    if (nVal < 0.48) {
      brush.set("rotring", PAL.wVoid, 0.55);
      brush.line(px, py, px + random(-2.5, 2.5), py + random(-2.5, 2.5));
    } else if (nVal > 0.62 && f < 0.45) {
      brush.set("cpencil", PAL.wTan, 0.55);
      brush.line(px, py, px + 3, py + 2);
    }
  }

  // --- B. CONCAVE INTERIOR CHAMBER ---
  let outerRimPts = [];
  let innerRimPts = [];
  const rimSteps = 44;
  for (let i = 0; i < rimSteps; i++) {
    let a = (i / rimSteps) * 360;
    let u = cos(a);
    let v = sin(a);
    let [ox, oy] = rightShellPt(u, v);
    let jag = (noise(cos(a) * 2.2 + 5, sin(a) * 2.2 + 5) - 0.5) * 9;
    outerRimPts.push([ox + jag, oy + jag]);

    let [ix, iy] = rightShellPt(u * 0.82, v * 0.85);
    innerRimPts.push([ix + jag * 0.6, iy + jag * 0.6]);
  }

  // Base wash for woody rim and concave bowl
  resetBrush();
  brush.wash(PAL.wTan, 245);
  tracePoly(outerRimPts, 0.25, true);
  brush.wash(PAL.wRoast, 240);
  tracePoly(innerRimPts, 0.25, true);
  resetBrush();

  // Concave bowl shading: in a concave bowl lit from top-left, the upper-left inner wall
  // is in deep shadow, while the lower-right inner wall catches warm light!
  for (let ring = 0; ring < 26; ring++) {
    let radFrac = map(ring, 0, 25, 0.06, 0.82);
    for (let seg = 0; seg < 28; seg++) {
      let a0 = (seg / 28) * 360;
      let a1 = ((seg + 1) / 28) * 360;
      let aMid = (a0 + a1) / 2;

      let u0 = cos(a0) * radFrac;
      let v0 = sin(a0) * radFrac;
      let u1 = cos(a1) * radFrac;
      let v1 = sin(a1) * radFrac;

      let p0 = rightShellPt(u0, v0);
      let p1 = rightShellPt(u1, v1);

      // Concave illumination: bright when u > 0, v > 0 (bottom-right wall facing top-left light)
      let illum = (cos(aMid - 35) * radFrac + 1.0) * 0.5;
      let col;
      if (illum < 0.28) col = PAL.wEspresso;
      else if (illum < 0.45) col = PAL.wUmber;
      else if (illum < 0.62) col = PAL.wBronze;
      else if (illum < 0.78) col = PAL.wOchre;
      else if (illum < 0.9) col = PAL.wTan;
      else col = PAL.wBone;

      brush.set("cpencil", col, 0.75);
      brush.line(p0[0], p0[1], p1[0], p1[1]);
    }
  }

  // Fine stippling inside the concave chamber
  for (let i = 0; i < 320; i++) {
    let a = random(360);
    let r = sqrt(random()) * 0.8;
    let [px, py] = rightShellPt(cos(a) * r, sin(a) * r);
    let illum = (cos(a - 35) * r + 1.0) * 0.5;
    if (illum < 0.55 || random() < 0.35) {
      let col = illum < 0.35 ? PAL.wVoid : PAL.wUmber;
      brush.set("rotring", col, 0.42);
      brush.line(px, py, px + random(-1.5, 1.5), py + random(-1.5, 1.5));
    } else {
      brush.set("cpencil", PAL.wIvory, 0.45);
      brush.line(px, py, px + 2, py + 1);
    }
  }

  // --- C. CENTRAL VASCULAR RIB & TORN PAPERY MEMBRANE IN RIGHT SHELL ---
  let ribSpine = [];
  for (let i = 0; i <= 18; i++) {
    let v = map(i, 0, 18, -0.84, 0.84);
    let [x, y] = rightShellPt(sin(v * 120) * 0.04, v);
    ribSpine.push([x, y]);
  }
  brush.set("cpencil", PAL.wVoid, 1.5);
  brush.spline(ribSpine, 0.4);
  brush.set("cpencil", PAL.wUmber, 0.9);
  brush.spline(ribSpine, 0.4);

  // Torn papery septum wing protruding from center of right shell
  let septumWing = [
    rightShellPt(0.0, -0.42),
    rightShellPt(-0.26, -0.18),
    rightShellPt(-0.34, 0.08),
    rightShellPt(-0.18, 0.32),
    rightShellPt(0.04, 0.45),
    rightShellPt(0.14, 0.12),
    rightShellPt(0.08, -0.22)
  ];
  resetBrush();
  brush.wash(PAL.wBone, 230);
  tracePoly(septumWing, 0.25, true);
  resetBrush();

  // Delicate parallel papery venation lines on the septum fragment
  for (let i = 0; i < 18; i++) {
    let v = map(i, 0, 17, -0.35, 0.38);
    let pA = rightShellPt(0.02, v);
    let pB = rightShellPt(-0.24 * sin(map(i, 0, 17, 15, 165)), v - 0.06);
    brush.set("2H", i % 2 === 0 ? PAL.wIvory : PAL.wOchre, 0.45);
    brush.line(pA[0], pA[1], pB[0], pB[1]);
  }
  brush.set("rotring", PAL.wUmber, 0.45);
  tracePoly(septumWing, 0.25, true);

  // --- D. THICK FRACTURED WOODY RIM OF RIGHT SHELL ---
  for (let i = 0; i < rimSteps; i++) {
    let iNext = (i + 1) % rimSteps;
    let o0 = outerRimPts[i];
    let o1 = outerRimPts[iNext];
    let in0 = innerRimPts[i];
    let in1 = innerRimPts[iNext];

    // Radial woody cleavage striae across the fractured shell thickness
    for (let k = 0; k < 4; k++) {
      let f = k / 4;
      let sx = lerp(o0[0], o1[0], f);
      let sy = lerp(o0[1], o1[1], f);
      let ex = lerp(in0[0], in1[0], f);
      let ey = lerp(in0[1], in1[1], f);

      let a = (i / rimSteps) * 360;
      let rimLight = cos(a - 215); // Brightest on top-left-facing rim facets
      let col = rimLight > 0.2 ? PAL.wIvory : rimLight > -0.3 ? PAL.wBone : PAL.wOchre;
      brush.set("cpencil", col, 0.65);
      brush.line(sx, sy, ex, ey);
    }

    // Crisp dark fracture edge & vascular pores along the woody rim
    brush.set("rotring", PAL.wEspresso, 0.55);
    brush.line(o0[0], o0[1], o1[0], o1[1]);
    brush.set("rotring", PAL.wUmber, 0.45);
    brush.line(in0[0], in0[1], in1[0], in1[1]);

    // Specular highlight along upper-facing fractured rim bevel
    if (i > 16 && i < 36) {
      brush.set("cpencil", PAL.wSpecular, 0.6);
      brush.line(
        lerp(o0[0], in0[0], 0.3),
        lerp(o0[1], in0[1], 0.3),
        lerp(o1[0], in1[0], 0.3),
        lerp(o1[1], in1[1], 0.3)
      );
    }
  }
  resetBrush();
}

// Helper for Left Enthroned Shell Half & Brain Kernel coordinate frame
function leftShellPt(u, v) {
  // Centered at (512, 635), tilted -10 deg
  const cx = 512;
  const cy = 635;
  const tilt = -10;
  let rx = 152 * sin(((v + 1) * 0.5) * 180);
  if (v < 0) rx *= map(v, -1, 0, 0.68, 1.0); // Pointed apical crown
  else rx *= map(v, 0, 1, 1.0, 0.92); // Broad rounded base
  let lx = u * rx;
  let ly = v * 205;
  let x = cx + lx * cos(tilt) - ly * sin(tilt);
  let y = cy + lx * sin(tilt) + ly * cos(tilt);
  return [x, y];
}

function drawLeftEnthronedShellAndKernel() {
  // 1. OUTER LEFT SHELL CRESCENT (visible on the left side of the upright shell cradle)
  let leftBellyPts = [];
  for (let i = 0; i <= 32; i++) {
    let v = map(i, 0, 32, -0.94, 0.96);
    leftBellyPts.push(leftShellPt(-1.0, v));
  }
  for (let i = 32; i >= 0; i--) {
    let v = map(i, 0, 32, -0.94, 0.96);
    let [x, y] = leftShellPt(-1.0, v);
    let bulge = sin(map(v, -0.94, 0.96, 0, 180)) * 46;
    leftBellyPts.push([x - bulge * 0.92, y + bulge * 0.25]);
  }

  resetBrush();
  brush.wash(PAL.wUmber, 245);
  tracePoly(leftBellyPts, 0.25, true);
  resetBrush();

  // Sculpted longitudinal ribs and deep pits on the outer left shell crescent
  for (let r = 0; r < 12; r++) {
    let f = r / 11;
    let ribPts = [];
    for (let s = 0; s <= 26; s++) {
      let v = map(s, 0, 26, -0.9, 0.92);
      let [x, y] = leftShellPt(-1.0, v);
      let bulge = sin(map(v, -0.94, 0.96, 0, 180)) * 46 * f;
      let w = (noise(r * 0.8 + 10, s * 0.3) - 0.5) * 8;
      ribPts.push([x - bulge * 0.92 + w, y + bulge * 0.25 + w]);
    }
    // Directly lit by top-left light on outer edge, curving into mid-tone near fracture
    let col = f > 0.65 ? PAL.wBone : f > 0.35 ? PAL.wOchre : PAL.wBronze;
    brush.set("cpencil", col, 0.9);
    brush.spline(ribPts, 0.4);
  }

  for (let i = 0; i < 200; i++) {
    let v = random(-0.85, 0.88);
    let f = random(0.1, 0.9);
    let [x, y] = leftShellPt(-1.0, v);
    let bulge = sin(map(v, -0.94, 0.96, 0, 180)) * 46 * f;
    let px = x - bulge * 0.92 + random(-3, 3);
    let py = y + bulge * 0.25 + random(-3, 3);
    if (noise(px * 0.045, py * 0.045) < 0.48) {
      brush.set("rotring", PAL.wEspresso, 0.5);
      brush.line(px, py, px + random(-2, 2), py + random(-2, 2));
    }
  }

  // 2. FRACTURED WOODY SHELL RIM & DARK INNER CAVITY SURROUNDING THE KERNEL
  let outerRim = [];
  let innerRim = [];
  const steps = 52;
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    let u = cos(a);
    let v = sin(a);
    let [ox, oy] = leftShellPt(u, v);
    let jag = (noise(u * 2.5 + 20, v * 2.5 + 20) - 0.5) * 11;
    outerRim.push([ox + jag, oy + jag]);

    let [ix, iy] = leftShellPt(u * 0.84, v * 0.87);
    innerRim.push([ix + jag * 0.6, iy + jag * 0.6]);
  }

  // Base washes for rim and dark shadow pocket behind the kernel
  resetBrush();
  brush.wash(PAL.wTan, 248);
  tracePoly(outerRim, 0.2, true);
  brush.wash(PAL.wVoid, 248);
  tracePoly(innerRim, 0.25, true);
  resetBrush();

  // Render the woody fractured shell wall with radial cleavage lines and stepped facets
  for (let i = 0; i < steps; i++) {
    let iNext = (i + 1) % steps;
    let o0 = outerRim[i];
    let o1 = outerRim[iNext];
    let in0 = innerRim[i];
    let in1 = innerRim[iNext];
    let a = (i / steps) * 360;

    for (let k = 0; k < 4; k++) {
      let f = k / 4;
      let sx = lerp(o0[0], o1[0], f);
      let sy = lerp(o0[1], o1[1], f);
      let ex = lerp(in0[0], in1[0], f);
      let ey = lerp(in0[1], in1[1], f);

      let lightVal = cos(a - 210);
      let col = lightVal > 0.25 ? PAL.wIvory : lightVal > -0.25 ? PAL.wBone : PAL.wOchre;
      brush.set("cpencil", col, 0.72);
      brush.line(sx, sy, ex, ey);
    }

    // Stepped woody fracture lines & outer/inner crisp edges
    brush.set("rotring", PAL.wEspresso, 0.6);
    brush.line(o0[0], o0[1], o1[0], o1[1]);
    brush.set("rotring", PAL.wVoid, 0.65);
    brush.line(in0[0], in0[1], in1[0], in1[1]);

    // Bright bone-ivory highlight along top-left fractured bevel
    if (a > 140 && a < 295) {
      brush.set("cpencil", PAL.wSpecular, 0.65);
      brush.line(
        lerp(o0[0], in0[0], 0.35),
        lerp(o0[1], in0[1], 0.35),
        lerp(o1[0], in1[0], 0.35),
        lerp(o1[1], in1[1], 0.35)
      );
    }
  }

  // Dark vascular bundle pores at the apex (v = -0.93) and base (v = 0.93) of the shell wall
  for (let vPole of [-0.93, 0.93]) {
    let [px, py] = leftShellPt(0, vPole);
    for (let k = 0; k < 28; k++) {
      let ang = random(360);
      let r = random(2, 14);
      brush.set("rotring", PAL.wVoid, 0.6);
      brush.line(px + cos(ang) * r, py + sin(ang) * r, px + cos(ang) * (r + 3), py + sin(ang) * (r + 3));
    }
  }

  // Deep shadow cross-hatching inside the shell pocket around the kernel
  for (let i = 0; i < 180; i++) {
    let a = random(360);
    let r = random(0.72, 0.85);
    let [px, py] = leftShellPt(cos(a) * r, sin(a) * r);
    brush.set("2B", PAL.wVoid, 0.65);
    brush.line(px - 6, py - 4, px + 6, py + 4);
  }

  // 3. THE BRAIN-LIKE KERNEL (Cerebral Hemispheres, Gyri, Sulci, Stippling & Oily Sheen)
  drawBrainKernel();
}

