function sampleSpine(spineArr, t) {
  let n = spineArr.length - 1;
  let idx = constrain(floor(t * n), 0, n - 1);
  let frac = t * n - idx;
  return lerp(spineArr[idx], spineArr[idx + 1], frac);
}

function renderSingleGyrus(g) {
  const nAlong = 26;
  let spineScreen = [];
  let radScreen = [];

  for (let i = 0; i <= nAlong; i++) {
    let t = i / nAlong;
    let u = sampleSpine(g.uSpine, t);
    let v = sampleSpine(g.vSpine, t);
    let r = sampleSpine(g.rSpine, t) * sin(constrain(t * 180, 12, 168));
    spineScreen.push(leftShellPt(u, v));
    radScreen.push(r);
  }

  // Compute tangents & normals along the gyrus spine
  let normals = [];
  for (let i = 0; i <= nAlong; i++) {
    let pPrev = spineScreen[max(0, i - 1)];
    let pNext = spineScreen[min(nAlong, i + 1)];
    let dx = pNext[0] - pPrev[0];
    let dy = pNext[1] - pPrev[1];
    let len = max(0.001, sqrt(dx * dx + dy * dy));
    normals.push([-dy / len, dx / len]);
  }

  // Build gyrus outline polygon for dark sulcus undercut + warm amber base wash
  let polyPts = [];
  for (let i = 0; i <= nAlong; i++) {
    let p = spineScreen[i];
    let n = normals[i];
    let r = radScreen[i];
    polyPts.push([p[0] + n[0] * r, p[1] + n[1] * r]);
  }
  for (let i = nAlong; i >= 0; i--) {
    let p = spineScreen[i];
    let n = normals[i];
    let r = radScreen[i];
    polyPts.push([p[0] - n[0] * r, p[1] - n[1] * r]);
  }

  // Sulcus shadow outline around the lobe
  resetBrush();
  brush.wash(PAL.wBronze, 235);
  tracePoly(polyPts, 0.35, true);
  brush.set("2B", PAL.wVoid, 1.15);
  tracePoly(polyPts, 0.35, true);
  resetBrush();

  // Light direction from upper-left (-0.58, -0.62, 0.52)
  const lx = -0.58;
  const ly = -0.62;
  const lz = 0.52;

  // Longitudinal & Cross-contour coloured pencil sculpting across the 3D cylinder of the gyrus
  const nStrips = 11;
  for (let s = 0; s < nStrips; s++) {
    let w = map(s, 0, nStrips - 1, -0.92, 0.92); // Across width of gyrus
    let nz = sqrt(max(0.05, 1.0 - w * w));

    let stripPts = [];
    let avgLight = 0;
    for (let i = 0; i <= nAlong; i++) {
      let p = spineScreen[i];
      let n = normals[i];
      let r = radScreen[i];
      let px = p[0] + n[0] * r * w;
      let py = p[1] + n[1] * r * w;
      stripPts.push([px, py]);

      let nx = n[0] * w;
      let ny = n[1] * w;
      avgLight += nx * lx + ny * ly + nz * lz;
    }
    avgLight /= nAlong + 1;

    let col;
    if (avgLight < 0.05) col = PAL.wEspresso;
    else if (avgLight < 0.22) col = PAL.wUmber;
    else if (avgLight < 0.38) col = PAL.wRoast;
    else if (avgLight < 0.54) col = PAL.wBronze;
    else if (avgLight < 0.68) col = PAL.wAmber;
    else if (avgLight < 0.80) col = PAL.wOchre;
    else if (avgLight < 0.90) col = PAL.wTan;
    else col = PAL.wBone;

    brush.set("cpencil", col, 0.82);
    brush.spline(stripPts, 0.4);
  }

  // Cross-contour curved pencil rings wrapping over the gyrus crest
  for (let i = 2; i < nAlong - 1; i += 2) {
    let p = spineScreen[i];
    let n = normals[i];
    let r = radScreen[i];
    let tNext = spineScreen[min(nAlong, i + 1)];
    let tx = tNext[0] - p[0];
    let ty = tNext[1] - p[1];
    let tLen = max(0.001, sqrt(tx * tx + ty * ty));
    tx /= tLen;
    ty /= tLen;

    let ringPts = [];
    for (let k = -3; k <= 3; k++) {
      let wf = k / 3;
      let arch = sqrt(max(0, 1 - wf * wf)) * r * 0.35;
      ringPts.push([
        p[0] + n[0] * r * wf - tx * arch,
        p[1] + n[1] * r * wf - ty * arch
      ]);
    }
    let crestLight = n[0] * (-0.3) * lx + n[1] * (-0.3) * ly + 0.85 * lz;
    let cCol = crestLight > 0.5 ? PAL.wTan : PAL.wAmber;
    brush.set("cpencil", cCol, 0.55);
    brush.spline(ringPts, 0.45);
  }

  // Fine branching vascular veins on the golden pellicle skin of the gyrus
  for (let i = 4; i < nAlong - 3; i += 5) {
    let p = spineScreen[i];
    let n = normals[i];
    let r = radScreen[i];
    let vPts = [
      [p[0] - n[0] * r * 0.65, p[1] - n[1] * r * 0.65],
      [p[0] + random(-3, 3), p[1] + random(-3, 3)],
      [p[0] + n[0] * r * 0.6, p[1] + n[1] * r * 0.6]
    ];
    brush.set("rotring", PAL.wRoast, 0.32);
    brush.spline(vPts, 0.4);
  }

  // Fine pen stippling in the sulcus shadow edges and pellicle pores
  for (let i = 0; i < 65; i++) {
    let idx = floor(random(1, nAlong));
    let p = spineScreen[idx];
    let n = normals[idx];
    let r = radScreen[idx];
    // Bias stippling toward the edges (sulci)
    let w = (random() < 0.5 ? -1 : 1) * random(0.45, 1.02);
    let px = p[0] + n[0] * r * w + random(-2, 2);
    let py = p[1] + n[1] * r * w + random(-2, 2);
    let sCol = abs(w) > 0.82 ? PAL.wVoid : PAL.wUmber;
    brush.set("rotring", sCol, 0.42);
    brush.line(px, py, px + random(-1.4, 1.4), py + random(-1.4, 1.4));
  }

  // OILY KERNEL SHEEN: Glistening ivory & pure white specular ridge along the top-left-lit crest!
  let sheenPts = [];
  for (let i = 3; i <= nAlong - 3; i++) {
    let p = spineScreen[i];
    let n = normals[i];
    let r = radScreen[i];
    // Shift slightly toward light source (-0.28 along normal if facing light)
    let dotN = n[0] * lx + n[1] * ly;
    let wShift = constrain(dotN * 0.42, -0.45, 0.45);
    sheenPts.push([p[0] + n[0] * r * wShift, p[1] + n[1] * r * wShift]);
  }
  brush.set("cpencil", PAL.wIvory, 0.85);
  brush.spline(sheenPts, 0.4);

  // Pinpoint wet oil glints along the crest
  for (let i = 4; i <= nAlong - 4; i += 2) {
    let sp = sheenPts[i - 3];
    if (sp && random() < 0.78) {
      brush.set("cpencil", PAL.wSpecular, 0.75);
      brush.line(sp[0] - 2.5, sp[1] - 1.5, sp[0] + 2.5, sp[1] + 1.5);
      brush.set("2H", PAL.wSpecular, 0.55);
      brush.line(sp[0], sp[1] - 2, sp[0], sp[1] + 2);
    }
  }

  // Optional chipped pellicle spot exposing pure waxy ivory nutmeat
  if (g.chipped) {
    let cp = spineScreen[floor(nAlong * 0.5)];
    let chipPts = [];
    for (let k = 0; k < 10; k++) {
      let a = (k / 10) * 360;
      let rad = 13 + (noise(k * 0.9) - 0.5) * 6;
      chipPts.push([cp[0] + cos(a) * rad, cp[1] + sin(a) * rad * 0.75]);
    }
    resetBrush();
    brush.wash(PAL.wIvory, 248);
    tracePoly(chipPts, 0.2, true);
    brush.set("cpencil", PAL.wSpecular, 0.7);
    brush.line(cp[0] - 6, cp[1] - 3, cp[0] + 5, cp[1] - 1);
    brush.set("rotring", PAL.wRoast, 0.48);
    tracePoly(chipPts, 0.2, true);
    resetBrush();
  }
}

