// ============================================================================
// GEOMETRY & DRAWING HELPERS
// ============================================================================

function safeSpline(pts, curv, brushName, col, weight) {
  if (!pts || pts.length < 2) return;
  let cleaned = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    let prev = cleaned[cleaned.length - 1];
    let dx = pts[i][0] - prev[0];
    let dy = pts[i][1] - prev[1];
    if (dx * dx + dy * dy > 2.25) {
      cleaned.push(pts[i]);
    }
  }
  if (cleaned.length < 2) return;
  brush.set(brushName, col, weight);
  if (cleaned.length === 2) {
    brush.line(cleaned[0][0], cleaned[0][1], cleaned[1][0], cleaned[1][1]);
  } else {
    brush.spline(cleaned, curv);
  }
}

function safeLine(x1, y1, x2, y2, brushName, col, weight) {
  if ((x2 - x1) * (x2 - x1) + (y2 - y1) * (y2 - y1) < 0.5) return;
  brush.set(brushName, col, weight);
  brush.line(x1, y1, x2, y2);
}

function drawWashPoly(pts, col, opacity) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noFill();
  brush.wash(col, opacity);
  brush.beginShape(0);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noWash();
}

function drawWatercolorPoly(pts, col, opacity, bleed = 0.2, tex = 0.5) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noWash();
  brush.fill(col, opacity);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, 0.35);
  brush.beginShape(0.15);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noFill();
}

// Compute 2D projected point and outward screen normal on a 3D tilted torus bangle
function getBanglePoint(b, theta, sOffset = 0) {
  let cT = cos(theta);
  let sT = sin(theta);
  let ux = b.R * cT;
  let uy = b.R * sT * b.cosP;
  let z = b.cz + b.R * sT * b.sinP;

  // Outward normal to ellipse in local frame
  let nx = cT * b.cosP;
  let ny = sT;
  let nLen = sqrt(nx * nx + ny * ny) || 1;
  nx /= nLen;
  ny /= nLen;

  let lx = ux + nx * (sOffset * b.r);
  let ly = uy + ny * (sOffset * b.r);

  // Rotate by yaw into canvas space
  let wx = b.cx + lx * b.cosY - ly * b.sinY;
  let wy = b.cy + lx * b.sinY + ly * b.cosY;

  // World normal
  let wnx = nx * b.cosY - ny * b.sinY;
  let wny = nx * b.sinY + ny * b.cosY;

  return { x: wx, y: wy, z: z, nx: wnx, ny: wny };
}

// ============================================================================
// 1. MIRRORED CHAMAK-PATTI REFLECTIVE TAPE PANEL
// ============================================================================

function drawChamakPattiPanel() {
  const margin = 76;
  const tileW = 68;
  const tileH = 68;

  // Metallic & prismatic chamak-patti colors
  const tapeColors = [
    "#d8e8f8", // Chrome mirror silver
    "#00e5ff", // Prismatic cyan
    "#ff0077", // Reflective rani magenta
    "#ffcc00", // Gold prism tape
    "#00dc64", // Reflective emerald
    "#182442", // Deep mirror slate shadow
    "#ffffff"  // Pure specular mirror flash
  ];

  // Batch diamond tiles by color for fast wash rendering
  let colorBatches = tapeColors.map(() => []);

  for (let gx = margin - tileW; gx < width - margin + tileW; gx += tileW) {
    for (let gy = margin - tileH; gy < height - margin + tileH; gy += tileH) {
      let cx = gx + tileW * 0.5;
      let cy = gy + tileH * 0.5;

      // 4 interlocking chevron/diamond facets per cell
      let ptsTop = [[cx, gy], [gx + tileW, cy], [cx, cy], [gx, cy]];
      let ptsBot = [[cx, cy], [gx + tileW, cy], [cx, gy + tileH], [gx, cy]];

      let idx1 = floor((gx * 0.03 + gy * 0.05 + random(2)) % tapeColors.length);
      let idx2 = (idx1 + floor(random(1, 4))) % tapeColors.length;

      colorBatches[idx1].push({ pts: ptsTop, cx, cy: gy + tileH * 0.25 });
      colorBatches[idx2].push({ pts: ptsBot, cx, cy: gy + tileH * 0.75 });
    }
  }

  // Render reflective tape facet washes
  for (let c = 0; c < tapeColors.length; c++) {
    let col = tapeColors[c];
    for (let item of colorBatches[c]) {
      drawWashPoly(item.pts, col, 215);
    }
  }

  // Add prismatic honeycomb micro-grid and diagonal mirror streaks on the tape
  for (let gx = margin; gx < width - margin; gx += tileW) {
    for (let gy = margin; gy < height - margin; gy += tileH) {
      let cx = gx + tileW * 0.5;
      let cy = gy + tileH * 0.5;

      // Crisp diamond facet borders
      safeLine(cx, gy, gx + tileW, cy, "rotring", "#060814", 0.55);
      safeLine(gx + tileW, cy, cx, gy + tileH, "rotring", "#060814", 0.55);
      safeLine(cx, gy + tileH, gx, cy, "rotring", "#060814", 0.55);
      safeLine(gx, cy, cx, gy, "rotring", "#060814", 0.55);

      // Internal retro-reflective honeycomb hatching
      for (let k = 1; k <= 3; k++) {
        let t = k / 4;
        let xL = lerp(gx, cx, t);
        let yL = lerp(cy, gy, t);
        let xR = lerp(cx, gx + tileW, t);
        let yR = lerp(gy + tileH, cy, t);
        safeLine(xL, yL, xR, yR, "2H", "#ffffff", 0.35);
      }

      // High-contrast mirror flash across selected chamak-patti diamonds
      if (random() < 0.45) {
        safeLine(gx + 8, cy - 3, gx + tileW - 8, cy + 3, "glint_blade", "#ffffff", 1.1);
      }
    }
  }
}

// ============================================================================
// 2. GENERATE DENSE 3D BANGLE HEAP
// ============================================================================

function generateBangleHeap() {
  bangles = [];
  segments = [];

  let idCounter = 0;

  function addBangle(cx, cy, cz, R, r, yaw, pitch, familyKey, patternType) {
    let pal = PALETTE[familyKey];
    let b = {
      id: idCounter++,
      cx,
      cy,
      cz,
      R,
      r,
      yaw,
      pitch,
      cosY: cos(yaw),
      sinY: sin(yaw),
      cosP: cos(pitch),
      sinP: sin(pitch),
      familyKey,
      pal,
      patternType, // 0: Zari/Gold Fleck, 1: Cut-Glass Facets, 2: Beaded Churi, 3: Liquid Gloss
      seed: random(1000)
    };
    bangles.push(b);
  }

  // Stratum 0 & 1: Dense interlocking carpet covering every square inch from 90..1110
  const cols = 6;
  const rows = 6;
  const startX = 145;
  const endX = 1055;
  const startY = 145;
  const endY = 1055;
  const stepX = (endX - startX) / (cols - 1);
  const stepY = (endY - startY) / (rows - 1);

  for (let rIdx = 0; rIdx < rows; rIdx++) {
    for (let cIdx = 0; cIdx < cols; cIdx++) {
      let baseX = startX + cIdx * stepX + (rIdx % 2 === 0 ? -18 : 18) + random(-24, 24);
      let baseY = startY + rIdx * stepY + random(-24, 24);
      let baseZ = 10 + (rIdx * cols + cIdx) * 0.8 + random(-8, 8);

      let yaw = random(0, 360);
      let pitch = random(20, 56);
      let R = random(118, 152);
      let tubeR = random(13.5, 17.5);

      let fam1 = FAMILY_KEYS[(rIdx * 3 + cIdx * 2 + floor(random(2))) % FAMILY_KEYS.length];
      let pat1 = fam1 === "BLACK_GOLD" ? 0 : floor(random(4));
      addBangle(baseX, baseY, baseZ, R, tubeR, yaw, pitch, fam1, pat1);

      // 65% chance to turn this into a cascading wrist-stack of 2 or 3 parallel bangles!
      if (random() < 0.65) {
        let stackCount = random() < 0.4 ? 2 : 1;
        let cascadeDirX = cos(yaw + 90) * tubeR * 1.45;
        let cascadeDirY = sin(yaw + 90) * tubeR * 1.45;
        let fam2 = FAMILY_KEYS[(FAMILY_KEYS.indexOf(fam1) + floor(random(1, 5))) % FAMILY_KEYS.length];

        for (let s = 1; s <= stackCount; s++) {
          let fKey = s % 2 === 1 ? fam2 : fam1;
          addBangle(
            baseX + cascadeDirX * s + random(-4, 4),
            baseY + cascadeDirY * s + random(-4, 4),
            baseZ + s * 6 + random(-2, 2),
            R + random(-3, 3),
            tubeR * random(0.92, 1.05),
            yaw + random(-5, 5),
            constrain(pitch + random(-4, 4), 18, 64),
            fKey,
            fKey === "BLACK_GOLD" ? 0 : (pat1 + s) % 4
          );
        }
      }
    }
  }

  // Stratum 2: Mid-heap tangled clusters & steeply tilted rolls bridging gaps
  for (let i = 0; i < 16; i++) {
    let bx = random(160, 1040);
    let by = random(160, 1040);
    let bz = random(48, 82);
    let yaw = random(0, 360);
    let pitch = random(32, 66);
    let R = random(122, 158);
    let tubeR = random(14, 18.5);
    let famA = FAMILY_KEYS[i % FAMILY_KEYS.length];
    let famB = FAMILY_KEYS[(i + 2) % FAMILY_KEYS.length];

    let rollCount = floor(random(2, 4));
    let dx = cos(yaw + 90) * tubeR * 1.5;
    let dy = sin(yaw + 90) * tubeR * 1.5;

    for (let k = 0; k < rollCount; k++) {
      let fk = k % 2 === 0 ? famA : famB;
      addBangle(
        bx + dx * k,
        by + dy * k,
        bz + k * 7,
        R,
        tubeR,
        yaw + random(-4, 4),
        pitch + random(-3, 3),
        fk,
        fk === "BLACK_GOLD" ? 0 : k % 4
      );
    }
  }

  // Stratum 3: Hero top-layer bangles lying prominently across the heap
  const heroSpots = [
    [270, 260], [600, 230], [920, 270],
    [230, 580], [490, 480], [740, 520], [960, 590],
    [420, 740], [690, 770],
    [280, 930], [610, 950], [920, 920],
    [350, 370], [830, 390], [580, 630]
  ];

  for (let i = 0; i < heroSpots.length; i++) {
    let hx = heroSpots[i][0] + random(-35, 35);
    let hy = heroSpots[i][1] + random(-35, 35);
    let hz = 92 + i * 3.5;
    let yaw = random(0, 360);
    let pitch = random(18, 52);
    let R = random(128, 162);
    let tubeR = random(15.5, 19.5);
    let fk = FAMILY_KEYS[(i * 2) % FAMILY_KEYS.length];

    addBangle(hx, hy, hz, R, tubeR, yaw, pitch, fk, fk === "BLACK_GOLD" ? 0 : i % 4);
  }

  // Break all bangles into 8 angular arc segments for authentic 3D depth weaving
  const N_SEG = 8;
  const stepDeg = 360 / N_SEG;

  for (let b of bangles) {
    for (let s = 0; s < N_SEG; s++) {
      let t1 = s * stepDeg;
      let t2 = (s + 1) * stepDeg;
      let tMid = (t1 + t2) * 0.5;
      let midPt = getBanglePoint(b, tMid, 0);

      segments.push({
        b,
        t1: t1 - 2.2, // Slight overlap for seamless continuity
        t2: t2 + 2.2,
        tMid,
        mx: midPt.x,
        my: midPt.y,
        mz: midPt.z,
        mnx: midPt.nx,
        mny: midPt.ny,
        neighborPal: null
      });
    }
  }

  // Precompute nearest neighbor of a DIFFERENT color family for hyperreal color refraction!
  for (let i = 0; i < segments.length; i++) {
    let segA = segments[i];
    let bestDistSq = 180 * 180;
    let bestPal = PALETTE[FAMILY_KEYS[(FAMILY_KEYS.indexOf(segA.b.familyKey) + 1) % FAMILY_KEYS.length]];

    for (let j = 0; j < segments.length; j += 2) {
      let segB = segments[j];
      if (segB.b.id === segA.b.id || segB.b.familyKey === segA.b.familyKey) continue;
      let dx = segB.mx - segA.mx;
      let dy = segB.my - segA.my;
      let dSq = dx * dx + dy * dy;
      if (dSq < bestDistSq && dSq > 60) {
        bestDistSq = dSq;
        bestPal = segB.b.pal;
      }
    }
    segA.neighborPal = bestPal;
  }

  // Sort segments back-to-front by 3D depth z
  segments.sort((a, b) => a.mz - b.mz);
}

// ============================================================================
// 3. WATERCOLOR CAUSTIC & SHADOW UNDERPAINTING
// ============================================================================

function drawWatercolorCausticUnderlayer() {
  // Group caustic washes by color family for optimal p5.brush fill caching
  for (let fk of FAMILY_KEYS) {
    let pal = PALETTE[fk];
    let familyBangles = bangles.filter((b) => b.familyKey === fk);

    for (let i = 0; i < familyBangles.length; i += 2) {
      let b = familyBangles[i];
      // Caustic ribbon polygon offset toward shadow direction
      let causticPts = [];
      let startAng = random(0, 180);
      for (let a = startAng; a <= startAng + 160; a += 32) {
        let pOut = getBanglePoint(b, a, 0.9);
        causticPts.push([pOut.x + 10, pOut.y + 14]);
      }
      for (let a = startAng + 160; a >= startAng; a -= 32) {
        let pIn = getBanglePoint(b, a, -0.9);
        causticPts.push([pIn.x + 10, pIn.y + 14]);
      }
      let washCol = fk === "BLACK_GOLD" ? pal.accent : pal.mid;
      drawWatercolorPoly(causticPts, washCol, 95, 0.28, 0.55);
    }
  }
}

// ============================================================================
// 4. DEPTH-SORTED 3D HYPERREAL BANGLE RENDERING
// ============================================================================

function drawDepthSortedBangles() {
  const numPts = 5;

  for (let idx = 0; idx < segments.length; idx++) {
    let seg = segments[idx];
    let b = seg.b;
    let pal = b.pal;
    let nPal = seg.neighborPal;

    // Sample points along the arc segment
    let spinePts = [];
    let outerRimPts = [];
    let innerRimPts = [];
    let bodyOutPts = [];
    let bodyInPts = [];
    let causticPts = [];
    let refractPts = [];
    let specPts = [];
    let secSpecPts = [];
    let shadowPts = [];

    // Alignment of segment normal with primary light source (-52 deg)
    let worldNormAng = atan2(seg.mny, seg.mnx);
    let lightDot = cos(worldNormAng - LIGHT_ANGLE); // -1 to +1
    let lightSign = lightDot >= 0 ? 1 : -1;
    let specIntensity = abs(lightDot); // Strongest when glass tube runs perpendicular to light ray

    // Cross-section positions for optical features
    let sCaustic = -0.38 * lightSign; // Lens focus opposite lit side
    let sRefract = 0.48 * lightSign;  // Neighbor refraction on flank
    let sSpec = 0.36 * lightSign;     // Primary specular ridge
    let sSecSpec = -0.66 * lightSign; // Secondary internal wall bounce

    for (let k = 0; k < numPts; k++) {
      let f = k / (numPts - 1);
      let theta = lerp(seg.t1, seg.t2, f);
      let endPress = (k === 0 || k === numPts - 1) ? 0.72 : 1.05;

      let pSpine = getBanglePoint(b, theta, 0);
      let pOutRim = getBanglePoint(b, theta, 0.86);
      let pInRim = getBanglePoint(b, theta, -0.86);
      let pBodyOut = getBanglePoint(b, theta, 0.42);
      let pBodyIn = getBanglePoint(b, theta, -0.42);
      let pCaustic = getBanglePoint(b, theta, sCaustic);
      let pRefract = getBanglePoint(b, theta, sRefract);
      let pSpec = getBanglePoint(b, theta, sSpec);
      let pSecSpec = getBanglePoint(b, theta, sSecSpec);

      spinePts.push([pSpine.x, pSpine.y, endPress]);
      outerRimPts.push([pOutRim.x, pOutRim.y, endPress]);
      innerRimPts.push([pInRim.x, pInRim.y, endPress]);
      bodyOutPts.push([pBodyOut.x, pBodyOut.y, endPress]);
      bodyInPts.push([pBodyIn.x, pBodyIn.y, endPress]);
      causticPts.push([pCaustic.x, pCaustic.y, endPress]);
      refractPts.push([pRefract.x, pRefract.y, endPress]);
      specPts.push([pSpec.x, pSpec.y, (k === 0 || k === numPts - 1) ? 0.3 : 1.25]);
      secSpecPts.push([pSecSpec.x, pSecSpec.y, 0.65]);
      shadowPts.push([pSpine.x + 6, pSpine.y + 8, endPress * 0.85]);
    }

    let wScale = b.r / 15.5;

    // A. Cast occlusion shadow onto underlying bangles / chamak-patti
    safeSpline(shadowPts, 0.3, "shadow_wash", pal.shadow, 1.35 * wScale);

    // B. Solid translucent glass core wash to block background where glass is dense
    let quadPts = [
      [outerRimPts[0][0], outerRimPts[0][1]],
      [outerRimPts[2][0], outerRimPts[2][1]],
      [outerRimPts[4][0], outerRimPts[4][1]],
      [innerRimPts[4][0], innerRimPts[4][1]],
      [innerRimPts[2][0], innerRimPts[2][1]],
      [innerRimPts[0][0], innerRimPts[0][1]]
    ];
    drawWashPoly(quadPts, pal.dark, b.familyKey === "BLACK_GOLD" ? 235 : 185);

    // C. Saturated Marker Body Strokes
    safeSpline(bodyOutPts, 0.3, "glass_marker", pal.mid, 1.15 * wScale);
    safeSpline(bodyInPts, 0.3, "glass_marker", pal.dark, 1.15 * wScale);
    safeSpline(spinePts, 0.3, "glass_marker", pal.mid, 1.3 * wScale);

    // D. Refracted Neighbor Color Reflected Inside the Glass Tube!
    let refractCol = nPal.bright;
    safeSpline(refractPts, 0.3, "caustic_glow", refractCol, 0.72 * wScale);

    // E. Internal Luminous Caustic Core
    let causticCol = specIntensity > 0.55 ? pal.core : pal.bright;
    safeSpline(causticPts, 0.3, "caustic_glow", causticCol, 0.88 * wScale);

    // F. High-Contrast Fresnel Dark Edges (Inner & Outer Glass Wall Boundaries)
    safeSpline(outerRimPts, 0.3, "pen", pal.shadow, 1.45 * wScale);
    safeSpline(innerRimPts, 0.3, "pen", pal.shadow, 1.35 * wScale);

    // G. Authentic Surface Embellishments (Gold Flecks, Zari Stripes, Facets, Churi Ridges)
    drawBangleSurfacePattern(seg, b, pal, nPal, wScale, specIntensity);

    // H. Sharp Specular Streaks & Secondary Internal Reflections
    if (specIntensity > 0.25) {
      let glintW = map(specIntensity, 0.25, 1.0, 0.45, 1.25) * wScale;
      safeSpline(specPts, 0.3, "glint_blade", "#ffffff", glintW);
      safeSpline(secSpecPts, 0.3, "rotring", pal.core, 0.55 * wScale);
    } else {
      safeSpline(specPts, 0.3, "rotring", pal.bright, 0.5 * wScale);
    }
  }
}

function drawBangleSurfacePattern(seg, b, pal, nPal, wScale, specIntensity) {
  if (b.patternType === 0) {
    // Type 0: Gold-Flecked & Diagonal Zari Stripes (Signature on Black-Gold & Emerald)
    let isBlackGold = b.familyKey === "BLACK_GOLD";
    let stripeSteps = isBlackGold ? 3 : 2;

    for (let m = 0; m < stripeSteps; m++) {
      let tA = lerp(seg.t1 + 4, seg.t2 - 4, (m + 0.2) / stripeSteps);
      let tB = tA + 7;
      let p1 = getBanglePoint(b, tA, -0.72);
      let p2 = getBanglePoint(b, (tA + tB) * 0.5, 0);
      let p3 = getBanglePoint(b, tB, 0.72);

      safeSpline(
        [[p1.x, p1.y, 0.6], [p2.x, p2.y, 1.2], [p3.x, p3.y, 0.6]],
        0.25,
        "pen",
        pal.accent,
        1.1 * wScale
      );

      // Gold leaf & Kundan sparkle flecks
      brush.set("zari_sparkle", pal.secAccent, 0.9 * wScale);
      brush.line(p1.x, p1.y, p3.x, p3.y);

      if (isBlackGold) {
        // Raised gold Kundan stud highlight
        brush.set("glint_blade", "#fff8cc", 0.95 * wScale);
        brush.line(p2.x - 2, p2.y - 2, p2.x + 2, p2.y + 2);
      }
    }
  } else if (b.patternType === 1) {
    // Type 1: Diamond Cut-Glass Facets (Katan) with Fractured Reflections
    for (let m = 0; m < 2; m++) {
      let tC = lerp(seg.t1 + 8, seg.t2 - 8, (m + 0.5) / 2);
      let pTop = getBanglePoint(b, tC - 3.5, -0.48);
      let pMid = getBanglePoint(b, tC, 0.15);
      let pBot = getBanglePoint(b, tC + 3.5, -0.48);
      let pOpp = getBanglePoint(b, tC, 0.58);

      // Refracted neighbor flash inside cut facet
      safeLine(pTop.x, pTop.y, pMid.x, pMid.y, "pen", nPal.bright, 0.95 * wScale);
      safeLine(pMid.x, pMid.y, pBot.x, pBot.y, "glint_blade", "#ffffff", 0.75 * wScale);
      safeLine(pMid.x, pMid.y, pOpp.x, pOpp.y, "rotring", pal.accent, 0.7 * wScale);
    }
  } else if (b.patternType === 2) {
    // Type 2: Ridged Churi with Rhythmic Transverse Specular Pearls
    for (let m = 0; m < 3; m++) {
      let tR = lerp(seg.t1 + 5, seg.t2 - 5, (m + 0.5) / 3);
      let pA = getBanglePoint(b, tR, -0.65);
      let pB = getBanglePoint(b, tR, 0.65);
      safeLine(pA.x, pA.y, pB.x, pB.y, "rotring", pal.shadow, 0.55 * wScale);

      if (specIntensity > 0.35) {
        let pGlint = getBanglePoint(b, tR, 0.22);
        safeLine(pGlint.x - 2, pGlint.y - 1.5, pGlint.x + 2, pGlint.y + 1.5, "glint_blade", "#ffffff", 0.95 * wScale);
      }
    }
  }
}

// ============================================================================
// 5. TOP-LAYER OPTICAL GLINTS & FRACTURED REFLECTIONS
// ============================================================================

function drawTopOpticalGlints() {
  // Add ultra-crisp white pen glints, cross-starbursts, and micro-refractions on upper strata
  let topSegments = segments.slice(floor(segments.length * 0.55));

  for (let i = 0; i < topSegments.length; i++) {
    let seg = topSegments[i];
    let b = seg.b;
    let pal = b.pal;
    let nPal = seg.neighborPal;

    let worldNormAng = atan2(seg.mny, seg.mnx);
    let lightDot = cos(worldNormAng - LIGHT_ANGLE);

    // High-intensity specular blade on top bangles
    if (abs(lightDot) > 0.62) {
      let sPos = 0.34 * (lightDot >= 0 ? 1 : -1);
      let p1 = getBanglePoint(b, seg.tMid - 9, sPos);
      let p2 = getBanglePoint(b, seg.tMid, sPos);
      let p3 = getBanglePoint(b, seg.tMid + 9, sPos);

      safeSpline(
        [[p1.x, p1.y, 0.2], [p2.x, p2.y, 1.4], [p3.x, p3.y, 0.2]],
        0.3,
        "glint_blade",
        "#ffffff",
        1.15
      );

      // Tiny fractured cross-glint star at peak curvature
      if (abs(lightDot) > 0.85 && i % 3 === 0) {
        let flareLen = 7.5;
        safeLine(p2.x - flareLen, p2.y, p2.x + flareLen, p2.y, "glint_blade", "#ffffff", 0.75);
        safeLine(p2.x, p2.y - flareLen, p2.x, p2.y + flareLen, "glint_blade", "#ffffff", 0.75);
        safeLine(p2.x - 4, p2.y - 4, p2.x + 4, p2.y + 4, "rotring", nPal.core, 0.6);
      }
    }

    // Tiny fractured chamak-patti reflection ticks on glass flank
    if (i % 4 === 0) {
      let pFlank = getBanglePoint(b, seg.tMid + 5, -0.52);
      let tickAng = b.yaw + 45;
      let tx = cos(tickAng) * 5;
      let ty = sin(tickAng) * 5;
      safeLine(pFlank.x - tx, pFlank.y - ty, pFlank.x + tx, pFlank.y + ty, "pen", nPal.bright, 0.75);
    }
  }
}

// ============================================================================
// 6. DENSE TRUCK-ART BORDER OF PAINTED PETALS & CHEVRONS
// ============================================================================

function drawTruckArtBorder() {
  const B = 84; // Total border width
  const outerTrack = 20;
  const innerTrack = 18;

  // 1. Solid dark framing ground for the four border strips
  drawWashPoly([[0, 0], [width, 0], [width, B], [0, B]], "#05040d", 250);
  drawWashPoly([[0, height - B], [width, height - B], [width, height], [0, height]], "#05040d", 250);
  drawWashPoly([[0, B], [B, B], [B, height - B], [0, height - B]], "#05040d", 250);
  drawWashPoly([[width - B, B], [width, B], [width, height - B], [width - B, height - B]], "#05040d", 250);

  // 2. Outer Chamak-Patti Chevron Band (0 .. 20px from canvas edge)
  drawChevronBand(0, outerTrack, 28, true);

  // 3. Inner Sawtooth & Chevron Moulding (B - 18 .. B px from canvas edge)
  drawChevronBand(B - innerTrack, B, 22, false);

  // 4. Dense Painted Truck-Art Petal Frieze (20 .. 66px from canvas edge)
  drawPaintedPetalFrieze(outerTrack, B - innerTrack, B);

  // 5. Crisp Gold & White Structural Framing Lines
  const frameLines = [outerTrack, B - innerTrack, B];
  for (let offset of frameLines) {
    let col = offset === B ? "#ffd000" : "#ffffff";
    let w = offset === B ? 1.1 : 0.75;
    safeLine(offset, offset, width - offset, offset, "pen", col, w);
    safeLine(width - offset, offset, width - offset, height - offset, "pen", col, w);
    safeLine(width - offset, height - offset, offset, height - offset, "pen", col, w);
    safeLine(offset, height - offset, offset, offset, "pen", col, w);
  }

  // 6. Four Celebratory Corner Medallions
  drawCornerMedallion(B * 0.5, B * 0.5, B * 0.52);
  drawCornerMedallion(width - B * 0.5, B * 0.5, B * 0.52);
  drawCornerMedallion(width - B * 0.5, height - B * 0.5, B * 0.52);
  drawCornerMedallion(B * 0.5, height - B * 0.5, B * 0.52);
}

function drawChevronBand(d1, d2, step, isOuter) {
  const chevronColors = [
    PALETTE.EMERALD.mid,
    PALETTE.HOT_PINK.mid,
    PALETTE.SAFFRON.mid,
    PALETTE.ULTRAMARINE.mid,
    "#ffd000",
    "#ffffff",
    "#120e1f"
  ];

  // Draw chevrons along all 4 sides using transform helper
  const sides = [
    { x0: d2, y0: d1, x1: width - d2, y1: d1, nx: 0, ny: 1, tx: 1, ty: 0 },
    { x0: width - d1, y0: d2, x1: width - d1, y1: height - d2, nx: -1, ny: 0, tx: 0, ty: 1 },
    { x0: width - d2, y0: height - d1, x1: d2, y1: height - d1, nx: 0, ny: -1, tx: -1, ty: 0 },
    { x0: d1, y0: height - d2, x1: d1, y1: d2, nx: 1, ny: 0, tx: 0, ty: -1 }
  ];

  let bandW = d2 - d1;
  let midW = bandW * 0.5;

  for (let s = 0; s < sides.length; s++) {
    let sd = sides[s];
    let len = dist(sd.x0, sd.y0, sd.x1, sd.y1);
    let count = floor(len / step);
    let actualStep = len / count;

    for (let i = 0; i < count; i++) {
      let col = chevronColors[(i + s * 2) % chevronColors.length];
      let dA = i * actualStep;
      let dB = (i + 1) * actualStep;
      let tipShift = actualStep * 0.45;

      // Chevron polygon vertices
      let p1 = [sd.x0 + sd.tx * dA, sd.y0 + sd.ty * dA];
      let p2 = [sd.x0 + sd.tx * dB, sd.y0 + sd.ty * dB];
      let p3 = [sd.x0 + sd.tx * (dB + tipShift) + sd.nx * midW, sd.y0 + sd.ty * (dB + tipShift) + sd.ny * midW];
      let p4 = [sd.x0 + sd.tx * dB + sd.nx * bandW, sd.y0 + sd.ty * dB + sd.ny * bandW];
      let p5 = [sd.x0 + sd.tx * dA + sd.nx * bandW, sd.y0 + sd.ty * dA + sd.ny * bandW];
      let p6 = [sd.x0 + sd.tx * (dA + tipShift) + sd.nx * midW, sd.y0 + sd.ty * (dA + tipShift) + sd.ny * midW];

      drawWashPoly([p1, p2, p3, p4, p5, p6], col, 240);

      // Crisp black outline and white specular tick
      safeLine(p1[0], p1[1], p6[0], p6[1], "rotring", "#05040a", 0.7);
      safeLine(p6[0], p6[1], p5[0], p5[1], "rotring", "#05040a", 0.7);
      if (isOuter && i % 2 === 0) {
        safeLine(p6[0], p6[1], p3[0], p3[1], "glint_blade", "#ffffff", 0.65);
      }
    }
  }
}

function drawPaintedPetalFrieze(dInner, dOuter, cornerPad) {
  let bandW = dOuter - dInner;
  let midOff = (dInner + dOuter) * 0.5;

  const sides = [
    { x0: cornerPad, y0: midOff, x1: width - cornerPad, y1: midOff, ang: 0 },
    { x0: width - midOff, y0: cornerPad, x1: width - midOff, y1: height - cornerPad, ang: 90 },
    { x0: width - cornerPad, y0: height - midOff, x1: cornerPad, y1: height - midOff, ang: 180 },
    { x0: midOff, y0: height - cornerPad, x1: midOff, y1: cornerPad, ang: 270 }
  ];

  const flowerFamilies = ["HOT_PINK", "SAFFRON", "ULTRAMARINE", "EMERALD"];

  for (let s = 0; s < sides.length; s++) {
    let sd = sides[s];
    let len = dist(sd.x0, sd.y0, sd.x1, sd.y1);
    let numBlooms = 19;
    let step = len / numBlooms;

    for (let i = 0; i < numBlooms; i++) {
      let t = (i + 0.5) / numBlooms;
      let bx = lerp(sd.x0, sd.x1, t);
      let by = lerp(sd.y0, sd.y1, t);
      let fk = flowerFamilies[(i + s) % flowerFamilies.length];
      let pal = PALETTE[fk];

      // Emerald truck-art leaves flanking each blossom
      for (let sideSign of [-1, 1]) {
        let leafAng = sd.ang + (sideSign > 0 ? 28 : 152);
        let lx1 = bx + cos(leafAng) * (step * 0.22);
        let ly1 = by + sin(leafAng) * (step * 0.22);
        let lx2 = bx + cos(leafAng) * (step * 0.52);
        let ly2 = by + sin(leafAng) * (step * 0.52);
        let lPerpX = -sin(leafAng) * 7;
        let lPerpY = cos(leafAng) * 7;

        drawWashPoly(
          [[bx, by], [lx1 + lPerpX, ly1 + lPerpY], [lx2, ly2], [lx1 - lPerpX, ly1 - lPerpY]],
          PALETTE.EMERALD.mid,
          230
        );
        safeLine(bx, by, lx2, ly2, "pen", PALETTE.EMERALD.bright, 0.75);
      }

      // 6-petal painted truck-art blossom
      let numPetals = 6;
      let pRadius = bandW * 0.46;
      for (let p = 0; p < numPetals; p++) {
        let pAng = sd.ang + p * (360 / numPetals);
        let tipX = bx + cos(pAng) * pRadius;
        let tipY = by + sin(pAng) * pRadius;
        let leftX = bx + cos(pAng - 24) * (pRadius * 0.62);
        let leftY = by + sin(pAng - 24) * (pRadius * 0.62);
        let rightX = bx + cos(pAng + 24) * (pRadius * 0.62);
        let rightY = by + sin(pAng + 24) * (pRadius * 0.62);

        // Saturated petal wash + bright core + crisp white scallop outline
        drawWashPoly([[bx, by], [leftX, leftY], [tipX, tipY], [rightX, rightY]], pal.mid, 245);
        safeLine(bx, by, tipX, tipY, "caustic_glow", pal.bright, 0.85);
        safeSpline([[leftX, leftY, 0.6], [tipX, tipY, 1.1], [rightX, rightY, 0.6]], 0.35, "glint_blade", "#ffffff", 0.7);
      }

      // Golden & ruby center eye of the blossom
      brush.noStroke();
      brush.wash("#ffd000", 250);
      brush.circle(bx, by, 5.5);
      brush.noWash();
      safeLine(bx - 2, by - 2, bx + 2, by + 2, "glint_blade", "#ffffff", 0.9);
    }
  }
}

function drawCornerMedallion(cx, cy, rad) {
  // Square dark base
  drawWashPoly(
    [[cx - rad, cy - rad], [cx + rad, cy - rad], [cx + rad, cy + rad], [cx - rad, cy + rad]],
    "#060412",
    255
  );

  // Outer 12-petal marigold & rani rosette
  let petals = 12;
  for (let i = 0; i < petals; i++) {
    let a = i * (360 / petals);
    let pal = i % 2 === 0 ? PALETTE.SAFFRON : PALETTE.HOT_PINK;
    let rOut = rad * 0.92;
    let p1 = [cx + cos(a - 14) * (rOut * 0.55), cy + sin(a - 14) * (rOut * 0.55)];
    let p2 = [cx + cos(a) * rOut, cy + sin(a) * rOut];
    let p3 = [cx + cos(a + 14) * (rOut * 0.55), cy + sin(a + 14) * (rOut * 0.55)];

    drawWashPoly([[cx, cy], p1, p2, p3], pal.mid, 245);
    safeLine(cx, cy, p2[0], p2[1], "pen", pal.bright, 0.8);
    safeSpline([p1, p2, p3], 0.3, "glint_blade", "#ffffff", 0.75);
  }

  // Inner chamak-patti emerald & ultramarine star
  for (let i = 0; i < 8; i++) {
    let a = i * 45 + 22.5;
    let rStar = rad * 0.48;
    let col = i % 2 === 0 ? PALETTE.EMERALD.bright : PALETTE.ULTRAMARINE.bright;
    let p1 = [cx + cos(a - 18) * (rStar * 0.45), cy + sin(a - 18) * (rStar * 0.45)];
    let p2 = [cx + cos(a) * rStar, cy + sin(a) * rStar];
    let p3 = [cx + cos(a + 18) * (rStar * 0.45), cy + sin(a + 18) * (rStar * 0.45)];
    drawWashPoly([[cx, cy], p1, p2, p3], col, 250);
    safeLine(p1[0], p1[1], p2[0], p2[1], "rotring", "#05040a", 0.65);
  }

  // Central mirror jewel
  brush.noStroke();
  brush.wash("#ffd000", 255);
  brush.circle(cx, cy, rad * 0.18);
  brush.noWash();
  safeLine(cx - 5, cy - 5, cx + 5, cy + 5, "glint_blade", "#ffffff", 1.1);
  safeLine(cx - 5, cy + 5, cx + 5, cy - 5, "glint_blade", "#ffffff", 1.1);
}

// ============================================================================
// 7. FOREGROUND BANGLE ARCS OVERLAPPING THE INNER BORDER EDGE
// ============================================================================

function drawBorderOverlappingArcs() {
  // Re-draw segments that sit near the inner border edge (84px) and belong to upper strata
  // so that the teeming bangle heap physically spills slightly over the inner moulding!
  const B = 84;
  for (let seg of segments) {
    if (seg.mz < 55) continue;
    let nearBorder =
      (seg.mx > B - 22 && seg.mx < B + 26) ||
      (seg.mx > width - B - 26 && seg.mx < width - B + 22) ||
      (seg.my > B - 22 && seg.my < B + 26) ||
      (seg.my > height - B - 26 && seg.my < height - B + 22);

    if (!nearBorder) continue;

    let b = seg.b;
    let pal = b.pal;
    let wScale = b.r / 15.5;

    let spinePts = [];
    let outPts = [];
    let inPts = [];
    let specPts = [];

    for (let k = 0; k < 5; k++) {
      let theta = lerp(seg.t1, seg.t2, k / 4);
      let pS = getBanglePoint(b, theta, 0);
      let pO = getBanglePoint(b, theta, 0.82);
      let pI = getBanglePoint(b, theta, -0.82);
      let pG = getBanglePoint(b, theta, 0.3);
      spinePts.push([pS.x, pS.y, 1.0]);
      outPts.push([pO.x, pO.y, 1.0]);
      inPts.push([pI.x, pI.y, 1.0]);
      specPts.push([pG.x, pG.y, 1.1]);
    }

    safeSpline(spinePts, 0.3, "glass_marker", pal.mid, 1.35 * wScale);
    safeSpline(outPts, 0.3, "pen", pal.shadow, 1.4 * wScale);
    safeSpline(inPts, 0.3, "pen", pal.shadow, 1.3 * wScale);
    safeSpline(specPts, 0.3, "glint_blade", "#ffffff", 0.9 * wScale);
  }
}

// Hyperreal Jointed Wooden Mannequin Hand & Three Black-Gloved Puppeteer Hands
// Rendered with p5.js v2 & p5.brush

const LIGHT_DIR = normalize3([-0.64, -0.54, 0.55]);
const BOUNCE_DIR = normalize3([0.72, 0.42, 0.25]);
const VIEW_DIR = [0, 0, 1];
const HALF_VEC = normalize3([
  LIGHT_DIR[0] + VIEW_DIR[0],
  LIGHT_DIR[1] + VIEW_DIR[1],
  LIGHT_DIR[2] + VIEW_DIR[2]
]);

function normalize3(v) {
  let m = Math.hypot(v[0], v[1], v[2]) || 1;
  return [v[0] / m, v[1] / m, v[2] / m];
}

function dot3(a, b) {
  return a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
}

function clamp01(v) {
  return Math.max(0, Math.min(1, v));
}

function lerpNum(a, b, t) {
  return a + (b - a) * t;
}

function lerpPt(p1, p2, t) {
  return [lerpNum(p1[0], p2[0], t), lerpNum(p1[1], p2[1], t)];
}

function hexToRgb(hex) {
  let h = hex.replace("#", "");
  if (h.length === 3) {
    h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2];
  }
  let n = parseInt(h, 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

function rgbToHex(r, g, b) {
  const c = (v) => Math.max(0, Math.min(255, Math.round(v))).toString(16).padStart(2, "0");
  return "#" + c(r) + c(g) + c(b);
}

function mixHex(h1, h2, t) {
  let a = hexToRgb(h1);
  let b = hexToRgb(h2);
  let u = clamp01(t);
  return rgbToHex(
    lerpNum(a[0], b[0], u),
    lerpNum(a[1], b[1], u),
    lerpNum(a[2], b[2], u)
  );
}

// Maps 3D lighting values to a soft pastel & warm beech wood palette
function woodColorAt(diffuse, bounce, spec) {
  let col;
  if (diffuse > 0.68) {
    col = mixHex("#f4e2ce", "#fbf4eb", (diffuse - 0.68) / 0.32);
  } else if (diffuse > 0.36) {
    col = mixHex("#ebc6a6", "#f4e2ce", (diffuse - 0.36) / 0.32);
  } else if (diffuse > 0.06) {
    col = mixHex("#d9a28d", "#ebc6a6", (diffuse - 0.06) / 0.30);
  } else if (diffuse > -0.24) {
    col = mixHex("#9c6755", "#d9a28d", (diffuse + 0.24) / 0.30);
  } else {
    col = mixHex("#593528", "#9c6755", clamp01((diffuse + 0.75) / 0.51));
  }

  // Soft pastel bounce light on the shadow edge (cool slate-lavender & warm amber)
  if (diffuse < 0.05 && bounce > 0.15) {
    let bAmt = clamp01((bounce - 0.15) * 0.75) * clamp01(-diffuse + 0.15);
    col = mixHex(col, "#9e8886", bAmt * 0.65);
  }

  // Glossy specular varnish sheen
  if (spec > 0.08) {
    col = mixHex(col, "#fffdf9", clamp01(spec * 0.85));
  }
  return col;
}

function resetBrushState() {
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.noField();
}

function drawShapePoly(pts, curvature = 0.12, closed = true) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closed);
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  angleMode(DEGREES);
  brush.scaleBrushes(3);
  randomSeed(7391);
  noiseSeed(7391);

  // Add a delicate micro-grain brush for beech wood pores and varnish scuffs
  brush.add("beech_pore", {
    type: "default",
    weight: 0.45,
    scatter: 0.12,
    sharpness: 0.78,
    grain: 0.65,
    opacity: 165,
    spacing: 0.18,
    pressure: [0.4, 1.1, 0.3],
    noise: 0.4
  });

  // Add a dense velvety charcoal brush for the void and puppeteer gloves
  brush.add("velvet_void", {
    type: "default",
    weight: 3.8,
    scatter: 0.85,
    sharpness: 0.22,
    grain: 0.88,
    opacity: 95,
    spacing: 0.22,
    pressure: [0.3, 1.0, 0.25],
    noise: 0.8
  });
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#0b0a0e");

  // 1. Deep velvety charcoal black background & atmospheric void
  renderVelvetVoid();

  // 2. Back layers of the three black-gloved hands emerging from the void
  renderGlovesBack();

  // 3. The lit jointed wooden mannequin hand (back-to-front anatomical order)
  renderMannequinHand();

  // 4. Front overlapping gloved fingers holding/manipulating the wooden hand
  renderGlovesFront();

  // 5. Final theatrical chiaroscuro, stray dust & specular touches
  renderFinalTouches();

  noLoop();
}

// ============================================================================
// STAGE 1: DEEP VELVETY CHARCOAL VOID
// ============================================================================
function renderVelvetVoid() {
  resetBrushState();

  // Base deep charcoal wash across canvas
  brush.wash("#0a090d", 255);
  drawShapePoly([[0, 0], [1200, 0], [1200, 1200], [0, 1200]], 0);
  brush.noWash();

  // Subtle hushed theatrical spotlight warmth in the central void
  const haloLayers = [
    { r: 520, col: "#121017", op: 110 },
    { r: 410, col: "#17141d", op: 95 },
    { r: 310, col: "#1d1823", op: 80 },
    { r: 220, col: "#221c27", op: 60 }
  ];
  for (let h of haloLayers) {
    let pts = [];
    let steps = 28;
    for (let i = 0; i < steps; i++) {
      let ang = (i / steps) * 360;
      let rad = h.r * (0.88 + 0.16 * noise(i * 0.3, h.r * 0.01));
      pts.push([
        585 + cos(ang) * rad * 0.92,
        555 + sin(ang) * rad * 1.12
      ]);
    }
    brush.wash(h.col, h.op);
    drawShapePoly(pts, 0.25);
  }
  brush.noWash();

  // Velvety diagonal & radial charcoal strokes across the background
  const voidTones = ["#07060a", "#0d0c12", "#13111a", "#09080c", "#181521"];
  for (let i = 0; i < 340; i++) {
    let x = random(-40, 1240);
    let y = random(-40, 1240);
    let dCenter = dist(x, y, 585, 540);
    let col = dCenter < 340 ? voidTones[int(random(1, 5))] : voidTones[int(random(0, 3))];
    let len = random(90, 240);
    let ang = -55 + random(-22, 22);
    let x2 = x + cos(ang) * len;
    let y2 = y + sin(ang) * len;

    brush.set("velvet_void", col, random(1.2, 2.8));
    brush.line(x, y, x2, y2);
  }

  // Fine charcoal grain & spray stipple in the transition zone
  for (let i = 0; i < 160; i++) {
    let ang = random(360);
    let rad = random(180, 560);
    let x = 585 + cos(ang) * rad * 0.9;
    let y = 550 + sin(ang) * rad * 1.05;
    let l = random(40, 110);
    let a2 = ang + 90 + random(-30, 30);
    brush.set("charcoal", i % 2 === 0 ? "#08070b" : "#17141f", random(0.8, 1.8));
    brush.line(x, y, x + cos(a2) * l, y + sin(a2) * l);
  }
}

// ============================================================================
// CORE GEOMETRY & RENDERING FOR GLOVED PUPPETEER HANDS
// ============================================================================
function drawGloveSegment(p1, r1, p2, r2, opts = {}) {
  resetBrushState();
  let dx = p2[0] - p1[0];
  let dy = p2[1] - p1[1];
  let L = Math.hypot(dx, dy) || 1;
  let ux = dx / L;
  let uy = dy / L;
  let nx = -uy;
  let ny = ux;

  // Build rounded capsule polygon for opaque dark charcoal base
  let poly = [];
  let steps = 12;
  for (let i = 0; i <= steps; i++) {
    let u = i / steps;
    let swell = Math.sin(u * Math.PI) * (opts.swell || 0.08);
    let r = lerpNum(r1, r2, u) * (1 + swell);
    let cx = lerpNum(p1[0], p2[0], u);
    let cy = lerpNum(p1[1], p2[1], u);
    poly.push([cx - nx * r, cy - ny * r]);
  }
  // Tip cap
  for (let i = 1; i < 6; i++) {
    let a = (i / 6) * 180;
    let ca = cos(a);
    let sa = sin(a);
    poly.push([
      p2[0] + nx * ca * r2 + ux * sa * (r2 * 0.85),
      p2[1] + ny * ca * r2 + uy * sa * (r2 * 0.85)
    ]);
  }
  for (let i = steps; i >= 0; i--) {
    let u = i / steps;
    let swell = Math.sin(u * Math.PI) * (opts.swell || 0.08);
    let r = lerpNum(r1, r2, u) * (1 + swell);
    let cx = lerpNum(p1[0], p2[0], u);
    let cy = lerpNum(p1[1], p2[1], u);
    poly.push([cx + nx * r, cy + ny * r]);
  }
  // Base cap
  for (let i = 1; i < 5; i++) {
    let a = (i / 5) * 180;
    let ca = cos(a);
    let sa = sin(a);
    poly.push([
      p1[0] - nx * ca * r1 - ux * sa * (r1 * 0.65),
      p1[1] - ny * ca * r1 - uy * sa * (r1 * 0.65)
    ]);
  }

  // Opaque velvety black wash so the glove cleanly occludes anything behind it
  brush.wash(opts.baseCol || "#0c0b10", 252);
  drawShapePoly(poly, 0.12);
  brush.noWash();

  // Dry charcoal mass inside the glove segment
  brush.mass("charcoal", "#121018", { precision: 0.45, strength: 0.55, outline: false });
  drawShapePoly(poly, 0.12);
  brush.noMass();

  // Directional charcoal shading strokes along the glove fabric
  let nLines = Math.max(12, Math.floor((r1 + r2) * 0.55));
  for (let i = 0; i < nLines; i++) {
    let s = lerpNum(-0.92, 0.92, i / (nLines - 1));
    let u0 = random(0.02, 0.18);
    let u1 = random(0.82, 0.98);
    let rA = lerpNum(r1, r2, u0);
    let rB = lerpNum(r1, r2, u1);
    let xA = lerpNum(p1[0], p2[0], u0) + nx * s * rA;
    let yA = lerpNum(p1[1], p2[1], u0) + ny * s * rA;
    let xB = lerpNum(p1[0], p2[0], u1) + nx * s * rB;
    let yB = lerpNum(p1[1], p2[1], u1) + ny * s * rB;

    // Compute 3D normal to see if this edge catches faint rim or bounce light
    let nz = Math.sqrt(Math.max(0, 1 - s * s));
    let n3 = [s * nx, s * ny, nz];
    let diff = dot3(n3, LIGHT_DIR);

    let col = "#09080d";
    if (diff > 0.35) {
      col = mixHex("#14121b", "#292536", (diff - 0.35) / 0.65);
    } else if (diff > 0.0) {
      col = "#14121b";
    }
    brush.set("charcoal", col, random(0.55, 1.15));
    brush.line(xA, yA, xB, yB);
  }

  // Subtle edge rim on the lit side or wood-facing side
  if (opts.rimSide !== undefined) {
    let side = opts.rimSide; // -1 or 1
    let rimCol = opts.rimCol || "#4e495e";
    let pts = [];
    for (let i = 1; i <= 8; i++) {
      let u = i / 9;
      let swell = Math.sin(u * Math.PI) * (opts.swell || 0.08);
      let r = lerpNum(r1, r2, u) * (1 + swell) * 0.92;
      let cx = lerpNum(p1[0], p2[0], u) + nx * side * r;
      let cy = lerpNum(p1[1], p2[1], u) + ny * side * r;
      pts.push([cx, cy, random(0.3, 0.9)]);
    }
    brush.set("cpencil", rimCol, 0.55);
    brush.spline(pts, 0.35);
  }

  // Creases where the charcoal mass breaks up into soft pastel slate / lavender / peach
  let creases = opts.creases || 3;
  for (let c = 0; c < creases; c++) {
    let u = lerpNum(0.18, 0.82, (c + 0.5) / creases) + random(-0.06, 0.06);
    let r = lerpNum(r1, r2, u);
    let cx = lerpNum(p1[0], p2[0], u);
    let cy = lerpNum(p1[1], p2[1], u);
    let sStart = random(-0.75, -0.15);
    let sEnd = sStart + random(0.45, 0.95);
    let arch = random(-0.22, 0.22) * r;

    let pA = [cx + nx * sStart * r, cy + ny * sStart * r];
    let pM = [
      cx + nx * ((sStart + sEnd) * 0.5) * r + ux * arch,
      cy + ny * ((sStart + sEnd) * 0.5) * r + uy * arch
    ];
    let pB = [cx + nx * sEnd * r, cy + ny * sEnd * r];

    // Dark crease trough
    brush.set("2B", "#050408", 0.75);
    brush.spline([pA, pM, pB], 0.4);

    // Pastel highlight ridge catching light along the crease edge
    let cCol = opts.warmBounce && c === creases - 1
      ? mixHex("#6e5850", "#9c7c6f", random(0.2, 0.85))
      : mixHex("#4f4b61", "#7d7794", random(0.2, 0.85));

    let off = 2.2;
    brush.set("cpencil", cCol, random(0.42, 0.72));
    brush.spline([
      [pA[0] - ux * off, pA[1] - uy * off, 0.3],
      [pM[0] - ux * off, pM[1] - uy * off, 0.95],
      [pB[0] - ux * off, pB[1] - uy * off, 0.3]
    ], 0.4);
  }

  // Tailored glove seam line along the finger
  if (opts.seam) {
    let sSeam = opts.seamSide || -0.55;
    let seamPts = [];
    for (let i = 1; i <= 7; i++) {
      let u = i / 8;
      let r = lerpNum(r1, r2, u);
      seamPts.push([
        lerpNum(p1[0], p2[0], u) + nx * sSeam * r,
        lerpNum(p1[1], p2[1], u) + ny * sSeam * r,
        0.5 + 0.4 * sin(u * 180)
      ]);
    }
    brush.set("2H", "#464254", 0.42);
    brush.spline(seamPts, 0.25);
  }
}

function drawGloveCreaseCluster(cx, cy, angle, span, count, warm = false) {
  resetBrushState();
  for (let i = 0; i < count; i++) {
    let t = (i / Math.max(1, count - 1)) - 0.5;
    let a = angle + t * 28 + random(-5, 5);
    let rad = span * (0.65 + 0.35 * (1 - Math.abs(t)));
    let nx = -sin(a);
    let ny = cos(a);
    let ox = cx + nx * t * span * 0.55;
    let oy = cy + ny * t * span * 0.55;

    let p1 = [ox - cos(a) * rad * 0.5, oy - sin(a) * rad * 0.5, 0.2];
    let p2 = [ox + nx * random(-7, 7), oy + ny * random(-7, 7), 1.0];
    let p3 = [ox + cos(a) * rad * 0.5, oy + sin(a) * rad * 0.5, 0.2];

    // Deep charcoal fold shadow
    brush.set("charcoal", "#050407", 0.7);
    brush.spline([p1, p2, p3], 0.45);

    // Breaking charcoal mass: pale pastel slate / lavender or warm peach-grey crease
    let hCol = warm
      ? mixHex("#6b564e", "#a8877a", random(0.15, 0.9))
      : mixHex("#4c495e", "#87819e", random(0.15, 0.9));
    brush.set("cpencil", hCol, random(0.38, 0.68));
    brush.spline([
      [p1[0] + nx * 2.2, p1[1] + ny * 2.2, 0.2],
      [p2[0] + nx * 2.5, p2[1] + ny * 2.5, 0.95],
      [p3[0] + nx * 2.2, p3[1] + ny * 2.2, 0.2]
    ], 0.45);
  }
}

