    creases: 4,
    rimSide: 1,
    rimCol: "#3a364a"
  });
  drawGloveSegment([985, 518], 58, [865, 488], 50, {
    creases: 4,
    rimSide: 1,
    rimCol: "#4a4559",
    warmBounce: true
  });

  // Curled lower fingers (Pinky & Ring) of Glove 3 in the right void
  drawGloveSegment([895, 535], 19, [832, 552], 15, { creases: 2, seam: true });
  drawGloveSegment([832, 552], 15, [788, 568], 12, { creases: 2, warmBounce: true });

  drawGloveSegment([882, 508], 21, [812, 512], 17, { creases: 2, seam: true });
  drawGloveSegment([812, 512], 17, [762, 526], 14, { creases: 2, warmBounce: true });

  // Proximal segments of Glove 3's Middle, Index & Thumb
  drawGloveSegment([868, 475], 22, [795, 442], 18, {
    creases: 3,
    seam: true,
    warmBounce: true
  });
  drawGloveSegment([855, 442], 23, [758, 355], 18, {
    creases: 3,
    seam: true,
    rimSide: 1,
    rimCol: "#58526b",
    warmBounce: true
  });
  drawGloveSegment([880, 542], 28, [790, 578], 23, {
    creases: 3,
    seam: true,
    warmBounce: true
  });

  drawGloveCreaseCluster(980, 518, 105, 70, 5, false);
  drawGloveCreaseCluster(872, 495, 115, 62, 6, true);
}

// ============================================================================
// STAGE 3: HYPERREAL JOINTED WOODEN MANNEQUIN HAND
