// Renders a soft cast shadow polygon on a wooden surface
function drawWoodCastShadow(pts, darkness = 0.65) {
  resetBrushState();
  brush.wash(mixHex("#8c5e47", "#2b180f", darkness), 150);
  drawShapePoly(pts, 0.2);
  brush.noWash();

  brush.fill(mixHex("#70432e", "#1f100a", darkness), 95);
  brush.fillBleed(0.18, "out");
  brush.fillTexture(0.45, 0.3);
  drawShapePoly(pts, 0.2);
  brush.noFill();
}

// Renders a metallic axle pin recessed into a wooden joint
function drawMetalJointPin(x, y, rx, ry, angleDeg, isBrass = false) {
  resetBrushState();
  let steps = 16;
  let ca = cos(angleDeg);
  let sa = sin(angleDeg);

  const ellPt = (cx, cy, a, b, deg) => {
    let px = cos(deg) * a;
    let py = sin(deg) * b;
    return [cx + px * ca - py * sa, cy + px * sa + py * ca];
  };

  // 1. Dark recessed wooden borehole ring
  let holePts = [];
  for (let i = 0; i < steps; i++) {
    holePts.push(ellPt(x, y, rx * 1.32, ry * 1.32, (i / steps) * 360));
  }
  brush.wash("#21120a", 235);
  drawShapePoly(holePts, 0.15);

  // 2. Metallic pin body (cool pastel slate-silver or muted antique brass)
  let pinPts = [];
  for (let i = 0; i < steps; i++) {
    pinPts.push(ellPt(x + 0.6, y + 0.6, rx * 0.95, ry * 0.95, (i / steps) * 360));
  }
  brush.wash(isBrass ? "#8f7a56" : "#6c7a82", 245);
  drawShapePoly(pinPts, 0.15);

  // 3. Lit upper-left metallic bevel crescent
  let litPts = [];
  for (let i = 0; i <= 10; i++) {
    let deg = -155 + (i / 10) * 140;
    litPts.push(ellPt(x + 0.4, y + 0.4, rx * 0.85, ry * 0.85, deg));
  }
  for (let i = 10; i >= 0; i--) {
    let deg = -155 + (i / 10) * 140;
    litPts.push(ellPt(x + 0.9, y + 0.9, rx * 0.35, ry * 0.35, deg));
  }
  brush.wash(isBrass ? "#dec8a2" : "#cad6de", 230);
  drawShapePoly(litPts, 0.12);
  brush.noWash();

  // 4. Micro-crevice rim line & sharp white specular glint
  brush.set("rotring", "#1a0d06", 0.45);
  let rimCurve = [];
  for (let i = 0; i <= 12; i++) {
    let p = ellPt(x, y, rx * 1.25, ry * 1.25, -170 + (i / 12) * 210);
    rimCurve.push([p[0], p[1], 0.7]);
  }
  brush.spline(rimCurve, 0.25);

  // Specular glint on pin head and wood borehole rim
  let glintP1 = ellPt(x, y, rx * 0.65, ry * 0.65, -135);
  let glintP2 = ellPt(x, y, rx * 0.65, ry * 0.65, -75);
  brush.set("cpencil", "#ffffff", 0.55);
  brush.line(glintP1[0], glintP1[1], glintP2[0], glintP2[1]);
}

// Renders a 3D turned wooden ball joint with beech grain, worn varnish & pin
function drawWoodenBallJoint(cx, cy, r, opts = {}) {
  resetBrushState();

  // 1. Dark carved socket recess around the ball
  if (!opts.noSocket) {
    let sockPts = [];
    let nS = 24;
    for (let i = 0; i < nS; i++) {
      let a = (i / nS) * 360;
      let sr = r * 1.07;
      sockPts.push([cx + cos(a) * sr, cy + sin(a) * sr]);
    }
    brush.wash("#2a170e", 220);
    drawShapePoly(sockPts, 0.15);
    brush.noWash();
  }

  // 2. Concentric 3D-lit wash layers shifted toward the upper-left light source
  const bands = 8;
  for (let b = 0; b < bands; b++) {
    let t = b / (bands - 1); // 0 = outer shadow rim, 1 = bright highlight core
    let rad = r * lerpNum(1.0, 0.18, t);
    let offX = lerpNum(0, -r * 0.36, t);
    let offY = lerpNum(0, -r * 0.32, t);

    // Sample 3D sphere normal at this band
    let sx = lerpNum(0.55, -0.45, t);
    let sy = lerpNum(0.50, -0.40, t);
    let sz = Math.sqrt(Math.max(0.05, 1 - sx * sx - sy * sy));
    let n3 = normalize3([sx, sy, sz]);
    let diff = dot3(n3, LIGHT_DIR);
    let bnc = dot3(n3, BOUNCE_DIR);
    let sp = Math.pow(Math.max(0, dot3(n3, HALF_VEC)), 24);
    let col = woodColorAt(diff, bnc, sp * 0.5);

    let pts = [];
    let steps = 22;
    for (let i = 0; i < steps; i++) {
      let a = (i / steps) * 360;
      pts.push([cx + offX + cos(a) * rad, cy + offY + sin(a) * rad]);
    }
    brush.wash(col, 245);
    drawShapePoly(pts, 0.18);
  }
  brush.noWash();

  // 3. Pale pastel watercolor wash on the halftone/shadow crescent (dusty rose & honey ochre)
  let wcPts = [];
  for (let i = 0; i <= 12; i++) {
    let a = -35 + (i / 12) * 195;
    wcPts.push([cx + cos(a) * r * 0.96, cy + sin(a) * r * 0.96]);
  }
  for (let i = 12; i >= 0; i--) {
    let a = -35 + (i / 12) * 195;
    wcPts.push([cx - r * 0.12 + cos(a) * r * 0.42, cy - r * 0.10 + sin(a) * r * 0.42]);
  }
  brush.fill(opts.blushCol || "#d49689", 72);
  brush.fillBleed(0.16, "in");
  brush.fillTexture(0.5, 0.35);
  drawShapePoly(wcPts, 0.18);
  brush.noFill();

  // 4. Curved meridian beech wood grain lines wrapping over the sphere
  let gAngle = opts.grainAngle || -75;
  let ux = cos(gAngle);
  let uy = sin(gAngle);
  let nx = -uy;
  let ny = ux;

  let nGrain = Math.max(6, Math.floor(r * 0.42));
  for (let g = 0; g < nGrain; g++) {
    let s = lerpNum(-0.82, 0.82, g / (nGrain - 1));
    let curvePts = [];
    for (let k = 0; k <= 6; k++) {
      let u = lerpNum(-0.82, 0.82, k / 6) * Math.sqrt(Math.max(0, 1 - s * s * 0.85));
      let bow = Math.cos((k / 6 - 0.5) * Math.PI) * s * r * 0.25;
      let px = cx + ux * u * r + nx * (s * r * 0.82 + bow);
      let py = cy + uy * u * r + ny * (s * r * 0.82 + bow);
      curvePts.push([px, py, 0.35 + 0.5 * Math.sin((k / 6) * Math.PI)]);
    }
    let gCol = s < -0.15 ? "#b88768" : (s < 0.35 ? "#875338" : "#54301e");
    brush.set("cpencil", gCol, 0.38);
    brush.spline(curvePts, 0.35);
  }

  // 5. Spherical cross-contour pencil shading on the core shadow crescent
  let nShade = Math.max(8, Math.floor(r * 0.55));
  for (let i = 0; i < nShade; i++) {
    let a1 = random(-25, 45);
    let a2 = a1 + random(55, 115);
    let rad = r * random(0.58, 0.95);
    let pts = [];
    for (let k = 0; k <= 4; k++) {
      let a = lerpNum(a1, a2, k / 4);
      pts.push([cx + cos(a) * rad, cy + sin(a) * rad, 0.3 + 0.6 * sin((k / 4) * 180)]);
    }
    brush.set(i % 2 === 0 ? "cpencil" : "2B", i % 3 === 0 ? "#472718" : "#73442e", 0.42);
    brush.spline(pts, 0.35);
  }

  // 6. Beech wood pores (tiny dark flecks)
  let nPores = Math.floor(r * 0.85);
  for (let i = 0; i < nPores; i++) {
    let a = random(360);
    let d = random(0.15, 0.88) * r;
    let px = cx + cos(a) * d;
    let py = cy + sin(a) * d;
    let plen = random(2.2, 4.8);
    brush.set("beech_pore", "#5e341f", random(0.4, 0.75));
    brush.line(px, py, px + ux * plen, py + uy * plen);
  }

  // 7. Worn varnish halo, raw-wood scuffs & glossy knuckle wear
  let hx = cx - r * 0.34;
  let hy = cy - r * 0.30;

  // Matte raw-wood wear ring where varnish has rubbed thin around the knuckle crown
  for (let i = 0; i < 9; i++) {
    let a = -165 + i * 16 + random(-5, 5);
    let rIn = r * random(0.28, 0.44);
    let rOut = rIn + random(3.5, 7.5);
    brush.set("cpencil", i % 2 === 0 ? "#f5e7d6" : "#dec2a6", 0.48);
    brush.line(
      cx + cos(a) * rIn,
      cy + sin(a) * rIn,
      cx + cos(a) * rOut,
      cy + sin(a) * rOut
    );
  }

  // Glossy specular knuckle highlight crescent
  let specPts = [];
  for (let i = 0; i <= 6; i++) {
    let a = -155 + (i / 6) * 75;
    let sr = r * 0.56;
    specPts.push([cx + cos(a) * sr, cy + sin(a) * sr, 0.4 + 0.8 * sin((i / 6) * 180)]);
  }
  brush.set("cpencil", "#fffdf9", 0.85);
  brush.spline(specPts, 0.4);

  // Pinpoint bright white varnish reflection dot
  brush.set("rotring", "#ffffff", 0.75);
  brush.line(hx - 2.2, hy + 1.5, hx + 2.5, hy - 1.5);

  // 8. Carved hinge slot shadow on the sphere if slotted
  if (opts.slotAngle !== undefined) {
    let sa = opts.slotAngle;
    let sux = cos(sa);
    let suy = sin(sa);
    let snx = -suy;
    let sny = sux;
    let sw = r * 0.24;
    let slotPoly = [
      [cx + sux * r * 0.25 - snx * sw, cy + suy * r * 0.25 - sny * sw],
      [cx + sux * r * 0.96 - snx * sw * 0.85, cy + suy * r * 0.96 - sny * sw * 0.85],
      [cx + sux * r * 0.96 + snx * sw * 0.85, cy + suy * r * 0.96 + sny * sw * 0.85],
      [cx + sux * r * 0.25 + snx * sw, cy + suy * r * 0.25 + sny * sw]
    ];
    brush.wash("#24130b", 215);
    drawShapePoly(slotPoly, 0.1);
    brush.noWash();

    // Lit wooden lip next to the carved slot
    brush.set("cpencil", "#f7ead9", 0.5);
    brush.line(
      cx + sux * r * 0.28 - snx * (sw + 1.8),
      cy + suy * r * 0.28 - sny * (sw + 1.8),
      cx + sux * r * 0.92 - snx * (sw + 1.5),
      cy + suy * r * 0.92 - sny * (sw + 1.5)
    );
  }

  // 9. Metal joint axle pin
  if (opts.pin) {
    let px = cx + (opts.pinOffset ? opts.pinOffset[0] : r * 0.22);
    let py = cy + (opts.pinOffset ? opts.pinOffset[1] : r * 0.08);
    drawMetalJointPin(
      px,
      py,
      opts.pinRx || r * 0.22,
      opts.pinRy || r * 0.16,
      opts.pinAngle || -20,
      opts.isBrass || false
    );
  }
}

// Renders a 3D turned wooden cylindrical/tapered phalanx or forearm segment
function drawWoodenSegment(p1, r1, p2, r2, opts = {}) {
  resetBrushState();
  let dx = p2[0] - p1[0];
  let dy = p2[1] - p1[1];
  let L = Math.hypot(dx, dy) || 1;
  let ux = dx / L;
  let uy = dy / L;
  let nx = -uy;
  let ny = ux;

  const swellAmt = opts.swell !== undefined ? opts.swell : 0.065;
  const radiusAt = (u) => lerpNum(r1, r2, u) * (1 + Math.sin(u * Math.PI) * swellAmt);

  // Helper to get point on segment at longitudinal u in [0,1] and transverse s in [-1,1]
  const ptAt = (u, s) => {
    let r = radiusAt(u);
    let endCurve = (u < 0.5 ? -1 : 1) * (1 - s * s) * Math.min(r * 0.24, 9);
    let cx = lerpNum(p1[0], p2[0], u) + ux * (u === 0 || u === 1 ? endCurve : 0);
    let cy = lerpNum(p1[1], p2[1], u) + uy * (u === 0 || u === 1 ? endCurve : 0);
    return [cx + nx * s * r, cy + ny * s * r];
  };

  // 1. Multi-band 3D shaded opaque wash across the cylinder width
  const nBands = 10;
  let specS = -0.35;
  let maxSpec = -1;

  for (let b = 0; b < nBands; b++) {
    let s0 = lerpNum(-1.0, 1.0, b / nBands);
    let s1 = lerpNum(-1.0, 1.0, (b + 1) / nBands);
    let sMid = (s0 + s1) * 0.5;

    let nz = Math.sqrt(Math.max(0.02, 1 - sMid * sMid));
    let n3 = normalize3([sMid * nx, sMid * ny, nz]);
    let diff = dot3(n3, LIGHT_DIR);
    let bnc = dot3(n3, BOUNCE_DIR);
    let sp = Math.pow(Math.max(0, dot3(n3, HALF_VEC)), 26);

    if (sp > maxSpec) {
      maxSpec = sp;
      specS = sMid;
    }

    let col = woodColorAt(diff, bnc, sp * 0.65);

    let bandPoly = [];
    let uSteps = 10;
    for (let i = 0; i <= uSteps; i++) {
      let u = i / uSteps;
      let r = radiusAt(u);
      let cap0 = (1 - s0 * s0) * Math.min(r * 0.25, 10) * (1 - 2 * u);
      bandPoly.push([
        lerpNum(p1[0], p2[0], u) + nx * s0 * r - ux * cap0 * (i === 0 || i === uSteps ? 1 : 0),
        lerpNum(p1[1], p2[1], u) + ny * s0 * r - uy * cap0 * (i === 0 || i === uSteps ? 1 : 0)
      ]);
    }
    for (let i = uSteps; i >= 0; i--) {
      let u = i / uSteps;
      let r = radiusAt(u);
      let cap1 = (1 - s1 * s1) * Math.min(r * 0.25, 10) * (1 - 2 * u);
      bandPoly.push([
        lerpNum(p1[0], p2[0], u) + nx * s1 * r - ux * cap1 * (i === 0 || i === uSteps ? 1 : 0),
        lerpNum(p1[1], p2[1], u) + ny * s1 * r - uy * cap1 * (i === 0 || i === uSteps ? 1 : 0)
      ]);
    }

    brush.wash(col, 248);
    drawShapePoly(bandPoly, 0.08);
  }

  // If this is a rounded fingertip (distal phalanx), draw the dome tip cap
  if (opts.isTip) {
    let tipBands = 6;
    for (let b = 0; b < tipBands; b++) {
      let t = b / (tipBands - 1);
      let rad = r2 * lerpNum(0.98, 0.22, t);
      let cx = p2[0] + ux * r2 * lerpNum(0.15, 0.55, t) - nx * r2 * 0.18 * t;
      let cy = p2[1] + uy * r2 * lerpNum(0.15, 0.55, t) - ny * r2 * 0.18 * t;
      let col = mixHex("#d6a089", "#fbf3e8", t);
      let domePts = [];
      for (let i = 0; i <= 14; i++) {
        let a = -90 + (i / 14) * 180;
        let ca = cos(a);
        let sa = sin(a);
        domePts.push([
          cx + nx * sa * rad + ux * ca * rad * 0.92,
          cy + ny * sa * rad + uy * ca * rad * 0.92
        ]);
      }
      brush.wash(col, 240);
      drawShapePoly(domePts, 0.15);
    }
  }
  brush.noWash();

  // 2. Pale pastel watercolor washes (soft apricot, honey ochre, dusty rose)
  let wcShadow = [];
  for (let i = 0; i <= 8; i++) {
    let u = i / 8;
    wcShadow.push(ptAt(u, 0.05));
  }
  for (let i = 8; i >= 0; i--) {
    let u = i / 8;
    wcShadow.push(ptAt(u, 0.88));
  }
  brush.fill(opts.watercolorCol || "#d99e89", 68);
  brush.fillBleed(0.18, "in");
  brush.fillTexture(0.52, 0.35);
  drawShapePoly(wcShadow, 0.15);

  let wcMid = [];
  for (let i = 0; i <= 8; i++) {
    let u = lerpNum(0.08, 0.92, i / 8);
    wcMid.push(ptAt(u, -0.35));
  }
  for (let i = 8; i >= 0; i--) {
    let u = lerpNum(0.08, 0.92, i / 8);
    wcMid.push(ptAt(u, 0.38));
  }
  brush.fill("#ebb996", 52);
  brush.fillBleed(0.15, "in");
  drawShapePoly(wcMid, 0.15);
  brush.noFill();

  // 3. Carved hinge slot recesses at base and/or tip
  if (opts.baseSlot) {
    let sw = r1 * 0.32;
    let sd = Math.min(L * 0.24, r1 * 0.95);
    let sPoly = [
      [p1[0] - nx * sw, p1[1] - ny * sw],
      [p1[0] + ux * sd - nx * sw * 0.82, p1[1] + uy * sd - ny * sw * 0.82],
      [p1[0] + ux * sd + nx * sw * 0.82, p1[1] + uy * sd + ny * sw * 0.82],
      [p1[0] + nx * sw, p1[1] + ny * sw]
    ];
    brush.wash("#26150c", 215);
    drawShapePoly(sPoly, 0.12);
    brush.noWash();

    // Crisp rim highlight along the carved slot edge
    brush.set("cpencil", "#f9efe2", 0.52);
    brush.line(
      p1[0] + ux * 2 - nx * (sw + 1.8),
      p1[1] + uy * 2 - ny * (sw + 1.8),
      p1[0] + ux * sd - nx * (sw * 0.82 + 1.8),
      p1[1] + uy * sd - ny * (sw * 0.82 + 1.8)
    );
  }

  if (opts.tipSlot) {
    let sw = r2 * 0.32;
    let sd = Math.min(L * 0.24, r2 * 0.95);
    let sPoly = [
      [p2[0] - nx * sw, p2[1] - ny * sw],
      [p2[0] - ux * sd - nx * sw * 0.82, p2[1] - uy * sd - ny * sw * 0.82],
      [p2[0] - ux * sd + nx * sw * 0.82, p2[1] - uy * sd + ny * sw * 0.82],
      [p2[0] + nx * sw, p2[1] + ny * sw]
    ];
    brush.wash("#26150c", 215);
    drawShapePoly(sPoly, 0.12);
    brush.noWash();

    brush.set("cpencil", "#f9efe2", 0.52);
    brush.line(
      p2[0] - ux * 2 - nx * (sw + 1.8),
      p2[1] - uy * 2 - ny * (sw + 1.8),
      p2[0] - ux * sd - nx * (sw * 0.82 + 1.8),
      p2[1] - uy * sd - ny * (sw * 0.82 + 1.8)
    );
  }

  // 4. Longitudinal beech wood grain lines (cathedral & flowing grain)
  let nGrain = Math.max(9, Math.floor((r1 + r2) * 0.38));
  for (let g = 0; g < nGrain; g++) {
    let sBase = lerpNum(-0.90, 0.90, g / (nGrain - 1));
    let arch = (noise(p1[0] * 0.02 + g * 0.4, p1[1] * 0.02) - 0.5) * 0.26;
    let gPts = [];
    for (let k = 0; k <= 7; k++) {
      let u = lerpNum(0.03, 0.97, k / 7);
      let s = clamp01((sBase + Math.sin(u * Math.PI) * arch + 1) * 0.5) * 1.88 - 0.94;
      let pt = ptAt(u, s);
      gPts.push([pt[0], pt[1], 0.3 + 0.65 * Math.sin(u * Math.PI)]);
    }

    let nz = Math.sqrt(Math.max(0.05, 1 - sBase * sBase));
    let diff = dot3(normalize3([sBase * nx, sBase * ny, nz]), LIGHT_DIR);
    let gCol = diff > 0.35 ? "#c29272" : (diff > -0.1 ? "#8c573a" : "#522e1b");
    brush.set(g % 3 === 0 ? "2H" : "cpencil", gCol, random(0.32, 0.52));
    brush.spline(gPts, 0.32);
  }

  // If fingertip, draw delicate concentric end-grain arches at the rounded tip
  if (opts.isTip) {
    for (let k = 1; k <= 4; k++) {
      let t = k / 5;
      let arcPts = [];
      for (let i = 0; i <= 6; i++) {
        let a = -65 + (i / 6) * 130;
        let rad = r2 * (0.3 + t * 0.55);
        arcPts.push([
          p2[0] + nx * sin(a) * rad + ux * cos(a) * rad * 0.65,
          p2[1] + ny * sin(a) * rad + uy * cos(a) * rad * 0.65,
          0.5
        ]);
      }
      brush.set("cpencil", "#8a563b", 0.35);
      brush.spline(arcPts, 0.35);
    }
  }

  // 5. Beech wood ray flecks (characteristic short dark pores parallel to the grain)
  let nFlecks = Math.max(18, Math.floor((r1 + r2) * L * 0.012));
  for (let i = 0; i < nFlecks; i++) {
    let u = random(0.06, 0.94);
    let s = random(-0.88, 0.88);
    // Avoid washing out the brightest specular highlight strip
    if (Math.abs(s - specS) < 0.14 && random() < 0.7) continue;

    let p = ptAt(u, s);
    let foreshorten = Math.sqrt(Math.max(0.15, 1 - s * s));
    let flen = random(2.5, 6.8) * foreshorten;
    let fCol = s < 0 ? "#855034" : "#542e1b";
    brush.set("beech_pore", fCol, random(0.38, 0.72) * foreshorten);
    brush.line(p[0], p[1], p[0] + ux * flen, p[1] + uy * flen);
  }

  // 6. Cross-contour pencil shading & lathe turning rings wrapping around the cylinder
  let nRings = Math.max(12, Math.floor(L * 0.18));
  for (let i = 0; i < nRings; i++) {
    let u = lerpNum(0.05, 0.95, i / (nRings - 1)) + random(-0.02, 0.02);
    let r = radiusAt(u);
    // Wrap from terminator across core shadow
    let sStart = random(-0.15, 0.25);
    let sEnd = random(0.68, 0.96);
    let ringPts = [];
    for (let k = 0; k <= 4; k++) {
      let s = lerpNum(sStart, sEnd, k / 4);
      let bow = Math.sqrt(Math.max(0, 1 - s * s)) * Math.min(r * 0.22, 8);
      let cx = lerpNum(p1[0], p2[0], u) + ux * bow;
      let cy = lerpNum(p1[1], p2[1], u) + uy * bow;
      ringPts.push([cx + nx * s * r, cy + ny * s * r, 0.35 + 0.6 * sin((k / 4) * 180)]);
    }
    let shCol = i % 3 === 0 ? "#4a2919" : (i % 3 === 1 ? "#75462f" : "#6e5c63");
    brush.set(i % 2 === 0 ? "cpencil" : "2B", shCol, random(0.36, 0.56));
    brush.spline(ringPts, 0.35);
  }

  // 7. Scuffs, worn varnish edges & glossy specular highlight strip
  // Raw matte wood scuffs near the high-wear joint ends
  for (let i = 0; i < 8; i++) {
    let u = i < 4 ? random(0.06, 0.28) : random(0.72, 0.94);
    let s = specS + random(-0.26, 0.26);
    let p = ptAt(u, clamp01((s + 1) * 0.5) * 1.7 - 0.85);
    let ang = atan2(uy, ux) + random(-35, 35);
    let slen = random(4, 11);
    brush.set("cpencil", i % 2 === 0 ? "#f5e7d5" : "#d9b898", 0.45);
    brush.line(p[0], p[1], p[0] + cos(ang) * slen, p[1] + sin(ang) * slen);
  }

  // Broken glossy varnish highlight along the specular ridge
  let hSegs = 2;
  for (let h = 0; h < hSegs; h++) {
    let uA = h === 0 ? 0.12 : 0.56;
    let uB = h === 0 ? 0.46 : 0.88;
    let hPts = [];
    for (let k = 0; k <= 4; k++) {
      let u = lerpNum(uA, uB, k / 4);
      let pt = ptAt(u, specS);
      hPts.push([pt[0], pt[1], 0.4 + 0.7 * sin((k / 4) * 180)]);
    }
    brush.set("cpencil", "#fffdf9", 0.78);
    brush.spline(hPts, 0.32);
  }

  // Sharp white specular glint on the crown of the segment
  let g1 = ptAt(0.24, specS);
  let g2 = ptAt(0.38, specS);
  brush.set("rotring", "#ffffff", 0.6);
  brush.line(g1[0], g1[1], g2[0], g2[1]);

  // Crisp contour definition on both edges of the wooden cylinder
  let leftEdge = [];
  let rightEdge = [];
  for (let i = 0; i <= 8; i++) {
    let u = i / 8;
    let pL = ptAt(u, -0.98);
    let pR = ptAt(u, 0.98);
    leftEdge.push([pL[0], pL[1], 0.5]);
    rightEdge.push([pR[0], pR[1], 0.6]);
  }
  brush.set("2H", "#c99b7a", 0.42);
  brush.spline(leftEdge, 0.25);
  brush.set("2B", "#3d2214", 0.52);
  brush.spline(rightEdge, 0.25);
}

// Renders the complex sculpted 3D wooden Metacarpal Palm Block
function renderWoodenPalmBlock() {
  resetBrushState();

  // Outer sculpted contour of the wooden palm block
  const palmLeft = [
    [522, 706],
    [510, 668],
    [506, 615],
    [512, 562],
    [520, 518]
  ];
  const palmTop = [
    [520, 518],
    [555, 504],
    [592, 500],
    [645, 514],
    [708, 548]
  ];
  const palmRight = [
    [708, 548],
    [714, 598],
    [702, 650],
    [676, 695],
    [638, 726]
  ];
  const palmBottom = [
    [638, 726],
    [605, 712],
    [572, 704],
    [545, 704],
    [522, 706]
  ];

  // Helper to evaluate bilinear coordinates (u across width [0..1], v bottom-to-top [0..1])
  const palmPt = (u, v) => {
    let idx = v * 4;
    let i0 = Math.min(3, Math.floor(idx));
    let f = idx - i0;
    let pL = lerpPt(palmLeft[i0], palmLeft[i0 + 1], f);
    let pR = lerpPt(palmRight[4 - i0], palmRight[3 - i0], f);
    // Arch across the palm
    let archY = -Math.sin(u * Math.PI) * lerpNum(8, 22, v);
    return [lerpNum(pL[0], pR[0], u), lerpNum(pL[1], pR[1], u) + archY];
  };

  // 1. Multi-strip 3D shaded wash across the sculpted palm block
  const strips = 12;
  for (let s = 0; s < strips; s++) {
    let u0 = s / strips;
    let u1 = (s + 1) / strips;
    let uMid = (u0 + u1) * 0.5;

    // 3D normal across the sculpted palmar block (convex left/top, bevelled right)
    let sx = lerpNum(-0.62, 0.86, uMid);
    let sy = -0.18;
    let sz = Math.sqrt(Math.max(0.05, 1 - sx * sx - sy * sy));
    let n3 = normalize3([sx, sy, sz]);
    let diff = dot3(n3, LIGHT_DIR);
    let bnc = dot3(n3, BOUNCE_DIR);
    let sp = Math.pow(Math.max(0, dot3(n3, HALF_VEC)), 22);
    let col = woodColorAt(diff, bnc, sp * 0.45);

    let poly = [];
    for (let k = 0; k <= 8; k++) {
      poly.push(palmPt(u0, k / 8));
    }
    for (let k = 8; k >= 0; k--) {
      poly.push(palmPt(u1, k / 8));
    }
    brush.wash(col, 250);
    drawShapePoly(poly, 0.12);
  }
  brush.noWash();

  // 2. Pale pastel watercolor washes on the palmar hollow, right bevel & wrist collar
  // Central palmar hollow (soft dusty rose & peach)
  let hollowPts = [
    palmPt(0.24, 0.32),
    palmPt(0.45, 0.68),
    palmPt(0.75, 0.65),
    palmPt(0.78, 0.28),
    palmPt(0.50, 0.20)
  ];
  brush.fill("#d69a8d", 75);
  brush.fillBleed(0.22, "in");
  brush.fillTexture(0.58, 0.4);
  drawShapePoly(hollowPts, 0.25);

  // Right hypothenar shadow bevel wash (warm honey-umber & pastel slate)
  let bevelPts = [
    palmPt(0.68, 0.05),
    palmPt(0.66, 0.55),
    palmPt(0.68, 0.95),
    palmPt(0.98, 0.95),
    palmPt(0.98, 0.50),
    palmPt(0.98, 0.05)
  ];
  brush.fill("#a86e58", 82);
  brush.fillBleed(0.2, "in");
  drawShapePoly(bevelPts, 0.18);

  // Warm apricot wash across upper knuckle swell
  let swellPts = [
    palmPt(0.08, 0.68),
    palmPt(0.08, 0.96),
    palmPt(0.68, 0.96),
    palmPt(0.65, 0.65)
  ];
  brush.fill("#f0c5a5", 58);
  brush.fillBleed(0.18, "in");
  drawShapePoly(swellPts, 0.2);
  brush.noFill();

  // 3. Dry pastel mass on the bright upper-left palmar ridge
  let litRidge = [
    palmPt(0.06, 0.45),
    palmPt(0.06, 0.92),
    palmPt(0.42, 0.92),
    palmPt(0.36, 0.42)
  ];
  brush.mass("cpencil", "#fbf2e6", { precision: 0.7, strength: 0.35, outline: false });
  drawShapePoly(litRidge, 0.2);
  brush.noMass();

  // 4. Sculpted bevel ridge line & palmar crease planes
  // Subtle machined plane break on the right side (hypothenar bevel)
  let bevelLine = [];
  for (let k = 0; k <= 8; k++) {
    let v = k / 8;
    let p = palmPt(0.72 - 0.05 * Math.sin(v * Math.PI), v);
    bevelLine.push([p[0], p[1], 0.3 + 0.6 * Math.sin(v * Math.PI)]);
  }
  brush.set("cpencil", "#8c573c", 0.55);
  brush.spline(bevelLine, 0.35);

  // Carved lower wrist socket shadow at bottom of palm block
  let wristCollar = [
    palmPt(0.08, 0.0),
    palmPt(0.25, 0.11),
    palmPt(0.55, 0.13),
    palmPt(0.82, 0.09),
    palmPt(0.94, 0.0),
    palmPt(0.50, -0.02)
  ];
  brush.wash("#361e12", 195);
  drawShapePoly(wristCollar, 0.2);
  brush.noWash();

  // 5. Cathedral arch beech wood grain lines flowing up the sculpted palm block
  const nCathedral = 24;
  for (let g = 0; g < nCathedral; g++) {
    let uBase = lerpNum(0.04, 0.96, g / (nCathedral - 1));
    // Create nested parabolic/cathedral wood grain arches centered around u = 0.38
    let dCenter = uBase - 0.38;
    let gPts = [];
    for (let k = 0; k <= 10; k++) {
      let v = lerpNum(0.03, 0.97, k / 10);
      let pinch = Math.sin(v * Math.PI) * dCenter * 0.18;
      let waviness = (noise(g * 0.35, v * 2.2) - 0.5) * 0.035;
      let u = clamp01(uBase - pinch + waviness);
      let p = palmPt(u, v);
      gPts.push([p[0], p[1], 0.35 + 0.65 * Math.sin(v * Math.PI)]);
    }
    let gCol = uBase < 0.35 ? "#c29170" : (uBase < 0.68 ? "#8c5639" : "#4f2c1a");
    brush.set(g % 3 === 0 ? "2H" : "cpencil", gCol, random(0.34, 0.55));
    brush.spline(gPts, 0.35);
  }

  // Inner cathedral arch loops in the upper-center of the palm block
  for (let loop = 0; loop < 5; loop++) {
    let w = 0.05 + loop * 0.042;
    let vTop = 0.86 - loop * 0.075;
    let archPts = [];
    for (let i = 0; i <= 10; i++) {
      let t = (i / 10) * 2 - 1; // -1 to 1
      let u = 0.38 + t * w;
      let v = lerpNum(0.12 + loop * 0.04, vTop, 1 - t * t);
      let p = palmPt(u, v);
      archPts.push([p[0], p[1], 0.3 + 0.6 * (1 - Math.abs(t))]);
    }
    brush.set("cpencil", "#965e40", 0.42);
    brush.spline(archPts, 0.4);
  }

  // 6. Hundreds of tiny dark beech wood ray flecks scattered across the palm
  for (let i = 0; i < 190; i++) {
    let u = random(0.04, 0.95);
    let v = random(0.06, 0.94);
    let p = palmPt(u, v);
    let pUp = palmPt(u, Math.min(1, v + 0.035));
    let dx = pUp[0] - p[0];
    let dy = pUp[1] - p[1];
    let m = Math.hypot(dx, dy) || 1;
    let flen = random(3.0, 7.5) * (1 - 0.35 * Math.abs(u - 0.45));
    let fCol = u < 0.35 ? "#8c5436" : (u < 0.72 ? "#693b22" : "#422313");
    brush.set("beech_pore", fCol, random(0.4, 0.78));
    brush.line(p[0], p[1], p[0] + (dx / m) * flen, p[1] + (dy / m) * flen);
  }

  // 7. Cross-contour pencil shading across the palmar hollow & right bevel
  for (let i = 0; i < 34; i++) {
    let v = lerpNum(0.06, 0.94, i / 33);
    let uStart = random(0.38, 0.58);
    let uEnd = random(0.82, 0.98);
    let cPts = [];
    for (let k = 0; k <= 4; k++) {
      let u = lerpNum(uStart, uEnd, k / 4);
      let p = palmPt(u, v);
      cPts.push([p[0], p[1] + Math.sin((k / 4) * Math.PI) * 5, 0.35 + 0.6 * sin((k / 4) * 180)]);
    }
    brush.set(i % 2 === 0 ? "cpencil" : "2B", i % 3 === 0 ? "#472717" : "#784830", 0.44);
    brush.spline(cPts, 0.35);
  }

  // 8. Four carved U-shaped knuckle hinge slots along the top ridge of the palm
  const knuckleSlots = [
    { x: 535, y: 520, w: 19, h: 22, ang: -12 },
    { x: 592, y: 510, w: 20, h: 24, ang: -3 },
    { x: 648, y: 525, w: 19, h: 22, ang: 10 },
    { x: 696, y: 552, w: 17, h: 20, ang: 22 }
  ];
  for (let ks of knuckleSlots) {
    let ca = cos(ks.ang);
    let sa = sin(ks.ang);
    const rotP = (lx, ly) => [ks.x + lx * ca - ly * sa, ks.y + lx * sa + ly * ca];
    let uPoly = [
      rotP(-ks.w, -ks.h * 0.45),
      rotP(-ks.w * 0.88, ks.h * 0.65),
      rotP(0, ks.h * 0.85),
      rotP(ks.w * 0.88, ks.h * 0.65),
      rotP(ks.w, -ks.h * 0.45)
    ];
    brush.wash("#22120a", 230);
    drawShapePoly(uPoly, 0.18);
    brush.noWash();

    // Bright bevel lip around the left/bottom of the carved U-slot
    let lip1 = rotP(-ks.w - 2.2, -ks.h * 0.3);
    let lip2 = rotP(-ks.w * 0.9, ks.h * 0.78);
    let lip3 = rotP(ks.w * 0.5, ks.h * 0.88);
    brush.set("cpencil", "#fbf1e3", 0.62);
    brush.spline([[lip1[0], lip1[1], 0.4], [lip2[0], lip2[1], 1.0], [lip3[0], lip3[1], 0.3]], 0.35);
  }

  // 9. Surface scuffs, worn varnish marks & glossy ridge highlights on the palm
  for (let i = 0; i < 18; i++) {
    let u = random(0.12, 0.62);
    let v = random(0.22, 0.88);
    let p = palmPt(u, v);
    let a = random(-65, 25);
    let l = random(6, 18);
    brush.set("cpencil", i % 2 === 0 ? "#f9efe2" : "#e0be9e", random(0.38, 0.62));
    brush.line(p[0], p[1], p[0] + cos(a) * l, p[1] + sin(a) * l);
  }

  // Specular varnish sheen along the upper-left palmar swell
  for (let k = 0; k < 3; k++) {
    let u = 0.16 + k * 0.045;
    let hLine = [
      palmPt(u, 0.52),
      palmPt(u + 0.02, 0.70),
      palmPt(u + 0.05, 0.86)
    ];
    brush.set("cpencil", "#fffdf9", 0.75);
    brush.spline([
      [hLine[0][0], hLine[0][1], 0.3],
      [hLine[1][0], hLine[1][1], 1.0],
      [hLine[2][0], hLine[2][1], 0.3]
    ], 0.35);
  }
}

