// ============================================================================
// COORDINATE & GEOMETRY HELPERS
// ============================================================================

// Transform cabbage-local coordinates (u = lateral, v = longitudinal from center) to canvas (x, y)
function cabToCanvas(u, v) {
  let c = cos(CAB_ANGLE);
  let s = sin(CAB_ANGLE);
  // Subtle organic warp so the cabbage head is naturally asymmetrical
  let nU = (noise(u * 0.004 + 10, v * 0.004 + 10) - 0.5) * 16;
  let nV = (noise(u * 0.004 + 50, v * 0.004 + 50) - 0.5) * 16;
  let uu = u + nU;
  let vv = v + nV;
  return [
    CAB_CX + uu * c - vv * s,
    CAB_CY + uu * s + vv * c
  ];
}

// Inverse transform from canvas (x, y) to approximate cabbage-local (u, v)
function canvasToCab(x, y) {
  let dx = x - CAB_CX;
  let dy = y - CAB_CY;
  let c = cos(-CAB_ANGLE);
  let s = sin(-CAB_ANGLE);
  return [dx * c - dy * s, dx * s + dy * c];
}

// Radius of the cabbage cut-face dome at local angle phi (0 = right, 90 = top crown, -90 = stem base)
function cutFaceRadiusAtAngle(phi) {
  // Flattened obovate / heart-dome shape characteristic of a halved red cabbage
  let s = sin(phi);
  let c = cos(phi);
  let r = 228;
  // Slightly wider at the upper-middle shoulders
  r += 14 * cos(2 * (phi - 15));
  // Slight indentation at the basal lobes flanking the stem (around -65 and -115 deg)
  if (s < -0.2) {
    let bottomFactor = map(s, -0.2, -1.0, 0, 1);
    r -= 18 * bottomFactor * pow(abs(c), 0.7);
  }
  // Protruding conical stem at the very bottom (-90 deg)
  let stemDist = abs(phi + 90);
  if (stemDist < 19) {
    let stemBulge = 34 * pow(cos(map(stemDist, 0, 19, 0, 90)), 1.4);
    r += stemBulge;
  }
  // Organic contour ripple
  r += (noise(cos(phi) * 1.8 + 4.2, sin(phi) * 1.8 + 7.1) - 0.5) * 12;
  return r;
}

// Point on the outer perimeter of the cut face for parameter phi (degrees)
function cutFaceBoundaryPt(phi, scaleR = 1.0) {
  let r = cutFaceRadiusAtAngle(phi) * scaleR;
  let u = r * cos(phi);
  let v = r * sin(phi);
  return cabToCanvas(u, v);
}

// Check if a canvas point (x, y) is strictly inside the inner reserve of the cut face
// (Slightly inside the outer wrapper leaves so gold leaf is 100% continuous up to the cabbage)
function inCutFaceReserve(x, y) {
  let [u, v] = canvasToCab(x, y);
  let r = sqrt(u * u + v * v);
  let phi = atan2(v, u);
  let boundR = cutFaceRadiusAtAngle(phi) * 0.88;
  return r < boundR;
}

// Helper to draw a closed shape using brush.beginShape / brush.vertex
function drawClosedShape(pts, curvature = 0.25) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

// Half-width of the central white pith/core at longitudinal position v (v in [-252, +22])
function coreHalfWidth(v) {
  if (v < -255 || v > 24) return 0;
  if (v < -195) {
    // Exposed cut stem stalk
    return map(v, -255, -195, 30, 44);
  } else if (v < -135) {
    // Bulging stem neck with leaf attachment ledges
    let t = map(v, -195, -135, 0, 180);
    return 44 + 7 * sin(t);
  } else {
    // Tapering gothic-arch internal core apex
    let t = constrain(map(v, -135, 22, 1, 0), 0, 1);
    return 44 * pow(t, 0.68);
  }
}

// ============================================================================
// 1. LAID GOLD-LEAF GROUND (FAINTLY SEAMED SQUARES OF BURNISHED OCHRE)
// ============================================================================

function drawGoldLeafGround() {
  brush.noField();
  brush.noStroke();
  brush.noHatch();

  let sqSize = 166;
  let overlap = 6;
  let cols = 9;
  let rows = 9;
  let startX = -60;
  let startY = -60;

  // Group squares by palette tone for efficient fill/wash batching
  let batches = PALETTE.goldSquares.map(() => []);
  let allSquares = [];

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      // Slight staggering and hand-laid angular/positional imperfection
      let jx = (noise(c * 0.7, r * 0.7) - 0.5) * 5;
      let jy = (noise(c * 0.7 + 20, r * 0.7 + 20) - 0.5) * 5;
      let x0 = startX + c * (sqSize - overlap) + (r % 2) * 4 + jx;
      let y0 = startY + r * (sqSize - overlap) + jy;
      let w = sqSize + (noise(c, r + 10) - 0.5) * 3;
      let h = sqSize + (noise(c + 10, r) - 0.5) * 3;

      let toneIdx = floor(noise(c * 0.85 + 3, r * 0.85 + 9) * PALETTE.goldSquares.length);
      toneIdx = constrain(toneIdx, 0, PALETTE.goldSquares.length - 1);

      // Subdivide square into a 3x3 subgrid if it’s near the cabbage cut-face reserve
      // so the interior of the cut cabbage keeps its pure ivory base
      let cx = x0 + w * 0.5;
      let cy = y0 + h * 0.5;
      let distToCab = dist(cx, cy, CAB_CX, CAB_CY);

      if (distToCab < 340) {
        let subN = 4;
        let sw = w / subN;
        let sh = h / subN;
        for (let sr = 0; sr < subN; sr++) {
          for (let sc = 0; sc < subN; sc++) {
            let sx = x0 + sc * sw;
            let sy = y0 + sr * sh;
            let scx = sx + sw * 0.5;
            let scy = sy + sh * 0.5;
            if (!inCutFaceReserve(scx, scy)) {
              batches[toneIdx].push([
                [sx - 1, sy - 1],
                [sx + sw + 1, sy - 1],
                [sx + sw + 1, sy + sh + 1],
                [sx - 1, sy + sh + 1]
              ]);
            }
          }
        }
      } else {
        batches[toneIdx].push([
          [x0, y0],
          [x0 + w, y0],
          [x0 + w, y0 + h],
          [x0, y0 + h]
        ]);
      }

      allSquares.push({ x: x0, y: y0, w, h, r, c, toneIdx });
    }
  }

  // Pass 1: Solid opaque gold-ochre washes per square batch
  for (let b = 0; b < batches.length; b++) {
    brush.wash(PALETTE.goldSquares[b], 235);
    for (let poly of batches[b]) {
      drawClosedShape(poly, 0.02);
    }
  }
  brush.noWash();

  // Pass 2: Rich mottled watercolor texture over selected gold squares for burnished depth
  brush.fillBleed(0.12, "in");
  brush.fillTexture(0.55, 0.35);
  for (let b = 0; b < batches.length; b += 2) {
    brush.fill(PALETTE.goldSquares[(b + 2) % PALETTE.goldSquares.length], 55);
    for (let i = 0; i < batches[b].length; i += 2) {
      drawClosedShape(batches[b][i], 0.05);
    }
  }
  brush.noFill();

  // Pass 3: Subtle metallic directional grain & burnishing marks inside each gold-leaf square
  for (let sq of allSquares) {
    let cx = sq.x + sq.w * 0.5;
    let cy = sq.y + sq.h * 0.5;
    if (inCutFaceReserve(cx, cy)) continue;

    // Faint metallic hatch on alternate squares
    if ((sq.r + sq.c) % 2 === 0 && dist(cx, cy, CAB_CX, CAB_CY) > 220) {
      let hatchAngle = (sq.r % 2 === 0) ? 2 : 88;
      brush.hatchStyle("2H", (sq.c % 2 === 0) ? PALETTE.goldHighlight : PALETTE.goldPatina, 0.35);
      brush.hatch(14, hatchAngle, { rand: 0.08, gradient: 0.35 });
      brush.noStroke();
      drawClosedShape([
        [sq.x + 6, sq.y + 6],
        [sq.x + sq.w - 6, sq.y + 6],
        [sq.x + sq.w - 6, sq.y + sq.h - 6],
        [sq.x + 6, sq.y + sq.h - 6]
      ], 0.02);
      brush.noHatch();
    }

    // Soft burnish streaks catching the light on the vast right gold expanse
    let nStrokes = (cx > 650) ? 5 : 3;
    for (let k = 0; k < nStrokes; k++) {
      let sy = sq.y + random(14, sq.h - 14);
      let sx1 = sq.x + random(8, sq.w * 0.45);
      let sx2 = sx1 + random(35, sq.w * 0.5);
      if (inCutFaceReserve(sx1, sy) || inCutFaceReserve(sx2, sy)) continue;
      let col = (k % 2 === 0) ? PALETTE.goldHighlight : PALETTE.goldPatina;
      brush.set("gold_burnish", col, random(0.6, 1.2));
      brush.line(sx1, sy, sx2, sy + random(-1.5, 1.5));
    }
  }

  // Pass 4: Faintly seamed gold-leaf overlap edges (bole red-ochre, dark umber tarnish & specular foil edge)
  brush.wiggle(0.8);
  for (let sq of allSquares) {
    // Horizontal seam along top of square
    drawClippedSeam(sq.x, sq.y, sq.x + sq.w, sq.y, true);
    // Secondary overlap line 4px inside (where adjacent gold leaf sheet overlaps)
    drawClippedSeam(sq.x + 3, sq.y + 4.5, sq.x + sq.w - 3, sq.y + 4.5, false);

    // Vertical seam along left of square
    drawClippedSeam(sq.x, sq.y, sq.x, sq.y + sq.h, true);
    drawClippedSeam(sq.x + 4.5, sq.y + 3, sq.x + 4.5, sq.y + sq.h - 3, false);
  }
  brush.noField();
}

function drawClippedSeam(x1, y1, x2, y2, isPrimary) {
  let steps = 8;
  for (let i = 0; i < steps; i++) {
    let t0 = i / steps;
    let t1 = (i + 1) / steps;
    let ax = lerp(x1, x2, t0);
    let ay = lerp(y1, y2, t0);
    let bx = lerp(x1, x2, t1);
    let by = lerp(y1, y2, t1);
    let mx = (ax + bx) * 0.5;
    let my = (ay + by) * 0.5;
    if (inCutFaceReserve(mx, my)) continue;

    if (isPrimary) {
      // Faint warm Armenian bole / dark ochre seam
      if (random() < 0.88) {
        brush.set("2H", PALETTE.goldSeamBole, random(0.32, 0.55));
        brush.line(ax, ay, bx, by);
      }
      // Specular metallic glint right beside the seam
      if (random() < 0.72) {
        brush.set("micro_needle", PALETTE.goldHighlight, random(0.35, 0.65));
        brush.line(ax + 1.2, ay + 1.2, bx + 1.2, by + 1.2);
      }
    } else {
      // Subtle overlapping leaf edge shadow
      if (random() < 0.65) {
        brush.set("2H", PALETTE.goldSeamDark, random(0.22, 0.38));
        brush.line(ax, ay, bx, by);
      }
    }
  }
}

// ============================================================================
// 2. CAST SHADOW & CONTACT SHADOW ON THE GOLD GROUND
// ============================================================================

function drawCabbageShadow() {
  brush.noField();
  brush.noStroke();

  // Layered soft watercolor shadow cast to the lower-right onto the gold leaf
  let shadowLayers = [
    { dx: 38, dy: 44, scale: 1.12, col: "#4a3319", alpha: 55, bleed: 0.35 },
    { dx: 26, dy: 30, scale: 1.05, col: "#1b2438", alpha: 68, bleed: 0.28 },
    { dx: 14, dy: 18, scale: 0.99, col: PALETTE.prussianAbyss, alpha: 92, bleed: 0.18 }
  ];

  for (let sl of shadowLayers) {
    let pts = [];
    for (let phi = -180; phi < 180; phi += 8) {
      let [px, py] = cutFaceBoundaryPt(phi, sl.scale);
      pts.push([px + sl.dx, py + sl.dy]);
    }
    brush.fillBleed(sl.bleed, "out");
    brush.fillTexture(0.65, 0.55);
    brush.fill(sl.col, sl.alpha);
    drawClosedShape(pts, 0.35);
  }
  brush.noFill();
}

// ============================================================================
// 3. OUTER LEAVES IN THE TARASHIKOMI WATERCOLOR MANNER
// ============================================================================

function drawTarashikomiOuterLeaves() {
  brush.noField();

  // Define 9 lush, ruffled outer cabbage leaves radiating around the halved head.
  // They flare broadly to the top-left, left, and bottom-left, and form a dramatic
  // scalloped wet edge along the right side facing the vast gold-leaf field.
  let outerLeaves = [
    // Large upper-left royal indigo & magenta leaf
    { aStart: 95, aEnd: 158, rInner: 175, rOuter: 375, baseCol: PALETTE.prussianDark, bloomCol: PALETTE.magentaBloom, thirdCol: PALETTE.cobaltViolet, waves: 5 },
    // Far-left sweeping Prussian blue & cobalt violet leaf
    { aStart: 145, aEnd: 208, rInner: 170, rOuter: 365, baseCol: PALETTE.prussianMid, bloomCol: PALETTE.cobaltVioletDeep, thirdCol: PALETTE.prussianAbyss, waves: 6 },
    // Lower-left curled leaf flanking the stem
    { aStart: 195, aEnd: 256, rInner: 165, rOuter: 350, baseCol: PALETTE.cobaltVioletDeep, bloomCol: PALETTE.prussianDark, thirdCol: PALETTE.magentaBloom, waves: 5 },
    // Stem-side basal collar leaf (bottom-right of stem)
    { aStart: 278, aEnd: 336, rInner: 168, rOuter: 325, baseCol: PALETTE.prussianDark, bloomCol: PALETTE.magentaDark, thirdCol: PALETTE.cobaltViolet, waves: 4 },
    // Right-lower dramatic scalloped tarashikomi leaf bordering the gold expanse
    { aStart: 325, aEnd: 382, rInner: 175, rOuter: 315, baseCol: PALETTE.cobaltViolet, bloomCol: PALETTE.prussianDark, thirdCol: PALETTE.magentaBloom, waves: 5 },
    // Right-upper loose wing leaf blooming into the gold field
    { aStart: 12, aEnd: 66, rInner: 175, rOuter: 310, baseCol: PALETTE.prussianMid, bloomCol: PALETTE.magentaBloom, thirdCol: PALETTE.prussianAbyss, waves: 4 },
    // Crown apical ruffled leaf (top)
    { aStart: 52, aEnd: 110, rInner: 175, rOuter: 345, baseCol: PALETTE.cobaltVioletDeep, bloomCol: PALETTE.prussianMid, thirdCol: PALETTE.magentaRose, waves: 5 },
    // Inner secondary overlapping leaf flaps for rich layered depth
    { aStart: 118, aEnd: 175, rInner: 170, rOuter: 300, baseCol: PALETTE.magentaDark, bloomCol: PALETTE.prussianAbyss, thirdCol: PALETTE.cobaltVioletBright, waves: 4 },
    { aStart: 215, aEnd: 268, rInner: 165, rOuter: 285, baseCol: PALETTE.prussianAbyss, bloomCol: PALETTE.magentaBloom, thirdCol: PALETTE.prussianCyan, waves: 4 }
  ];

  // Store generated leaf geometries and sub-pools so we can batch fills and then draw tide-lines & veins
  let leafGeoms = [];

  for (let idx = 0; idx < outerLeaves.length; idx++) {
    let lf = outerLeaves[idx];
    let mainPts = buildRuffledLeafPolygon(lf.aStart, lf.aEnd, lf.rInner, lf.rOuter, lf.waves, idx * 17);

    // Create 3 overlapping wet-in-wet tarashikomi pigment pools inside each leaf
    let aMid = (lf.aStart + lf.aEnd) * 0.5;
    let aSpan = (lf.aEnd - lf.aStart);

    let pool1 = buildRuffledLeafPolygon(
      lf.aStart + aSpan * 0.06,
      aMid + aSpan * 0.18,
      lf.rInner + 15,
      lf.rOuter * 0.93,
      lf.waves - 1,
      idx * 31 + 5
    );

    let pool2 = buildRuffledLeafPolygon(
      aMid - aSpan * 0.15,
      lf.aEnd - aSpan * 0.05,
      lf.rInner + 20,
      lf.rOuter * 0.90,
      lf.waves - 1,
      idx * 47 + 11
    );

    // Water-bloom "cauliflower" push-back pool (lighter pigment with high border intensity)
    let bloomPool = buildRuffledLeafPolygon(
      aMid - aSpan * 0.22,
      aMid + aSpan * 0.24,
      (lf.rInner + lf.rOuter) * 0.46,
      lf.rOuter * 0.84,
      3,
      idx * 61 + 19
    );

    leafGeoms.push({ lf, mainPts, pool1, pool2, bloomPool });
  }

  // Pass 1: Base wet watercolor washes for all outer leaves
  brush.noStroke();
  for (let lg of leafGeoms) {
    brush.fillBleed(0.36, "out");
    brush.fillTexture(0.88, 0.94);
    brush.fill(lg.lf.baseCol, 128);
    drawClosedShape(lg.mainPts, 0.35);
  }

  // Pass 2: Wet-in-wet tarashikomi dropped pigment pools (indigo & magenta blooming into each other)
  for (let lg of leafGeoms) {
    brush.fillBleed(0.32, "in");
    brush.fillTexture(0.92, 0.96);
    brush.fill(lg.lf.bloomCol, 138);
    drawClosedShape(lg.pool1, 0.38);

    brush.fillBleed(0.28, "out");
    brush.fillTexture(0.90, 0.95);
    brush.fill(lg.lf.thirdCol, 125);
    drawClosedShape(lg.pool2, 0.38);
  }

  // Pass 3: Luminous water-drop blooms & warm gold-ochre back-runs inside the wet leaves
  for (let i = 0; i < leafGeoms.length; i++) {
    let lg = leafGeoms[i];
    let backrunCol = (i % 3 === 0) ? PALETTE.goldBase : ((i % 2 === 0) ? PALETTE.prussianCyan : PALETTE.magentaRose);
    brush.fillBleed(0.22, "in");
    brush.fillTexture(0.94, 0.98);
    brush.fill(backrunCol, 88);
    drawClosedShape(lg.bloomPool, 0.42);
  }
  brush.noFill();

  // Pass 4: Granulated dark tide-lines (the characteristic drying meniscus of tarashikomi)
  for (let lg of leafGeoms) {
    drawGranulatedTideLine(lg.mainPts, PALETTE.prussianAbyss, 0.82);
    drawGranulatedTideLine(lg.pool1, PALETTE.violetAbyss, 0.75);
    drawGranulatedTideLine(lg.pool2, PALETTE.prussianAbyss, 0.72);
    drawGranulatedTideLine(lg.bloomPool, PALETTE.magentaDark, 0.85);
  }

  // Pass 5: Botanical leaf veins threading through the pooled watercolor outer leaves
  for (let i = 0; i < leafGeoms.length; i++) {
    drawOuterLeafVenation(leafGeoms[i].lf, i * 29);
  }

  // Pass 6: Delicate wet watercolor blooms / droplets near the outer leaf margins on the gold ground
  drawTarashikomiDroplets();
}

function buildRuffledLeafPolygon(aStart, aEnd, rInner, rOuter, numWaves, seedOff) {
  let pts = [];
  let steps = 28;

  // Inner attachment arc (tucked behind the cut face)
  for (let i = 0; i <= 8; i++) {
    let a = lerp(aStart, aEnd, i / 8);
    let r = rInner + (noise(i * 0.4 + seedOff) - 0.5) * 18;
    pts.push(cabToCanvas(r * cos(a), r * sin(a)));
  }

  // Outer scalloped / ruffled margin
  for (let i = steps; i >= 0; i--) {
    let t = i / steps;
    let a = lerp(aStart, aEnd, t);
    // Envelope tapers at start and end of leaf lobe
    let env = sin(t * 180);
    let wave = sin(t * numWaves * 360 + seedOff * 25) * 18 * env;
    let subWave = cos(t * numWaves * 720 + seedOff * 13) * 8 * env;
    let n = (noise(t * 3.5 + seedOff, seedOff * 0.1) - 0.5) * 32;
    let r = lerp(rInner + 25, rOuter, pow(env, 0.42)) + wave + subWave + n;
    pts.push(cabToCanvas(r * cos(a), r * sin(a)));
  }

  return pts;
}

function drawGranulatedTideLine(pts, col, density) {
  if (!pts || pts.length < 4) return;
  // Trace irregular segments of the polygon perimeter with the granulated tide-line brush + fine spray
  let n = pts.length;
  let chunk = [];
  for (let i = 0; i <= n; i++) {
    let p = pts[i % n];
    // Skip points hidden deep inside the cut face
    if (!inCutFaceReserve(p[0], p[1]) && random() < density) {
      chunk.push([p[0] + random(-1.2, 1.2), p[1] + random(-1.2, 1.2), random(0.4, 1.3)]);
    } else {
      if (chunk.length >= 3) {
        brush.set("tarashikomi_edge", col, random(0.65, 1.25));
        brush.spline(chunk, 0.45);
        // Subtle crisp pigment line along the darkest meniscus
        if (random() < 0.65) {
          brush.set("razor_pen", col, random(0.35, 0.65));
          brush.spline(chunk, 0.45);
        }
      }
      chunk = [];
    }
  }
  if (chunk.length >= 3) {
    brush.set("tarashikomi_edge", col, random(0.65, 1.20));
    brush.spline(chunk, 0.45);
  }

  // Add subtle spray granulation along the outer lobes
  brush.set("spray", col, 0.45);
  for (let i = 0; i < n; i += 3) {
    let p = pts[i];
    if (!inCutFaceReserve(p[0], p[1]) && random() < 0.45) {
      brush.line(p[0], p[1], p[0] + random(-6, 6), p[1] + random(-6, 6));
    }
  }
}

function drawOuterLeafVenation(lf, seedOff) {
  let aMid = (lf.aStart + lf.aEnd) * 0.5;
  let rStart = lf.rInner + 35;
  let rEnd = lf.rOuter * 0.91;

  // Main outer-leaf midrib
  let ribPts = [];
  let steps = 12;
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let r = lerp(rStart, rEnd, t);
    let a = aMid + sin(t * 180 + seedOff) * 5 + (noise(t * 2 + seedOff) - 0.5) * 6;
    let p = cabToCanvas(r * cos(a), r * sin(a));
    ribPts.push([p[0], p[1], lerp(1.3, 0.25, t)]);
  }

  // Translucent lilac-white vein highlight
  brush.set("gouache_detail", PALETTE.lilacPale, 0.95);
  brush.spline(ribPts, 0.4);
  // Crisp Prussian-blue edge along the vein
  brush.set("razor_pen", PALETTE.prussianAbyss, 0.55);
  brush.spline(ribPts, 0.4);

  // Branching lateral veins on the outer leaf
  for (let b = 1; b <= 6; b++) {
    let t0 = b / 7.2;
    let side = (b % 2 === 0) ? 1 : -1;
    let r0 = lerp(rStart, rEnd, t0);
    let a0 = aMid + sin(t0 * 180 + seedOff) * 5;
    let branchPts = [];
    for (let k = 0; k <= 6; k++) {
      let kt = k / 6;
      let br = r0 + kt * (lf.rOuter - r0) * 0.62;
      let ba = a0 + side * kt * (lf.aEnd - lf.aStart) * 0.34 + sin(kt * 140) * 3 * side;
      let bp = cabToCanvas(br * cos(ba), br * sin(ba));
      branchPts.push([bp[0], bp[1], lerp(0.85, 0.2, kt)]);
    }
    brush.set("gouache_detail", (b % 2 === 0) ? PALETTE.lilacPale : PALETTE.prussianPale, 0.62);
    brush.spline(branchPts, 0.4);
    brush.set("micro_needle", PALETTE.violetAbyss, 0.5);
    brush.spline(branchPts, 0.4);
  }
}

function drawTarashikomiDroplets() {
  // Small pooled watercolor blooms and droplets around the outer leaves
  let drops = [
    { a: 15, r: 332, rad: 9, col: PALETTE.prussianMid },
    { a: 32, r: 345, rad: 5.5, col: PALETTE.magentaBloom },
    { a: 132, r: 392, rad: 11, col: PALETTE.prussianDark },
    { a: 142, r: 405, rad: 6, col: PALETTE.cobaltViolet },
    { a: 215, r: 375, rad: 8, col: PALETTE.magentaBloom },
    { a: 348, r: 338, rad: 10, col: PALETTE.cobaltVioletDeep },
    { a: 356, r: 355, rad: 5, col: PALETTE.prussianMid }
  ];

  for (let d of drops) {
    let [dx, dy] = cabToCanvas(d.r * cos(d.a), d.r * sin(d.a));
    brush.noStroke();
    brush.fillBleed(0.22, "out");
    brush.fillTexture(0.9, 0.95);
    brush.fill(d.col, 130);
    brush.circle(dx, dy, d.rad, 0.35);
    brush.noFill();

    brush.set("tarashikomi_edge", PALETTE.prussianAbyss, 0.55);
    brush.circle(dx, dy, d.rad, 0.35);
  }
}

// ============================================================================
// 4. CUT FACE FOUNDATION — DARK CAVITIES & ANTHOCYANIN WASHES
// ============================================================================

function drawCutFaceFoundation() {
  brush.noField();
  brush.noStroke();

  // 1. Clean ivory-white base over the entire cut-face silhouette
  // (Ensures even the outer rim overlapping the gold leaf has a crisp botanical ground)
  let outerFacePts = [];
  for (let phi = -180; phi < 180; phi += 4) {
    outerFacePts.push(cutFaceBoundaryPt(phi, 1.0));
  }
  brush.wash(PALETTE.ivory, 250);
  drawClosedShape(outerFacePts, 0.25);
  brush.noWash();

  // 2. Deep Prussian-blue & velvet violet-black foundation inside the left and right hemispheres
  // (Leaving the central conical stem/pith reserve pure ivory!)
  for (let side of [-1, 1]) {
    let hemiPts = [];
    // Trace along the flank of the central core from bottom neck up to apex
    for (let v = -195; v <= 22; v += 14) {
      let cw = coreHalfWidth(v) + 5;
      hemiPts.push(cabToCanvas(side * cw, v));
    }
    // Continue up to the top crown
    hemiPts.push(cabToCanvas(side * 4, 95));
    hemiPts.push(cabToCanvas(side * 2, 205));

    // Trace around the outer dome back down to the stem neck
    let startPhi = 90 - side * 4;
    let endPhi = 90 - side * 164;
    let step = -side * 6;
    for (let phi = startPhi; side > 0 ? phi >= endPhi : phi <= endPhi; phi += step) {
      let r = cutFaceRadiusAtAngle(phi) * 0.93;
      hemiPts.push(cabToCanvas(r * cos(phi), r * sin(phi)));
    }

    // Opaque dark violet-indigo foundation wash for high contrast against the white veins
    brush.wash(PALETTE.violetAbyss, 232);
    drawClosedShape(hemiPts, 0.25);
    brush.noWash();

    // Rich Cobalt Violet & Prussian Blue wet pigment glow over the chambers
    brush.fillBleed(0.18, "in");
    brush.fillTexture(0.75, 0.80);
    brush.fill((side < 0) ? PALETTE.prussianDark : PALETTE.cobaltVioletDeep, 130);
    drawClosedShape(hemiPts, 0.25);
    brush.noFill();
  }

  // 3. Apical heart chamber foundation (above the tip of the central core)
  let heartPts = [];
  for (let a = 0; a < 360; a += 15) {
    let u = 88 * cos(a);
    let v = 108 + 82 * sin(a);
    heartPts.push(cabToCanvas(u, v));
  }
  brush.wash(PALETTE.prussianAbyss, 225);
  drawClosedShape(heartPts, 0.3);
  brush.noWash();
}

// ============================================================================
// 5. CUT FACE LABYRINTH — VEINS, ARCHING MIDRIBS, CORE & RAZOR-FINE PEN
// ============================================================================

function drawCutFaceLabyrinth() {
  brush.noField();

  // A. Outer Concentric Wrapper Leaves (4 tightly packed layers forming the cut rim)
  drawOuterWrapperRim();

  // B. Generate the Arching Primary Midrib Skeleton (7 left & 7 right ribs)
  let leftRibs = generatePrimaryRibs(-1);
  let rightRibs = generatePrimaryRibs(1);

  // C. Fill the Inter-Rib Chambers with Convoluted Labyrinthine Folds
  // (Rendered before & integrated with the main ribs so secondary veins branch seamlessly)
  for (let i = 0; i < leftRibs.length - 1; i++) {
    drawLabyrinthChamber(leftRibs[i], leftRibs[i + 1], -1, i);
  }
  for (let i = 0; i < rightRibs.length - 1; i++) {
    drawLabyrinthChamber(rightRibs[i], rightRibs[i + 1], 1, i);
  }

  // D. Basal Lobe Pockets tucked beside the stem neck
  drawBasalLobePockets(-1);
  drawBasalLobePockets(1);

  // E. The Innermost Apical Heart (tightly curled meristem scrolls above the core tip)
  drawApicalHeartLabyrinth();

  // F. Render the Bold Arching Primary Midribs & Lateral Branch Spurs
  for (let i = 0; i < leftRibs.length; i++) {
    drawPrimaryMidrib(leftRibs[i], -1, i);
  }
  for (let i = 0; i < rightRibs.length; i++) {
    drawPrimaryMidrib(rightRibs[i], 1, i);
  }

  // G. Render the Central Conical Stem & Pith Core with Botanical Precision
  drawCentralCoreAndStem();
}

// --- A. Outer Concentric Wrapper Rim ---
function drawOuterWrapperRim() {
  let numWrappers = 4;
  for (let w = 0; w < numWrappers; w++) {
    let scaleR = map(w, 0, numWrappers - 1, 0.988, 0.932);
    // Split into left and right wrapper arcs that clasp from the stem neck up over the crown
    // and interleave across the top dome
    for (let side of [-1, 1]) {
      let phiStart = -90 + side * 18;
      let phiEnd = (side > 0) ? (102 + (w % 2) * 14) : (78 - (w % 2) * 14);
      let step = side * 3.5;

      let spinePts = [];
      let outerEdge = [];
      let innerEdge = [];

      for (let phi = phiStart; side > 0 ? phi <= phiEnd : phi >= phiEnd; phi += step) {
        let t = abs(phi - phiStart) / abs(phiEnd - phiStart);
        let rBase = cutFaceRadiusAtAngle(phi) * scaleR;
        // Slight organic waviness
        let wave = (noise(phi * 0.08 + w * 7, side + 5) - 0.5) * 3.2;
        let r = rBase + wave;
        let thick = lerp(2.8, 1.3, t) * (w === 0 ? 1.15 : 0.9);

        let p = cabToCanvas(r * cos(phi), r * sin(phi));
        spinePts.push([p[0], p[1], lerp(1.1, 0.5, t)]);
        outerEdge.push(cabToCanvas((r + thick * 0.55) * cos(phi), (r + thick * 0.55) * sin(phi)));
        innerEdge.push(cabToCanvas((r - thick * 0.55) * cos(phi), (r - thick * 0.55) * sin(phi)));
      }

      // Cobalt violet & magenta halo along the wrapper leaf
      brush.set("cpencil", (w % 2 === 0) ? PALETTE.cobaltViolet : PALETTE.magentaBloom, 0.85);
      brush.spline(spinePts, 0.35);

      // Crisp white wrapper leaf section
      brush.set("gouache_white", (w === 0) ? PALETTE.ivory : PALETTE.ivoryLilac, (w === 0) ? 0.95 : 0.72);
      brush.spline(spinePts, 0.35);

      // Razor-sharp pen lines on both sides of the wrapper leaf
      brush.set("razor_pen", PALETTE.prussianAbyss, 0.65);
      brush.spline(outerEdge, 0.35);
      brush.set("razor_pen", PALETTE.violetAbyss, 0.55);
      brush.spline(innerEdge, 0.35);
    }
  }
}

// --- B. Generate Arching Primary Midribs ---
function generatePrimaryRibs(side) {
  // 7 ribs per side originating from the core flank and arching around the hemisphere
  let ribs = [];
  let numRibs = 7;

  for (let i = 0; i < numRibs; i++) {
    let f = i / (numRibs - 1); // 0 = outermost/lowest rib, 1 = innermost/highest rib
    let vAttach = lerp(-182, -8, pow(f, 0.88));
    let uAttach = side * (coreHalfWidth(vAttach) - 1);

    // Maximum lateral reach and upper arch height of this rib
    let uMax = side * lerp(206, 86, pow(f, 0.82));
    let vBottomDip = vAttach - lerp(26, 4, f);
    let vTopArch = lerp(202, 96, pow(f, 0.78)) + ((i % 2 === 0) ? 5 : -4) * side;
    // Ribs interleave past the vertical centerline at the crown
    let uTip = -side * lerp(28, 12, f) + (noise(i * 3, side + 2) - 0.5) * 14;
    let vTip = vTopArch - lerp(12, 24, f);

    let ptsUV = [];
    let steps = 32;
    for (let s = 0; s <= steps; s++) {
      let t = s / steps;
      let u, v;
      if (t < 0.28) {
        // Sweep outward and slightly downward from the core attachment into the basal shoulder
        let lt = t / 0.28;
        u = lerp(uAttach, uMax * 0.88, sin(lt * 90));
        v = lerp(vAttach, vBottomDip, sin(lt * 180)) + lt * (vAttach * 0.15);
      } else if (t < 0.75) {
        // Sweep boldly upward along the lateral dome
        let lt = (t - 0.28) / 0.47;
        let ang = lerp(-15, 72, lt);
        u = uMax * cos(ang) * lerp(0.88, 1.0, sin(lt * 180));
        v = lerp(vAttach, vTopArch, pow(lt, 0.85));
      } else {
        // Wrap over the apical crown and interleave
        let lt = (t - 0.75) / 0.25;
        u = lerp(uMax * cos(72), uTip, pow(lt, 0.9));
        v = lerp(vTopArch, vTip, lt * lt) + sin(lt * 180) * 8;
      }

      // Add subtle natural organic undulation to the midrib
      let wiggleU = (noise(t * 3.5 + i * 7, side * 10 + 3) - 0.5) * 10 * sin(t * 180);
      let wiggleV = (noise(t * 3.5 + i * 13, side * 10 + 9) - 0.5) * 10 * sin(t * 180);
      u += wiggleU;
      v += wiggleV;

      // Clamp strictly within the wrapper leaf boundary
      let phi = atan2(v, u);
      let maxR = cutFaceRadiusAtAngle(phi) * 0.91;
      let curR = sqrt(u * u + v * v);
      if (curR > maxR) {
        u *= maxR / curR;
        v *= maxR / curR;
      }

      // Thickness profile of the fleshy white midrib (thick near petiole base, tapering toward apex)
      let baseW = lerp(15.5, 7.5, f);
      let w = baseW * pow(1 - t * 0.86, 0.75) * (1 + 0.18 * sin(t * 220));

      ptsUV.push({ u, v, w, t });
    }

    ribs.push(ptsUV);
  }
  return ribs;
}

// --- C. Draw Convoluted Labyrinth Chamber Between Two Consecutive Ribs ---
function drawLabyrinthChamber(outerRib, innerRib, side, chamberIdx) {
  let n = outerRib.length;

  // 1. Add deep Prussian-blue & violet-black cross-hatching inside the chamber for velvety depth
  let chamberPoly = [];
  for (let i = 0; i < n; i += 2) {
    chamberPoly.push(cabToCanvas(outerRib[i].u, outerRib[i].v));
  }
  for (let i = n - 1; i >= 0; i -= 2) {
    chamberPoly.push(cabToCanvas(innerRib[i].u, innerRib[i].v));
  }
  brush.hatchStyle("razor_pen", (chamberIdx % 2 === 0) ? PALETTE.prussianAbyss : PALETTE.violetAbyss, 0.45);
  brush.hatch(4.5, 35 * side + chamberIdx * 22, { rand: 0.12 });
  brush.noStroke();
  drawClosedShape(chamberPoly, 0.2);
  brush.noHatch();

  // 2. Generate tightly packed serpentine / S-folded leaf blades filling the crescent chamber!
  // In a halved cabbage, the lamina between ribs folds back and forth like ribbon candy.
  let numMeanders = 2; // Two interlocking serpentine ribbon families per chamber
  for (let m = 0; m < numMeanders; m++) {
    let freq = lerp(11, 7, chamberIdx / 6) * 180; // Oscillation frequency along the chamber arch
    let phase = m * 180 + chamberIdx * 55 + (side > 0 ? 40 : 0);

    let ribbonUV = [];
    let subSteps = 88;
    for (let s = 0; s <= subSteps; s++) {
      let frac = s / subSteps;
      // Avoid overlapping the very tip or exact core attachment
      let idxFloat = constrain(frac * (n - 1), 0.5, n - 1.5);
      let i0 = floor(idxFloat);
      let i1 = min(n - 1, i0 + 1);
      let lt = idxFloat - i0;

      let uOut = lerp(outerRib[i0].u, outerRib[i1].u, lt);
      let vOut = lerp(outerRib[i0].v, outerRib[i1].v, lt);
      let wOut = lerp(outerRib[i0].w, outerRib[i1].w, lt);

      let uIn = lerp(innerRib[i0].u, innerRib[i1].u, lt);
      let vIn = lerp(innerRib[i0].v, innerRib[i1].v, lt);
      let wIn = lerp(innerRib[i0].w, innerRib[i1].w, lt);

      // Available interior span between the two bounding ribs
      let du = uOut - uIn;
      let dv = vOut - vIn;
      let span = sqrt(du * du + dv * dv);
      if (span < 4) continue;

      // Sharp hairpin wave (flattened sine wave so folds hug both walls and turn crisply)
      let rawSin = sin(frac * freq + phase + (noise(frac * 4 + chamberIdx, m * 7) - 0.5) * 90);
      let wave = 0.5 + 0.40 * (rawSin >= 0 ? pow(rawSin, 0.62) : -pow(-rawSin, 0.62));

      // Keep clear of the thick white primary rib walls
      let marginIn = constrain((wIn * 0.55 + 2.2) / span, 0.12, 0.42);
      let marginOut = constrain((wOut * 0.55 + 2.2) / span, 0.12, 0.42);
      let across = lerp(marginIn, 1.0 - marginOut, wave);

      let u = lerp(uIn, uOut, across);
      let v = lerp(vIn, vOut, across);

      // Folds are thicker at the hairpin turns (cut obliquely) and thinner on straight stretches
      let turnFactor = pow(abs(rawSin), 1.4);
      let veinWeight = lerp(0.42, 0.95, turnFactor) * lerp(1.05, 0.65, chamberIdx / 6);

      ribbonUV.push({ u, v, w: veinWeight });
    }

    drawLabyrinthVeinRibbon(ribbonUV, chamberIdx + m);
  }

  // 3. Nested C-loops & tight U-folds tucked into the pockets between the serpentine bends
  let numPockets = floor(lerp(13, 8, chamberIdx / 6));
  for (let p = 1; p < numPockets; p++) {
    let fracCenter = (p + random(-0.2, 0.2)) / numPockets;
    let idx = constrain(floor(fracCenter * (n - 1)), 1, n - 2);

    let pOut = outerRib[idx];
    let pIn = innerRib[idx];
    let span = dist(pOut.u, pOut.v, pIn.u, pIn.v);
    if (span < 12) continue;

    // Construct a tight U-shaped or S-shaped folded leaf loop inside the pocket
    let loopUV = [];
    let dir = (p % 2 === 0) ? 1 : -1;
    let tangU = (outerRib[idx + 1].u - outerRib[idx - 1].u) * 0.45;
    let tangV = (outerRib[idx + 1].v - outerRib[idx - 1].v) * 0.45;

    for (let a = -110; a <= 110; a += 22) {
      let ca = cos(a);
      let sa = sin(a);
      let across = (dir > 0)
        ? map(ca, -0.35, 1, 0.22, 0.78)
        : map(ca, -0.35, 1, 0.78, 0.22);
      let baseU = lerp(pIn.u, pOut.u, across);
      let baseV = lerp(pIn.v, pOut.v, across);
      let u = baseU + tangU * sa * 0.68;
      let v = baseV + tangV * sa * 0.68;
      let w = lerp(0.35, 0.85, pow(ca * 0.5 + 0.5, 1.2));
      loopUV.push({ u, v, w });
    }

    drawLabyrinthVeinRibbon(loopUV, chamberIdx + p);
  }
}

// Render a single labyrinthine vein ribbon with 4 hyperreal passes:
// 1) Cobalt-violet / magenta anthocyanin halo
// 2) Crisp opaque ivory-white vein core
// 3) Razor-sharp dual pen contours along both walls of the vein
// 4) Fine cellular & shadow cross-ticks in the adjacent crevice
function drawLabyrinthVeinRibbon(ptsUV, styleSeed) {
  if (!ptsUV || ptsUV.length < 3) return;

  let spinePts = [];
  let leftWall = [];
  let rightWall = [];

  for (let i = 0; i < ptsUV.length; i++) {
    let cur = ptsUV[i];
    let prev = ptsUV[max(0, i - 1)];
    let next = ptsUV[min(ptsUV.length - 1, i + 1)];

    let du = next.u - prev.u;
    let dv = next.v - prev.v;
    let len = sqrt(du * du + dv * dv) || 1;
    let nu = -dv / len;
    let nv = du / len;

    let halfW = cur.w * 2.1;
    let pCenter = cabToCanvas(cur.u, cur.v);
    let pLeft = cabToCanvas(cur.u + nu * halfW, cur.v + nv * halfW);
    let pRight = cabToCanvas(cur.u - nu * halfW, cur.v - nv * halfW);

    spinePts.push([pCenter[0], pCenter[1], cur.w]);
    leftWall.push([pLeft[0], pLeft[1], 0.75]);
    rightWall.push([pRight[0], pRight[1], 0.75]);
  }

  // Pass 1: Glowing Cobalt Violet / Magenta anthocyanin transition rim
  let haloCol = (styleSeed % 3 === 0)
    ? PALETTE.magentaBloom
    : ((styleSeed % 2 === 0) ? PALETTE.cobaltVioletBright : PALETTE.cobaltViolet);
  brush.set("cpencil", haloCol, 1.25);
  brush.spline(spinePts, 0.45);

  // Pale lilac transition edge
  brush.set("gouache_detail", PALETTE.lilacPale, 1.05);
  brush.spline(spinePts, 0.45);

  // Pass 2: Bright ivory-white vein core
  brush.set("gouache_white", PALETTE.ivory, 0.68);
  brush.spline(spinePts, 0.45);

  // Specular pure white highlight along the center of thicker folds
  brush.set("gouache_detail", PALETTE.pureWhite, 0.55);
  brush.spline(spinePts, 0.45);

  // Pass 3: Razor-fine pen contour lines along BOTH edges of the white vein
  brush.set("razor_pen", PALETTE.violetAbyss, 0.62);
  brush.spline(leftWall, 0.42);
  brush.set("razor_pen", PALETTE.prussianAbyss, 0.58);
  brush.spline(rightWall, 0.42);

  // Pass 4: Delicate micro-needle cross-contour shading ticks into the dark violet crevice
  for (let i = 1; i < leftWall.length - 1; i += 2) {
    if (random() < 0.55) {
      let p0 = leftWall[i];
      let pC = spinePts[i];
      let dx = p0[0] - pC[0];
      let dy = p0[1] - pC[1];
      brush.set("micro_needle", (i % 2 === 0) ? PALETTE.prussianAbyss : PALETTE.cobaltVioletDeep, 0.55);
      brush.line(p0[0], p0[1], p0[0] + dx * 1.15, p0[1] + dy * 1.15);
    }
  }
}

// --- D. Basal Lobe Pockets (Beside the Stem Neck) ---
function drawBasalLobePockets(side) {
  // Tightly curled basal leaf folds tucked in the lower shoulder (v in [-205, -135])
  for (let k = 0; k < 4; k++) {
    let uCenter = side * lerp(72, 138, k / 3);
    let vCenter = lerp(-182, -148, k / 3);
    let radU = lerp(24, 34, k / 3);
    let radV = lerp(16, 24, k / 3);

    let loopUV = [];
    for (let a = -150; a <= 150; a += 25) {
      let rScale = map(a, -150, 150, 0.45, 1.0);
      let u = uCenter + side * radU * rScale * cos(a);
      let v = vCenter + radV * rScale * sin(a);
      loopUV.push({ u, v, w: lerp(0.45, 0.85, sin(map(a, -150, 150, 0, 180))) });
    }
    drawLabyrinthVeinRibbon(loopUV, k + 10);
  }
}

// --- E. The Innermost Apical Heart (Concentric Rosebud / Meristem Labyrinth) ---
function drawApicalHeartLabyrinth() {
  // Directly above the core apex (v in [20, 118], |u| < 88), young leaves form
  // tightly nested, brain-like S-curves and interlocking C-scrolls
  let numLayers = 7;
  for (let l = 0; l < numLayers; l++) {
    let f = l / (numLayers - 1); // 0 = outer heart, 1 = innermost bud right at core tip
    let vBase = lerp(108, 28, f);
    let uSpan = lerp(78, 16, f);
    let vSpan = lerp(34, 10, f);

    for (let side of [-1, 1]) {
      let scrollUV = [];
      let steps = 20;
      for (let s = 0; s <= steps; s++) {
        let t = s / steps;
        // Interlocking S-scroll that wraps around the meristem dome
        let ang = lerp(-75, 195, t);
        let rMod = 1.0 - 0.35 * t + 0.14 * sin(t * 540 + l * 45);
        let u = side * uSpan * rMod * cos(ang * 0.75) + side * (1 - f) * 8;
        let v = vBase + vSpan * rMod * sin(ang) + sin(t * 360) * 5;
        let w = lerp(0.85, 0.35, f) * sin(t * 180 + 15);
        scrollUV.push({ u, v, w: max(0.32, w) });
      }
      drawLabyrinthVeinRibbon(scrollUV, l * 3 + (side > 0 ? 1 : 0));
    }
  }
}

// --- F. Render Bold Arching Primary Midribs & Lateral Spurs ---
function drawPrimaryMidrib(ribUV, side, ribIdx) {
  let leftEdge = [];
  let rightEdge = [];
  let centerLine = [];

  for (let i = 0; i < ribUV.length; i++) {
    let cur = ribUV[i];
    let prev = ribUV[max(0, i - 1)];
    let next = ribUV[min(ribUV.length - 1, i + 1)];

    let du = next.u - prev.u;
    let dv = next.v - prev.v;
    let len = sqrt(du * du + dv * dv) || 1;
    let nu = -dv / len;
    let nv = du / len;

    // Slight organic bumps along the rib wall where secondary veins branch off
    let cren = (noise(i * 0.45 + ribIdx * 11, side + 3) - 0.5) * 2.2;
    let hw = cur.w * 0.5 + cren;

    let pL = cabToCanvas(cur.u + nu * hw, cur.v + nv * hw);
    let pR = cabToCanvas(cur.u - nu * hw, cur.v - nv * hw);
    let pC = cabToCanvas(cur.u, cur.v);

    leftEdge.push(pL);
    rightEdge.push(pR);
    centerLine.push([pC[0], pC[1], map(cur.w, 1.5, 16, 0.4, 1.6)]);
  }

  let ribPoly = leftEdge.concat(rightEdge.slice().reverse());

  // 1. Cobalt violet & pale lilac anthocyanin halo along the midrib margins
  brush.set("cpencil", PALETTE.cobaltViolet, 1.15);
  brush.spline(leftEdge, 0.35);
  brush.spline(rightEdge, 0.35);

  // 2. Opaque ivory-white polygon wash + bright gouache spine for the fleshy midrib
  brush.noStroke();
  brush.wash(PALETTE.ivory, 248);
  drawClosedShape(ribPoly, 0.25);
  brush.noWash();

  brush.set("gouache_white", PALETTE.ivory, 1.1);
  brush.spline(centerLine, 0.35);
  brush.set("gouache_detail", PALETTE.pureWhite, 0.9);
  brush.spline(centerLine, 0.35);

  // 3. Branching lateral vein spurs shooting off the primary midrib into the chambers
  let numSpurs = 6;
  for (let s = 1; s <= numSpurs; s++) {
    let idx = floor(map(s, 1, numSpurs + 1, 3, ribUV.length - 5));
    let cur = ribUV[idx];
    let next = ribUV[idx + 1];
    let du = next.u - cur.u;
    let dv = next.v - cur.v;
    let len = sqrt(du * du + dv * dv) || 1;
    let bDir = (s % 2 === 0) ? 1 : -1;
    let nu = (-dv / len) * bDir;
    let nv = (du / len) * bDir;

    let spurUV = [];
    for (let k = 0; k <= 6; k++) {
      let kt = k / 6;
      let distOut = cur.w * 0.4 + kt * lerp(18, 9, ribIdx / 6);
      let curveAlong = kt * kt * 10;
      let su = cur.u + nu * distOut + (du / len) * curveAlong + sin(kt * 220) * 3 * nu;
      let sv = cur.v + nv * distOut + (dv / len) * curveAlong + sin(kt * 220) * 3 * nv;
      spurUV.push({ u: su, v: sv, w: lerp(0.75, 0.22, kt) });
    }
    drawLabyrinthVeinRibbon(spurUV, ribIdx + s);
  }

  // 4. Razor-sharp technical pen outlines & internal vascular striations along the midrib
  brush.set("razor_pen", PALETTE.violetAbyss, 0.68);
  brush.spline(leftEdge, 0.35);
  brush.set("razor_pen", PALETTE.prussianAbyss, 0.68);
  brush.spline(rightEdge, 0.35);

  // Delicate longitudinal cellular fiber lines inside the white midrib
  for (let f of [-0.22, 0.22]) {
    let fiberPts = [];
    for (let i = 0; i < leftEdge.length; i += 2) {
      let t = 0.5 + f;
      let fx = lerp(leftEdge[i][0], rightEdge[i][0], t);
      let fy = lerp(leftEdge[i][1], rightEdge[i][1], t);
      fiberPts.push([fx, fy, 0.45]);
    }
    brush.set("micro_needle", PALETTE.lilacMid, 0.45);
    brush.spline(fiberPts, 0.35);
  }
}

// --- G. Central Conical Stem & Pith Core ---
function drawCentralCoreAndStem() {
  let leftFlank = [];
  let rightFlank = [];
  let innerLeft = [];
  let innerRight = [];

  for (let v = -254; v <= 22; v += 8) {
    let cw = coreHalfWidth(v);
    // Add natural leaf-scar notches along the stem neck (-195 to -130)
    let notch = 0;
    if (v > -195 && v < -125) {
      notch = sin((v + 195) * 9) * 3.5;
    }
    let w = max(0, cw + notch);
    leftFlank.push(cabToCanvas(-w, v));
    rightFlank.push(cabToCanvas(w, v));
    innerLeft.push(cabToCanvas(-w * 0.66, v));
    innerRight.push(cabToCanvas(w * 0.66, v));
  }

  let corePoly = leftFlank.concat(rightFlank.slice().reverse());
  let pithPoly = innerLeft.concat(innerRight.slice().reverse());

  // 1. Opaque lilac-ivory cortex wash + warm ivory central pith wash
  brush.noStroke();
  brush.wash(PALETTE.ivoryLilac, 245);
  drawClosedShape(corePoly, 0.2);
  brush.wash(PALETTE.ivoryWarm, 250);
  drawClosedShape(pithPoly, 0.2);
  brush.noWash();

  // Reinforce with opaque white gouache along the pith center for maximum luminosity
  for (let uFrac of [-0.35, 0, 0.35]) {
    let coreSpine = [];
    for (let v = -246; v <= 16; v += 12) {
      let p = cabToCanvas(coreHalfWidth(v) * uFrac, v);
      coreSpine.push([p[0], p[1], 1.2]);
    }
    brush.set("gouache_white", PALETTE.ivory, 1.35);
    brush.spline(coreSpine, 0.3);
  }

  // 2. Longitudinal fibrous striations inside the stem & pith
  for (let i = -6; i <= 6; i++) {
    let frac = i / 7.5;
    let fibPts = [];
    for (let v = -250; v <= 16; v += 12) {
      let u = coreHalfWidth(v) * frac + (noise(i * 3, v * 0.05) - 0.5) * 2.5;
      let p = cabToCanvas(u, v);
      fibPts.push([p[0], p[1], 0.55]);
    }
    let col = (abs(i) >= 5) ? PALETTE.cobaltViolet : PALETTE.coreShadow;
    brush.set("micro_needle", col, (abs(i) >= 5) ? 0.52 : 0.38);
    brush.spline(fibPts, 0.3);
  }

  // 3. Cambium vascular bundle dots & axillary bud primordia along both core flanks
  for (let v = -242; v <= 14; v += 6.5) {
    let cw = coreHalfWidth(v) * 0.76;
    for (let side of [-1, 1]) {
      let [vx, vy] = cabToCanvas(side * cw + random(-1, 1), v);
      brush.set("razor_pen", ( random() < 0.5 ) ? PALETTE.cobaltVioletDeep : PALETTE.prussianDark, random(0.45, 0.85));
      brush.line(vx, vy, vx + random(-1.2, 1.2), vy + random(1.5, 3.2));
    }
  }

  // 4. Crisp cut stem base at v = -254 (showing concentric vascular ring at the knife cut)
  let basePts = [];
  for (let u = -30; u <= 30; u += 6) {
    let v = -254 + 4 * sin(map(u, -30, 30, 0, 180));
    basePts.push(cabToCanvas(u, v));
  }
  brush.set("razor_pen", PALETTE.prussianAbyss, 0.85);
  brush.spline(basePts, 0.3);

  // Shading hatch at the base of the cut stem
  for (let u = -28; u <= 28; u += 3.5) {
    let p0 = cabToCanvas(u, -253);
    let p1 = cabToCanvas(u * 0.92, -238 - random(0, 8));
    brush.set("micro_needle", PALETTE.prussianDark, 0.48);
    brush.line(p0[0], p0[1], p1[0], p1[1]);
  }

  // 5. Razor-sharp contour lines along the left and right flanks of the core
  brush.set("razor_pen", PALETTE.violetAbyss, 0.65);
  brush.spline(leftFlank, 0.25);
  brush.spline(rightFlank, 0.25);
}

// ============================================================================
// 6. FINAL BOTANICAL DETAILS — KNIFE STRIATIONS & SPECULAR HIGHLIGHTS
// ============================================================================

function drawFinalBotanicalDetails() {
  brush.noField();

  // 1. Subtle parallel diagonal knife-slice striations across the flat cut face
  // (A hallmark of hyperreal botanical cross-sections)
  let sliceAngle = CAB_ANGLE + 38;
  let ca = cos(sliceAngle);
  let sa = sin(sliceAngle);

  for (let i = -18; i <= 18; i++) {
    let offset = i * 11 + random(-3, 3);
    let ox = CAB_CX - sa * offset;
    let oy = CAB_CY + ca * offset;

    for (let seg = -5; seg <= 5; seg++) {
      if (random() < 0.45) continue;
      let d0 = seg * 34 + random(-8, 8);
      let d1 = d0 + random(14, 28);
      let x0 = ox + ca * d0;
      let y0 = oy + sa * d0;
      let x1 = ox + ca * d1;
      let y1 = oy + sa * d1;

      if (inCutFaceReserve(x0, y0) && inCutFaceReserve(x1, y1)) {
        let col = (i % 2 === 0) ? PALETTE.pureWhite : PALETTE.lilacPale;
        brush.set("micro_needle", col, 0.35);
        brush.line(x0, y0, x1, y1);
      }
    }
  }

  // 2. Deepest velvet crevice accents where primary ribs meet the central core
  for (let side of [-1, 1]) {
    for (let v = -180; v <= 5; v += 28) {
      let cw = coreHalfWidth(v) + 2;
      let [px, py] = cabToCanvas(side * cw, v);
      let [qx, qy] = cabToCanvas(side * (cw + 14), v - 6);
      brush.set("razor_pen", PALETTE.prussianAbyss, 0.85);
      brush.line(px, py, qx, qy);
    }
  }
}

