// ============================================================================
// 3D PAPER SURFACE, CURL & RAKING PERSPECTIVE PROJECTION
// ============================================================================

const TABLE_CX = 602;
const TABLE_CY = 596;
const PAPER_ROT = -2.2 * (Math.PI / 180); // Slight natural placement angle on table

function getPaperZ(u, v) {
  let absU = Math.abs(u);
  let t = absU / 405;

  // Central mountain fold ridge (u = 0) lifted off the table in a crisp V-crease
  let spineRidge = (16.5 + 3.5 * Math.cos(v * 0.009) + 2.5 * Math.sin(v * 0.017)) * Math.exp(-t / 0.23);

  // Paper touches down near mid-wing (t ~ 0.44), then curls upward toward outer edges
  let sideAsym = u >= 0 ? 1.26 : 0.86; // Right wing lifts higher than left wing
  let cornerLift = 1.0 + 0.34 * Math.pow(v / 430, 2) + (v > 0 ? 0.12 : -0.04);
  let outerCurl = 36.0 * sideAsym * cornerLift * Math.pow(Math.max(0, t - 0.38) / 0.62, 2.15);

  // Gentle organic undulation in the thin paper sheet
  let ripple = 2.4 * Math.sin(v * 0.015 + (u >= 0 ? 0.6 : -0.4)) * Math.pow(t, 0.8);

  return Math.max(1.1, spineRidge + outerCurl + ripple);
}

function getPaperSlopeU(u, v) {
  let eps = 2.0;
  return (getPaperZ(u + eps, v) - getPaperZ(u - eps, v)) / (2 * eps);
}

function projectUV(u, v) {
  let z = getPaperZ(u, v);
  let absU = Math.abs(u);
  let signU = u >= 0 ? 1 : -1;

  // Physical horizontal pull-in as the paper curls upward at the edges and spine
  let curlPull = signU * (Math.pow(Math.max(0, absU - 150) / 255, 2.0) * 11.5 + (absU / 405) * 4.5);
  let u3d = u - curlPull;
  let v3d = v * 0.915; // Overhead slightly raking perspective foreshortening (~23 deg)

  // Rotate on tabletop plane
  let cosR = Math.cos(PAPER_ROT);
  let sinR = Math.sin(PAPER_ROT);
  let tx = TABLE_CX + u3d * cosR - v3d * sinR;
  let ty = TABLE_CY + u3d * sinR + v3d * cosR;

  // Paper point shifts upward-left toward camera as it lifts by z above the tabletop
  let paperX = tx - z * 0.08;
  let paperY = ty - z * 0.46;

  // Raking cool studio light from upper-left casts shadow toward lower-right on table
  let shadowX = tx + z * 0.96;
  let shadowY = ty + z * 0.68;

  return {
    px: paperX,
    py: paperY,
    sx: shadowX,
    sy: shadowY,
    tx: tx,
    ty: ty,
    z: z,
    u: u,
    v: v
  };
}

// ============================================================================
// STEP 1: HONEY-COLOURED PINE TABLETOP (WATERCOLOUR WASHES, GRAIN & KNOTS)
// ============================================================================

function buildPineKnots() {
  knots = [
    { x: 295, y: 845, rx: 46, ry: 22, angle: -4, strength: 1.15 }, // Lower-left under curling edge
    { x: 515, y: 455, rx: 28, ry: 14, angle: 2, strength: 0.78 },  // Peeking through inner heart cutouts
    { x: 915, y: 275, rx: 36, ry: 17, angle: -3, strength: 0.92 }  // Upper-right tabletop
  ];
}

function getWoodGrainY(x, baseY) {
  // Subtle tabletop rake angle
  let y = baseY + (x - 600) * 0.025;

  // Broad cathedral arch modulation along the plank
  let plankCenter = baseY < 215 ? 110 : (baseY > 1010 ? 1105 : 610);
  let dyPlank = baseY - plankCenter;
  let cathedral = Math.sin((x - 180) * 0.0042) * 26 * Math.sin( dyPlank * 0.006 );
  let n = (noise(x * 0.0025, baseY * 0.008) - 0.5) * 28;
  y += cathedral + n;

  // Smooth fluid deflection around pine knots
  for (let k of knots) {
    let dx = x - k.x;
    let dy = y - k.y;
    let distSq = (dx * dx) / (k.rx * k.rx * 5.5) + (dy * dy) / (k.ry * k.ry * 4.2);
    if (distSq < 12.0) {
      let push = k.strength * 34 * Math.exp(-distSq * 0.55);
      y += (dy >= 0 ? 1 : -1) * push * (1.0 / (1.0 + Math.abs(dy) * 0.018));
    }
  }
  return y;
}

function drawPineTabletop() {
  // Cool north-light studio base over pale honey pine
  background("#dedad0");

  brush.noStroke();

  // 1A. Broad raking light and cool shadow washes across the tabletop
  let baseWashes = [
    { col: "#e7e4dc", op: 95, x: 360, y: 320, w: 760, h: 640 }, // Cool daylight highlight upper-left
    { col: "#d8bb8c", op: 65, x: 580, y: 580, w: 1120, h: 980 }, // Warm honey pine core
    { col: "#ccb386", op: 55, x: 640, y: 650, w: 1050, h: 720 }, // Golden amber mid-tone
    { col: "#8d99a6", op: 38, x: 920, y: 920, w: 680, h: 620 }, // Cool slate ambient falloff lower-right
    { col: "#9aa4b0", op: 32, x: 180, y: 980, w: 520, h: 420 }  // Cool shadow undertone lower-left
  ];

  brush.fillBleed(0.24, "out");
  brush.fillTexture(0.5, 0.25);
  for (let w of baseWashes) {
    brush.fill(w.col, w.op);
    brush.rect(w.x, w.y, w.w, w.h, "center");
  }

  // 1B. Cathedral pine latewood/earlywood bands in batched watercolour washes
  let warmAmberBands = [45, 135, 290, 395, 515, 645, 765, 895, 1055, 1140];
  brush.fillBleed(0.16, "out");
  brush.fillTexture(0.62, 0.38);
  brush.fill("#c79355", 52);
  for (let by of warmAmberBands) {
    drawWoodBandPolygon(by, 24 + (by % 17));
  }

  let honeyOchreBands = [85, 175, 245, 340, 450, 580, 705, 830, 955, 1095];
  brush.fill("#d5aa72", 48);
  for (let by of honeyOchreBands) {
    drawWoodBandPolygon(by, 32 + (by % 19));
  }

  // Cool greyed-umber grain washes to anchor the cool palette hint
  let coolSlateGrainBands = [115, 320, 485, 615, 795, 935, 1030];
  brush.fill("#8c857b", 36);
  for (let by of coolSlateGrainBands) {
    drawWoodBandPolygon(by, 18 + (by % 13));
  }

  // 1C. Render the Pine Knots in layered watercolour washes & dark resinous cores
  for (let k of knots) {
    // Outer amber halo
    brush.fillBleed(0.22, "out");
    brush.fillTexture(0.65, 0.45);
    brush.fill("#b3783c", 75);
    drawKnotEllipse(k.x, k.y, k.rx * 1.45, k.ry * 1.38, k.angle);

    // Mid sienna ring
    brush.fillBleed(0.14, "out");
    brush.fill("#7d4c24", 110);
    drawKnotEllipse(k.x, k.y, k.rx * 0.95, k.ry * 0.92, k.angle);

    // Dark cool-umber core
    brush.fillBleed(0.08, "in");
    brush.fill("#332822", 165);
    drawKnotEllipse(k.x, k.y, k.rx * 0.48, k.ry * 0.46, k.angle);
  }
  brush.noFill();

  // 1D. Fine continuous pine wood grain striations & resin ducts
  for (let baseY = -10; baseY <= 1215; baseY += 5.5) {
    let pts = [];
    for (let x = -20; x <= 1220; x += 30) {
      pts.push([x, getWoodGrainY(x, baseY)]);
    }

    let bandPhase = Math.sin(baseY * 0.055) + noise(baseY * 0.03) * 0.8;
    if (bandPhase > 0.45) {
      // Resinous warm latewood line
      let col = random() < 0.65 ? "#9c6836" : "#7e542d";
      brush.set("pine_grain", col, random(0.55, 1.15));
      brush.spline(pts, 0.4);
    } else if (bandPhase < -0.25) {
      // Cool silver-oat earlywood highlight / cool grey pore line
      let col = random() < 0.55 ? "#ece9e1" : "#8e969e";
      brush.set("2H", col, random(0.35, 0.65));
      brush.spline(pts, 0.4);
    } else if (random() < 0.45) {
      // Subtle mid-tone honey-taupe striation
      brush.set("pine_grain", "#b58b59", random(0.4, 0.8));
      brush.spline(pts, 0.4);
    }
  }

  // 1E. Knot concentric growth rings and radial checking cracks in sharp pencil
  for (let k of knots) {
    for (let r = 0.25; r <= 1.35; r += 0.18) {
      let ringPts = [];
      for (let a = 0; a <= 360; a += 30) {
        let rad = a * (Math.PI / 180);
        let px = k.x + Math.cos(rad) * k.rx * r + (noise(a, r * 10) - 0.5) * 4;
        let py = k.y + Math.sin(rad) * k.ry * r + (noise(r * 10, a) - 0.5) * 2.5;
        ringPts.push([px, py]);
      }
      brush.set("2B", r < 0.7 ? "#261d18" : "#694121", r < 0.7 ? 0.55 : 0.4);
      brush.spline(ringPts, 0.5);
    }
    // Radial dry check cracks inside the knot
    brush.set("rotring", "#1a1412", 0.42);
    for (let c = 0; c < 5; c++) {
      let ang = (c * 72 + 15) * (Math.PI / 180);
      brush.line(
        k.x + Math.cos(ang) * 2,
        k.y + Math.sin(ang) * 1.5,
        k.x + Math.cos(ang) * k.rx * random(0.35, 0.7),
        k.y + Math.sin(ang) * k.ry * random(0.35, 0.7)
      );
    }
  }

  // 1F. Subtle horizontal plank joints at y ~ 212 and y ~ 1008
  for (let py of [212, 1008]) {
    let y0 = py - 15;
    let y1 = py + 15;
    brush.set("2B", "#59493b", 0.55);
    brush.line(0, y0, 1200, y1);
    brush.set("2H", "#efeae0", 0.5);
    brush.line(0, y0 + 1.8, 1200, y1 + 1.8);
  }
}

function drawWoodBandPolygon(baseY, thickness) {
  brush.beginShape(0.35);
  for (let x = -20; x <= 1220; x += 60) {
    let wave = Math.sin(x * 0.005 + baseY * 0.02) * (thickness * 0.45);
    brush.vertex(x, getWoodGrainY(x, baseY - thickness * 0.5 - wave));
  }
  for (let x = 1220; x >= -20; x -= 60) {
    let wave = Math.sin(x * 0.005 + baseY * 0.02) * (thickness * 0.45);
    brush.vertex(x, getWoodGrainY(x, baseY + thickness * 0.5 + wave));
  }
  brush.endShape(true);
}

function drawKnotEllipse(cx, cy, rx, ry, angDeg) {
  let ang = angDeg * (Math.PI / 180);
  let cosA = Math.cos(ang);
  let sinA = Math.sin(ang);
  brush.beginShape(0.45);
  for (let a = 0; a < 360; a += 30) {
    let rad = a * (Math.PI / 180);
    let lx = Math.cos(rad) * rx;
    let ly = Math.sin(rad) * ry;
    brush.vertex(cx + lx * cosA - ly * sinA, cy + lx * sinA + ly * cosA);
  }
  brush.endShape(true);
}

// ============================================================================
// STEP 2: BUILD SCHERENSCHNITTE GEOMETRY (SYMMETRICAL TREE OF BIRDS & HEARTS)
// ============================================================================

function addSymmetricRibbon(ptsUV, widths, curvature = 0.38, tag = "branch") {
  // Subdivide centerline smoothly in (u, v) so ribbons curve with surgical precision
  let densePts = subdivideUV(ptsUV, widths);
  for (let side of [-1, 1]) {
    let leftSide = [];
    let rightSide = [];
    for (let i = 0; i < densePts.length; i++) {
      let p = densePts[i];
      // Slight handmade variation (< 0.7px) between left & right cut layers
      let jitterU = (noise(p.u * 0.05, p.v * 0.05, side > 0 ? 10 : 20) - 0.5) * 0.9;
      let jitterV = (noise(p.v * 0.05, p.u * 0.05, side > 0 ? 30 : 40) - 0.5) * 0.9;
      let u = side * p.u + jitterU;
      let v = p.v + jitterV;

      let prev = densePts[Math.max(0, i - 1)];
      let next = densePts[Math.min(densePts.length - 1, i + 1)];
      let du = side * (next.u - prev.u);
      let dv = next.v - prev.v;
      let len = Math.hypot(du, dv) || 1;
      let nu = -dv / len;
      let nv = du / len;

      leftSide.push([u + nu * p.w, v + nv * p.w]);
      rightSide.push([u - nu * p.w, v - nv * p.w]);
    }
    let polyUV = leftSide.concat(rightSide.reverse());
    registerShapeUV(polyUV, curvature, tag);
  }
}

function addCenterBridgePolygon(polyRightUV, curvature = 0.35, vMin = null, vMax = null) {
  // Builds a single symmetrical shape straddling the central fold u = 0
  let fullUV = [];
  for (let i = 0; i < polyRightUV.length; i++) {
    fullUV.push([polyRightUV[i][0], polyRightUV[i][1]]);
  }
  for (let i = polyRightUV.length - 1; i >= 0; i--) {
    if (polyRightUV[i][0] > 0.5) {
      fullUV.push([-polyRightUV[i][0], polyRightUV[i][1]]);
    }
  }
  registerShapeUV(fullUV, curvature, "center");
  if (vMin !== null && vMax !== null) {
    spineIntervals.push([vMin, vMax]);
  }
}

function addSymmetricPolygon(polyUV, curvature = 0.35, tag = "motif") {
  for (let side of [-1, 1]) {
    let mirrored = polyUV.map(pt => [
      side * pt[0] + (noise(pt[0] * 0.1, pt[1] * 0.1, side + 5) - 0.5) * 0.7,
      pt[1] + (noise(pt[1] * 0.1, pt[0] * 0.1, side + 9) - 0.5) * 0.7
    ]);
    if (side === -1) mirrored.reverse();
    registerShapeUV(mirrored, curvature, tag);
  }
}

function registerShapeUV(polyUV, curvature, tag) {
  let projected = polyUV.map(pt => projectUV(pt[0], pt[1]));
  let zSum = 0;
  let uSum = 0;
  let vSum = 0;
  for (let p of projected) {
    zSum += p.z;
    uSum += p.u;
    vSum += p.v;
  }
  let n = projected.length || 1;
  paperShapes.push({
    pts: projected,
    curvature: curvature,
    zAvg: zSum / n,
    uAvg: uSum / n,
    vAvg: vSum / n,
    tag: tag
  });
}

function subdivideUV(pts, widths) {
  let out = [];
  for (let i = 0; i < pts.length - 1; i++) {
    let p0 = pts[Math.max(0, i - 1)];
    let p1 = pts[i];
    let p2 = pts[i + 1];
    let p3 = pts[Math.min(pts.length - 1, i + 2)];
    let w1 = widths[i];
    let w2 = widths[i + 1];
    let dist = Math.hypot(p2[0] - p1[0], p2[1] - p1[1]);
    let steps = Math.max(2, Math.min(8, Math.floor(dist / 14)));
    for (let s = 0; s < steps; s++) {
      let t = s / steps;
      let t2 = t * t;
      let t3 = t2 * t;
      // Catmull-Rom interpolation
      let u = 0.5 * (
        (2 * p1[0]) +
        (-p0[0] + p2[0]) * t +
        (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 +
        (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3
      );
      let v = 0.5 * (
        (2 * p1[1]) +
        (-p0[1] + p2[1]) * t +
        (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 +
        (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3
      );
      let w = w1 + (w2 - w1) * t;
      out.push({ u, v, w });
    }
  }
  let last = pts[pts.length - 1];
  out.push({ u: last[0], v: last[1], w: widths[widths.length - 1] });
  return out;
}

// Helper for open folk-art heart frames
function addOpenHeart(cx, cy, rx, ry, wArch = 5.5, rotDeg = 0) {
  let ang = rotDeg * (Math.PI / 180);
  let cosA = Math.cos(ang);
  let sinA = Math.sin(ang);
  let mapPt = (lx, ly) => [
    cx + lx * cosA - ly * sinA,
    cy + lx * sinA + ly * cosA
  ];

  // Outer right & left lobes of the heart
  for (let lobe of [-1, 1]) {
    let pts = [
      mapPt(0, -ry * 0.28),
      mapPt(lobe * rx * 0.48, -ry * 0.92),
      mapPt(lobe * rx * 0.98, -ry * 0.42),
      mapPt(lobe * rx * 0.72, ry * 0.25),
      mapPt(0, ry * 0.98)
    ];
    let ws = [wArch * 0.85, wArch * 1.15, wArch * 1.2, wArch * 0.95, wArch * 0.75];
    addSymmetricRibbon(pts, ws, 0.42, "heart");
  }
}

// Helper for solid cut heart (with optional tiny inner cutout split)
function addSolidHeart(cx, cy, rx, ry, rotDeg = 0) {
  let ang = rotDeg * (Math.PI / 180);
  let cosA = Math.cos(ang);
  let sinA = Math.sin(ang);
  let mapPt = (lx, ly) => [
    cx + lx * cosA - ly * sinA,
    cy + lx * sinA + ly * cosA
  ];
  let poly = [
    mapPt(0, -ry * 0.28),
    mapPt(rx * 0.38, -ry * 0.88),
    mapPt(rx * 0.92, -ry * 0.58),
    mapPt(rx * 0.96, -ry * 0.05),
    mapPt(rx * 0.55, ry * 0.48),
    mapPt(0, ry * 0.98),
    mapPt(-rx * 0.55, ry * 0.48),
    mapPt(-rx * 0.96, -ry * 0.05),
    mapPt(-rx * 0.92, -ry * 0.58),
    mapPt(-rx * 0.38, -ry * 0.88)
  ];
  addSymmetricPolygon(poly, 0.38, "heart");
}

// Helper for serrated lanceolate leaf
function addLeaf(u0, v0, angleDeg, len, width = 5.5) {
  let a = angleDeg * (Math.PI / 180);
  let ca = Math.cos(a);
  let sa = Math.sin(a);
  let na = -sa;
  let nb = ca;
  let poly = [
    [u0, v0],
    [u0 + ca * len * 0.28 + na * width * 0.75, v0 + sa * len * 0.28 + nb * width * 0.75],
    [u0 + ca * len * 0.55 + na * width * 1.0, v0 + sa * len * 0.55 + nb * width * 1.0],
    [u0 + ca * len * 0.82 + na * width * 0.55, v0 + sa * len * 0.82 + nb * width * 0.55],
    [u0 + ca * len, v0 + sa * len],
    [u0 + ca * len * 0.82 - na * width * 0.55, v0 + sa * len * 0.82 - nb * width * 0.55],
    [u0 + ca * len * 0.55 - na * width * 1.0, v0 + sa * len * 0.55 - nb * width * 1.0],
    [u0 + ca * len * 0.28 - na * width * 0.75, v0 + sa * len * 0.28 - nb * width * 0.75]
  ];
  addSymmetricPolygon(poly, 0.25, "leaf");
}

// Helper for intricate folk-art songbird with pierced body, multi-plume wing & fanned tail
function addFolkBird(cx, cy, scale, dirX = -1, tiltDeg = 0) {
  let ang = tiltDeg * (Math.PI / 180);
  let cosA = Math.cos(ang);
  let sinA = Math.sin(ang);
  // Transforms local bird coords (where +x is forward toward beak, +y is downward)
  let M = (lx, ly) => {
    let sx = lx * dirX * scale;
    let sy = ly * scale;
    return [
      cx + sx * cosA - sy * sinA,
      cy + sx * sinA + sy * cosA
    ];
  };
  let W = (w) => w * scale;

  // 1. Upper head, crown arch, neck & back ribbon (leaves hollow body aperture)
  addSymmetricRibbon(
    [M(34, -22), M(24, -33), M(11, -30), M(2, -16), M(-14, -8), M(-36, -4)],
    [W(3.2), W(5.8), W(6.2), W(5.2), W(5.5), W(4.8)],
    0.42, "bird"
  );

  // 2. Throat, puffed breast & lower belly arch ribbon (encloses teardrop cutout in bird body)
  addSymmetricRibbon(
    [M(28, -18), M(24, -2), M(16, 16), M(0, 22), M(-20, 14), M(-36, -2)],
    [W(4.2), W(6.8), W(7.5), W(6.8), W(5.5), W(4.5)],
    0.42, "bird"
  );

  // 3. Decorative inner heart/foliate scroll inside the hollow bird body
  addSymmetricRibbon(
    [M(-16, 2), M(-2, 10), M(10, 4), M(6, -6), M(-4, -3)],
    [W(2.4), W(3.4), W(3.2), W(2.6), W(1.8)],
    0.45, "bird"
  );

  // 4. Crisp singing upper & lower beak
  addSymmetricPolygon([M(31, -25), M(49, -23), M(33, -19)], 0.1, "bird");
  addSymmetricPolygon([M(30, -19), M(46, -15), M(28, -14)], 0.1, "bird");

  // 5. Folk-art regal crest plumes on head
  addLeaf(M(15, -31)[0], M(15, -31)[1], dirX > 0 ? -135 + tiltDeg : -45 - tiltDeg, 19 * scale, 3.4 * scale);
  addLeaf(M(10, -29)[0], M(10, -29)[1], dirX > 0 ? -155 + tiltDeg : -25 - tiltDeg, 15 * scale, 2.8 * scale);

  // 6. Raised scalloped wing (5 distinct curved primary feathers)
  for (let f = 0; f < 5; f++) {
    let t = f / 4;
    let p0 = M(4 - f * 4.5, -10 - f * 1.5);
    let p1 = M(-8 - f * 7.5, -28 - f * 5.5);
    let p2 = M(-26 - f * 9.5, -42 - f * 4.0 + t * 8);
    let p3 = M(-42 - f * 7.0, -46 + f * 4.5);
    addSymmetricRibbon(
      [p0, p1, p2, p3],
      [W(3.6), W(4.6 - t * 0.6), W(5.2 - t * 0.8), W(1.6)],
      0.42, "bird"
    );
  }
  // Wing coverts bridge connecting feathers
  addSymmetricRibbon(
    [M(4, -12), M(-12, -26), M(-28, -32)],
    [W(4.5), W(4.0), W(3.0)],
    0.38, "bird"
  );

  // 7. Fanned tail feathers (4 ornate plumes)
  for (let tf = -1.5; tf <= 1.5; tf += 1.0) {
    let p0 = M(-34, -2);
    let p1 = M(-52, -4 + tf * 9);
    let p2 = M(-72, -6 + tf * 17);
    let p3 = M(-86, -5 + tf * 23);
    addSymmetricRibbon(
      [p0, p1, p2, p3],
      [W(3.2), W(3.8), W(4.8), W(1.8)],
      0.38, "bird"
    );
  }

  // 8. Grasping legs connecting bird to branch below
  addSymmetricRibbon([M(2, 20), M(-2, 36), M(4, 44)], [W(2.8), W(2.4), W(2.2)], 0.25, "bird");
  addSymmetricRibbon([M(-10, 17), M(-14, 35), M(-8, 43)], [W(2.6), W(2.2), W(2.0)], 0.25, "bird");
}

function buildScherenschnitteGeometry() {
  paperShapes = [];
  spineIntervals = [];

  // --------------------------------------------------------------------------
  // A. CENTRAL SPINE & TRUNK (STRADDLING THE FOLD CREASE u = 0)
  // --------------------------------------------------------------------------
  // In authentic folded Scherenschnitte, cutouts along the fold alternate with
  // solid paper bridges across u = 0. We record exact spine intervals for the grey crease!

  // 1. Crown finial bridge at very top (v: -435 to -398)
  addCenterBridgePolygon([[0, -436], [14, -424], [24, -408], [0, -396]], 0.35, -436, -396);

  // 2. Crown heart base bridge (v: -315 to -276)
  addCenterBridgePolygon([[0, -316], [19, -304], [24, -290], [0, -275]], 0.35, -316, -275);
  // Central crown heart arch enclosing heart cutout on fold (v: -398 to -312)
  addSymmetricRibbon(
    [[0, -398], [38, -422], [72, -392], [64, -348], [28, -314], [0, -288]],
    [6.5, 8.5, 9.0, 8.0, 7.0, 6.5],
    0.42, "heart"
  );
  // Inner miniature heart suspended on fold inside the Crown Heart (v: -376 to -340)
  addCenterBridgePolygon([[0, -376], [18, -388], [28, -370], [16, -352], [0, -338]], 0.38, -376, -338);
  // Thin vertical fold stem holding the miniature crown heart
  addCenterBridgePolygon([[0, -398], [3.5, -386], [0, -374]], 0.2, -398, -374);
  addCenterBridgePolygon([[0, -340], [3.5, -326], [0, -314]], 0.2, -340, -314);

  // 3. Upper trunk chalice & diamond lattice along fold (v: -275 to +310)
  // Upper trunk bridge 1 (v: -220 to -172)
  addCenterBridgePolygon([[0, -222], [22, -206], [26, -190], [0, -170]], 0.35, -222, -170);
  // Trunk arches around upper fold cutout (v: -280 to -215)
  addSymmetricRibbon([[8, -282], [34, -262], [38, -236], [14, -210]], [7.5, 8.5, 8.5, 7.5], 0.4, "trunk");

  // Middle trunk bridge 2 (v: -105 to -52)
  addCenterBridgePolygon([[0, -108], [28, -90], [32, -72], [0, -50]], 0.35, -108, -50);
  // Trunk arches around upper-mid heart cutout (v: -180 to -100)
  addSymmetricRibbon([[10, -182], [44, -162], [48, -132], [18, -98]], [8.5, 10.0, 9.5, 8.5], 0.4, "trunk");
  // Suspended solid heart on fold inside upper-mid cutout (v: -156 to -122)
  addCenterBridgePolygon([[0, -154], [15, -165], [24, -148], [13, -132], [0, -120]], 0.38, -154, -120);

  // Lower-mid trunk bridge 3 (v: +24 to +84)
  addCenterBridgePolygon([[0, 22], [34, 42], [38, 64], [0, 86]], 0.35, 22, 86);
  // Trunk arches around central heart medallion (v: -60 to +32)
