// ============================================================================
// STEP 3: RENDER MULTI-LAYERED RAKING CAST SHADOWS & CONTACT SHADOWS
// ============================================================================

function drawPaperShadows() {
  brush.noStroke();

  // 2A. Soft diffused watercolour penumbra under the highest-lifted paper zones
  // (Batch by cool slate-umber watercolour tones for performance and realism)
  let liftedZones = [
    // Right outer curling wing (highest lift Z ~ 32-44)
    { u: 345, v: -220, rx: 68, ry: 95 },
    { u: 365, v: -40, rx: 72, ry: 105 },
    { u: 355, v: 150, rx: 70, ry: 100 },
    { u: 310, v: 310, rx: 65, ry: 80 },
    { u: 255, v: -335, rx: 60, ry: 70 },
    // Left outer curling wing (moderate lift Z ~ 24-32)
    { u: -345, v: -210, rx: 58, ry: 85 },
    { u: -365, v: -30, rx: 62, ry: 95 },
    { u: -350, v: 160, rx: 60, ry: 90 },
    { u: -300, v: 310, rx: 55, ry: 75 },
    // Central mountain fold ridge (lifted Z ~ 18)
    { u: 0, v: -350, rx: 45, ry: 65 },
    { u: 0, v: -140, rx: 42, ry: 85 },
    { u: 0, v: 60, rx: 45, ry: 90 },
    { u: 0, v: 270, rx: 50, ry: 85 }
  ];

  brush.fillBleed(0.32, "out");
  brush.fillTexture(0.45, 0.2);
  brush.fill("#46525e", 42); // Cool Payne's grey / north-light shadow wash
  for (let z of liftedZones) {
    let p = projectUV(z.u, z.v);
    drawKnotEllipse(p.sx + 4, p.sy + 3, z.rx, z.ry, -8);
  }
  brush.noFill();

  // 2B. Soft blurred penumbra strokes for lifted shapes (Z > 11)
  for (let sh of paperShapes) {
    if (sh.zAvg > 11.0) {
      let col = sh.zAvg > 22 ? "#495461" : "#38424d";
      let w = map(sh.zAvg, 11, 38, 0.7, 1.85, true);
      brush.set("shadow_blur", col, w);
      let sPts = sh.pts.map(p => [p.sx + 2.5, p.sy + 2.0]);
      sPts.push(sPts[0]);
      brush.spline(sPts, sh.curvature);
    }
  }

  // 2C. Core projected cast shadow of every paper ribbon/polygon on the pine wood
  // Using translucent cool slate-umber wash so wood grain shows clearly through the shadow
  brush.noStroke();
  for (let sh of paperShapes) {
    // Contact zones (low Z) have darker, tighter shadows; high-lifted zones have lighter, diffused shadows
    let alpha = Math.floor(map(sh.zAvg, 2, 36, 128, 68, true));
    let shadowHex = sh.zAvg < 9 ? "#232a33" : (sh.zAvg < 20 ? "#2f3844" : "#3d4754");
    brush.wash(shadowHex, alpha);
    brush.beginShape(sh.curvature);
    for (let p of sh.pts) {
      brush.vertex(p.sx, p.sy);
    }
    brush.endShape(true);
  }
  brush.noWash();

  // 2D. Razor-sharp dark contact shadow accent where paper nearly touches the tabletop (Z < 8.5)
  for (let sh of paperShapes) {
    if (sh.zAvg < 9.5) {
      brush.set("2B", "#181d24", map(sh.zAvg, 1.5, 9.5, 0.85, 0.35, true));
      let cPts = sh.pts.map(p => [p.sx, p.sy]);
      cPts.push(cPts[0]);
      brush.spline(cPts, sh.curvature);
    }
  }
}

