// STEP 4: STRAY PAPER-CUTTING SHAVINGS ON THE TABLETOP
// ============================================================================

function drawStrayCuttings() {
  // Tiny crescent & diamond black paper snippets resting near the cutting on the bench
  let scraps = [
    { x: 145, y: 895, len: 11, ang: 28 },
    { x: 168, y: 922, len: 7.5, ang: -42 },
    { x: 1025, y: 865, len: 12.5, ang: 115 },
    { x: 1055, y: 810, len: 8.5, ang: 64 },
    { x: 205, y: 265, len: 9.0, ang: -18 },
    { x: 965, y: 195, len: 10.5, ang: 142 },
    { x: 585, y: 1065, len: 8.0, ang: 12 }
  ];

  for (let sc of scraps) {
    let rad = sc.ang * (Math.PI / 180);
    let ca = Math.cos(rad);
    let sa = Math.sin(rad);
    let na = -sa;
    let nb = ca;

    let poly = [
      [sc.x, sc.y],
      [sc.x + ca * sc.len * 0.5 + na * 2.4, sc.y + sa * sc.len * 0.5 + nb * 2.4],
      [sc.x + ca * sc.len, sc.y + sa * sc.len],
      [sc.x + ca * sc.len * 0.5 + na * 0.5, sc.y + sa * sc.len * 0.5 + nb * 0.5]
    ];

    // Tiny 1.5px contact shadow
    brush.noStroke();
    brush.wash("#232a33", 150);
    brush.beginShape(0.2);
    for (let pt of poly) brush.vertex(pt[0] + 1.6, pt[1] + 1.2);
    brush.endShape(true);

    // Matte black paper snippet
    brush.wash("#14181f", 252);
    brush.beginShape(0.2);
    for (let pt of poly) brush.vertex(pt[0], pt[1]);
    brush.endShape(true);
    brush.noWash();

    // Micro grey edge fiber on snippet
    brush.set("paper_fiber", "#7d8896", 0.55);
    brush.line(poly[0][0], poly[0][1], poly[1][0], poly[1][1]);
  }
}

// ============================================================================
// STEP 5: MATTE CARBON-BLACK PAPER BODY & 3D SURFACE SHADING
// ============================================================================

function drawMatteBlackPaper() {
  // 5A. Physical paper thickness under-bevel (~0.85px offset on shadow side)
  brush.noStroke();
  brush.wash("#262e38", 230);
  for (let sh of paperShapes) {
    brush.beginShape(sh.curvature);
    for (let p of sh.pts) {
      brush.vertex(p.px + 0.85, p.py + 0.85);
    }
    brush.endShape(true);
  }

  // 5B. Primary Matte Carbon-Black Ink Fill
  // Using high-opacity wash (#13171e) so all overlapping ribbons fuse into one continuous cut sheet
  for (let sh of paperShapes) {
    let slopeU = getPaperSlopeU(sh.uAvg, sh.vAvg);
    // Subtle cool-slate value shift depending on whether the 3D curl faces the upper-left light
    let col = "#13171e";
    if (slopeU > 0.035) {
      col = "#191f28"; // Tilted toward cool raking light (left side of crease & right outer curl)
    } else if (slopeU < -0.035) {
      col = "#0e1117"; // Tilted away from raking light (right side of central mountain crease)
    }
    brush.wash(col, 254);
    brush.beginShape(sh.curvature);
    for (let p of sh.pts) {
      brush.vertex(p.px, p.py);
    }
    brush.endShape(true);
  }
  brush.noWash();

  // 5C. Velvety matte paper tooth & directional light sheen across the 3D paper surface
  for (let i = 0; i < paperShapes.length; i++) {
    let sh = paperShapes[i];
    if (sh.pts.length < 3) continue;
    let p0 = sh.pts[0];
    let pMid = sh.pts[Math.floor(sh.pts.length / 2)];
    let slopeU = getPaperSlopeU(sh.uAvg, sh.vAvg);

    if (slopeU > 0.03 && i % 2 === 0) {
      // Cool slate-grey paper tooth catching raking light on upturned curl
      brush.set("matte_tooth", "#343e4b", 0.55);
      brush.line(p0.px, p0.py, pMid.px, pMid.py);
    } else if (slopeU < -0.03 && i % 2 === 0) {
      // Deep carbon velvet on shadowed slope just right of the central fold
      brush.set("matte_tooth", "#07090c", 0.65);
      brush.line(p0.px, p0.py, pMid.px, pMid.py);
    }

    // Fine fibrous paper grain strokes inside wider trunk, heart and bird bodies
    if (sh.tag === "trunk" || sh.tag === "center" || sh.tag === "bird") {
      brush.set("2B", slopeU > 0 ? "#262e38" : "#0b0d12", 0.45);
      brush.line(
        (p0.px + pMid.px) * 0.5 - 3,
        (p0.py + pMid.py) * 0.5 - 3,
        pMid.px,
        pMid.py
      );
    }
  }
}

// ============================================================================
// STEP 6: CENTRAL FOLD CREASE CATCHING A DULL COOL-GREY HIGHLIGHT
// ============================================================================

function drawCentralFoldCrease() {
  // Only render the crease along intervals of v where black paper physically crosses u = 0!
  for (let interval of spineIntervals) {
    let vStart = interval[0] + 1.2;
    let vEnd = interval[1] - 1.2;
    if (vEnd <= vStart) continue;

    let steps = Math.max(4, Math.floor((vEnd - vStart) / 5));
    let ridgePts = [];
    let leftBevelPts = [];
    let rightShadowPts = [];

    for (let s = 0; s <= steps; s++) {
      let v = vStart + (vEnd - vStart) * (s / steps);
      let pCenter = projectUV(0, v);
      let pLeft = projectUV(-2.2, v);
      let pRight = projectUV(2.4, v);

      let jitter = (noise(v * 0.15) - 0.5) * 0.7;
      ridgePts.push([pCenter.px + jitter, pCenter.py]);
      leftBevelPts.push([pLeft.px, pLeft.py]);
      rightShadowPts.push([pRight.px, pRight.py]);
    }

    // 1. Soft bruised-paper transition on the lit left slope of the fold
    brush.set("HB", "#38424f", 0.85);
    brush.spline(leftBevelPts, 0.3);

    // 2. Crisp shadow drop-off immediately to the right of the mountain crease
    brush.set("2B", "#080a0d", 0.95);
    brush.spline(rightShadowPts, 0.3);

    // 3. Dull cool-grey highlight along the stressed apex of the fold
    brush.set("2H", "#6f7b8a", 0.72);
    brush.spline(ridgePts, 0.3);

    // 4. Finer broken silver-slate highlight & microscopic transverse fold-stress fibres
    for (let i = 0; i < ridgePts.length - 1; i++) {
      let p1 = ridgePts[i];
      let p2 = ridgePts[i + 1];
      if (random() < 0.82) {
        brush.set("paper_fiber", random() < 0.5 ? "#8e9ba8" : "#5c6775", random(0.45, 0.8));
        brush.line(p1[0], p1[1], p2[0], p2[1]);
      }
      // Tiny transverse cracked-dye fibres across the fold ridge
      if (random() < 0.65) {
        let mx = (p1[0] + p2[0]) * 0.5;
        let my = (p1[1] + p2[1]) * 0.5;
        let len = random(1.4, 3.2);
        let ang = random(-25, 25) * (Math.PI / 180);
        brush.set("paper_fiber", "#7c8896", 0.45);
        brush.line(
          mx - Math.cos(ang) * len,
          my - Math.sin(ang) * len,
          mx + Math.cos(ang) * len * 0.6,
          my + Math.sin(ang) * len * 0.6
        );
      }
    }
  }
}

// ============================================================================
// STEP 7: CUT EDGES & MICROSCOPIC FEATHERED FIBRES IN SHARP PENCIL
// ============================================================================

function drawCutEdgeFibres() {
  // Light vector from upper-left raking studio source
  const lx = -0.78;
  const ly = -0.62;

  for (let sh of paperShapes) {
    let pts = sh.pts;
    let n = pts.length;
    if (n < 3) continue;

    // Compute signed area in screen space to ensure outward-pointing edge normals
    let area = 0;
    for (let i = 0; i < n; i++) {
      let p1 = pts[i];
      let p2 = pts[(i + 1) % n];
      area += p1.px * p2.py - p2.px * p1.py;
    }
    let winding = area >= 0 ? 1 : -1;

    for (let i = 0; i < n; i++) {
      let p1 = pts[i];
      let p2 = pts[(i + 1) % n];
      let dx = p2.px - p1.px;
      let dy = p2.py - p1.py;
      let segLen = Math.hypot(dx, dy);
      if (segLen < 1.5) continue;

      let tx = dx / segLen;
      let ty = dy / segLen;
      // Outward normal
      let nx = winding * ty;
      let ny = winding * (-tx);

      // Dot product with upper-left raking light
      let lightDot = nx * lx + ny * ly;
      let zMid = (p1.z + p2.z) * 0.5;

      if (lightDot > 0.18) {
        // Cut edge faces the cool raking light -> thin slate-grey paper thickness rim!
        let rimCol = lightDot > 0.62
          ? (zMid > 18 ? "#95a2b0" : "#788492")
          : "#515c69";
        let rimW = map(lightDot, 0.18, 1.0, 0.35, 0.72) * map(zMid, 2, 36, 0.85, 1.2, true);
        brush.set("2H", rimCol, rimW);
        brush.line(p1.px, p1.py, p2.px, p2.py);
      } else {
        // Shadowed cut edge -> crisp carbon-black scalpel contour
        brush.set("rotring", "#0c0f14", 0.38);
        brush.line(p1.px, p1.py, p2.px, p2.py);
      }

      // Sprout tiny feathered paper fibres in sharp pencil along the cut edge
      // Higher density at tight turns, vertices, heart cusps & lifted edges
      let numFibers = Math.floor(segLen / 11) + (random() < 0.55 ? 1 : 0);
      for (let f = 0; f < numFibers; f++) {
        let t = random(0.05, 0.95);
        let fx = p1.px + dx * t;
        let fy = p1.py + dy * t;

        // Fibres peel slightly outward from the cut edge at a shallow tangential angle (12–32 deg)
        let peelDir = random() < 0.75 ? 1 : -1;
        let peelAng = Math.atan2(ty * peelDir, tx * peelDir) + random(0.18, 0.52) * winding * peelDir;
        let fLen = random(1.6, 4.2);

        let ex = fx + Math.cos(peelAng) * fLen + nx * 0.4;
        let ey = fy + Math.sin(peelAng) * fLen + ny * 0.4;

        let fiberCol;
        if (lightDot > 0.15) {
          fiberCol = random() < 0.6 ? "#7e8a98" : "#56616e";
        } else {
          fiberCol = random() < 0.65 ? "#222933" : "#434d59";
        }

        brush.set("paper_fiber", fiberCol, random(0.38, 0.72));
        brush.line(fx, fy, ex, ey);
      }
    }
  }
}

