// ============================================================================
// GEOMETRY & SMOOTH DISTANCE FIELD (COB + PEELED HUSKS + STEM)
// ============================================================================

function cobSpine(s) {
  // Diagonal spine from bottom-left base (365, 825) to top-right tip (990, 195)
  let x0 = 365, y0 = 825;
  let x1 = 990, y1 = 195;
  let dx = x1 - x0, dy = y1 - y0;
  let len = Math.hypot(dx, dy);
  let tx = dx / len, ty = dy / len;
  let nx = -ty, ny = tx; // Points toward upper-left (-0.71, -0.704)

  // Subtle organic upward bow along the ear
  let bow = -16 * Math.sin(s * Math.PI);
  let dBow = -16 * Math.PI * Math.cos(s * Math.PI) / len;

  let cx = x0 + dx * s + nx * bow;
  let cy = y0 + dy * s + ny * bow;

  let ttx = tx + nx * dBow;
  let tty = ty + ny * dBow;
  let tLen = Math.hypot(ttx, tty);
  ttx /= tLen;
  tty /= tLen;
  let nnx = -tty, nny = ttx;

  return { x: cx, y: cy, tx: ttx, ty: tty, nx: nnx, ny: nny, len: len };
}

function cobRadius(s) {
  let baseTap = 0.72 + 0.28 * Math.sin(Math.min(1, s / 0.20) * (Math.PI / 2));
  let tipTap = Math.pow(Math.max(0, 1 - Math.pow(s, 1.82)), 0.70);
  return 15 + 114 * baseTap * tipTap;
}

function evalCubicBezier(p0, p1, p2, p3, t) {
  let u = 1 - t;
  let b0 = u * u * u;
  let b1 = 3 * u * u * t;
  let b2 = 3 * u * t * t;
  let b3 = t * t * t;
  let x = b0 * p0[0] + b1 * p1[0] + b2 * p2[0] + b3 * p3[0];
  let y = b0 * p0[1] + b1 * p1[1] + b2 * p2[1] + b3 * p3[1];

  let db0 = -3 * u * u;
  let db1 = 3 * u * u - 6 * u * t;
  let db2 = 6 * u * t - 3 * t * t;
  let db3 = 3 * t * t;
  let tx = db0 * p0[0] + db1 * p1[0] + db2 * p2[0] + db3 * p3[0];
  let ty = db0 * p0[1] + db1 * p1[1] + db2 * p2[1] + db3 * p3[1];
  let len = Math.hypot(tx, ty) || 1;
  tx /= len;
  ty /= len;
  return { x, y, tx, ty, nx: -ty, ny: tx };
}

function getHuskDefinitions() {
  return [
    // Husk 0: Grand Upper-Left Sweeping Husk
    {
      p0: [375, 815], p1: [255, 650], p2: [160, 450], p3: [118, 235],
      w0: 60, wMid: 88, w1: 3, tMid: 0.36, arch: -22,
      palette: "upper_left", layer: "back",
      curlStart: 0.78, curlOffset: [42, 48]
    },
    // Husk 1: Mid-Left Arching Husk
    {
      p0: [358, 835], p1: [220, 745], p2: [120, 650], p3: [68, 520],
      w0: 52, wMid: 72, w1: 3, tMid: 0.38, arch: 18,
      palette: "mid_left", layer: "back",
      curlStart: 0.80, curlOffset: [32, -36]
    },
    // Husk 2: Lower-Left Curling Husk
    {
      p0: [342, 852], p1: [215, 862], p2: [128, 915], p3: [82, 1025],
      w0: 46, wMid: 62, w1: 3, tMid: 0.40, arch: -16,
      palette: "lower_left", layer: "back",
      curlStart: 0.82, curlOffset: [38, -22]
    },
    // Husk 3: Grand Lower-Right Sweeping Husk
    {
      p0: [388, 832], p1: [565, 915], p2: [790, 940], p3: [1035, 1015],
      w0: 66, wMid: 96, w1: 4, tMid: 0.42, arch: 26,
      palette: "lower_right", layer: "back",
      curlStart: 0.76, curlOffset: [-54, -42]
    },
    // Husk 4: Bottom-Center Drooping Husk
    {
      p0: [365, 855], p1: [435, 975], p2: [535, 1068], p3: [675, 1125],
      w0: 52, wMid: 74, w1: 3, tMid: 0.38, arch: -18,
      palette: "bottom_center", layer: "back",
      curlStart: 0.82, curlOffset: [-28, -38]
    }
  ];
}

function huskHalfWidth(h, t) {
  if (t < h.tMid) {
    let u = t / h.tMid;
    return h.w0 + (h.wMid - h.w0) * Math.sin(u * (Math.PI / 2));
  } else {
    let u = (t - h.tMid) / (1 - h.tMid);
    return h.w1 + (h.wMid - h.w1) * Math.pow(1 - u, 1.35);
  }
}

function buildSilhouetteSDF() {
  sdfDiscs = [];

  // 1. Sample Cob Spine
  for (let i = 0; i <= 26; i++) {
    let s = i / 26;
    let sp = cobSpine(s);
    let r = cobRadius(s) + 4;
    sdfDiscs.push({ x: sp.x, y: sp.y, r: r });
  }

  // 2. Sample Silk Crown at Tip
  let silkPts = [
    [1015, 170, 26], [1045, 145, 24], [1080, 120, 20],
    [1105, 105, 14], [1065, 175, 22], [1095, 185, 15]
  ];
  for (let sp of silkPts) {
    sdfDiscs.push({ x: sp[0], y: sp[1], r: sp[2] });
  }

  // 3. Sample Husks
  let husks = getHuskDefinitions();
  for (let h of husks) {
    for (let i = 0; i <= 16; i++) {
      let t = i / 16;
      let b = evalCubicBezier(h.p0, h.p1, h.p2, h.p3, t);
      let w = huskHalfWidth(h, t);
      sdfDiscs.push({ x: b.x, y: b.y, r: w + 3 });
    }
  }

  // 4. Sample Stem / Shank
  let st0 = [348, 848], st1 = [285, 912], st2 = [225, 982], st3 = [165, 1055];
  for (let i = 0; i <= 10; i++) {
    let t = i / 10;
    let b = evalCubicBezier(st0, st1, st2, st3, t);
    let r = 44 * (1 - 0.34 * t) + 5 * Math.sin(t * Math.PI * 3);
    sdfDiscs.push({ x: b.x, y: b.y, r: r });
  }
}

// Smooth minimum (log-sum-exp) distance field + exact analytical gradient
function evalSDF(x, y) {
  let k = 26.0;
  let invK = 1.0 / k;
  let minD = 1e9;
  let n = sdfDiscs.length;

  for (let i = 0; i < n; i++) {
    let d = Math.hypot(x - sdfDiscs[i].x, y - sdfDiscs[i].y) - sdfDiscs[i].r;
    if (d < minD) minD = d;
  }

  let sumW = 0;
  let gx = 0;
  let gy = 0;

  for (let i = 0; i < n; i++) {
    let dx = x - sdfDiscs[i].x;
    let dy = y - sdfDiscs[i].y;
    let dist = Math.hypot(dx, dy) || 1e-6;
    let d = dist - sdfDiscs[i].r;
    let diff = d - minD;
    if (diff < 180) {
      let w = Math.exp(-diff * invK);
      sumW += w;
      gx += w * (dx / dist);
      gy += w * (dy / dist);
    }
  }

  let val = minD - k * Math.log(sumW);
  let gLen = Math.hypot(gx, gy) || 1;
  return { f: val, gx: gx / gLen, gy: gy / gLen };
}

// ============================================================================
// LAYER 1: CONCENTRIC BACKGROUND RIPPLES IN COBALT & ACID LIME
// ============================================================================

function drawBackgroundRipples() {
  let dStart = -6.0;
  let dEnd = 845.0;
  let dStep = 3.55;
  let ringIdx = 0;

  for (let d = dStart; d <= dEnd; d += dStep, ringIdx++) {
    let loopPts = traceIsolineLoop(d);
    if (loopPts.length < 6) continue;

    // Split into visible canvas segments inside [-18, 1218]^2
    let chains = clipLoopToCanvas(loopPts, -18, 1218);

    for (let chain of chains) {
      // Subdivide long chains into ~20-vertex overlapping chunks so color shifts smoothly along the contour
      let chunkSize = 18;
      for (let start = 0; start < chain.length - 2; start += chunkSize - 1) {
        let end = Math.min(chain.length, start + chunkSize);
        let sub = chain.slice(start, end);
        if (sub.length < 3) continue;

        let midPt = sub[Math.floor(sub.length / 2)];
        let style = getBackgroundRippleStyle(d, midPt[0], midPt[1], ringIdx);

        brush.set(style.brushName, style.color, style.weight);
        safeSpline(sub, 0.45);

        // Add crisp yarn-fiber core highlight on selected crests
        if (style.accentColor) {
          brush.set("yarn_fine", style.accentColor, style.accentWeight);
          safeSpline(sub, 0.45);
        }
      }
    }
  }
}

function traceIsolineLoop(targetD) {
  // Raycast toward upper-left from cob center (580, 560) to find initial point on F(x, y) = targetD
  let x = 580, y = 560;
  let dirX = -0.7071, dirY = -0.7071;
  let r = Math.max(40, targetD + 135);
  x += dirX * r;
  y += dirY * r;

  // Newton refinement onto exact isoline
  for (let iter = 0; iter < 10; iter++) {
    let res = evalSDF(x, y);
    let err = res.f - targetD;
    x -= err * res.gx;
    y -= err * res.gy;
    if (Math.abs(err) < 0.08) break;
  }

  let x0 = x, y0 = y;
  let pts = [[x, y]];
  let ds = 15.0;
  let maxSteps = 950;

  for (let step = 0; step < maxSteps; step++) {
    let res = evalSDF(x, y);
    // Tangent vector (-gy, gx)
    let tx = -res.gy;
    let ty = res.gx;
    x += tx * ds;
    y += ty * ds;

    // 2-step Newton projection back onto F(x, y) = targetD
    for (let c = 0; c < 2; c++) {
      let r2 = evalSDF(x, y);
      let err = r2.f - targetD;
      x -= err * r2.gx;
      y -= err * r2.gy;
    }

    pts.push([x, y]);

    if (step > 18) {
      let dx = x - x0, dy = y - y0;
      if (dx * dx + dy * dy < ds * ds * 1.15) {
        pts.push([x0, y0]);
        break;
      }
    }
  }

  return pts;
}

function clipLoopToCanvas(pts, minB, maxB) {
  let chains = [];
  let current = [];

  for (let i = 0; i < pts.length; i++) {
    let p = pts[i];
    let inside = p[0] >= minB && p[0] <= maxB && p[1] >= minB && p[1] <= maxB;
    if (inside) {
      current.push(p);
    } else {
      if (current.length >= 3) chains.push(current);
      current = [];
    }
  }
  if (current.length >= 3) chains.push(current);
  return chains;
}

function getBackgroundRippleStyle(d, x, y, ringIdx) {
  // Global twilight light factor: brighter on upper-left, deeper twilight toward lower-right
  let light = constrain(1.0 - ((x - 150) * 0.45 + (y - 150) * 0.55) / 1100, 0, 1);
  // Proximity glow near the corn ear
  let aura = Math.exp(-Math.max(0, d) / 140.0);

  // Angle around center for subtle organic wave undulation
  let ang = Math.atan2(y - 600, x - 560);
  let waveDist = Math.max(0, d + 10) + 12 * Math.sin(ang * 3.0 + d * 0.018);

  // Inner twilight shadow halo right against the corn & husks (d < 18)
  if (d < 18) {
    let t = constrain((d + 6) / 24, 0, 1);
    let col = lerpHexColor("#0f0c29", "#172b6e", t);
    return {
      brushName: "yarn_bold",
      color: col,
      weight: 1.08,
      accentColor: ringIdx % 2 === 0 ? "#1f3d96" : null,
      accentWeight: 0.7
    };
  }

  // Periodic concentric wave packets of Cobalt and Acid Lime
  let period = 72.0;
  let phase = (waveDist % period) / period; // [0, 1)

  let col, accent = null;
  if (phase < 0.56) {
    // Cobalt Wave Band (deep twilight indigo -> royal cobalt -> electric cerulean cobalt)
    let u = phase / 0.56;
    let cDark = lerpHexColor("#11153b", "#172059", light);
    let cMid = lerpHexColor("#19388f", "#2454d6", 0.35 + 0.65 * light);
    let cBright = lerpHexColor("#1c60b8", "#2687e8", 0.4 + 0.6 * light + 0.2 * aura);

    if (u < 0.45) {
      col = lerpHexColor(cDark, cMid, u / 0.45);
    } else {
      col = lerpHexColor(cMid, cBright, (u - 0.45) / 0.55);
    }
    if (ringIdx % 2 === 0) {
      accent = lerpHexColor(col, "#4ea8ff", 0.22 * light);
    }
  } else if (phase < 0.65) {
    // Twilight Teal Bridge
    let u = (phase - 0.56) / 0.09;
    let cTeal = lerpHexColor("#176878", "#1fa39c", light);
    let cChart = lerpHexColor("#449e3b", "#6fd136", light);
    col = lerpHexColor(cTeal, cChart, u);
  } else if (phase < 0.89) {
    // Acid Lime Crest Band
    let u = (phase - 0.65) / 0.24;
    let crest = Math.sin(u * Math.PI); // Peaks in the middle of the acid-lime band
    let cLimeBase = lerpHexColor("#65b825", "#8fe026", light);
    let cLimePeak = lerpHexColor("#b2ed28", "#e2ff47", 0.45 + 0.55 * light);
    col = lerpHexColor(cLimeBase, cLimePeak, crest);
    if (crest > 0.55) {
      accent = lerpHexColor("#d4ff3b", "#f3ff8c", 0.5 * light);
    }
  } else {
    // Dusky Twilight Return into Cobalt Trough
    let u = (phase - 0.89) / 0.11;
    let cGreen = lerpHexColor("#3a8046", "#54ab3c", light);
    let cIndigo = lerpHexColor("#141b4d", "#1c2b6e", light);
    col = lerpHexColor(cGreen, cIndigo, u);
  }

  return {
    brushName: "yarn",
    color: col,
    weight: 1.15,
    accentColor: accent,
    accentWeight: 0.72
  };
}

// ============================================================================
// LAYER 2 & 6: CORN SILK STRANDS (FLOWING CONTOUR LOCKS)
// ============================================================================

function drawCornSilk(isBackLayer) {
  let count = isBackLayer ? 46 : 26;
  let silkPalettes = [
    ["#3b1730", "#7d2c4d", "#c95b6b", "#f5a38c"],
    ["#422318", "#8f4e22", "#d98f2b", "#ffdb78"],
    ["#29331c", "#5d7a28", "#a8cf38", "#e8ff85"],
    ["#33142e", "#702463", "#bf479b", "#ff99d6"]
  ];

  for (let i = 0; i < count; i++) {
    let frac = i / (count - 1);
    let pal = silkPalettes[i % silkPalettes.length];

    // Start near tip of cob (965..995, 185..225)
    let sx = 965 + 28 * frac + random(-8, 8);
    let sy = 215 - 28 * frac + random(-8, 8);

    // Control points sweeping into a curling lock at top-right
    let spread = (frac - 0.45) * 165;
    let p0 = [sx, sy];
    let p1 = [sx + 48 + spread * 0.25, sy - 52 + spread * 0.35];
    let p2 = [sx + 98 + spread * 0.55, sy - 75 + spread * 0.75];
    let p3 = [sx + 125 + spread * 0.72, sy - 42 + spread * 1.15];

    let totalPts = 22;
    let strand = [];
    for (let k = 0; k <= totalPts; k++) {
      let t = k / totalPts;
      let b = evalCubicBezier(p0, p1, p2, p3, t);
      let wave = Math.sin(t * Math.PI * 3.2 + i * 0.7) * (4 + 8 * t);
      strand.push([b.x + b.nx * wave, b.y + b.ny * wave]);
    }

    // Draw in 3 tonal segments from shadowed base to sunlit tip
    let seg1 = strand.slice(0, 9);
    let seg2 = strand.slice(7, 16);
    let seg3 = strand.slice(14);

    let w = isBackLayer ? 0.92 : 0.78;
    brush.set("yarn", pal[0], w);
    safeSpline(seg1, 0.5);

    brush.set("yarn", pal[1], w * 0.92);
    safeSpline(seg2, 0.5);

    brush.set("yarn", pal[2], w * 0.85);
    safeSpline(seg3, 0.5);

    if (i % 2 === 0) {
      brush.set("yarn_fine", pal[3], 0.72);
      safeSpline(strand.slice(5, 19), 0.5);
    }
  }
}

// ============================================================================
// LAYER 3: WOODY SHANK / STEM & PEELED BACK HUSKS
// ============================================================================

function drawStem() {
  let st0 = [355, 842], st1 = [288, 910], st2 = [225, 982], st3 = [165, 1055];
  let numFibers = 34;

  for (let i = 0; i < numFibers; i++) {
    let u = (i / (numFibers - 1)) * 2 - 1; // [-1, 1] across stem width
    let pts = [];
    let steps = 20;

    for (let k = 0; k <= steps; k++) {
      let t = k / steps;
      let b = evalCubicBezier(st0, st1, st2, st3, t);
      let r = 43 * (1 - 0.34 * t) + 4.5 * Math.sin(t * Math.PI * 3);
      // Cylindrical foreshortening sin(u * PI/2) so edge fibers pack tightly
      let offset = Math.sin(u * (Math.PI / 2)) * r;
      // Slight axial curvature across cylinder rings
      let ringCurve = (1 - Math.cos(u * (Math.PI / 2))) * 10;
      pts.push([
        b.x + b.nx * offset - b.tx * ringCurve,
        b.y + b.ny * offset - b.ty * ringCurve
      ]);
    }

    // 3D cylinder shading across u in [-1, 1] (upper-left u > 0 is lit, lower-right u < 0 is shadowed)
    let cylLight = Math.pow(constrain((u + 0.85) / 1.85, 0, 1), 1.15);
    let vein = 0.5 + 0.5 * Math.sin(i * 1.9);

    let cShadow = lerpHexColor("#1a0e29", "#361c3d", vein);
    let cMid = lerpHexColor("#633938", "#8f5f3b", vein);
    let cLit = lerpHexColor("#b58c42", "#d4cf52", vein);

    let col = cylLight < 0.5
      ? lerpHexColor(cShadow, cMid, cylLight * 2)
      : lerpHexColor(cMid, cLit, (cylLight - 0.5) * 2);

    brush.set("yarn", col, 0.88);
    safeSpline(pts, 0.45);

    if (i % 3 === 0) {
      let fineCol = lerpHexColor(col, "#e8e382", 0.3 * cylLight);
      brush.set("yarn_fine", fineCol, 0.65);
      safeSpline(pts, 0.45);
    }
  }

  // Concentric wood-pith rings on the cut end of the stem at (165, 1055)
  let endB = evalCubicBezier(st0, st1, st2, st3, 1.0);
  let pithColors = ["#1c0f2b", "#3d1e3b", "#6e3838", "#9c6239", "#c99b49", "#bed959", "#f2df94"];
  for (let rIdx = 0; rIdx < 7; rIdx++) {
    let frac = 1.0 - rIdx / 7.2;
    let rx = 28 * frac;
    let ry = 11 * frac;
    let ring = [];
    for (let a = 0; a <= 20; a++) {
      let theta = (a / 20) * Math.PI * 2;
      let px = endB.x + endB.nx * Math.cos(theta) * rx + endB.tx * Math.sin(theta) * ry;
      let py = endB.y + endB.ny * Math.cos(theta) * rx + endB.ty * Math.sin(theta) * ry;
      ring.push([px, py]);
    }
    brush.set("yarn", pithColors[rIdx], 0.72);
    safeSpline(ring, 0.5);
  }
}

function drawBackHusks() {
  let husks = getHuskDefinitions();
  for (let h of husks) {
    drawSingleHuskRibbon(h);
  }
}

function getHuskVeinColor(paletteName, u, t, veinMod) {
  // u in [-1, 1] across width, t in [0, 1] from base to tip
  // Create rich 3D concave/convex fold lighting + dusky twilight anthocyanin blushing
  let foldLight;
  if (paletteName === "lower_right" || paletteName === "bottom_center") {
    // Concave inner cradle with lit upper rim (u > 0.3) and warm outer belly
    foldLight = 0.25 + 0.75 * Math.pow(Math.abs(u - 0.15), 0.9);
    if (u > 0.35) foldLight = Math.min(1, foldLight + 0.25);
  } else {
    // Upper/left husks: brightly lit on upper-left edge, deep twilight fold near center
    foldLight = 0.2 + 0.8 * Math.pow(constrain((u + 0.75) / 1.75, 0, 1), 0.85);
  }

  // Base fold near t = 0 is tucked in deep twilight shadow; tip catches warm glow
  let axialLight = constrain(0.25 + 0.85 * Math.pow(t, 0.55), 0, 1);
  let lum = constrain(foldLight * axialLight + 0.12 * veinMod, 0, 1);

  // Flint corn husk twilight palette: deep plum-indigo -> dusky rose/ochre -> saffron-parchment & chartreuse
  let c0 = "#1c0f2e"; // Deep twilight fold
  let c1 = lerpHexColor("#4a2040", "#59332e", veinMod); // Dusky wine / umber
  let c2 = lerpHexColor("#964952", "#9e7036", veinMod); // Twilight rose / toasted ochre
  let c3 = lerpHexColor("#d69e47", "#9ec938", 0.35 * (1 - t) + 0.45 * veinMod); // Saffron gold & lime vein
  let c4 = "#f5e39b"; // Luminous parchment highlight ridge

  if (lum < 0.25) return lerpHexColor(c0, c1, lum / 0.25);
  if (lum < 0.52) return lerpHexColor(c1, c2, (lum - 0.25) / 0.27);
  if (lum < 0.82) return lerpHexColor(c2, c3, (lum - 0.52) / 0.30);
  return lerpHexColor(c3, c4, (lum - 0.82) / 0.18);
}

function drawSingleHuskRibbon(h) {
  let numVeins = 44;
  let steps = 28;

  for (let i = 0; i < numVeins; i++) {
    let u = (i / (numVeins - 1)) * 2 - 1; // [-1, 1]
    // Slightly tighter vein packing near the rolled edges of the husk leaf
    let uShaped = 0.65 * u + 0.35 * Math.sin(u * (Math.PI / 2));
    let veinMod = 0.5 + 0.5 * Math.sin(i * 1.65);

    let pts = [];
    for (let k = 0; k <= steps; k++) {
      let t = k / steps;
      let b = evalCubicBezier(h.p0, h.p1, h.p2, h.p3, t);
      let w = huskHalfWidth(h, t);

      // Transverse 3D cup/arch displacement across the leaf width
      let cup = (1 - uShaped * uShaped) * h.arch * Math.sin(t * Math.PI);
      let px = b.x + b.nx * (uShaped * w) + b.tx * cup;
      let py = b.y + b.ny * (uShaped * w) + b.ty * cup;
      pts.push([px, py]);
    }

    // Draw each longitudinal vein in 3 overlapping tonal segments from base to tip
    let segBounds = [[0, 11, 0.18], [9, 20, 0.52], [18, steps + 1, 0.85]];
    for (let sb of segBounds) {
      let sub = pts.slice(sb[0], sb[1]);
      let col = getHuskVeinColor(h.palette, uShaped, sb[2], veinMod);
      brush.set("yarn", col, 0.86);
      safeSpline(sub, 0.45);

      if (i % 3 === 0 || Math.abs(u) > 0.86) {
        let detailCol = lerpHexColor(col, "#fff0b8", 0.22 * veinMod);
        brush.set("yarn_fine", detailCol, 0.68);
        safeSpline(sub, 0.45);
      }
    }
  }

  // Curled-over 3D tip flap on each husk
  if (h.curlStart) {
    let flapVeins = 18;
    for (let i = 0; i < flapVeins; i++) {
      let u = (i / (flapVeins - 1)) * 2 - 1;
      let flapPts = [];
      let flapSteps = 12;
      for (let k = 0; k <= flapSteps; k++) {
        let f = k / flapSteps;
        let t = h.curlStart + (1 - h.curlStart) * f;
        let b = evalCubicBezier(h.p0, h.p1, h.p2, h.p3, t);
        let w = huskHalfWidth(h, t) * 1.15;
        let curlFold = Math.pow(f, 1.5);
        let px = b.x + b.nx * (u * w) + h.curlOffset[0] * curlFold;
        let py = b.y + b.ny * (u * w) + h.curlOffset[1] * curlFold;
        flapPts.push([px, py]);
      }
      let col = i === 0 || i === flapVeins - 1
        ? "#2a1438"
        : lerpHexColor("#c47c44", "#f0d978", 0.35 + 0.65 * (i / flapVeins));
      brush.set("yarn", col, 0.78);
      safeSpline(flapPts, 0.5);
    }
  }
}

function drawForegroundHusks() {
  // Clasping sheath wrapping over the base of the cob (overlapping lowest kernel rows)
  // Left sheath lobe + Right sheath lobe meeting in an organic V-split at the base
  let lobes = [
    {
      // Upper-left clasping sheath flap
      p0: [332, 855], p1: [375, 785], p2: [425, 725], p3: [492, 655],
      w0: 48, wMid: 58, w1: 6, tMid: 0.42, side: 1
    },
    {
      // Lower-right clasping sheath flap
      p0: [352, 868], p1: [428, 825], p2: [505, 780], p3: [582, 725],
      w0: 52, wMid: 62, w1: 8, tMid: 0.45, side: -1
    }
  ];

  // First draw cast shadow contour lines onto the kernels just beyond each sheath lobe edge
  for (let lobe of lobes) {
    for (let sOff = 1; sOff <= 3; sOff++) {
      let shPts = [];
      for (let k = 0; k <= 18; k++) {
        let t = k / 18;
        let b = evalCubicBezier(lobe.p0, lobe.p1, lobe.p2, lobe.p3, t);
        let w = huskHalfWidth(lobe, t);
        let edgeDir = -lobe.side; // Inner edge facing the exposed kernels
        let px = b.x + b.nx * (edgeDir * w) + b.tx * (sOff * 3.0);
        let py = b.y + b.ny * (edgeDir * w) + b.ty * (sOff * 3.0);
        shPts.push([px, py]);
      }
      brush.set("yarn", sOff === 1 ? "#120821" : "#220f36", 0.9);
      safeSpline(shPts, 0.45);
    }
  }

  // Now thread the foreground sheath lobes with tightly packed parallel veins
  for (let lobe of lobes) {
    let numVeins = 28;
    for (let i = 0; i < numVeins; i++) {
      let u = (i / (numVeins - 1)) * 2 - 1;
      let veinMod = 0.5 + 0.5 * Math.sin(i * 1.8);
      let pts = [];
      for (let k = 0; k <= 20; k++) {
        let t = k / 20;
        let b = evalCubicBezier(lobe.p0, lobe.p1, lobe.p2, lobe.p3, t);
        let w = huskHalfWidth(lobe, t);
        let curve = (1 - u * u) * 14 * Math.sin(t * Math.PI);
        pts.push([
          b.x + b.nx * (u * w) + b.tx * curve,
          b.y + b.ny * (u * w) + b.ty * curve
        ]);
      }

      let light = lobe.side === 1
        ? 0.45 + 0.55 * constrain((u + 1) / 2, 0, 1)
        : 0.20 + 0.55 * constrain((1 - u) / 2, 0, 1);

      let cDark = lerpHexColor("#261236", "#5c2b45", veinMod);
      let cMid = lerpHexColor("#9e5d42", "#AD9B3B", veinMod);
      let cBright = lerpHexColor("#e3b654", "#f7e89e", veinMod);

      let col = light < 0.5
        ? lerpHexColor(cDark, cMid, light * 2)
        : lerpHexColor(cMid, cBright, (light - 0.5) * 2);

      brush.set("yarn", col, 0.85);
      safeSpline(pts.slice(0, 12), 0.45);

      let tipCol = lerpHexColor(col, "#fae696", 0.28);
      brush.set("yarn", tipCol, 0.82);
      safeSpline(pts.slice(10), 0.45);

      if (i % 3 === 0) {
        brush.set("yarn_fine", lerpHexColor(tipCol, "#ffffff", 0.25), 0.65);
        safeSpline(pts, 0.45);
      }
    }
  }
}

// ============================================================================
// LAYER 4 & 5: HYPERREAL MULTICOLOURED FLINT CORN KERNELS
// ============================================================================

function generateFlintCornKernels() {
  // Build non-uniform axial s-positions so kernel height scales naturally with cob radius
  let numRowsAxial = 27;
  let weights = [];
  let sumW = 0;
  for (let i = 0; i < numRowsAxial; i++) {
    let sEst = (i + 0.5) / numRowsAxial;
    let w = 0.52 + 0.48 * (cobRadius(sEst) / 126.0);
    weights.push(w);
    sumW += w;
  }

  let sCenters = [];
  let sDeltas = [];
  let acc = 0.025;
  let span = 0.955;
  for (let i = 0; i < numRowsAxial; i++) {
    let ds = (weights[i] / sumW) * span;
    sCenters.push(acc + ds * 0.5);
    sDeltas.push(ds);
    acc += ds;
  }

  // Create grid of kernel centers in (u, v) surface space + 3D cylindrical coordinates
  let grid = [];
  let allKernels = [];

  // Four primary kernel families: 0=Fuchsia, 1=Turquoise, 2=Saffron, 3=Blood-Orange
  for (let i = 0; i < numRowsAxial; i++) {
    let sBase = sCenters[i];
    let dsBase = sDeltas[i];
    let rCob = cobRadius(sBase);

    // Number of visible ranks across the front hemisphere
    let numPhi = sBase > 0.88 ? 7 : (sBase > 0.76 ? 8 : 9);
    let phiMax = 0.485 * Math.PI;
    let dPhi = (2 * phiMax) / (numPhi - 1);

    let rowArr = [];
    for (let j = 0; j < numPhi; j++) {
      let phiBase = -phiMax + j * dPhi;
      // Organic longitudinal row wave + subtle axial stagger between adjacent ranks
      let rowWave = 0.032 * Math.sin(sBase * 8.5 + j * 1.65);
      let stagger = ((j % 2 === 0 ? 1 : -1) * 0.18 + random(-0.09, 0.09)) * dsBase;

      let s = constrain(sBase + stagger, 0.015, 0.988);
      let phi = phiBase + rowWave + random(-0.02, 0.02);

      let sp = cobSpine(s);
      let rad = cobRadius(s);

      // Surface coordinates (u = axial pixels, v = circumferential arc pixels)
      let u = s * sp.len;
      let v = phi * rad;

      // Natural semi-axes in surface space before Voronoi compression
      let aU = dsBase * sp.len * 0.54 * random(0.95, 1.06);
      let aV = dPhi * rad * 0.55 * random(0.95, 1.06);

      // Assign genetic flint-corn color family (balanced mosaic with occasional organic clusters)
      let fam;
      if (i > 0 && j > 0 && random() < 0.22) {
        fam = grid[i - 1][Math.min(j, grid[i - 1].length - 1)].family;
      } else {
        // Ensure neighbouring kernel rarely repeats the exact same family unless clustered
        let prevFam = j > 0 ? rowArr[j - 1].family : -1;
        fam = Math.floor(random(4));
        if (fam === prevFam && random() < 0.75) {
          fam = (fam + 1 + Math.floor(random(3))) % 4;
        }
      }

      // Variegated secondary accent family on ~22% of kernels (authentic flint corn genetics)
      let secFam = random() < 0.22 ? (fam + 1 + Math.floor(random(3))) % 4 : fam;
      let shadeVar = random(-0.12, 0.12);
      let duskVar = random() < 0.18 ? 0.22 : 0.0; // Occasional deeper twilight jewel kernel

      let kObj = {
        i, j, s, phi, rad, sp,
        u, v, aU, aV,
        family: fam,
        secFamily: secFam,
        shadeVar,
        duskVar,
        weightVor: random(0.94, 1.06),
        depthScore: Math.cos(phi) - 0.16 * s
      };

      rowArr.push(kObj);
      allKernels.push(kObj);
    }
    grid.push(rowArr);
  }

  // Compute Voronoi-compressed plump cushion boundary for each kernel
  let numAngles = 26;
  for (let k of allKernels) {
    // Collect immediate neighbors
    let nbrs = [];
    for (let di = -1; di <= 1; di++) {
      let ri = k.i + di;
      if (ri < 0 || ri >= grid.length) continue;
      for (let m of grid[ri]) {
        if (m === k) continue;
        let du = m.u - k.u;
        let dv = m.v - k.v;
        let dist = Math.hypot(du, dv);
        if (dist < (k.aU + k.aV) * 1.95) {
          nbrs.push({ du, dv, dist, w: m.weightVor });
        }
      }
    }

    // Compute local boundary radii r(theta) in (u, v) surface space
    let rBoundary = [];
    for (let a = 0; a < numAngles; a++) {
      let theta = (a / numAngles) * Math.PI * 2;
      let cu = Math.cos(theta);
      let sv = Math.sin(theta);

      // Plump rounded squircle base radius
      let rSq = Math.pow(
        Math.pow(Math.abs(cu / k.aU), 2.5) + Math.pow(Math.abs(sv / k.aV), 2.5),
        -1 / 2.5
      );

      // Smooth-clamp against Voronoi bisector planes of neighbors
      let rLim = rSq;
      for (let nb of nbrs) {
        let proj = cu * nb.du + sv * nb.dv;
        if (proj > 0.001) {
          let frac = k.weightVor / (k.weightVor + nb.w);
          let rVor = (nb.dist * nb.dist * frac * 0.98) / proj;
          // Smooth minimum between rLim and rVor so corners stay pillowy
          let kk = 3.2;
          rLim = -kk * Math.log(Math.exp(-rLim / kk) + Math.exp(-rVor / kk));
        }
      }
      rBoundary.push(rLim);
    }

    // Smooth rBoundary circularly so every kernel cushion is silky-smooth
    let rSmooth = [];
    for (let a = 0; a < numAngles; a++) {
      let prev = rBoundary[(a - 1 + numAngles) % numAngles];
      let curr = rBoundary[a];
      let next = rBoundary[(a + 1) % numAngles];
      rSmooth.push(0.22 * prev + 0.56 * curr + 0.22 * next);
    }
    k.rBoundary = rSmooth;

    // Compute 3D lighting on this kernel's position on the cob cylinder
    // Key light from upper-left: phi_light = -0.30 * PI
    let cylDot = Math.cos(k.phi + 0.30 * Math.PI);
    k.cobLight = constrain(0.18 + 0.82 * Math.pow(constrain((cylDot + 0.35) / 1.35, 0, 1), 1.15), 0.08, 1.0);
  }

  // Sort kernels back-to-front (edge/limb kernels first, center-spine kernels on top)
  allKernels.sort((a, b) => a.depthScore - b.depthScore);
  return allKernels;
}

// Project a point on kernel k at normalized ring parameter t in [-0.2, 1.0] and angle index a
function projectKernelPoint(k, t, a, numAngles) {
  let theta = (a / numAngles) * Math.PI * 2;
  let cu = Math.cos(theta);
  let sv = Math.sin(theta);

  // Outer Voronoi cushion radius at t = 0
  let rOuter = k.rBoundary[a];

  // Specular highlight center shifted toward upper-left key light on the kernel dome
  let shiftU = k.aU * 0.18;
  let shiftV = -k.aV * (0.22 * Math.cos(k.phi * 0.65) + 0.06);

  // Size of bare glossy highlight oval (larger on sunlit kernels, crisp pinpoint on shadowed side)
  let hScale = 0.21 + 0.09 * k.cobLight;
  let rHighU = k.aU * hScale * 0.82;
  let rHighV = k.aV * hScale * 1.08;

  let duOuter = cu * rOuter;
  let dvOuter = sv * rOuter;

  let duHigh = shiftU + cu * rHighU;
  let dvHigh = shiftV + sv * rHighV;

  // Smooth interpolation from outer boundary (t=0) to highlight rim (t=1)
  let du, dv, rho;
  if (t <= 0) {
    let expand = 1.0 - t * 1.15; // For t < 0 (crevice mortar rings)
    du = duOuter * expand;
    dv = dvOuter * expand;
    rho = 1.0;
  } else {
    let easeT = Math.pow(t, 0.94);
    du = duOuter + (duHigh - duOuter) * easeT;
    dv = dvOuter + (dvHigh - dvOuter) * easeT;
    rho = 1.0 - easeT * 0.82;
  }

  let uPt = k.u + du;
  let vPt = k.v + dv;

  let sPt = constrain(uPt / k.sp.len, 0.005, 0.995);
  let sp = cobSpine(sPt);
  let rad = cobRadius(sPt);
  let phiPt = constrain(vPt / rad, -0.53 * Math.PI, 0.53 * Math.PI);

  // 3D dome bulge height h(rho): bulges outward along cylinder normal (sin(phi)) and slightly forward
  let domeH = 9.5 * Math.sqrt(Math.max(0, 1.0 - 0.88 * rho * rho));

  let across = (rad + domeH) * Math.sin(phiPt);
  // Perspective curvature of cylinder rings + dome shingle
  let axialCurve = -0.15 * rad * (1.0 - Math.cos(phiPt)) + 0.22 * domeH * Math.cos(phiPt);

  let x = sp.x + sp.nx * across + sp.tx * axialCurve;
  let y = sp.y + sp.ny * across + sp.ty * axialCurve;
  return [x, y];
}

function drawCobCreviceBed(kernels) {
  let numAngles = 26;
  // Interlocking dark twilight crevice rings around every kernel so zero bare ground leaks between kernels
  for (let k of kernels) {
    let creviceRings = [-0.22, -0.09];
    for (let rIdx = 0; rIdx < creviceRings.length; rIdx++) {
      let t = creviceRings[rIdx];
      let pts = [];
      for (let a = 0; a <= numAngles + 1; a++) {
        pts.push(projectKernelPoint(k, t, a % numAngles, numAngles));
      }
      let col = rIdx === 0
        ? lerpHexColor("#0e071c", "#1c0e30", k.cobLight)
        : lerpHexColor("#170b29", "#2b1340", k.cobLight);
      brush.set("yarn", col, 0.95);
      safeSpline(pts, 0.5);
    }
  }
}

function getKernelRingColor(family, t, cobLight, shadeVar, duskVar) {
  // Effective illumination combining global cob 3D light + kernel dome height t + genetic variation
  let domeLight = constrain(cobLight * (0.72 + 0.42 * t) - duskVar + shadeVar * 0.35, 0.05, 1.0);

  // 5-stop palette per family: [Crevice, Dusky Outer, Rich Core Marker, Luminous Inner, Specular Rim]
  let stops;
  if (family === 0) {
    // FUCHSIA
    stops = [
      lerpHexColor("#1c0826", "#2e0c3b", cobLight),
      lerpHexColor("#4f0e4b", "#7a1163", cobLight),
      lerpHexColor("#961471", "#d4198a", cobLight),
      lerpHexColor("#cf2d99", "#ff42b0", cobLight),
      lerpHexColor("#f26bc2", "#ffa6de", cobLight)
    ];
  } else if (family === 1) {
    // TURQUOISE
    stops = [
      lerpHexColor("#081629", "#0c243d", cobLight),
      lerpHexColor("#0d3854", "#115978", cobLight),
      lerpHexColor("#12788f", "#0fb3c9", cobLight),
      lerpHexColor("#22b5c4", "#2ef0f7", cobLight),
      lerpHexColor("#6be8ed", "#b5fcff", cobLight)
    ];
  } else if (family === 2) {
    // SAFFRON
    stops = [
      lerpHexColor("#24111c", "#3b1b1e", cobLight),
      lerpHexColor("#5e3112", "#8c4e11", cobLight),
      lerpHexColor("#a6670f", "#e0920f", cobLight),
      lerpHexColor("#d99c18", "#ffc71f", cobLight),
      lerpHexColor("#f5cb53", "#fff08f", cobLight)
    ];
  } else {
    // BLOOD-ORANGE
    stops = [
      lerpHexColor("#210918", "#380e1d", cobLight),
      lerpHexColor("#5c131d", "#8a1c1b", cobLight),
      lerpHexColor("#a62717", "#de3616", cobLight),
      lerpHexColor("#d94b1e", "#ff621f", cobLight),
      lerpHexColor("#f58349", "#ffb478", cobLight)
    ];
  }

  // Blend stops along concentric ring progression t in [0, 1]
  let pos = constrain(t * (0.82 + 0.22 * domeLight), 0, 1) * 4.0;
  let idx = Math.min(3, Math.floor(pos));
  let frac = pos - idx;
  return lerpHexColor(stops[idx], stops[idx + 1], frac);
}

function drawAllKernels(kernels) {
  let numAngles = 26;
  // Start each closed loop at bottom-right angle (shadowed side of kernel) so highlight side is unbroken
  let startOffset = 3;

  for (let k of kernels) {
    // Number of concentric marker rings scaled to projected pixel size of kernel
    let projWidth = (k.aU + k.aV) * (0.55 + 0.45 * Math.cos(k.phi));
    let numRings = constrain(Math.round(projWidth / 2.25), 5, 9);

    for (let r = 0; r < numRings; r++) {
      let t = r / (numRings - 1); // 0.0 (outer edge) -> 1.0 (bare highlight rim)

      // Occasional variegated flint-corn accent ring
      let fam = (k.secFamily !== k.family && (r === 2 || r === 3)) ? k.secFamily : k.family;
      let col = getKernelRingColor(fam, t, k.cobLight, k.shadeVar, k.duskVar);

      let ringPts = [];
      for (let step = 0; step <= numAngles + 1; step++) {
        let a = (step + startOffset) % numAngles;
        ringPts.push(projectKernelPoint(k, t, a, numAngles));
      }

      // Draw full concentric marker loop
      let w = map(t, 0, 1, 0.84, 0.68);
      brush.set("yarn", col, w);
      safeSpline(ringPts, 0.5);

      // Add 3D directional crescent shading along the lower-right shadowed belly of the kernel dome
      if (r >= 1 && r <= numRings - 2 && r % 2 === 1) {
        let shadowArc = ringPts.slice(0, Math.floor(numAngles * 0.48));
        let shCol = getKernelRingColor(fam, Math.max(0, t - 0.28), k.cobLight * 0.55, k.shadeVar, k.duskVar);
        brush.set("yarn_fine", shCol, 0.68);
        safeSpline(shadowArc, 0.5);
      }

      // Add luminous yarn-fiber highlight crescent hugging the upper-left side of the bare glossy highlight
      if (r === numRings - 1 || r === numRings - 2) {
        let litArc = ringPts.slice(Math.floor(numAngles * 0.46), Math.floor(numAngles * 0.94));
        let rimCol = lerpHexColor(col, "#fff9eb", r === numRings - 1 ? 0.42 * k.cobLight : 0.22 * k.cobLight);
        brush.set("yarn_fine", rimCol, 0.72);
        safeSpline(litArc, 0.5);
      }
    }
  }
}

// ============================================================================
// UTILITIES: SAFE SPLINE & HEX COLOR INTERPOLATION
// ============================================================================

function safeSpline(pts, curvature = 0.5) {
  if (!pts || pts.length < 3) return;
  let clean = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    let dx = pts[i][0] - clean[clean.length - 1][0];
    let dy = pts[i][1] - clean[clean.length - 1][1];
    if (dx * dx + dy * dy > 0.65) {
      clean.push(pts[i]);
    }
  }
  if (clean.length >= 3) {
    brush.spline(clean, curvature);
  } else if (clean.length === 2) {
    brush.line(clean[0][0], clean[0][1], clean[1][0], clean[1][1]);
  }
}

function lerpHexColor(hex1, hex2, amt) {
  let t = constrain(amt, 0, 1);
  let c1 = parseInt(hex1.slice(1), 16);
  let c2 = parseInt(hex2.slice(1), 16);

  let r1 = (c1 >> 16) & 255, g1 = (c1 >> 8) & 255, b1 = c1 & 255;
  let r2 = (c2 >> 16) & 255, g2 = (c2 >> 8) & 255, b2 = c2 & 255;

  let r = Math.round(r1 + (r2 - r1) * t);
  let g = Math.round(g1 + (g2 - g1) * t);
  let b = Math.round(b1 + (b2 - b1) * t);

  return "#" + ((1 << 24) + (r << 16) + (g << 8) + b).toString(16).slice(1);
}

// Hyperreal Slab of Thick Lake Ice — Celadon Glaze, Trapped Bubble Columns & Crackle Network

let frontPoly = [];
let leftPoly = [];
let topPoly = [];
let backRightGhost = [];
let backTopGhost = [];

function interpolateEdge(p1, p2, steps, roughness, seedOffset) {
  let pts = [];
  for (let i = 0; i < steps; i++) {
    let t = i / steps;
    let x = lerp(p1[0], p2[0], t);
    let y = lerp(p1[1], p2[1], t);
    let n = (noise(t * 4.5 + seedOffset) - 0.5) * 2.0;
    let stepJagged = (noise(floor(t * 9) * 1.7 + seedOffset * 2) - 0.5) * 0.8;
    let dx = -(p2[1] - p1[1]);
    let dy = p2[0] - p1[0];
    let len = sqrt(dx * dx + dy * dy) || 1;
    dx /= len;
    dy /= len;
    let offset = (n * 0.7 + stepJagged * 0.3) * roughness * sin(t * 180);
    pts.push([x + dx * offset, y + dy * offset]);
  }
  return pts;
}

function drawShapePoly(pts, curvature = 0.08) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

function pointInPoly(pt, vs) {
  let x = pt[0], y = pt[1];
  let inside = false;
  for (let i = 0, j = vs.length - 1; i < vs.length; j = i++) {
    let xi = vs[i][0], yi = vs[i][1];
    let xj = vs[j][0], yj = vs[j][1];
    let intersect = ((yi > y) !== (yj > y)) &&
      (x < (xj - xi) * (y - yi) / ((yj - yi) || 0.00001) + xi);
    if (intersect) inside = !inside;
  }
  return inside;
}

function segIntersection(a1, a2, b1, b2) {
  let dax = a2[0] - a1[0], day = a2[1] - a1[1];
  let dbx = b2[0] - b1[0], dby = b2[1] - b1[1];
  let denom = dax * dby - day * dbx;
  if (abs(denom) < 1e-6) return null;
  let s = ((a1[0] - b1[0]) * dby - (a1[1] - b1[1]) * dbx) / denom;
  let t = ((a1[0] - b1[0]) * day - (a1[1] - b1[1]) * dax) / denom;
  if (s >= 0 && s <= 1 && t >= 0 && t <= 1) {
    return {
      x: a1[0] + s * dax,
      y: a1[1] + s * day,
      s: s,
      t: t
    };
  }
  return null;
}

function splitPolygonByLine(poly, l1, l2) {
  let leftPts = [];
  let rightPts = [];
  let dx = l2[0] - l1[0];
  let dy = l2[1] - l1[1];

  function sideOf(p) {
    return (p[0] - l1[0]) * dy - (p[1] - l1[1]) * dx;
  }

  for (let i = 0; i < poly.length; i++) {
    let cur = poly[i];
    let nxt = poly[(i + 1) % poly.length];
    let sCur = sideOf(cur);
    let sNxt = sideOf(nxt);

    if (sCur >= 0) leftPts.push(cur);
    if (sCur <= 0) rightPts.push(cur);

    if ((sCur > 0 && sNxt < 0) || (sCur < 0 && sNxt > 0)) {
      let t = sCur / (sCur - sNxt);
      let ix = lerp(cur[0], nxt[0], t);
      let iy = lerp(cur[1], nxt[1], t);
      leftPts.push([ix, iy]);
      rightPts.push([ix, iy]);
    }
  }
  if (leftPts.length >= 3 && rightPts.length >= 3) {
    return [leftPts, rightPts];
  }
  return [poly];
}

function polyCentroid(poly) {
  let cx = 0, cy = 0;
  for (let p of poly) {
    cx += p[0];
    cy += p[1];
  }
  return [cx / poly.length, cy / poly.length];
}

function polyArea(poly) {
  let a = 0;
  for (let i = 0; i < poly.length; i++) {
    let p1 = poly[i];
    let p2 = poly[(i + 1) % poly.length];
    a += p1[0] * p2[1] - p2[0] * p1[1];
  }
  return abs(a) * 0.5;
}

function shrinkPoly(poly, amount) {
  let c = polyCentroid(poly);
  return poly.map(p => {
    let dx = p[0] - c[0];
    let dy = p[1] - c[1];
    let d = sqrt(dx * dx + dy * dy) || 1;
    let f = max(0.1, (d - amount) / d);
    return [c[0] + dx * f, c[1] + dy * f];
  });
}

