function draw() {
  translate(-width / 2, -height / 2);
  background("#edf2f1");

  // =========================================================================
  // 1. DEFINE ICE SLAB GEOMETRY (upright thick slab with left & top bevels)
  // =========================================================================
  let ftl = [368, 192];
  let ftr = [868, 178];
  let fbr = [892, 992];
  let fbl = [346, 1004];

  let btl = [294, 166];
  let btr = [798, 148];
  let bbl = [282, 976];

  let edgeTop = interpolateEdge(ftl, ftr, 18, 9, 11.2);
  let edgeRight = interpolateEdge(ftr, fbr, 26, 14, 23.7);
  let edgeBottom = interpolateEdge(fbr, fbl, 18, 7, 37.1);
  let edgeLeft = interpolateEdge(fbl, ftl, 26, 11, 51.4);

  frontPoly = [...edgeTop, ...edgeRight, ...edgeBottom, ...edgeLeft];

  let backLeftEdge = interpolateEdge(btl, bbl, 26, 12, 64.8);
  let topBackEdge = interpolateEdge(btl, btr, 18, 8, 79.3);

  // Left thickness plane (from back-left to front-left)
  leftPoly = [
    ...backLeftEdge,
    [fbl[0], fbl[1]],
    ...edgeLeft.slice().reverse()
  ];

  // Top thickness plane (from back-top to front-top)
  topPoly = [
    ...topBackEdge,
    [ftr[0], ftr[1]],
    ...edgeTop.slice().reverse()
  ];

  // Internal ghost edges (back face seen refracted inside the ice block)
  backRightGhost = interpolateEdge([808, 160], [830, 968], 24, 11, 91.5);
  backTopGhost = interpolateEdge([358, 218], [812, 160], 16, 7, 104.2);

  // Full silhouette polygon for outer mask reference
  let fullSlabPoly = [
    ...topBackEdge,
    ...edgeRight,
    ...edgeBottom,
    ...backLeftEdge.slice().reverse()
  ];

  // =========================================================================
  // 2. MUTED COOL GREY BACKGROUND & GROUND WASHES (Color-Batched)
  // =========================================================================
  brush.noStroke();

  // Pass A: Broad atmospheric cool grey-blue paper wash
  brush.fill("#d4dcde", 42);
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.45, 0.18);
  drawShapePoly([[40, 40], [1160, 40], [1160, 960], [40, 960]], 0.05);
  drawShapePoly([[90, 80], [1110, 80], [1110, 1130], [90, 1130]], 0.05);

  // Pass B: Deeper muted cool grey halo behind upper/mid slab to make ice glow
  brush.fill("#b4c0c4", 38);
  brush.fillBleed(0.4, "out");
  brush.fillTexture(0.5, 0.22);
  drawShapePoly([[150, 90], [1050, 90], [1030, 930], [170, 930]], 0.12);
  drawShapePoly([[210, 120], [970, 110], [990, 860], [190, 880]], 0.15);

  // Pass C: Concentrated cool slate vignette immediately framing the ice edges
  brush.fill("#98a6ad", 34);
  brush.fillBleed(0.32, "out");
  brush.fillTexture(0.48, 0.25);
  drawShapePoly([[220, 115], [940, 105], [960, 960], [210, 970]], 0.1);
  drawShapePoly([[250, 130], [420, 130], [390, 990], [220, 980]], 0.12);
  drawShapePoly([[790, 130], [965, 145], [985, 975], [810, 975]], 0.12);

  // Pass D: Quiet Ground Plane / Studio Table Washes
  brush.fill("#a7b4b9", 44);
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.42, 0.2);
  drawShapePoly([[40, 935], [1160, 925], [1160, 1165], [40, 1165]], 0.04);
  drawShapePoly([[120, 965], [1080, 960], [1120, 1120], [80, 1125]], 0.06);

  // Pass E: Cast shadow & celadon subsurface glow on the ground plane
  brush.fill("#6f848a", 48);
  brush.fillBleed(0.24, "out");
  brush.fillTexture(0.45, 0.28);
  drawShapePoly([[200, 972], [935, 978], [980, 1045], [160, 1035]], 0.1);
  drawShapePoly([[255, 985], [895, 988], [860, 1025], [275, 1020]], 0.08);

  // Soft jade-green light transmitted onto the wet surface right below the front face
  brush.fill("#688f88", 42);
  brush.fillBleed(0.26, "out");
  brush.fillTexture(0.4, 0.2);
  drawShapePoly([[335, 998], [885, 990], [855, 1075], [360, 1085]], 0.12);
  drawShapePoly([[395, 1002], [810, 996], [775, 1120], [430, 1125]], 0.15);

  // =========================================================================
  // 3. GENERATE CELADON CRACKLE & FRACTURE SUBDIVISION CELLS
  // =========================================================================
  // First, lift the slab interior back to luminous icy brightness using opaque/translucent washes
  brush.wash("#eef5f4", 195);
  drawShapePoly(fullSlabPoly, 0.04);
  brush.wash("#f5faf9", 140);
  drawShapePoly(frontPoly, 0.04);
  brush.noWash();

  // Subdivide the front face into realistic fracture cells (like thick celadon glaze & lake ice)
  let cells = [frontPoly.map(p => [p[0], p[1]])];

  // Primary fracture split lines (spanning the slab)
  let primarySplitLines = [
    [[350, 390], [885, 515]],
    [[348, 695], [888, 625]],
    [[545, 182], [655, 998]],
    [[715, 180], [465, 998]],
    [[360, 275], [875, 315]],
    [[348, 845], [890, 810]]
  ];

  for (let line of primarySplitLines) {
    let nextCells = [];
    for (let c of cells) {
      let res = splitPolygonByLine(c, line[0], line[1]);
      nextCells.push(...res);
    }
    cells = nextCells;
  }

  // Secondary subdivisions within larger cells (arrested cracks)
  for (let pass = 0; pass < 2; pass++) {
    let nextCells = [];
    for (let c of cells) {
      let area = polyArea(c);
      if (area > 16500 && random() < 0.82) {
        let cent = polyCentroid(c);
        let ang = random([18, 42, 74, 108, 138, 162]) + random(-10, 10);
        let rad = 600;
        let l1 = [cent[0] - cos(ang) * rad, cent[1] - sin(ang) * rad];
        let l2 = [cent[0] + cos(ang) * rad, cent[1] + sin(ang) * rad];
        let res = splitPolygonByLine(c, l1, l2);
        nextCells.push(...res);
      } else {
        nextCells.push(c);
      }
    }
    cells = nextCells;
  }

  // =========================================================================
  // 4. LAYERED WATERCOLOR GLAZES INSIDE THE ICE SLAB (Batched by Color!)
  // =========================================================================
  brush.noStroke();

  // --- Batch 1: Pale Celadon Base Glaze (#c4dbd6) ---
  brush.fill("#c4dbd6", 52);
  brush.fillBleed(0.14, "in");
  brush.fillTexture(0.38, 0.22);
  drawShapePoly(frontPoly, 0.04);
  drawShapePoly(topPoly, 0.04);

  // --- Batch 2: Cool Grey-Blue Bevel & Left Thickness Glaze (#7791a1) ---
  brush.fill("#7791a1", 62);
  brush.fillBleed(0.12, "in");
  brush.fillTexture(0.45, 0.3);
  drawShapePoly(leftPoly, 0.04);
  // Also some right-side and lower internal grey-blue refraction zones
  drawShapePoly([[760, 185], [868, 178], [892, 992], [790, 994]], 0.06);
  drawShapePoly([[346, 860], [890, 835], [892, 992], [346, 1004]], 0.06);

  // --- Batch 3: Mid Jade-Celadon Depth Glazes (#7ca39b) ---
  brush.fill("#7ca39b", 48);
  brush.fillBleed(0.15, "in");
  brush.fillTexture(0.42, 0.26);
  drawShapePoly([[375, 230], [845, 220], [860, 940], [365, 950]], 0.08);
  for (let i = 0; i < cells.length; i++) {
    let cent = polyCentroid(cells[i]);
    let n = noise(cent[0] * 0.004, cent[1] * 0.004);
    if (n > 0.38 && n <= 0.56) {
      drawShapePoly(shrinkPoly(cells[i], 1.5), 0.03);
    }
  }

  // --- Batch 4: Rich Celadon Heart Glazes (#58827a) ---
  brush.fill("#58827a", 50);
  brush.fillBleed(0.12, "in");
  brush.fillTexture(0.46, 0.32);
  drawShapePoly([[410, 310], [815, 295], [830, 880], [395, 890]], 0.1);
  for (let i = 0; i < cells.length; i++) {
    let cent = polyCentroid(cells[i]);
    let distFromCenter = dist(cent[0], cent[1], 615, 590);
    if (distFromCenter < 290 && random() < 0.55) {
      drawShapePoly(shrinkPoly(cells[i], 2.0), 0.03);
    }
  }

  // --- Batch 5: Deepest Jade-Grey-Green Core & Fracture Shadows (#3d635d) ---
  brush.fill("#3d635d", 54);
  brush.fillBleed(0.1, "in");
  brush.fillTexture(0.5, 0.38);
  drawShapePoly([[455, 395], [765, 375], [785, 795], [435, 815]], 0.12);
  for (let i = 0; i < cells.length; i++) {
    let cent = polyCentroid(cells[i]);
    let distFromCenter = dist(cent[0], cent[1], 610, 580);
    if (distFromCenter < 230 && random() < 0.42) {
      drawShapePoly(shrinkPoly(cells[i], 2.5), 0.02);
    }
  }

  // --- Batch 6: Deep Slate-Blue Internal Cleavage Shadows (#435e6d) ---
  brush.fill("#435e6d", 48);
  brush.fillBleed(0.09, "in");
  brush.fillTexture(0.48, 0.35);
  // Left bevel lower shadow & internal shadow wedges
  drawShapePoly([
    [286, 520], [355, 515], [346, 1004], [282, 976]
  ], 0.05);
  for (let i = 0; i < cells.length; i++) {
    let cent = polyCentroid(cells[i]);
    if ((cent[0] < 460 || cent[0] > 760 || cent[1] > 810) && random() < 0.38) {
      drawShapePoly(shrinkPoly(cells[i], 2.0), 0.02);
    }
  }

  // --- Batch 7: Luminous Milky-Celadon & White Refractive Cells (#e5f2ef) ---
  // In real ice, cells adjacent to dark fracture planes catch total internal reflection
  brush.fill("#e5f2ef", 68);
  brush.fillBleed(0.06, "in");
  brush.fillTexture(0.28, 0.18);
  drawShapePoly(topPoly, 0.03);
  for (let i = 0; i < cells.length; i++) {
    let cent = polyCentroid(cells[i]);
    if ((cent[1] < 360 || random() < 0.28)) {
      drawShapePoly(shrinkPoly(cells[i], 2.5), 0.02);
    }
  }

  // =========================================================================
  // 5. MILKY WHITE FREEZE STRATA & TRANSLUCENT WAShes
  // =========================================================================
  // Lake ice forms horizontal freeze horizons (slush/snow-ice top crust & internal bands)
  let strataY = [235, 345, 525, 735, 935];
  for (let sy of strataY) {
    let bandH = sy < 260 ? 55 : random(24, 42);
    let bandPts = [];
    for (let x = 352; x <= 880; x += 28) {
      let yOff = (noise(x * 0.008, sy * 0.02) - 0.5) * 22;
      bandPts.push([x, sy + yOff]);
    }
    for (let x = 880; x >= 352; x -= 28) {
      let yOff = (noise(x * 0.008 + 5, sy * 0.02) - 0.5) * 22;
      bandPts.push([x, sy + bandH + yOff]);
    }
    brush.wash(sy < 260 ? "#f4faf9" : "#dfeeeb", sy < 260 ? 78 : 38);
    drawShapePoly(bandPts, 0.15);
  }

  // Diagonal glassy Fresnel reflection bands across the front face
  brush.wash("#ffffff", 26);
  drawShapePoly([[395, 190], [515, 186], [425, 995], [352, 998]], 0.02);
  drawShapePoly([[640, 182], [775, 180], [670, 992], [555, 994]], 0.02);
  brush.noWash();

  // =========================================================================
  // 6. 3D INTERNAL FRACTURE RIBBONS (Curtains of Light & Shadow inside the Slab)
  // =========================================================================
  // Define the primary & major secondary crack paths with smooth spline points
  let majorFractures = [
    // 1. Long sweeping main diagonal-vertical thermal fracture
    {
      pts: [[538, 183], [556, 305], [588, 438], [602, 575], [634, 730], [648, 868], [656, 995]],
      ribbonOffset: [22, 10],
      lightSide: 1
    },
    // 2. Counter-diagonal stress crack from top-right to lower-left
    {
      pts: [[718, 180], [682, 310], [632, 452], [588, 575], [534, 718], [492, 862], [464, 998]],
      ribbonOffset: [-20, 12],
      lightSide: -1
    },
    // 3. Upper-mid transverse conchoidal fracture
    {
      pts: [[356, 392], [465, 412], [588, 438], [728, 478], [878, 514]],
      ribbonOffset: [8, 22],
      lightSide: -1
    },
    // 4. Lower-mid transverse fracture
    {
      pts: [[350, 696], [478, 676], [595, 652], [742, 638], [886, 626]],
      ribbonOffset: [6, -19],
      lightSide: 1
    },
    // 5. High horizontal crown crackle
    {
      pts: [[364, 276], [505, 286], [662, 298], [872, 314]],
      ribbonOffset: [5, 15],
      lightSide: 1
    },
    // 6. Deep base compression fracture (from propping the slab upright)
    {
      pts: [[348, 846], [496, 834], [642, 822], [774, 816], [888, 810]],
      ribbonOffset: [8, -16],
      lightSide: 1
    },
    // 7. Left-bevel spall fracture curving into the core
    {
      pts: [[354, 485], [418, 535], [478, 676], [452, 838], [412, 998]],
      ribbonOffset: [18, 8],
      lightSide: 1
    },
    // 8. Right-side internal cleavage curve
    {
      pts: [[868, 240], [792, 365], [755, 520], [774, 695], [835, 880]],
      ribbonOffset: [-18, 9],
      lightSide: -1
    }
  ];

  // Render translucent 3D internal fracture ribbons + Wallner hackle striations
  for (let mf of majorFractures) {
    let pts = mf.pts;
    let ox = mf.ribbonOffset[0];
    let oy = mf.ribbonOffset[1];

    // Construct the 3D ribbon polygon between the front surface crack and back internal edge
    let ribbonPoly = [];
    for (let i = 0; i < pts.length; i++) {
      ribbonPoly.push([pts[i][0], pts[i][1]]);
    }
    for (let i = pts.length - 1; i >= 0; i--) {
      let taper = sin((i / (pts.length - 1)) * 180) * 0.75 + 0.25;
      ribbonPoly.push([pts[i][0] + ox * taper, pts[i][1] + oy * taper]);
    }

    // Glaze the internal ribbon plane
    brush.noStroke();
    if (mf.lightSide > 0) {
      brush.wash("#eef8f6", 64);
      drawShapePoly(ribbonPoly, 0.12);
    } else {
      brush.wash("#315451", 46);
      drawShapePoly(ribbonPoly, 0.12);
    }
    brush.noWash();

    // Draw fine internal hackle marks (conchoidal fracture striations across the ribbon width)
    for (let i = 0; i < pts.length - 1; i++) {
      let p1 = pts[i];
      let p2 = pts[i + 1];
      let segSteps = 14;
      for (let s = 0; s < segSteps; s++) {
        let t = (i + s / segSteps) / (pts.length - 1);
        let taper = sin(t * 180) * 0.75 + 0.25;
        let sx = lerp(p1[0], p2[0], s / segSteps);
        let sy = lerp(p1[1], p2[1], s / segSteps);
        let ex = sx + ox * taper;
        let ey = sy + oy * taper;

        if (random() < 0.75) {
          brush.set("razor_etch", mf.lightSide > 0 ? "#ffffff" : "#284647", random(0.35, 0.7));
          brush.line(sx, sy, ex, ey);
        }
      }
    }

    // Draw the soft ghost back-edge of the internal fracture ribbon
    let ghostBack = pts.map((p, idx) => {
      let taper = sin((idx / (pts.length - 1)) * 180) * 0.75 + 0.25;
      return [p[0] + ox * taper, p[1] + oy * taper, 0.5];
    });
    brush.set("2H", "#638783", 0.55);
    brush.spline(ghostBack, 0.35);
  }

  // Draw the internal ghost rear edges of the thick slab (seen refracted through the ice)
  brush.set("2H", "#7ea19d", 0.65);
  brush.spline(backRightGhost.map(p => [p[0], p[1], 0.5]), 0.25);
  brush.spline(backTopGhost.map(p => [p[0], p[1], 0.5]), 0.25);
  brush.set("ice_glint", "#e4f2ef", 0.6);
  brush.spline(backRightGhost.map(p => [p[0] - 2.5, p[1], 0.5]), 0.25);

  // =========================================================================
  // 7. COLUMNS OF TRAPPED BUBBLES (Deep Veils, Mid Trains & Hyperreal Pearls)
  // =========================================================================
  // Generate ~68 vertical bubble columns characteristic of thick lake ice
  let bubbleColumns = [];
  for (let i = 0; i < 68; i++) {
    let bx = random(368, 862);
    // Group columns slightly into natural clusters
    bx += sin(bx * 2.2) * 14;
    let topStart = random(205, 580);
    let colLen = random(140, 480);
    let bottomEnd = min(975, topStart + colLen);
    let depthLayer = random(); // 0..0.4 deep, 0.4..0.75 mid, 0.75..1.0 foreground
    bubbleColumns.push({
      x: bx,
      yStart: topStart,
      yEnd: bottomEnd,
      depth: depthLayer,
      seed: random(1000)
    });
  }

  // Sort from deepest to closest so foreground bubbles sit crisply on top
  bubbleColumns.sort((a, b) => a.depth - b.depth);

  for (let col of bubbleColumns) {
    let curY = col.yStart;
    let isForeground = col.depth > 0.72;
    let isMid = col.depth > 0.38 && col.depth <= 0.72;

    // Subtle vertical milky haze along the bubble column track
    if (random() < 0.65) {
      brush.set("velvet_glaze", isForeground ? "#e8f5f3" : "#b8d3ce", random(0.4, 0.85));
      let driftX = (noise(col.seed) - 0.5) * 8;
      brush.line(col.x, col.yStart, col.x + driftX, col.yEnd);
    }

    while (curY < col.yEnd) {
      // Check if near a freeze stratum (bubbles cluster and flatten at freeze horizons)
      let nearStratum = false;
      for (let sy of strataY) {
        if (abs(curY - sy) < 18) nearStratum = true;
      }

      let drift = (noise(curY * 0.015, col.seed) - 0.5) * 14;
      let cx = col.x + drift;

      if (!pointInPoly([cx, curY], frontPoly)) {
        curY += 12;
        continue;
      }

      let bType = random();
      if (bType < 0.28 && !nearStratum) {
        // Vertical tubular "candle-ice" worm bubble
        let tubeLen = random(8, 26) * (0.6 + col.depth * 0.6);
        if (isForeground) {
          // Dark refractive edge beside the bright tube
          brush.set("razor_etch", "#2d4e4c", 0.55);
          brush.line(cx + 1.4, curY, cx + 1.4, curY + tubeLen);
          // Milky core
          brush.set("bubble_pearl", "#e7f5f3", 0.55);
          brush.line(cx, curY, cx, curY + tubeLen);
          // Crisp specular highlight
          brush.set("ice_glint", "#ffffff", 0.65);
          brush.line(cx - 0.5, curY + 1, cx - 0.5, curY + tubeLen * 0.75);
        } else {
          brush.set("2H", isMid ? "#d2e6e2" : "#9abbb5", isMid ? 0.65 : 0.45);
          brush.line(cx, curY, cx, curY + tubeLen);
        }
        curY += tubeLen + random(4, 14);
      } else {
        // Flattened lenticular disc bubble or pearl bubble in a rising train
        let rad = (nearStratum ? random(3.2, 6.8) : random(1.6, 4.6)) * (0.55 + col.depth * 0.65);

        if (isForeground) {
          // 1. Dark jade-slate underside crescent (total internal refraction shadow)
          brush.set("razor_etch", "#24403f", 0.65);
          brush.line(cx - rad * 0.85, curY + rad * 0.42, cx + rad * 0.85, curY + rad * 0.42);
          brush.line(cx - rad * 0.55, curY + rad * 0.62, cx + rad * 0.55, curY + rad * 0.62);

          // 2. Milky-white translucent bubble body (flattened oval)
          brush.set("bubble_pearl", "#eef8f7", map(rad, 1.5, 7, 0.45, 1.15));
          brush.line(cx - rad * 0.75, curY, cx + rad * 0.75, curY);

          // 3. Upper-left bright white specular glint
          brush.set("ice_glint", "#ffffff", map(rad, 1.5, 7, 0.45, 0.95));
          brush.line(cx - rad * 0.65, curY - rad * 0.28, cx + rad * 0.25, curY - rad * 0.32);
        } else if (isMid) {
          brush.set("razor_etch", "#486e6a", 0.45);
          brush.line(cx - rad * 0.7, curY + rad * 0.35, cx + rad * 0.7, curY + rad * 0.35);
          brush.set("bubble_pearl", "#d4e8e4", map(rad, 1, 6, 0.35, 0.8));
          brush.line(cx - rad * 0.65, curY, cx + rad * 0.65, curY);
          brush.set("ice_glint", "#f4fbfa", 0.4);
          brush.line(cx - rad * 0.45, curY - rad * 0.2, cx + rad * 0.15, curY - rad * 0.2);
        } else {
          // Deep out-of-focus bubble
          brush.set("bubble_pearl", "#a7c6c0", map(rad, 1, 5, 0.3, 0.65));
          brush.line(cx - rad * 0.6, curY, cx + rad * 0.6, curY);
        }

        curY += nearStratum ? random(3.5, 7.5) : random(5.5, 16);
      }
    }
  }

  // Fine micro-bubble dust & frost stipple suspended inside the slab
  for (let i = 0; i < 420; i++) {
    let px = random(355, 875);
    let py = random(195, 985);
    if (pointInPoly([px, py], frontPoly)) {
      let c = random() < 0.7 ? "#ffffff" : "#cbe0dc";
      brush.set("ice_glint", c, random(0.25, 0.55));
      brush.line(px, py, px + random(0.8, 2.2), py + random(-0.4, 0.4));
    }
  }

  // =========================================================================
  // 8. HAIRLINE PEN NETWORK — CELADON CRACKLE & OVERLAP DARKENING
  // =========================================================================
  // Collect all fracture segments so we can trace them and find every overlap/intersection
  let allCrackSegments = [];
  let junctionPoints = [];

  // Helper to add a polyline to the crackle network
  function registerCrackPolyline(pts, tier) {
    for (let i = 0; i < pts.length - 1; i++) {
      allCrackSegments.push({
        p1: pts[i],
        p2: pts[i + 1],
        tier: tier // 1 = primary, 2 = secondary cell boundary, 3 = tertiary micro-crackle
      });
    }
  }

  // 8A. Add dense subdivided points along the major fractures
  for (let mf of majorFractures) {
    let finePts = [];
    for (let i = 0; i < mf.pts.length - 1; i++) {
      let a = mf.pts[i];
      let b = mf.pts[i + 1];
      let steps = 8;
      for (let s = 0; s < steps; s++) {
        let t = s / steps;
        let x = lerp(a[0], b[0], t);
        let y = lerp(a[1], b[1], t);
        let jitter = (noise(x * 0.03, y * 0.03) - 0.5) * 4.5 * sin(t * 180);
        finePts.push([x + jitter, y - jitter * 0.6]);
      }
    }
    finePts.push(mf.pts[mf.pts.length - 1]);
    registerCrackPolyline(finePts, 1);
  }

  // 8B. Extract secondary crackle edges from the subdivided cells + add natural crystalline jitter
  let edgeMap = new Set();
  for (let c of cells) {
    for (let i = 0; i < c.length; i++) {
      let p1 = c[i];
      let p2 = c[(i + 1) % c.length];
      // Skip outer perimeter edges of the slab (handled separately)
      let d1 = dist(p1[0], p1[1], constrain(p1[0], 372, 860), constrain(p1[1], 200, 985));
      let d2 = dist(p2[0], p2[1], constrain(p2[0], 372, 860), constrain(p2[1], 200, 985));
      if (d1 > 16 && d2 > 16) continue;

      let key1 = `${round(p1[0] / 3)},${round(p1[1] / 3)}-${round(p2[0] / 3)},${round(p2[1] / 3)}`;
      let key2 = `${round(p2[0] / 3)},${round(p2[1] / 3)}-${round(p1[0] / 3)},${round(p1[1] / 3)}`;
      if (!edgeMap.has(key1) && !edgeMap.has(key2)) {
        edgeMap.add(key1);
        let segLen = dist(p1[0], p1[1], p2[0], p2[1]);
        let steps = max(2, floor(segLen / 18));
        let pts = [];
        for (let s = 0; s <= steps; s++) {
          let t = s / steps;
          let x = lerp(p1[0], p2[0], t);
          let y = lerp(p1[1], p2[1], t);
          let j = (s > 0 && s < steps) ? (noise(x * 0.04, y * 0.04) - 0.5) * 5.0 : 0;
          pts.push([x + j, y + j * 0.7]);
        }
        registerCrackPolyline(pts, 2);
        junctionPoints.push({ x: p1[0], y: p1[1], weight: 1.0 });
        junctionPoints.push({ x: p2[0], y: p2[1], weight: 1.0 });
      }
    }
  }

  // 8C. Generate tertiary fine celadon crazing (branching cracks inside cells & on left/top bevels)
  for (let c of cells) {
    let area = polyArea(c);
    let subCount = floor(map(area, 2000, 35000, 1, 5, true));
    for (let k = 0; k < subCount; k++) {
      let idx1 = floor(random(c.length));
      let idx2 = (idx1 + floor(random(1, c.length - 1))) % c.length;
      let a1 = c[idx1], a2 = c[(idx1 + 1) % c.length];
      let b1 = c[idx2], b2 = c[(idx2 + 1) % c.length];
      let tA = random(0.2, 0.8);
      let tB = random(0.2, 0.8);
      let startPt = [lerp(a1[0], a2[0], tA), lerp(a1[1], a2[1], tA)];
      let endPt = [lerp(b1[0], b2[0], tB), lerp(b1[1], b2[1], tB)];

      // Sometimes arrest midway inside the cell or connect to another crack
      let steps = 5;
      let pts = [];
      for (let s = 0; s <= steps; s++) {
        let t = s / steps;
        let x = lerp(startPt[0], endPt[0], t);
        let y = lerp(startPt[1], endPt[1], t);
        let j = (s > 0 && s < steps) ? (noise(x * 0.05 + k, y * 0.05) - 0.5) * 6.5 : 0;
        pts.push([x + j, y - j * 0.8]);
      }
      registerCrackPolyline(pts, 3);
      junctionPoints.push({ x: startPt[0], y: startPt[1], weight: 0.75 });
      junctionPoints.push({ x: endPt[0], y: endPt[1], weight: 0.75 });
    }
  }

  // Also add crackle fractures wrapping onto the left thickness bevel and top thickness bevel
  for (let i = 0; i < 22; i++) {
    let idx = floor(random(2, edgeLeft.length - 2));
    let fp = edgeLeft[idx];
    let bp = backLeftEdge[edgeLeft.length - 1 - idx] || [fp[0] - 58, fp[1] - 18];
    let mid = [
      lerp(fp[0], bp[0], 0.5) + random(-4, 4),
      lerp(fp[1], bp[1], 0.5) + random(-6, 6)
    ];
    registerCrackPolyline([fp, mid, bp], 2);
    junctionPoints.push({ x: fp[0], y: fp[1], weight: 1.1 });
  }

  for (let i = 0; i < 14; i++) {
    let idx = floor(random(2, edgeTop.length - 2));
    let fp = edgeTop[idx];
    let bp = topBackEdge[idx] || [fp[0] - 60, fp[1] - 25];
    let mid = [
      lerp(fp[0], bp[0], 0.5) + random(-5, 5),
      lerp(fp[1], bp[1], 0.5) + random(-3, 3)
    ];
    registerCrackPolyline([fp, mid, bp], 2);
    junctionPoints.push({ x: fp[0], y: fp[1], weight: 1.0 });
  }

  // 8D. Find geometric intersections between primary & secondary crack segments
  for (let i = 0; i < allCrackSegments.length; i++) {
    let s1 = allCrackSegments[i];
    if (s1.tier > 2) continue;
    for (let j = i + 2; j < allCrackSegments.length; j++) {
      let s2 = allCrackSegments[j];
      if (s2.tier > 2) continue;
      let hit = segIntersection(s1.p1, s1.p2, s2.p1, s2.p2);
      if (hit) {
        let dEnd = min(
          dist(hit.x, hit.y, s1.p1[0], s1.p1[1]),
          dist(hit.x, hit.y, s1.p2[0], s1.p2[1])
        );
        if (dEnd > 2) {
          junctionPoints.push({
            x: hit.x,
            y: hit.y,
            weight: (s1.tier === 1 && s2.tier === 1) ? 1.5 : 1.15
          });
        }
      }
    }
  }

  // 8E. Render the Crackle Network:
  // Step 1: Light-catching specular edge right next to each crack
  for (let seg of allCrackSegments) {
    let dx = seg.p2[0] - seg.p1[0];
    let dy = seg.p2[1] - seg.p1[1];
    let len = sqrt(dx * dx + dy * dy) || 1;
    let nx = -dy / len;
    let ny = dx / len;
    let shift = seg.tier === 1 ? 1.35 : (seg.tier === 2 ? 0.95 : 0.65);

    if (seg.tier <= 2 || random() < 0.65) {
      let glintCol = seg.tier === 1 ? "#ffffff" : "#e3f3f0";
      let glintW = seg.tier === 1 ? 0.68 : (seg.tier === 2 ? 0.45 : 0.3);
      brush.set("ice_glint", glintCol, glintW);
      brush.line(
        seg.p1[0] + nx * shift,
        seg.p1[1] + ny * shift,
        seg.p2[0] + nx * shift,
        seg.p2[1] + ny * shift
      );
    }
  }

  // Step 2: Hairline pen network tracing every fracture
  for (let seg of allCrackSegments) {
    if (seg.tier === 1) {
      brush.set("hairline_pen", "#20383a", random(0.68, 0.95));
      brush.line(seg.p1[0], seg.p1[1], seg.p2[0], seg.p2[1]);
      // Second tight pass for crisp ink density on primary fractures
      brush.set("razor_etch", "#152628", 0.55);
      brush.line(seg.p1[0], seg.p1[1], seg.p2[0], seg.p2[1]);
    } else if (seg.tier === 2) {
      let col = random(["#294547", "#345356", "#233c3e"]);
      brush.set("hairline_pen", col, random(0.45, 0.72));
      brush.line(seg.p1[0], seg.p1[1], seg.p2[0], seg.p2[1]);
    } else {
      let col = random(["#3e5f61", "#4b6d6f", "#314e50"]);
      brush.set("razor_etch", col, random(0.32, 0.52));
      brush.line(seg.p1[0], seg.p1[1], seg.p2[0], seg.p2[1]);
    }
  }

  // Step 3: Darkening where fractures overlap / intersect (micro-wedges, ink pooling & feathering)
  for (let jp of junctionPoints) {
    if (jp.x < 280 || jp.x > 900 || jp.y < 145 || jp.y > 1008) continue;

    // Find segments near this junction to darken along their actual converging arms
    let nearbyArms = [];
    for (let seg of allCrackSegments) {
      let d1 = dist(jp.x, jp.y, seg.p1[0], seg.p1[1]);
      let d2 = dist(jp.x, jp.y, seg.p2[0], seg.p2[1]);
      if (d1 < 14) {
        let ang = atan2(seg.p2[1] - seg.p1[1], seg.p2[0] - seg.p1[0]);
        nearbyArms.push(ang);
      } else if (d2 < 14) {
        let ang = atan2(seg.p1[1] - seg.p2[1], seg.p1[0] - seg.p2[0]);
        nearbyArms.push(ang);
      }
    }

    let armDarkLen = random(7, 16) * jp.weight;
    for (let ang of nearbyArms) {
      brush.set("hairline_pen", "#102022", random(0.65, 1.05) * jp.weight);
      brush.line(
        jp.x,
        jp.y,
        jp.x + cos(ang) * armDarkLen,
        jp.y + sin(ang) * armDarkLen
      );
    }

    // Tiny micro-spall / shadow ticks in the acute corner between overlapping fractures
    if (nearbyArms.length >= 2) {
      let a1 = nearbyArms[0];
      let a2 = nearbyArms[1];
      let midAng = (a1 + a2) * 0.5;
      for (let m = 0; m < 3; m++) {
        let r1 = random(1.5, 5.5) * jp.weight;
        let r2 = r1 + random(2, 4);
        brush.set("razor_etch", "#0d1a1c", 0.65);
        brush.line(
          jp.x + cos(a1) * r1,
          jp.y + sin(a1) * r1,
          jp.x + cos(midAng) * r2,
          jp.y + sin(midAng) * r2
        );
      }
      // Bright crushed-ice spark right beside the dark junction node
      brush.set("ice_glint", "#ffffff", 0.75 * jp.weight);
      brush.line(
        jp.x - 1.8,
        jp.y - 1.8,
        jp.x + cos(midAng + 180) * 4.5,
        jp.y + sin(midAng + 180) * 4.5
      );
    }
  }

  // =========================================================================
  // 9. CRYSTALLINE PERIMETER CLEAVAGES, CONCHOIDAL CHIPS & GLASSY EDGES
  // =========================================================================
  // Left front arris (the sharp vertical ridge between the front face and left thickness face)
  for (let i = 0; i < edgeLeft.length - 1; i++) {
    let p1 = edgeLeft[i];
    let p2 = edgeLeft[i + 1];
    // Bright specular catch on the arris ridge
    brush.set("ice_glint", "#ffffff", random(0.8, 1.35));
    brush.line(p1[0], p1[1], p2[0], p2[1]);
    brush.set("ice_glint", "#e6f5f2", 0.7);
    brush.line(p1[0] + 1.5, p1[1], p2[0] + 1.5, p2[1]);

    // Dark refractive edge immediately inside the bevel
    brush.set("hairline_pen", "#223b3e", random(0.55, 0.85));
    brush.line(p1[0] - 1.8, p1[1], p2[0] - 1.8, p2[1]);

    // Conchoidal step chips along the ridge
    if (i % 2 === 0) {
      let chipW = random(6, 16);
      let chipH = random(12, 28);
      brush.set("razor_etch", "#2b484b", 0.5);
      brush.line(p1[0], p1[1], p1[0] - chipW, p1[1] + chipH * 0.4);
      brush.line(p1[0] - chipW, p1[1] + chipH * 0.4, p1[0], p1[1] + chipH);
      brush.set("ice_glint", "#ffffff", 0.65);
      brush.line(p1[0] - chipW + 1, p1[1] + chipH * 0.4, p1[0] + 2, p1[1] + chipH * 0.8);
    }
  }

  // Top front arris (between front face and top bevel)
  for (let i = 0; i < edgeTop.length - 1; i++) {
    let p1 = edgeTop[i];
    let p2 = edgeTop[i + 1];
    brush.set("ice_glint", "#ffffff", random(0.9, 1.4));
    brush.line(p1[0], p1[1], p2[0], p2[1]);
    brush.set("hairline_pen", "#264245", random(0.5, 0.8));
    brush.line(p1[0], p1[1] + 2.0, p2[0], p2[1] + 2.0);
  }

  // Outer back-left and back-top edges
  for (let i = 0; i < backLeftEdge.length - 1; i++) {
    let p1 = backLeftEdge[i];
    let p2 = backLeftEdge[i + 1];
    brush.set("hairline_pen", "#2c464f", random(0.6, 0.95));
    brush.line(p1[0], p1[1], p2[0], p2[1]);
    brush.set("ice_glint", "#dcece9", 0.6);
    brush.line(p1[0] + 1.4, p1[1], p2[0] + 1.4, p2[1]);
  }

  for (let i = 0; i < topBackEdge.length - 1; i++) {
    let p1 = topBackEdge[i];
    let p2 = topBackEdge[i + 1];
    brush.set("hairline_pen", "#355158", random(0.5, 0.8));
    brush.line(p1[0], p1[1], p2[0], p2[1]);
    brush.set("ice_glint", "#ffffff", 0.75);
    brush.line(p1[0], p1[1] + 1.2, p2[0], p2[1] + 1.2);
  }

  // Right outer cleaved edge (catch-light + sharp crystalline steps)
  for (let i = 0; i < edgeRight.length - 1; i++) {
    let p1 = edgeRight[i];
    let p2 = edgeRight[i + 1];
    brush.set("hairline_pen", "#1e3538", random(0.65, 1.0));
    brush.line(p1[0], p1[1], p2[0], p2[1]);
    brush.set("ice_glint", "#ffffff", random(0.7, 1.15));
    brush.line(p1[0] - 1.6, p1[1], p2[0] - 1.6, p2[1]);

    // Horizontal internal step-cleavages at the right edge
    if (random() < 0.55) {
      let inLen = random(10, 28);
      brush.set("razor_etch", "#294649", 0.5);
      brush.line(p1[0], p1[1], p1[0] - inLen, p1[1] + random(-4, 6));
      brush.set("ice_glint", "#e9f6f4", 0.5);
      brush.line(p1[0], p1[1] + 1.2, p1[0] - inLen * 0.8, p1[1] + 1.2);
    }
  }

  // =========================================================================
  // 10. PROPPED BASE CONTACT, MELTWATER FILM, ICE SPLINTERS & REFLECTION
  // =========================================================================
  // Crisp dark contact meniscus where the heavy ice slab meets the wet surface
  for (let i = 0; i < edgeBottom.length - 1; i++) {
    let p1 = edgeBottom[i];
    let p2 = edgeBottom[i + 1];
    brush.set("hairline_pen", "#122326", random(0.85, 1.3));
    brush.line(p1[0], p1[1], p2[0], p2[1]);
    brush.set("razor_etch", "#243d42", 0.7);
    brush.line(p1[0], p1[1] + 2.2, p2[0], p2[1] + 2.2);
    // Bright wet meniscus rim
    brush.set("ice_glint", "#ffffff", random(0.65, 1.0));
    brush.line(p1[0], p1[1] - 1.5, p2[0], p2[1] - 1.5);
  }

  // Left bevel base contact
  brush.set("hairline_pen", "#15282c", 1.05);
  brush.line(bbl[0], bbl[1], fbl[0], fbl[1]);
  brush.set("ice_glint", "#d8ebe8", 0.7);
  brush.line(bbl[0], bbl[1] - 1.5, fbl[0], fbl[1] - 1.5);

  // Small chipped ice splinters & crystalline crumbs resting around the propped base
  let crumbs = [
    { x: 312, y: 1002, w: 22, h: 11 },
    { x: 368, y: 1014, w: 16, h: 8 },
    { x: 425, y: 1010, w: 11, h: 6 },
    { x: 635, y: 1008, w: 26, h: 12 },
    { x: 672, y: 1015, w: 14, h: 7 },
    { x: 842, y: 1004, w: 24, h: 11 },
    { x: 882, y: 1012, w: 15, h: 8 },
    { x: 912, y: 1002, w: 12, h: 6 }
  ];

  for (let cr of crumbs) {
    let cPoly = [
      [cr.x - cr.w * 0.5, cr.y],
      [cr.x - cr.w * 0.15, cr.y - cr.h],
      [cr.x + cr.w * 0.45, cr.y - cr.h * 0.65],
      [cr.x + cr.w * 0.55, cr.y + 1]
    ];
    brush.noStroke();
    brush.wash("#e3f2ef", 170);
    drawShapePoly(cPoly, 0.02);
    brush.noWash();

    // Shadow under crumb
    brush.set("hairline_pen", "#1d3337", 0.65);
    brush.line(cr.x - cr.w * 0.5, cr.y + 1, cr.x + cr.w * 0.6, cr.y + 1.5);
    // Crumb facet lines & bright top glint
    brush.set("razor_etch", "#355357", 0.45);
    brush.line(cr.x - cr.w * 0.5, cr.y, cr.x - cr.w * 0.15, cr.y - cr.h);
    brush.line(cr.x - cr.w * 0.15, cr.y - cr.h, cr.x + cr.w * 0.45, cr.y - cr.h * 0.65);
    brush.line(cr.x + cr.w * 0.45, cr.y - cr.h * 0.65, cr.x + cr.w * 0.55, cr.y + 1);
    brush.set("ice_glint", "#ffffff", 0.75);
    brush.line(cr.x - cr.w * 0.15, cr.y - cr.h, cr.x + cr.w * 0.45, cr.y - cr.h * 0.65);
    brush.line(cr.x - cr.w * 0.15, cr.y - cr.h, cr.x, cr.y);
  }

  // Wet surface reflection streaks below the slab (vertical ghost of crackle & horizontal ripples)
  for (let i = 0; i < 65; i++) {
    let rx = random(310, 895);
    let ry = random(1002, 1110);
    let rLen = map(ry, 1002, 1110, random(35, 95), random(12, 35));
    let col = random(["#e8f4f2", "#88aaa4", "#5c7a82", "#ffffff"]);
    let w = map(ry, 1002, 1110, 0.55, 0.25);
    brush.set("2H", col, w);
    brush.line(rx - rLen * 0.5, ry, rx + rLen * 0.5, ry);
  }

  // Final glassy vertical sheen lines across the ice face for cold, polished mineral perfection
  for (let i = 0; i < 48; i++) {
    let gx = random(360, 870);
    let gy1 = random(195, 780);
    let gy2 = gy1 + random(45, 190);
    if (pointInPoly([gx, gy1], frontPoly) && pointInPoly([gx, gy2], frontPoly)) {
      brush.set("ice_glint", "#ffffff", random(0.2, 0.42));
      brush.line(gx, gy1, gx, gy2);
    }
  }

  noLoop();
}

let pulses = [];
const SEED_RED_LENTIL = 0;
const SEED_GREEN_PEA = 1;
const SEED_BELUGA = 2;
const SEED_MUNG_BEAN = 3;

// Light direction: from upper-left (-132 deg) casting shadows toward bottom-right (+48 deg)
const LIGHT_DIR_X = 0.743;
const LIGHT_DIR_Y = 0.669;

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(7391);
  noiseSeed(7391);

  // Add an ultra-fine colored pencil tip for tiny botanical seed scars & highlights
  brush.add("micro_pencil", {
    type: "default",
    weight: 0.22,
    scatter: 0.18,
    sharpness: 0.82,
    grain: 14,
    opacity: 210,
    spacing: 0.35,
    pressure: [0.7, 1.15, 0.6],
    noise: 0.35
  });

  // Add a soft dry-pastel pencil for subtle fabric fold & shadow blending
  brush.add("soft_shade", {
    type: "default",
    weight: 0.9,
    scatter: 0.85,
    sharpness: 0.25,
    grain: 22,
    opacity: 65,
    spacing: 0.5,
    pressure: [0.4, 1.0, 0.4],
    noise: 0.5
  });

  generateDitsyScatter();
}

// Evaluate the gentle diagonal fold across the cotton lawn sheet
// Fold runs diagonally from upper-left-center (190, -60) to lower-right (1090, 1260)
function getFoldData(x, y) {
  const x0 = 190;
  const y0 = -60;
  const dx = 900;
  const dy = 1320;
  const len = Math.hypot(dx, dy);
  const nx = -dy / len; // normal pointing toward upper-right
  const ny = dx / len;
  const tx = dx / len;
  const ty = dy / len;

  const relX = x - x0;
  const relY = y - y0;
  const along = relX * tx + relY * ty;

  // Gentle organic wave along the diagonal crease
  const curveOffset =
    Math.sin(along * 0.0032 + 0.4) * 26 +
    Math.cos(along * 0.0071 - 1.1) * 9;

  // Signed perpendicular distance from the fold crest
  const d = relX * nx + relY * ny - curveOffset;

  // Primary fold ridge: sunlit slope on upper-left side (d < 0), soft shadow trough on lower-right (d > 0)
  const crestHighlight = Math.exp(-Math.pow((d + 16) / 38, 2)) * 0.95;
  const troughShadow = -Math.exp(-Math.pow((d - 34) / 48, 2)) * 1.0;
  const farRecovery = Math.exp(-Math.pow((d - 105) / 60, 2)) * 0.22;

  // Subtle secondary fabric undulation further across the lawn
  const secondaryWave =
    Math.sin((d + 280) * 0.012) * Math.exp(-Math.pow((d + 260) / 190, 2)) * 0.22 +
    Math.sin((d - 340) * 0.011) * Math.exp(-Math.pow((d - 330) / 210, 2)) * 0.18;

  const tone = crestHighlight + troughShadow + farRecovery + secondaryWave;

  // Micro 3D thread deflection across the fold ridge
  const shiftMag = Math.exp(-Math.pow((d - 6) / 52, 2)) * 3.8;
  return {
    d,
    along,
    tone,
    shiftX: nx * shiftMag,
    shiftY: ny * shiftMag
  };
}

// Generate an evenly spaced, non-clumping all-over ditsy scatter with no focal point
function generateDitsyScatter() {
  pulses = [];
  const spacing = 64;
  const rowH = spacing * 0.866;
  const margin = 24;

  let rawPts = [];
  let rowIdx = 0;
  for (let y = -margin; y <= height + margin; y += rowH) {
    const xOffset = (rowIdx % 2) * (spacing * 0.5);
    for (let x = -margin + xOffset; x <= width + margin; x += spacing) {
      // Slightly rotate & jitter coordinates so no grid lines are perceptible
      const jx = x + random(-16, 16);
      const jy = y + random(-16, 16);
      rawPts.push({ x: jx, y: jy });
    }
    rowIdx++;
  }

  // Relax points for 4 iterations so spacing is rhythmically even like a classic dress print
  const minDist = 49;
  for (let iter = 0; iter < 4; iter++) {
    for (let i = 0; i < rawPts.length; i++) {
      for (let j = i + 1; j < rawPts.length; j++) {
        const dx = rawPts[j].x - rawPts[i].x;
        const dy = rawPts[j].y - rawPts[i].y;
        const distSq = dx * dx + dy * dy;
        if (distSq < minDist * minDist && distSq > 0.01) {
          const dist = Math.sqrt(distSq);
          const push = (minDist - dist) * 0.35;
          const ux = dx / dist;
          const uy = dy / dist;
          rawPts[i].x -= ux * push;
          rawPts[i].y -= uy * push;
          rawPts[j].x += ux * push;
          rawPts[j].y += uy * push;
        }
      }
    }
  }

  // Assign the 4 pulse varieties in a balanced spatial mix so every region has all 4 types
  for (let i = 0; i < rawPts.length; i++) {
    const p = rawPts[i];
    if (p.x < -18 || p.x > width + 18 || p.y < -18 || p.y > height + 18) continue;

    // Count neighbor types within 115px to avoid adjacent duplicates where possible
    let counts = [0, 0, 0, 0];
    for (let j = 0; j < pulses.length; j++) {
      const other = pulses[j];
      const d2 = (p.x - other.x) ** 2 + (p.y - other.y) ** 2;
      if (d2 < 115 * 115) {
        counts[other.type] += d2 < 75 * 75 ? 3 : 1;
      }
    }

    // Pick among the least-represented types nearby
    let candidates = [0, 1, 2, 3];
    candidates.sort((a, b) => counts[a] - counts[b] + random(-0.4, 0.4));
    const type = candidates[0];

    const fold = getFoldData(p.x, p.y);
    const rot = random(0, 360);
    const scaleVar = random(0.91, 1.09);

    // Precompute organic contour wobble for each seed
    let wobble = [];
    for (let k = 0; k < 14; k++) {
      wobble.push(random(-0.045, 0.045));
    }

    pulses.push({
      x: p.x + fold.shiftX * 0.6,
      y: p.y + fold.shiftY * 0.6,
      type,
      rot,
      sc: scaleVar,
      foldTone: fold.tone,
      wobble,
      splitSide: random() < 0.45,
      scarSide: random() < 0.5 ? 1 : -1,
      speckSeed: floor(random(10000))
    });
  }
}

function draw() {
  translate(-width / 2, -height / 2);

  // 1. Soft powder-pink cotton lawn base ground
  background("#f3dedb");

  // 2. Render the diagonal fabric fold and fine cotton lawn weave
  drawCottonLawnAndFold();

  // 3. Render miniature cast shadows beneath every pulse
  drawAllCastShadows();

  // 4. Render solid undertone washes batched by pulse variety
  drawAllSeedBaseWashes();

  // 5. Render hyperreal colored-pencil modeling, reflected light, seed scars & highlights
  for (let i = 0; i < pulses.length; i++) {
    const s = pulses[i];
    if (s.type === SEED_RED_LENTIL) {
      drawRedLentilDetail(s);
    } else if (s.type === SEED_GREEN_PEA) {
      drawGreenPeaDetail(s);
    } else if (s.type === SEED_BELUGA) {
      drawBelugaLentilDetail(s);
    } else {
      drawMungBeanDetail(s);
    }
  }

  noLoop();
}

// ============================================================================
// COTTON LAWN WEAVE & GENTLE DIAGONAL FOLD
// ============================================================================
function drawCottonLawnAndFold() {
  brush.noField();

  // Subtle overall warm powder-pink tonal variations across the lawn
  brush.noStroke();
  brush.noHatch();

  // Draw the diagonal fold trough & crest using soft layered pastel strokes along the fold
  const x0 = 190;
  const y0 = -60;
  const dx = 900;
  const dy = 1320;
  const len = Math.hypot(dx, dy);
  const nx = -dy / len;
  const ny = dx / len;
  const tx = dx / len;
  const ty = dy / len;

  // Sweep parallel lines along the fold corridor to build a seamless soft cloth wave
  for (let offset = -240; offset <= 260; offset += 3.5) {
    // Evaluate fold intensity at this perpendicular offset
    const crest = Math.exp(-Math.pow((offset + 16) / 36, 2));
    const trough = Math.exp(-Math.pow((offset - 34) / 46, 2));
    const deepTrough = Math.exp(-Math.pow((offset - 26) / 22, 2));
    const farSlope = Math.exp(-Math.pow((offset - 96) / 52, 2));

    if (crest < 0.06 && trough < 0.06 && farSlope < 0.08) continue;

    let col = "#ebcfcb";
    let wt = 0.65;
    if (trough > crest) {
      if (deepTrough > 0.55) {
        col = "#d2b0ab";
        wt = 0.85;
      } else if (trough > 0.45) {
        col = "#dcc0bc";
        wt = 0.75;
      } else {
        col = "#e5cac6";
        wt = 0.6;
      }
    } else if (crest > 0.2) {
      col = crest > 0.6 ? "#fff4f2" : "#faeae7";
      wt = 0.8;
    } else {
      col = "#f7e6e3";
      wt = 0.5;
    }

    brush.set("soft_shade", col, wt);

    let pts = [];
    for (let s = -80; s <= len + 80; s += 95) {
      const wave =
        Math.sin(s * 0.0032 + 0.4) * 26 +
        Math.cos(s * 0.0071 - 1.1) * 9;
      const d = offset + wave;
      const px = x0 + tx * s + nx * d;
      const py = y0 + ty * s + ny * d;
      pts.push([px, py, 0.8]);
    }
    brush.spline(pts, 0.4);
  }

  // Secondary faint fabric undulations so the whole sheet breathes like real lawn
  for (let band of [-275, 325]) {
    for (let off = -42; off <= 42; off += 6) {
      const col = off < 0 ? "#f9eae7" : "#e6cbc7";
      brush.set("soft_shade", col, 0.42);
      let pts = [];
      for (let s = -80; s <= len + 80; s += 120) {
        const wave = Math.sin(s * 0.0028 - 0.5) * 18;
        const d = band + off + wave;
        const px = x0 + tx * s + nx * d;
        const py = y0 + ty * s + ny * d;
        pts.push([px, py, 0.65]);
      }
      brush.spline(pts, 0.4);
    }
  }

  // Fine woven cotton lawn texture (warp & weft threads)
  // Cotton lawn is a crisp, fine plain weave; threads deflect subtly across the diagonal fold
  const step = 6;

  // Horizontal weft threads
  for (let y = 0; y <= height; y += step) {
    const isHighlightThread = (y / step) % 2 === 0;
    // Break weft into segments so tone modulates across the fold
    let x = 0;
    while (x < width) {
      const segLen = random(95, 165);
      const x2 = Math.min(width, x + segLen);
      const midX = (x + x2) * 0.5;
      const f1 = getFoldData(x, y);
      const fMid = getFoldData(midX, y);
      const f2 = getFoldData(x2, y);

      let col;
      if (fMid.tone < -0.35) {
        col = isHighlightThread ? "#e3c5c1" : "#cfb0ab";
      } else if (fMid.tone > 0.35) {
        col = isHighlightThread ? "#fff6f4" : "#edd5d1";
      } else {
        col = isHighlightThread ? "#f9e9e6" : "#e5cac6";
      }

      brush.set("2H", col, random(0.14, 0.22));
      brush.line(
        x + f1.shiftX,
        y + f1.shiftY,
        x2 + f2.shiftX,
        y + f2.shiftY
      );
      x = x2 + random(2, 8);
    }
  }

  // Vertical warp threads
  for (let x = 0; x <= width; x += step) {
    const isLightWarp = (x / step) % 2 === 0;
    let y = 0;
    while (y < height) {
      const segLen = random(95, 165);
      const y2 = Math.min(height, y + segLen);
      const midY = (y + y2) * 0.5;
      const f1 = getFoldData(x, y);
      const fMid = getFoldData(x, midY);
      const f2 = getFoldData(x, y2);

      let col;
      if (fMid.tone < -0.35) {
        col = isLightWarp ? "#e0c2be" : "#cba9a4";
      } else if (fMid.tone > 0.35) {
        col = isLightWarp ? "#fdf3f1" : "#ebd2ce";
      } else {
        col = isLightWarp ? "#f7e6e3" : "#e2c6c2";
      }

      brush.set("2H", col, random(0.13, 0.2));
      brush.line(
        x + f1.shiftX,
        y + f1.shiftY,
        x + f2.shiftX,
        y2 + f2.shiftY
      );
      y = y2 + random(2, 8);
    }
  }

  // Tiny occasional cotton slub/nep threads for tactile hyperrealism
  for (let i = 0; i < 160; i++) {
    const sx = random(width);
    const sy = random(height);
    const f = getFoldData(sx, sy);
    const slubLen = random(8, 22);
    const horiz = random() < 0.5;
    brush.set("micro_pencil", f.tone < -0.25 ? "#edd3cf" : "#fff7f5", random(0.2, 0.32));
    if (horiz) {
      brush.line(sx, sy, sx + slubLen, sy);
    } else {
      brush.line(sx, sy, sx, sy + slubLen);
    }
  }
}

// ============================================================================
// SEED SILHOUETTE GEOMETRY HELPERS
// ============================================================================
function getSeedDims(s) {
  if (s.type === SEED_RED_LENTIL) {
    return { rx: 10.6 * s.sc, ry: 10.0 * s.sc, h: 6.8 * s.sc };
  } else if (s.type === SEED_GREEN_PEA) {
    return { rx: 12.2 * s.sc, ry: 10.6 * s.sc, h: 9.8 * s.sc };
  } else if (s.type === SEED_BELUGA) {
    return { rx: 9.2 * s.sc, ry: 8.5 * s.sc, h: 7.8 * s.sc };
  } else {
    // Olive mung bean: plump barrel-oval
    return { rx: 12.0 * s.sc, ry: 8.4 * s.sc, h: 9.2 * s.sc };
  }
}

// Transform local seed coordinates (lx, ly) into canvas space
function toWorld(s, lx, ly) {
  const c = cos(s.rot);
  const sn = sin(s.rot);
  return [s.x + lx * c - ly * sn, s.y + lx * sn + ly * c];
}

// Generate 14-point organic perimeter for a seed at (cx, cy)
function getSeedPolygonPoints(s, cx, cy, scaleMult = 1.0) {
  const dims = getSeedDims(s);
  const rx = dims.rx * scaleMult;
  const ry = dims.ry * scaleMult;
  const c = cos(s.rot);
  const sn = sin(s.rot);

  let pts = [];
  const N = 14;
  for (let i = 0; i < N; i++) {
    const a = (i * 360) / N;
    const ca = cos(a);
    const sa = sin(a);
    let rMod = 1 + s.wobble[i];

    let lx = ca * rx * rMod;
    let ly = sa * ry * rMod;

    if (s.type === SEED_RED_LENTIL) {
      // Slight pinch at the seed scar notch near angle 0
      if (i === 0) {
        lx *= 0.93;
      } else if (i === 1 || i === N - 1) {
        lx *= 1.02;
      }
    } else if (s.type === SEED_GREEN_PEA) {
      // Slightly flattened cotyledon margin on one side
      if (sa > 0.4) {
        ly *= 0.92;
      }
    } else if (s.type === SEED_MUNG_BEAN) {
      // Barrel-shaped fullness at the corners of the oval
      const barrel = 1 + 0.08 * Math.pow(Math.sin(2 * (a * Math.PI / 180)), 2);
      lx *= barrel;
      ly *= barrel;
      // Subtle hilum indentation on the scar side
      if (i === 3 || i === 4) {
        ly *= 0.94;
      }
    }

    const wx = cx + lx * c - ly * sn;
    const wy = cy + lx * sn + ly * c;
    pts.push([wx, wy]);
  }
  return pts;
}

function drawPolygonShape(pts, curvature = 0.45) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

// ============================================================================
// MINIATURE CAST SHADOWS ON THE PINK CLOTH
// ============================================================================
function drawAllCastShadows() {
  brush.noField();
  brush.noFill();
  brush.noHatch();

  // Pass 1: Soft outer penumbra wash on the powder-pink cotton lawn
  brush.noStroke();
  brush.wash("#d6b1ac", 115);
  for (let i = 0; i < pulses.length; i++) {
    const s = pulses[i];
    const dims = getSeedDims(s);
    const sx = s.x + LIGHT_DIR_X * dims.h * 0.72;
    const sy = s.y + LIGHT_DIR_Y * dims.h * 0.72;
    const pts = getSeedPolygonPoints(s, sx, sy, 1.04);
    drawPolygonShape(pts, 0.5);
  }

  // Pass 2: Main warm rose-mauve cast shadow wash
  brush.wash("#b58a85", 155);
  for (let i = 0; i < pulses.length; i++) {
    const s = pulses[i];
    const dims = getSeedDims(s);
    const sx = s.x + LIGHT_DIR_X * dims.h * 0.52;
    const sy = s.y + LIGHT_DIR_Y * dims.h * 0.52;
    const pts = getSeedPolygonPoints(s, sx, sy, 0.96);
    drawPolygonShape(pts, 0.45);
  }

  // Pass 3: Core umber-plum occlusion wash close to the seed base
  brush.wash("#8a5f5a", 180);
  for (let i = 0; i < pulses.length; i++) {
    const s = pulses[i];
    const dims = getSeedDims(s);
    const sx = s.x + LIGHT_DIR_X * dims.h * 0.3;
    const sy = s.y + LIGHT_DIR_Y * dims.h * 0.3;
    const pts = getSeedPolygonPoints(s, sx, sy, 0.88);
    drawPolygonShape(pts, 0.45);
  }
  brush.noWash();

  // Pass 4: Colored-pencil shadow feathering & tight dark contact occlusion
  for (let i = 0; i < pulses.length; i++) {
    const s = pulses[i];
    const dims = getSeedDims(s);
    const sx = s.x + LIGHT_DIR_X * dims.h * 0.52;
    const sy = s.y + LIGHT_DIR_Y * dims.h * 0.52;

    // Subtle warm bounce inside the cast shadow for red lentils and green peas
    if (s.type === SEED_RED_LENTIL) {
      brush.set("cpencil", "#c77d6b", 0.35);
      brush.circle(sx, sy, dims.rx * 0.55, 0.15);
    } else if (s.type === SEED_GREEN_PEA) {
      brush.set("cpencil", "#9c8b76", 0.32);
      brush.circle(sx, sy, dims.rx * 0.55, 0.15);
    }

    // Feathered colored-pencil hatching along the shadow tail
    brush.set("cpencil", "#9e726d", 0.28);
    for (let k = -2; k <= 2; k++) {
      const perpX = -LIGHT_DIR_Y * k * 2.2 * s.sc;
      const perpY = LIGHT_DIR_X * k * 2.2 * s.sc;
      brush.line(
        s.x + perpX + LIGHT_DIR_X * dims.rx * 0.4,
        s.y + perpY + LIGHT_DIR_Y * dims.ry * 0.4,
        sx + perpX + LIGHT_DIR_X * dims.rx * 0.82,
        sy + perpY + LIGHT_DIR_Y * dims.ry * 0.82
      );
    }

    // Tight dark contact shadow right under the bottom-right rim of the seed
    brush.set("micro_pencil", "#4f2f2c", 0.42);
    const occX = s.x + LIGHT_DIR_X * 1.4;
    const occY = s.y + LIGHT_DIR_Y * 1.4;
    brush.arc(occX, occY, (dims.rx + dims.ry) * 0.49, 2, 94);
  }
}

// ============================================================================
// SEED UNDERTONE BASE WASHES (BATCHED BY COLOR)
// ============================================================================
function drawAllSeedBaseWashes() {
  brush.noStroke();
  brush.noFill();
  brush.noHatch();

  const baseColors = [
    ["#d16f53", 242], // Red lentil muted terracotta-apricot
    ["#80945f", 242], // Green split pea muted sage-celadon
    ["#2b2429", 248], // Black beluga lentil deep plum-charcoal
    ["#71753d", 245]  // Olive mung bean golden-khaki olive
  ];

  for (let t = 0; t < 4; t++) {
    brush.wash(baseColors[t][0], baseColors[t][1]);
    for (let i = 0; i < pulses.length; i++) {
      const s = pulses[i];
      if (s.type !== t) continue;
      const pts = getSeedPolygonPoints(s, s.x, s.y, 1.0);
      drawPolygonShape(pts, 0.45);
    }
  }
  brush.noWash();
}

// ============================================================================
// 1. RED LENTIL (SPLIT MASOOR DAL) — COLOURED PENCIL HYPERREAL DETAIL
// ============================================================================
function drawRedLentilDetail(s) {
  const dims = getSeedDims(s);
  const r = (dims.rx + dims.ry) * 0.5;

  // 1. Mid-body radial & curved colored-pencil grain
  brush.set("cpencil", "#de8163", 0.42);
  for (let k = -3; k <= 3; k++) {
    const yOff = k * 2.1 * s.sc;
    const halfSpan = Math.sqrt(Math.max(1, r * r - yOff * yOff)) * 0.85;
    brush.spline([
      [s.x - halfSpan, s.y + yOff * 0.85, 0.5],
      [s.x, s.y + yOff - 1.2 * s.sc, 1.0],
      [s.x + halfSpan, s.y + yOff * 0.85, 0.5]
    ], 0.4);
  }

  // 2. Shadow crescent on the bottom-right slope (burnt terracotta / rust)
  brush.set("cpencil", "#a84b35", 0.44);
  brush.arc(s.x, s.y, r * 0.88, -18, 118);
  brush.arc(s.x, s.y, r * 0.76, -8, 108);

  brush.set("cpencil", "#8f3925", 0.36);
  brush.arc(s.x, s.y, r * 0.84, 8, 92);

  // 3. Upper-left lit dome (warm apricot-peach & soft ochre-salmon)
  brush.set("cpencil", "#eb9b78", 0.45);
  brush.arc(s.x, s.y, r * 0.82, 165, 305);
