  brush.arc(s.x - 1.6 * s.sc, s.y - 1.4 * s.sc, r * 0.36, 170, 305);

  // 4. Characteristic pale chalky split-cotyledon outer rim
  brush.set("micro_pencil", "#f7d5be", 0.35);
