  for (let i = 0; i < pts.length; i++) {
    const p1 = pts[i];
    const p2 = pts[(i + 1) % pts.length];
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // 7. Tiny starch flecks & orange-red cotyledon pores
  brush.set("micro_pencil", "#963b26", 0.28);
  for (let k = 0; k < 4; k++) {
    const a = (s.speckSeed * 47 + k * 89) % 360;
    const rad = ((k + 1) * 0.19) * r;
    const px = s.x + cos(a) * rad;
    const py = s.y + sin(a) * rad;
    brush.line(px, py, px + 0.9, py + 0.6);
  }
  brush.set("micro_pencil", "#ffeade", 0.3);
  for (let k = 0; k < 3; k++) {
    const a = (s.speckSeed * 31 + k * 113) % 360;
    const rad = ((k + 1) * 0.22) * r;
    const px = s.x + cos(a) * rad;
    const py = s.y + sin(a) * rad;
    brush.line(px, py, px + 1.0, py - 0.5);
  }

  // 8. Specular highlight on upper-left swell
  brush.set("micro_pencil", "#ffefe3", 0.45);
  brush.arc(s.x - 1.5 * s.sc, s.y - 1.4 * s.sc, r * 0.44, 198, 268);

  // 9. Seed scar (tiny pale radicle notch at local angle 0 on the margin)
  const scarOuter = toWorld(s, dims.rx * 0.96, 0);
  const scarInner = toWorld(s, dims.rx * 0.73, 0);
  const scarL = toWorld(s, dims.rx * 0.88, -1.5 * s.sc);
  const scarR = toWorld(s, dims.rx * 0.88, 1.5 * s.sc);

  brush.set("micro_pencil", "#fff5eb", 0.46);
  brush.line(scarL[0], scarL[1], scarInner[0], scarInner[1]);
  brush.line(scarR[0], scarR[1], scarInner[0], scarInner[1]);
  brush.set("micro_pencil", "#692314", 0.34);
  brush.line(scarOuter[0], scarOuter[1], scarInner[0], scarInner[1]);
}

