// 4. OLIVE MUNG BEAN — COLOURED PENCIL HYPERREAL DETAIL
// ============================================================================
function drawMungBeanDetail(s) {
  const dims = getSeedDims(s);
  const rx = dims.rx;
  const ry = dims.ry;

  // Determine which longitudinal side faces more toward the top-left light
  const upWorld = toWorld(s, 0, -1);
  const sideSign = (upWorld[0] - s.x) * LIGHT_DIR_X + (upWorld[1] - s.y) * LIGHT_DIR_Y < 0 ? -1 : 1;
  const litY = sideSign * ry;
  const shadY = -sideSign * ry;

  // 1. Cylindrical shadow side along the barrel (deep bronze-olive)
  brush.set("cpencil", "#4a4d24", 0.46);
  for (let frac of [0.55, 0.72, 0.86]) {
    const p1 = toWorld(s, -rx * 0.78, shadY * frac * 0.75);
    const p2 = toWorld(s, 0, shadY * frac);
    const p3 = toWorld(s, rx * 0.78, shadY * frac * 0.75);
    brush.spline([
      [p1[0], p1[1], 0.5],
      [p2[0], p2[1], 1.0],
      [p3[0], p3[1], 0.5]
    ], 0.4);
  }

  brush.set("cpencil", "#363918", 0.38);
  const sp1 = toWorld(s, -rx * 0.68, shadY * 0.82 * 0.75);
  const sp2 = toWorld(s, 0, shadY * 0.84);
  const sp3 = toWorld(s, rx * 0.68, shadY * 0.82 * 0.75);
  brush.spline([
    [sp1[0], sp1[1], 0.5],
    [sp2[0], sp2[1], 1.0],
    [sp3[0], sp3[1], 0.5]
  ], 0.4);

  // 2. Mid-body golden-olive longitudinal modeling & faint seed-coat veining
  brush.set("cpencil", "#868b4c", 0.44);
  for (let frac of [-0.15, 0.08, 0.28]) {
    const p1 = toWorld(s, -rx * 0.82, litY * frac * 0.75);
    const p2 = toWorld(s, 0, litY * frac);
    const p3 = toWorld(s, rx * 0.82, litY * frac * 0.75);
    brush.spline([
      [p1[0], p1[1], 0.6],
      [p2[0], p2[1], 1.0],
      [p3[0], p3[1], 0.6]
    ], 0.4);
  }

  // Rounded barrel-end shading
  brush.set("cpencil", "#585c2c", 0.36);
  const e1 = toWorld(s, rx * 0.76, -ry * 0.52);
  const e2 = toWorld(s, rx * 0.90, 0);
  const e3 = toWorld(s, rx * 0.76, ry * 0.52);
  brush.spline([[e1[0], e1[1], 0.5], [e2[0], e2[1], 1.0], [e3[0], e3[1], 0.5]], 0.5);

  const w1 = toWorld(s, -rx * 0.76, -ry * 0.52);
  const w2 = toWorld(s, -rx * 0.90, 0);
  const w3 = toWorld(s, -rx * 0.76, ry * 0.52);
  brush.spline([[w1[0], w1[1], 0.5], [w2[0], w2[1], 1.0], [w3[0], w3[1], 0.5]], 0.5);

  // 3. Upper-left lit cylindrical ridge (warm khaki-citrine)
  brush.set("cpencil", "#a3a864", 0.45);
  for (let frac of [0.38, 0.56]) {
    const p1 = toWorld(s, -rx * 0.72, litY * frac * 0.75);
    const p2 = toWorld(s, 0, litY * frac);
    const p3 = toWorld(s, rx * 0.72, litY * frac * 0.75);
    brush.spline([
      [p1[0], p1[1], 0.5],
      [p2[0], p2[1], 1.0],
      [p3[0], p3[1], 0.5]
    ], 0.4);
  }

  brush.set("cpencil", "#bfc480", 0.40);
  const lp1 = toWorld(s, -rx * 0.56, litY * 0.46 * 0.8);
  const lp2 = toWorld(s, -rx * 0.1, litY * 0.52);
  const lp3 = toWorld(s, rx * 0.45, litY * 0.46 * 0.8);
  brush.spline([
    [lp1[0], lp1[1], 0.5],
    [lp2[0], lp2[1], 1.0],
    [lp3[0], lp3[1], 0.5]
  ], 0.4);

  // 4. Glossy specular highlight strip along the lit cylindrical brow
  brush.set("micro_pencil", "#f2f5cc", 0.48);
  const hp1 = toWorld(s, -rx * 0.42, litY * 0.48 * 0.85);
  const hp2 = toWorld(s, -rx * 0.08, litY * 0.53);
  const hp3 = toWorld(s, rx * 0.28, litY * 0.48 * 0.85);
  brush.spline([
    [hp1[0], hp1[1], 0.5],
    [hp2[0], hp2[1], 1.1],
    [hp3[0], hp3[1], 0.5]
  ], 0.4);

  // 5. Reflected pink cotton lawn light along the bottom-right shadow rim
  brush.set("micro_pencil", "#a6877c", 0.35);
  const rp1 = toWorld(s, -rx * 0.55, shadY * 0.92 * 0.8);
  const rp2 = toWorld(s, 0, shadY * 0.95);
  const rp3 = toWorld(s, rx * 0.55, shadY * 0.92 * 0.8);
  brush.spline([
    [rp1[0], rp1[1], 0.5],
    [rp2[0], rp2[1], 1.0],
    [rp3[0], rp3[1], 0.5]
  ], 0.4);

  // 6. Crisp dark olive-umber contour
  brush.set("micro_pencil", "#2e3014", 0.28);
  const pts = getSeedPolygonPoints(s, s.x, s.y, 1.0);
  for (let i = 0; i < pts.length; i++) {
    const p1 = pts[i];
    const p2 = pts[(i + 1) % pts.length];
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // 7. ICONIC MUNG BEAN HILUM (SEED SCAR):
  // A crisp elongated white-ivory oval scar rimmed with a dark chocolate-brown halo
  const hilumY = litY * 0.82;
  const hLeft = toWorld(s, -2.5 * s.sc, hilumY * 0.96);
  const hMid = toWorld(s, 0.3 * s.sc, hilumY);
  const hRight = toWorld(s, 3.1 * s.sc, hilumY * 0.96);

  // Dark brown-black rim around the hilum
  brush.set("cpencil", "#2b2113", 0.55);
  brush.spline([
    [hLeft[0], hLeft[1], 0.8],
    [hMid[0], hMid[1], 1.2],
    [hRight[0], hRight[1], 0.8]
  ], 0.4);

  // Crisp bright white-cream hilum cushion inside the halo
  const wLeft = toWorld(s, -2.0 * s.sc, hilumY * 0.96);
  const wRight = toWorld(s, 2.6 * s.sc, hilumY * 0.96);
  brush.set("micro_pencil", "#fffaf0", 0.58);
  brush.spline([
    [wLeft[0], wLeft[1], 0.9],
    [hMid[0], hMid[1], 1.3],
    [wRight[0], wRight[1], 0.9]
  ], 0.4);

  // Microscopic central longitudinal cleft inside the white hilum
  const cLeft = toWorld(s, -1.1 * s.sc, hilumY * 0.96);
  const cRight = toWorld(s, 1.7 * s.sc, hilumY * 0.96);
  brush.set("micro_pencil", "#87745c", 0.24);
  brush.line(cLeft[0], cLeft[1], cRight[0], cRight[1]);
}

// Hyperreal Overhead View of Tandir Flatbreads on a Madder-Red & Indigo/Ivory Cloth
// p5.js 2.x + p5.brush (WEBGL)

const DEG2RAD = Math.PI / 180;

// High-contrast hyperreal palette
const PAL = {
  // Deep Madder-Red Cloth
  clothAbyss: "#1c0305",
  clothDark: "#38060a",
  clothDeep: "#590d13",
  clothMid: "#7a161e",
  clothBright: "#9c222b",
  clothHighlight: "#ba3840",

  // Indigo & Ivory Diamond Motifs
  indigoAbyss: "#060b17",
  indigoDark: "#0d1830",
  indigoMid: "#1b3059",
  indigoLight: "#2e4d82",
  ivoryShadow: "#b8a98a",
  ivoryMid: "#dfd1b2",
  ivoryBright: "#f7efe0",
  ivoryPure: "#fffdf7",

  // Tandir Bread Crust (Ochre, Burnt Sienna, Soot Black, Wheat Cream)
  sootBlack: "#090403",
  sootChar: "#170905",
  umberDark: "#2e1005",
  umberMid: "#4d1a07",
  siennaDeep: "#6e2208",
  siennaBurnt: "#91300c",
  siennaWarm: "#b34414",
  ochreDeep: "#cc6818",
  ochreWarm: "#e08b26",
  ochreGold: "#f0b042",
  ochreBright: "#f7cc6b",
  crustCream: "#fce49c",
  crustSpec: "#fff7de",

  // Seeds
  sesameShadow: "#8c581c",
  sesameMid: "#e0b86e",
  sesameLight: "#faecc5",
  sesameSpec: "#fffdf2",
  nigellaBlack: "#0c0807",
  nigellaEdge: "#7a7067"
};

// Global directional light (raking from top-left)
const LIGHT = {
  lx: -0.64,
  ly: -0.64,
  lz: 0.425
};

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(42719);
  noiseSeed(8831);
}

function draw() {
  translate(-width / 2, -height / 2);
  brush.noField();

  // -------------------------------------------------------------------------
  // 1. DEEP MADDER-RED CLOTH GROUND & WOVEN TEXTURE
  // -------------------------------------------------------------------------
  background(PAL.clothAbyss);
  drawMadderClothGround();

  // Lattice configuration: 3x3 full loaves, 4x4 interstitial diamond gaps
  const gridS = 368;
  const startC = 600 - gridS; // 232 -> [232, 600, 968]
  const loafR = 177;

  // Precompute all 9 loaves' geometry so cloth shadows & diamonds interact accurately
  const loaves = [];
  for (let row = 0; row < 3; row++) {
    for (let col = 0; col < 3; col++) {
      const idx = row * 3 + col;
      const cx = startC + col * gridS + random(-2.5, 2.5);
      const cy = startC + row * gridS + random(-2.5, 2.5);
      loaves.push(createLoafData(cx, cy, loafR, row, col, idx));
    }
  }

  // -------------------------------------------------------------------------
  // 2. INDIGO & IVORY SECONDARY DIAMOND MOTIFS IN THE LATTICE GAPS
  // -------------------------------------------------------------------------
  drawInterstitialLattice(startC, gridS);

  // -------------------------------------------------------------------------
  // 3. DEEP CAST SHADOWS & AMBIENT OCCLUSION OF LOAVES ON THE CLOTH
  // -------------------------------------------------------------------------
  drawLoafCastShadows(loaves);

  // -------------------------------------------------------------------------
  // 4. HYPERREAL TANDIR FLATBREADS (3x3 STRICT LATTICE)
  // -------------------------------------------------------------------------
  // Batch base washes across all loaves first for optimal p5.brush fill caching
  drawAllLoafBaseWashes(loaves);

  // Render dense cross-hatching, octagonal gul stamps, blisters & seeds per loaf
  for (let i = 0; i < loaves.length; i++) {
    renderHyperrealLoaf(loaves[i]);
  }

  noLoop();
}

// =============================================================================
// PHASE 1: MADDER-RED WOVEN CLOTH
// =============================================================================
function drawMadderClothGround() {
  brush.noStroke();

  // Deep madder watercolor base washes
  brush.fill(PAL.clothDeep, 175);
  brush.fillBleed(0.25, "in");
  brush.fillTexture(0.55, 0.35);
  brush.rect(0, 0, width, height, "corner");

  // Rich crimson-madder variation patches
  brush.fill(PAL.clothMid, 120);
  brush.fillBleed(0.3, "out");
  for (let y = 60; y < height; y += 368) {
    for (let x = 60; x < width; x += 368) {
      brush.circle(x + 184, y + 184, 150, 0.25);
    }
  }

  brush.noFill();
  brush.noWash();

  // Fine warp and weft textile weave across the visible gap channels and borders
  // We focus cloth weave density on the diamond gaps & outer margins
  brush.set("cpencil", PAL.clothDark, 0.45);
  for (let y = 4; y < height; y += 6) {
    // Draw horizontal weft threads where cloth is exposed
    if (isClothVisibleRow(y)) {
      brush.line(0, y, width, y + random(-0.5, 0.5));
    } else {
      // Draw in the 4 gap columns: [0..85], [345..485], [715..855], [1115..1200]
      brush.line(0, y, 95, y);
      brush.line(335, y, 495, y);
      brush.line(705, y, 865, y);
      brush.line(1105, y, 1200, y);
    }
  }

  brush.set("rotring", PAL.clothBright, 0.35);
  for (let x = 4; x < width; x += 6) {
    if (isClothVisibleCol(x)) {
      brush.line(x, 0, x + random(-0.5, 0.5), height);
    } else {
      brush.line(x, 0, x, 95);
      brush.line(x, 335, x, 495);
      brush.line(x, 705, x, 865);
      brush.line(x, 1105, x, 1200);
    }
  }

  // Subtle crimson slub highlights in the weave
  brush.set("pen", PAL.clothHighlight, 0.3);
  for (let i = 0; i < 420; i++) {
    const gx = random(width);
    const gy = random(height);
    if (isPointInClothGap(gx, gy)) {
      const len = random(10, 28);
      if (random() < 0.5) {
        brush.line(gx - len / 2, gy, gx + len / 2, gy);
      } else {
        brush.line(gx, gy - len / 2, gx, gy + len / 2);
      }
    }
  }
}

function isClothVisibleRow(y) {
  return y < 78 || (y > 350 && y < 482) || (y > 718 && y < 850) || y > 1122;
}

function isClothVisibleCol(x) {
  return x < 78 || (x > 350 && x < 482) || (x > 718 && x < 850) || x > 1122;
}

function isPointInClothGap(x, y) {
  const centers = [232, 600, 968];
  for (let r = 0; r < 3; r++) {
    for (let c = 0; c < 3; c++) {
      const dx = x - centers[c];
      const dy = y - centers[r];
      if (dx * dx + dy * dy < 168 * 168) return false;
    }
  }
  return true;
}

// =============================================================================
// PHASE 2: INDIGO & IVORY DIAMOND MOTIFS IN THE LATTICE GAPS
// =============================================================================
function drawInterstitialLattice(startC, gridS) {
  // Gap coordinates: 4x4 grid of diamond centers
  // startC = 232, gridS = 368 -> gaps at 48, 416, 784, 1152
  const gapCoords = [
    startC - gridS / 2,
    startC + gridS / 2,
    startC + (3 * gridS) / 2,
    startC + (5 * gridS) / 2
  ];

  // First draw connecting ivory & indigo runner lines along the lattice seams
  for (let i = 0; i < 4; i++) {
    const pos = gapCoords[i];
    drawWovenRunnerLine(pos, 0, pos, height, true);
    drawWovenRunnerLine(0, pos, width, pos, false);
  }

  // Draw the 16 stepped diamond medallions (4 full interior, 8 edge, 4 corner)
  for (let r = 0; r < 4; r++) {
    for (let c = 0; c < 4; c++) {
      const gx = gapCoords[c];
      const gy = gapCoords[r];
      const isInterior = r >= 1 && r <= 2 && c >= 1 && c <= 2;
      const motifScale = isInterior ? 1.0 : 0.88;
      drawSteppedDiamondMotif(gx, gy, motifScale, (r + c) % 2);
    }
  }
}

function drawWovenRunnerLine(x1, y1, x2, y2, isVertical) {
  // Dashed/stepped ivory and indigo border stitch along the narrow channels
  const steps = 120;
  for (let i = 0; i < steps; i++) {
    const t1 = i / steps;
    const t2 = (i + 0.65) / steps;
    const ax = lerp(x1, x2, t1);
    const ay = lerp(y1, y2, t1);
    if (!isPointInClothGap(ax, ay)) continue;

    const bx = lerp(x1, x2, t2);
    const by = lerp(y1, y2, t2);

    brush.set("rotring", i % 2 === 0 ? PAL.ivoryMid : PAL.indigoDark, 0.55);
    brush.line(ax, ay, bx, by);

    if (i % 3 === 0) {
      brush.set("rotring", PAL.ivoryBright, 0.45);
      if (isVertical) {
        brush.line(ax - 5, ay, ax + 5, ay);
      } else {
        brush.line(ax, ay - 5, ax, ay + 5);
      }
    }
  }
}

function drawSteppedDiamondMotif(cx, cy, sc, variant) {
  const outerR = 112 * sc;
  const midR = 76 * sc;
  const innerR = 44 * sc;
  const coreR = 20 * sc;

  // 1. Deep Indigo Astroid/Diamond Base Wash
  brush.noStroke();
  brush.wash(PAL.indigoDark, 235);
  traceAstroidDiamond(cx, cy, outerR, 0.72);

  // 2. Stepped Ivory Frame & Woven Indigo Cross-Hatching
  brush.noWash();
  brush.noFill();

  // Woven indigo weft strokes inside the outer diamond
  const stepH = 3.5;
  for (let dy = -outerR; dy <= outerR; dy += stepH) {
    const normY = Math.abs(dy) / outerR;
    // Concave astroid width profile that fits snugly between 4 circles
    const halfW = outerR * Math.pow(Math.max(0, 1 - Math.pow(normY, 0.78)), 1.28);
    if (halfW > 2) {
      // Quantize to stepped carpet knots (6px grid)
      const qW = Math.floor(halfW / 5.5) * 5.5;
      if (qW > 1) {
        brush.set("rotring", Math.abs(dy) % 7 < 3.5 ? PAL.indigoAbyss : PAL.indigoMid, 0.65);
        brush.line(cx - qW, cy + dy, cx + qW, cy + dy);

        // Stepped ivory outer edge stitches (left & right stepped border)
        brush.set("cpencil", PAL.ivoryBright, 0.85);
        brush.line(cx - qW - 5, cy + dy, cx - qW + 2, cy + dy);
        brush.line(cx + qW - 2, cy + dy, cx + qW + 5, cy + dy);

        // Inner stepped ivory ring
        if (qW > 18 * sc) {
          brush.set("rotring", PAL.ivoryMid, 0.55);
          brush.line(cx - qW + 11 * sc, cy + dy, cx - qW + 15 * sc, cy + dy);
          brush.line(cx + qW - 15 * sc, cy + dy, cx + qW - 11 * sc, cy + dy);
        }
      }
    }
  }

  // Vertical warp threads in indigo & ivory across the diamond
  for (let dx = -outerR * 0.85; dx <= outerR * 0.85; dx += 4.5) {
    const normX = Math.abs(dx) / outerR;
    const halfH = outerR * Math.pow(Math.max(0, 1 - Math.pow(normX, 0.78)), 1.28);
    const qH = Math.floor(halfH / 5.5) * 5.5;
    if (qH > 2) {
      brush.set("rotring", PAL.indigoLight, 0.4);
      brush.line(cx + dx, cy - qH * 0.85, cx + dx, cy + qH * 0.85);
    }
  }

  // 3. Secondary Madder & Ivory Stepped Medallion Inside the Indigo Field
  for (let dy = -midR; dy <= midR; dy += 3.2) {
    const halfW = midR * (1 - Math.abs(dy) / midR);
    const qW = Math.floor(halfW / 5) * 5;
    if (qW > 1) {
      // Ivory stepped ring
      brush.set("cpencil", PAL.ivoryPure, 0.75);
      brush.line(cx - qW - 3.5, cy + dy, cx - qW + 3.5, cy + dy);
      brush.line(cx + qW - 3.5, cy + dy, cx + qW + 3.5, cy + dy);

      // Rich madder-red inner carpet field
      if (qW > 7) {
        brush.set("rotring", variant === 0 ? PAL.clothMid : PAL.clothDeep, 0.65);
        brush.line(cx - qW + 4, cy + dy, cx + qW - 4, cy + dy);
      }
    }
  }

  // 4. Inner Indigo & Ochre-Gold Octagonal Star
  for (let dy = -innerR; dy <= innerR; dy += 3.0) {
    const halfW = innerR * (1 - Math.abs(dy) / innerR);
    const qW = Math.floor(halfW / 4) * 4;
    if (qW > 1) {
      brush.set("rotring", PAL.indigoAbyss, 0.7);
      brush.line(cx - qW, cy + dy, cx + qW, cy + dy);

      brush.set("rotring", PAL.ochreGold, 0.55);
      brush.line(cx - qW - 2.5, cy + dy, cx - qW + 1.5, cy + dy);
      brush.line(cx + qW - 1.5, cy + dy, cx + qW + 2.5, cy + dy);
    }
  }

  // 5. High-Contrast Ivory Center Cross & Four Cardinal Ram's-Horn Finials
  brush.set("cpencil", PAL.ivoryPure, 0.85);
  for (let d = -coreR; d <= coreR; d += 3) {
    const span = coreR - Math.abs(d);
    brush.line(cx - span, cy + d, cx + span, cy + d);
  }
  brush.set("rotring", PAL.indigoAbyss, 0.75);
  brush.line(cx - coreR * 0.6, cy, cx + coreR * 0.6, cy);
  brush.line(cx, cy - coreR * 0.6, cx, cy + coreR * 0.6);

  // Cardinal Latch-Hooks extending into the 4 narrow channels between loaves
  const dirs = [
    [1, 0],
    [-1, 0],
    [0, 1],
    [0, -1]
  ];
  for (let d = 0; d < 4; d++) {
    const dx = dirs[d][0];
    const dy = dirs[d][1];
    const px = -dy;
    const py = dx;

    for (let k = 1; k <= 4; k++) {
      const dist = outerR * 0.72 + k * 9 * sc;
      const wing = (5 - k) * 4.5 * sc;
      const hx = cx + dx * dist;
      const hy = cy + dy * dist;

      brush.set("rotring", PAL.indigoAbyss, 0.85);
      brush.line(hx - px * (wing + 2), hy - py * (wing + 2), hx + px * (wing + 2), hy + py * (wing + 2));

      brush.set("cpencil", PAL.ivoryPure, 0.75);
      brush.line(hx - px * wing, hy - py * wing, hx + px * wing, hy + py * wing);
    }
  }

  // Diagonal X-stitch accents in the 4 concave corners facing the loaves
  const diagDirs = [
    [1, 1],
    [-1, 1],
    [1, -1],
    [-1, -1]
  ];
  for (let d = 0; d < 4; d++) {
    const sx = cx + diagDirs[d][0] * 44 * sc;
    const sy = cy + diagDirs[d][1] * 44 * sc;
    brush.set("rotring", PAL.ivoryBright, 0.6);
    brush.line(sx - 6 * sc, sy - 6 * sc, sx + 6 * sc, sy + 6 * sc);
    brush.line(sx - 6 * sc, sy + 6 * sc, sx + 6 * sc, sy - 6 * sc);
  }
}

function traceAstroidDiamond(cx, cy, rad, power) {
  brush.beginShape(0.15);
  const steps = 36;
  for (let i = 0; i < steps; i++) {
    const ang = (i / steps) * Math.PI * 2;
    const ca = Math.cos(ang);
    const sa = Math.sin(ang);
    const x = cx + Math.sign(ca) * Math.pow(Math.abs(ca), power) * rad;
    const y = cy + Math.sign(sa) * Math.pow(Math.abs(sa), power) * rad;
    brush.vertex(x, y);
  }
  brush.endShape(true);
}

// =============================================================================
// PHASE 3: LOAF GEOMETRY GENERATION & CAST SHADOWS ON CLOTH
// =============================================================================
function createLoafData(cx, cy, R0, row, col, idx) {
  // Unique organic parameters for each loaf while keeping strict architectural family
  const seedBase = (idx + 1) * 917;
  const h2 = random(-3.2, 3.2);
  const p2 = random(0, Math.PI * 2);
  const h3 = random(-2.8, 2.8);
  const p3 = random(0, Math.PI * 2);
  const h4 = random(-2.0, 2.0);
  const p4 = random(0, Math.PI * 2);
  const h5 = random(-1.6, 1.6);
  const p5 = random(0, Math.PI * 2);
  const h8 = random(0.8, 2.2); // subtle octagonal memory from the stamp

  const rotDeg = random(-7.5, 7.5);
  const rotRad = rotDeg * DEG2RAD;
  const wellRatio = random(0.465, 0.495);
  const bakeFactor = random(0.9, 1.14); // variation in oven char intensity
  const fluteCount = 24;

  // Generate blisters for this loaf
  const blisters = [];
  // 18 hero blisters along the toroidal rim crest (u in 0.57 .. 0.88)
  const numHero = floor(random(16, 22));
  for (let b = 0; b < numHero; b++) {
    const bAng = (b / numHero) * Math.PI * 2 + random(-0.12, 0.12);
    const bu = random(0.58, 0.86);
    const br = random(7, 21) * (bu > 0.65 && bu < 0.8 ? 1.18 : 0.85);
    const charLevel = constrain(
      map(bu, 0.56, 0.78, 0.4, 1.0) * bakeFactor + random(-0.2, 0.25),
      0.15,
      1.0
    );
    blisters.push({
      ang: bAng,
      u: bu,
      r: br,
      aspect: random(1.15, 1.55), // stretched tangentially along dough ring
      charLevel: charLevel,
      cracked: random() < 0.55
    });
  }
  // 3-4 smaller blisters inside the central well
  for (let b = 0; b < 4; b++) {
    const bAng = random(Math.PI * 2);
    const bu = random(0.14, 0.4);
    blisters.push({
      ang: bAng,
      u: bu,
      r: random(5, 10),
      aspect: random(1.0, 1.25),
      charLevel: random(0.35, 0.75) * bakeFactor,
      cracked: false
    });
  }

  return {
    cx,
    cy,
    R0,
    row,
    col,
    idx,
    seedBase,
    h2,
    p2,
    h3,
    p3,
    h4,
    p4,
    h5,
    p5,
    h8,
    rotDeg,
    rotRad,
    wellRatio,
    bakeFactor,
    fluteCount,
    blisters,
    getRadius: function (radAngle) {
      return (
        this.R0 +
        this.h2 * Math.cos(2 * radAngle + this.p2) +
        this.h3 * Math.sin(3 * radAngle + this.p3) +
        this.h4 * Math.cos(4 * radAngle + this.p4) +
        this.h5 * Math.sin(5 * radAngle + this.p5) +
        this.h8 * Math.cos(8 * (radAngle - this.rotRad))
      );
    }
  };
}

function drawLoafCastShadows(loaves) {
  // Batch dark shadow washes first
  brush.noStroke();
  brush.fill(PAL.clothAbyss, 215);
  brush.fillBleed(0.22, "out");
  brush.fillTexture(0.45, 0.4);

  for (let i = 0; i < loaves.length; i++) {
    const L = loaves[i];
    // Offset toward bottom-right away from top-left light
    brush.beginShape(0.2);
    const steps = 40;
    for (let s = 0; s < steps; s++) {
      const ang = (s / steps) * Math.PI * 2;
      const r = L.getRadius(ang) + 5;
      // Stronger shadow projection on bottom-right (cos(ang - 45deg) > 0)
      const lightAlign = Math.cos(ang - Math.PI * 0.25);
      const off = 11 + Math.max(0, lightAlign) * 14;
      const sx = L.cx + Math.cos(ang) * r + off * 0.7;
      const sy = L.cy + Math.sin(ang) * r + off * 0.7;
      brush.vertex(sx, sy);
    }
    brush.endShape(true);
  }

  brush.noFill();
  brush.noWash();

  // Dense soot-black & deep oxblood cross-hatching around each loaf's contact shadow
  for (let i = 0; i < loaves.length; i++) {
    const L = loaves[i];
    const numShadowStrokes = 180;
    for (let s = 0; s < numShadowStrokes; s++) {
      const ang = (s / numShadowStrokes) * Math.PI * 2;
      const rEdge = L.getRadius(ang);
      const lightAlign = Math.cos(ang - Math.PI * 0.25); // peaks at +45 deg (bottom-right)
      const shadowSpan = 9 + Math.max(0, lightAlign + 0.3) * 20;

      const x1 = L.cx + Math.cos(ang) * (rEdge - 2);
      const y1 = L.cy + Math.sin(ang) * (rEdge - 2);
      const x2 = L.cx + Math.cos(ang) * (rEdge + shadowSpan);
      const y2 = L.cy + Math.sin(ang) * (rEdge + shadowSpan);

      brush.set("rotring", PAL.sootBlack, 0.85);
      brush.line(x1, y1, x2, y2);

      // Tangential cross-hatch in the cast shadow zone
      if (lightAlign > -0.2 && s % 2 === 0) {
        const midR = rEdge + shadowSpan * 0.45;
        const mx = L.cx + Math.cos(ang) * midR;
        const my = L.cy + Math.sin(ang) * midR;
        const tx = -Math.sin(ang) * 10;
        const ty = Math.cos(ang) * 10;
        brush.set("cpencil", PAL.clothAbyss, 0.8);
        brush.line(mx - tx, my - ty, mx + tx, my + ty);
      }
    }
  }
}

// =============================================================================
// PHASE 4A: BATCHED BASE WASHES FOR ALL 9 LOAVES
// =============================================================================
function drawAllLoafBaseWashes(loaves) {
  brush.noStroke();

  // 1. Opaque golden-ochre base wash so dark cloth doesn't bleed through bread
  for (let i = 0; i < loaves.length; i++) {
    const L = loaves[i];
    brush.wash(PAL.ochreWarm, 245);
    traceLoafRing(L, 1.0, 0, 0);
  }
  brush.noWash();

  // 2. Luminous pale gold highlight wash on top-left lit rim
  brush.fill(PAL.crustCream, 175);
  brush.fillBleed(0.18, "in");
  brush.fillTexture(0.4, 0.25);
  for (let i = 0; i < loaves.length; i++) {
    const L = loaves[i];
    traceLoafRing(L, 0.88, -14, -14);
  }

  // 3. Rich burnt sienna watercolor wash over the toasted rim & shadow side
  brush.fill(PAL.siennaBurnt, 145);
  brush.fillBleed(0.25, "in");
  brush.fillTexture(0.6, 0.45);
  for (let i = 0; i < loaves.length; i++) {
    const L = loaves[i];
    traceLoafRing(L, 0.92, 8, 8);
  }

  // 4. Deep caramelized sienna wash inside the sunken central stamped well
  brush.fill(PAL.siennaDeep, 165);
  brush.fillBleed(0.15, "in");
  for (let i = 0; i < loaves.length; i++) {
    const L = loaves[i];
    traceLoafOctagon(L, L.wellRatio * 1.03);
  }

  // 5. Warm golden cushion inside the center of the well
  brush.fill(PAL.ochreGold, 150);
  brush.fillBleed(0.15, "out");
  for (let i = 0; i < loaves.length; i++) {
    const L = loaves[i];
    traceLoafOctagon(L, L.wellRatio * 0.82);
  }

  brush.noFill();
  brush.noWash();
}

function traceLoafRing(L, scaleU, offX, offY) {
  brush.beginShape(0.2);
  const steps = 40;
  for (let s = 0; s < steps; s++) {
    const ang = (s / steps) * Math.PI * 2;
    const r = L.getRadius(ang) * scaleU;
    brush.vertex(L.cx + offX + Math.cos(ang) * r, L.cy + offY + Math.sin(ang) * r);
  }
  brush.endShape(true);
}

function traceLoafOctagon(L, uOct) {
  brush.beginShape(0.08);
  const steps = 16;
  for (let s = 0; s < steps; s++) {
    const ang = L.rotRad + (s / steps) * Math.PI * 2;
    const r = L.R0 * uOct;
    brush.vertex(L.cx + Math.cos(ang) * r, L.cy + Math.sin(ang) * r);
  }
  brush.endShape(true);
}

// =============================================================================
// 3D TOROIDAL BREAD SURFACE & LIGHTING MODEL
// =============================================================================
// Evaluates height z in [0..1], illumination Id in [0..1], specular Is, and glaze heat
function evalBreadSurface(L, u, radAngle) {
  const wR = L.wellRatio;
  let z = 0;
  let dzdu = 0; // radial slope (>0 slopes up outward, <0 slopes down outward)
  let dzdt = 0; // tangential slope from flutes/ribs

  if (u < wR) {
    // Central sunken well with gentle quilting
    const t = u / wR;
    z = 0.12 + 0.05 * Math.cos(t * Math.PI * 2);
    dzdu = -0.1 * Math.sin(t * Math.PI * 2);
  } else if (u < 0.74) {
    // Rising inner wall of the toroidal rim (slopes UP outward -> normal points INWARD)
    const t = (u - wR) / (0.74 - wR);
    z = 0.1 + 0.9 * Math.sin(t * Math.PI * 0.5);
    dzdu = 1.65 * Math.cos(t * Math.PI * 0.5);

    // Stamped radial flutes on the lower inner collar (wR .. 0.62)
    if (u < 0.63) {
      const fluteEnv = Math.sin(((u - wR) / (0.63 - wR)) * Math.PI);
      const fPhase = L.fluteCount * (radAngle - L.rotRad);
      z += 0.045 * fluteEnv * Math.cos(fPhase);
      dzdt = -0.22 * fluteEnv * Math.sin(fPhase);
    }
  } else {
    // Outer slope of the toroidal rim (slopes DOWN outward -> normal points OUTWARD)
    const t = Math.min(1, (u - 0.74) / (1.0 - 0.74));
    z = Math.pow(Math.cos(t * Math.PI * 0.5), 0.82);
    dzdu = -2.1 * Math.pow(Math.sin(t * Math.PI * 0.5), 0.65);
  }

  // Convert cylindrical slope (dzdu, dzdt) to 3D normal (nx, ny, nz)
  const ca = Math.cos(radAngle);
  const sa = Math.sin(radAngle);
  let nx = -dzdu * ca + dzdt * sa;
  let ny = -dzdu * sa - dzdt * ca;
  let nz = 1.0;
  const nLen = Math.sqrt(nx * nx + ny * ny + nz * nz);
  nx /= nLen;
  ny /= nLen;
  nz /= nLen;

  // Diffuse lighting from top-left raking light
  const Id = Math.max(0, nx * LIGHT.lx + ny * LIGHT.ly + nz * LIGHT.lz);

  // Specular highlight (half-vector with viewer (0,0,1))
  const hx = LIGHT.lx;
  const hy = LIGHT.ly;
  const hz = LIGHT.lz + 1.0;
  const hLen = Math.sqrt(hx * hx + hy * hy + hz * hz);
  const ndoth = Math.max(0, (nx * hx + ny * hy + nz * hz) / hLen);
  const Is = Math.pow(ndoth, 14);

  // Tandir radiant heat browning peaks on the high crest (u ~ 0.66 - 0.84)
  const crestHeat = Math.exp(-Math.pow((u - 0.73) / 0.13, 2)) * L.bakeFactor;

  return { z, Id, Is, crestHeat };
}

// =============================================================================
// PHASE 4B-4F: HYPERREAL LOAF RENDERING
// =============================================================================
function renderHyperrealLoaf(L) {
  // 1. Toroidal Rim Volumetric Cross-Hatching (Radial + Diagonal Mesh + Circumferential)
  drawToroidalRimCrossHatching(L);

  // 2. Octagonal Gul-Like Stamped Pattern in the Central Well (Stepped Borders & Pricked Dots)
  drawOctagonalGulStamp(L);

  // 3. Blistered Crust, Charred Soot Spots & Micro-Blisters
  drawBlisteredCrust(L);

  // 4. Sesame Seeds & Black Nigella Seeds
  drawSeedsOnLoaf(L);
}

// -----------------------------------------------------------------------------
// 1. TOROIDAL RIM VOLUMETRIC CROSS-HATCHING
// -----------------------------------------------------------------------------
function drawToroidalRimCrossHatching(L) {
  const wR = L.wellRatio;

  // PASS A: Radial Contour Hatching across the Torus (divided into 4 radial zones)
  const numRad = 180;
  const uZones = [
    [wR - 0.01, wR + 0.11], // Zone 0: Inner fluted collar
    [wR + 0.09, 0.73],      // Zone 1: Upper inner dome slope
    [0.7, 0.87],            // Zone 2: High glazed crest & outer shoulder
    [0.85, 1.0]             // Zone 3: Steep outer rim edge
  ];

  for (let i = 0; i < numRad; i++) {
    const ang = (i / numRad) * Math.PI * 2 + random(-0.006, 0.006);
    const rMax = L.getRadius(ang);
    const ca = Math.cos(ang);
    const sa = Math.sin(ang);
    const tx = -sa;
    const ty = ca;

    for (let zIdx = 0; zIdx < 4; zIdx++) {
      const u1 = uZones[zIdx][0] + random(-0.01, 0.01);
      const u2 = uZones[zIdx][1] + random(-0.01, 0.01);
      const uMid = 0.5 * (u1 + u2);
      const surf = evalBreadSurface(L, uMid, ang);

      // Select pigment color and weight from 3D illumination & tandir glaze heat
      let col = PAL.ochreWarm;
      let wt = 0.55;
      let bName = "rotring";

      if (surf.Id > 0.76) {
        col = surf.Is > 0.45 ? PAL.crustSpec : PAL.crustCream;
        wt = 0.65;
        bName = "cpencil";
      } else if (surf.Id > 0.58) {
        col = surf.crestHeat > 0.85 ? PAL.siennaWarm : PAL.ochreGold;
        wt = 0.58;
      } else if (surf.Id > 0.4) {
        col = surf.crestHeat > 0.75 ? PAL.siennaBurnt : PAL.ochreDeep;
        wt = 0.62;
      } else if (surf.Id > 0.24) {
        col = PAL.siennaDeep;
        wt = 0.7;
      } else {
        col = zIdx === 3 || zIdx === 0 ? PAL.sootChar : PAL.umberDark;
        wt = 0.78;
      }

      // Slight tangential curve to suggest 3D volume of the dough pillow
      const curveBend = (zIdx < 2 ? -1 : 1) * 2.2;
      const x1 = L.cx + ca * (rMax * u1);
      const y1 = L.cy + sa * (rMax * u1);
      const x2 = L.cx + ca * (rMax * u2) + tx * curveBend;
      const y2 = L.cy + sa * (rMax * u2) + ty * curveBend;

      brush.set(bName, col, wt);
      brush.line(x1, y1, x2, y2);

      // Extra soot/sienna shadow density in deep shadow troughs
      if (surf.Id < 0.34 && i % 2 === 0) {
        brush.set("rotring", surf.Id < 0.2 ? PAL.sootBlack : PAL.umberMid, 0.68);
        brush.line(x1 + tx * 1.8, y1 + ty * 1.8, x2 - tx * 1.2, y2 - ty * 1.2);
      }
    }
  }

  // PASS B: Multi-Directional Lozenge / Diagonal Cross-Hatching Rings
  // 16 concentric bands from u = wR to u = 0.99 with alternating +24 deg / -24 deg diagonal strokes
  const numBands = 16;
  for (let b = 0; b < numBands; b++) {
    const uBand = map(b, 0, numBands - 1, wR + 0.01, 0.985);
    const segs = floor(map(uBand, 0.48, 1.0, 56, 112));

    for (let s = 0; s < segs; s++) {
      const ang = (s / segs) * Math.PI * 2 + (b % 2) * 0.03;
      const rMax = L.getRadius(ang);
      const r = rMax * uBand;
      const surf = evalBreadSurface(L, uBand, ang);

      const cxp = L.cx + Math.cos(ang) * r;
      const cyp = L.cy + Math.sin(ang) * r;

      // Tangent angle + diagonal cross-hatch tilt
      const tilt = (b % 2 === 0 ? 22 : -22) * DEG2RAD;
      const strokeAng = ang + Math.PI * 0.5 + tilt;
      const halfLen = map(uBand, 0.48, 1.0, 6.5, 11.5);
      const dx = Math.cos(strokeAng) * halfLen;
      const dy = Math.sin(strokeAng) * halfLen;

      // High-contrast value selection
      if (surf.Id > 0.72) {
        // Specular & bright crust highlights
        brush.set("cpencil", surf.Is > 0.4 ? PAL.crustSpec : PAL.ochreBright, 0.65);
        brush.line(cxp - dx, cyp - dy, cxp + dx, cyp + dy);
      } else if (surf.Id > 0.48) {
        // Glazed burnt sienna & golden ochre midtones
        const midCol = surf.crestHeat > 0.82 ? PAL.siennaBurnt : PAL.ochreWarm;
        brush.set("rotring", midCol, 0.58);
        brush.line(cxp - dx, cyp - dy, cxp + dx, cyp + dy);

        // Counter-diagonal cross-hatch on the glazed crest
        if (surf.crestHeat > 0.78 && s % 2 === 0) {
          const cAng = ang + Math.PI * 0.5 - tilt;
          const cdx = Math.cos(cAng) * halfLen * 0.85;
          const cdy = Math.sin(cAng) * halfLen * 0.85;
          brush.set("rotring", PAL.siennaWarm, 0.5);
          brush.line(cxp - cdx, cyp - cdy, cxp + cdx, cyp + cdy);
        }
      } else {
        // Deep burnt sienna, roasted umber & soot-black shadow cross-hatching
        const shCol = surf.Id < 0.22 ? PAL.sootBlack : surf.Id < 0.34 ? PAL.umberDark : PAL.siennaDeep;
        brush.set("rotring", shCol, 0.72);
        brush.line(cxp - dx, cyp - dy, cxp + dx, cyp + dy);

        // Opposite diagonal hatch for dense shadow mesh
        const cAng = ang + Math.PI * 0.5 - tilt;
        const cdx = Math.cos(cAng) * halfLen * 0.9;
        const cdy = Math.sin(cAng) * halfLen * 0.9;
        brush.set("rotring", surf.Id < 0.28 ? PAL.sootChar : PAL.siennaBurnt, 0.62);
        brush.line(cxp - cdx, cyp - cdy, cxp + cdx, cyp + cdy);
      }
    }
  }

  // PASS C: Reflected Madder-Red Glow along the Shadowed Bottom-Right Rim Edge
  for (let s = 0; s < 48; s++) {
    const ang = map(s, 0, 48, -Math.PI * 0.15, Math.PI * 0.65);
    const r = L.getRadius(ang) * random(0.95, 0.99);
    const px = L.cx + Math.cos(ang) * r;
    const py = L.cy + Math.sin(ang) * r;
    const tx = -Math.sin(ang) * 7;
    const ty = Math.cos(ang) * 7;
    brush.set("cpencil", PAL.clothBright, 0.55);
    brush.line(px - tx, py - ty, px + tx, py + ty);
  }
}

// -----------------------------------------------------------------------------
// 2. OCTAGONAL GUL-LIKE STAMPED PATTERN (STEPPED BORDERS & PRICKED DOTS)
// -----------------------------------------------------------------------------
function drawOctagonalGulStamp(L) {
  const wR = L.wellRatio;
  const maxWellR = L.R0 * wR;

  // A. Deep Recessed Octagonal Moat & Stepped Carpet Collar (u ~ wR)
  // Draw 8 octagonal sides with stepped corner turrets (bastions)
  for (let side = 0; side < 8; side++) {
    const a1 = L.rotRad + side * (Math.PI / 4);
    const a2 = L.rotRad + (side + 1) * (Math.PI / 4);
    const midA = 0.5 * (a1 + a2);

    // Lighting of the moat groove (inner wall of groove faces opposite to midA)
    const grooveLight =
      Math.cos(midA) * LIGHT.lx + Math.sin(midA) * LIGHT.ly;

    // 3 concentric octagonal stepped rings at the perimeter of the well
    const ringScales = [0.98, 0.9, 0.81];
    for (let rIdx = 0; rIdx < 3; rIdx++) {
      const rr = maxWellR * ringScales[rIdx];
      const x1 = L.cx + Math.cos(a1) * rr;
      const y1 = L.cy + Math.sin(a1) * rr;
      const x2 = L.cx + Math.cos(a2) * rr;
      const y2 = L.cy + Math.sin(a2) * rr;

      // Deep stamped channel in soot/umber/sienna
      brush.set(
        "rotring",
        rIdx === 0 ? PAL.sootChar : PAL.siennaDeep,
        rIdx === 0 ? 0.95 : 0.72
      );
      brush.line(x1, y1, x2, y2);

      // Lit ridge next to the channel
      const ridgeOff = grooveLight > 0 ? -2.2 : 2.2;
      const nx = Math.cos(midA) * ridgeOff;
      const ny = Math.sin(midA) * ridgeOff;
      brush.set("cpencil", grooveLight > 0 ? PAL.crustCream : PAL.ochreGold, 0.65);
      brush.line(x1 + nx, y1 + ny, x2 + nx, y2 + ny);
    }

    // Stepped Carpet-Knot Bastions at each of the 8 Octagonal Vertices
    const vx = L.cx + Math.cos(a1) * (maxWellR * 0.91);
    const vy = L.cy + Math.sin(a1) * (maxWellR * 0.91);
    const radX = Math.cos(a1);
    const radY = Math.sin(a1);
    const tanX = -radY;
    const tanY = radX;

    for (let st = -2; st <= 2; st++) {
      const stepW = (3 - Math.abs(st)) * 3.8;
      const sx = vx + radX * (st * 3.2);
      const sy = vy + radY * (st * 3.2);
      brush.set("rotring", PAL.umberDark, 0.75);
      brush.line(sx - tanX * stepW, sy - tanY * stepW, sx + tanX * stepW, sy + tanY * stepW);

      brush.set("rotring", PAL.ochreBright, 0.5);
      brush.line(
        sx - tanX * (stepW - 1.5) + 1.2,
        sy - tanY * (stepW - 1.5) + 1.2,
        sx + tanX * (stepW - 1.5) + 1.2,
        sy + tanY * (stepW - 1.5) + 1.2
      );
    }

    // B. Stamped Sector Motif (Gul Petal / Stepped Diamond Hook) inside each of the 8 sectors
    const secR = maxWellR * 0.56;
    const scx = L.cx + Math.cos(midA) * secR;
    const scy = L.cy + Math.sin(midA) * secR;
    const sRadX = Math.cos(midA);
    const sRadY = Math.sin(midA);
    const sTanX = -sRadY;
    const sTanY = sRadX;

    // Stepped lozenge in each octant
    for (let k = -3; k <= 3; k++) {
      const span = (4 - Math.abs(k)) * 3.4;
      const px = scx + sRadX * (k * 3.6);
      const py = scy + sRadY * (k * 3.6);
      brush.set("rotring", k === 0 ? PAL.sootChar : PAL.siennaBurnt, 0.65);
      brush.line(px - sTanX * span, py - sTanY * span, px + sTanX * span, py + sTanY * span);

      if (Math.abs(k) <= 2) {
        brush.set("cpencil", PAL.crustCream, 0.55);
        brush.line(
          px - sTanX * (span * 0.55) + 1.5,
          py - sTanY * (span * 0.55) + 1.5,
          px + sTanX * (span * 0.55) + 1.5,
          py + sTanY * (span * 0.55) + 1.5
        );
      }
    }
  }

  // C. Cross-Hatching on the Pillowed Dough Cushions inside the Well
  const wellSteps = 14;
  for (let ix = -wellSteps; ix <= wellSteps; ix++) {
    for (let iy = -wellSteps; iy <= wellSteps; iy++) {
      const dx = (ix / wellSteps) * maxWellR * 0.78;
      const dy = (iy / wellSteps) * maxWellR * 0.78;
      const dist = Math.sqrt(dx * dx + dy * dy);
      if (dist < maxWellR * 0.76) {
        const px = L.cx + dx;
        const py = L.cy + dy;
        // Shadow from top-left inner rim wall falls on top-left of well (dx+dy < -0.35*maxWellR)
        const inRimShadow = dx * LIGHT.lx + dy * LIGHT.ly > maxWellR * 0.22;
        const hCol = inRimShadow
          ? PAL.siennaDeep
          : (ix + iy) % 2 === 0
          ? PAL.ochreGold
          : PAL.siennaWarm;
        brush.set("rotring", hCol, 0.48);
        brush.line(px - 3.5, py - 3.5, px + 3.5, py + 3.5);
        if (inRimShadow) {
          brush.set("rotring", PAL.umberDark, 0.52);
          brush.line(px - 3.5, py + 3.5, px + 3.5, py - 3.5);
        }
      }
    }
  }

  // D. RIGOROUS PRICKED DOT PATTERN (Chekich Tine Marks)
  // 1. Concentric octagonal rings of pricked dots
  const dotRingRadii = [0.16, 0.3, 0.44, 0.68, 0.85, 0.94];
  const dotsPerSide = [2, 3, 5, 7, 9, 10];

  for (let rIdx = 0; rIdx < dotRingRadii.length; rIdx++) {
    const rr = maxWellR * dotRingRadii[rIdx];
    const nDots = dotsPerSide[rIdx];

    for (let side = 0; side < 8; side++) {
      const a1 = L.rotRad + side * (Math.PI / 4);
      const a2 = L.rotRad + (side + 1) * (Math.PI / 4);
      const x1 = L.cx + Math.cos(a1) * rr;
      const y1 = L.cy + Math.sin(a1) * rr;
      const x2 = L.cx + Math.cos(a2) * rr;
      const y2 = L.cy + Math.sin(a2) * rr;

      for (let d = 0; d < nDots; d++) {
        const t = d / nDots;
        const dx = lerp(x1, x2, t);
        const dy = lerp(y1, y2, t);
        drawPrickedDot(dx, dy, 1.0);
      }
    }
  }

  // 2. Radial spoke lines of pricked dots along the 8 octagonal axes
  for (let side = 0; side < 8; side++) {
    const ang = L.rotRad + side * (Math.PI / 4);
    for (let step = 2; step <= 8; step++) {
      const rr = maxWellR * (step * 0.095);
      const dx = L.cx + Math.cos(ang) * rr;
      const dy = L.cy + Math.sin(ang) * rr;
      drawPrickedDot(dx, dy, 0.9);
    }
  }

  // 3. Stamped Radial Chekich Pricks climbing the lower inner slope of the rim
  for (let f = 0; f < L.fluteCount; f++) {
    const ang = L.rotRad + (f / L.fluteCount) * Math.PI * 2;
    for (let k = 0; k < 3; k++) {
      const rr = L.R0 * (wR + 0.025 + k * 0.032);
      const dx = L.cx + Math.cos(ang) * rr;
      const dy = L.cy + Math.sin(ang) * rr;
      drawPrickedDot(dx, dy, 0.85);
    }
  }

  // Central pricked rosette cluster
  drawPrickedDot(L.cx, L.cy, 1.25);
}

function drawPrickedDot(x, y, sz) {
  // Warm sienna puckered dough halo
  brush.set("rotring", PAL.siennaDeep, 0.9 * sz);
  brush.line(x - 1.8 * sz, y - 0.8 * sz, x + 1.2 * sz, y + 0.8 * sz);

  // Soot-black deep pinhole
  brush.set("rotring", PAL.sootBlack, 1.15 * sz);
  brush.line(x - 0.9 * sz, y - 0.5 * sz, x + 0.9 * sz, y + 0.5 * sz);

  // Crisp pale golden-cream lit lip on bottom-right of pinhole
  brush.set("cpencil", PAL.crustSpec, 0.75 * sz);
  brush.line(x + 0.4 * sz, y + 1.3 * sz, x + 1.9 * sz, y + 0.3 * sz);
}

// -----------------------------------------------------------------------------
// 3. HYPERREAL BLISTERED CRUST & CHARRED SOOT SPOTS
// -----------------------------------------------------------------------------
function drawBlisteredCrust(L) {
  // A. Hero Blisters on the Toroidal Rim and Well
  for (let i = 0; i < L.blisters.length; i++) {
    const B = L.blisters[i];
    const rLoaf = L.getRadius(B.ang);
    const bx = L.cx + Math.cos(B.ang) * (rLoaf * B.u);
    const by = L.cy + Math.sin(B.ang) * (rLoaf * B.u);
    const tangAng = B.ang + Math.PI * 0.5;
    const ct = Math.cos(tangAng);
    const st = Math.sin(tangAng);
    const cr = Math.cos(B.ang);
    const sr = Math.sin(B.ang);

    const rw = B.r * B.aspect; // tangential half-width
    const rh = B.r;            // radial half-height

    // 1. Cast shadow crescent of blister dome (toward bottom-right)
    brush.set("rotring", PAL.sootBlack, 0.85);
    for (let k = -4; k <= 4; k++) {
      const t = k / 4;
      const sx = bx + ct * (t * rw * 0.85) + 2.2;
      const sy = by + st * (t * rw * 0.85) + 2.2;
      brush.line(sx - 2, sy + rh * 0.55, sx + 2, sy + rh * 0.85);
    }

    // 2. Caramelized burnt-sienna & roasted-umber blister dome cross-hatching
    const domeLines = Math.max(6, floor(B.r * 0.9));
    for (let k = -domeLines; k <= domeLines; k++) {
      const norm = k / domeLines;
      const halfSpan = rw * Math.sqrt(Math.max(0, 1 - norm * norm));
      const ox = bx + cr * (norm * rh);
      const oy = by + sr * (norm * rh);

      const x1 = ox - ct * halfSpan;
      const y1 = oy - st * halfSpan;
      const x2 = ox + ct * halfSpan;
      const y2 = oy + st * halfSpan;

      // Outer ring is glossy burnt sienna; core is charred soot black
      const distFromCore = Math.abs(norm);
      if (distFromCore < 0.62 * B.charLevel) {
        brush.set("rotring", PAL.sootBlack, 0.95);
        brush.line(x1, y1, x2, y2);
        // Perpendicular carbon crackle hatch
        if (k % 2 === 0) {
          brush.set("charcoal", PAL.sootChar, 0.65);
          brush.line(
            ox - ct * halfSpan * 0.5 - cr * 2,
            oy - st * halfSpan * 0.5 - sr * 2,
            ox + ct * halfSpan * 0.5 + cr * 2,
            oy + st * halfSpan * 0.5 + sr * 2
          );
        }
      } else {
        brush.set("rotring", distFromCore < 0.82 ? PAL.umberDark : PAL.siennaBurnt, 0.75);
        brush.line(x1, y1, x2, y2);
      }
    }

    // 3. High-contrast blister rim specular highlight (top-left edge of dome) & ash crack
    for (let k = -3; k <= 3; k++) {
      const t = k / 3.5;
      const hx = bx + ct * (t * rw * 0.72) - 1.8;
      const hy = by + st * (t * rw * 0.72) - 1.8 - rh * 0.55 * (1 - t * t * 0.4);
      brush.set("cpencil", PAL.crustSpec, 0.85);
      brush.line(hx - ct * 2.5, hy - st * 2.5, hx + ct * 2.5, hy + st * 2.5);
    }

    if (B.cracked && B.r > 9) {
      // Fine pale golden crust fissure across the blister skin
      brush.set("rotring", PAL.crustCream, 0.5);
      brush.line(
        bx - ct * rw * 0.45 + cr * 1.5,
        by - st * rw * 0.45 + sr * 1.5,
        bx + ct * rw * 0.35 - cr * 1.5,
        by + st * rw * 0.35 - sr * 1.5
      );
    }
  }

  // B. 60 Micro-Blisters & Toasted Crust Flecks scattered across the rim
  for (let m = 0; m < 60; m++) {
    const ang = random(Math.PI * 2);
    const u = random(0.5, 0.94);
    const r = L.getRadius(ang) * u;
    const mx = L.cx + Math.cos(ang) * r;
    const my = L.cy + Math.sin(ang) * r;
    const sz = random(1.5, 3.8);

    brush.set("rotring", random() < 0.55 ? PAL.sootChar : PAL.siennaDeep, 0.85);
    brush.line(mx - sz, my - sz * 0.5, mx + sz, my + sz * 0.5);

    brush.set("cpencil", PAL.crustCream, 0.65);
    brush.line(mx - sz * 0.8, my - sz * 0.9, mx + sz * 0.3, my - sz * 0.4);
  }
}

// -----------------------------------------------------------------------------
// 4. HYPERREAL SESAME SEEDS & NIGELLA (BLACK CUMIN) SEEDS
// -----------------------------------------------------------------------------
function drawSeedsOnLoaf(L) {
  const wR = L.wellRatio;
  const totalSeeds = 155;

  for (let s = 0; s < totalSeeds; s++) {
    const ang = random(Math.PI * 2);
    // Natural distribution: dense in the stamped well moat (u ~ wR) and on the glazed crest
    let u;
    const pick = random();
    if (pick < 0.38) {
      u = wR + random(-0.08, 0.05); // pooled in the recessed collar
    } else if (pick < 0.82) {
      u = random(0.55, 0.84); // stuck to the egg-washed rim crest
    } else {
      u = random(0.12, 0.42); // scattered inside the gul stamp
    }

    const r = L.getRadius(ang) * u;
    const sx = L.cx + Math.cos(ang) * r;
    const sy = L.cy + Math.sin(ang) * r;
    const surf = evalBreadSurface(L, u, ang);

    // Seed orientation (mostly tangential with organic tumble)
    const sAng = ang + Math.PI * 0.5 + random(-0.7, 0.7);
    const dx = Math.cos(sAng) * 2.1;
    const dy = Math.sin(sAng) * 2.1;

    const isNigella = s % 5 === 0; // ~20% jet-black nigella seeds, ~80% golden-ivory sesame

    if (isNigella) {
      // Matte black three-cornered nigella seed with tiny cool highlight edge
      brush.set("rotring", PAL.nigellaBlack, 1.0);
      brush.line(sx - dx * 0.9, sy - dy * 0.9, sx + dx * 0.9, sy + dy * 0.9);
      if (surf.Id > 0.35) {
        brush.set("rotring", PAL.nigellaEdge, 0.45);
        brush.line(sx - dx * 0.4 - 0.5, sy - dy * 0.4 - 0.5, sx + dx * 0.3 - 0.5, sy + dy * 0.3 - 0.5);
      }
    } else {
      // Hyperreal Sesame Seed:
      // 1. Tiny dark umber contact shadow underneath
      brush.set("rotring", PAL.umberDark, 0.85);
      brush.line(sx - dx + 0.9, sy - dy + 1.0, sx + dx + 0.9, sy + dy + 1.0);

      // 2. Plump teardrop sesame body shaded by local 3D illumination
      let seedCol = PAL.sesameLight;
      if (surf.Id > 0.7) {
        seedCol = PAL.sesameSpec;
      } else if (surf.Id < 0.35) {
        seedCol = PAL.sesameShadow;
      } else if (surf.Id < 0.52 || surf.crestHeat > 0.9) {
        seedCol = PAL.sesameMid;
      }

      brush.set("cpencil", seedCol, 0.95);
      brush.line(sx - dx, sy - dy, sx + dx, sy + dy);

      // 3. Pinpoint highlight along the plump end of lit seeds
      if (surf.Id > 0.5) {
        brush.set("rotring", PAL.sesameSpec, 0.55);
        brush.line(sx - dx * 0.5 - 0.3, sy - dy * 0.5 - 0.3, sx + dx * 0.2 - 0.3, sy + dy * 0.2 - 0.3);
      }
    }
  }
}

