      let a = random(360);
      let r = sqrt(random()) * 0.78;
      let bx = sp.cx + cos(a) * sp.rx * r;
      let by = sp.cy + sin(a) * sp.ry * r;
      let bw = random(9, 16) * sc;
      let bh = bw * 0.55;

      // Draw a 3-lobed sage bush crown in crisp sepia pen
      brush.set("rotring", PAL.inkMid, sw(0.38));
      polyLine([
        [bx - bw * 0.6, by + bh * 0.2],
        [bx - bw * 0.35, by - bh * 0.45],
        [bx, by - bh * 0.7],
        [bx + bw * 0.35, by - bh * 0.45],
        [bx + bw * 0.6, by + bh * 0.2]
      ], 0.45);
      // Shaded right-side foliage ticks
      brush.set("rotring", PAL.inkDark, sw(0.3));
      brush.line(bx + bw * 0.15, by - bh * 0.2, bx + bw * 0.35, by + bh * 0.15);
      brush.line(bx + bw * 0.32, by - bh * 0.1, bx + bw * 0.48, by + bh * 0.2);
    }
  }

  // 2. Columnar Mediterranean Cypresses
  for (let c of cypresses) {
    // Dark olive-green wash for cypress spire
    brush.noStroke();
    brush.wash(PAL.cypress, 215);
    polyShape([
      [c.x, c.y - c.h],
      [c.x + c.w * 0.55, c.y - c.h * 0.28],
      [c.x + c.w * 0.38, c.y],
      [c.x - c.w * 0.38, c.y],
      [c.x - c.w * 0.55, c.y - c.h * 0.28]
    ]);
    brush.noWash();

    // Trunk & tufted sepia foliage outline
    brush.set("rotring", PAL.inkDark, sw(0.45));
    brush.line(c.x, c.y, c.x, c.y + 4);
    for (let h = 0.1; h < 0.95; h += 0.16) {
      let yy = c.y - c.h * h;
      let ww = c.w * 0.55 * sin(h * 165);
      brush.line(c.x - ww, yy + 2, c.x, yy - 3);
      brush.line(c.x, yy - 3, c.x + ww, yy + 2);
    }
  }
}

function drawQuaysPiersAndBreakwaterPen() {
  // 1. Main Ferry Pier, Riva Quay & South Breakwater Coping Edges & Seawalls
  const quayEdges = [
    // North Quay to Pier Root
    [[390, 290], [525, 365], 16],
    // Main Ferry Pier Outer Edge
    [[532, 392], [376, 510], 18],
    // Main Ferry Pier Head
    [[376, 510], [416, 556], 20],
    // Main Ferry Pier Inner Edge
    [[416, 556], [582, 442], 18],
    // Curved Riva Promenade Seawall
    [[582, 442], [712, 518], 20],
    [[712, 518], [832, 622], 22],
    [[832, 622], [916, 758], 22],
    [[916, 758], [892, 868], 22],
    // South Breakwater Inner Edge
    [[892, 868], [650, 902], 20],
    [[650, 902], [408, 926], 22],
    // South Breakwater Outer Seaward Wall
    [[404, 962], [720, 975], 24],
    [[720, 975], [1200, 915], 24]
  ];

  for (let qe of quayEdges) {
    let [p0, p1, wallH] = qe;
    // Top coping stone edge (double line)
    brush.set("rotring", PAL.inkDark, sw(0.65));
    brush.line(p0[0], p0[1], p1[0], p1[1]);
    brush.set("rotring", PAL.inkMid, sw(0.38));
    brush.line(p0[0], p0[1] - 3, p1[0], p1[1] - 3);

    // Bottom waterline edge
    brush.set("rotring", PAL.inkDark, sw(0.55));
    brush.line(p0[0], p0[1] + wallH, p1[0], p1[1] + wallH);

    // Horizontal masonry courses
    brush.set("rotring", PAL.inkMid, sw(0.3));
    brush.line(p0[0], p0[1] + wallH * 0.35, p1[0], p1[1] + wallH * 0.35);
    brush.line(p0[0], p0[1] + wallH * 0.7, p1[0], p1[1] + wallH * 0.7);

    // Vertical stone joints & coping slab ticks
    let len = dist(p0[0], p0[1], p1[0], p1[1]);
    let steps = floor(len / 14);
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let x = lerp(p0[0], p1[0], t);
      let y = lerp(p0[1], p1[1], t);
      // Coping tick
      brush.line(x, y - 3, x, y + wallH * 0.35);
      // Staggered lower masonry joint
      let x2 = lerp(p0[0], p1[0], min(1, t + 0.5 / steps));
      let y2 = lerp(p0[1], p1[1], min(1, t + 0.5 / steps));
      brush.line(x2, y2 + wallH * 0.35, x2, y2 + wallH * 0.7);
      brush.line(x, y + wallH * 0.7, x, y + wallH);
    }

    // Timber fenders along the Main Ferry Pier (for the ferry to berth against!)
    if (p0[0] === 532 || p0[0] === 376) {
      for (let i = 1; i < steps; i += 2) {
        let t = i / steps;
        let x = lerp(p0[0], p1[0], t);
        let y = lerp(p0[1], p1[1], t);
        brush.set("rotring", PAL.inkDark, sw(0.9));
        brush.line(x, y + 1, x, y + wallH - 1);
      }
    }
  }

  // 2. Round Stone Harbour Beacon / Mole Lantern Tower at Breakwater Head (x: 412, y: 924)
  drawMoleLanternTower(412, 928);

  // 3. Floating Wooden Jetties plank detailing in South Basin
  const jetties = [
    [[625, 804], [885, 774]],
    [[665, 848], [898, 822]]
  ];
  for (let j of jetties) {
    let [j0, j1] = j;
    brush.set("rotring", PAL.inkDark, sw(0.5));
    brush.line(j0[0], j0[1], j1[0], j1[1]);
    brush.line(j0[0] + 3, j0[1] + 12, j1[0] + 3, j1[1] + 12);
    for (let i = 0; i <= 28; i++) {
      let t = i / 28;
      let x = lerp(j0[0], j1[0], t);
      let y = lerp(j0[1], j1[1], t);
      brush.set("rotring", PAL.inkMid, sw(0.32));
      brush.line(x, y, x + 3, y + 12);
    }
  }
}

function drawMoleLanternTower(x, y) {
  let r = 18, h = 42;
  // Circular stone bastion base & cylindrical lantern tower
  brush.noStroke();
  brush.wash(PAL.wallOchre, 240);
  polyShape([
    [x - r, y], [x + r, y],
    [x + r * 0.85, y - h], [x - r * 0.85, y - h]
  ]);
  brush.wash(PAL.wallShade1, 220);
  polyShape([
    [x, y], [x + r, y],
    [x + r * 0.85, y - h], [x, y - h]
  ]);
  brush.wash(PAL.roofBright, 235);
  polyShape([
    [x - r * 0.65, y - h - 10],
    [x + r * 0.65, y - h - 10],
    [x, y - h - 22]
  ]);
  brush.noWash();

  // Crisp sepia pen masonry & iron lantern gallery
  brush.set("rotring", PAL.inkDark, sw(0.55));
  polyLine([[x - r, y], [x - r * 0.3, y + 6], [x + r * 0.3, y + 6], [x + r, y]], 0.3);
  brush.line(x - r, y, x - r * 0.85, y - h);
  brush.line(x + r, y, x + r * 0.85, y - h);
  polyLine([[x - r * 0.95, y - h], [x, y - h + 4], [x + r * 0.95, y - h]], 0.3);

  // Stone courses on tower
  brush.set("rotring", PAL.inkMid, sw(0.32));
  for (let k = 1; k <= 5; k++) {
    let yy = y - (h * k) / 6;
    let rr = lerp(r, r * 0.85, k / 6);
    polyLine([[x - rr, yy], [x, yy + 3], [x + rr, yy]], 0.3);
  }
  // Lantern glass cage & conical terracotta cap
  brush.set("rotring", PAL.inkDark, sw(0.45));
  brush.rect(x - r * 0.55, y - h - 10, r * 1.1, 10, "corner");
  polyLine([[x - r * 0.65, y - h - 10], [x, y - h - 22], [x + r * 0.65, y - h - 10]], 0.05);
  brush.line(x, y - h - 22, x, y - h - 29);
}

// =============================================================================
// MOORED DINGHIES, SAILBOATS & THE ISLAND FERRY (CRISP SEPIA PEN)
// =============================================================================
function drawMooredDinghiesAndSailboatsPen() {
  // 1. Moored Dinghies & Fishing Gozzi
  for (let d of dinghies) {
    if (!d.pts) continue;
    let dux = cos(d.ang), duy = sin(d.ang);
    let dvx = -sin(d.ang), dvy = cos(d.ang);
    let L = d.len * 0.5, W = d.beam * 0.5;

    // Inner wooden hull cockpit wash
    brush.noStroke();
    brush.wash(PAL.paperWarm, 220);
    let innerPts = d.pts.map(p => [lerp(d.x, p[0], 0.74), lerp(d.y, p[1], 0.74)]);
    polyShape(innerPts);
    brush.noWash();

    // Outer hull contour & double gunwale rub-rail in crisp sepia pen
    brush.set("rotring", PAL.inkDark, sw(0.52));
    polyLine([...d.pts, d.pts[0]], 0.25);
    brush.set("rotring", PAL.inkMid, sw(0.34));
    polyLine([...innerPts, innerPts[0]], 0.25);

    // Wooden thwarts (benches) & bottom floorboards
    for (let t of [-0.35, 0.0, 0.32]) {
      let tx = d.x + dux * L * t;
      let ty = d.y + duy * L * t;
      let tw = W * (0.72 - abs(t) * 0.35);
      brush.set("rotring", PAL.inkDark, sw(0.4));
      brush.line(tx - dvx * tw, ty - dvy * tw, tx + dvx * tw, ty + dvy * tw);
    }
    // Keel & floorboard line
    brush.set("rotring", PAL.inkLight, sw(0.28));
    brush.line(d.x - dux * L * 0.65, d.y - duy * L * 0.65, d.x + dux * L * 0.65, d.y + duy * L * 0.65);

    // Optional small cuddy cabin on fishing gozzo
    if (d.hasCabin) {
      brush.noStroke();
      brush.wash(PAL.wallCream, 235);
      let c0 = [d.x + dux * L * 0.05 - dvx * W * 0.55, d.y + duy * L * 0.05 - dvy * W * 0.55 - 3];
      let c1 = [d.x + dux * L * 0.45 - dvx * W * 0.45, d.y + duy * L * 0.45 - dvy * W * 0.45 - 3];
      let c2 = [d.x + dux * L * 0.45 + dvx * W * 0.45, d.y + duy * L * 0.45 + dvy * W * 0.45 - 3];
      let c3 = [d.x + dux * L * 0.05 + dvx * W * 0.55, d.y + duy * L * 0.05 + dvy * W * 0.55 - 3];
      polyShape([c0, c1, c2, c3]);
      brush.noWash();
      brush.set("rotring", PAL.inkDark, sw(0.4));
      polyLine([c0, c1, c2, c3, c0], 0.05);
    }

    // Tiny wooden oars resting across the gunwales
    if (d.hasOars) {
      brush.set("rotring", PAL.inkMid, sw(0.35));
      for (let s of [-0.55, 0.55]) {
        let ox0 = d.x - dux * L * 0.45 + dvx * W * s;
        let oy0 = d.y - duy * L * 0.45 + dvy * W * s;
        let ox1 = d.x + dux * L * 0.35 + dvx * W * s * 1.3;
        let oy1 = d.y + duy * L * 0.35 + dvy * W * s * 1.3;
        brush.line(ox0, oy0, ox1, oy1);
      }
    }

    // Mooring rope from bow to bollard or buoy
    let bow = d.pts[0];
    brush.set("rotring", PAL.inkMid, sw(0.32));
    polyLine([
      bow,
      [(bow[0] + d.moorX) * 0.5, (bow[1] + d.moorY) * 0.5 + 5],
      [d.moorX, d.moorY]
    ], 0.4);

    if (d.buoy) {
      brush.noStroke();
      brush.wash(PAL.roofBright, 230);
      brush.circle(d.moorX, d.moorY, 2.5, 0.1);
      brush.noWash();
      brush.set("rotring", PAL.inkDark, sw(0.35));
      brush.circle(d.moorX, d.moorY, 2.5, 0.1);
    }

    // Waterline ripple hugging the dinghy
    brush.set("rotring", PAL.inkLight, sw(0.28));
    polyLine([
      [d.pts[0][0] + dux * 3, d.pts[0][1] + duy * 3 + 2],
      [d.pts[1][0] + dvx * 3, d.pts[1][1] + dvy * 3 + 3],
      [d.pts[2][0] + dvx * 3, d.pts[2][1] + dvy * 3 + 3],
      [d.pts[3][0] - dux * 3, d.pts[3][1] - duy * 3 + 2]
    ], 0.35);
  }

  // 2. Sailboats in the outer bay & horizon
  for (let sb of sailboats) {
    let { x, y, sc, ang } = sb;
    let L = 24 * sc, H = 38 * sc;
    let ux = cos(ang), uy = sin(ang);

    // Sail shadow & cream canvas fill
    brush.noStroke();
    brush.wash(PAL.wallCream, 235);
    // Mainsail
    polyShape([
      [x, y - 4 * sc],
      [x, y - H],
      [x - ux * L * 0.85, y - 7 * sc]
    ]);
    // Jib sail
    polyShape([
      [x + ux * 2 * sc, y - 5 * sc],
      [x, y - H * 0.88],
      [x + ux * L * 0.78, y - 4 * sc]
    ]);
    // Hull wash
    brush.wash(PAL.roofBright, 225);
    polyShape([
      [x - ux * L * 0.8, y],
      [x + ux * L * 0.85, y],
      [x + ux * L * 0.6, y + 5 * sc],
      [x - ux * L * 0.65, y + 5 * sc]
    ]);
    brush.noWash();

    // Sepia pen rigging, mast, sails & hull
    brush.set("rotring", PAL.inkDark, sw(0.45));
    brush.line(x, y, x, y - H - 3 * sc);
    polyLine([[x, y - H], [x - ux * L * 0.85, y - 7 * sc], [x, y - 4 * sc]], 0.15);
    polyLine([[x, y - H * 0.88], [x + ux * L * 0.78, y - 4 * sc], [x + ux * 2 * sc, y - 5 * sc]], 0.2);
    polyLine([
      [x - ux * L * 0.8, y],
      [x + ux * L * 0.85, y],
      [x + ux * L * 0.6, y + 5 * sc],
      [x - ux * L * 0.65, y + 5 * sc],
      [x - ux * L * 0.8, y]
    ], 0.15);
  }
}

function drawIslandFerryPen() {
  let fx = 235, fy = 675, fang = -34;
  let ux = cos(fang), uy = sin(fang);
  let vx = -sin(fang), vy = cos(fang);
  function fp(l, w, h = 0) {
    return [fx + ux * l + vx * w, fy + uy * l + vy * w - h];
  }

  // 1. Waterline & Hull Strakes
  brush.set("rotring", PAL.inkDark, sw(0.7));
  polyLine([
    fp(-120, -26, 0), fp(-120, 28, 0),
    fp(85, 30, 0), fp(132, 0, 0), fp(85, -30, 0)
  ], 0.18);

  // Bulwark / Main Car-Deck Gunwale (h = 16, flared bow h = 20)
  let deckContour = [
    fp(-122, -26, 16), fp(82, -28, 16), fp(136, 0, 20),
    fp(82, 28, 16), fp(-122, 26, 16), fp(-122, -26, 16)
  ];
  brush.set("rotring", PAL.inkDark, sw(0.65));
  polyLine(deckContour, 0.12);

  // Hull rubbing strakes & bow anchor hawsepipe
  brush.set("rotring", PAL.inkMid, sw(0.4));
  polyLine([fp(-121, 27, 8), fp(83, 29, 8), fp(134, 0, 10)], 0.15);
  polyLine([fp(-121, 27, 12), fp(83, 29, 12), fp(135, 0, 15)], 0.15);
  brush.set("rotring", PAL.inkDark, sw(0.55));
  brush.circle(fp(108, 14, 11)[0], fp(108, 14, 11)[1], 3, 0.1);

  // Foredeck car ramp & tiny cars waiting to disembark
  brush.set("rotring", PAL.inkMid, sw(0.42));
  polyLine([fp(68, -16, 16), fp(122, -8, 18), fp(122, 8, 18), fp(68, 16, 16)], 0.05);
  // Two tiny vehicles on foredeck
  for (let cw of [-7, 7]) {
    brush.noStroke();
    brush.wash(cw < 0 ? PAL.roofBright : PAL.umbGold, 220);
    polyShape([fp(76, cw - 4, 17), fp(92, cw - 4, 17), fp(92, cw + 4, 19), fp(76, cw + 4, 19)]);
    brush.noWash();
    brush.set("rotring", PAL.inkDark, sw(0.38));
    polyLine([fp(76, cw - 4, 17), fp(92, cw - 4, 17), fp(92, cw + 4, 19), fp(76, cw + 4, 19), fp(76, cw - 4, 17)], 0.05);
  }

  // 2. Lower Saloon Deck & Promenade Deck Superstructure
  for (let dh of [16, 31, 46]) {
    let L0 = dh === 46 ? -105 : -112;
    let L1 = dh === 46 ? 60 : 72;
    let W = dh === 46 ? 21 : 24;
    brush.set("rotring", PAL.inkDark, sw(0.55));
    polyLine([
      fp(L0, -W, dh), fp(L1, -W, dh), fp(L1 + 14, 0, dh),
      fp(L1, W, dh), fp(L0, W, dh), fp(L0, -W, dh)
    ], 0.06);
  }

  // Vertical corner stanchions of superstructure
  brush.set("rotring", PAL.inkDark, sw(0.48));
  for (let l of [-105, -60, -15, 30, 58]) {
    let pA = fp(l, 23, 16), pB = fp(l, 21, 46);
    brush.line(pA[0], pA[1], pB[0], pB[1]);
  }

  // Rows of saloon windows along starboard side (h = 21 and h = 36)
  for (let rowH of [20, 35]) {
    for (let l = -98; l <= 50; l += 11) {
      let w0 = fp(l, 23, rowH);
      let w1 = fp(l + 7, 23, rowH);
      let w2 = fp(l + 7, 23, rowH + 6);
      let w3 = fp(l, 23, rowH + 6);
      brush.noStroke();
      brush.wash(PAL.inkDark, 195);
      polyShape([w0, w1, w2, w3]);
      brush.noWash();
      brush.set("rotring", PAL.inkDark, sw(0.35));
      polyLine([w0, w1, w2, w3, w0], 0.02);
    }
  }

  // 3. Navigation Bridge & Wing Cabs (l: 35..66, h: 46..58)
  brush.noStroke();
  brush.wash(PAL.wallCream, 240);
  polyShape([
    fp(32, -23, 46), fp(62, -23, 46), fp(70, 0, 46), fp(62, 25, 46), fp(32, 25, 46),
    fp(32, 23, 58), fp(60, 23, 58), fp(68, 0, 58), fp(32, -21, 58)
  ]);
  brush.noWash();

  brush.set("rotring", PAL.inkDark, sw(0.55));
  polyLine([
    fp(32, -21, 58), fp(60, -21, 58), fp(68, 0, 58),
    fp(60, 23, 58), fp(32, 23, 58), fp(32, -21, 58)
  ], 0.06);

  // Bridge wrap-around windows
  for (let w = -16; w <= 16; w += 8) {
    let b0 = fp(63, w, 50), b1 = fp(63, w + 6, 50), b2 = fp(62, w + 6, 55), b3 = fp(62, w, 55);
    brush.set("rotring", PAL.inkDark, sw(0.45));
    polyLine([b0, b1, b2, b3, b0], 0.02);
  }

  // 4. Streamlined Funnel, Radar Mast & Signal Flags
  brush.set("rotring", PAL.inkDark, sw(0.55));
  polyLine([
    fp(-22, -6, 46), fp(4, -6, 46), fp(4, 6, 46), fp(-22, 6, 46),
    fp(-20, 5, 72), fp(-2, 5, 72), fp(-2, -5, 72), fp(-20, -5, 72)
  ], 0.08);
  // Prussian band on funnel
  brush.set("rotring", PAL.inkDark, sw(0.9));
  let fBand0 = fp(-19, 5, 65), fBand1 = fp(-2, 5, 65);
  brush.line(fBand0[0], fBand0[1], fBand1[0], fBand1[1]);

  // Radar Mast on Bridge Roof
  let mBase = fp(48, 0, 58), mTop = fp(48, 0, 86);
  brush.set("rotring", PAL.inkDark, sw(0.55));
  brush.line(mBase[0], mBase[1], mTop[0], mTop[1]);
  // Yardarm & radar scanner bar
  let y0 = fp(48, -12, 76), y1 = fp(48, 12, 76);
  brush.line(y0[0], y0[1], y1[0], y1[1]);
  // Signal rigging lines & stern ensign flag
  let sternPost = fp(-120, 0, 28);
  brush.set("rotring", PAL.inkMid, sw(0.32));
  brush.line(mTop[0], mTop[1], fp(-18, 0, 72)[0], fp(-18, 0, 72)[1]);
  brush.line(mTop[0], mTop[1], fp(128, 0, 20)[0], fp(128, 0, 20)[1]);
  // Fluttering maritime flag at stern
  brush.noStroke();
  brush.wash(PAL.roofBright, 230);
  polyShape([sternPost, [sternPost[0] - 12, sternPost[1] - 6], [sternPost[0] - 10, sternPost[1] + 2]]);
  brush.noWash();
  brush.set("rotring", PAL.inkDark, sw(0.4));
  brush.line(fp(-120, 0, 16)[0], fp(-120, 0, 16)[1], sternPost[0], sternPost[1]);

  // 5. Aft Sun-Deck Awning Ribs & Tiny Passengers along the Rails
  brush.set("rotring", PAL. foamWhite, sw(0.45));
  for (let l = -98; l <= -30; l += 11) {
    let a0 = fp(l, -20, 46), a1 = fp(l, 20, 46);
    brush.line(a0[0], a0[1], a1[0], a1[1]);
  }
  // Lifeboats in davits (starboard side)
  brush.set("rotring", PAL.inkDark, sw(0.42));
  for (let lb of [-37, -5]) {
    polyLine([fp(lb - 11, 21, 34), fp(lb + 11, 21, 34), fp(lb + 9, 26, 30), fp(lb - 9, 26, 30), fp(lb - 11, 21, 34)], 0.15);
  }
}

// =============================================================================
// HYPERREAL BUILDINGS & INDIVIDUAL ROOFTOP TILES IN CRISP SEPIA PEN
// =============================================================================
function drawAllBuildingsAndRoofTilesPen() {
  for (let b of buildings) {
    let g = b.geom;
    if (!g) continue;

    // 1. Wall Outlines & Corner Quoins
    brush.set("rotring", PAL.inkDark, sw(0.52));
    // Front wall
    polyLine([g.F, g.R, g.RT, g.FT, g.F], 0.03);
    // Right side wall
    if (b.roofType === "gabled") {
      polyLine([g.R, g.B, g.BT, g.R1, g.RT], 0.03);
    } else {
      polyLine([g.R, g.B, g.BT, g.RT], 0.03);
    }

    // Stringcourses (horizontal floor moldings)
    brush.set("rotring", PAL.inkMid, sw(0.32));
    for (let s = 1; s < b.stories; s++) {
      let fh = (b.h * s) / b.stories;
      brush.line(g.F[0], g.F[1] - fh, g.R[0], g.R[1] - fh);
      brush.line(g.R[0], g.R[1] - fh, g.B[0], g.B[1] - fh);
    }

    // Shaded right wall diagonal cross-hatching for rich volume
    brush.set("rotring", PAL.inkLight, sw(0.26));
    let hatchSteps = floor(b.h / (4.5 * b.sc));
    for (let k = 1; k < hatchSteps; k++) {
      let hy = (b.h * k) / hatchSteps;
      brush.line(g.R[0], g.R[1] - hy, g.B[0], g.B[1] - hy);
    }

    // 2. Windows, Shutters, Ground Arcades & Balconies
    let cols = max(2, floor(b.w / (11 * b.sc)));
    for (let s = 0; s < b.stories; s++) {
      let yBot = (b.h * s) / b.stories;
      let yTop = (b.h * (s + 1)) / b.stories;

      for (let c = 0; c < cols; c++) {
        let u0 = (c + 0.28) / cols;
        let u1 = (c + 0.72) / cols;
        let uMid = (u0 + u1) * 0.5;

        if (s === 0 && b.arcade) {
          // Ground floor arched loggia opening
          let ax0 = lerp(g.F[0], g.R[0], u0), ay0 = lerp(g.F[1], g.R[1], u0);
          let ax1 = lerp(g.F[0], g.R[0], u1), ay1 = lerp(g.F[1], g.R[1], u1);
          let ah = (yTop - yBot) * 0.78;
          brush.noStroke();
          brush.wash(PAL.inkDark, 185);
          polyShape([
            [ax0, ay0], [ax1, ay1],
            [ax1, ay1 - ah * 0.7],
            [(ax0 + ax1) * 0.5, (ay0 + ay1) * 0.5 - ah],
            [ax0, ay0 - ah * 0.7]
          ]);
          brush.noWash();
          brush.set("rotring", PAL.inkDark, sw(0.42));
          polyLine([
            [ax0, ay0], [ax0, ay0 - ah * 0.7],
            [(ax0 + ax1) * 0.5, (ay0 + ay1) * 0.5 - ah],
            [ax1, ay1 - ah * 0.7], [ax1, ay1]
          ], 0.25);
        } else {
          // Upper story window with louvered shutters
          let wx0 = lerp(g.F[0], g.R[0], u0), wy0 = lerp(g.F[1], g.R[1], u0) - yBot - (yTop - yBot) * 0.2;
          let wx1 = lerp(g.F[0], g.R[0], u1), wy1 = lerp(g.F[1], g.R[1], u1) - yBot - (yTop - yBot) * 0.2;
          let wh = (yTop - yBot) * 0.55;

          brush.noStroke();
          brush.wash(PAL.inkDark, 180);
          polyShape([[wx0, wy0], [wx1, wy1], [wx1, wy1 - wh], [wx0, wy0 - wh]]);
          brush.noWash();

          brush.set("rotring", PAL.inkDark, sw(0.36));
          polyLine([[wx0, wy0], [wx1, wy1], [wx1, wy1 - wh], [wx0, wy0 - wh], [wx0, wy0]], 0.02);

          // Tiny open shutters on either side
          let shW = 2.2 * b.sc;
          brush.set("rotring", PAL.inkMid, sw(0.3));
          brush.line(wx0 - g.ux * shW, wy0, wx0 - g.ux * shW, wy0 - wh);
          brush.line(wx1 + g.ux * shW, wy1, wx1 + g.ux * shW, wy1 - wh);

          // Optional wrought-iron balcony on 2nd story
          if (s === 1 && b.balcony && c % 2 === 1) {
            let bx = lerp(g.F[0], g.R[0], uMid);
            let by = lerp(g.F[1], g.R[1], uMid) - yBot - (yTop - yBot) * 0.15;
            brush.set("rotring", PAL.inkDark, sw(0.42));
            brush.line(wx0 - 1, wy0 + 1, wx1 + 1, wy1 + 1);
            brush.line(bx - 4 * b.sc, by - 3 * b.sc, bx + 4 * b.sc, by - 2 * b.sc);
          }
        }
      }
    }

    // Side-wall windows
    let sideCols = max(1, floor(b.d / (13 * b.sc)));
    for (let s = 1; s < b.stories; s++) {
      let yMid = (b.h * (s + 0.35)) / b.stories;
      let wh = (b.h / b.stories) * 0.45;
      for (let c = 0; c < sideCols; c++) {
        let v0 = (c + 0.35) / sideCols;
        let v1 = (c + 0.65) / sideCols;
        let sx0 = lerp(g.R[0], g.B[0], v0), sy0 = lerp(g.R[1], g.B[1], v0) - yMid;
        let sx1 = lerp(g.R[0], g.B[0], v1), sy1 = lerp(g.R[1], g.B[1], v1) - yMid;
        brush.set("rotring", PAL.inkDark, sw(0.38));
        polyLine([[sx0, sy0], [sx1, sy1], [sx1, sy1 - wh], [sx0, sy0 - wh], [sx0, sy0]], 0.02);
      }
    }

    // 3. EVERY ROOFTOP TILE DRAWN IN CRISP SEPIA PEN!
    drawRoofTilesPen(b, g);

    // 4. Special Architectural Landmarks (Clocktower, Church Dome, Lighthouse, Windmill)
    if (b.special) {
      drawSpecialLandmarkDetails(b, g);
    }
  }
}

function drawRoofTilesPen(b, g) {
  // 1. Front-facing terracotta slope: quad [FT, RT, R1, R0]
  let tileCols = max(5, floor(b.w / (4.2 * b.sc)));
  let slopeLen = dist(g.FT[0], g.FT[1], g.R0[0], g.R0[1]);
  let tileRows = max(3, floor(slopeLen / (4.0 * b.sc)));

  // Down-slope pan tile seams
  brush.set("rotring", PAL.inkMid, sw(0.3));
  for (let i = 0; i <= tileCols; i++) {
    let u = i / tileCols;
    let topX = lerp(g.R0[0], g.R1[0], u);
    let topY = lerp(g.R0[1], g.R1[1], u);
    let botX = lerp(g.FT[0], g.RT[0], u);
    let botY = lerp(g.FT[1], g.RT[1], u);
    brush.line(topX, topY, botX, botY);
  }

  // Horizontal overlapping barrel tile courses (curved imbrications)
  brush.set("rotring", PAL.inkDark, sw(0.32));
  for (let r = 1; r <= tileRows; r++) {
    let v = r / tileRows;
    for (let i = 0; i < tileCols; i++) {
      let u0 = i / tileCols;
      let u1 = (i + 1) / tileCols;
      let x0 = lerp(lerp(g.R0[0], g.R1[0], u0), lerp(g.FT[0], g.RT[0], u0), v);
      let y0 = lerp(lerp(g.R0[1], g.R1[1], u0), lerp(g.FT[1], g.RT[1], u0), v);
      let x1 = lerp(lerp(g.R0[0], g.R1[0], u1), lerp(g.FT[0], g.RT[0], u1), v);
      let y1 = lerp(lerp(g.R0[1], g.R1[1], u1), lerp(g.FT[1], g.RT[1], u1), v);
      // Slight upward curve of each barrel tile mouth
      let xm = (x0 + x1) * 0.5;
      let ym = (y0 + y1) * 0.5 - 1.2 * b.sc;
      polyLine([[x0, y0], [xm, ym], [x1, y1]], 0.35);
    }
  }

  // 2. Right-side hip triangle: [RT, BT, R1]
  if (b.roofType !== "gabled") {
    let sideCols = max(3, floor(b.d / (4.4 * b.sc)));
    brush.set("rotring", PAL.inkMid, sw(0.3));
    for (let j = 1; j < sideCols; j++) {
      let v = j / sideCols;
      let bx = lerp(g.RT[0], g.BT[0], v);
      let by = lerp(g.RT[1], g.BT[1], v);
      brush.line(g.R1[0], g.R1[1], bx, by);
    }
    for (let r = 1; r <= tileRows; r++) {
      let t = r / tileRows;
      let pA = [lerp(g.R1[0], g.RT[0], t), lerp(g.R1[1], g.RT[1], t)];
      let pB = [lerp(g.R1[0], g.BT[0], t), lerp(g.R1[1], g.BT[1], t)];
      brush.line(pA[0], pA[1], pB[0], pB[1]);
    }
  }

  // 3. Left hip edge & back slope edge
  brush.set("rotring", PAL.inkDark, sw(0.52));
  polyLine([g.FT, g.R0, g.R1, g.RT, g.FT], 0.03);
  if (b.roofType !== "gabled") {
    polyLine([g.RT, g.BT, g.R1], 0.03);
    polyLine([g.FT, g.LT, g.R0], 0.03);
  } else {
    polyLine([g.BT, g.R1], 0.03);
  }

  // Thick segmented ridge tiles along [R0 -> R1]
  let ridgeSegs = max(4, floor(tileCols * 0.7));
  brush.set("rotring", PAL.inkDark, sw(0.62));
  for (let k = 0; k <= ridgeSegs; k++) {
    let t = k / ridgeSegs;
    let rx = lerp(g.R0[0], g.R1[0], t);
    let ry = lerp(g.R0[1], g.R1[1], t);
    brush.line(rx, ry - 1.5 * b.sc, rx, ry + 1.5 * b.sc);
  }

  // 4. Tiny Masonry Chimneys with Terracotta Pots
  for (let c = 0; c < b.chimneys; c++) {
    let t = b.chimneys === 1 ? 0.35 : (c === 0 ? 0.25 : 0.75);
    let cx = lerp(g.R0[0], g.R1[0], t);
    let cy = lerp(g.R0[1], g.R1[1], t) + 2 * b.sc;
    let cw = 3.6 * b.sc, ch = 8.5 * b.sc;
    brush.noStroke();
    brush.wash(PAL.wallCream, 240);
    brush.rect(cx - cw * 0.5, cy - ch, cw, ch, "corner");
    brush.noWash();
    brush.set("rotring", PAL.inkDark, sw(0.4));
    brush.rect(cx - cw * 0.5, cy - ch, cw, ch, "corner");
    brush.line(cx - cw * 0.7, cy - ch, cx + cw * 0.7, cy - ch);
  }
}

function drawSpecialLandmarkDetails(b, g) {
  let mx = (g.R0[0] + g.R1[0]) * 0.5;
  let my = (g.R0[1] + g.R1[1]) * 0.5;

  if (b.special === "capitaneria") {
    // Harbour Master's Clocktower rising above the roof ridge
    let tw = 16 * b.sc, th = 28 * b.sc;
    brush.noStroke();
    brush.wash(PAL.wallOchre, 245);
    brush.rect(mx - tw * 0.5, my - th, tw, th, "corner");
    brush.wash(PAL.roofClassic, 235);
    polyShape([[mx - tw * 0.6, my - th], [mx + tw * 0.6, my - th], [mx, my - th - 14 * b.sc]]);
    brush.noWash();

    brush.set("rotring", PAL.inkDark, sw(0.52));
    brush.rect(mx - tw * 0.5, my - th, tw, th, "corner");
    polyLine([[mx - tw * 0.6, my - th], [mx, my - th - 14 * b.sc], [mx + tw * 0.6, my - th], [mx - tw * 0.6, my - th]], 0.05);
    // Clock face & belfry arch
    brush.noStroke();
    brush.wash(PAL.foamWhite, 245);
    brush.circle(mx, my - th * 0.45, 4.5 * b.sc, 0.05);
    brush.noWash();
    brush.set("rotring", PAL.inkDark, sw(0.42));
    brush.circle(mx, my - th * 0.45, 4.5 * b.sc, 0.05);
    brush.line(mx, my - th * 0.45, mx, my - th * 0.45 - 3 * b.sc);
    brush.line(mx, my - th * 0.45, mx + 2.5 * b.sc, my - th * 0.45);
    // Weathervane
    brush.line(mx, my - th - 14 * b.sc, mx, my - th - 22 * b.sc);
  } else if (b.special === "church") {
    // Hilltop Baroque Church Terracotta Dome & Campanile
    let dr = 14 * b.sc, dh = 24 * b.sc;
    brush.noStroke();
    brush.wash(PAL.wallCream, 245);
    brush.rect(mx - dr, my - dh * 0.45, dr * 2, dh * 0.45, "corner");
    brush.wash(PAL.roofBright, 235);
    polyShape([
      [mx - dr, my - dh * 0.45],
      [mx - dr * 0.75, my - dh * 0.95],
      [mx, my - dh * 1.15],
      [mx + dr * 0.75, my - dh * 0.95],
      [mx + dr, my - dh * 0.45]
    ]);
    brush.noWash();

    brush.set("rotring", PAL.inkDark, sw(0.5));
    brush.rect(mx - dr, my - dh * 0.45, dr * 2, dh * 0.45, "corner");
    polyLine([
      [mx - dr, my - dh * 0.45],
      [mx - dr * 0.75, my - dh * 0.95],
      [mx, my - dh * 1.15],
      [mx + dr * 0.75, my - dh * 0.95],
      [mx + dr, my - dh * 0.45]
    ], 0.35);
    // Dome ribs & lantern cross
    brush.set("rotring", PAL.inkMid, sw(0.34));
    for (let f of [-0.45, 0, 0.45]) {
      polyLine([[mx + dr * f, my - dh * 0.45], [mx + dr * f * 0.6, my - dh * 0.9], [mx, my - dh * 1.15]], 0.3);
    }
    brush.set("rotring", PAL.inkDark, sw(0.45));
    brush.line(mx, my - dh * 1.15, mx, my - dh * 1.48);
    brush.line(mx - 3 * b.sc, my - dh * 1.35, mx + 3 * b.sc, my - dh * 1.35);
  } else if (b.special === "lighthouse") {
    // Tall Cylindrical Headland Lighthouse rising from keeper's house
    let lw = 11 * b.sc, lh = 38 * b.sc;
    brush.noStroke();
    brush.wash(PAL.wallCream, 248);
    polyShape([[mx - lw * 0.55, my], [mx + lw * 0.55, my], [mx + lw * 0.42, my - lh], [mx - lw * 0.42, my - lh]]);
    brush.wash(PAL.roofBright, 235);
    polyShape([[mx - lw * 0.5, my - lh * 0.55], [mx + lw * 0.5, my - lh * 0.55], [mx + lw * 0.46, my - lh * 0.75], [mx - lw * 0.46, my - lh * 0.75]]);
    polyShape([[mx - lw * 0.5, my - lh - 6 * b.sc], [mx + lw * 0.5, my - lh - 6 * b.sc], [mx, my - lh - 14 * b.sc]]);
    brush.noWash();

    brush.set("rotring", PAL.inkDark, sw(0.5));
    polyLine([[mx - lw * 0.55, my], [mx - lw * 0.42, my - lh], [mx + lw * 0.42, my - lh], [mx + lw * 0.55, my]], 0.02);
    brush.line(mx - lw * 0.65, my - lh, mx + lw * 0.65, my - lh);
    brush.rect(mx - lw * 0.38, my - lh - 6 * b.sc, lw * 0.76, 6 * b.sc, "corner");
    polyLine([[mx - lw * 0.5, my - lh - 6 * b.sc], [mx, my - lh - 14 * b.sc], [mx + lw * 0.5, my - lh - 6 * b.sc]], 0.05);
  } else if (b.special === "windmill") {
    // Old Island Windmill Sails (4 lattice blades in sepia pen)
    let cx = mx - 4 * b.sc, cy = my - 4 * b.sc;
    let bladeL = 22 * b.sc;
    brush.set("rotring", PAL.inkDark, sw(0.45));
    for (let a = 35; a < 360; a += 90) {
      let ex = cx + cos(a) * bladeL;
      let ey = cy + sin(a) * bladeL;
      brush.line(cx, cy, ex, ey);
      let px = -sin(a) * 4 * b.sc, py = cos(a) * 4 * b.sc;
      polyLine([
        [cx + cos(a) * 5 * b.sc, cy + sin(a) * 5 * b.sc],
        [cx + cos(a) * 5 * b.sc + px, cy + sin(a) * 5 * b.sc + py],
        [ex + px, ey + py],
        [ex, ey]
      ], 0.03);
    }
  }
}

// =============================================================================
// CAFÉ UMBRELLAS, PROMENADE LIFE, BOLLARDS & MOORING ROPES
// =============================================================================
function drawCafeUmbrellasAndPromenadeLifePen() {
  for (let u of umbrellas) {
    if (!u.pts) continue;
    // Tiny café chairs & table legs peeking out in the shade under the umbrella
    brush.set("rotring", PAL.inkDark, sw(0.36));
    brush.line(u.x + 2 * u.sc, u.y + 2 * u.sc, u.x + 2 * u.sc, u.y + 8 * u.sc);
    brush.circle(u.x - 4 * u.sc, u.y + 6 * u.sc, 2.2 * u.sc, 0.1);
    brush.circle(u.x + 7 * u.sc, u.y + 6 * u.sc, 2.2 * u.sc, 0.1);

    // Octagonal canopy perimeter
    brush.set("rotring", PAL.inkDark, sw(0.46));
    polyLine([...u.pts, u.pts[0]], 0.06);

    // 8 radial ribs from central finial apex
    let apexX = u.x - 0.5 * u.sc, apexY = u.y - 2.5 * u.sc;
    brush.set("rotring", PAL.inkMid, sw(0.32));
    for (let p of u.pts) {
      brush.line(apexX, apexY, p[0], p[1]);
    }

    // Front scalloped valance fringe along the lower edges (indices 0, 1, 2, 3)
    brush.set("rotring", PAL.inkDark, sw(0.38));
    for (let idx = 0; idx < 4; idx++) {
      let pA = u.pts[idx], pB = u.pts[(idx + 1) % 8];
      let xm = (pA[0] + pB[0]) * 0.5, ym = (pA[1] + pB[1]) * 0.5 + 2.4 * u.sc;
      polyLine([pA, [xm, ym], pB], 0.35);
    }

    // Bright finial dot at top center
    brush.set("rotring", PAL.foamWhite, sw(0.75));
    brush.circle(apexX, apexY, 1.0 * u.sc, 0.05);
  }

  // Tiny strolling figures, harbour crates, barrels & lamp posts along the Riva & Pier
  const figures = [
    [412, 522], [420, 526], [485, 442], [492, 445],
    [545, 405], [625, 452], [632, 455], [685, 505],
    [742, 548], [748, 552], [818, 608], [888, 695],
    [712, 938], [720, 940], [545, 932]
  ];
  for (let f of figures) {
    let [px, py] = f;
    let sc = pScale(py);
    // Cast shadow
    brush.set("rotring", PAL.inkLight, sw(0.45));
    brush.line(px, py, px + 6 * sc, py + 2 * sc);
    // Body & head in crisp sepia pen
    brush.set("rotring", PAL.inkDark, sw(0.65));
    brush.line(px, py, px, py - 6.5 * sc);
    brush.circle(px, py - 8 * sc, 1.4 * sc, 0.1);
  }

  // Quayside wrought-iron lamp posts along the promenade
  const lamps = [
    [435, 318], [520, 368], [588, 438], [670, 488],
    [755, 548], [835, 618], [898, 708], [912, 795]
  ];
  for (let lp of lamps) {
    let [lx, ly] = lp;
    let sc = pScale(ly);
    let h = 18 * sc;
    brush.set("rotring", PAL.inkDark, sw(0.48));
    brush.line(lx, ly, lx, ly - h);
    brush.circle(lx, ly - h - 2 * sc, 2 * sc, 0.1);
  }
}

function drawBollardsAndMooringLinesPen() {
  for (let b of bollards) {
    let { x, y, sc, hasCoil } = b;
    let bw = 3.2 * sc, bh = 5.5 * sc;

    // Diagonal cast shadow on the limestone coping
    brush.set("rotring", PAL.inkMid, sw(0.65));
    brush.line(x, y, x + 6 * sc, y + 2 * sc);

    // Flanged base plate
    brush.set("rotring", PAL.inkDark, sw(0.55));
    brush.line(x - bw * 0.9, y, x + bw * 0.9, y);

    // Sturdy cast-iron bollard post & T-horns
    brush.set("rotring", PAL.inkDark, sw(1.05 * sc));
    brush.line(x, y, x, y - bh);
    brush.set("rotring", PAL.inkDark, sw(0.65));
    brush.line(x - bw * 0.85, y - bh * 0.78, x + bw * 0.85, y - bh * 0.78);

    // Bright highlight dot on top of iron cap
    brush.set("rotring", PAL.foamWhite, sw(0.55));
    brush.line(x - 0.8 * sc, y - bh, x + 0.8 * sc, y - bh);

    // Coiled mooring rope beside the bollard
    if (hasCoil) {
      brush.set("rotring", PAL.inkMid, sw(0.32));
      let cx = x + 6.5 * sc, cy = y - 1 * sc;
      brush.circle(cx, cy, 3.2 * sc, 0.15);
      brush.circle(cx, cy, 1.6 * sc, 0.15);
      brush.line(x, y - bh * 0.5, cx - 2 * sc, cy);
    }
  }
}

// =============================================================================
// PICTORIAL COMPASS ROSE & FLOATING BLANK CARTOUCHE BANNERS
// =============================================================================
function drawCompassRoseAndMapFramePen() {
  // Ornate pictorial compass rose in the lower-left sea corner (x: 108, y: 1092)
  let cx = 108, cy = 1092, rOuter = 54, rInner = 16;

  // Translucent parchment wash inside compass ring
  brush.noStroke();
  brush.wash(PAL.cartouche, 175);
  brush.circle(cx, cy, rOuter * 0.78, 0.05);
  brush.noWash();

  // Concentric degree rings & rhumb lines radiating across the water
  brush.set("rotring", PAL.inkLight, sw(0.28));
  for (let a = 0; a < 360; a += 22.5) {
    brush.line(
      cx + cos(a) * rOuter, cy + sin(a) * rOuter,
      cx + cos(a) * (rOuter + 28), cy + sin(a) * (rOuter + 28)
    );
  }

  brush.set("rotring", PAL.inkDark, sw(0.5));
  brush.circle(cx, cy, rOuter, 0.04);
  brush.circle(cx, cy, rOuter * 0.88, 0.04);
  brush.circle(cx, cy, rInner, 0.04);

  // 8-point wind star (alternating dark sepia & warm gold-ochre halves)
  for (let i = 0; i < 8; i++) {
    let a = i * 45 - 90;
    let tipR = i % 2 === 0 ? rOuter * 0.96 : rOuter * 0.68;
    let sideA1 = a - 16, sideA2 = a + 16;
    let tip = [cx + cos(a) * tipR, cy + sin(a) * tipR];
    let pL = [cx + cos(sideA1) * rInner, cy + sin(sideA1) * rInner];
    let pR = [cx + cos(sideA2) * rInner, cy + sin(sideA2) * rInner];

    // Shaded half of star point
    brush.noStroke();
    brush.wash(i % 2 === 0 ? PAL.inkDark : PAL.roofBright, 210);
    polyShape([[cx, cy], tip, pR]);
    brush.wash(PAL.cartouche, 230);
    polyShape([[cx, cy], tip, pL]);
    brush.noWash();

    brush.set("rotring", PAL.inkDark, sw(0.42));
    polyLine([pL, tip, pR], 0.02);
    brush.line(cx, cy, tip[0], tip[1]);
  }

  // Ornamental fleur-de-lis pointer at North (top)
  let ny = cy - rOuter - 12;
  brush.set("rotring", PAL.inkDark, sw(0.5));
  polyLine([[cx, cy - rOuter], [cx - 5, ny + 5], [cx, ny - 4], [cx + 5, ny + 5], [cx, cy - rOuter]], 0.25);
}

function drawFloatingCartouches() {
  // Tiny cartouche-like blank banners floating over key buildings
  for (let c of cartouches) {
    let { x, y, w, h, targetX, targetY } = c;
    let hw = w * 0.5, hh = h * 0.5;

    // 1. Thin pointer pin connecting floating cartouche to landmark below
    brush.set("rotring", PAL.inkDark, sw(0.42));
    brush.line(x, y + hh + 3, targetX, targetY);
    brush.circle(targetX, targetY, 2.2, 0.05);

    // 2. Soft drop shadow wash so banner visibly floats over the rooftops
    brush.noStroke();
    brush.wash(PAL.inkDark, 85);
    polyShape([
      [x - hw - 8, y - hh + 6],
      [x + hw + 14, y - hh + 6],
      [x + hw + 14, y + hh + 9],
      [x - hw - 8, y + hh + 9]
    ]);

    // 3. Folded ribbon tails on left & right (darker warm parchment)
    let tailW = 14, tailDrop = 5;
    brush.wash(PAL.cartoucheBack, 245);
    // Left folded ribbon tail
    polyShape([
      [x - hw - tailW, y - hh + tailDrop],
      [x - hw + 3, y - hh + tailDrop],
      [x - hw + 3, y + hh + tailDrop],
      [x - hw - tailW, y + hh + tailDrop],
      [x - hw - tailW + 5, y + tailDrop]
    ]);
    // Right folded ribbon tail
    polyShape([
      [x + hw - 3, y - hh + tailDrop],
      [x + hw + tailW, y - hh + tailDrop],
      [x + hw + tailW - 5, y + tailDrop],
      [x + hw + tailW, y + hh + tailDrop],
      [x + hw - 3, y + hh + tailDrop]
    ]);

    // 4. Main arched blank banner body (bright warm cream parchment)
    let bodyPts = [
      [x - hw, y - hh],
      [x - hw * 0.4, y - hh - 2.5],
      [x + hw * 0.4, y - hh - 2.5],
      [x + hw, y - hh],
      [x + hw, y + hh],
      [x + hw * 0.4, y + hh - 2.5],
      [x - hw * 0.4, y + hh - 2.5],
      [x - hw, y + hh]
    ];
    brush.fill(PAL.cartouche, 250);
    brush.fillBleed(0.04, "in");
    polyShape(bodyPts);
    brush.noFill();
    brush.noWash();

    // 5. Crisp sepia pen outlines, scrolled volute curls & inner frame (completely blank inside!)
    brush.set("rotring", PAL.inkDark, sw(0.55));
    polyLine([...bodyPts, bodyPts[0]], 0.15);

    // Inner double-line frame border
    let padX = 4, padY = 3.2;
    brush.set("rotring", PAL.inkMid, sw(0.3));
    polyLine([
      [x - hw + padX, y - hh + padY],
      [x, y - hh - 2.5 + padY],
      [x + hw - padX, y - hh + padY],
      [x + hw - padX, y + hh - padY],
      [x, y + hh - 2.5 - padY],
      [x - hw + padX, y + hh - padY],
      [x - hw + padX, y - hh + padY]
    ], 0.15);

    // Left and right ribbon tails & rolled scroll volutes
    brush.set("rotring", PAL.inkDark, sw(0.48));
    polyLine([
      [x - hw, y - hh + tailDrop],
      [x - hw - tailW, y - hh + tailDrop],
      [x - hw - tailW + 5, y + tailDrop],
      [x - hw - tailW, y + hh + tailDrop],
      [x - hw + 3, y + hh + tailDrop],
      [x - hw, y + hh]
    ], 0.05);
    polyLine([
      [x + hw, y - hh + tailDrop],
      [x + hw + tailW, y - hh + tailDrop],
      [x + hw + tailW - 5, y + tailDrop],
      [x + hw + tailW, y + hh + tailDrop],
      [x + hw - 3, y + hh + tailDrop],
      [x + hw, y + hh]
    ], 0.05);

    // Rolled corner curls & small central Baroque crest flourish on top edge
    brush.circle(x - hw + 1.5, y + hh + 2.5, 2.2, 0.1);
    brush.circle(x + hw - 1.5, y + hh + 2.5, 2.2, 0.1);
    polyLine([
      [x - 8, y - hh - 2.5],
      [x, y - hh - 6.5],
      [x + 8, y - hh - 2.5]
    ], 0.4);
  }
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(8472);
  noiseSeed(8472);
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#020306");

  brush.noField();
  brush.noFill();
  brush.noWash();
  brush.noHatch();

  const CX = 600;
  const CY = 625;

  // Eye geometry constants
  const EYE_L = { x: 414, y: 602, rx: 134, ry: 162, rz: 138, tilt: -11 };
  const EYE_R = { x: 786, y: 602, rx: 134, ry: 162, rz: 138, tilt: 11 };

  // Precompute antenna spine curves for spatial channel-overlap queries
  const antSpines = {
    left: buildAntennaSpine(-1),
    right: buildAntennaSpine(1)
  };

  // =========================================================================
  // HELPER FUNCTIONS: ANATOMICAL FIELDS & ADDITIVE FLUORESCENCE COLOR ENGINE
  // =========================================================================

  function cubicBez(p0, p1, p2, p3, t) {
    const u = 1 - t;
    const tt = t * t, uu = u * u;
    const uuu = uu * u, ttt = tt * t;
    return {
      x: uuu * p0.x + 3 * uu * t * p1.x + 3 * u * tt * p2.x + ttt * p3.x,
      y: uuu * p0.y + 3 * uu * t * p1.y + 3 * u * tt * p2.y + ttt * p3.y
    };
  }

  function cubicBezTangent(p0, p1, p2, p3, t) {
    const u = 1 - t;
    const dx = 3 * u * u * (p1.x - p0.x) + 6 * u * t * (p2.x - p1.x) + 3 * t * t * (p3.x - p2.x);
    const dy = 3 * u * u * (p1.y - p0.y) + 6 * u * t * (p2.y - p1.y) + 3 * t * t * (p3.y - p2.y);
    const len = Math.hypot(dx, dy) || 1;
    return { x: dx / len, y: dy / len, angle: atan2(dy, dx) };
  }

  function buildAntennaSpine(side) {
    const p0 = { x: CX + side * 80, y: 478 };
    const p1 = { x: CX + side * 145, y: 282 };
    const p2 = { x: CX + side * 345, y: 122 };
    const p3 = { x: CX + side * 542, y: 238 };
    const samples = [];
    const N = 80;
    for (let i = 0; i <= N; i++) {
      const t = i / N;
      const pt = cubicBez(p0, p1, p2, p3, t);
      const tan = cubicBezTangent(p0, p1, p2, p3, t);
      // Plume envelope lengths (ventral hangs lower, dorsal arches above)
      const env = Math.pow(Math.sin(t * Math.PI), 0.72) * (1 - 0.18 * t);
      const vLen = 185 * env + 10 * (1 - t);
      const dLen = 128 * env + 8 * (1 - t);
      samples.push({ t, x: pt.x, y: pt.y, tx: tan.x, ty: tan.y, angle: tan.angle, vLen, dLen });
    }
    return { p0, p1, p2, p3, samples, side };
  }

  // Evaluate 3D normalized coordinates on an eye ellipsoid
  function evalEyePoint(x, y, eye) {
    const dx = x - eye.x;
    const dy = y - eye.y;
    const c = cos(-eye.tilt);
    const s = sin(-eye.tilt);
    const lx = (dx * c - dy * s) / eye.rx;
    const ly = (dx * s + dy * c) / eye.ry;
    const r2 = lx * lx + ly * ly;
    const r = Math.sqrt(r2);
    const nz = r2 < 1.0 ? Math.sqrt(1.0 - r2) : 0;
    return { lx, ly, r, nz };
  }

  // Evaluate local intensities of Cyan (scales), Emerald (eyes), and Magenta (antennae)
  function sampleChannels(x, y) {
    // 1. EMERALD (Compound Eyes)
    const eL = evalEyePoint(x, y, EYE_L);
    const eR = evalEyePoint(x, y, EYE_R);
    let emerald = 0;
    const eMin = eL.r < eR.r ? eL : eR;
    if (eMin.r < 1.08) {
      if (eMin.r <= 1.0) {
        // Rim amplification + upper-outer confocal highlight
        const rim = Math.pow(eMin.r, 1.6) * 0.75;
        emerald = 0.28 + rim;
      } else {
        emerald = map(eMin.r, 1.0, 1.08, 0.55, 0, true);
      }
    }

    // 2. CYAN (Head Capsule + Prothoracic Collar / Thorax Fur)
    let cyan = 0;
    // Head frons/vertex shield between eyes
    const hdx = (x - CX) / 138;
    const hdy = (y - 590) / 185;
    const headDist = Math.hypot(hdx, hdy);
    if (headDist < 1.15) {
      cyan = Math.max(cyan, map(headDist, 0.65, 1.15, 0.95, 0.0, true));
    }
    // Periocular scale cuff around eyes
    if (eMin.r > 0.86 && eMin.r < 1.24) {
      // Stronger on medial, dorsal, and ventral edges of eye
      const medialFactor = 1.0 - 0.45 * Math.abs((x - CX) / 360);
      const cuff = (1.0 - Math.abs(eMin.r - 1.03) / 0.19) * medialFactor;
      if (cuff > 0) cyan = Math.max(cyan, cuff * 0.85);
    }
    // Thorax cape (wide heart/shield shape)
    const tdx = (x - CX) / 465;
    const tdy = (y - 695) / 390;
    // Indent slightly at top-center, widen at shoulders (patagia)
    const ang = atan2(y - 640, x - CX);
    const shoulderWave = 0.12 * cos(ang * 2) - 0.06 * sin(ang * 3) + 0.04 * cos(ang * 10);
    const thoraxR = Math.hypot(tdx, tdy) / (1.0 + shoulderWave);
    if (thoraxR < 1.04 && y > 280) {
      let tVal = map(thoraxR, 0.35, 1.04, 0.85, 0.0, true);
      // Carve out central eye interiors from deep thorax cyan
      if (eMin.r < 0.88 && Math.abs(x - CX) > 115) {
        tVal *= map(eMin.r, 0.72, 0.88, 0.0, 1.0, true);
      }
      cyan = Math.max(cyan, tVal);
    }

    // 3. MAGENTA (Feathered Antenna Plumes)
    let magenta = 0;
    const spine = x < CX ? antSpines.left : antSpines.right;
    const side = x < CX ? -1 : 1;
    let minD = 9999;
    let bestS = null;
    for (let i = 0; i < spine.samples.length; i += 2) {
      const s = spine.samples[i];
      const d = Math.hypot(x - s.x, y - s.y);
      if (d < minD) {
        minD = d;
        bestS = s;
      }
    }
    if (bestS) {
      // Project (x - bestS.x, y - bestS.y) onto normal of shaft
      const vx = x - bestS.x;
      const vy = y - bestS.y;
      // Normal pointing downward/ventral vs upward/dorsal
      const nx = -bestS.ty * side;
      const ny = bestS.tx * side;
      const proj = vx * nx + vy * ny; // positive = ventral (down), negative = dorsal (up)
      const maxReach = proj >= 0 ? bestS.vLen : bestS.dLen;
      const absProj = Math.abs(proj);
      if (absProj < maxReach) {
        const u = 1.0 - absProj / (maxReach + 1);
        // Stronger near the shaft and in mid-plume
        const shaftBoost = Math.exp(-absProj * absProj / 280);
        // Feather filament wave modulation
        const ribMod = 0.65 + 0.35 * Math.sin(bestS.t * 190 + absProj * 0.09);
        magenta = Math.min(1.2, (Math.pow(u, 0.55) * 0.82 * ribMod + shaftBoost * 0.65));
      }
    }

    return { cyan, emerald, magenta };
  }

  // Convert (Cyan, Magenta, Emerald) stain amounts into hex color with additive white blending
  function stainToHex(c, m, e, boost = 1.0) {
    c = Math.max(0, c * boost);
    m = Math.max(0, m * boost);
    e = Math.max(0, e * boost);

    // Pairwise overlap drives rapid convergence toward crisp white
    const overlap = (c * m * 1.45) + (c * e * 1.45) + (m * e * 1.45) + (c * m * e * 2.2);
    // Self-saturation at high single-channel brightness also pulls toward white core
    const selfWhite =
      Math.max(0, c - 0.88) * 1.35 +
      Math.max(0, m - 0.88) * 1.35 +
      Math.max(0, e - 0.88) * 1.35;

    const w = overlap + selfWhite;

    // Linear additive RGB mixing of the 3 fluorophore channels:
    // Cyan:    (0.02, 0.86, 1.00)
    // Magenta: (1.00, 0.06, 0.58)
    // Emerald: (0.04, 1.00, 0.46)
    let r = c * 0.03 + m * 1.02 + e * 0.05 + w * 0.95;
    let g = c * 0.85 + m * 0.07 + e * 1.00 + w * 0.95;
    let b = c * 1.02 + m * 0.58 + e * 0.46 + w * 0.98;

    // Tone curve for crisp high-contrast confocal brilliance
    r = Math.min(1, Math.pow(Math.max(0, r), 0.86));
    g = Math.min(1, Math.pow(Math.max(0, g), 0.86));
    b = Math.min(1, Math.pow(Math.max(0, b), 0.86));

    const ri = Math.round(r * 255);
    const gi = Math.round(g * 255);
    const bi = Math.round(b * 255);
    return (
      "#" +
      ri.toString(16).padStart(2, "0") +
      gi.toString(16).padStart(2, "0") +
      bi.toString(16).padStart(2, "0")
    );
  }

  // Compute anatomical scale flow direction at (x, y)
  function getScaleFlowAngle(x, y) {
    const dx = x - CX;
    const dy = y - 555;
    const side = dx < 0 ? -1 : 1;

    // 1. Antennal socket (torulus) radial whorl around (CX ± 80, 478)
    const tx = CX + side * 80;
    const ty = 478;
    const dTor = Math.hypot(x - tx, y - ty);
    if (dTor < 62) {
      const radialAng = atan2(y - ty, x - tx);
      const blend = map(dTor, 20, 62, 1, 0, true);
      const baseAng = dy < 0 ? -90 + side * 25 : 90 - side * 15;
      return radialAng * blend + baseAng * (1 - blend);
    }

    // 2. Central Frons & Vertex (between the eyes)
    if (Math.abs(dx) < 125 && y > 435 && y < 715) {
      if (y < 510) {
        // Vertex crown tuft sweeping upward and outward
        return -90 + (dx / 125) * 48;
      } else {
        // Frons scales streaming downward with slight chevron convergence toward midline
        const chevron = -side * map(Math.abs(dx), 0, 120, 4, 28, true);
        return 90 + chevron;
      }
    }

    // 3. Labial Palps (below frons, curving inward and upward)
    if (Math.abs(dx) < 95 && y >= 700 && y < 815) {
      return 90 - side * 32;
    }

    // 4. Periocular Cuff (scales hugging and radiating from eye rim)
    const eye = dx < 0 ? EYE_L : EYE_R;
    const ep = evalEyePoint(x, y, eye);
    if (ep.r > 0.88 && ep.r < 1.26) {
      const eyeAng = atan2(y - eye.y, x - eye.x);
      const t = map(ep.r, 0.88, 1.26, 0.75, 0.15, true);
      const thoraxAng = atan2(y - 565, dx * 0.92);
      return eyeAng * t + thoraxAng * (1 - t);
    }

    // 5. Prothoracic Collar, Tegulae (Shoulders), and Pectus (Chest Ruff)
    let baseAng = atan2(y - 545, dx * 0.88);
    // In ventral chest region, pull flow downward into lush V-shaped chevron tiers
    if (y > 700) {
      const ventralPull = map(y, 700, 1080, 0.0, 0.55, true);
      const targetAng = 90 + side * map(Math.abs(dx), 0, 380, 6, 42, true);
      baseAng = baseAng * (1 - ventralPull) + targetAng * ventralPull;
    }
    // Add subtle anatomical lock/tuft wave undulation
    const wave = 9 * sin(x * 0.025 + y * 0.02) + 6 * cos(x * 0.05 - y * 0.03);
    return baseAng + wave;
  }

  // =========================================================================
  // STAGE 1: LAYERED MARKER UNDER-STAINS ON PURE BLACK
  // =========================================================================
  {
    const underStrokes = [];
    // Sample grid across the specimen to lay down deep marker stain passes
    for (let y = 130; y <= 1110; y += 22) {
      for (let x = 75; x <= 1125; x += 22) {
        const jx = x + random(-9, 9);
        const jy = y + random(-9, 9);
        const ch = sampleChannels(jx, jy);
        const tot = ch.cyan + ch.emerald + ch.magenta;
        if (tot < 0.14) continue;

        let ang = getScaleFlowAngle(jx, jy);
        let len = 34;
        if (ch.magenta > ch.cyan && ch.magenta > ch.emerald) {
          ang = (jx < CX ? -55 : -125) + random(-15, 15);
          len = 42;
        }
        const col = stainToHex(ch.cyan * 0.42, ch.magenta * 0.42, ch.emerald * 0.42, 0.9);
        const tier = Math.floor( constrain(tot * 3, 0, 3) );
        underStrokes.push({ x: jx, y: jy, ang, len, col, tier, w: map(tot, 0.14, 1.5, 1.2, 2.4, true) });
      }
    }
    underStrokes.sort((a, b) => a.tier - b.tier);
    for (const s of underStrokes) {
      brush.set("marker", s.col, s.w);
      const dx = cos(s.ang) * s.len * 0.5;
      const dy = sin(s.ang) * s.len * 0.5;
      brush.line(s.x - dx, s.y - dy, s.x + dx, s.y + dy);
    }
  }

  // =========================================================================
  // STAGE 2: FURRY THORAX & HEAD CAPSULE — INDIVIDUAL CRISP SCALES
  // =========================================================================
  {
    const scales = [];

    // Generate concentric anatomical tiers of scales from outer halo to inner head frons
    // Outermost scales are drawn first; proximal scales overlap them like real shingles!
    for (let ring = 0; ring < 52; ring++) {
      const rNorm = map(ring, 0, 51, 1.06, 0.03); // 1.06 = outer halo, 0.03 = center of head
      const circumference = Math.max(18, Math.floor(rNorm * 145));

      for (let k = 0; k < circumference; k++) {
        const theta = (k / circumference) * 360 + (ring % 2) * (180 / circumference) + random(-2.2, 2.2);
        // Elliptical anatomical mapping centered around head/thorax
        const radX = 468 * rNorm;
        const radY = (theta > 0 && theta < 180 ? 445 : 310) * rNorm;
        const cyOff = theta > 0 && theta < 180 ? 645 : 575;

        // Add tuft lobe modulation on outer edge
        const lobeMod = 1.0 + 0.08 * cos(theta * 2) - 0.05 * sin(theta * 3) + 0.035 * cos(theta * 12);
        const sx = CX + cos(theta) * radX * lobeMod + random(-5, 5);
        const sy = cyOff + sin(theta) * radY * lobeMod + random(-5, 5);

        if (sy < 250 || sy > 1135 || sx < 85 || sx > 1115) continue;

        // Exclude interior of compound eyes (leave periocular cuff at r > 0.87)
        const eL = evalEyePoint(sx, sy, EYE_L);
        const eR = evalEyePoint(sx, sy, EYE_R);
        const minEyeR = Math.min(eL.r, eR.r);
        if (minEyeR < 0.87 && Math.abs(sx - CX) > 108) continue;

        // Exclude deep oral cleft right between labial palps
        if (Math.abs(sx - CX) < 18 && sy > 725 && sy < 775) continue;

        const ch = sampleChannels(sx, sy);
        if (ch.cyan < 0.06 && minEyeR > 1.15) continue;

        const ang = getScaleFlowAngle(sx, sy);

        // Determine scale morphology by anatomical zone:
        // - Outer rim (rNorm > 0.82): long tapering piliform hair-scales
        // - Mid thorax & tegulae (0.36 < rNorm <= 0.82): lanceolate striated scales
        // - Head frons, vertex, ocular cuff, palps (rNorm <= 0.36 or near eye): crisp serrated lamellar scales
        let type = "lanceolate";
        let len = random(26, 42);
        let wid = random(5.0, 8.0);

        if (rNorm > 0.84) {
          type = "piliform";
          len = random(42, 74);
          wid = random(2.5, 4.5);
        } else if (rNorm < 0.34 || (minEyeR >= 0.87 && minEyeR < 1.12)) {
          type = "lamellar";
          len = map(rNorm, 0.03, 0.34, 15, 27, true) * random(0.88, 1.14);
          wid = map(rNorm, 0.03, 0.34, 5.2, 8.8, true);
        }

        // Tuft clumping wave (creates tiered locks of scales with dark troughs and bright crests)
        const tuftWave =
          0.5 +
          0.3 * sin(rNorm * 42 * 180 / Math.PI + cos(theta * 4) * 1.6) +
          0.2 * cos(theta * 9 + rNorm * 18);

        // Channel intensities for this individual scale
        const cBase = constrain(ch.cyan * (0.45 + 0.72 * tuftWave) + random(-0.08, 0.10), 0.12, 1.25);
        // Scales near the eye margin pick up Emerald fluorescence bleed
        const eBleed = minEyeR < 1.16 ? map(minEyeR, 0.87, 1.16, 0.85, 0.0, true) : 0.0;
        // Scales under the antenna plume pick up Hot Magenta fluorescence bleed
        const mBleed = ch.magenta * (sy < 620 ? 0.92 : 0.45);

        scales.push({
          x: sx,
          y: sy,
          ang,
          len,
          wid,
          type,
          tuftWave,
          cBase,
          eBleed,
          mBleed,
          ring
        });
      }
    }

    // Add extra high-density micro-scales on the Frons, Antennal Rosettes, and Labial Palps
    for (let i = 0; i < 650; i++) {
      const zone = i % 3;
      let sx, sy, len, wid;
      if (zone === 0) {
        // Central Frons & Vertex crest
        sx = CX + randomGaussian(0, 56);
        sy = random(425, 705);
        len = random(14, 24);
        wid = random(4.8, 7.5);
      } else if (zone === 1) {
        // Antennal socket rosettes (Toruli)
        const side = i % 2 === 0 ? -1 : 1;
        const r = random(18, 54);
        const a = random(0, 360);
        sx = CX + side * 80 + cos(a) * r;
        sy = 478 + sin(a) * r;
        len = map(r, 18, 54, 11, 20);
        wid = map(r, 18, 54, 3.8, 6.2);
      } else {
        // Labial palps & sub-ocular cheek tufts
        const side = i % 2 === 0 ? -1 : 1;
        sx = CX + side * random(18, 92);
        sy = random(685, 815);
        len = random(16, 28);
        wid = random(4.2, 6.8);
      }

      const eL = evalEyePoint(sx, sy, EYE_L);
      const eR = evalEyePoint(sx, sy, EYE_R);
      const minEyeR = Math.min(eL.r, eR.r);
      if (minEyeR < 0.88) continue;

      const ch = sampleChannels(sx, sy);
      const ang = getScaleFlowAngle(sx, sy);
      const tuftWave = 0.65 + 0.35 * sin(sy * 0.12 + sx * 0.08);
      const cBase = constrain(0.68 + 0.45 * tuftWave + random(-0.08, 0.12), 0.25, 1.3);
      const eBleed = minEyeR < 1.15 ? map(minEyeR, 0.88, 1.15, 0.90, 0.0, true) : 0.0;
      const mBleed = ch.magenta * 0.95;

      scales.push({
        x: sx,
        y: sy,
        ang,
        len,
        wid,
        type: "lamellar",
        tuftWave,
        cBase,
        eBleed,
        mBleed,
        ring: 55 + Math.floor(i / 25)
      });
    }

    // Sort strictly from outer/posterior to inner/anterior so overlapping scale tips sit on top
    scales.sort((a, b) => a.ring - b.ring);

    // Render scales in anatomical tier groups so marker under-bodies and crisp pen tips interlock properly
    const GROUP_SIZE = 320;
    for (let g = 0; g < scales.length; g += GROUP_SIZE) {
      const slice = scales.slice(g, g + GROUP_SIZE);

      // 1. Translucent Marker Body of each scale in this tier
      for (const s of slice) {
        const bodyCol = stainToHex(s.cBase * 0.62, s.mBleed * 0.58, s.eBleed * 0.58, 0.92);
        brush.set("marker", bodyCol, constrain(s.wid * 0.16, 0.45, 1.25));
        const ca = cos(s.ang), sa = sin(s.ang);
        brush.line(s.x, s.y, s.x + ca * s.len * 0.86, s.y + sa * s.len * 0.86);
      }

      // 2. Dark Velvet Shadow Base at the root of each scale tuft
      brush.set("rotring", "#01060C", 0.28);
      for (const s of slice) {
        if (s.tuftWave < 0.48) {
          const ca = cos(s.ang), sa = sin(s.ang);
          const px = -sa * s.wid * 0.45, py = ca * s.wid * 0.45;
          brush.line(s.x - px, s.y - py, s.x + px + ca * s.len * 0.3, s.y + py + sa * s.len * 0.3);
        }
      }

      // 3. Crisp Fine-Tipped Pen Scale Ribs, Margins & Serrated Apical Denticles
      for (const s of slice) {
        const tipCol = stainToHex(s.cBase, s.mBleed, s.eBleed, 1.08);
        const penW = s.type === "piliform" ? 0.20 : 0.24;
        brush.set("rotring", tipCol, penW);

        const ca = cos(s.ang), sa = sin(s.ang);
        const nx = -sa, ny = ca;
        const hw = s.wid * 0.5;

        const tipX = s.x + ca * s.len;
        const tipY = s.y + sa * s.len;

        if (s.type === "piliform") {
          // Curved tapering hair-scale needle + twin flank filament
          const bend = (s.x < CX ? -1 : 1) * s.len * 0.12;
          const midX = s.x + ca * s.len * 0.55 + nx * bend;
          const midY = s.y + sa * s.len * 0.55 + ny * bend;
          brush.spline([[s.x, s.y, 0.9], [midX, midY, 0.7], [tipX + nx * bend * 1.4, tipY + ny * bend * 1.4, 0.2]], 0.5);
        } else if (s.type === "lamellar") {
          // Broad spatulate scale: left & right diverging ribs + central keel + serrated apical teeth
          const tL_x = tipX - nx * hw - ca * 1.8;
          const tL_y = tipY - ny * hw - sa * 1.8;
          const tR_x = tipX + nx * hw - ca * 1.8;
          const tR_y = tipY + ny * hw - sa * 1.8;

          // Left and right crisp margins from narrow stalk base
          brush.line(s.x - nx * hw * 0.22, s.y - ny * hw * 0.22, tL_x, tL_y);
          brush.line(s.x + nx * hw * 0.22, s.y + ny * hw * 0.22, tR_x, tR_y);
          // Central longitudinal ridge (keel) extending to central apical tooth
          brush.line(s.x, s.y, tipX + ca * 1.5, tipY + sa * 1.5);
          // Serrated W-shaped apical margin connecting the teeth
          brush.line(tL_x, tL_y, tipX + ca * 1.5, tipY + sa * 1.5);
          brush.line(tipX + ca * 1.5, tipY + sa * 1.5, tR_x, tR_y);
        } else {
          // Lanceolate scale: crisp diamond-lance ribs converging to a sharp apex
          const shX = s.x + ca * s.len * 0.68;
          const shY = s.y + sa * s.len * 0.68;
          brush.line(s.x, s.y, shX - nx * hw, shY - ny * hw);
          brush.line(shX - nx * hw, shY - ny * hw, tipX, tipY);
          brush.line(s.x, s.y, shX + nx * hw, shY + ny * hw);
          brush.line(shX + nx * hw, shY + ny * hw, tipX, tipY);
          brush.line(s.x + ca * s.len * 0.15, s.y + sa * s.len * 0.15, tipX, tipY);
        }
      }
    }
  }

  // Subtle proboscis coil & oral shadow nestled between the labial palps
  {
    brush.set("marker", "#01050A", 1.8);
    for (let y = 712; y <= 785; y += 7) {
      brush.line(CX - 14, y, CX + 14, y);
    }
    // Transverse annular rings of the galeae (proboscis) in cyan-emerald-white
    for (let y = 716; y <= 778; y += 5.5) {
      const t = map(y, 716, 778, 0, 1);
      const w = map(sin(t * 180), 0, 1, 7, 13);
      const col = stainToHex(0.75, 0.25, 0.65, 0.95);
      brush.set("rotring", col, 0.24);
      brush.line(CX - w, y, CX + w, y + 1.5);
      brush.set("rotring", "#FFFFFF", 0.18);
      brush.line(CX - w * 0.35, y + 0.5, CX + w * 0.35, y + 1.0);
    }
  }

  // =========================================================================
  // STAGE 3: COMPOUND EYES — ACID-FREE EMERALD GREEN & 3D HEXAGONAL OMMATIDIA
  // =========================================================================
  function renderCompoundEye(eye, side) {
    // 1. Deep ocular socket shadow & layered emerald marker under-dome
    brush.set("marker", "#000F07", 2.2);
    for (let a = 0; a < 360; a += 8) {
      const r1 = 0.2, r2 = 0.98;
      const c = cos(eye.tilt), s = sin(eye.tilt);
      const lx1 = cos(a) * eye.rx * r1, ly1 = sin(a) * eye.ry * r1;
      const lx2 = cos(a) * eye.rx * r2, ly2 = sin(a) * eye.ry * r2;
      const x1 = eye.x + lx1 * c - ly1 * s, y1 = eye.y + lx1 * s + ly1 * c;
      const x2 = eye.x + lx2 * c - ly2 * s, y2 = eye.y + lx2 * s + ly2 * c;
      brush.line(x1, y1, x2, y2);
    }

    // Volumetric emerald marker rings from deep pseudopupil to glowing coronal rim
    for (let ring = 1; ring <= 14; ring++) {
      const rFrac = ring / 14;
      const eInt = rFrac < 0.38 ? map(rFrac, 0, 0.38, 0.18, 0.45) : map(rFrac, 0.38, 1.0, 0.45, 0.98);
      const col = stainToHex(0.02, 0.0, eInt, 0.85);
      brush.set("marker", col, 1.35);
      const steps = 36;
      const c = cos(eye.tilt), s = sin(eye.tilt);
      for (let i = 0; i < steps; i++) {
        const a1 = (i / steps) * 360;
        const a2 = ((i + 1) / steps) * 360;
        const lx1 = cos(a1) * eye.rx * rFrac, ly1 = sin(a1) * eye.ry * rFrac;
        const lx2 = cos(a2) * eye.rx * rFrac, ly2 = sin(a2) * eye.ry * rFrac;
        brush.line(
          eye.x + lx1 * c - ly1 * s,
          eye.y + lx1 * s + ly1 * c,
          eye.x + lx2 * c - ly2 * s,
          eye.y + lx2 * s + ly2 * c
        );
      }
    }

    // 2. Project a 3D spherical hexagonal lattice of ommatidia across the hemisphere
    const hexSpacing = 0.056; // Angular spacing in azimuthal equidistant projection
    const hexR = hexSpacing * 0.52;
    const maxAngle = 1.54; // ~88 degrees from center of dome to horizon limb
    const gridN = 32;

    const ct = cos(eye.tilt), st = sin(eye.tilt);

    // Helper: map tangent plane (u, v) in radians onto 3D tilted ellipsoid
    function projectEyeUV(u, v) {
      const theta = Math.hypot(u, v);
      if (theta > maxAngle) return null;
      const sinT = Math.sin(theta);
      const cosT = Math.cos(theta);
      const ux = theta > 1e-5 ? (u / theta) * sinT : 0;
      const uy = theta > 1e-5 ? (v / theta) * sinT : 0;
      const lx = ux * eye.rx;
      const ly = uy * eye.ry;
      return {
        x: eye.x + lx * ct - ly * st,
        y: eye.y + lx * st + ly * ct,
        nx: ux * ct - uy * st,
        ny: ux * st + uy * ct,
        nz: cosT,
        theta
      };
    }

    const facets = [];
    for (let q = -gridN; q <= gridN; q++) {
      for (let r = -gridN; r <= gridN; r++) {
        const u = hexSpacing * (q + r * 0.5);
        const v = hexSpacing * (r * Math.sqrt(3) * 0.5);
        const center = projectEyeUV(u, v);
        if (!center) continue;

        // Project the 6 vertices of this hexagonal ommatidium onto the 3D surface
        const verts = [];
        for (let k = 0; k < 6; k++) {
          const ang = k * 60 + 30;
          const vu = u + cos(ang) * hexR;
          const vv = v + sin(ang) * hexR;
          const vp = projectEyeUV(vu, vv) || center;
          verts.push(vp);
        }

        // Compute confocal emerald illumination on this facet:
        // - Dark central pseudopupil where we look straight down the ommatidial rhabdoms
        const pupilDx = center.nx - side * 0.14;
        const pupilDy = center.ny + 0.05;
        const pupilDist = Math.hypot(pupilDx, pupilDy);
        const pupilDip = map(pupilDist, 0.0, 0.38, 0.18, 1.0, true);

        // - Grazing coronal rim glow (confocal membrane fluorescence)
        const rimGlow = Math.pow(1.0 - center.nz, 1.35) * 0.95;

        // - Upper-outer specular excitation crescent
        const specDot = Math.max(0, center.nx * side * 0.68 - center.ny * 0.65 + center.nz * 0.34);
        const specHighlight = Math.pow(specDot, 5.5) * 0.95;

        // - Secondary lower-inner bounce reflection from cyan cheek scales
        const bounceDot = Math.max(0, -center.nx * side * 0.55 + center.ny * 0.65 + center.nz * 0.25);
        const bounceGlow = Math.pow(bounceDot, 4.0) * 0.45;

        const eVal = constrain((0.28 + rimGlow + specHighlight) * pupilDip + specHighlight * 0.55, 0.12, 1.45);

        // Sample channel cross-talk from nearby Cyan ocular scales and Magenta antenna rami
        const ch = sampleChannels(center.x, center.y);
        let cCross = bounceGlow * 0.55;
        if (center.theta > 1.22 && side * (center.x - eye.x) < 25) {
          cCross += map(center.theta, 1.22, 1.54, 0.0, 0.85, true);
        }
        const mCross = ch.magenta * (center.y < eye.y - 35 ? 0.88 : 0.25);

        facets.push({
          center,
          verts,
          eVal,
          cCross,
          mCross
        });
      }
    }

    // Sort facets from outer horizon limb (low nz) to dome apex (high nz)
    facets.sort((a, b) => a.center.nz - b.center.nz);

    // Pass A: Glowing corneal lens fill inside each facet
    for (const f of facets) {
      const lensCol = stainToHex(f.cCross * 0.7, f.mCross * 0.7, f.eVal * 0.78, 0.95);
      brush.set("marker", lensCol, map(f.center.nz, 0, 1, 0.32, 0.68));
      brush.line(f.verts[0].x, f.verts[0].y, f.verts[3].x, f.verts[3].y);
    }

    // Pass B: Crisp hexagonal facet walls in fine-tipped pen
    for (const f of facets) {
      const rimCol = stainToHex(f.cCross, f.mCross, f.eVal, 1.12);
      const penW = f.eVal > 1.05 ? 0.24 : 0.18;
      brush.set("rotring", rimCol, penW);

      // Draw the 4 lit hexagonal walls of each perspective-projected ommatidium
      const v = f.verts;
      brush.line(v[3].x, v[3].y, v[4].x, v[4].y);
      brush.line(v[4].x, v[4].y, v[5].x, v[5].y);
      brush.line(v[5].x, v[5].y, v[0].x, v[0].y);
      if (f.center.nz > 0.35) {
        brush.line(v[0].x, v[0].y, v[1].x, v[1].y);
      }
    }

    // Pass C: Specular white micro-glints on the brightest ommatidial lenses
    brush.set("rotring", "#FFFFFF", 0.22);
    for (const f of facets) {
      if (f.eVal + f.cCross + f.mCross > 1.28) {
        const v = f.verts;
        brush.line(v[4].x, v[4].y, v[5].x, v[5].y);
      }
    }
  }

  renderCompoundEye(EYE_L, -1);
  renderCompoundEye(EYE_R, 1);

  // =========================================================================
  // STAGE 3.5: PERIOCULAR OVERHANG SCALES (CYAN + EMERALD -> AQUAMARINE/WHITE)
  // =========================================================================
  // Scales along the inner/ventral/dorsal eye socket that physically overlap the emerald cornea
  for (let side of [-1, 1]) {
    const eye = side === -1 ? EYE_L : EYE_R;
    const ct = cos(eye.tilt), st = sin(eye.tilt);

    for (let i = 0; i < 135; i++) {
      // Concentrate along the medial, dorsal, and ventral socket margins
      const a = side === -1 ? random(-105, 115) : random(65, 295);
      const r = random(0.94, 1.07);
      const lx = cos(a) * eye.rx * r;
      const ly = sin(a) * eye.ry * r;
      const sx = eye.x + lx * ct - ly * st;
      const sy = eye.y + lx * st + ly * ct;

      // Scales point slightly across the rim of the eye
      const inwardAng = atan2(eye.y - sy, eye.x - sx) + random(-22, 22);
      const len = random(14, 24);
      const wid = random(4.0, 6.2);

      const ch = sampleChannels(sx, sy);
      // High Cyan + High Emerald overlap -> luminous aquamarine & pure white!
      const col = stainToHex(0.95, ch.magenta * 0.85, 0.90, 1.15);

      const ca = cos(inwardAng), sa = sin(inwardAng);
      const nx = -sa * wid * 0.5, ny = ca * wid * 0.5;
      const tipX = sx + ca * len, tipY = sy + sa * len;

      brush.set("marker", stainToHex(0.75, ch.magenta * 0.5, 0.70, 0.9), 0.55);
      brush.line(sx, sy, tipX, tipY);

      brush.set("rotring", col, 0.24);
      brush.line(sx - nx * 0.3, sy - ny * 0.3, tipX - nx, tipY - ny);
      brush.line(sx + nx * 0.3, sy + ny * 0.3, tipX + nx, tipY + ny);
      brush.line(sx, sy, tipX + ca * 1.5, tipY + sa * 1.5);
      brush.line(tipX - nx, tipY - ny, tipX + ca * 1.5, tipY + sa * 1.5);
      brush.line(tipX + ca * 1.5, tipY + sa * 1.5, tipX + nx, tipY + ny);
    }
  }

  // =========================================================================
  // STAGE 4: FEATHERED BIPECTINATE ANTENNAE (HOT MAGENTA + WHITE OVERLAPS)
  // =========================================================================
  function renderFeatheredAntenna(spine) {
    const side = spine.side;
    const N_SEG = 64;

    // 1. Basal Scape & Pedicel (emerging from the cyan torulus socket at P0)
    // Dense overlapping cyan-magenta-white scales bridging the head and antenna shaft
    for (let i = 0; i < 55; i++) {
      const t = i / 55;
      const bx = spine.p0.x + side * t * 14 + random(-11, 11) * (1 - 0.4 * t);
      const by = spine.p0.y - t * 34 + random(-8, 8);
      const ang = -90 + side * 24 + random(-16, 16);
      const len = random(12, 20);
      const col = stainToHex(1.0 - t * 0.55, 0.55 + t * 0.65, 0.15, 1.18);
      brush.set("marker", col, 0.55);
      brush.line(bx, by, bx + cos(ang) * len * 0.8, by + sin(ang) * len * 0.8);
      brush.set("rotring", stainToHex(1.0 - t * 0.4, 0.75 + t * 0.5, 0.2, 1.3), 0.24);
      brush.line(bx, by, bx + cos(ang) * len, by + sin(ang) * len);
    }

    // Build all 64 flagellomere segments and their 4 pectinate rami (2 ventral, 2 dorsal)
    const ramiList = [];

    for (let i = 1; i < N_SEG; i++) {
      const t = i / N_SEG;
      const pt = cubicBez(spine.p0, spine.p1, spine.p2, spine.p3, t);
      const tan = cubicBezTangent(spine.p0, spine.p1, spine.p2, spine.p3, t);

      // Normal vector pointing ventrally (downward/outward)
      const vnx = -tan.y * side;
      const vny = tan.x * side;

      // Biological plume length envelope
      const env = Math.pow(Math.sin(t * Math.PI), 0.68) * (1.0 - 0.16 * t);
      const vLen1 = 186 * env + 8 * (1 - t); // Primary ventral ramus
      const vLen2 = 152 * env + 6 * (1 - t); // Secondary ventral ramus (creates 3D lattice crossing)
      const dLen1 = 132 * env + 6 * (1 - t); // Primary dorsal ramus
      const dLen2 = 104 * env + 5 * (1 - t); // Secondary dorsal ramus

      // Helper to construct a 5-point curved 3D ramus filament
      function buildRamus(basePt, dirSign, length, sweepOffset, isPrimary) {
        const pts = [];
        const steps = 5;
        for (let s = 0; s <= steps; s++) {
          const u = s / steps;
          // Rami emerge nearly perpendicular, then curve gracefully toward the antenna tip
          const sweep = (0.12 + 0.52 * u * u + sweepOffset) * length;
          const drop = dirSign * u * length * (1.0 - 0.12 * u * u);
          // Subtle S-curve organic wave at the filament tip
          const tipCurl = Math.pow(u, 2.4) * 18 * dirSign;

          const rx = basePt.x + vnx * drop + tan.x * (sweep + tipCurl);
          const ry = basePt.y + vny * drop + tan.y * (sweep + tipCurl);
          pts.push({ x: rx, y: ry, u });
        }
        return { pts, t, dirSign, isPrimary, length };
      }

      // Secondary row (drawn behind primary row, angled slightly more distally to cross in projection)
      if (i % 1 === 0) {
        ramiList.push(buildRamus(pt, 1, vLen2, 0.16, false));  // Ventral secondary
        ramiList.push(buildRamus(pt, -1, dLen2, 0.18, false)); // Dorsal secondary
        ramiList.push(buildRamus(pt, 1, vLen1, -0.04, true));  // Ventral primary
        ramiList.push(buildRamus(pt, -1, dLen1, -0.02, true)); // Dorsal primary
      }
    }

    // Sort rami so secondary (inner/posterior) row renders first, then primary (outer/anterior) row
    ramiList.sort((a, b) => (a.isPrimary === b.isPrimary ? a.t - b.t : a.isPrimary ? 1 : -1));

    // Pass 1: Translucent Hot Magenta Marker Halo along every ramus
    for (const r of ramiList) {
      for (let s = 0; s < r.pts.length - 1; s++) {
        const pA = r.pts[s];
        const pB = r.pts[s + 1];
        const mx = (pA.x + pB.x) * 0.5;
        const my = (pA.y + pB.y) * 0.5;
        const ch = sampleChannels(mx, my);

        const mInt = (r.isPrimary ? 0.72 : 0.48) * (1.0 - 0.35 * pA.u);
        const col = stainToHex(ch.cyan * 0.55, mInt, ch.emerald * 0.55, 0.92);
        const w = map(pA.u, 0, 1, r.isPrimary ? 0.72 : 0.48, 0.22);
        brush.set("marker", col, w);
        brush.line(pA.x, pA.y, pB.x, pB.y);
      }
    }

    // Pass 2: Crisp Fine-Tipped Pen Filaments + Microscopic Sensory Cilia (Sensilla)
    for (const r of ramiList) {
      for (let s = 0; s < r.pts.length - 1; s++) {
        const pA = r.pts[s];
        const pB = r.pts[s + 1];
        const mx = (pA.x + pB.x) * 0.5;
        const my = (pA.y + pB.y) * 0.5;
        const ch = sampleChannels(mx, my);

        // Compute crossing modulation (where primary and secondary rami cross in lattice waves)
        const latticeCross = 0.25 * Math.pow(0.5 + 0.5 * Math.sin(r.t * 140 + pA.u * 12), 3);
        const mInt = (r.isPrimary ? 0.96 : 0.72) * (1.0 - 0.22 * pA.u) + latticeCross;

        // Additive blending with underlying Cyan scales and Emerald compound eyes -> White!
        const col = stainToHex(ch.cyan * 0.92, mInt, ch.emerald * 0.92, 1.12);
        const penW = map(pA.u, 0, 1, r.isPrimary ? 0.30 : 0.20, 0.14);

        brush.set("rotring", col, penW);
        brush.line(pA.x, pA.y, pB.x, pB.y);

        // Microscopic sensory cilia hairs (sensilla trichodea) along primary and secondary rami
        if (r.length > 35 && s < r.pts.length - 1) {
          const segDx = pB.x - pA.x;
          const segDy = pB.y - pA.y;
          const segAng = atan2(segDy, segDx);
          const nCilia = r.isPrimary ? 3 : 2;

          const ciliaCol = stainToHex(ch.cyan * 0.85, mInt * 0.95, ch.emerald * 0.85, 1.05);
          brush.set("rotring", ciliaCol, 0.14);

          for (let c = 0; c < nCilia; c++) {
            const frac = (c + 0.3) / nCilia;
            const cx = lerp(pA.x, pB.x, frac);
            const cy = lerp(pA.y, pB.y, frac);
            const cLen = (r.isPrimary ? 5.5 : 4.0) * (1.0 - 0.45 * pA.u);
            const cAng1 = segAng + 38;
            const cAng2 = segAng - 38;
            brush.line(cx, cy, cx + cos(cAng1) * cLen, cy + sin(cAng1) * cLen);
            brush.line(cx, cy, cx + cos(cAng2) * cLen, cy + sin(cAng2) * cLen);
          }
        }
      }
    }

    // Pass 3: The Segmented Central Shaft (Rachis) with Flagellomere Articulation Rings
    for (let i = 0; i < N_SEG; i++) {
      const t1 = i / N_SEG;
      const t2 = (i + 1) / N_SEG;
      const p1 = cubicBez(spine.p0, spine.p1, spine.p2, spine.p3, t1);
      const p2 = cubicBez(spine.p0, spine.p1, spine.p2, spine.p3, t2);
      const tan = cubicBezTangent(spine.p0, spine.p1, spine.p2, spine.p3, t1);
      const nx = -tan.y, ny = tan.x;

      const halfW = map(Math.pow(1 - t1, 0.85), 0, 1, 0.8, 6.2);
      const ch = sampleChannels(p1.x, p1.y);

      // Marker core of the shaft segment
      const coreCol = stainToHex(ch.cyan * 0.8, 1.05, ch.emerald * 0.6, 1.05);
      brush.set("marker", coreCol, constrain(halfW * 0.35, 0.35, 1.4));
      brush.line(p1.x, p1.y, p2.x, p2.y);

      // Crisp upper and lower cortical margins of the shaft
      const edgeCol = stainToHex(ch.cyan * 0.9, 1.25, ch.emerald * 0.7, 1.25);
      brush.set("rotring", edgeCol, 0.28);
      brush.line(p1.x + nx * halfW, p1.y + ny * halfW, p2.x + nx * halfW * 0.96, p2.y + ny * halfW * 0.96);
      brush.line(p1.x - nx * halfW, p1.y - ny * halfW, p2.x - nx * halfW * 0.96, p2.y - ny * halfW * 0.96);

      // White/pink inter-segmental articulation ring & dorsal scale imbrications
      brush.set("rotring", "#FFFFFF", 0.22);
      brush.line(p1.x - nx * halfW, p1.y - ny * halfW, p1.x + nx * halfW, p1.y + ny * halfW);
      // Central specular spine highlight
      brush.line(p1.x, p1.y, p2.x, p2.y);
    }
  }

  renderFeatheredAntenna(antSpines.left);
  renderFeatheredAntenna(antSpines.right);

  // =========================================================================
  // STAGE 5: TACTILE VIBRISSAE, OVERLAP HIGHLIGHTS & LAB-PLATE RETICLE
  // =========================================================================
  // Delicate sensory bristles (chaetosemata / ocular vibrissae) curving from brow & vertex
  for (let side of [-1, 1]) {
    for (let b = 0; b < 7; b++) {
      const bx = CX + side * (42 + b * 14);
      const by = 455 - b * 4 + random(-5, 5);
      const ang = -90 + side * (18 + b * 7);
      const len = random(48, 82);
      const p1 = [bx, by, 0.9];
      const p2 = [bx + cos(ang) * len * 0.5, by + sin(ang) * len * 0.5, 0.6];
      const p3 = [bx + cos(ang + side * 14) * len, by + sin(ang + side * 14) * len, 0.2];
      brush.set("rotring", stainToHex(0.95, 0.95, 0.35, 1.25), 0.20);
      brush.spline([p1, p2, p3], 0.5);
    }
  }

  // Surgical Lab-Plate Framing & Multi-Channel Calibration Reticle
  {
    const M = 36;
    const W = 1200;
    const H = 1200;

    // Corner fiducial brackets in crisp fine-tipped pen
    brush.set("rotring", "#006680", 0.22);
    const bLen = 28;
    // Top-left
    brush.line(M, M, M + bLen, M);
    brush.line(M, M, M, M + bLen);
    // Top-right
    brush.line(W - M, M, W - M - bLen, M);
    brush.line(W - M, M, W - M, M + bLen);
    // Bottom-left
    brush.line(M, H - M, M + bLen, H - M);
    brush.line(M, H - M, M, H - M - bLen);
    // Bottom-right
    brush.line(W - M, H - M, W - M - bLen, H - M);
    brush.line(W - M, H - M, W - M, H - M - bLen);

    // Surgical center-axis alignment micro-ticks at all 4 cardinal midpoints
    brush.set("rotring", "#FFFFFF", 0.20);
    brush.line(CX, M - 6, CX, M + 10);
    brush.line(CX, H - M - 10, CX, H - M + 6);
    brush.line(M - 6, CY, M + 10, CY);
    brush.line(W - M - 10, CY, W - M + 6, CY);

    // Stained-channel calibration bars (bottom-left lab plate legend: Cyan, Magenta, Emerald, Additive White)
    const calY = H - M - 14;
    const calX = M + 44;
    const barW = 26;
    const gap = 10;

    brush.set("marker", "#00E5FF", 0.85);
    brush.line(calX, calY, calX + barW, calY);
    brush.set("rotring", "#00E5FF", 0.22);
    brush.line(calX, calY - 4, calX, calY + 4);

    brush.set("marker", "#FF007F", 0.85);
    brush.line(calX + (barW + gap), calY, calX + (barW + gap) + barW, calY);
    brush.set("rotring", "#FF007F", 0.22);
    brush.line(calX + (barW + gap), calY - 4, calX + (barW + gap), calY + 4);

    brush.set("marker", "#00FF80", 0.85);
    brush.line(calX + 2 * (barW + gap), calY, calX + 2 * (barW + gap) + barW, calY);
    brush.set("rotring", "#00FF80", 0.22);
    brush.line(calX + 2 * (barW + gap), calY - 4, calX + 2 * (barW + gap), calY + 4);

    brush.set("marker", "#FFFFFF", 0.85);
    brush.line(calX + 3 * (barW + gap), calY, calX + 3 * (barW + gap) + barW, calY);
    brush.set("rotring", "#FFFFFF", 0.22);
    brush.line(calX + 3 * (barW + gap), calY - 4, calX + 3 * (barW + gap), calY + 4);
    brush.line(calX + 3 * (barW + gap) + barW, calY - 4, calX + 3 * (barW + gap) + barW, calY + 4);

    // Micrometer scale bar on bottom-right
    const sbX1 = W - M - 144;
    const sbX2 = W - M - 44;
    brush.set("rotring", "#90E0EF", 0.24);
    brush.line(sbX1, calY, sbX2, calY);
    for (let k = 0; k <= 10; k++) {
      const tx = lerp(sbX1, sbX2, k / 10);
      const th = k % 5 === 0 ? 5 : 2.5;
      brush.line(tx, calY - th, tx, calY + th);
    }
  }

  noLoop();
}

