// =============================================================================
// GEOMETRY & RENDERING HELPERS
// =============================================================================

function washPoly(pts, col, alpha) {
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.wash(col, alpha);
  brush.beginShape(0);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noWash();
}

// Returns a point on the nacelle ring with authentic flat-bottom turbofan geometry
function cowlPt(cx, cy, rx, ry, angDeg, flattenAmt = 0.0) {
  let c = cos(angDeg);
  let s = sin(angDeg);
  let x = cx + c * rx;
  let y = cy + s * ry;
  if (flattenAmt > 0 && s > 0.15) {
    // Flatten bottom of nacelle slightly and bulge lower cheeks (classic 737/777 cowl)
    let f = pow((s - 0.15) / 0.85, 1.5);
    y -= f * ry * 0.095 * flattenAmt;
    x += c * f * rx * 0.055 * flattenAmt;
  }
  return [x, y];
}

function lerpHex(c1, c2, t) {
  t = constrain(t, 0, 1);
  let col1 = color(c1);
  let col2 = color(c2);
  return lerpColor(col1, col2, t);
}

