// =============================================================================
// 4. OUTER NACELLE COWLING BODY
// =============================================================================
function drawOuterNacelleCowl() {
  // Build the sculpted outer cowling shell between R_outer (430) and R_lip_outer (374)
  let steps = 72;
  let radialRings = 5;

  for (let rIdx = 0; rIdx < radialRings; rIdx++) {
    let u0 = rIdx / radialRings;
    let u1 = (rIdx + 1) / radialRings;

    let rx0 = lerp(432, 374, u0), ry0 = lerp(422, 370, u0);
    let rx1 = lerp(432, 374, u1), ry1 = lerp(422, 370, u1);
    let cx0 = lerp(COWL_CX, LIP_CX, u0), cy0 = lerp(COWL_CY, LIP_CY, u0);
    let cx1 = lerp(COWL_CX, LIP_CX, u1), cy1 = lerp(COWL_CY, LIP_CY, u1);
    let flat0 = lerp(1.0, 0.45, u0);
    let flat1 = lerp(1.0, 0.45, u1);

    for (let i = 0; i < steps; i++) {
      let a0 = (i / steps) * 360;
      let a1 = ((i + 1) / steps) * 360;
      let aMid = (a0 + a1) * 0.5;

      // Compute hyperreal metallic reflection on the outer nacelle skin:
      // - Top (-150..-30): bright sky reflection
      // - Horizon line (~0..12 and 168..180): sharp transition from bright sky to dark tarmac
      // - Bottom belly (20..160): dark charcoal reflecting tarmac, with soft ground bounce at 90 deg
      let s = sin(aMid); // -1 at top, +1 at bottom
      let c = cos(aMid);
      let lum;
      if (s < -0.12) {
        // Upper cowling facing sky
        lum = map(s, -1.0, -0.12, 0.94, 0.72) + c * -0.06;
      } else if (s < 0.08) {
        // Razor horizon transition on left/right cheeks
        lum = map(s, -0.12, 0.08, 0.72, 0.16);
      } else {
        // Lower cowling facing dark asphalt, with slight warm-grey ground bounce at bottom
        let bounce = exp(-pow((aMid - 90) / 38, 2)) * 0.16;
        lum = 0.14 + bounce + (1 - u0) * 0.05;
      }
      lum = constrain(lum + (u1 - 0.5) * 0.08, 0.06, 0.98);

      let col = lum > 0.5
        ? lerpHex("#7c8490", "#f3f5f9", (lum - 0.5) * 2)
        : lerpHex("#13161b", "#7c8490", lum * 2);

      let p00 = cowlPt(cx0, cy0, rx0, ry0, a0, flat0);
      let p10 = cowlPt(cx0, cy0, rx0, ry0, a1, flat0);
      let p11 = cowlPt(cx1, cy1, rx1, ry1, a1, flat1);
      let p01 = cowlPt(cx1, cy1, rx1, ry1, a0, flat1);

      washPoly([p00, p10, p11, p01], col, 225);
    }
  }

  // Graphite contour shading following the outer nacelle curvature
  for (let i = 0; i < 160; i++) {
    let a = random(0, 360);
    let span = random(14, 36);
    let u = random(0.05, 0.92);
    let rx = lerp(430, 375, u), ry = lerp(420, 371, u);
    let cx = lerp(COWL_CX, LIP_CX, u), cy = lerp(COWL_CY, LIP_CY, u);
    let flat = lerp(1.0, 0.45, u);

    let s = sin(a);
    let isDark = s > 0.0;
    brush.set(isDark ? "2B" : "2H", isDark ? "#12151a" : "#9aa2ae", isDark ? 0.55 : 0.35);

    let pts = [];
    for (let k = 0; k <= 4; k++) {
      let ak = a + (k / 4 - 0.5) * span;
      let pt = cowlPt(cx, cy, rx, ry, ak, flat);
      pts.push([pt[0], pt[1], 0.7]);
    }
    brush.spline(pts, 0.4);
  }

  // Crisp outer silhouette edge of the nacelle
  brush.set("rotring", "#1a1e24", 0.65);
  let silPts = [];
  for (let a = 0; a <= 360; a += 5) {
    let pt = cowlPt(COWL_CX, COWL_CY, 432, 422, a, 1.0);
    silPts.push([pt[0], pt[1], 0.85]);
  }
  brush.spline(silPts, 0.35);
}

// =============================================================================
// 5. POLISHED INTAKE LIP (HILITE RING) & ACOUSTIC THROAT BARREL
// =============================================================================
function drawIntakeLipAndAcousticBarrel() {
  // A) THE POLISHED METALLIC INTAKE LIP TORUS (from R=374 inward to R=322)
  // Notice the optical inversion across the torus crown (u = 0.42):
  // - Outer bevel (u = 0..0.42): Top is bright sky, bottom is dark tarmac
  // - Crown (u = 0.38..0.52): Dazzling specular highlight ring
  // - Inner bevel (u = 0.52..1.0): Top faces down into shadow (dark), bottom faces up to sky (bright!)
  let lipRings = 9;
  let steps = 72;

  for (let rIdx = 0; rIdx < lipRings; rIdx++) {
    let u0 = rIdx / lipRings;
    let u1 = (rIdx + 1) / lipRings;
    let uMid = (u0 + u1) * 0.5;

    let rx0 = lerp(374, 322, u0), ry0 = lerp(370, 320, u0);
    let rx1 = lerp(374, 322, u1), ry1 = lerp(370, 320, u1);
    let cx0 = lerp(LIP_CX, THROAT_CX, u0), cy0 = lerp(LIP_CY, THROAT_CY, u0);
    let cx1 = lerp(LIP_CX, THROAT_CX, u1), cy1 = lerp(LIP_CY, THROAT_CY, u1);
    let flat0 = lerp(0.45, 0.08, u0);
    let flat1 = lerp(0.45, 0.08, u1);

    for (let i = 0; i < steps; i++) {
      let a0 = (i / steps) * 360;
      let a1 = ((i + 1) / steps) * 360;
      let aMid = (a0 + a1) * 0.5;
      let s = sin(aMid); // -1 top, +1 bottom
      let c = cos(aMid);

      // Outer bevel reflectance
      let outerLum = s < -0.05
        ? map(s, -1, -0.05, 0.96, 0.65)
        : map(s, -0.05, 1, 0.18, 0.12);

      // Inner bowl reflectance (inverted: sky illuminates bottom inner bowl!)
      let innerLum = s > 0.05
        ? map(s, 0.05, 1.0, 0.48, 0.90)
        : map(s, -1.0, 0.05, 0.12, 0.38);

      // Torus crown highlight boost at uMid ~ 0.42
      let crownBoost = exp(-pow((uMid - 0.42) / 0.16, 2)) * (0.38 + 0.18 * abs(c));

      let lum = lerp(outerLum, innerLum, constrain(map(uMid, 0.25, 0.72, 0, 1), 0, 1)) + crownBoost;

      // Sharp dark chrome reflection band just inside the crown
      if (uMid > 0.52 && uMid < 0.68 && s < 0.1) {
        lum *= 0.48;
      }
      lum = constrain(lum, 0.06, 0.99);

      let col = lum > 0.55
        ? lerpHex("#858d99", "#ffffff", (lum - 0.55) / 0.45)
        : lerpHex("#0e1116", "#858d99", lum / 0.55);

      let p00 = cowlPt(cx0, cy0, rx0, ry0, a0, flat0);
      let p10 = cowlPt(cx0, cy0, rx0, ry0, a1, flat0);
      let p11 = cowlPt(cx1, cy1, rx1, ry1, a1, flat1);
      let p01 = cowlPt(cx1, cy1, rx1, ry1, a0, flat1);

      washPoly([p00, p10, p11, p01], col, 235);
    }
  }

  // Fine metallic graphite & technical pen strokes around the intake lip
  for (let i = 0; i < 180; i++) {
    let a = random(0, 360);
    let span = random(12, 32);
    let u = random(0.05, 0.95);
    let rx = lerp(373, 323, u), ry = lerp(369, 321, u);
    let cx = lerp(LIP_CX, THROAT_CX, u), cy = lerp(LIP_CY, THROAT_CY, u);
    let flat = lerp(0.45, 0.08, u);

    let isCrown = abs(u - 0.42) < 0.11;
    if (isCrown) {
      brush.set("tech_needle", "#ffffff", 0.65);
    } else {
      let darkZone = (u < 0.4 && sin(a) > 0) || (u > 0.55 && sin(a) < 0);
      brush.set(darkZone ? "2B" : "2H", darkZone ? "#111419" : "#7e8692", darkZone ? 0.5 : 0.32);
    }

    let pts = [];
    for (let k = 0; k <= 4; k++) {
      let ak = a + (k / 4 - 0.5) * span;
      let pt = cowlPt(cx, cy, rx, ry, ak, flat);
      pts.push([pt[0], pt[1], 0.8]);
    }
    brush.spline(pts, 0.4);
  }

  // Razor-sharp lip splice ring (where polished bare metal lip meets painted nacelle cowl)
  brush.set("rotring", "#1b1f26", 0.55);
  let lipSeamPts = [];
  for (let a = 0; a <= 360; a += 5) {
    let pt = cowlPt(LIP_CX, LIP_CY, 374, 370, a, 0.45);
    lipSeamPts.push([pt[0], pt[1], 0.85]);
  }
  brush.spline(lipSeamPts, 0.35);

  // B) THE ACOUSTIC LINER BARREL (stepping from throat R=322 back to fan shroud R=294)
  let barrelRings = 5;
  for (let rIdx = 0; rIdx < barrelRings; rIdx++) {
    let u0 = rIdx / barrelRings;
    let u1 = (rIdx + 1) / barrelRings;
    let uMid = (u0 + u1) * 0.5;

    let r0 = lerp(322, 294, u0);
    let r1 = lerp(322, 294, u1);
    let cx0 = lerp(THROAT_CX, FAN_CX, u0), cy0 = lerp(THROAT_CY, FAN_CY, u0);
    let cx1 = lerp(THROAT_CX, FAN_CX, u1), cy1 = lerp(THROAT_CY, FAN_CY, u1);

    for (let i = 0; i < steps; i++) {
      let a0 = (i / steps) * 360;
      let a1 = ((i + 1) / steps) * 360;
      let aMid = (a0 + a1) * 0.5;
      let s = sin(aMid);

      // Acoustic honeycomb liner is dark matte graphite, brighter on the lower bowl
      let lum = map(s, -1.0, 1.0, 0.08, 0.42) * (1 - uMid * 0.32);
      // Rear fan-tip rub strip (uIdx == 3) is darker anthracite
      if (rIdx === 3) lum *= 0.65;

      let col = lerpHex("#0b0d11", "#8c94a0", constrain(lum, 0, 1));
      washPoly([
        [cx0 + cos(a0) * r0, cy0 + sin(a0) * r0],
        [cx0 + cos(a1) * r0, cy0 + sin(a1) * r0],
        [cx1 + cos(a1) * r1, cy1 + sin(a1) * r1],
        [cx1 + cos(a0) * r1, cy1 + sin(a0) * r1]
      ], col, 240);
    }

    // Circumferential acoustic splice ring in crisp technical pen
    brush.set("rotring", "#090b0e", 0.55);
    let ringPts = [];
    for (let a = 0; a <= 360; a += 6) {
      ringPts.push([cx0 + cos(a) * r0, cy0 + sin(a) * r0, 0.8]);
    }
    brush.spline(ringPts, 0.35);
  }

  // Acoustic barrel axial splice seams & micro-perforation graphite texture
  brush.set("2B", "#14171d", 0.4);
  for (let i = 0; i < 90; i++) {
    let a = random(0, 360);
    let pStart = [THROAT_CX + cos(a) * 321, THROAT_CY + sin(a) * 321];
    let pEnd   = [FAN_CX + cos(a) * 294, FAN_CY + sin(a) * 294];
    brush.line(pStart[0], pStart[1], pEnd[0], pEnd[1]);
  }
}

// =============================================================================
// 6. DEEP TURBINE CAVITY & REAR STATOR VANES
// =============================================================================
function drawEngineAbyssAndStators() {
  // Jet-black abyss behind the fan stage
  let abyssPts = [];
  for (let a = 0; a < 360; a += 6) {
    abyssPts.push([FAN_CX + cos(a) * 295, FAN_CY + sin(a) * 295]);
  }
  washPoly(abyssPts, "#090b0e", 255);

  // Subtle radial Exit Guide Vanes (stators) glimpsed deep through the gaps between fan blades
  let numStators = 54;
  for (let i = 0; i < numStators; i++) {
    let a = (i / numStators) * 360;
    let x1 = HUB_CX + cos(a) * 95;
    let y1 = HUB_CY + sin(a) * 95;
    let x2 = FAN_CX + cos(a - 6) * 290;
    let y2 = FAN_CY + sin(a - 6) * 290;
    brush.set("HB", "#232830", 0.45);
    brush.line(x1, y1, x2, y2);
  }
}

// =============================================================================
// 7. THE 24 WIDE-CHORD SWEPT TITANIUM FAN BLADES
// =============================================================================
function drawTitaniumFanBlades() {
  const N_BLADES = 24;
  const R_HUB = 90;
  const R_TIP = 294;

  // Helper returning 3D-projected coordinates on blade i at radial fraction u (0..1)
  // and chord fraction v (0 = razor leading edge, 1 = trailing edge tucked under neighbor)
  function bladePoint(bladeIdx, u, v) {
    let baseAngle = (bladeIdx / N_BLADES) * 360 - 90;

    // Wide-chord forward-then-aft scimitar sweep profile along the leading edge (v=0)
    let leSweep = -12 * sin(u * 145) + 21 * pow(u, 1.85);

    // Blade angular chord width twists from hub (~15.5 deg) to tip (~14.2 deg)
    // leaving a deep shadow slot where it tucks under the adjacent blade
    let chordSpan = lerp(15.2, 13.8, u);

    let ang = baseAngle + leSweep + v * chordSpan;
    let r = lerp(R_HUB, R_TIP, u);
    let cx = lerp(HUB_CX, FAN_CX, u);
    let cy = lerp(HUB_CY, FAN_CY, u);

    return {
      x: cx + cos(ang) * r,
      y: cy + sin(ang) * r,
      ang: ang,
      r: r
    };
  }

  // Anisotropic metallic reflectance across twisted titanium blades
  function bladeLuminance(ang, u, v) {
    // Normalize angle
    let a = ((ang % 360) + 360) % 360;
    // Because the blade twists from hub to tip, specular reflection bands spiral inward!
    let twistShift = a - u * 34;

    // Two primary metallic reflection lobes (10-11 o'clock & 4-5 o'clock) + secondary horizon glints
    let lobe1 = pow( 0.5 + 0.5 * cos((twistShift - 315) * 2), 2.2 );
    let lobe2 = pow( 0.5 + 0.5 * cos((twistShift - 205) * 1), 3.0 ) * 0.45;
    let radialSheen = 0.82 + 0.18 * sin(u * 180);

    // Chordwise lighting: bright near leading edge & forward camber (v=0.05..0.38),
    // plunging into deep occlusion shadow (v=0.68..1.0) under the neighboring blade
    let chordProfile;
    if (v < 0.08) {
      chordProfile = lerp(0.95, 0.85, v / 0.08);
    } else if (v < 0.55) {
      chordProfile = lerp(0.88, 0.42, (v - 0.08) / 0.47);
    } else {
      chordProfile = lerp(0.42, 0.03, pow((v - 0.55) / 0.45, 0.85));
    }

    let lum = (0.10 + 0.82 * lobe1 + lobe2) * radialSheen * chordProfile;

    // Extra specular highlight right near the leading edge bevel
    if (v < 0.12) {
      lum += 0.28 * (1 - v / 0.12) * (0.35 + 0.65 * lobe1);
    }
    return constrain(lum, 0.02, 0.99);
  }

  // PASS 1: Tonal Underpainting of all 24 twisted titanium fan blades
  let uSteps = 7;
  let vStrips = [0.0, 0.10, 0.26, 0.46, 0.70, 0.96];

  for (let b = 0; b < N_BLADES; b++) {
    for (let ui = 0; ui < uSteps; ui++) {
      let u0 = ui / uSteps;
      let u1 = (ui + 1) / uSteps;
      let uMid = (u0 + u1) * 0.5;

      for (let vi = 0; vi < vStrips.length - 1; vi++) {
        let v0 = vStrips[vi];
        let v1 = vStrips[vi + 1];
        let vMid = (v0 + v1) * 0.5;

        let p00 = bladePoint(b, u0, v0);
        let p10 = bladePoint(b, u1, v0);
        let p11 = bladePoint(b, u1, v1);
        let p01 = bladePoint(b, u0, v1);

        let lum = bladeLuminance(p00.ang, uMid, vMid);
        let col;
        if (lum > 0.62) {
          col = lerpHex("#8e96a3", "#f5f7fb", (lum - 0.62) / 0.38);
        } else if (lum > 0.25) {
          col = lerpHex("#272c34", "#8e96a3", (lum - 0.25) / 0.37);
        } else {
          col = lerpHex("#090b0f", "#272c34", lum / 0.25);
        }

        washPoly([
          [p00.x, p00.y],
          [p10.x, p10.y],
          [p11.x, p11.y],
          [p01.x, p01.y]
        ], col, 240);
      }
    }
  }

  // PASS 2: Dense Graphite Shading & Metallic Grain Along Every Blade Surface
  for (let b = 0; b < N_BLADES; b++) {
    // A) Radial spiral graphite strokes from hub to tip across the blade chord
    let radialLines = 11;
    for (let li = 1; li < radialLines; li++) {
      let v = map(li, 0, radialLines, 0.04, 0.92);
      let pts = [];
      for (let ui = 0; ui <= 6; ui++) {
        let u = ui / 6;
        let p = bladePoint(b, u, v);
        pts.push([p.x, p.y, lerp(0.5, 1.0, sin(u * 180))]);
      }

      let midP = bladePoint(b, 0.5, v);
      let lum = bladeLuminance(midP.ang, 0.5, v);

      if (v > 0.62) {
        // Deep overlap trough under adjacent blade: rich dark 2B/charcoal tone
        brush.set("2B", "#0a0c10", 0.62);
      } else if (lum > 0.65) {
        // Bright titanium reflection band: crisp 2H silver-white sheen
        brush.set("2H", "#eef2f7", 0.38);
      } else {
        // Mid-tone brushed titanium graphite grain
        brush.set("HB", lerpHex("#1c2027", "#7d8591", lum), 0.42);
      }
      brush.spline(pts, 0.45);
    }

    // B) Chordwise cross-contour graphite hatching following the 3D airfoil camber
    for (let ui = 1; ui <= 14; ui++) {
      let u = ui / 15;
      let pStart = bladePoint(b, u, 0.03);
      let pMid   = bladePoint(b, min(1, u + 0.025), 0.48);
      let pEnd   = bladePoint(b, min(1, u + 0.045), 0.95);
      let lum = bladeLuminance(pMid.ang, u, 0.35);

      brush.set("2H", lum > 0.55 ? "#cfd5df" : "#1f242c", 0.32);
      brush.spline([
        [pStart.x, pStart.y, 0.4],
        [pMid.x, pMid.y, 0.85],
        [pEnd.x, pEnd.y, 0.5]
      ], 0.35);
    }

    // C) Mid-span aerodynamic snubber / titanium grain inflection at u = 0.64
    let snub0 = bladePoint(b, 0.64, 0.02);
    let snub1 = bladePoint(b, 0.66, 0.65);
    brush.set("rotring", "#171b22", 0.32);
    brush.line(snub0.x, snub0.y, snub1.x, snub1.y);
  }

  // PASS 3: Razor-Sharp Pen Linework on Every Titanium Leading Edge, Root Fillet & Tip
  for (let b = 0; b < N_BLADES; b++) {
    let lePts = [];
    let hiPts = [];
    let shadowEdgePts = [];

    for (let ui = 0; ui <= 10; ui++) {
      let u = ui / 10;
      let pLE = bladePoint(b, u, 0.0);
      let pHi = bladePoint(b, u, 0.032);
      let pSh = bladePoint(b, u, 0.96);

      // Pressure tapers slightly at root and tip for surgical drafting precision
      let pr = 0.65 + 0.45 * sin(u * 180);
      lePts.push([pLE.x, pLE.y, pr]);
      hiPts.push([pHi.x, pHi.y, pr]);
      shadowEdgePts.push([pSh.x, pSh.y, pr * 0.85]);
    }

    // 1. Deep interstitial shadow line where previous blade tucks underneath
    brush.set("rotring", "#060709", 0.72);
    brush.spline(shadowEdgePts, 0.45);

    // 2. Razor-sharp Titanium Sheath Leading Edge (dark surgical rotring cut)
    brush.set("rotring", "#0b0d12", 0.58);
    brush.spline(lePts, 0.45);

    // 3. Blazing metallic specular edge right along the titanium leading edge bevel
    let midLE = bladePoint(b, 0.55, 0.0);
    let leLum = bladeLuminance(midLE.ang, 0.55, 0.02);

    // Blades near the horizontal flare axis (y ~ 524) also catch electric cyan/violet glints!
    let distToFlare = abs(midLE.y - FLARE_Y);
    let edgeCol = "#e4e9f2";
    if (distToFlare < 68) {
      edgeCol = midLE.x < FAN_CX ? "#9bf6ff" : "#DFC8FF";
    } else if (leLum > 0.6) {
      edgeCol = "#ffffff";
    } else {
      edgeCol = "#9ca4b0";
    }

    brush.set("tech_needle", edgeCol, leLum > 0.55 ? 0.85 : 0.52);
    brush.spline(hiPts, 0.45);

    // 4. Crisp blade tip arc at the outer containment shroud (R_TIP)
    let tip0 = bladePoint(b, 1.0, 0.0);
    let tip1 = bladePoint(b, 1.0, 0.88);
    brush.set("rotring", "#080a0d", 0.55);
    brush.line(tip0.x, tip0.y, tip1.x, tip1.y);

    // 5. Machined blade root platform fillet at the spinner hub collar (R_HUB)
    let root0 = bladePoint(b, 0.0, 0.0);
    let root1 = bladePoint(b, 0.0, 0.92);
    brush.set("rotring", "#12151b", 0.5);
    brush.line(root0.x, root0.y, root1.x, root1.y);
  }
}

// =============================================================================
// 8. CENTER SPINNER CONE (NOSE CONE, WHITE SWIRL & CHROME APEX)
// =============================================================================
function drawSpinnerCone() {
  const R_BASE = 91;

  // Dark recessed hub seam ring at the base of the spinner cone
  brush.set("rotring", "#07090c", 0.85);
  let baseRing = [];
  for (let a = 0; a <= 360; a += 8) {
    baseRing.push([HUB_CX + cos(a) * R_BASE, HUB_CY + sin(a) * R_BASE, 0.85]);
  }
  brush.spline(baseRing, 0.35);

  // Build the 3D paraboloid cone from base (s=1 at HUB_CX, HUB_CY) to apex (s=0 at TIP_CX, TIP_CY)
  let coneRings = 18;
  let steps = 48;

  for (let ri = coneRings - 1; ri >= 0; ri--) {
    let s0 = ri / coneRings;
    let s1 = (ri + 1) / coneRings;
    let sMid = (s0 + s1) * 0.5;

    // Slight aerodynamic ogive curvature on the spinner profile
    let r0 = R_BASE * pow(s0, 0.88);
    let r1 = R_BASE * pow(s1, 0.88);
    let cx0 = lerp(TIP_CX, HUB_CX, s0), cy0 = lerp(TIP_CY, HUB_CY, s0);
    let cx1 = lerp(TIP_CX, HUB_CX, s1), cy1 = lerp(TIP_CY, HUB_CY, s1);

    for (let i = 0; i < steps; i++) {
      let a0 = (i / steps) * 360;
      let a1 = ((i + 1) / steps) * 360;
      let aMid = (a0 + a1) * 0.5;

      // 3D Conical lighting: bright upper-left (-115 deg), deep core shadow lower-right (+55 deg),
      // soft tarmac bounce at +115 deg
      let lightDot = cos(aMid - (-115));
      let baseLum = map(lightDot, -1, 1, 0.08, 0.62);
      let bounce = exp(-pow((aMid - 115) / 40, 2)) * 0.14;
      let lum = baseLum + bounce;

      // Polished bare titanium/chrome nose cap for sMid < 0.24
      let isChromeTip = sMid < 0.24;
      if (isChromeTip) {
        lum = lightDot > 0.2
          ? map(lightDot, 0.2, 1.0, 0.65, 0.99)
          : map(lightDot, -1.0, 0.2, 0.12, 0.45);
      }

      let col = lum > 0.5
        ? lerpHex("#6e7682", "#f6f8fc", (lum - 0.5) * 2)
        : lerpHex("#0b0d12", "#6e7682", lum * 2);

      washPoly([
        [cx0 + cos(a0) * r0, cy0 + sin(a0) * r0],
        [cx0 + cos(a1) * r0, cy0 + sin(a1) * r0],
        [cx1 + cos(a1) * r1, cy1 + sin(a1) * r1],
        [cx1 + cos(a0) * r1, cy1 + sin(a0) * r1]
      ], col, 245);
    }
  }

  // Painted White Archimedean Safety Spiral ("Swirl") wrapping 1.65 turns around the 3D cone
  let spiralSteps = 75;
  for (let i = 0; i < spiralSteps; i++) {
    let t0 = i / spiralSteps;
    let t1 = (i + 1) / spiralSteps;
    let s0 = lerp(0.24, 0.90, t0);
    let s1 = lerp(0.24, 0.90, t1);

    let ang0 = -55 + t0 * 560;
    let ang1 = -55 + t1 * 560;
    let halfW0 = lerp(28, 19, t0);
    let halfW1 = lerp(28, 19, t1);

    let r0 = R_BASE * pow(s0, 0.88);
    let r1 = R_BASE * pow(s1, 0.88);
    let cx0 = lerp(TIP_CX, HUB_CX, s0), cy0 = lerp(TIP_CY, HUB_CY, s0);
    let cx1 = lerp(TIP_CX, HUB_CX, s1), cy1 = lerp(TIP_CY, HUB_CY, s1);

    // Shade the white spiral band according to the 3D cone illumination
    let lightDot = cos(ang0 - (-115));
    let swirlLum = map(lightDot, -1, 1, 0.36, 0.97);
    let swirlCol = lerpHex("#3e444e", "#f7f9fc", swirlLum);

    let p00 = [cx0 + cos(ang0 - halfW0) * r0, cy0 + sin(ang0 - halfW0) * r0];
    let p10 = [cx0 + cos(ang0 + halfW0) * r0, cy0 + sin(ang0 + halfW0) * r0];
    let p11 = [cx1 + cos(ang1 + halfW1) * r1, cy1 + sin(ang1 + halfW1) * r1];
    let p01 = [cx1 + cos(ang1 - halfW1) * r1, cy1 + sin(ang1 - halfW1) * r1];

    washPoly([p00, p10, p11, p01], swirlCol, 240);
  }

  // Crisp technical pen outlines along the painted spiral edges & chrome tip seam
  let swirlOuter = [], swirlInner = [];
  for (let i = 0; i <= 50; i++) {
    let t = i / 50;
    let s = lerp(0.24, 0.90, t);
    let ang = -55 + t * 560;
    let halfW = lerp(28, 19, t);
    let r = R_BASE * pow(s, 0.88);
    let cx = lerp(TIP_CX, HUB_CX, s), cy = lerp(TIP_CY, HUB_CY, s);
    swirlOuter.push([cx + cos(ang + halfW) * r, cy + sin(ang + halfW) * r, 0.75]);
    swirlInner.push([cx + cos(ang - halfW) * r, cy + sin(ang - halfW) * r, 0.75]);
  }
  brush.set("rotring", "#151920", 0.45);
  brush.spline(swirlOuter, 0.4);
  brush.spline(swirlInner, 0.4);

  // Chrome nose cap seam ring at s = 0.24
  let capRing = [];
  let rCap = R_BASE * pow(0.24, 0.88);
  let cxCap = lerp(TIP_CX, HUB_CX, 0.24), cyCap = lerp(TIP_CY, HUB_CY, 0.24);
  for (let a = 0; a <= 360; a += 12) {
    capRing.push([cxCap + cos(a) * rCap, cyCap + sin(a) * rCap, 0.8]);
  }
  brush.set("rotring", "#0e1116", 0.5);
  brush.spline(capRing, 0.35);

  // Fine radial graphite shading lines on the spinner cone
  for (let a = 0; a < 360; a += 8) {
    let lightDot = cos(a - (-115));
    if (abs(lightDot) < 0.25) continue;
    brush.set(lightDot < 0 ? "2B" : "2H", lightDot < 0 ? "#0d1015" : "#cfd6e0", 0.35);
    let x1 = lerp(TIP_CX, HUB_CX, 0.12) + cos(a) * (R_BASE * 0.14);
    let y1 = lerp(TIP_CY, HUB_CY, 0.12) + sin(a) * (R_BASE * 0.14);
    let x2 = HUB_CX + cos(a) * R_BASE;
    let y2 = HUB_CY + sin(a) * R_BASE;
    brush.line(x1, y1, x2, y2);
  }
}

// =============================================================================
// 9. EXTERIOR COWLING SEAMS, RIVETS, STRAKE & TECHNICAL STENCILS
// =============================================================================
function drawHyperrealSurfaceDetails() {
  // 1. Radial lip splice seams at 12, 3, 6, 9, and 4/8 o'clock positions
  let seamAngles = [-90, -35, 12, 85, 95, 168, 215];
  brush.set("rotring", "#1e222a", 0.42);
  for (let a of seamAngles) {
    let pOut = cowlPt(COWL_CX, COWL_CY, 432, 422, a, 1.0);
    let pLip = cowlPt(LIP_CX, LIP_CY, 374, 370, a, 0.45);
    let pThr = cowlPt(THROAT_CX, THROAT_CY, 325, 323, a, 0.08);
    brush.line(pOut[0], pOut[1], pLip[0], pLip[1]);
    brush.line(pLip[0], pLip[1], pThr[0], pThr[1]);
  }

  // 2. Flush rivet rows along the intake lip splice ring (R ~ 377)
  brush.set("rotring", "#2b303a", 0.35);
  for (let a = 0; a < 360; a += 2.5) {
    let p1 = cowlPt(LIP_CX, LIP_CY, 377, 373, a, 0.48);
    let p2 = cowlPt(LIP_CX, LIP_CY, 379, 375, a, 0.48);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // 3. Nacelle Vortex Generator Strake (Chine) on upper-right outer cowl (-28 deg)
  let strakeBaseA1 = -34, strakeBaseA2 = -19;
  let sb1 = cowlPt(COWL_CX, COWL_CY, 412, 404, strakeBaseA1, 0.85);
  let sb2 = cowlPt(COWL_CX, COWL_CY, 428, 418, strakeBaseA2, 0.95);
  let st1 = [sb1[0] + 42, sb1[1] - 18];
  let st2 = [sb2[0] + 54, sb2[1] - 12];

  // Cast shadow of the strake onto the silver cowling below it
  washPoly([
    sb1, sb2, [sb2[0] + 18, sb2[1] + 34], [sb1[0] + 10, sb1[1] + 22]
  ], "#232830", 160);
  // Strake upper lit blade & dark underside
  washPoly([sb1, st1, st2, sb2], "#e2e7ef", 230);
  brush.set("rotring", "#161920", 0.5);
  brush.line(sb1[0], sb1[1], st1[0], st1[1]);
  brush.line(st1[0], st1[1], st2[0], st2[1]);
  brush.line(sb1[0], sb1[1], sb2[0], sb2[1]);

  // 4. Lower Cowl Drain Mast at 6 o'clock (protruding into the hot tarmac shimmer)
  washPoly([[618, 886], [631, 886], [626, 926], [619, 926]], "#1a1d24", 230);
  brush.set("rotring", "#0c0e12", 0.45);
  brush.line(618, 886, 619, 926);
  brush.line(631, 886, 626, 926);

  // 5. Technical aviation stencil markings on left cheek of cowling (monochrome)
  // Intake danger triangle & horizontal station datum line
  let stX = 212, stY = 486;
  brush.set("rotring", "#3a404a", 0.38);
  brush.line(stX, stY - 12, stX + 16, stY + 10);
  brush.line(stX + 16, stY + 10, stX - 6, stY + 10);
  brush.line(stX - 6, stY + 10, stX, stY - 12);
  // Datum line & micro stencil ticks
  brush.line(196, 548, 238, 548);
  for (let tx = 200; tx <= 234; tx += 5) {
    brush.line(tx, 544, tx - 2, 546);
  }
}

// =============================================================================
// 10. SINGLE EDGE-TO-EDGE HORIZONTAL ANAMORPHIC FLARE (ELECTRIC CYAN & VIOLET)
// =============================================================================
function drawAnamorphicFlare() {
  // The single horizontal lens flare slices the entire frame edge-to-edge (x = 0..1200)
  // at y = FLARE_Y (524), triggered by the blazing glint on the spinner tip (606, 524)
  // and left/right intake lip highlights (272, 524) & (968, 524).

  // STEP 1: Soft Wide Atmospheric Pale Violet & Electric Cyan Airbrushed Veil
  // Outer pale violet envelope
  for (let i = 0; i < 28; i++) {
    let dy = random(-46, 46);
    let x1 = random(-20, 280);
    let x2 = random(920, 1220);
    let col = random(["#b892ff", "#cdb2ff", "#9b6eff", "#d9c4ff"]);
    let wt = map(abs(dy), 0, 46, 1.4, 0.45);
    brush.set("airbrush_soft", col, wt);
    brush.line(x1, FLARE_Y + dy, x2, FLARE_Y + dy + random(-2, 2));
  }

  // Fine airbrushed spray particles in pale violet & electric cyan along the entire horizontal band
  for (let i = 0; i < 45; i++) {
    let isCyan = random() < 0.58;
    let dy = isCyan ? random(-22, 22) : random(-44, 44);
    let col = isCyan
      ? random(["#00f0ff", "#00b8ff", "#5cf7ff", "#00d4ff"])
      : random(["#c19cff", "#a375ff", "#dfd0ff"]);
    brush.set("spray", col, isCyan ? random(0.55, 1.15) : random(0.45, 0.95));
    let xStart = random(0, 350);
    let xEnd   = random(850, 1200);
    brush.line(xStart, FLARE_Y + dy, xEnd, FLARE_Y + dy);
  }

  // Inner electric cyan airbrushed glow from edge to edge
  for (let i = 0; i < 34; i++) {
    let dy = random(-18, 18);
    let col = random(["#00f2ff", "#00c8ff", "#66f9ff", "#00e1ff"]);
    let wt = map(abs(dy), 0, 18, 1.35, 0.4);
    brush.set("airbrush_soft", col, wt);
    brush.line(0, FLARE_Y + dy, 1200, FLARE_Y + dy);
  }

  // STEP 2: Anamorphic Oval Ghost Reflections Strung Along the Horizontal Flare
  // Real anamorphic lens ghosts are vertical/horizontal ovals with glowing cyan & violet rims
  let ghosts = [
    { x: 64,   rx: 26, ry: 52, col: "#b892ff", rim: "#e2ccff", alpha: 24 },
    { x: 138,  rx: 18, ry: 38, col: "#00ecff", rim: "#96fbff", alpha: 30 },
    { x: 192,  rx: 38, ry: 72, col: "#9e70ff", rim: "#d4b8ff", alpha: 20 },
    { x: 272,  rx: 28, ry: 54, col: "#00f5ff", rim: "#ffffff", alpha: 38 }, // Left lip crown
    { x: 358,  rx: 22, ry: 44, col: "#c49eff", rim: "#e8d6ff", alpha: 26 },
    { x: 425,  rx: 46, ry: 84, col: "#00d8ff", rim: "#7cf8ff", alpha: 18 },
    { x: 492,  rx: 15, ry: 32, col: "#00f6ff", rim: "#d8ffff", alpha: 34 },
    { x: 548,  rx: 30, ry: 56, col: "#b488ff", rim: "#e0c8ff", alpha: 24 },
    { x: 606,  rx: 36, ry: 68, col: "#00f5ff", rim: "#ffffff", alpha: 42 }, // Spinner apex core
    { x: 678,  rx: 20, ry: 42, col: "#c8a6ff", rim: "#efe0ff", alpha: 28 },
    { x: 742,  rx: 48, ry: 88, col: "#00cfff", rim: "#88f8ff", alpha: 18 },
    { x: 816,  rx: 16, ry: 35, col: "#00f5ff", rim: "#ccffff", alpha: 34 },
    { x: 888,  rx: 32, ry: 62, col: "#ad80ff", rim: "#dec4ff", alpha: 22 },
    { x: 968,  rx: 26, ry: 52, col: "#00f2ff", rim: "#ffffff", alpha: 38 }, // Right lip crown
    { x: 1048, rx: 38, ry: 70, col: "#be98ff", rim: "#e5d2ff", alpha: 22 },
    { x: 1132, rx: 22, ry: 45, col: "#00e8ff", rim: "#a2fbff", alpha: 28 }
  ];

  for (let g of ghosts) {
    // Translucent interior bokeh wash
    let ovalPts = [];
    for (let a = 0; a < 360; a += 10) {
      ovalPts.push([g.x + cos(a) * g.rx, FLARE_Y + sin(a) * g.ry]);
    }
    washPoly(ovalPts, g.col, g.alpha);

    // Inner bright core wash for smaller high-intensity ghosts
    if (g.rx < 30) {
      let innerPts = [];
      for (let a = 0; a < 360; a += 15) {
        innerPts.push([g.x + cos(a) * (g.rx * 0.55), FLARE_Y + sin(a) * (g.ry * 0.55)]);
      }
      washPoly(innerPts, g.rim, g.alpha * 0.85);
    }

    // Soft airbrushed spray perimeter around the oval ghost
    brush.set("spray", g.col, 0.38);
    let rimPts = [];
    for (let a = 0; a <= 360; a += 15) {
      rimPts.push([g.x + cos(a) * g.rx, FLARE_Y + sin(a) * g.ry, 0.7]);
    }
    brush.spline(rimPts, 0.45);

    // Characteristic bright left & right crescent arcs on each anamorphic oval ghost
    brush.set("airbrush_core", g.rim, 0.32);
    let leftArc = [], rightArc = [];
    for (let a = -55; a <= 55; a += 18) {
      rightArc.push([g.x + cos(a) * g.rx, FLARE_Y + sin(a) * g.ry, 0.8 * cos(a)]);
      leftArc.push([g.x + cos(a + 180) * g.rx, FLARE_Y + sin(a + 180) * g.ry, 0.8 * cos(a)]);
    }
    brush.spline(rightArc, 0.45);
    brush.spline(leftArc, 0.45);
  }

  // STEP 3: Intense Specular Nodes (Spinner Apex & Left/Right Intake Lip Crowns)
  let hotspots = [
    { x: 272, w: 170, intensity: 0.85 },
    { x: 606, w: 280, intensity: 1.25 },
    { x: 968, w: 170, intensity: 0.85 }
  ];
  for (let hs of hotspots) {
    for (let k = 0; k < 10; k++) {
      let span = hs.w * random(0.35, 1.15);
      let dy = random(-6, 6);
      brush.set("airbrush_core", k % 3 === 0 ? "#d9bfff" : "#00f5ff", 0.65 * hs.intensity);
      brush.line(hs.x - span, FLARE_Y + dy, hs.x + span, FLARE_Y + dy);
    }
  }

  // STEP 4: Razor-Straight Edge-to-Edge Anamorphic Core Beam (x = 0 to 1200)
  // Upper and lower pale violet chromatic aberration fringes
  brush.set("airbrush_core", "#c59eff", 0.55);
  brush.line(0, FLARE_Y - 5.5, 1200, FLARE_Y - 5.5);
  brush.line(0, FLARE_Y + 5.5, 1200, FLARE_Y + 5.5);

  // Electric cyan laser core beam slicing edge to edge
  for (let pass = 0; pass < 6; pass++) {
    let dy = map(pass, 0, 5, -2.5, 2.5);
    brush.set("airbrush_core", "#00f6ff", 0.85);
    brush.line(0, FLARE_Y + dy, 1200, FLARE_Y + dy);
  }

  // Crisp incandescent ice-cyan & pure white center needle from x = 0 to 1200
  brush.set("tech_needle", "#80fbff", 1.6);
  brush.line(0, FLARE_Y - 1.0, 1200, FLARE_Y - 1.0);
  brush.line(0, FLARE_Y + 1.0, 1200, FLARE_Y + 1.0);

  brush.set("tech_needle", "#ffffff", 1.85);
  brush.line(0, FLARE_Y, 1200, FLARE_Y);

  // Blazing white diamond star glint right at the spinner tip (606, 524) and lip crowns
  for (let hs of hotspots) {
    let halfLen = hs.w * 0.48;
    brush.set("tech_needle", "#ffffff", 2.2 * hs.intensity);
    brush.line(hs.x - halfLen, FLARE_Y, hs.x + halfLen, FLARE_Y);
    // Subtle vertical anamorphic cross-spike at the primary spinner glint
    if (hs.intensity > 1.0) {
      brush.set("airbrush_core", "#00f5ff", 0.45);
      brush.line(hs.x, FLARE_Y - 38, hs.x, FLARE_Y + 38);
      brush.set("tech_needle", "#ffffff", 1.1);
      brush.line(hs.x, FLARE_Y - 22, hs.x, FLARE_Y + 22);
    }
  }
}

// =============================================================================
// 11. LETTERBOX BANDS & ARCHIVAL WIDESCREEN GATE EDGE
// =============================================================================
function drawLetterboxFinish() {
  // Ensure the heavy top and bottom bands remain 100% pure unpainted archival paper
  washPoly([[0, 0], [1200, 0], [1200, TOP_BAR], [0, TOP_BAR]], "#f2f1ed", 255);
  washPoly([[0, BOT_BAR], [1200, BOT_BAR], [1200, 1200], [0, 1200]], "#f2f1ed", 255);

  // Crisp graphite drafting rule along the top and bottom letterbox gate boundaries
  brush.set("2H", "#6e747e", 0.42);
  brush.line(0, TOP_BAR, 1200, TOP_BAR);
  brush.line(0, BOT_BAR, 1200, BOT_BAR);

  brush.set("rotring", "#20242b", 0.35);
  brush.line(0, TOP_BAR + 0.6, 1200, TOP_BAR + 0.6);
  brush.line(0, BOT_BAR - 0.6, 1200, BOT_BAR - 0.6);
}
